// 🔥🔥🔥 统一定义POS活跃订单状态常量
// 所有订单查询应使用此常量，确保状态一致性
// 包含: pending(待付款), on-hold(待处理), processing(处理中)
define('RUIYI_POS_ACTIVE_ORDER_STATUSES', ['pending', 'on-hold', 'processing']);
define('RUIYI_POS_ACTIVE_ORDER_STATUSES_WC', ['wc-pending', 'wc-on-hold', 'wc-processing']);

/**
 * 获取缓存的 Verifactu 插件实例（同一请求内只创建一次）
 */
function ruiyi_get_verifactu_instance() {
    static $instance = null;
    if ($instance === null && class_exists('WC_Verifactu_QR')) {
        $instance = WC_Verifactu_QR::instance();
    }
    return $instance;
}

/**
 * 获取缓存的 Verifactu 反射方法（避免每次创建 Reflection）
 * @param string $method_name 'generate_and_store_qr' 或 'generate_pdf_with_qr'
 * @return ReflectionMethod|null
 */
function ruiyi_get_verifactu_method($method_name) {
    static $cache = [];
    $instance = ruiyi_get_verifactu_instance();
    if (!$instance) return null;

    if (!isset($cache[$method_name])) {
        try {
            $reflection = new ReflectionMethod($instance, $method_name);
            $reflection->setAccessible(true);
            $cache[$method_name] = $reflection;
        } catch (Exception $e) {
            $cache[$method_name] = false;
        }
    }

    return $cache[$method_name] ?: null;
}

/**
 * 检查 Verifactu 插件是否可用（缓存结果）
 */
function ruiyi_has_verifactu() {
    static $result = null;
    if ($result === null) {
        $result = class_exists('WC_Verifactu_QR') || has_action('verifactu_delayed_processing');
    }
    return $result;
}

/**
 * 统一小票上显示的发票号码格式：年份 + 7位订单序号，例如 20260000381。
 * 只格式化显示内容，不修改 Verifactu 插件生成的订单 meta 或其他主题数据。
 *
 * @param string $raw_invoice_number Verifactu label 或旧格式发票号。
 * @param WC_Order|int|null $order 订单对象或订单ID，用于兜底获取年份/订单ID。
 * @return string
 */
function ruiyi_format_receipt_invoice_number($raw_invoice_number = '', $order = null) {
    $wc_order = null;
    if ($order instanceof WC_Order) {
        $wc_order = $order;
    } elseif (is_numeric($order) && (int) $order > 0 && function_exists('wc_get_order')) {
        $wc_order = wc_get_order((int) $order);
    }

    $order_id = $wc_order ? (int) $wc_order->get_id() : (is_numeric($order) ? (int) $order : 0);
    // 年份必须取当前站点年份，不固定为 2026。
    $year = current_time('Y');

    $raw = trim(wp_strip_all_tags(html_entity_decode((string) $raw_invoice_number, ENT_QUOTES, 'UTF-8')));
    $sequence = '';

    if ($raw !== '' && preg_match('/(20\d{2}).*?(\d{1,12})(?!.*\d)/', $raw, $matches)) {
        $year = $matches[1];
        $sequence = $matches[2];
    } elseif ($raw !== '' && preg_match_all('/\d+/', $raw, $matches) && !empty($matches[0])) {
        $sequence = end($matches[0]);
    }

    if ($sequence === '' && $order_id > 0) {
        $sequence = (string) $order_id;
    }

    $sequence = preg_replace('/\D+/', '', (string) $sequence);
    $sequence = ltrim($sequence, '0');
    if ($sequence === '') {
        return $raw;
    }

    return $year . str_pad($sequence, 7, '0', STR_PAD_LEFT);
}

function ruiyi_is_valid_verifactu_receipt_label($label) {
    $label = trim((string) $label);
    return $label !== '' && strcasecmp($label, 'Pending') !== 0 && strcasecmp($label, 'Error') !== 0;
}

function ruiyi_wait_for_verifactu_invoice_label($order, $max_attempts = 6, $sleep_microseconds = 250000) {
    if (!$order instanceof WC_Order) {
        return '';
    }

    $order_id = $order->get_id();
    for ($attempt = 1; $attempt <= $max_attempts; $attempt++) {
        $fresh_order = wc_get_order($order_id);
        if (!$fresh_order) {
            return '';
        }

        $label = (string) $fresh_order->get_meta('_verifactu_invoice_label');
        if (ruiyi_is_valid_verifactu_receipt_label($label)) {
            return $label;
        }

        try {
            $label_method = ruiyi_get_verifactu_method('get_invoice_label');
            if ($label_method) {
                $generated_label = (string) $label_method->invoke(ruiyi_get_verifactu_instance(), $fresh_order);
                if (ruiyi_is_valid_verifactu_receipt_label($generated_label)) {
                    return $generated_label;
                }
            }
        } catch (Throwable $e) {
            ruiyi_debug_log('[小票发票号] Verifactu label 生成失败: ' . $e->getMessage());
        }

        try {
            do_action('verifactu_delayed_processing', $order_id);
        } catch (Throwable $e) {
            ruiyi_debug_log('[小票发票号] Verifactu delayed processing 触发失败: ' . $e->getMessage());
        }

        clean_post_cache($order_id);
        wp_cache_delete($order_id, 'post_meta');
        $fresh_order = wc_get_order($order_id);
        $label = $fresh_order ? (string) $fresh_order->get_meta('_verifactu_invoice_label') : '';
        if (ruiyi_is_valid_verifactu_receipt_label($label)) {
            return $label;
        }

        if ($attempt < $max_attempts) {
            usleep($sleep_microseconds);
        }
    }

    ruiyi_debug_log('[小票发票号] Verifactu 已启用，但等待后仍未获取到有效发票号，订单 #' . $order_id);
    return '';
}

/**
 * 获取订单在小票上应显示的统一发票号码。
 *
 * @param WC_Order|int|null $order 订单对象或订单ID。
 * @param bool $wait_for_verifactu Verifactu 启用时是否等待/触发正式号码生成。
 * @return string
 */
function ruiyi_get_receipt_invoice_number($order, $wait_for_verifactu = true) {
    $wc_order = $order instanceof WC_Order ? $order : (is_numeric($order) && function_exists('wc_get_order') ? wc_get_order((int) $order) : null);
    $raw_invoice_number = '';
    if ($wc_order) {
        if (ruiyi_has_verifactu() && $wait_for_verifactu) {
            $raw_invoice_number = ruiyi_wait_for_verifactu_invoice_label($wc_order);
            if ($raw_invoice_number === '') {
                return '';
            }
        } else {
            $raw_invoice_number = $wc_order->get_meta('_verifactu_invoice_label');
        }
    }
    return ruiyi_format_receipt_invoice_number($raw_invoice_number, $wc_order ?: $order);
}

/**
 * 获取结账小票/预结单使用的统一含税税种设置。
 * 这里只影响小票显示和含税反算，不修改 WooCommerce 税率、分类税率或 Verifactu 插件数据。
 */
function ruiyi_get_receipt_tax_config() {
    $type = get_option('pos_receipt_tax_type', 'iva_10');
    if (!in_array($type, array('iva_10', 'igic_7'), true)) {
        $type = 'iva_10';
    }

    if ($type === 'igic_7') {
        return array(
            'type' => 'igic_7',
            'label' => 'IGIC',
            'rate' => 7.0,
        );
    }

    return array(
        'type' => 'iva_10',
        'label' => 'IVA incluido',
        'rate' => 10.0,
    );
}

function ruiyi_get_receipt_tax_display_label($tax_config = null) {
    $tax_config = is_array($tax_config) ? $tax_config : ruiyi_get_receipt_tax_config();
    $rate = isset($tax_config['rate']) ? (float) $tax_config['rate'] : 10.0;
    $rate_label = rtrim(rtrim(number_format($rate, 2, '.', ''), '0'), '.');
    if (($tax_config['type'] ?? '') === 'igic_7') {
        return $tax_config['label'] . ' ' . $rate_label . '%';
    }
    return $tax_config['label'] . ' (' . $rate_label . '%)';
}

function ruiyi_calculate_receipt_included_tax($gross_total, $tax_config = null) {
    $tax_config = is_array($tax_config) ? $tax_config : ruiyi_get_receipt_tax_config();
    $gross_total = max(0, (float) $gross_total);
    $rate = isset($tax_config['rate']) ? max(0, (float) $tax_config['rate']) : 10.0;
    $divisor = 1 + ($rate / 100);
    $base = $divisor > 0 ? ($gross_total / $divisor) : $gross_total;
    return array(
        'base' => $base,
        'tax' => $gross_total - $base,
        'total' => $gross_total,
        'rate' => $rate,
        'label' => ruiyi_get_receipt_tax_display_label($tax_config),
    );
}

function ruiyi_get_receipt_logo_dimensions($logo_url = '') {
    $logo_url = $logo_url ?: get_option('pos_receipt_logo', '');
    $saved_width = (int) get_option('pos_receipt_logo_width', 0);
    $saved_height = (int) get_option('pos_receipt_logo_height', 0);
    $saved_url = get_option('pos_receipt_logo_dimension_url', '');
    if ($saved_width > 0 && $saved_height > 0 && $saved_url === $logo_url) {
        return array('width' => $saved_width, 'height' => $saved_height);
    }

    if (empty($logo_url)) {
        return array('width' => 0, 'height' => 0);
    }

    $upload_dir = wp_upload_dir();
    $base_url = trailingslashit($upload_dir['baseurl']);
    $base_dir = trailingslashit($upload_dir['basedir']);
    $path = '';
    if (strpos($logo_url, $base_url) === 0) {
        $relative = ltrim(substr($logo_url, strlen($base_url)), '/');
        $path = $base_dir . $relative;
    } else {
        $parsed_logo = wp_parse_url($logo_url);
        $parsed_base = wp_parse_url($base_url);
        if (!empty($parsed_logo['path']) && !empty($parsed_base['path']) && strpos($parsed_logo['path'], $parsed_base['path']) === 0) {
            $relative = ltrim(substr($parsed_logo['path'], strlen($parsed_base['path'])), '/');
            $path = $base_dir . $relative;
        }
    }

    if ($path && file_exists($path)) {
        $size = @getimagesize($path);
        if (is_array($size) && !empty($size[0]) && !empty($size[1])) {
                update_option('pos_receipt_logo_width', (int) $size[0]);
                update_option('pos_receipt_logo_height', (int) $size[1]);
                update_option('pos_receipt_logo_dimension_url', $logo_url);
                return array('width' => (int) $size[0], 'height' => (int) $size[1]);
            }
        }

    return array('width' => 0, 'height' => 0);
}

/**
 * 🔥 显示权限错误页面（带退出登录按钮）
 * 用于替代 wp_die()，提供更友好的错误页面体验
 */
function ruiyi_permission_denied_page($message = '', $title = '') {
    // 默认消息
    if (empty($message)) {
        $message = ruiyi_translate(
            'No tienes permisos para acceder a esta página.',
            'You do not have permission to access this page.',
            '您没有权限访问此页面。'
        );
    }
    // 默认标题
    if (empty($title)) {
        $title = ruiyi_translate('Acceso Denegado', 'Access Denied', '访问被拒绝');
    }

    // 获取退出登录URL
    $logout_url = wp_logout_url(wp_login_url());
    $logout_text = ruiyi_translate('Cerrar Sesión', 'Logout', '退出登录');
    $return_text = ruiyi_translate('Volver a Iniciar Sesión', 'Return to Login', '返回登录页面');

    // 设置HTTP状态码
    status_header(403);

    // 输出自定义错误页面
    ?>
    <!DOCTYPE html>
    <html lang="<?php echo get_locale(); ?>">
    <head>
        <meta charset="UTF-8">
        <meta name="viewport" content="width=device-width, initial-scale=1.0">
        <title><?php echo esc_html($title); ?></title>
        <style>
            * {
                margin: 0;
                padding: 0;
                box-sizing: border-box;
            }
            body {
                font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
                background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
                min-height: 100vh;
                display: flex;
                align-items: center;
                justify-content: center;
                padding: 20px;
            }
            .error-container {
                background: white;
                border-radius: 16px;
                box-shadow: 0 20px 60px rgba(0, 0, 0, 0.3);
                padding: 40px;
                max-width: 450px;
                width: 100%;
                text-align: center;
            }
            .error-icon {
                font-size: 64px;
                margin-bottom: 20px;
            }
            .error-title {
                color: #1a1a2e;
                font-size: 24px;
                font-weight: 700;
                margin-bottom: 16px;
            }
            .error-message {
                color: #4a5568;
                font-size: 16px;
                line-height: 1.6;
                margin-bottom: 32px;
            }
            .logout-btn {
                display: inline-block;
                background: linear-gradient(135deg, #ef4444 0%, #dc2626 100%);
                color: white;
                text-decoration: none;
                padding: 14px 32px;
                border-radius: 8px;
                font-size: 16px;
                font-weight: 600;
                transition: all 0.3s ease;
                box-shadow: 0 4px 15px rgba(239, 68, 68, 0.4);
            }
            .logout-btn:hover {
                transform: translateY(-2px);
                box-shadow: 0 6px 20px rgba(239, 68, 68, 0.5);
            }
            .logout-btn:active {
                transform: translateY(0);
            }
            .user-info {
                margin-top: 24px;
                padding-top: 20px;
                border-top: 1px solid #e2e8f0;
                color: #718096;
                font-size: 14px;
            }
            .user-info strong {
                color: #4a5568;
            }
        </style>
    </head>
    <body>
        <div class="error-container">
            <div class="error-icon">🚫</div>
            <h1 class="error-title"><?php echo esc_html($title); ?></h1>
            <p class="error-message"><?php echo esc_html($message); ?></p>
            <a href="<?php echo esc_url($logout_url); ?>" class="logout-btn">
                🔓 <?php echo esc_html($return_text); ?>
            </a>
            <?php if (is_user_logged_in()): ?>
                <?php $current_user = wp_get_current_user(); ?>
                <div class="user-info">
                    <?php echo ruiyi_translate('Usuario actual:', 'Current user:', '当前用户：'); ?>
                    <strong><?php echo esc_html($current_user->display_name); ?></strong>
                    (<?php echo esc_html(implode(', ', $current_user->roles)); ?>)
                </div>
            <?php endif; ?>
        </div>
