}

// 🔥 延长 WordPress Nonce 有效期为 365 天
// 解决 POS 系统长时间运行后 Nonce 过期导致同步失败的问题
// 默认是 86400 秒（24小时），这里设置为 31536000 秒（365天）
add_filter('nonce_life', function() {
    return 365 * DAY_IN_SECONDS; // 365天 = 31536000 秒
});

