// 🔍 检查WooCommerce依赖
function ruiyi_check_woocommerce_dependency() {
    if (!class_exists('WooCommerce')) {
        add_action('admin_notices', function() {
            echo '<div class="notice notice-error"><p>';
            echo '<strong>RUIYI POS系统错误：</strong> 此主题需要WooCommerce插件支持。请安装并激活WooCommerce插件。';
            echo '</p></div>';
        });
        return false;
    }
    return true;
}

// 🚀 确保WooCommerce在主题功能加载前完全初始化
function ruiyi_ensure_woocommerce_loaded() {
    if (!did_action('woocommerce_loaded')) {
        add_action('woocommerce_loaded', 'ruiyi_init_theme_features');
    } else {
        ruiyi_init_theme_features();
    }
}
add_action('after_setup_theme', 'ruiyi_ensure_woocommerce_loaded');

/**
 * 主题功能初始化（在WooCommerce加载后执行）
 */
function ruiyi_init_theme_features() {
    // 验证WooCommerce依赖
    if (!ruiyi_check_woocommerce_dependency()) {
        return; // 如果WooCommerce不可用，停止加载主题功能
    }

    // 现在安全地加载所有主题功能
    ruiyi_load_theme_includes();
}

/**
 * 加载主题包含文件
 */
function ruiyi_load_theme_includes() {
    // 引入认证相关功能
    require_once get_template_directory() . '/Inc/auth.php';

// 引入用户积分管理系统
require_once get_template_directory() . '/Inc/user-points-system.php';

// 跨站点功能已移至独立插件 - 这些引入已移除


