// Función para limpiar footer completamente en páginas del POS
function ruiyi_remove_footer_credits() {
    // Remover todos los posibles footer credits
    remove_action('wp_footer', 'wp_admin_bar_render', 1000);
    
    // Filtrar el contenido del footer
    add_filter('the_content', function($content) {
        // Remover cualquier referencia a "powered by" o "funciona gracias a"
        $content = preg_replace('/.*funciona gracias a.*<a.*WordPress.*<\/a>.*/i', '', $content);
        $content = preg_replace('/.*powered by.*<a.*WordPress.*<\/a>.*/i', '', $content);
        return $content;
    });
}
add_action('wp_head', 'ruiyi_remove_footer_credits');

