if (!function_exists('ruiyi_pos_product_sort_value')) {
    function ruiyi_pos_product_sort_value($product_id) {
        $sort_order = get_post_meta($product_id, '_ruiyi_product_sort_order', true);
        return $sort_order !== '' ? intval($sort_order) : intval($product_id);
    }
}

if (!function_exists('ruiyi_pos_sort_products_like_cashier')) {
    function ruiyi_pos_sort_products_like_cashier($products) {
        if (!is_array($products)) {
            return [];
        }

        usort($products, function($a, $b) {
            $a_id = is_object($a) && method_exists($a, 'get_id') ? $a->get_id() : 0;
            $b_id = is_object($b) && method_exists($b, 'get_id') ? $b->get_id() : 0;
            $a_sort = ruiyi_pos_product_sort_value($a_id);
            $b_sort = ruiyi_pos_product_sort_value($b_id);

            if ($a_sort === $b_sort) {
                return intval($a_id) - intval($b_id);
            }
            return $a_sort - $b_sort;
        });

        return $products;
    }
}

if (!function_exists('ruiyi_pos_get_category_descendant_ids_for_waiter')) {
    function ruiyi_pos_get_category_descendant_ids_for_waiter($category_id) {
        $ids = [intval($category_id)];
        $children = get_term_children($category_id, 'product_cat');

        if (!is_wp_error($children) && !empty($children)) {
            $ids = array_merge($ids, array_map('intval', $children));
        }

        return array_values(array_unique(array_filter($ids)));
    }
}

if (!function_exists('ruiyi_pos_get_waiter_categories_like_cashier')) {
    function ruiyi_pos_get_waiter_categories_like_cashier() {
        $excluded_slugs = ['uncategorized', 'suplementos'];
        $categories = get_terms([
            'taxonomy' => 'product_cat',
            'hide_empty' => true,
            'parent' => 0,
            'orderby' => 'name',
            'order' => 'ASC',
        ]);

        if (is_wp_error($categories) || empty($categories)) {
            return [];
        }

        $ordered = [];
        foreach ($categories as $category) {
            if (in_array($category->slug, $excluded_slugs, true)) {
                continue;
            }

            $sort_order = get_term_meta($category->term_id, 'category_sort_order', true);
            $category->sort_order = $sort_order !== '' ? intval($sort_order) : 999;
            $ordered[] = $category;
        }

        usort($ordered, function($a, $b) {
            if ($a->sort_order === $b->sort_order) {
                return strcasecmp($a->name, $b->name);
            }
            return $a->sort_order - $b->sort_order;
        });

        return $ordered;
    }
}

function ruiyi_get_simple_products() {
    // Verificar nonce
    if (!isset($_POST['nonce']) || !wp_verify_nonce($_POST['nonce'], 'ruiyi_pos_nonce')) {
        wp_send_json_error(['message' => 'Error de seguridad']);
        return;
    }
    
    try {
        // Obtener productos de WooCommerce
        $products = wc_get_products([
            'limit' => -1,
            'status' => 'publish'
        ]);
        $products = ruiyi_pos_sort_products_like_cashier($products);
        
        $products_data = [];
        
        foreach ($products as $product) {
            $image_id = $product->get_image_id();
            $image_url = '';
            
            // Obtener URL de imagen con fallbacks
            if ($image_id) {
                $image_url = wp_get_attachment_url($image_id);
            }
            
            // Si no hay imagen, intentar obtener la imagen destacada
            if (!$image_url) {
                $thumbnail_id = get_post_thumbnail_id($product->get_id());
                if ($thumbnail_id) {
                    $image_url = wp_get_attachment_url($thumbnail_id);
                }
            }
            
            // Placeholder si no hay imagen
            if (!$image_url) {
                $image_url = 'https://via.placeholder.com/200x200?text=Sin+Imagen';
            }
            
            $categories = [];
            $terms = get_the_terms($product->get_id(), 'product_cat');
            if ($terms && !is_wp_error($terms)) {
                foreach ($terms as $term) {
                    $categories[] = [
                        'term_id' => $term->term_id,
                        'name' => $term->name,
                        'slug' => $term->slug
                    ];
                }
            }
            
            // 🔥 获取分区价格
            $zone_prices = get_post_meta($product->get_id(), '_ruiyi_zone_prices', true);
            if (!is_array($zone_prices)) {
                $zone_prices = array();
            }

            $products_data[] = [
                'id' => $product->get_id(),
                'name' => $product->get_name(), // 西班牙语名称（原始）
                'name_zh' => get_post_meta($product->get_id(), '_product_name_zh', true), // 中文名称
                'name_en' => get_post_meta($product->get_id(), '_product_name_en', true), // 英文名称
                'price' => floatval($product->get_price()), // 使用产品原始价格（基础价格）
                'zone_prices' => $zone_prices, // 🔥 分区价格
                'image' => $image_url,
                'image_url' => $image_url,
                'stock_status' => $product->get_stock_status(),
                'categories' => $categories,
                'sort_order' => ruiyi_pos_product_sort_value($product->get_id())
            ];
        }
        
        wp_send_json_success(['products' => $products_data]);
        
    } catch (Exception $e) {
        wp_send_json_error(['message' => 'Error al obtener productos: ' . $e->getMessage()]);
    }
}

/* 🏷️ AJAX端点simplificado para categorías */
add_action('wp_ajax_ruiyi_get_simple_categories', 'ruiyi_get_simple_categories');
add_action('wp_ajax_nopriv_ruiyi_get_simple_categories', 'ruiyi_get_simple_categories');

function ruiyi_get_simple_categories() {
    // Verificar nonce
    if (!isset($_POST['nonce']) || !wp_verify_nonce($_POST['nonce'], 'ruiyi_pos_nonce')) {
        wp_send_json_error(['message' => 'Error de seguridad']);
        return;
    }
    
    try {
        // Obtener categorías en el mismo orden que la caja principal
        $categories = ruiyi_pos_get_waiter_categories_like_cashier();
        
        $categories_data = [];
        
        if (!is_wp_error($categories)) {
            foreach ($categories as $category) {
                // 获取多语言字段（根据您的插件可能的字段名）
                $name_zh = get_term_meta($category->term_id, 'name_zh', true) ?:
                          get_term_meta($category->term_id, 'chinese_name', true) ?:
                          get_term_meta($category->term_id, 'category_name_zh', true);
                
                $name_en = get_term_meta($category->term_id, 'name_en', true) ?:
                          get_term_meta($category->term_id, 'english_name', true) ?:
                          get_term_meta($category->term_id, 'category_name_en', true);
                
                $name_es = get_term_meta($category->term_id, 'name_es', true) ?:
                          get_term_meta($category->term_id, 'spanish_name', true) ?:
                          get_term_meta($category->term_id, 'category_name_es', true);
                
                $categories_data[] = [
                    'id' => $category->term_id,
                    'term_id' => $category->term_id,
                    'name' => $category->name,
                    'slug' => $category->slug,
                    'count' => $category->count,
                    'parent' => $category->parent,
                    'descendant_ids' => ruiyi_pos_get_category_descendant_ids_for_waiter($category->term_id),
                    'sort_order' => isset($category->sort_order) ? intval($category->sort_order) : 999,
                    // 添加多语言支持
                    'name_zh' => $name_zh,
                    'name_en' => $name_en,
                    'name_es' => $name_es
                ];
            }
        }
        
        wp_send_json_success(['categories' => $categories_data]);
        
    } catch (Exception $e) {
        wp_send_json_error(['message' => 'Error al obtener categorías: ' . $e->getMessage()]);
    }
}

/* 🧹 AJAX端点para invalidar cache de estados de mesa */
add_action('wp_ajax_ruiyi_invalidate_table_cache', 'ruiyi_invalidate_table_cache');
add_action('wp_ajax_nopriv_ruiyi_invalidate_table_cache', 'ruiyi_invalidate_table_cache');

function ruiyi_invalidate_table_cache() {
    // Verificar nonce
    if (!isset($_POST['nonce']) || !wp_verify_nonce($_POST['nonce'], 'ruiyi_pos_nonce')) {
        wp_send_json_error(['message' => 'Error de seguridad']);
        return;
    }
    
    $source = isset($_POST['source']) ? sanitize_text_field($_POST['source']) : 'unknown';
    
    // Limpiar todas las caches relacionadas con estados de mesa
    delete_transient('ruiyi_pos_table_statuses');
    delete_transient('ruiyi_pos_table_orders');
    wp_cache_delete('table_statuses', 'ruiyi_pos');
    wp_cache_delete('live_table_statuses', 'ruiyi_pos');
    
    // Forzar recálculo de estados
    $live_statuses = get_option('ruiyi_pos_live_table_statuses', array());
    
    // Actualizar timestamp para forzar refresh en sistemas cliente
    update_option('ruiyi_pos_cache_timestamp', time(), 'no');
    
    ruiyi_debug_log("RUIYI POS: Cache de estados de mesa invalidado por: $source");
    
    wp_send_json_success([
        'message' => 'Cache invalidado exitosamente',
        'timestamp' => time(),
        'source' => $source
    ]);
}

/**
 * 🔥 桌位状态原子更新辅助函数（防止并发竞态条件）
 * 使用 MySQL SELECT ... FOR UPDATE 行级锁，确保读-改-写操作的原子性
 *
 * @param callable $callback 接收当前状态数组，返回更新后的数组。返回 false 则不写入。
 */
function ruiyi_atomic_update_table_statuses($callback) {
    global $wpdb;
    $wpdb->query('START TRANSACTION');
    try {
        $row = $wpdb->get_var($wpdb->prepare(
            "SELECT option_value FROM {$wpdb->options} WHERE option_name = %s FOR UPDATE",
            'ruiyi_pos_live_table_statuses'
        ));
        $current = $row ? maybe_unserialize($row) : array();
        if (!is_array($current)) $current = array();

        $updated = call_user_func($callback, $current);

        if ($updated !== false && is_array($updated)) {
            $serialized = maybe_serialize($updated);
            if ($row !== null) {
                $wpdb->update(
                    $wpdb->options,
                    array('option_value' => $serialized),
                    array('option_name' => 'ruiyi_pos_live_table_statuses')
                );
            } else {
                $wpdb->insert(
                    $wpdb->options,
                    array('option_name' => 'ruiyi_pos_live_table_statuses', 'option_value' => $serialized, 'autoload' => 'no')
                );
            }
        }
        $wpdb->query('COMMIT');
    } catch (Exception $e) {
        $wpdb->query('ROLLBACK');
        ruiyi_debug_log("[竞态保护] ❌ 桌位状态原子更新失败: " . $e->getMessage());
    }
    wp_cache_delete('ruiyi_pos_live_table_statuses', 'options');
    delete_transient('ruiyi_pos_table_statuses');
}

/**
 * 🔥 原子设置单个桌位状态
 */
function ruiyi_update_single_table_status($table_number_numeric, $status_data) {
    ruiyi_atomic_update_table_statuses(function($statuses) use ($table_number_numeric, $status_data) {
        $statuses[$table_number_numeric] = $status_data;
        return $statuses;
    });
}

/**
 * 🔥 原子清除桌位状态（清除匹配数字桌号的所有键格式）
 * @return void
 */
function ruiyi_clear_table_status_all_formats($table_number_numeric) {
    ruiyi_atomic_update_table_statuses(function($statuses) use ($table_number_numeric) {
        $cleared = false;
        $_mappings = ruiyi_get_all_table_categories_mapping();
        foreach (array_keys($statuses) as $key) {
            $key_global = ruiyi_safe_extract_table_number($key, $_mappings);
            if ($key_global === $table_number_numeric) {
                unset($statuses[$key]);
                $cleared = true;
            }
        }
        return $cleared ? $statuses : false;
    });
}

/* 🏷️ AJAX端点para productos con descuento */
add_action('wp_ajax_ruiyi_get_discount_products', 'ruiyi_get_discount_products');
add_action('wp_ajax_nopriv_ruiyi_get_discount_products', 'ruiyi_get_discount_products');

function ruiyi_get_discount_products() {
    // Verificar nonce
    if (!isset($_POST['nonce']) || !wp_verify_nonce($_POST['nonce'], 'ruiyi_pos_nonce')) {
        wp_send_json_error(['message' => 'Error de seguridad']);
        return;
    }
    
    try {
        // Obtener productos con descuento (sale_price menor que regular_price), excluyendo productos de puntos
        $products = wc_get_products([
            'limit' => -1,
            'status' => 'publish',
            'meta_query' => [
                'relation' => 'AND',
                [
                    'key' => '_sale_price',
                    'value' => '',
                    'compare' => '!='
                ],
                [
                    'key' => '_sale_price',
                    'value' => 0,
                    'compare' => '>'
                ],
                [
                    'key' => '_is_points_product',
                    'value' => 'yes',
                    'compare' => '!='
                ]
            ]
        ]);
        
        $discount_products = [];
        
        foreach ($products as $product) {
            $regular_price = floatval($product->get_regular_price());
            $sale_price = floatval($product->get_sale_price());
            
            // Solo incluir productos que realmente tienen descuento
            if ($sale_price > 0 && $sale_price < $regular_price) {
                $discount_amount = $regular_price - $sale_price;
                $discount_percentage = round(($discount_amount / $regular_price) * 100);
                
                $image_id = $product->get_image_id();
                $image_url = $image_id ? wp_get_attachment_url($image_id) : '';
                if (!$image_url) {
                    $thumbnail_id = get_post_thumbnail_id($product->get_id());
                    if ($thumbnail_id) {
                        $image_url = wp_get_attachment_url($thumbnail_id);
                    }
                }
                if (!$image_url) {
                    $image_url = 'https://via.placeholder.com/200x200?text=Sin+Imagen';
                }
                
                $categories = [];
                $terms = get_the_terms($product->get_id(), 'product_cat');
                if ($terms && !is_wp_error($terms)) {
                    foreach ($terms as $term) {
                        $categories[] = [
                            'term_id' => $term->term_id,
                            'name' => $term->name,
                            'slug' => $term->slug
                        ];
                    }
                }
                
                $discount_products[] = [
                    'id' => $product->get_id(),
                    'name' => $product->get_name(),
                    'regular_price' => $regular_price,
                    'sale_price' => $sale_price,
                    'discount_amount' => $discount_amount,
                    'discount_percentage' => $discount_percentage,
                    'image' => $image_url,
                    'image_url' => $image_url,
                    'stock_status' => $product->get_stock_status(),
                    'categories' => $categories
                ];
            }
        }
        
        // Ordenar por mayor descuento porcentual
        usort($discount_products, function($a, $b) {
            return $b['discount_percentage'] - $a['discount_percentage'];
        });
        
        wp_send_json_success(['products' => $discount_products]);
        
    } catch (Exception $e) {
        wp_send_json_error(['message' => 'Error al obtener productos con descuento: ' . $e->getMessage()]);
    }
}

/* 🧾 CAMPOS PERSONALIZADOS PARA FACTURACIÓN */
// Añadir campo NIF/CIF en el checkout (después del campo empresa)
add_filter('woocommerce_checkout_fields', 'ruiyi_add_nif_cif_checkout_field');

function ruiyi_add_nif_cif_checkout_field($fields) {
    // Añadir campo NIF/CIF después del campo empresa
    $fields['billing']['billing_nif_cif'] = array(
        'type'        => 'text',
        'label'       => 'NIF/CIF',
        'placeholder' => ruiyi_translate('Introduce tu número de identificación fiscal (opcional)', 'Enter your tax identification number (optional)', '输入您的税务识别号码（可选）'),
        'required'    => false,
        'class'       => array('form-row-wide'),
        'priority'    => 35, // Colocar después del campo empresa (que suele tener priority 30)
        'clear'       => true
    );
    
    return $fields;
}

// Validar el campo NIF/CIF en checkout
add_action('woocommerce_checkout_process', 'ruiyi_validate_nif_cif_checkout');

function ruiyi_validate_nif_cif_checkout() {
    // Campo opcional, no se requiere validación estricta
    if (isset($_POST['billing_nif_cif']) && !empty($_POST['billing_nif_cif'])) {
        $nif_cif = sanitize_text_field($_POST['billing_nif_cif']);
        
        // Validación básica de formato (opcional)
        if (strlen($nif_cif) < 8 || strlen($nif_cif) > 12) {
            wc_add_notice(ruiyi_translate('El NIF/CIF debe tener entre 8 y 12 caracteres.', 'NIF/CIF must be between 8 and 12 characters.', 'NIF/CIF必须是8到12个字符。'), 'error');
        }
    }
}

