function ruiyi_add_nif_cif_admin_js() {
    global $pagenow, $post_type;
    
    // Solo añadir el script en páginas de edición de pedidos de WooCommerce
    if ($pagenow === 'post.php' && isset($_GET['post']) && get_post_type($_GET['post']) === 'shop_order') {
        ?>
        <script>
        document.addEventListener('DOMContentLoaded', function() {
            const nifCifInput = document.querySelector('input[name="_billing_nif_cif"]');
            if (nifCifInput) {
                nifCifInput.addEventListener('input', function() {
                    let value = this.value.toUpperCase().replace(/[^A-Z0-9]/g, '');
                    if (value.length > 12) value = value.substring(0, 12);
                    this.value = value;
                    
                    // Validación visual
                    const isValid = /^[A-Z0-9]{8,12}$/.test(value);
                    if (value.length > 0) {
                        this.style.borderColor = isValid ? '#28a745' : '#dc3545';
                        this.style.backgroundColor = isValid ? '#f8fff8' : '#fff8f8';
                    } else {
                        this.style.borderColor = '#ddd';
                        this.style.backgroundColor = '#fff';
                    }
                });
                
                // Añadir ayuda contextual
                const helpText = document.createElement('p');
                helpText.style.cssText = 'margin-top: 5px; color: #666; font-size: 12px; font-style: italic;';
                helpText.innerHTML = '<?php echo esc_js(ruiyi_translate("Formato: NIF (12345678A) o CIF (B12345678)", "Format: NIF (12345678A) or CIF (B12345678)", "格式: NIF (12345678A) 或 CIF (B12345678)")); ?>';
                nifCifInput.parentNode.appendChild(helpText);
            }
        });
        </script>
        <?php
    }
}

