/* 8️⃣ SCRIPTS DEL MODAL DE PIN */
function ruiyi_modulos_footer_scripts() {
    ?>
    <script>
    document.addEventListener("DOMContentLoaded", function () {
        let pin = "";
        let selectedModule = "";

        document.querySelectorAll(".ruiyi-modulo").forEach(modulo => {
            modulo.addEventListener("click", function (e) {
                if (this.dataset.module === "admin") {
                    e.preventDefault();
                    selectedModule = this.dataset.module;
                    document.querySelector(".frame").style.display = "flex";
                    pin = "";
                    document.querySelectorAll(".dot").forEach(dot => dot.classList.remove("filled"));
                }
            });
        });

        document.querySelectorAll(".pin-button").forEach(button => {
            button.addEventListener("click", function () {
                if (this.classList.contains("delete")) {
                    if (pin.length > 0) {
                        document.getElementById("dot" + pin.length).classList.remove("filled");
                        pin = pin.slice(0, -1);
                    }
                    return;
                }
                if (pin.length < 4) {
                    pin += this.dataset.number;
                    document.getElementById("dot" + pin.length).classList.add("filled");
                }
            });
        });

        document.getElementById("submit-pin").addEventListener("click", function () {
    if (pin.length !== 4) {
        Swal.fire({
            icon: 'warning',
            title: '⚠️ PIN Incompleto',
            text: 'El PIN debe tener 4 dígitos.'
        });
        return;
    }

    // Validar por AJAX
    fetch("<?php echo admin_url('admin-ajax.php'); ?>", {
        method: "POST",
        headers: { "Content-Type": "application/x-www-form-urlencoded" },
        body: new URLSearchParams({
            action: "ruiyi_validate_pin",
            pin: pin,
            module: selectedModule
        })
    })
    .then(res => res.json())
    .then(data => {
        if (data.success) {
            Swal.fire({
                icon: 'success',
                title: '✅ PIN Correcto',
                text: 'Redirigiendo...',
                timer: 1500,
                showConfirmButton: false
            }).then(() => {
                window.location.href = data.redirect;
            });
        } else {
            Swal.fire({
                icon: 'error',
                title: '❌ PIN Incorrecto',
                text: data.message || 'Vuelve a intentarlo.'
            });
            pin = "";
            document.querySelectorAll(".dot").forEach(dot => dot.classList.remove("filled"));
        }
    })
    .catch(err => {
        Swal.fire({ icon: 'error', title: '⚠️ Error de red', text: 'No se pudo validar el PIN.' });
    });
});

   <script>
function pagarOrden() {
  if (cart.length === 0) {
    Swal.fire('🛒 Carrito vacío', 'Agrega productos antes de pagar.', 'warning');
    return;
  }

  Swal.fire({
    title: 'Seleccionar método de pago',
    showDenyButton: true,
    showCancelButton: true,
    confirmButtonText: '💵 Efectivo',
    denyButtonText: '💳 Tarjeta',
    cancelButtonText: 'Cancelar',
  }).then((result) => {
    if (result.isConfirmed) {
      procesarPago('efectivo');  // 💵
    } else if (result.isDenied) {
      procesarPago('tarjeta');   // 💳
    }
  });
}

function procesarPago(metodoPago) {
  Swal.fire({
    title: 'Procesando pago...',
    allowOutsideClick: false,
    didOpen: () => Swal.showLoading()
  });

  const totalAmount = calcularTotalConDescuento();

  setTimeout(() => {
    Swal.close();

    if (metodoPago === 'efectivo') {
      abrirCajonDinero(); // 💵 SOLO efectivo
    }

    // 移除了这里的直接调用，避免重复打印
    // imprimirTicket();      // 🖨️ Ticket pequeño
    generarFacturaPDF();   // 📄 Factura A4

    // 📦 Crear el pedido y guardar en localStorage si todo va bien
    guardarPedidoWooCommerce(metodoPago).then(data => {
      if (data.success) {
        // 🔹 Guardar el ticket
        localStorage.setItem('ticket_pendiente', JSON.stringify({
          id: data.order_id,
          cart: cart,
          total: totalAmount,
          timestamp: Date.now()
        }));

        // 在这里调用imprimirTicket，并传递data参数
        imprimirTicket(data);
        Swal.fire('✅ Pedido creado', 'Pedido guardado correctamente.', 'success');
      } else {
        Swal.fire('❌ Error al crear pedido', data.message || 'Error desconocido', 'error');
      }
    }).catch(err => {
      console.error('Error en pedido WooCommerce:', err);
      
      // 显示更详细的错误信息
      Swal.fire({
        icon: 'error',
        title: '❌ Error de conexión',
        text: 'No se pudo comunicar con el servidor. Verifique su conexión a internet e inténtelo nuevamente.',
        footer: '技术错误: ' + err.message,
        confirmButtonColor: '#d33',
        confirmButtonText: 'Intentar de nuevo'
      }).then((result) => {
        if (result.isConfirmed) {
          // 用户点击重试按钮，可以在这里重新尝试
          console.log("用户请求重试支付流程");
        }
      });
    });
  }, 1000);
}

function guardarPedidoWooCommerce(metodoPago) {
  return fetch(ajaxurl, {
    method: 'POST',
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body: new URLSearchParams({
      action: 'ruiyi_pos_create_order',
      cart: JSON.stringify(cart),
      payment_method: metodoPago,
      nonce: ruiyi_pos_nonce
    })
  })
  .then(res => {
    // 检查响应状态
    if (!res.ok) {
      throw new Error(`Error HTTP: ${res.status}`);
    }
    return res.json();
  })
  .then(data => {
    // 移除这里的imprimirTicket调用，避免重复打印
    // if (data.success) {
    //   imprimirTicket(data);  // 这里不再调用，而是在procesarPago中统一调用
    // }
    
    if (!data.success) {
      console.error('Error en la respuesta del servidor:', data);
      alert('发生错误: ' + (data.message || '服务器未返回成功状态'));
    }
    return data;
  })
  .catch(error => {
    console.error('Error de conexión:', error);
    alert('连接错误: 无法与服务器通信，请检查网络连接并重试');
    return { success: false, message: error.message };
  });
}


function calcularTotalConDescuento() {
  const subtotal = cart.reduce((acc, item) => acc + (item.price * item.quantity), 0);
  const discount = parseFloat(document.getElementById('discount-input')?.value) || 0;
  return subtotal - discount;
}
</script>

<script>
async function abrirCajonDinero() {
  try {
    const port = await navigator.serial.requestPort();
    await port.open({ baudRate: 9600 });
    const writer = port.writable.getWriter();
    const abrir = new Uint8Array([27, 112, 0, 25, 250]); // 🧠 ESC/POS comando abrir cajón
    await writer.write(abrir);
    writer.releaseLock();
    await port.close();
    console.log('Cajón abierto ✅');
  } catch (error) {
    console.error('No se pudo abrir el cajón:', error);
  }
}
</script>
<script src="https://cdn.jsdelivr.net/npm/qrcode/build/qrcode.min.js"></script> <!-- Necesario para QR -->
function imprimirTicket(orderData) {
  try {
    // 如果没有传入orderData，终止执行并记录错误
    if (!orderData) {
      console.error('Error: No se proporcionaron datos de pedido para imprimir el ticket');
      return;
    }
    
    const ticketWindow = window.open('', '_blank');
    if (!ticketWindow) {
      console.error('Error: No se pudo abrir la ventana del ticket. Compruebe si el navegador bloquea ventanas emergentes.');
      alert('No se pudo imprimir el ticket. Verifique que no esté bloqueando ventanas emergentes.');
      return;
    }

    const total = orderData.total || 0;
    const orderId = orderData.order_id || Math.floor(Math.random() * 90000 + 10000);

    const checkoutUrl = `${window.location.origin}/pago-qr-pedido/?order_id=${orderId}`;

    const productosHTML = cart.map(item =>
      `${item.quantity} x ${item.name} - $${(item.price * item.quantity).toFixed(2)}`
    ).join('<br>');

    ticketWindow.document.write(`
      <html>
      <head>
        <title>Ticket RUIYI</title>
        <style>
          body { font-family: monospace; text-align: center; padding: 20px; }
          .line { border-top: 1px dashed #000; margin: 10px 0; }
          .qr-code { margin-top: 20px; }
        </style>
      </head>
      <body>
        <h2>🏠 Restaurante RUIYI</h2>
        <div class="line"></div>
        ${productosHTML}
        <div class="line"></div>
        <strong>Total: $${total.toFixed(2)}</strong>
        <div class="line"></div>
        <div class="qr-code">
          <canvas id="qrcode"></canvas>
        </div>
        <p>¡Gracias por tu compra! 🙏</p>

        <script src="https://cdn.jsdelivr.net/npm/qrcode/build/qrcode.min.js"></script>
      <script>
        // 加载完成后生成QR码
        window.onload = function() {
          try {
            if (typeof QRCode !== 'undefined') {
              QRCode.toCanvas(document.getElementById('qrcode'), "${checkoutUrl}", { width: 150 });
              
              // 延迟1秒后打印
              setTimeout(function() {
                window.print();
                // 打印后延迟关闭窗口
                setTimeout(function() {
                  window.close();
                }, 500);
              }, 1000);
            } else {
              console.error("QRCode no está disponible");
            }
          } catch(e) {
            console.error("Error al generar QR:", e);
          }
        }
      </script>
    </body>
    </html>
  `);

  ticketWindow.document.close();
  } catch (error) {
    console.error('Error al imprimir ticket:', error);
    alert('Error al generar el ticket: ' + error.message);
  }
}

<script>
function generarFacturaPDF() {
  const { jsPDF } = window.jspdf;
  const doc = new jsPDF();

  doc.setFontSize(20);
  doc.text('Factura Restaurante RUIYI', 20, 20);

  doc.setFontSize(12);
  let y = 40;
  cart.forEach(item => {
    doc.text(`${item.quantity} x ${item.name}`, 20, y);
    doc.text(`$${(item.price * item.quantity).toFixed(2)}`, 160, y, { align: 'right' });
    y += 10;
  });

  doc.setDrawColor(0);
  doc.line(20, y, 190, y);

  y += 10;
  doc.setFontSize(14);
  doc.text('Total:', 20, y);
  doc.text(`$${calcularTotalConDescuento().toFixed(2)}`, 160, y, { align: 'right' });

  y += 20;
  doc.setFontSize(10);
  doc.text('¡Gracias por su compra! 🙏', 20, y);

  doc.save(`Factura_RUIYI_${Date.now()}.pdf`);
}
</script>


