/* 🔐 NONCE 刷新端点 - 解决长时间运行导致nonce过期的问题 */
add_action('wp_ajax_ruiyi_pos_refresh_nonce', 'ruiyi_pos_refresh_nonce_callback');
add_action('wp_ajax_nopriv_ruiyi_pos_refresh_nonce', 'ruiyi_pos_refresh_nonce_callback');

function ruiyi_pos_refresh_nonce_callback() {
    // 生成新的nonce
    $new_nonce = wp_create_nonce('ruiyi_pos_nonce');

    wp_send_json_success([
        'nonce' => $new_nonce,
        'expires_in' => 12 * HOUR_IN_SECONDS, // WordPress nonces valid for ~12 hours
        'timestamp' => time()
    ]);
}

/* 🔥 检查订单状态API - 用于支付同步失败时智能检测订单是否已完成 */
add_action('wp_ajax_ruiyi_pos_check_order_status', 'ruiyi_pos_check_order_status_callback');
add_action('wp_ajax_nopriv_ruiyi_pos_check_order_status', 'ruiyi_pos_check_order_status_callback');

function ruiyi_pos_check_order_status_callback() {
    // 获取订单ID列表
    $order_ids_json = isset($_POST['order_ids']) ? sanitize_text_field($_POST['order_ids']) : '[]';
    $order_ids = json_decode($order_ids_json, true);

    if (!is_array($order_ids) || empty($order_ids)) {
        wp_send_json_error(['message' => 'No order IDs provided']);
        return;
    }

    $statuses = [];

    foreach ($order_ids as $order_id) {
        $order_id = intval($order_id);
        if ($order_id <= 0) continue;

        $order = wc_get_order($order_id);
        if ($order) {
            $statuses[$order_id] = $order->get_status();
        }
    }

    wp_send_json_success([
        'statuses' => $statuses,
        'checked_at' => current_time('mysql')
    ]);
}

/* 9️⃣ CREAR PEDIDO DESDE POS */
add_action('wp_ajax_ruiyi_pos_create_order', 'ruiyi_pos_create_order');
add_action('wp_ajax_nopriv_ruiyi_pos_create_order', 'ruiyi_pos_create_order');
// 已修改：使用新的处理函数 ruiyi_get_pedidos_cocina_handler
// add_action('wp_ajax_ruiyi_get_pedidos_cocina', 'ruiyi_get_pedidos_cocina');
// add_action('wp_ajax_nopriv_ruiyi_get_pedidos_cocina', 'ruiyi_get_pedidos_cocina');

function ruiyi_pos_create_order() {
    // Validar el nonce de seguridad primero
    if (!isset($_POST['nonce']) || !wp_verify_nonce($_POST['nonce'], 'ruiyi_pos_nonce')) {
        wp_send_json_error(['message' => __('❌ Error de seguridad: nonce inválido.', 'ruiyi-pos')]);
        return;
    }

    // Verificar si es pedido de invitado
    $is_guest = isset($_POST['is_guest']) && $_POST['is_guest'] === 'yes';
    
    // Verificar login solo para usuarios no invitados
    if (!$is_guest && !is_user_logged_in()) {
        wp_send_json_error(['message' => __('🔒 Debes iniciar sesión para crear pedidos.', 'ruiyi-pos')]);
        return;
    }

    // Verificar carrito (permitir carrito vacío si hay productos con puntos o自助餐)
    $has_regular_items = isset($_POST['cart']) && !empty($_POST['cart']);
    $has_points_items = isset($_POST['points_items']) && !empty($_POST['points_items']);
    $has_buffet_items = isset($_POST['buffet_items']) && !empty($_POST['buffet_items']);


    if (!$has_regular_items && !$has_points_items && !$has_buffet_items) {
        wp_send_json_error(['message' => __('🛒 El carrito está vacío.', 'ruiyi-pos')]);
        return;
    }

    // Obtener datos del formulario y sanitizarlos
    $user_id = $is_guest ? 0 : get_current_user_id();
    
    // Decodificar y validar el carrito regular
    $cart = array();
    if ($has_regular_items) {
        $cart_json = stripslashes($_POST['cart']);
        $cart = json_decode($cart_json, true);

        // 🔥🔥🔥 调试日志：记录收到的购物车数据
        ruiyi_debug_log("[create_order-DEBUG] 📦 收到购物车数据 (JSON): " . $cart_json);
        ruiyi_debug_log("[create_order-DEBUG] 📦 解析后购物车数量: " . (is_array($cart) ? count($cart) : '解析失败'));
        if (is_array($cart) && !empty($cart)) {
            foreach ($cart as $idx => $item) {
                ruiyi_debug_log("[create_order-DEBUG] 📦 购物车项 #{$idx}: id=" . ($item['id'] ?? 'N/A') . ", qty=" . ($item['quantity'] ?? 'N/A') . ", price=" . ($item['price'] ?? 'N/A') . ", customPrice=" . ($item['customPrice'] ?? 'N/A') . ", zoneCategoryId=" . ($item['zoneCategoryId'] ?? 'N/A') . ", basePrice=" . ($item['basePrice'] ?? 'N/A'));
            }
        }

        // 如果解码后是空数组，则认为没有常规产品
        if (empty($cart)) {
            $has_regular_items = false;
        }
    }
    
    // Decodificar y validar productos con puntos
    $points_items = array();
    if ($has_points_items) {
        $points_json = stripslashes($_POST['points_items']);
        $points_items = json_decode($points_json, true);
        
        if (json_last_error() !== JSON_ERROR_NONE) {
            wp_send_json_error([
                'message' => __('❌ Error en formato del carrito.', 'ruiyi-pos'),
                'error_detail' => json_last_error_msg()
            ]);
            return;
        }
        
        // 如果解码后是空数组，则认为没有积分产品
        if (empty($points_items)) {
            $has_points_items = false;
        }
    }
    
    // 重新验证是否有有效产品（在解码之后）
    if (!$has_regular_items && !$has_points_items && !$has_buffet_items) {
        wp_send_json_error(['message' => __('🛒 El carrito está vacío.', 'ruiyi-pos')]);
        return;
    }
    
    // 验证购物车格式（只在有相应产品时验证）
    if ($has_regular_items && !is_array($cart)) {
        wp_send_json_error(['message' => __('🛒 El carrito está vacío o tiene formato inválido.', 'ruiyi-pos')]);
        return;
    }
    
    if ($has_points_items && !is_array($points_items)) {
        wp_send_json_error(['message' => __('🛒 Los productos con puntos tienen formato inválido.', 'ruiyi-pos')]);
        return;
    }

    // Sanitizar otros campos
    $discount_param = isset($_POST['discount']) ? sanitize_text_field($_POST['discount']) : '0.00';
    $discount_amount = floatval(str_replace(',', '.', $discount_param));

    if (!is_numeric($discount_amount) || $discount_amount < 0) {
        $discount_amount = 0.00;
    }

    $tip_amount = isset($_POST['tip_amount']) ? floatval($_POST['tip_amount']) : 0;
    $note = isset($_POST['note']) ? sanitize_textarea_field($_POST['note']) : '';
    $table_number = isset($_POST['table_number']) ? sanitize_text_field($_POST['table_number']) : '';
    $payment_method = isset($_POST['payment_method']) ? sanitize_text_field($_POST['payment_method']) : 'cod';

    // 🔥🔥🔥 调试日志：记录客户扫码页面传递的关键参数
    ruiyi_debug_log("[create_order-DEBUG] 🔑 桌号: '" . $table_number . "' (empty: " . (empty($table_number) ? 'YES' : 'NO') . ")");
    ruiyi_debug_log("[create_order-DEBUG] 🔑 is_guest: " . (isset($_POST['is_guest']) ? $_POST['is_guest'] : 'NOT SET'));

    // 🔥 添加调试日志：记录接收到的支付方式参数
    ruiyi_debug_log("POS: 收到的支付方式参数: " . $payment_method . " (isset: " . (isset($_POST['payment_method']) ? 'true' : 'false') . ")");

    // 获取订单类型 (默认为堂食 "servir")
    $order_type = isset($_POST['order_type']) ? sanitize_text_field($_POST['order_type']) : 'servir';
    // 记录收到的order_type参数
    ruiyi_debug_log("POS: 收到的订单类型参数: " . $order_type);
    
    // 检查是否为追加订单
    $is_addition = isset($_POST['is_addition']) && $_POST['is_addition'] === 'true';
    ruiyi_debug_log("POS: 是否为追加订单: " . ($is_addition ? 'true' : 'false'));
    
    // 获取客户信息（仅限外卖订单）
    $customer_info = null;

    // 🔍 [调试] 记录原始POST数据
    ruiyi_debug_log("🔍 [客户信息调试] POST数据检查:");
    ruiyi_debug_log("🔍 [客户信息调试] - order_type: " . $order_type);
    ruiyi_debug_log("🔍 [客户信息调试] - isset(\$_POST['customer_info']): " . (isset($_POST['customer_info']) ? 'YES' : 'NO'));
    ruiyi_debug_log("🔍 [客户信息调试] - empty(\$_POST['customer_info']): " . (empty($_POST['customer_info']) ? 'YES' : 'NO'));

    if (isset($_POST['customer_info'])) {
        ruiyi_debug_log("🔍 [客户信息调试] - 原始customer_info值: " . $_POST['customer_info']);
    }

    // 🔥 修复：移除 order_type === 'llevar' 限制，允许所有订单类型保存客户信息
    // 外送桌位（如"外送1"）也需要保存客户信息
    if (isset($_POST['customer_info']) && !empty($_POST['customer_info'])) {
        $customer_info_json = stripslashes($_POST['customer_info']);
        ruiyi_debug_log("🔍 [客户信息调试] - stripslashes后: " . $customer_info_json);

        $customer_info = json_decode($customer_info_json, true);

        ruiyi_debug_log("🔍 [客户信息调试] - json_decode成功: " . (is_array($customer_info) ? 'YES' : 'NO'));
        ruiyi_debug_log("🔍 [客户信息调试] - json_last_error: " . json_last_error_msg());
        ruiyi_debug_log("🔍 [客户信息调试] - 解析后的客户信息: " . json_encode($customer_info, JSON_UNESCAPED_UNICODE));
    } else {
        ruiyi_debug_log("🔍 [客户信息调试] - 客户信息获取条件未满足 (customer_info不存在或为空)");
    }
    
    // Verificar que WooCommerce esté activo
    if (!function_exists('wc_create_order')) {
        wp_send_json_error(['message' => __('❌ WooCommerce no está disponible.', 'ruiyi-pos')]);
        return;
    }

    try {
        // 🔥🔥🔥 订单合并功能：堂食桌位订单自动合并到现有订单
        $existing_order = null;
        $is_merging_to_existing = false;

        // 只有堂食订单（servir）且有桌号时才尝试合并
        ruiyi_debug_log("[create_order-DEBUG] 🔄 检查订单合并条件: order_type='{$order_type}', table_number='{$table_number}'");
        ruiyi_debug_log("[create_order-DEBUG] 🔄 合并条件满足: " . (($order_type === 'servir' && !empty($table_number)) ? 'YES' : 'NO'));

        if ($order_type === 'servir' && !empty($table_number)) {
            // 🔥 关键修复：提取纯数字作为桌号（与存储格式一致）
            // "室内1" → "1", "Mesa 2" → "2", "餐桌3" → "3"
            $table_number_numeric = preg_replace('/[^0-9]/', '', trim((string)$table_number));

            // 🔥🔥🔥 【2026-04-06 关键修复】自定义桌位名称解析
            // 当桌位使用自定义名称时，preg_replace 提取的数字 ≠ 全局编号
            // 例如：T16 → 提取 "16" 但全局编号是 27，会匹配到错误的订单
            // 必须通过映射表将自定义名解析为正确的全局编号
            if (function_exists('ruiyi_get_all_table_categories_mapping')) {
                $_all_mappings_co = ruiyi_get_all_table_categories_mapping();
                $_input_norm_co = strtoupper(preg_replace('/\s+/', '', trim((string)$table_number)));
                foreach ($_all_mappings_co as $_mapping_co) {
                    $_dn_co = isset($_mapping_co['category_display_name']) ? $_mapping_co['category_display_name'] : '';
                    $_dn_norm_co = strtoupper(preg_replace('/\s+/', '', trim($_dn_co)));
                    if ($_dn_norm_co === $_input_norm_co && !empty($_mapping_co['global_table_number'])) {
                        $_resolved_gtn_co = (string)$_mapping_co['global_table_number'];
                        ruiyi_debug_log("[create_order] 🔥 自定义桌名解析: '{$table_number}' → 全局编号 {$_resolved_gtn_co} (原始提取: {$table_number_numeric})");
                        $table_number_numeric = $_resolved_gtn_co;
                        // 同时规范化 table_number 为 "Mesa X" 格式，使其能匹配换台后的订单
                        $table_number = 'Mesa ' . $_resolved_gtn_co;
                        break;
                    }
                }
            }

            ruiyi_debug_log("[create_order-DEBUG] 🔄 提取的数字桌号: '{$table_number_numeric}'");

            if (!empty($table_number_numeric)) {
                // 🔥🔥🔥 关键修复：清除WooCommerce订单缓存，确保获取最新订单数据
                // 这解决了快速连续发送请求时缓存导致的订单查找失败问题
                // 使用更精确的缓存清除，而不是 wp_cache_flush() 避免影响性能
                if (function_exists('wc_delete_shop_order_transients')) {
                    wc_delete_shop_order_transients();
                }
                // 清除特定的订单查询缓存
                wp_cache_delete('wc_orders_cache_group', 'orders');

                // 🔥🔥🔥 关键修复：查找所有活跃状态的堂食订单（pending, on-hold, processing）
                // 原问题：只查找 processing 状态，但桌位订单可能是 pending 或 on-hold 状态
                // 使用 'nocache' 参数强制跳过缓存
                $all_processing_orders = wc_get_orders([
                    'status' => ['pending', 'on-hold', 'processing'],
                    'limit' => 50, // 🔥 增加限制从20到50，确保能找到所有相关订单
                    'orderby' => 'date',
                    'order' => 'DESC',
                    'cache' => false, // 🔥 禁用缓存，确保获取最新数据
                ]);

                ruiyi_debug_log("POS: 🔍🔍🔍 当前所有活跃订单 (pending/on-hold/processing):");
                foreach ($all_processing_orders as $debug_order) {
                    $debug_table = $debug_order->get_meta('_table_number');
                    $debug_type = $debug_order->get_meta('_order_type');
                    ruiyi_debug_log("POS:   - 订单 #{$debug_order->get_id()}: 桌号='{$debug_table}', 类型='{$debug_type}'");
                }

                // 🔥 手动筛选：避免 meta_query 可能的 HPOS 兼容性问题
                $existing_order = null;

                // 🔥🔥🔥 【2026-01-19 关键修复】提取桌号前缀和数字，避免不同桌位类型被错误合并
                // 例如：COMEDOR2 和 DOMICILIO2 虽然数字都是 "2"，但属于不同桌位类型，不应合并
                $table_prefix = preg_replace('/[0-9]+$/', '', trim((string)$table_number)); // 提取前缀
                $table_prefix = strtoupper(trim($table_prefix)); // 标准化为大写
                ruiyi_debug_log("[create_order-DEBUG] 🔄 桌号分解: 原始='{$table_number}', 前缀='{$table_prefix}', 数字='{$table_number_numeric}'");

                foreach ($all_processing_orders as $candidate_order) {
                    $candidate_table = $candidate_order->get_meta('_table_number');
                    $candidate_type = $candidate_order->get_meta('_order_type');
                    // 🔥🔥🔥 【2026-01-30 新增】获取订单的显示桌号（换台后会设置此字段）
                    $candidate_display_name = $candidate_order->get_meta('_table_display_name');

                    // 🔥🔥🔥 关键修复：提取候选订单桌号的前缀和数字
                    $candidate_table_numeric = preg_replace('/[^0-9]/', '', trim((string)$candidate_table));
                    $candidate_table_prefix = preg_replace('/[0-9]+$/', '', trim((string)$candidate_table));
                    $candidate_table_prefix = strtoupper(trim($candidate_table_prefix));

                    ruiyi_debug_log("POS: 🔍 对比: 搜索桌号='{$table_prefix}{$table_number_numeric}' vs 订单桌号='{$candidate_table}'(前缀:'{$candidate_table_prefix}',数字:'{$candidate_table_numeric}'), 显示名='{$candidate_display_name}', 类型='{$candidate_type}'");

                    // 🔥🔥🔥 【2026-01-30 新增】优先检查显示桌号匹配（换台后的订单）
                    // 换台后订单的 _table_number 变为 "Mesa X"（全局编号），但 _table_display_name 保存了目标桌位名称
                    // 例如：换台到 DOMICILIO1 后，_table_number="Mesa 11", _table_display_name="DOMICILIO1"
                    // 当追加产品时，前端发送 table_number="DOMICILIO1"，需要通过 _table_display_name 匹配
                    if (!empty($candidate_display_name) && $candidate_type === 'servir') {
                        $search_table_upper = strtoupper(preg_replace('/\s+/', '', trim((string)$table_number)));
                        $display_name_upper = strtoupper(preg_replace('/\s+/', '', trim((string)$candidate_display_name)));

                        if ($search_table_upper === $display_name_upper) {
                            $existing_order = $candidate_order;
                            ruiyi_debug_log("POS: ✅ 通过显示桌号匹配找到订单 #{$candidate_order->get_id()} (_table_display_name='{$candidate_display_name}' 匹配 '{$table_number}')");
                            break;
                        }
                    }

                    // 🔥🔥🔥 【2026-01-19 修复】前缀匹配逻辑
                    // 必须同时匹配前缀和数字，类型必须是 servir
                    // 前缀匹配规则（更严格）：
                    // 1. 完全相同（DOMICILIO == DOMICILIO, COMEDOR == COMEDOR）
                    // 2. 兼容旧数据：如果其中一方为空，另一方是常见默认前缀（MESA/餐桌/TABLE）
                    // 注意：DOMICILIO3 和 COMEDOR3 是不同桌位，不应该合并！

                    // 定义"默认"前缀（用于兼容纯数字桌号的旧数据）
                    $default_prefixes = ['', 'MESA', '餐桌', 'TABLE', '桌'];
                    $is_default_search = in_array($table_prefix, $default_prefixes);
                    $is_default_candidate = in_array($candidate_table_prefix, $default_prefixes);

                    // 🔥 前缀匹配规则：
                    // 1. 前缀完全相同 → 匹配
                    // 2. 两边都是默认/空前缀 → 匹配（兼容旧数据：Mesa 3 == 3 == 餐桌3）
                    // 3. 不同的非默认前缀 → 不匹配（DOMICILIO3 != COMEDOR3）
                    $prefix_match = ($table_prefix === $candidate_table_prefix) ||
                                    ($is_default_search && $is_default_candidate);

                    if ($candidate_table_numeric === $table_number_numeric &&
                        $prefix_match &&
                        $candidate_type === 'servir') {
                        $existing_order = $candidate_order;
                        ruiyi_debug_log("POS: ✅ 找到匹配订单 #{$candidate_order->get_id()} (前缀匹配: {$table_prefix}=={$candidate_table_prefix})");
                        break;
                    }
                }

                if ($existing_order) {
                    $is_merging_to_existing = true;
                    $found_table = $existing_order->get_meta('_table_number');
                    ruiyi_debug_log("POS: 🔄 找到桌位 {$table_number_numeric} 的现有订单 #{$existing_order->get_id()}（订单桌号: {$found_table}），将合并新商品到此订单");
                } else {
                    ruiyi_debug_log("POS: 📋 桌位 {$table_number_numeric} 没有现有堂食订单，将创建新订单");
                }
            }
        }

        // 如果有现有订单则使用它，否则创建新订单
        if ($is_merging_to_existing && $existing_order) {
            $order = $existing_order;
            $order->add_order_note(__('➕ 追加商品到此订单', 'ruiyi-pos'));
            ruiyi_debug_log("POS: 使用现有订单 #{$order->get_id()} 进行商品追加");
        } else {
            // Crear orden con manejo de errores
            $order_args = ['customer_id' => $user_id];
            $order = wc_create_order($order_args);

            if (is_wp_error($order)) {
                wp_send_json_error([
                    'message' => __('❌ Error al crear pedido: ', 'ruiyi-pos') . $order->get_error_message(),
                    'error_code' => $order->get_error_code()
                ]);
                return;
            }
            ruiyi_debug_log("POS: 创建新订单 #{$order->get_id()}");
        }

        // Para pedidos de invitados (solo para nuevos订单)
        if ($is_guest && !$is_merging_to_existing) {
            $order->add_order_note(__('Pedido creado desde carrito cliente sin iniciar sesión', 'ruiyi-pos'));
            $order->update_meta_data('is_guest_order', 'yes');
        }

        // Añadir productos con validación
        $productos_validos = false;

        // 🔥 【2026-01-21 新增】记录本次新添加的商品，用于厨房打印只打印新商品
        $newly_added_items = array();

        // 🍽️ 处理自助餐商品（只记录到 newly_added_items 用于厨房打印，不添加到订单）
        if ($has_buffet_items) {
            $buffet_items_json = stripslashes($_POST['buffet_items']);
            $buffet_items = json_decode($buffet_items_json, true);
            if (is_array($buffet_items)) {
                foreach ($buffet_items as $b_item) {
                    if (!isset($b_item['id']) || !isset($b_item['quantity'])) continue;
                    $b_product_id = intval($b_item['id']);
                    $b_product = wc_get_product($b_product_id);
                    $b_name = $b_product ? $b_product->get_name() : ($b_item['name'] ?? 'Buffet Item');
                    $newly_added_items[] = array(
                        'product_id' => $b_product_id,
                        'name' => $b_name,
                        'quantity' => intval($b_item['quantity']),
                        'notes' => isset($b_item['notes']) ? sanitize_text_field($b_item['notes']) : '',
                        'is_buffet' => true
                    );
                }
                ruiyi_debug_log("[create_order] 🍽️ 自助餐商品 " . count($buffet_items) . " 个已记录到厨房打印队列");
            }
        }

        // 🔥🔥🔥 关键修复：如果是合并到现有订单，先获取现有产品列表
        // 防止重复添加相同的产品（使用产品ID+单价作为唯一键，允许同产品不同价格）
        $existing_products_in_order = array();
        if ($is_merging_to_existing) {
            ruiyi_debug_log("[create_order-DEBUG] 📋 开始检查现有订单 #{$order->get_id()} 中的产品:");
            foreach ($order->get_items() as $item_id => $order_item) {
                $existing_product_id = $order_item->get_product_id();
                $existing_qty = $order_item->get_quantity();
                // 🔥🔥🔥 修复：使用 get_subtotal()（不含税）而非 get_total()（含税）
                // 这样才能与新添加产品的价格正确匹配
                $existing_unit_price = $existing_qty > 0 ? round($order_item->get_subtotal() / $existing_qty, 2) : 0;
                // 🔥 使用 product_id + 单价 + 自定义名称 作为唯一键，允许同产品不同价格/名称共存
                $existing_custom_name = wc_get_order_item_meta($item_id, '_has_custom_name', true) === 'yes' ? $order_item->get_name() : '';
                $existing_item_notes = wc_get_order_item_meta($item_id, '_item_notes', true) ?: '';
                $unique_key = $existing_product_id . '_' . $existing_unit_price . ($existing_custom_name ? '_cn' . $existing_custom_name : '') . ($existing_item_notes ? '_n' . $existing_item_notes : '');
                $existing_products_in_order[$unique_key] = array(
                    'item_id' => $item_id,
                    'product_id' => $existing_product_id,
                    'quantity' => $existing_qty,
                    'subtotal' => $order_item->get_subtotal(),
                    'unit_price' => $existing_unit_price
                );
                ruiyi_debug_log("[create_order-DEBUG]   - 订单项: product_id={$existing_product_id} 单价(不含税)€{$existing_unit_price} 数量{$existing_qty} key={$unique_key}");
            }
            ruiyi_debug_log("[create_order-DEBUG] 📋 现有产品keys: " . implode(', ', array_keys($existing_products_in_order)));
        } else {
            ruiyi_debug_log("[create_order-DEBUG] 📋 不是合并模式，跳过现有产品检查");
        }

        // Solo procesar productos regulares si existen
        if ($has_regular_items && !empty($cart)) {
            foreach ($cart as $item) {
                // Validar campos necesarios
                if (!isset($item['id']) || !isset($item['quantity'])) {
                    continue;
                }

                $product_id = intval($item['id']);

                // 🍽️ 跳过自助餐产品（不添加到WC订单，只记录到厨房打印）
                if (isset($item['is_buffet']) && $item['is_buffet']) {
                    $b_product = wc_get_product($product_id);
                    $newly_added_items[] = array(
                        'product_id' => $product_id,
                        'name' => $b_product ? $b_product->get_name() : ($item['name'] ?? 'Buffet Item'),
                        'quantity' => intval($item['quantity']),
                        'notes' => isset($item['notes']) ? sanitize_text_field($item['notes']) : '',
                        'is_buffet' => true
                    );
                    ruiyi_debug_log("[create_order] 🍽️ 跳过自助餐产品 (cart内): product_id={$product_id}");
                    continue;
                }
                $quantity = intval($item['quantity']);

                if ($quantity <= 0) {
                    continue;
                }

                $product = wc_get_product($product_id);
                if (!$product) {
                    // Registrar error pero continuar con otros productos
                    ruiyi_debug_log("RUIYI POS: Producto no encontrado ID: {$product_id}");
                    continue;
                }

                // 🔥🔥🔥 提前计算商品价格，用于重复检测
                // 优先级：customPrice > price (Varios/前端传递) > zone_price > 产品原价
                $has_custom_price = isset($item['customPrice']) && !is_null($item['customPrice']);
                $custom_price = null;
                $zone_price = null;

                if ($has_custom_price) {
                    $custom_price = floatval($item['customPrice']);
                } else {
                    // 检查是否为 Varios 商品或有前端传递的价格
                    $is_varios = isset($item['isVarios']) && $item['isVarios'] === true;
                    if ($is_varios && isset($item['price'])) {
                        $custom_price = floatval($item['price']);
                    }
                }

                // 🔥 分区价格处理
                $zone_category_id = isset($item['zoneCategoryId']) ? intval($item['zoneCategoryId']) : null;
                if ($custom_price === null && $zone_category_id) {
                    $zone_prices = get_post_meta($product_id, '_ruiyi_zone_prices', true);
                    if (is_array($zone_prices) && !empty($zone_prices)) {
                        $zone_key = 'category_' . $zone_category_id;
                        if (isset($zone_prices[$zone_key]) && $zone_prices[$zone_key] !== '') {
                            $zone_price = floatval($zone_prices[$zone_key]);
                            ruiyi_debug_log("POS: 商品 #{$product_id} 使用分区价格 €{$zone_price}（分区ID: {$zone_category_id}，基础价格 €" . $product->get_price() . "）");
                        }
                    }
                }

                // 确定最终使用的价格
                // 优先级：customPrice > zone_price (DB) > 前端price (分区回退) > 产品原价
                $final_price = null;
                $price_type = 'regular'; // 价格类型标记

                if ($custom_price !== null && $custom_price >= 0) {
                    $final_price = $custom_price;
                    $price_type = 'custom';
                } elseif ($zone_price !== null && $zone_price >= 0) {
                    $final_price = $zone_price;
                    $price_type = 'zone';
                } elseif ($zone_category_id && isset($item['price'])) {
                    // 🔥🔥🔥 【2026-03-10 关键修复】分区价格回退机制
                    // 当 customPrice 未设置且 DB 分区价格查询失败时，
                    // 使用前端传递的 price（已经是分区价格）作为最终价格
                    $frontend_price = floatval($item['price']);
                    $product_regular_price = floatval($product->get_price());
                    if ($frontend_price > 0 && abs($frontend_price - $product_regular_price) > 0.001) {
                        $final_price = $frontend_price;
                        $price_type = 'zone_frontend';
                        ruiyi_debug_log("POS: 🔥 商品 #{$product_id} 分区DB查询失败，使用前端价格 €{$frontend_price}（分区ID: {$zone_category_id}，产品原价 €{$product_regular_price}）");
                    }
                }

                // 🔥🔥🔥 【关键修复】计算当前商品的单价，用于重复检测
                // 使用 product_id + 单价 + 自定义名称 + 备注 作为唯一键
                $item_unit_price = ($final_price !== null) ? round($final_price, 2) : round(floatval($product->get_price()), 2);
                $item_custom_name = isset($item['customName']) && !empty($item['customName']) ? sanitize_text_field($item['customName']) : '';
                $item_notes_key = isset($item['notes']) && !empty($item['notes']) ? sanitize_text_field($item['notes']) : '';
                $unique_key = $product_id . '_' . $item_unit_price . ($item_custom_name ? '_cn' . $item_custom_name : '') . ($item_notes_key ? '_n' . $item_notes_key : '');

                // 🔥🔥🔥 调试日志：记录重复检测过程
                ruiyi_debug_log("[create_order-DEBUG] 🔍 检查产品 #{$product_id} 价格€{$item_unit_price} unique_key={$unique_key}");
                ruiyi_debug_log("[create_order-DEBUG]   - is_merging_to_existing: " . ($is_merging_to_existing ? 'true' : 'false'));
                ruiyi_debug_log("[create_order-DEBUG]   - existing_products_in_order keys: " . implode(', ', array_keys($existing_products_in_order)));
                ruiyi_debug_log("[create_order-DEBUG]   - unique_key存在: " . (isset($existing_products_in_order[$unique_key]) ? 'YES' : 'NO'));

                // 🔥🔥🔥 检查产品是否已存在于订单中（相同产品+相同价格）
                // 🔥🔥🔥 修复：如果已存在，增加数量而不是跳过
                if ($is_merging_to_existing && isset($existing_products_in_order[$unique_key])) {
                    $existing_item_info = $existing_products_in_order[$unique_key];
                    $existing_item_id = $existing_item_info['item_id'];
                    $existing_qty = $existing_item_info['quantity'];
                    $new_qty = $existing_qty + $quantity;

                    // 获取订单项并更新数量
                    $order_item = $order->get_item($existing_item_id);
                    if ($order_item) {
                        $order_item->set_quantity($new_qty);
                        // 重新计算总价
                        $unit_price = $existing_item_info['unit_price'];
                        $order_item->set_subtotal($unit_price * $new_qty);
                        $order_item->set_total($unit_price * $new_qty);
                        $order_item->save();

                        ruiyi_debug_log("[create_order-DEBUG] ✅ 已更新现有产品 #{$product_id} 数量: {$existing_qty} → {$new_qty}（单价 €{$unit_price}）");

                        // 更新existing_products_in_order中的数量，防止后续重复处理
                        $existing_products_in_order[$unique_key]['quantity'] = $new_qty;
                        $existing_products_in_order[$unique_key]['subtotal'] = $unit_price * $new_qty;

                        // 🔥 保存产品备注（如果有）
                        $item_notes = isset($item['notes']) ? sanitize_text_field($item['notes']) : '';
                        if (!empty($item_notes)) {
                            wc_update_order_item_meta($existing_item_id, '_item_notes', $item_notes);
                            ruiyi_debug_log("[create_order] 📝 保存产品备注 (追加): {$item_notes}");
                        }

                        // 🔥 【2026-01-21 修复】记录追加的数量到 newly_added_items，确保厨房小票只打印新增部分
                        // 🍽️ 开台商品(is_buffet_opening)不加入打印队列，避免客户点餐时误打印
                        $is_buffet_opening_item = !empty($item['is_buffet_opening']);
                        $item_name = $order_item->get_name();
                        if (!$is_buffet_opening_item) {
                            $newly_added_items[] = array(
                                'item_id' => $existing_item_id,
                                'product_id' => $product_id,
                                'name' => $item_name,
                                'quantity' => $quantity,  // 只记录新追加的数量，不是总数量
                                'price' => $unit_price,
                                'notes' => $item_notes
                            );
                            ruiyi_debug_log("[create_order] 📝 记录追加到已存在商品: {$item_name} x{$quantity}（总数量: {$new_qty}）");
                        } else {
                            ruiyi_debug_log("[create_order] 🍽️ 开台商品跳过打印队列: {$item_name} x{$quantity}");
                        }
                    }

                    $productos_validos = true;
                    continue; // 已更新，不需要再添加新行
                }

                ruiyi_debug_log("[create_order-DEBUG] ✅ 将添加产品 #{$product_id} 价格€{$item_unit_price}");

                // Obtener la tasa de impuesto del producto usando nuestra función
                $tax_rate = isset($item['taxRate']) ? floatval($item['taxRate']) : ruiyi_get_product_tax_rate($product);

                // 如果有自定义价格或分区价格，使用该价格
                if ($final_price !== null) {
                    // 使用计算后的价格添加到订单
                    $item_id = $order->add_product($product, $quantity, [
                        'subtotal' => $final_price * $quantity,
                        'total' => $final_price * $quantity
                    ]);

                    if ($item_id) {
                        // 🔥 添加 meta 标记价格类型
                        if ($price_type === 'custom') {
                            wc_update_order_item_meta($item_id, '_has_custom_price', 'yes');
                            wc_update_order_item_meta($item_id, '_custom_price', $final_price);
                        } elseif ($price_type === 'zone' || $price_type === 'zone_frontend') {
                            wc_update_order_item_meta($item_id, '_has_zone_price', 'yes');
                            wc_update_order_item_meta($item_id, '_zone_price', $final_price);
                            wc_update_order_item_meta($item_id, '_zone_category_id', $zone_category_id);
                        }

                        // 如果是 Varios 商品，也保留原有的 meta 标记（向后兼容）
                        if (isset($item['isVarios']) && $item['isVarios'] === true) {
                            wc_update_order_item_meta($item_id, '_is_varios_item', 'yes');
                            wc_update_order_item_meta($item_id, '_varios_custom_price', $final_price);
                        }

                        // 🔥🔥🔥 关键修复：如果有自定义名称（customName），更新订单项名称
                        if (isset($item['customName']) && !empty($item['customName'])) {
                            $custom_name = sanitize_text_field($item['customName']);
                            $order_item = $order->get_item($item_id);
                            if ($order_item) {
                                $order_item->set_name($custom_name);
                                $order_item->save();
                                wc_update_order_item_meta($item_id, '_has_custom_name', 'yes');
                                wc_update_order_item_meta($item_id, '_original_name', $product->get_name());
                                ruiyi_debug_log("POS: 商品 #{$product_id} 使用自定义名称 '{$custom_name}'（原名: " . $product->get_name() . "）");
                            }
                        }

                        // 🔥 记录日志
                        if ($price_type === 'custom') {
                            ruiyi_debug_log("POS: 商品 #{$product_id} 使用自定义价格 €{$final_price}（原价 €" . $product->get_price() . "）");
                        }

                        // 🔥 保存产品备注（如果有）
                        $item_notes = isset($item['notes']) ? sanitize_text_field($item['notes']) : '';
                        if (!empty($item_notes)) {
                            wc_update_order_item_meta($item_id, '_item_notes', $item_notes);
                            ruiyi_debug_log("[create_order] 📝 保存产品备注 (自定义/分区价格): {$item_notes}");
                        }

                        // 🔥 保存配料标记（如果是配料）
                        if (!empty($item['is_supplement'])) {
                            wc_update_order_item_meta($item_id, '_is_supplement', 'yes');
                            if (!empty($item['parent_item_name'])) {
                                wc_update_order_item_meta($item_id, '_parent_item_name', sanitize_text_field($item['parent_item_name']));
                            }
                        }

                        $productos_validos = true;

                        // 🔥 【2026-01-21 新增】记录新添加的商品用于厨房打印
                        // 🍽️ 开台商品(is_buffet_opening)不加入打印队列
                        if (empty($item['is_buffet_opening'])) {
                            $item_name = isset($item['customName']) && !empty($item['customName'])
                                ? sanitize_text_field($item['customName'])
                                : $product->get_name();
                            $newly_added_items[] = array(
                                'item_id' => $item_id,
                                'product_id' => $product_id,
                                'name' => $item_name,
                                'quantity' => $quantity,
                                'price' => $final_price,
                                'notes' => $item_notes,
                                'is_supplement' => !empty($item['is_supplement']),
                                'parent_item_name' => isset($item['parent_item_name']) ? sanitize_text_field($item['parent_item_name']) : ''
                            );
                        } else {
                            wc_update_order_item_meta($item_id, '_is_buffet_opening', 'yes');
                            ruiyi_debug_log("[create_order] 🍽️ 开台商品跳过打印队列: " . $product->get_name() . " x{$quantity} €{$final_price}");
                        }
                    }
                } else {
                    // 普通产品：使用产品原价
                    $item_id = $order->add_product($product, $quantity);
                    if ($item_id) {
                        // 🔥🔥🔥 关键修复：如果有自定义名称（customName），更新订单项名称
                        if (isset($item['customName']) && !empty($item['customName'])) {
                            $custom_name = sanitize_text_field($item['customName']);
                            $order_item = $order->get_item($item_id);
                            if ($order_item) {
                                $order_item->set_name($custom_name);
                                $order_item->save();
                                wc_update_order_item_meta($item_id, '_has_custom_name', 'yes');
                                wc_update_order_item_meta($item_id, '_original_name', $product->get_name());
                                ruiyi_debug_log("POS: 商品 #{$product_id} 使用自定义名称 '{$custom_name}'（原名: " . $product->get_name() . "）");
                            }
                        }

                        // 🔥 保存产品备注（如果有）
                        $item_notes = isset($item['notes']) ? sanitize_text_field($item['notes']) : '';
                        if (!empty($item_notes)) {
                            wc_update_order_item_meta($item_id, '_item_notes', $item_notes);
                            ruiyi_debug_log("[create_order] 📝 保存产品备注 (普通价格): {$item_notes}");
                        }

                        // 🔥 保存配料标记（如果是配料）
                        if (!empty($item['is_supplement'])) {
                            wc_update_order_item_meta($item_id, '_is_supplement', 'yes');
                            if (!empty($item['parent_item_name'])) {
                                wc_update_order_item_meta($item_id, '_parent_item_name', sanitize_text_field($item['parent_item_name']));
                            }
                        }

                        $productos_validos = true;

                        // 🔥 【2026-01-21 新增】记录新添加的商品用于厨房打印
                        // 🍽️ 开台商品(is_buffet_opening)不加入打印队列
                        if (empty($item['is_buffet_opening'])) {
                            $item_name = isset($item['customName']) && !empty($item['customName'])
                                ? sanitize_text_field($item['customName'])
                                : $product->get_name();
                            $newly_added_items[] = array(
                                'item_id' => $item_id,
                                'product_id' => $product_id,
                                'name' => $item_name,
                                'quantity' => $quantity,
                                'price' => $product->get_price(),
                                'notes' => $item_notes,
                                'is_supplement' => !empty($item['is_supplement']),
                                'parent_item_name' => isset($item['parent_item_name']) ? sanitize_text_field($item['parent_item_name']) : ''
                            );
                        } else {
                            wc_update_order_item_meta($item_id, '_is_buffet_opening', 'yes');
                            ruiyi_debug_log("[create_order] 🍽️ 开台商品跳过打印队列: " . $product->get_name() . " x{$quantity}");
                        }
                    }
                }
            }
        }

        // 处理积分产品兑换
        $points_products_processed = false;
        if ($has_points_items && !empty($points_items)) {
            foreach ($points_items as $points_item) {
                if (!isset($points_item['id']) || !isset($points_item['quantity']) || !isset($points_item['user_id'])) {
                    continue;
                }
                
                $product_id = intval($points_item['id']);
                $quantity = intval($points_item['quantity']);
                $user_id_points = intval($points_item['user_id']);
                $points_price = isset($points_item['points_price']) ? intval($points_item['points_price']) : 0;
                $total_points = $points_price * $quantity;
                
                if ($quantity <= 0 || $total_points <= 0) {
                    continue;
                }
                
                // 验证产品是否为积分产品
                $is_points_product = get_post_meta($product_id, '_is_points_product', true);
                if (!$is_points_product) {
                    continue;
                }
                
                // 检查用户积分余额
                $site_id = get_current_blog_id();
                $user_points = ruiyi_get_user_points($user_id_points, $site_id);
                if ($user_points < $total_points) {
                    $order->delete(true);
                    wp_send_json_error(['message' => __('❌ 积分余额不足，无法兑换产品。', 'ruiyi-pos')]);
                    return;
                }
                
                // 扣除积分（不保存历史记录）
                $product = wc_get_product($product_id);
                $description = sprintf("兑换商品: %s x%d (订单 #%d)", $product->get_name(), $quantity, $order->get_id());
                $result = ruiyi_deduct_user_points($user_id_points, $total_points, $site_id, $description, false);
                
                if (!$result) {
                    $order->delete(true);
                    wp_send_json_error(['message' => __('❌ 积分扣除失败。', 'ruiyi-pos')]);
                    return;
                }
                
                // 将积分产品添加到订单（价格为0）
                $item_id = $order->add_product($product, $quantity, array(
                    'subtotal' => 0,
                    'total' => 0
                ));
                
                if ($item_id) {
                    // 添加积分产品元数据
                    $order->add_meta_data("_points_product_{$item_id}", array(
                        'user_id' => $user_id_points,
                        'points_used' => $total_points,
                        'points_per_item' => $points_price
                    ));
                    $productos_validos = true;
                    $points_products_processed = true;
                }
            }
        }

        // 🔥 将自助餐商品添加为WC订单行项（价格为0），使其可被厨房打印API检测到
        if ($has_buffet_items) {
            $buffet_items_json = stripslashes($_POST['buffet_items']);
            $buffet_items_parsed = json_decode($buffet_items_json, true);
            if (is_array($buffet_items_parsed)) {
                foreach ($buffet_items_parsed as $b_item) {
                    if (!isset($b_item['id']) || !isset($b_item['quantity'])) continue;
                    $b_product_id = intval($b_item['id']);
                    $b_quantity = intval($b_item['quantity']);
                    $b_product = wc_get_product($b_product_id);
                    if (!$b_product) continue;

                    // 检查是否已存在于订单中（合并模式）
                    if ($is_merging_to_existing) {
                        $found_existing = false;
                        foreach ($order->get_items() as $ex_id => $ex_item) {
                            if ($ex_item->get_product_id() === $b_product_id) {
                                $ex_item->set_quantity($ex_item->get_quantity() + $b_quantity);
                                $ex_item->save();
                                $found_existing = true;
                                ruiyi_debug_log("[create_order] 🍽️ 自助餐商品合并数量: " . $b_product->get_name() . " +{$b_quantity}");
                                break;
                            }
                        }
                        if ($found_existing) continue;
                    }

                    // 添加为新行项（价格为0）
                    $b_item_id = $order->add_product($b_product, $b_quantity);
                    if ($b_item_id) {
                        $b_order_item = $order->get_item($b_item_id);
                        if ($b_order_item) {
                            $b_order_item->set_subtotal(0);
                            $b_order_item->set_total(0);
                            $b_order_item->save();
                        }
                        // 保存产品备注
                        $b_notes = isset($b_item['notes']) ? sanitize_text_field($b_item['notes']) : '';
                        if (!empty($b_notes)) {
                            wc_update_order_item_meta($b_item_id, '_item_notes', $b_notes);
                        }
                        ruiyi_debug_log("[create_order] 🍽️ 自助餐商品已添加到订单: " . $b_product->get_name() . " x{$b_quantity} €0");
                    }
                }
                $productos_validos = true; // 有自助餐产品也算有效
            }
        }

        // 🔥🔥🔥 调试日志：记录商品处理结果
        ruiyi_debug_log("[create_order-DEBUG] 📊 商品处理完成:");
        ruiyi_debug_log("[create_order-DEBUG]   - is_merging_to_existing: " . ($is_merging_to_existing ? 'true' : 'false'));
        ruiyi_debug_log("[create_order-DEBUG]   - productos_validos: " . ($productos_validos ? 'true' : 'false'));
        ruiyi_debug_log("[create_order-DEBUG]   - 订单ID: " . $order->get_id());
        ruiyi_debug_log("[create_order-DEBUG]   - 当前订单项数量: " . count($order->get_items()));

        // 🔥 在应用折扣/费用之前先计算订单总额，确保WC内部小计正确
        // 这样后续的折扣计算基于正确的商品总价（排除0元自助餐/免费产品的影响）
        $order->calculate_totals();

        // Check for pending points transactions and apply them to the order
        $pending_points_transaction = get_option('ruiyi_pending_points_transaction', false);
        $points_discount_applied = false;
        
        if ($pending_points_transaction && is_array($pending_points_transaction)) {
            $points_discount = floatval($pending_points_transaction['discount_amount']);
            $points_used = intval($pending_points_transaction['points_used']);
            $user_id = intval($pending_points_transaction['user_id']);
            
            if ($points_discount > 0) {
                // Create a new fee item for points discount
                $points_fee = new WC_Order_Item_Fee();
                $points_fee->set_name(sprintf(__('Descuento por Puntos (%d pts)', 'ruiyi-pos'), $points_used));
                $points_fee->set_amount(-$points_discount);
                $points_fee->set_tax_class('');
                $points_fee->set_tax_status('none');
                $points_fee->set_total(-$points_discount);
                
                // Add the points fee item to the order
                $order->add_item($points_fee);
                
                // Store points transaction info in order meta
                $order->update_meta_data('_points_discount_used', $points_used);
                $order->update_meta_data('_points_discount_amount', $points_discount);
                $order->update_meta_data('_points_discount_user_id', $user_id);
                
                $points_discount_applied = true;
                
                // Log the points discount application
                ruiyi_debug_log("RUIYI POS: Applied points discount to new order - User ID: {$user_id}, Points: {$points_used}, Discount: €{$points_discount}");
            }
        }
        
        // Aplicar descuento regular solo si no se aplicó descuento por puntos
        if (!$points_discount_applied && $discount_amount > 0) {
            // Create a new fee item
            $fee = new WC_Order_Item_Fee();

            $fee->set_name(__( 'Descuento POS', 'ruiyi-pos' )); // Fee name
            $fee->set_amount(-$discount_amount); // Fee amount (negative for discount)
            $fee->set_tax_class(''); // Tax class. '' for non-taxable.
            $fee->set_tax_status('none'); // Tax status ('taxable' or 'none')
            $fee->set_total(-$discount_amount); // The total for the fee (after tax if any)

            // Add the fee item to the order
            $order->add_item($fee);
        }

        // Aplicar propina
        if ($tip_amount > 0) {
            $order->add_fee(__('Propina', 'ruiyi-pos'), $tip_amount);
        }

        // Agregar nota
        if (!empty($note)) {
            $order->add_order_note($note);
        }

        // Guardar número de mesa (normalize as string for consistent comparison)
        if (!empty($table_number)) {
            // 🔥🔥🔥 【2026-01-19 修复】保存完整桌号（包含前缀），而不是只保存数字
            // 这样可以区分 "DOMICILIO3" 和 "COMEDOR3" 等不同区域的桌位
            // 前缀对于订单合并逻辑非常重要，不能丢失
            $full_table_number = strtoupper(trim((string)$table_number));
            $order->update_meta_data('_table_number', $full_table_number);

            // Log the table number being saved for debugging
            ruiyi_debug_log("[RUIYI_POS] Saving table number for order #{$order->get_id()}: '{$full_table_number}'");
        }
        
        // 保存订单类型
        $order->update_meta_data('_order_type', $order_type);
        // 标记订单来源为收银系统
        $order->update_meta_data('_ruiyi_order_source', '收银系统');
        ruiyi_debug_log("POS: 保存订单类型元数据 (orderID: ".$order->get_id()."): " . $order_type);

        // 🔥 保存订单备注（使用 update_post_meta 确保立即持久化）
        $order_notes = isset($_POST['order_notes']) ? sanitize_textarea_field($_POST['order_notes']) : '';
        if (!empty($order_notes)) {
            $order->update_meta_data('_order_notes', $order_notes);
            update_post_meta($order->get_id(), '_order_notes', $order_notes); // 🔥 立即写入DB
            $order->add_order_note('客户备注: ' . $order_notes);
            ruiyi_debug_log("POS: 保存订单备注 (orderID: ".$order->get_id()."): " . $order_notes);
        }
        
        // 🔥 处理客户信息（外卖和桌位订单都支持）
        ruiyi_debug_log("🔍 [客户信息调试] 开始处理客户信息保存...");
        ruiyi_debug_log("🔍 [客户信息调试] - order_type: {$order_type}");
        ruiyi_debug_log("🔍 [客户信息调试] - customer_info是否存在: " . ($customer_info ? 'YES' : 'NO'));
        ruiyi_debug_log("🔍 [客户信息调试] - customer_info是否为数组: " . (is_array($customer_info) ? 'YES' : 'NO'));

        if ($customer_info) {
            ruiyi_debug_log("🔍 [客户信息调试] - customer_info内容: " . json_encode($customer_info, JSON_UNESCAPED_UNICODE));
        }

        if ($customer_info && is_array($customer_info)) {
            ruiyi_debug_log("🔍 [客户信息调试] ✅ 条件满足，开始保存客户信息到订单meta...");

            // 🔥 【2026-03-12 修复】先无条件保存客户信息到订单meta
            // 即使客户管理系统(ruiyi_save_customer_info)因缺少姓名等字段而失败，
            // 电话号码和地址等关键信息仍应保存到WC订单中，确保外送桌位信息不丢失
            $order->update_meta_data('_customer_name', $customer_info['name'] ?? '');
            $order->update_meta_data('_customer_phone', $customer_info['phone'] ?? '');
            $order->update_meta_data('_customer_business_name', $customer_info['business_name'] ?? '');
            $order->update_meta_data('_customer_cif_nif', $customer_info['cif_nif'] ?? '');
            $order->update_meta_data('_customer_address', $customer_info['address'] ?? '');
            $order->update_meta_data('_customer_postal_code', $customer_info['postal_code'] ?? '');
            $order->update_meta_data('_customer_email', $customer_info['email'] ?? '');
            $order->update_meta_data('_customer_notes', $customer_info['notes'] ?? '');

            ruiyi_debug_log("🔍 [客户信息调试] ✅ 客户信息已保存到订单 #".$order->get_id()." Meta字段");
            ruiyi_debug_log("🔍 [客户信息调试] - 客户电话: " . ($customer_info['phone'] ?? ''));
            ruiyi_debug_log("🔍 [客户信息调试] - 客户地址: " . ($customer_info['address'] ?? ''));

            // 尝试保存到客户管理系统（可能因缺少姓名等字段而失败，不影响订单meta）
            $customer_id = ruiyi_save_customer_info($customer_info);

            if ($customer_id) {
                $order->update_meta_data('_customer_id', $customer_id);
                ruiyi_debug_log("🔍 [客户信息调试] ✅ 客户管理系统保存成功，客户ID: $customer_id");
            } else {
                ruiyi_debug_log("🔍 [客户信息调试] ⚠️ 客户管理系统保存失败（可能缺少姓名），但订单meta已保存");
            }
        } else {
            ruiyi_debug_log("🔍 [客户信息调试] ⚠️ 客户信息为空或格式错误，跳过保存");
            if (!$customer_info) {
                ruiyi_debug_log("🔍 [客户信息调试] - 原因: customer_info为NULL或false");
            } elseif (!is_array($customer_info)) {
                ruiyi_debug_log("🔍 [客户信息调试] - 原因: customer_info不是数组");
            }
        }

        // Configurar método de pago (normalizar valores comunes)
        $valid_payment_methods = ['cod', 'bacs', 'cheque', 'cash', 'card', 'wallet'];
        $normalized_method = strtolower($payment_method);
        
        // Normalizar nombres comunes de métodos de pago
        if ($normalized_method === 'cash' || $normalized_method === 'efectivo') {
            $normalized_method = 'cod';
            $payment_title = 'Efectivo';
        } elseif ($normalized_method === 'card' || $normalized_method === 'tarjeta' || $normalized_method === 'debit card') {
            $normalized_method = 'bacs';
            $payment_title = 'Tarjeta';
        } elseif ($normalized_method === 'bizum') {
            $normalized_method = 'bizum';
            $payment_title = 'Bizum/Transferencia';
        } elseif ($normalized_method === 'wallet' || $normalized_method === 'e-wallet' || $normalized_method === 'monedero') {
            $normalized_method = 'cheque';
            $payment_title = 'Monedero Electrónico';
        } else {
            $payment_title = ucfirst($payment_method);
        }
        
        // Establecer método de pago
        $order->set_payment_method($normalized_method);
        $order->set_payment_method_title($payment_title);

        // Finalizar orden
        // 🔥🔥🔥 关键修复：在计算总额前刷新订单对象，确保包含最新的订单项数据
        // 这解决了更新订单项后 calculate_totals() 使用旧数据的问题
        if ($is_merging_to_existing) {
            // 重新从数据库读取订单，确保获取所有最新的订单项
            $order = wc_get_order($order->get_id());
            ruiyi_debug_log("[create_order-DEBUG] 🔄 已刷新订单对象 #{$order->get_id()}");
        }

        $order->calculate_totals();

        // 🔥 Aplicar Cheque Restaurante DESPUÉS de calculate_totals()
        ruiyi_debug_log("🎫 [抵扣券调试] ========== 开始检查抵扣券(calculate_totals之后) ==========");
        ruiyi_debug_log("🎫 [抵扣券调试] POST中是否有cheque_restaurante_amount: " . (isset($_POST['cheque_restaurante_amount']) ? 'YES' : 'NO'));
        if (isset($_POST['cheque_restaurante_amount'])) {
            ruiyi_debug_log("🎫 [抵扣券调试] 原始值: " . $_POST['cheque_restaurante_amount'] . ", float值: " . floatval($_POST['cheque_restaurante_amount']));
        }

        if (isset($_POST['cheque_restaurante_amount']) && floatval($_POST['cheque_restaurante_amount']) > 0) {
            $cheque_restaurante = floatval($_POST['cheque_restaurante_amount']);

            // 记录添加fee之前的订单总额
            $before_total = $order->get_total();
            ruiyi_debug_log("🎫 [抵扣券调试] 添加fee之前的订单总额: €{$before_total}");

            // 使用新的WC_Order_Item_Fee对象
            $fee = new WC_Order_Item_Fee();
            $fee->set_name(__('Cheque Restaurante', 'ruiyi-pos'));
            $fee->set_amount(-$cheque_restaurante);
            $fee->set_total(-$cheque_restaurante);
            $order->add_item($fee);

            ruiyi_debug_log("🎫 [抵扣券调试] ✅ 已添加抵扣券fee对象,金额: -€{$cheque_restaurante}");

            // 重新计算订单总额
            $order->calculate_totals();
            $after_total = $order->get_total();
            ruiyi_debug_log("🎫 [抵扣券调试] 重新计算后的订单总额: €{$after_total}");

            // 保存抵扣券元数据
            $order->update_meta_data('_cheque_restaurante_amount', $cheque_restaurante);
            ruiyi_debug_log("🎫 [抵扣券调试] ✅ 已保存抵扣券元数据");
        } else {
            ruiyi_debug_log("🎫 [抵扣券调试] ❌ 未添加抵扣券（条件不满足）");
        }
        ruiyi_debug_log("🎫 [抵扣券调试] ========== 抵扣券检查结束 ==========");

        // 🔥 调试：记录最终的订单总额
        $final_total = $order->get_total();
        ruiyi_debug_log("🎫 [订单总额调试] 最终订单总额: €{$final_total}");
        ruiyi_debug_log("🎫 [订单总额调试] 订单ID: " . $order->get_id());

        // 🔥 调试:列出所有费用项
        $fees = $order->get_fees();
        ruiyi_debug_log("🎫 [订单总额调试] 费用项数量: " . count($fees));
        foreach ($fees as $fee_id => $fee) {
            ruiyi_debug_log("🎫 [订单总额调试] 费用项: " . $fee->get_name() . " = €" . $fee->get_total());
        }

        // 🔥 关键修复：在更新订单状态之前先保存支付详情
        // 因为 update_status('completed') 会触发 woocommerce_order_status_completed hook
        // 该hook会调用日结单记录函数，此时必须确保支付元数据已经保存
        // 优先级：混合支付 > 刷卡支付 > 现金支付 > 默认推断

        // 🔥 关键修复：先解析金额为浮点数，避免空字符串被isset误判
        $create_order_cash_amount = isset($_POST['cash_amount']) ? floatval($_POST['cash_amount']) : 0;
        $create_order_card_amount = isset($_POST['card_amount']) ? floatval($_POST['card_amount']) : 0;

        // 🔥 关键修复：只有当现金和刷卡金额都大于0时才是真正的混合支付
        if ($create_order_cash_amount > 0 && $create_order_card_amount > 0) {
            // ✓ 混合支付（现金和刷卡金额都大于0）
            $order->update_meta_data('_payment_method_detail', 'mixed');
            $order->update_meta_data('_cash_amount', round($create_order_cash_amount, 2));
            $order->update_meta_data('_card_amount', round($create_order_card_amount, 2));
            ruiyi_debug_log("POS: 保存混合支付详情 - 现金: €" . $create_order_cash_amount . ", 刷卡: €" . $create_order_card_amount);
        } elseif ($normalized_method === 'bizum' || strtolower($payment_method) === 'bizum') {
            // ✓ Bizum/转账支付
            $bizum_amount = isset($_POST['bizum_amount']) ? round(floatval($_POST['bizum_amount']), 2) : round($order->get_total(), 2);
            $order->update_meta_data('_payment_method_detail', 'bizum');
            $order->update_meta_data('_bizum_amount', $bizum_amount);
            $order->delete_meta_data('_cash_amount');
            $order->delete_meta_data('_card_amount');
            $order->delete_meta_data('_received_amount');
            $order->delete_meta_data('_change_amount');
            ruiyi_debug_log("POS: 保存Bizum支付详情 - 金额: €" . $bizum_amount);
        } elseif ($normalized_method === 'bacs' || strtolower($payment_method) === 'card' || strtolower($payment_method) === 'tarjeta') {
            // ✓ 其次判断刷卡支付（payment_method 为 card/bacs/tarjeta）
            // 关键：这个判断在 received_amount 检查之前，避免误判
            $order->update_meta_data('_payment_method_detail', 'card');
            $order->update_meta_data('_card_amount', $order->get_total());
            // 🔥 修复：清除现金支付的元数据，避免被误判为混合支付
            $order->delete_meta_data('_cash_amount');
            $order->delete_meta_data('_received_amount');
            $order->delete_meta_data('_change_amount');
            ruiyi_debug_log("POS: 保存刷卡支付详情 - 金额: " . $order->get_total() . ", normalized_method: " . $normalized_method . ", payment_method: " . $payment_method);
        } elseif (isset($_POST['received_amount']) && floatval($_POST['received_amount']) > 0) {
            // ✓ 现金支付（有 received_amount，但不是混合支付，也不是刷卡）
            $order->update_meta_data('_payment_method_detail', 'cash');
            $order->update_meta_data('_cash_amount', $order->get_total());
            $order->update_meta_data('_received_amount', floatval($_POST['received_amount']));
            $order->update_meta_data('_change_amount', floatval($_POST['change_amount'] ?? 0));
            ruiyi_debug_log("POS: 保存现金支付详情 - 实付: " . $order->get_total() . ", 收款: " . $_POST['received_amount'] . ", 找零: " . ($_POST['change_amount'] ?? 0));
        } elseif ($normalized_method === 'cod' || strtolower($payment_method) === 'cash' || strtolower($payment_method) === 'efectivo') {
            // ✓ 现金支付的备选判断（基于 payment_method）
            $order->update_meta_data('_payment_method_detail', 'cash');
            $order->update_meta_data('_cash_amount', $order->get_total());
            ruiyi_debug_log("POS: 保存支付详情（现金-默认推断） - 方式: " . $normalized_method . ", payment_method: " . $payment_method);
        } else {
            // 其他情况：根据normalized_method推断
            if ($normalized_method === 'cod') {
                $order->update_meta_data('_payment_method_detail', 'cash');
                $order->update_meta_data('_cash_amount', $order->get_total());
            } elseif ($normalized_method === 'bacs') {
                $order->update_meta_data('_payment_method_detail', 'card');
                $order->update_meta_data('_card_amount', $order->get_total());
                // 🔥 修复：清除现金支付的元数据
                $order->delete_meta_data('_cash_amount');
                $order->delete_meta_data('_received_amount');
                $order->delete_meta_data('_change_amount');
            } else {
                // 未知支付方式，默认为现金
                $order->update_meta_data('_payment_method_detail', 'cash');
                $order->update_meta_data('_cash_amount', $order->get_total());
            }
            ruiyi_debug_log("POS: 保存支付详情（其他-默认推断） - 方式: " . $normalized_method . ", payment_method: " . $payment_method);
        }

        // 🔥 保存餐厅抵扣票信息 (Cheque Restaurante)
        if (isset($_POST['cheque_restaurante_amount']) && floatval($_POST['cheque_restaurante_amount']) > 0) {
            $cheque_restaurante = floatval($_POST['cheque_restaurante_amount']);
            $order->update_meta_data('_cheque_restaurante_amount', $cheque_restaurante);
            $order->add_order_note(sprintf(
                __('Cheque Restaurante aplicado: €%.2f', 'ruiyi-pos'),
                $cheque_restaurante
            ));
            ruiyi_debug_log("POS: 保存餐厅抵扣票信息 - 金额: €{$cheque_restaurante}");
        }

        // 🔥 保存手动折扣信息
        if (isset($_POST['discount_percent']) && floatval($_POST['discount_percent']) > 0) {
            $discount_percent = floatval($_POST['discount_percent']);
            $discount_amount = isset($_POST['discount_amount']) ? floatval($_POST['discount_amount']) : 0;
            $order->update_meta_data('_manual_discount_percent', $discount_percent);
            $order->update_meta_data('_manual_discount_amount', $discount_amount);
            $order->add_order_note(sprintf(
                __('Descuento manual aplicado: %d%% (€%.2f)', 'ruiyi-pos'),
                $discount_percent,
                $discount_amount
            ));
            ruiyi_debug_log("POS: 保存手动折扣信息 - 百分比: {$discount_percent}%, 金额: €{$discount_amount}");
        }

        // Para pedidos de llevar (takeaway), marcar como completado inmediatamente
        // pero agregar flag para que la cocina lo vea
        if ($order_type === 'llevar') {
            // Marcar que necesita preparación en cocina antes de recoger
            $order->update_meta_data('_needs_kitchen_preparation', 'yes');
            // Establecer estado como completado para generar QR inmediatamente
            $order->update_status('completed', __('Pedido para llevar creado desde POS', 'ruiyi-pos'));
            ruiyi_debug_log("POS: Pedido para llevar #" . $order->get_id() . " marcado como completed con flag de cocina");
        } else {
            // Pedidos de mesa siguen el flujo normal
            // 🔥 对于合并订单，订单已经是 processing 状态，只需添加备注
            if ($is_merging_to_existing) {
                $order->add_order_note(__('✅ 商品追加完成', 'ruiyi-pos'));
                ruiyi_debug_log("POS: 订单 #{$order->get_id()} 商品追加完成");
            } else {
                $order->update_status('processing', __('Orden creada desde POS', 'ruiyi-pos'));
            }
        }

        $order->save();

        // 🔥🔥🔥 【2026-05-01 修复】每次订单变更生成稳定版本号，厨房追加打印只消费同版本批次。
        // 这样分单/部分结账后残留的旧批次不会被下一次追加误打印。
        $kitchen_batch_version = time() . '_' . wp_rand(1000, 9999);

        // 🔥🔥🔥 【2026-02-12 并发修复】使用 add_post_meta(unique=false) 独立存储每次提交的新商品批次
        // 解决：两台设备同时提交到同一桌时，update_meta_data 会互相覆盖导致商品丢失
        // add_post_meta 直接 INSERT 到数据库，每次提交生成独立行，不存在竞态条件
        if (!empty($newly_added_items)) {
            add_post_meta($order->get_id(), '_newly_added_items', array(
                'version' => $kitchen_batch_version,
                'created_at' => time(),
                'items' => $newly_added_items,
            ), false);
            ruiyi_debug_log("[create_order] 📝 记录新添加商品批次 version={$kitchen_batch_version} " . count($newly_added_items) . " 个: " . json_encode(array_column($newly_added_items, 'name')));
        }

        // Clear pending points transaction after successful order creation
        if ($pending_points_transaction) {
            delete_option('ruiyi_pending_points_transaction');
            ruiyi_debug_log("RUIYI POS: Cleared pending points transaction after order creation");
        }

        // ========================================
        // Record transaction to daily summary
        // 记录交易到日结单
        // ========================================
        // 🔥 关键修复：只有外卖订单（llevar）在创建时记录日结数据
        // 堂食订单（servir）在结账时才记录，以确保使用正确的支付方式
        if ($order_type === 'llevar') {
            try {
                // Prepare items array for daily summary
                $items_for_daily = [];
                foreach ($order->get_items() as $item) {
                    $items_for_daily[] = [
                        'name' => $item->get_name(),
                        'quantity' => $item->get_quantity(),
                        'total' => $item->get_total()
                    ];
                }

                // 🔥 验证日结单是否已被hook自动记录，如果没有则手动记录（双重保险）
                // 等待一小段时间让hook有机会先执行
                $order_id = $order->get_id();

                // 重新获取订单检查是否已记录
                $fresh_order = wc_get_order($order_id);
                $recorded = $fresh_order ? $fresh_order->get_meta('_recorded_in_daily_summary', true) : '';

                if ($recorded !== 'yes') {
                    // 手动记录到日结单（作为备份）
                    ruiyi_debug_log("[RUIYI POS] 🔧 日结单未被自动记录，手动触发记录 - Order #" . $order_id);
                    if (function_exists('ruiyi_record_daily_transaction')) {
                        ruiyi_record_daily_transaction($order_id, $normalized_method, $order->get_total(), $items_for_daily);
                        // 标记已记录
                        $fresh_order->update_meta_data('_recorded_in_daily_summary', 'yes');
                        $fresh_order->save();
                        ruiyi_debug_log("[RUIYI POS] ✅ 日结单手动记录成功 - Order #" . $order_id . ", Payment: {$normalized_method}, Total: €" . $order->get_total());
                    }
                } else {
                    ruiyi_debug_log("[RUIYI POS] ✅ 日结单已被自动hook记录 - Order #" . $order_id);
                }
            } catch (Exception $e) {
                // Don't fail the order if daily summary recording fails
                ruiyi_debug_log("[RUIYI POS] Failed to record transaction to daily summary: " . $e->getMessage());
            }
        } else {
            // 堂食订单不在此处记录，等待结账时记录
            ruiyi_debug_log("[RUIYI POS] 堂食订单跳过日结记录 - Order #" . $order->get_id() . ", Type: {$order_type}，等待结账时记录");
        }

        // Verificar que la orden se guardó correctamente
        $saved_order_id = $order->get_id();
        if (!$saved_order_id) {
            // Rollback points if order creation failed and points were used
            if ($pending_points_transaction && is_array($pending_points_transaction)) {
                $user_id = intval($pending_points_transaction['user_id']);
                $points_used = intval($pending_points_transaction['points_used']);
                $site_id = isset($pending_points_transaction['site_id']) ? $pending_points_transaction['site_id'] : null;
                
                // Restore points to user
                $points_key = is_multisite() && $site_id ? "site_{$site_id}_user_points" : 'user_points';
                $current_points = intval(get_user_meta($user_id, $points_key, true));
                $restored_points = $current_points + $points_used;
                update_user_meta($user_id, $points_key, $restored_points);
                
                // Record rollback in points history
                $description = sprintf('订单创建失败，回滚积分：%d积分', $points_used);
                if (function_exists('ruiyi_record_points_history')) {
                    ruiyi_record_points_history($user_id, $points_used, $restored_points, $description, get_current_user_id(), $site_id);
                }
                
                // Clear pending transaction
                delete_option('ruiyi_pending_points_transaction');
                
                ruiyi_debug_log("RUIYI POS: Rolled back points due to order creation failure - User ID: {$user_id}, Points restored: {$points_used}");
            }
            
            wp_send_json_error(['message' => __('❌ Error al guardar el pedido en la base de datos.', 'ruiyi-pos')]);
            return;
        }

        // Éxito - Devolver datos completos para el frontend
        // 厨房打印功能已移除 - 使用浏览器打印替代

        // 计算返回给前端的总价
        $return_total = $order->get_total();
        
        // 如果是追加订单且有桌号，计算桌位累计总价
        if ($is_addition && !empty($table_number) && $order_type === 'servir') {
            // 提取桌号数字和前缀部分
            $table_number_numeric = preg_replace('/[^0-9]/', '', $table_number);
            $table_prefix = preg_replace('/[0-9]+$/', '', trim((string)$table_number));
            $table_prefix = strtoupper(trim($table_prefix));

            if (!empty($table_number_numeric)) {
                // 🔥🔥🔥 【2026-01-19 修复】使用与订单合并相同的匹配逻辑
                // 原问题：meta_query 用精确匹配搜索数字 "3"，但存储的是 "MESA 3"
                // 修复：获取所有processing订单，然后用前缀+数字匹配逻辑过滤
                $all_processing_orders = wc_get_orders([
                    'status' => ['processing', 'pending', 'on-hold'],
                    'limit' => -1,
                    'meta_key' => '_order_type',
                    'meta_value' => 'servir'
                ]);

                $table_total = 0;
                $matched_count = 0;

                // 定义"默认"前缀（与订单合并逻辑保持一致）
                $default_prefixes = ['', 'MESA', '餐桌', 'TABLE', '桌'];
                $is_default_search = in_array($table_prefix, $default_prefixes);

                ruiyi_debug_log("POS: 【累计总价】查找桌位 前缀='{$table_prefix}' 数字='{$table_number_numeric}'，共有" . count($all_processing_orders) . "个堂食订单");

                foreach ($all_processing_orders as $table_order) {
                    $candidate_table = $table_order->get_meta('_table_number');
                    $candidate_table_numeric = preg_replace('/[^0-9]/', '', trim((string)$candidate_table));
                    $candidate_table_prefix = preg_replace('/[0-9]+$/', '', trim((string)$candidate_table));
                    $candidate_table_prefix = strtoupper(trim($candidate_table_prefix));

                    $is_default_candidate = in_array($candidate_table_prefix, $default_prefixes);

                    // 🔥 前缀匹配规则（与订单合并逻辑一致）：
                    // 1. 前缀完全相同 → 匹配
                    // 2. 两边都是默认/空前缀 → 匹配（兼容旧数据：Mesa 3 == 3 == 餐桌3）
                    // 3. 不同的非默认前缀 → 不匹配（DOMICILIO3 != COMEDOR3）
                    $prefix_match = ($table_prefix === $candidate_table_prefix) ||
                                    ($is_default_search && $is_default_candidate);

                    if ($candidate_table_numeric === $table_number_numeric && $prefix_match) {
                        $table_total += $table_order->get_total();
                        $matched_count++;
                        ruiyi_debug_log("POS: ✓ 匹配订单#{$table_order->get_id()} 桌号='{$candidate_table}' 总价=" . $table_order->get_total());
                    }
                }

                ruiyi_debug_log("POS: 【累计总价】匹配到{$matched_count}个订单，桌位累计总价: €{$table_total}");
                $return_total = $table_total;
                ruiyi_debug_log("POS: 追加订单 - 新订单总价: " . $order->get_total() . ", 桌位累计总价: " . $table_total);
                ruiyi_debug_log("POS: 返回给前端的总价: " . $return_total);
            }
        }

        // 🔥 重要：在返回响应前更新桌位实时状态
        ruiyi_debug_log("[桌位状态更新检查] 订单#{$saved_order_id} - table_number: '{$table_number}', order_type: '{$order_type}'");

        if (!empty($table_number) && $order_type !== 'llevar') {
            // 🔥 使用数字部分作为状态存储键，与前端保持一致
            $table_number_numeric = preg_replace('/[^0-9]/', '', $table_number);
            ruiyi_debug_log("[桌位状态更新检查] 数字桌号: '{$table_number_numeric}'");

            if (!empty($table_number_numeric)) {
                // 🔥 添加锁机制防止高并发时的竞态条件
                $lock_key = 'updating_table_status_' . $table_number_numeric;
                $max_retries = 10;
                $retry_count = 0;

                // 等待锁释放（最多500ms）
                while (get_transient($lock_key) && $retry_count < $max_retries) {
                    usleep(50000); // 等待50ms
                    $retry_count++;
                }

                if ($retry_count > 0) {
                    ruiyi_debug_log("[桌位状态] 等待锁释放，重试次数: {$retry_count}");
                }

                // 设置锁（2秒有效期）
                set_transient($lock_key, true, 2);

                try {
                    // 🔥🔥🔥 【关键修复】直接使用 wpdb 更新数据库，绕过 WordPress 缓存
                    // 问题原因：update_option 可能被对象缓存影响，导致手机点餐后 POS 不更新
                    global $wpdb;

                    // 🔥 使用事务 + FOR UPDATE 行级锁防止并发竞态
                    $wpdb->query('START TRANSACTION');

                    // 1. 直接从数据库读取当前值（绕过缓存，加行级锁）
                    $current_value = $wpdb->get_var($wpdb->prepare(
                        "SELECT option_value FROM {$wpdb->options} WHERE option_name = %s FOR UPDATE",
                        'ruiyi_pos_live_table_statuses'
                    ));

                    $live_statuses = array();
                    if ($current_value) {
                        $live_statuses = maybe_unserialize($current_value);
                        if (!is_array($live_statuses)) {
                            $live_statuses = array();
                        }
                    }

                    // 🔥 【关键修复】使用桌位累计总额 $return_total，而不是单个订单金额 $order->get_total()
                    // $return_total 在追加订单时已经包含了该桌位所有未完成订单的累计总额
                    // 这样可以确保轮询时前端获取到的是正确的桌位总金额
                    $table_cumulative_total = $return_total;
                    $new_version = $kitchen_batch_version;

                    // 🔥🔥🔥 【关键修复】全面清除所有匹配数字桌号的键，避免残留
                    foreach (array_keys($live_statuses) as $old_key) {
                        $key_digits = preg_replace('/\D/', '', $old_key);
                        if ($key_digits === $table_number_numeric) {
                            unset($live_statuses[$old_key]);
                            ruiyi_debug_log("[RUIYI_POS_DEBUG] 清除旧格式键: {$old_key}");
                        }
                    }

                    // 🔥 使用数字桌号作为键，与前端 "Mesa X" 格式保持一致
                    $live_statuses[$table_number_numeric] = array(
                        'status'    => 'ocupada',
                        'orderId'   => $saved_order_id,
                        'total'     => $table_cumulative_total,
                        'timestamp' => microtime(true), // 使用微秒级时间戳
                        'version'   => $new_version // 版本号确保唯一性
                    );

                    // 2. 直接更新数据库（绕过缓存）
                    $serialized = maybe_serialize($live_statuses);
                    $updated = $wpdb->update(
                        $wpdb->options,
                        array('option_value' => $serialized),
                        array('option_name' => 'ruiyi_pos_live_table_statuses')
                    );

                    // 3. 如果记录不存在，则插入
                    if ($updated === 0 && $wpdb->get_var($wpdb->prepare(
                        "SELECT COUNT(*) FROM {$wpdb->options} WHERE option_name = %s",
                        'ruiyi_pos_live_table_statuses'
                    )) == 0) {
                        $wpdb->insert(
                            $wpdb->options,
                            array(
                                'option_name' => 'ruiyi_pos_live_table_statuses',
                                'option_value' => $serialized,
                                'autoload' => 'no'
                            )
                        );
                    }

                    // 4. 清除所有相关缓存
                    wp_cache_delete('ruiyi_pos_live_table_statuses', 'options');
                    wp_cache_delete('alloptions', 'options');
                    wp_cache_delete('notoptions', 'options');

                    $wpdb->query('COMMIT');

                    ruiyi_debug_log("[RUIYI_POS_DEBUG] ✅ Live table status updated (DB direct): Table {$table_number_numeric}, Order ID {$saved_order_id}, Cumulative Total {$table_cumulative_total}, Version {$new_version}");
                } catch (Exception $e) {
                    $wpdb->query('ROLLBACK');
                    ruiyi_debug_log("[竞态保护] ❌ add_order_to_cart 桌位状态更新失败: " . $e->getMessage());
                } finally {
                    // 确保释放锁（即使发生异常）
                    delete_transient($lock_key);
                }
            } else {
                ruiyi_debug_log("[桌位状态更新检查] ❌ 数字桌号为空，无法更新状态");
            }
        } else {
            ruiyi_debug_log("[桌位状态更新检查] ❌ 不更新状态 - 原因: " .
                (empty($table_number) ? "桌号为空" : ($order_type === 'llevar' ? "外卖订单" : "未知")));
        }

        // 🔥🔥🔥 WebSocket 服务端推送：通知 pos-hub 有新订单/追加订单
        // 双保险机制：即使客户端 WebSocket 断连，服务端也能直接推送给 POS
        if (!empty($table_number) && $order_type !== 'llevar' && !empty($saved_order_id)) {
            $ws_table_numeric = isset($table_number_numeric) ? $table_number_numeric : preg_replace('/[^0-9]/', '', $table_number);
            if (!empty($ws_table_numeric)) {
        $notify_data = array(
            'table'     => 'Mesa ' . $ws_table_numeric,
            'orderId'   => $saved_order_id,
            'total'     => $return_total,
	            'version'   => isset($new_version) ? $new_version : $kitchen_batch_version,
            'is_merged' => $is_merging_to_existing,
            'newly_added_items' => $newly_added_items,
            'source'    => 'server-push',
            'timestamp' => round(microtime(true) * 1000),
            'site_id'   => get_current_blog_id()
        );

                wp_remote_post('http://127.0.0.1:4012/api/notify-order', array(
                    'body'      => wp_json_encode($notify_data),
                    'headers'   => array(
                        'Content-Type' => 'application/json',
                        'X-Api-Secret' => 'ruiyi_pos_hub_2025_secret_change_me'
                    ),
                    'timeout'   => 2,
                    'blocking'  => false,
                    'sslverify' => false
                ));

                ruiyi_debug_log("[WebSocket Push] 📡 Notified pos-hub: Table Mesa {$ws_table_numeric}, Order #{$saved_order_id}, Total: {$return_total}");
            }
        }

        // 最后返回成功响应
        // 🔥 根据是否合并订单返回不同的消息
        $success_message = $is_merging_to_existing
            ? __('✅ 商品已追加到订单', 'ruiyi-pos')
            : __('✅ Pedido creado correctamente', 'ruiyi-pos');

        // 🔥 获取订单存储的桌号用于调试
        $stored_table_number = $order->get_meta('_table_number');

        wp_send_json_success([
            'order_id' => $saved_order_id,
            'total' => $return_total,
            'status' => wc_get_order_status_name($order->get_status()),
            'payment_method' => $payment_title,
            'message' => $success_message,
            'is_merged' => $is_merging_to_existing,  // 🔥 告诉前端这是合并订单
	            'version' => isset($new_version) ? $new_version : $kitchen_batch_version,  // 🔥 【新增】返回版本号用于厨房打印检测
            'newly_added_items' => $newly_added_items,
            // 🔥 调试信息
            '_debug_table_received' => $table_number,
            '_debug_table_numeric' => isset($table_number_numeric) ? $table_number_numeric : 'N/A',
            '_debug_table_stored' => $stored_table_number,
            '_debug_order_type' => $order_type
        ]);

        // 清除旧的、可能存在的挂起更新（如果之前的逻辑是这样的话）
        // $pending_updates = get_option('ruiyi_pos_pending_table_updates', array());
        // if (isset($pending_updates[$table_number_numeric])) {
        //     unset($pending_updates[$table_number_numeric]);
        //     update_option('ruiyi_pos_pending_table_updates', $pending_updates, 'no');
        // }
        
        $results['status'] = 'success';

    } catch (Exception $e) {
        // Registrar error para debugging
        ruiyi_debug_log('RUIYI POS ERROR: ' . $e->getMessage());
        
        wp_send_json_error([
            'message' => '❌ ' . $e->getMessage(),
            'error_code' => $e->getCode(),
            'error_trace' => WP_DEBUG ? $e->getTraceAsString() : null
        ]);
    }
}
