/* 🧑‍🍳 ACTUALIZAR PEDIDO COCINA - MEJORADO */
add_action('wp_ajax_ruiyi_mark_order_complete', function () {
    if (!is_user_logged_in()) {
        wp_send_json_error(['message' => __('🔒 Debes iniciar sesión.', 'ruiyi-pos')]);
        return;
    }

    // Validar nonce
    if (!isset($_POST['nonce']) || !wp_verify_nonce($_POST['nonce'], 'ruiyi_pos_nonce')) {
        wp_send_json_error(['message' => __('❌ Nonce inválido.', 'ruiyi-pos')]);
        return;
    }

    $order_id = intval($_POST['order_id']);
    $order = wc_get_order($order_id);
    if (!$order) {
        wp_send_json_error(['message' => __('❌ Pedido no encontrado.', 'ruiyi-pos')]);
        return;
    }

    $order->update_status('completed', __('✅ Pedido completado desde cocina', 'ruiyi-pos'));
    $order->update_meta_data('completed_by_kitchen', true);
    $order->add_order_note(__('Marcado como completado desde Panel de Cocina POS', 'ruiyi-pos'));
    $order->save();

    wp_send_json_success(['message' => __('✅ Pedido marcado como completado', 'ruiyi-pos')]);
});

/* 🔥 PEDIDOS EN COCINA */
function ruiyi_get_pedidos_cocina() {
    // 检查安全性
    $nonce = isset($_POST['nonce']) ? sanitize_text_field($_POST['nonce']) : '';
    if (!wp_verify_nonce($nonce, 'cocina_nonce')) {
        wp_send_json_error(['message' => 'Nonce inválido'], 403);
        return;
    }

    // 第一步：先获取所有状态为 'processing' 的订单，暂时去掉 meta_query
    $args = [
        'status' => ['processing'],
        'limit' => 50, // 您可以根据需要调整这个数量
        'orderby' => 'date',
        'order' => 'DESC',
        'return' => 'objects', // 确保返回订单对象
    ];
    $orders_processing = wc_get_orders($args);
    
    // 添加调试日志，看看获取了多少处理中的订单
    ruiyi_debug_log('获取所有处理中的订单 (未经过厨房状态过滤): ' . count($orders_processing) . ' 个订单');

    // 第二步：在PHP中手动过滤掉那些已经被厨房标记为 'yes' 的订单
    $orders_for_kitchen = [];
    foreach ($orders_processing as $order) {
        $kitchen_completed = $order->get_meta('_kitchen_completed', true); // true表示获取单个值
        
        // 添加调试日志，查看每个订单的 _kitchen_completed 状态
        // ruiyi_debug_log('订单ID: ' . $order->get_id() . ' - _kitchen_completed 状态: ' . $kitchen_completed);

        if ($kitchen_completed !== 'yes') {
            $orders_for_kitchen[] = $order; // 只把未被厨房标记为 'yes' 的订单加入最终列表
        }
    }
    
    // 添加调试日志
    ruiyi_debug_log('经过厨房状态过滤后，未完成订单: ' . count($orders_for_kitchen) . ' 个订单');

    // 格式化订单数据 (使用 $orders_for_kitchen 进行格式化)
    $formatted_orders = [];
    foreach ($orders_for_kitchen as $order) { // 注意这里用的是 $orders_for_kitchen
        $order_id = $order->get_id();
        $order_items = [];
        
        foreach ($order->get_items() as $item_id => $item) {
            $order_items[] = [
                'id' => $item_id,
                'product_id' => $item->get_product_id(),
                'name' => $item->get_name(),
                'quantity' => $item->get_quantity(),
            ];
        }
        
        $table_number = $order->get_meta('_table_number');
        if (empty($table_number)) {
            $table_number = $order->get_meta('table_number');
        }
        
        if (empty($table_number)) {
            ruiyi_debug_log("订单 $order_id 没有餐桌号信息");
        } else {
            ruiyi_debug_log("订单 $order_id 的餐桌号: $table_number");
        }
        
        // 获取订单类型
        $order_type = $order->get_meta('_order_type', true);
        if (empty($order_type)) {
            $order_type = 'servir'; // 默认值
            ruiyi_debug_log("订单 $order_id 使用默认订单类型 'servir'");
        } else {
            ruiyi_debug_log("订单 $order_id 的订单类型: $order_type");
        }
        
        $formatted_orders[] = [
            'id' => $order_id,
            'date' => $order->get_date_created()->date('Y-m-d H:i:s'),
            'items' => $order_items,
            'table_number' => $table_number,
            'total' => $order->get_total(),
            'order_type' => $order_type, // 添加订单类型
        ];
    }

    wp_send_json_success([
        'orders' => $formatted_orders, // 这里使用已经过滤和格式化后的订单
        'count' => count($formatted_orders), // 确保count也是正确的
    ]);
}

// 获取已完成的厨房订单
function ruiyi_get_pedidos_cocina_completados() {
    // 检查安全性
    $nonce = isset($_POST['nonce']) ? sanitize_text_field($_POST['nonce']) : '';
    if (!wp_verify_nonce($nonce, 'cocina_nonce')) {
        wp_send_json_error(['message' => 'Nonce inválido'], 403);
        return;
    }

    // 获取已被厨房标记为完成的处理中订单
    $args = [
        'status' => ['processing'],
        'limit' => 20, // 限制获取最近20个完成的订单
        'orderby' => 'meta_value', // 按照完成时间排序
        'meta_key' => '_kitchen_completed_time',
        'order' => 'DESC',
        'meta_query' => [
            [
                'key' => '_kitchen_completed',
                'value' => 'yes',
                'compare' => '='
            ]
        ]
    ];
    $orders = wc_get_orders($args);
    
    // 添加调试日志
    ruiyi_debug_log('获取厨房已完成订单: ' . count($orders) . ' 个订单');

    // 格式化订单数据
    $formatted_orders = [];
    foreach ($orders as $order) {
        $order_id = $order->get_id();
        $order_items = [];
        
        // 获取订单商品
        foreach ($order->get_items() as $item_id => $item) {
            $order_items[] = [
                'id' => $item_id,
                'product_id' => $item->get_product_id(),
                'name' => $item->get_name(),
                'quantity' => $item->get_quantity(),
            ];
        }
        
        // 获取餐桌号
        $table_number = $order->get_meta('_table_number');
        if (empty($table_number)) {
            $table_number = $order->get_meta('table_number');
        }
        
        // 获取完成时间和完成人
        $completed_time = $order->get_meta('_kitchen_completed_time');
        $completed_by_id = $order->get_meta('_kitchen_completed_by');
        $completed_by = '';
        if ($completed_by_id) {
            $user = get_userdata($completed_by_id);
            if ($user) {
                $completed_by = $user->display_name;
            }
        }
        
        // 添加到格式化订单列表
        $formatted_orders[] = [
            'id' => $order_id,
            'date' => $order->get_date_created()->date('Y-m-d H:i:s'),
            'items' => $order_items,
            'table_number' => $table_number,
            'total' => $order->get_total(),
            'completed_time' => $completed_time,
            'completed_by' => $completed_by
        ];
    }

    // 返回订单数据
    wp_send_json_success([
        'completed_orders' => $formatted_orders,
        'count' => count($formatted_orders),
    ]);
}

