/* 📋 MOSTRAR EN ADMIN SI FUE COMPLETADO EN COCINA */
add_filter('manage_edit-shop_order_columns', function ($columns) {
    $columns['cocina'] = __('Cocina', 'ruiyi-pos');
    $columns['payment_details'] = __('Detalles de Pago', 'ruiyi-pos');
