add_action('manage_shop_order_posts_custom_column', function ($column, $post_id) {
    if ($column === 'cocina') {
        $value = get_post_meta($post_id, 'completed_by_kitchen', true);
        echo $value ? '✅' : '';
    }

    if ($column === 'payment_details') {
        $order = wc_get_order($post_id);
        if (!$order) return;

        $payment_method_detail = $order->get_meta('_payment_method_detail', true);
        $cash_amount = floatval($order->get_meta('_cash_amount', true));
        $card_amount = floatval($order->get_meta('_card_amount', true));
        $received_amount = floatval($order->get_meta('_received_amount', true));
        $change_amount = floatval($order->get_meta('_change_amount', true));

        $details = [];

        // 优先使用 _payment_method_detail Meta
        if (!empty($payment_method_detail)) {
            if ($payment_method_detail === 'cash') {
                // 现金支付
                $cash_display = $cash_amount > 0 ? $cash_amount : $order->get_total();
                $details[] = 'Efectivo: €' . number_format($cash_display, 2);
                if ($change_amount > 0) {
                    $details[] = 'Cambio: €' . number_format($change_amount, 2);
                }
            } elseif ($payment_method_detail === 'card') {
                // 刷卡支付
                $card_display = $card_amount > 0 ? $card_amount : $order->get_total();
                $details[] = 'Tarjeta: €' . number_format($card_display, 2);
            } elseif ($payment_method_detail === 'bizum') {
                // Bizum/转账支付
                $bizum_amount_display = floatval($order->get_meta('_bizum_amount', true));
                $bizum_display = $bizum_amount_display > 0 ? $bizum_amount_display : $order->get_total();
                $details[] = 'Bizum: €' . number_format($bizum_display, 2);
            } elseif ($payment_method_detail === 'mixed') {
                // 混合支付
                if ($cash_amount > 0) {
                    $details[] = 'Efectivo: €' . number_format($cash_amount, 2);
                }
                if ($card_amount > 0) {
                    $details[] = 'Tarjeta: €' . number_format($card_amount, 2);
                }
            }
        } else {
            // 没有 _payment_method_detail，从 WooCommerce payment_method 推断
            $payment_method = $order->get_payment_method();
            $payment_title = $order->get_payment_method_title();

            // 使用 payment_title 更准确（因为它显示的就是实际名称）
            if (stripos($payment_title, 'Tarjeta') !== false || stripos($payment_title, 'Card') !== false || $payment_method === 'bacs') {
                $details[] = 'Tarjeta: €' . number_format($order->get_total(), 2);
            } elseif (stripos($payment_title, 'Efectivo') !== false || stripos($payment_title, 'Cash') !== false || $payment_method === 'cod') {
                $details[] = 'Efectivo: €' . number_format($order->get_total(), 2);
            } elseif (!empty($payment_title)) {
                // 其他支付方式，显示原始标题
                $details[] = $payment_title . ': €' . number_format($order->get_total(), 2);
            }
        }

        if (!empty($details)) {
            echo '<small>' . implode('<br>', $details) . '</small>';
        } else {
            echo '<small style="color: #999;">-</small>';
        }
    }
}, 10, 2);

