/* 🔥 自动记录订单到日结单临时存储 */
/* 🔥 关键修复：只在订单完成(completed)时记录到日结单，不在processing状态记录 */
/* 这样确保：1) 外卖订单在支付完成时记录  2) 堂食订单只在结账完成时记录，不在创建时记录 */
add_action('woocommerce_order_status_completed', 'ruiyi_auto_record_to_daily_summary', 20, 2);

function ruiyi_auto_record_to_daily_summary($order_id, $order = null) {
    if (!$order) {
        $order = wc_get_order($order_id);
    }

    if (!$order) {
        ruiyi_debug_log('[日结单] 自动记录失败：无法获取订单 #' . $order_id);
        return;
    }

    // 🔥 检查是否即将被合并（防止重复记录）
    $will_be_merged = $order->get_meta('_will_be_merged', true);
    if ($will_be_merged === 'yes') {
        ruiyi_debug_log('[日结单] 订单 #' . $order_id . ' 即将被合并，跳过记录（避免重复）');
        return;
    }

    // 🔥 检查是否已被合并（防止重复记录）
    $is_merged = $order->get_meta('_is_merged', true);
    if ($is_merged === 'yes') {
        ruiyi_debug_log('[日结单] 订单 #' . $order_id . ' 已被合并，跳过记录（避免重复）');
        return;
    }

    // 🔥 【关键修复】检查是否有待应用的折扣（防止使用原价记录）
    $has_pending_discount = $order->get_meta('_has_pending_discount', true);
    if ($has_pending_discount === 'yes') {
        ruiyi_debug_log('[日结单] 订单 #' . $order_id . ' 有待应用折扣，延迟记录（避免使用原价）');
        return;
    }

    // 检查是否已经记录过（防止重复）
    $already_recorded = $order->get_meta('_recorded_in_daily_summary', true);
    if ($already_recorded === 'yes') {
        ruiyi_debug_log('[日结单] 订单 #' . $order_id . ' 已记录，跳过');
        return;
    }

    // 过滤非收银系统订单（不记录锐意助手等其他来源的订单）
    $order_source = $order->get_meta('_ruiyi_order_source');
    if ($order_source && $order_source !== '收银系统') {
        ruiyi_debug_log('[日结单] 订单 #' . $order_id . ' 来源为"' . $order_source . '"，非收银系统订单，跳过记录');
        return;
    }

    // 获取支付方式
    $payment_method = $order->get_payment_method();
    $total_amount = floatval($order->get_total());

    // 获取订单商品
    $items = [];
    foreach ($order->get_items() as $item) {
        $items[] = [
            'name' => $item->get_name(),
            'product_id' => $item->get_product_id(),
            'quantity' => $item->get_quantity(),
            'total' => floatval($item->get_total())
        ];
    }

    // 调用记录函数
    if (function_exists('ruiyi_record_daily_transaction')) {
        ruiyi_record_daily_transaction($order_id, $payment_method, $total_amount, $items);

        // 标记已记录
        $order->update_meta_data('_recorded_in_daily_summary', 'yes');
        $order->save();

        ruiyi_debug_log('[日结单] 自动记录成功 - 订单 #' . $order_id . ', 金额: €' . $total_amount);
    }
}


