// 处理税率设置保存
function ruiyi_handle_tax_rate_settings() {
    $categories = get_terms(['taxonomy' => 'product_cat', 'hide_empty' => false]);

    foreach ($categories as $category) {
        $option_name = 'ruiyi_tax_rate_cat_' . $category->term_id;
        register_setting('ruiyi_tax_rates', $option_name);
    }
}

// 获取产品税率的统一函数 - 基于产品分类
function ruiyi_get_product_tax_rate($product) {
    $tax_rate = 10.0; // 默认税率

    if (!$product) {
        ruiyi_debug_log('RUIYI TAX: ruiyi_get_product_tax_rate called with null product');
        return $tax_rate;
    }

    $product_id = $product->get_id();
    ruiyi_debug_log('RUIYI TAX: Getting tax rate for product ID: ' . $product_id . ', Name: ' . $product->get_name());

    // 获取产品分类
    $categories = wp_get_post_terms($product_id, 'product_cat');

    if (!empty($categories)) {
        // 使用第一个分类的税率设置
        $category = $categories[0];
        $option_name = 'ruiyi_tax_rate_cat_' . $category->term_id;
        $category_tax_rate = get_option($option_name, '10');

        if (!empty($category_tax_rate)) {
            $tax_rate = floatval($category_tax_rate);
            ruiyi_debug_log('RUIYI TAX: Using category "' . $category->name . '" tax rate: ' . $tax_rate . '%');
        } else {
            ruiyi_debug_log('RUIYI TAX: No tax rate set for category "' . $category->name . '", using default');
        }
    } else {
        ruiyi_debug_log('RUIYI TAX: No categories found for product, using default 10%');
    }

    ruiyi_debug_log('RUIYI TAX: Final tax rate for ' . $product->get_name() . ': ' . $tax_rate . '%');
    return $tax_rate;
}

/* 🛡️ SANITIZAR ARRAY DE PRODUCTOS */
function ruiyi_sanitize_cart_items($cart_items) {
    $clean_cart = [];
    foreach ($cart_items as $item) {
        $clean_cart[] = [
            'id'       => intval($item['id']),
            'name'     => sanitize_text_field($item['name']),
            'price'    => floatval($item['price']),
            'quantity' => intval($item['quantity']),
            'taxRate'  => isset($item['taxRate']) ? floatval($item['taxRate']) : 10.0,
        ];
    }
    return $clean_cart;
}
// ✅ Obtener productos para inventario
add_action('wp_ajax_get_inventory_products', function () {
    check_ajax_referer('ruiyi_pos_nonce', 'nonce');

    $products = wc_get_products(['limit' => -1, 'status' => 'publish']);
    $data = [];

    foreach ($products as $product) {
        $data[] = [
            'id' => $product->get_id(),
            'name' => $product->get_name(),
            'stock' => $product->get_stock_quantity()
        ];
    }

    wp_send_json_success($data);
});

// ✅ Actualizar stock desde la vista de inventario
add_action('wp_ajax_update_inventory_stock', function () {
    check_ajax_referer('ruiyi_pos_nonce', 'nonce');

    $id = intval($_POST['product_id']);
    $stock = intval($_POST['stock']);

    $product = wc_get_product($id);
    if (!$product) {
        wp_send_json_error('Producto no encontrado.');
    }

    $product->set_stock_quantity($stock);
    $product->save();

    wp_send_json_success();
});


