function ruiyi_load_cocina_template($template) {
    if (get_query_var('cocina_view') == 1) {
        get_header();

        // Verificar autenticación
        if (!is_user_logged_in()) {
            wp_redirect(home_url('/'));
            exit;
        }

        $user = wp_get_current_user();
        $allowed_roles = ['administrator', 'chef', 'cocina_staff'];
        if (!array_intersect($allowed_roles, $user->roles)) {
            ruiyi_permission_denied_page(
                ruiyi_translate(
                    'No tienes permisos para acceder a la cocina.',
                    'You do not have permission to access the kitchen.',
                    '您没有权限访问厨房系统。'
                )
            );
        }

        ?>
        <main class="ruiyi-cocina-dashboard">
            <h2><?php _e('Panel de Cocina', 'ruiyi-pos'); ?></h2>
            <div id="cocina-pedidos"></div>
        </main>
        <?php
        // 创建厨房系统专用nonce
        $cocina_nonce = wp_create_nonce('cocina_nonce');
        // 创建订单完成nonce（ruiyi_mark_order_complete 使用）
        $pos_nonce = wp_create_nonce('ruiyi_pos_nonce');
        ?>
        <script>
        document.addEventListener("DOMContentLoaded", function () {
            // 防止重复请求的标志
            let isLoading = false;
            let lastRequestTime = 0;
            const MIN_REQUEST_INTERVAL = 3000; // 最小请求间隔3秒

            function cargarPedidos() {
                // 防抖：如果正在加载或距离上次请求时间太短，跳过
                const now = Date.now();
                if (isLoading || (now - lastRequestTime < MIN_REQUEST_INTERVAL)) {
                    console.log('[厨房面板] 跳过请求 - 正在加载或间隔太短');
                    return;
                }

                isLoading = true;
                lastRequestTime = now;

                fetch('<?php echo admin_url('admin-ajax.php'); ?>', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
                    body: new URLSearchParams({
                        action: 'ruiyi_get_pedidos_cocina',
                        nonce: '<?php echo esc_js($cocina_nonce); ?>'
                    })
                })
                .then(res => {
                    if (!res.ok) {
                        throw new Error('HTTP ' + res.status);
                    }
                    return res.json();
                })
                .then(data => {
                    isLoading = false;
                    const contenedor = document.getElementById('cocina-pedidos');
                    contenedor.innerHTML = '';

                    if (data.success && data.data && data.data.orders && data.data.orders.length > 0) {
                        data.data.orders.forEach(order => {
                            const div = document.createElement('div');
                            div.classList.add('pedido');

                            let html = `<h3>Pedido #${order.id} | Mesa: ${order.table_number}</h3><ul>`;
                            order.items.forEach(item => {
                                html += `<li>${item.quantity} × ${item.name} - ${item.total}</li>`;
                            });
                            html += '</ul><button class="completar-btn" data-id="' + order.id + '">✅ Completar</button>';

                            div.innerHTML = html;
                            contenedor.appendChild(div);
                        });
                    } else {
                        contenedor.innerHTML = '<p>No hay pedidos pendientes.</p>';
                    }

                    // Botones completar
                    document.querySelectorAll('.completar-btn').forEach(btn => {
                        btn.addEventListener('click', function () {
                            const id = this.dataset.id;
                            fetch('<?php echo admin_url('admin-ajax.php'); ?>', {
                                method: 'POST',
                                headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
                                body: new URLSearchParams({
                                    action: 'ruiyi_mark_order_complete',
                                    order_id: id,
                                    nonce: '<?php echo esc_js($pos_nonce); ?>'
                                })
                            })
                            .then(res => res.json())
                            .then(result => {
                                alert(result.message);
                                cargarPedidos(); // Refrescar pedidos
                            });
                        });
                    });
                })
                .catch(error => {
                    isLoading = false;
                    console.error('[厨房面板] 请求失败:', error);
                });
            }

            cargarPedidos();
            setInterval(cargarPedidos, 15000); // Auto-refresh cada 15 segundos
        });
        </script>
        
        <style>
            .ruiyi-cocina-dashboard { padding: 20px; max-width: 800px; margin: auto; }
            .pedido { border: 1px solid #ccc; padding: 10px; margin-bottom: 15px; border-radius: 6px; }
            .pedido h3 { margin-top: 0; }
            .completar-btn { background: #28a745; color: white; border: none; padding: 8px 16px; cursor: pointer; border-radius: 4px; }
        </style>
        <?php

        get_footer();
        exit;
    }
    return $template;
}
