add_action('rest_api_init', function () {
    register_rest_route('ruiyi/v1', '/enviar-ticket', [
        'methods' => 'POST',
        'callback' => function ($request) {
            $params = $request->get_json_params();
            $email = sanitize_email($params['email']);
            $ticket = sanitize_textarea_field($params['ticket']);

            if (!is_email($email)) {
                return new WP_REST_Response(['success' => false, 'message' => 'Email inválido.'], 400);
            }

            $subject = '🧾 Tu Ticket - Restaurante RUIYI';
            $body = "Gracias por tu compra.\n\nDetalle del pedido:\n\n" . $ticket;
            $headers = ['Content-Type: text/plain; charset=UTF-8'];

            if (wp_mail($email, $subject, $body, $headers)) {
                return new WP_REST_Response(['success' => true]);
            } else {
                return new WP_REST_Response(['success' => false, 'message' => 'Error al enviar correo.'], 500);
            }
        },
        'permission_callback' => '__return_true',
    ]);
});
function ruiyi_enqueue_styles() {
    // 🔥 使用文件修改时间作为版本号，确保浏览器始终加载最新CSS
    $output_css_version = filemtime(get_template_directory() . '/assets/css/output.css') ?: '1.0';
    $style_css_version = filemtime(get_stylesheet_directory() . '/style.css') ?: '2.0.0';

    wp_enqueue_style('ruiyi-style', get_template_directory_uri() . '/assets/css/output.css', array(), $output_css_version, 'all');
    // Ensure theme `style.css` loads (contains PWA offline/banner styles)
    wp_enqueue_style('ruiyi-theme-style', get_stylesheet_uri(), array('ruiyi-style'), $style_css_version, 'all');
}
