/**
 * Disable Customizer/Admin-bar injected support script on POS UI.
 *
 * Fixes: "Uncaught SyntaxError: Unexpected token '<' (wp_customize_support_script)"
 * which can happen when offline/cached responses cause the Customizer support JS to
 * receive HTML and break parsing. POS does not need Customizer/admin-bar tooling.
 */
function ruiyi_pwa_disable_customizer_support_on_pos() {
    if (is_admin()) {
        return;
    }

    // PWA theme behaves like a kiosk UI: no admin bar/customizer UI needed.
    add_filter('show_admin_bar', '__return_false', 1000);

    // Prevent Customizer support script from being injected.
    remove_action('admin_bar_menu', 'wp_admin_bar_customize_menu', 40);
    remove_action('wp_before_admin_bar_render', 'wp_customize_support_script');

    // Prevent WooPayments from injecting WCPAY_ASSETS inline script on frontend.
    // It can break offline/cached pages with "Unexpected token '<'".
    if (class_exists('WC_Payments')) {
        remove_action('wp_enqueue_scripts', array('WC_Payments', 'enqueue_assets_script'));
    }
    // Safety: dequeue/deregister if it was already enqueued.
    add_action('wp_enqueue_scripts', function () {
        wp_dequeue_script('WCPAY_ASSETS');
        wp_deregister_script('WCPAY_ASSETS');
    }, 1000);

    // Prevent PHP warnings/notices from being printed into HTML (they break inline JS like woocommerce-js-extra).
    // Keep logging enabled via WP_DEBUG_LOG, just stop display.
    @ini_set('display_errors', '0');
    @ini_set('html_errors', '0');

    // WooCommerce frontend scripts are not needed in POS UI and can inject inline "*-js-extra" blocks.
    add_action('wp_enqueue_scripts', function () {
        // Core WooCommerce handles that may output inline script data.
        $handles = array(
            'woocommerce',
            'wc-add-to-cart',
            'wc-cart-fragments',
            'wc-cart',
            'wc-checkout',
            'wc-single-product',
            'wc-add-to-cart-variation',
            'wc-price-slider',
            'jquery-blockui',
            'js-cookie',
        );
        foreach ($handles as $h) {
            wp_dequeue_script($h);
            wp_deregister_script($h);
        }
    }, 1001);
}
add_action('wp', 'ruiyi_pwa_disable_customizer_support_on_pos', 1);

