/**
 * Get products for caching (PWA)
 */
add_action('wp_ajax_ruiyi_pos_get_products', 'ruiyi_pos_get_products_for_pwa');
add_action('wp_ajax_nopriv_ruiyi_pos_get_products', 'ruiyi_pos_get_products_for_pwa');

function ruiyi_pos_get_products_for_pwa() {
    if (!isset($_POST['nonce']) || !wp_verify_nonce($_POST['nonce'], 'ruiyi_pos_nonce')) {
        wp_send_json_error(['message' => 'Error de seguridad']);
        return;
    }

    try {
        $products = wc_get_products(['limit' => -1, 'status' => 'publish']);
        $products_data = [];

        foreach ($products as $product) {
            $image_id = $product->get_image_id();
            $image_url = $image_id ? wp_get_attachment_url($image_id) : '';

            $categories = [];
            $terms = get_the_terms($product->get_id(), 'product_cat');
            if ($terms && !is_wp_error($terms)) {
                foreach ($terms as $term) {
                    $categories[] = [
                        'term_id' => $term->term_id,
                        'name' => $term->name,
                        'slug' => $term->slug
                    ];
                }
            }

            $products_data[] = [
                'id' => $product->get_id(),
                'name' => $product->get_name(),
                'price' => floatval($product->get_price()),
                'image' => $image_url,
                'stock_status' => $product->get_stock_status(),
                'categories' => $categories,
                'tax_rate' => function_exists('ruiyi_get_product_tax_rate') ? ruiyi_get_product_tax_rate($product) : 0,
            ];
        }

        wp_send_json_success(['data' => $products_data]);
    } catch (Exception $e) {
        wp_send_json_error(['message' => 'Error al obtener productos: ' . $e->getMessage()]);
    }
}

/**
 * Get categories for caching (PWA)
 */
add_action('wp_ajax_ruiyi_pos_get_categories', 'ruiyi_pos_get_categories_for_pwa');
add_action('wp_ajax_nopriv_ruiyi_pos_get_categories', 'ruiyi_pos_get_categories_for_pwa');

function ruiyi_pos_get_categories_for_pwa() {
    if (!isset($_POST['nonce']) || !wp_verify_nonce($_POST['nonce'], 'ruiyi_pos_nonce')) {
        wp_send_json_error(['message' => 'Error de seguridad']);
        return;
    }

    try {
        $categories = get_terms([
            'taxonomy' => 'product_cat',
            'hide_empty' => true,
        ]);

        $categories_data = [];
        if (!is_wp_error($categories)) {
            foreach ($categories as $category) {
                $categories_data[] = [
                    'id' => $category->term_id,
                    'name' => $category->name,
                    'slug' => $category->slug,
                    'count' => $category->count,
                    'parent' => $category->parent,
                ];
            }
        }

        wp_send_json_success(['data' => $categories_data]);
    } catch (Exception $e) {
        wp_send_json_error(['message' => 'Error al obtener categorías: ' . $e->getMessage()]);
    }
}

/**
 * Get customers for caching (PWA)
 */
add_action('wp_ajax_ruiyi_pos_get_customers', 'ruiyi_pos_get_customers_for_pwa');
add_action('wp_ajax_nopriv_ruiyi_pos_get_customers', 'ruiyi_pos_get_customers_for_pwa');

function ruiyi_pos_get_customers_for_pwa() {
    if (!isset($_POST['nonce']) || !wp_verify_nonce($_POST['nonce'], 'ruiyi_pos_nonce')) {
        wp_send_json_error(['message' => 'Error de seguridad']);
        return;
    }

    try {
        $customers_data = [];

        // Get WooCommerce customers
        $users = get_users(['role__in' => ['customer', 'subscriber']]);
        foreach ($users as $user) {
            $phone = get_user_meta($user->ID, 'billing_phone', true);
            if ($phone || $user->user_email) {
                $customers_data[] = [
                    'id' => 'wc_' . $user->ID,
                    'name' => $user->display_name ? $user->display_name : ($phone ? $phone : $user->user_email),
                    'email' => $user->user_email,
                    'phone' => $phone,
                    'address' => get_user_meta($user->ID, 'billing_address_1', true),
                    'postal_code' => get_user_meta($user->ID, 'billing_postcode', true),
                    'type' => 'woocommerce'
                ];
            }
        }

        // Get ruiyi_customer post type customers
        global $wpdb;
        
        // Try direct database query first (more reliable)
        $customer_ids = $wpdb->get_col($wpdb->prepare(
            "SELECT ID FROM {$wpdb->posts} 
            WHERE post_type = %s 
            AND post_status = 'publish' 
            ORDER BY post_title ASC",
            'ruiyi_customer'
        ));
        
        $ruiyi_customers = array();
        if (!empty($customer_ids)) {
            foreach ($customer_ids as $customer_id) {
                $post = get_post($customer_id);
                if ($post) {
                    $ruiyi_customers[] = $post;
                }
            }
        }
        
        // Fallback: Use WP_Query if direct query didn't work
        if (empty($ruiyi_customers)) {
            $args = array(
                'post_type' => 'ruiyi_customer',
                'post_status' => 'publish',
                'posts_per_page' => -1,
                'orderby' => 'title',
                'order' => 'ASC',
                'suppress_filters' => false,
                'no_found_rows' => true
            );
            
            $ruiyi_query = new WP_Query($args);
            $ruiyi_customers = $ruiyi_query->posts;
        }

        foreach ($ruiyi_customers as $customer_post) {
            if (!$customer_post || !isset($customer_post->ID)) continue;
            
            $phone = get_post_meta($customer_post->ID, '_customer_phone', true);
            $name = $customer_post->post_title ? trim($customer_post->post_title) : '';
            
            // Include customer if has name or phone
            if ($name || $phone) {
                $customers_data[] = [
                    'id' => (string)$customer_post->ID,
                    'name' => $name ? $name : ($phone ? $phone : 'Customer'),
                    'phone' => $phone ? $phone : '',
                    'email' => get_post_meta($customer_post->ID, '_customer_email', true),
                    'business_name' => get_post_meta($customer_post->ID, '_customer_business_name', true),
                    'cif_nif' => get_post_meta($customer_post->ID, '_customer_cif_nif', true),
                    'address' => get_post_meta($customer_post->ID, '_customer_address', true),
                    'postal_code' => get_post_meta($customer_post->ID, '_customer_postal_code', true),
                    'type' => 'ruiyi_customer'
                ];
            }
        }

        // Log for debugging
        ruiyi_debug_log('[PWA] ruiyi_pos_get_customers: Found ' . count($customers_data) . ' total customers (WC: ' . count($users) . ', Ruiyi: ' . count($ruiyi_customers) . ')');

        wp_send_json_success(['data' => $customers_data]);
    } catch (Exception $e) {
        wp_send_json_error(['message' => 'Error al obtener clientes: ' . $e->getMessage()]);
    }
}

/* ============================================
   Service Worker Registration Route
   ============================================ */
add_action('init', 'ruiyi_pwa_register_sw_route');
function ruiyi_pwa_register_sw_route() {
    add_rewrite_rule('^sw\.js$', 'index.php?ruiyi_sw=1', 'top');
    add_rewrite_tag('%ruiyi_sw%', '([^&]+)');
}

add_action('parse_request', 'ruiyi_pwa_serve_sw');
function ruiyi_pwa_serve_sw($wp) {
    if (isset($wp->query_vars['ruiyi_sw'])) {
        $sw_file = get_template_directory() . '/sw.js';
        if (file_exists($sw_file)) {
            header('Content-Type: application/javascript');
            header('Service-Worker-Allowed: /');
            header('Cache-Control: no-cache, no-store, must-revalidate');
            header('Pragma: no-cache');
            header('Expires: 0');
            // Prevent redirect by using status 200
            status_header(200);
            readfile($sw_file);
            exit;
        }
    }
}
// 🔥 Acción AJAX para agregar cliente desde POS
add_action('wp_ajax_add_new_pos_client', function() {
    check_ajax_referer('ruiyi_pos_nonce', 'nonce');

    $name = sanitize_text_field($_POST['name']);
    $email = sanitize_email($_POST['email']);
    $phone = sanitize_text_field($_POST['phone']);
    $address = sanitize_text_field($_POST['address']);

    if (email_exists($email)) {
        wp_send_json_error(['message' => 'El correo electrónico ya está registrado.']);
    }

    $password = wp_generate_password();
    $user_id = wp_create_user($email, $password, $email);

    if (is_wp_error($user_id)) {
        wp_send_json_error(['message' => 'Error al crear el usuario.']);
    }

    // Asignar rol "customer"
    $user = new WP_User($user_id);
    $user->set_role('customer');

    // Guardar información adicional
    update_user_meta($user_id, 'billing_phone', $phone);
    update_user_meta($user_id, 'billing_address_1', $address);
    update_user_meta($user_id, 'first_name', $name);

    wp_send_json_success([
        'id' => $user_id,
        'name' => $name,
        'email' => $email
    ]);
});



