// 添加产品编辑页面的多语言字段
add_action('woocommerce_product_options_general_product_data', 'ruiyi_add_product_multilingual_fields');
function ruiyi_add_product_multilingual_fields() {
    global $woocommerce, $post;

    echo '<div class="options_group">';
    echo '<h4 style="padding: 10px 12px; margin: 0; background: #f1f1f1; border-bottom: 1px solid #ccc;">' . __('多语言产品名称 / Multilingual Product Names', 'ruiyi-pos') . '</h4>';

    // 中文名称
    woocommerce_wp_text_input(array(
        'id' => 'product_name_zh',
        'label' => __('中文名称 (Chinese Name)', 'ruiyi-pos'),
        'placeholder' => '例如：豆腐麻婆',
        'desc_tip' => true,
        'description' => __('产品的中文显示名称，当界面语言为中文时显示', 'ruiyi-pos'),
        'value' => get_post_meta($post->ID, '_product_name_zh', true)
    ));

    // 英文名称
    woocommerce_wp_text_input(array(
        'id' => 'product_name_en',
        'label' => __('英文名称 (English Name)', 'ruiyi-pos'),
        'placeholder' => 'e.g: Mapo Tofu',
        'desc_tip' => true,
        'description' => __('产品的英文显示名称，当界面语言为英文时显示', 'ruiyi-pos'),
        'value' => get_post_meta($post->ID, '_product_name_en', true)
    ));

    echo '<p style="padding: 10px 12px; margin: 0; font-size: 12px; color: #666; background: #fafafa; border: 1px solid #e6e6e6;">
        <strong>使用说明 / Instructions:</strong><br>
        • <strong>西班牙语：</strong>使用产品标题（主要名称）<br>
        • <strong>中文：</strong>填写上面的中文名称字段，前台中文界面会显示此名称<br>
        • <strong>英文：</strong>填写上面的英文名称字段，前台英文界面会显示此名称<br>
        • <strong>小票打印：</strong>所有小票默认显示西班牙语名称，无论前台使用什么语言<br><br>
        <strong>Note:</strong> Spanish uses product title. Chinese/English names are optional for frontend display. Receipt printing always uses Spanish names.
    </p>';

    echo '</div>';
}

// 添加产品颜色自定义字段
add_action('woocommerce_product_options_general_product_data', 'ruiyi_add_product_color_field');
function ruiyi_add_product_color_field() {
    global $post;

    echo '<div class="options_group">';
    echo '<h4 style="padding: 10px 12px; margin: 0; background: #f1f1f1; border-bottom: 1px solid #ccc;">' . __('POS 显示颜色 / POS Display Color', 'ruiyi-pos') . '</h4>';

    $current_color = get_post_meta($post->ID, '_ruiyi_product_color', true);
    if (empty($current_color)) {
        $current_color = '#1e293b'; // 默认深蓝色
    }

    // 预设颜色选项
    $preset_colors = array(
        '#1e293b' => '深蓝灰 (默认)',
        '#dc2626' => '红色',
        '#ea580c' => '橙色',
        '#ca8a04' => '黄色',
        '#16a34a' => '绿色',
        '#0891b2' => '青色',
        '#2563eb' => '蓝色',
        '#7c3aed' => '紫色',
        '#db2777' => '粉红',
        '#475569' => '灰色',
        '#0f172a' => '黑色',
    );

    echo '<p class="form-field">';
    echo '<label for="ruiyi_product_color">' . __('卡片背景颜色', 'ruiyi-pos') . '</label>';
    echo '<select id="ruiyi_product_color_preset" style="width: 200px; margin-right: 10px;">';
    echo '<option value="">-- 选择预设颜色 --</option>';
    foreach ($preset_colors as $color => $name) {
        $selected = ($current_color === $color) ? 'selected' : '';
        echo '<option value="' . esc_attr($color) . '" ' . $selected . ' style="background-color: ' . esc_attr($color) . '; color: white;">' . esc_html($name) . '</option>';
    }
    echo '<option value="custom">自定义颜色...</option>';
    echo '</select>';
    echo '<input type="color" id="ruiyi_product_color" name="ruiyi_product_color" value="' . esc_attr($current_color) . '" style="width: 60px; height: 30px; padding: 0; border: 1px solid #ccc; vertical-align: middle;">';
    echo '<span class="description" style="margin-left: 10px;">选择产品在POS界面显示的背景颜色</span>';
    echo '</p>';

    // JavaScript 处理预设颜色选择
    echo '<script>
    jQuery(document).ready(function($) {
        $("#ruiyi_product_color_preset").on("change", function() {
            var val = $(this).val();
            if (val && val !== "custom") {
                $("#ruiyi_product_color").val(val);
            }
        });
        $("#ruiyi_product_color").on("change", function() {
            $("#ruiyi_product_color_preset").val("");
        });
    });
    </script>';

    echo '</div>';
}

// 保存产品多语言字段
add_action('woocommerce_process_product_meta', 'ruiyi_save_product_multilingual_fields');
function ruiyi_save_product_multilingual_fields($post_id) {
    // 保存中文名称
    $product_name_zh = isset($_POST['product_name_zh']) ? sanitize_text_field($_POST['product_name_zh']) : '';
    update_post_meta($post_id, '_product_name_zh', $product_name_zh);

    // 保存英文名称
    $product_name_en = isset($_POST['product_name_en']) ? sanitize_text_field($_POST['product_name_en']) : '';
    update_post_meta($post_id, '_product_name_en', $product_name_en);

    // 保存产品颜色
    $product_color = isset($_POST['ruiyi_product_color']) ? sanitize_hex_color($_POST['ruiyi_product_color']) : '#1e293b';
    update_post_meta($post_id, '_ruiyi_product_color', $product_color);
}

// 🔥 在WordPress后台产品列表添加中文名和英文名列
add_filter('manage_edit-product_columns', 'ruiyi_add_multilingual_name_columns', 25);
function ruiyi_add_multilingual_name_columns($columns) {
    $new_columns = array();
    foreach ($columns as $key => $value) {
        $new_columns[$key] = $value;
        // 在名称列后插入中文名和英文名
        if ($key === 'name') {
            $new_columns['name_zh'] = '中文名';
            $new_columns['name_en'] = 'English';
        }
    }
    return $new_columns;
