add_action('manage_product_posts_custom_column', 'ruiyi_show_multilingual_name_columns', 10, 2);
function ruiyi_show_multilingual_name_columns($column, $post_id) {
    if ($column === 'name_zh') {
        $name_zh = get_post_meta($post_id, '_product_name_zh', true);
        echo $name_zh ? esc_html($name_zh) : '<span style="color:#999;">—</span>';
    }
    if ($column === 'name_en') {
