}

// 获取多语言产品名称的函数
function ruiyi_get_multilingual_product_name($product, $lang = null, $force_spanish_for_receipt = false) {
    if (!$lang) {
        // 自动检测当前语言
        $lang = defined('RUIYI_CURRENT_LANG') ? RUIYI_CURRENT_LANG : 'zh';
    }

    // 如果强制使用西班牙语（用于小票打印）
    if ($force_spanish_for_receipt) {
        return $product->get_name(); // 返回原始产品标题（西班牙语）
    }

    // 根据语言获取对应名称
    if ($lang === 'zh') {
        $zh_name = get_post_meta($product->get_id(), '_product_name_zh', true);
        if (!empty($zh_name)) {
            return $zh_name;
        }
    } elseif ($lang === 'en') {
        $en_name = get_post_meta($product->get_id(), '_product_name_en', true);
        if (!empty($en_name)) {
            return $en_name;
        }
    }

    // 如果没有对应语言的翻译，返回原始名称（西班牙语）
    return $product->get_name();
}

// 获取多语言产品名称的函数（数组形式产品数据）
function ruiyi_get_multilingual_product_name_array($product_array, $lang = null) {
    if (!$lang) {
        // 自动检测当前语言
        $lang = defined('RUIYI_CURRENT_LANG') ? RUIYI_CURRENT_LANG : 'zh';
    }

    // 根据语言获取对应名称
    if ($lang === 'zh' && !empty($product_array['name_zh'])) {
        return $product_array['name_zh'];
    } elseif ($lang === 'en' && !empty($product_array['name_en'])) {
        return $product_array['name_en'];
    }

    // 如果没有对应语言的翻译，返回原始名称（西班牙语）
    return $product_array['name'];
}

// ESC/POS热敏打印功能已移除 - 改用浏览器原生打印

add_action('wp_ajax_ruiyi_log_access', function () {
    $user = wp_get_current_user();
    $module = sanitize_text_field($_POST['module'] ?? 'unknown');
    $message = "[RUIYI POS] Acceso por PIN: Usuario {$user->user_login} ingresó al módulo: {$module}";
    ruiyi_debug_log($message); // Puedes cambiar esto para guardar en base de datos si quieres
    wp_send_json_success();
});
