// 获取仪表盘统计数据的AJAX处理函数
add_action('wp_ajax_get_dashboard_stats', 'ruiyi_get_dashboard_stats');
function ruiyi_get_dashboard_stats() {
    check_ajax_referer('ruiyi_pos_nonce', 'nonce');
    
    // Allow administrators, shop managers, and POS users
    $user = wp_get_current_user();
    $allowed_roles = ['administrator', 'shop_manager', 'pos_user'];
    if (!is_user_logged_in() || !array_intersect($allowed_roles, $user->roles)) {
        wp_send_json_error(['message' => ruiyi_translate('Permiso denegado', 'Permission denied', '权限不足')]);
    }
    
    // 初始化数据
    $daily_sales = 0;
    $monthly_revenue = 0;
    
    // 获取日期范围
    $today = date('Y-m-d');
    $month_start = date('Y-m-01');
    $month_end = date('Y-m-t');
    
    // 根据当前语言格式化日期显示
    $current_lang = defined('RUIYI_CURRENT_LANG') ? RUIYI_CURRENT_LANG : 'zh';
    if ($current_lang === 'en') {
        $today_display = date('j F Y');
        $month_start_display = date('j M', strtotime(date('Y-m-01')));
        $month_end_display = date('j M', strtotime(date('Y-m-t')));
    } elseif ($current_lang === 'zh') {
        $today_display = date('Y年n月j日');
        $month_start_display = date('n月j日', strtotime(date('Y-m-01')));
        $month_end_display = date('n月j日', strtotime(date('Y-m-t')));
    } else {
        $today_display = date('j F Y');
        $month_start_display = date('j M', strtotime(date('Y-m-01')));
        $month_end_display = date('j M', strtotime(date('Y-m-t')));
    }
    
    // 使用WooCommerce API获取今日销售数据
    $today_orders = wc_get_orders(array(
        'date_created' => $today,
        'status' => array('wc-completed', 'wc-processing'),
        'limit' => -1,
        'return' => 'ids',
    ));
    
    foreach ($today_orders as $order_id) {
        $order = wc_get_order($order_id);
        $daily_sales += $order->get_total();
    }
    
    // 使用WooCommerce API获取本月销售数据
    $monthly_orders = wc_get_orders(array(
        'date_created' => $month_start . '...' . $month_end,
        'status' => array('wc-completed', 'wc-processing'),
        'limit' => -1,
        'return' => 'ids',
    ));
    
    foreach ($monthly_orders as $order_id) {
        $order = wc_get_order($order_id);
        $monthly_revenue += $order->get_total();
    }
    
    // 返回数据
    wp_send_json_success([
        'daily_sales' => round($daily_sales),
        'monthly_revenue' => round($monthly_revenue),
        'today_display' => $today_display,
        'month_start_display' => $month_start_display,
        'month_end_display' => $month_end_display
    ]);
}

// 获取最新订单的AJAX处理函数
add_action('wp_ajax_get_latest_orders', 'ruiyi_get_latest_orders');
function ruiyi_get_latest_orders() {
    check_ajax_referer('ruiyi_pos_nonce', 'nonce');
    
    // Allow administrators, shop managers, and POS users
    $user = wp_get_current_user();
    $allowed_roles = ['administrator', 'shop_manager', 'pos_user'];
    if (!is_user_logged_in() || !array_intersect($allowed_roles, $user->roles)) {
        wp_send_json_error(['message' => ruiyi_translate('Permiso denegado', 'Permission denied', '权限不足')]);
    }
    
    $recent_orders = array();
    
    // 使用WooCommerce API获取最新订单
    $orders = wc_get_orders(array(
        'status' => array('wc-processing', 'wc-completed'),
        'limit' => 4,
        'orderby' => 'date',
        'order' => 'DESC'
    ));
    
    foreach ($orders as $order) {
        $order_items = $order->get_items();
        $items_count = count($order_items);
        
        // 收集所有商品信息
        $order_products = array();
        foreach ($order_items as $item) {
            $order_products[] = array(
                'name' => $item->get_name(),
                'quantity' => $item->get_quantity()
            );
        }
        
        $recent_orders[] = array(
            'id' => $order->get_id(),
            'status' => wc_get_order_status_name($order->get_status()),
            'date' => $order->get_date_created()->date_i18n('j M Y, H:i'),
            'items_count' => $items_count,
            'items' => $order_products,
            'total' => $order->get_total()
        );
    }
    
    wp_send_json_success($recent_orders);
}

// 获取销售数据的AJAX处理函数
add_action('wp_ajax_get_sales_data', 'get_sales_data');
function get_sales_data() {
    check_ajax_referer('ruiyi_pos_nonce', 'nonce');
    
    // Allow administrators, shop managers, and POS users
    $user = wp_get_current_user();
    $allowed_roles = ['administrator', 'shop_manager', 'pos_user'];
    if (!is_user_logged_in() || !array_intersect($allowed_roles, $user->roles)) {
        wp_send_json_error(ruiyi_translate('Permiso denegado', 'Permission denied', '权限不足'));
    }
    
    // 获取请求的时间段参数
    $period = isset($_POST['period']) ? sanitize_text_field($_POST['period']) : 'mensual';
    ruiyi_debug_log('RUIYI POS - Received period parameter: ' . $period);
    
    // 获取语言设置
    $lang = isset($_POST['lang']) ? sanitize_text_field($_POST['lang']) : 'zh';
    $data = array();
    
    $labels = array();
    $sales_data = array();
    $profit_data = array();
    
    switch ($period) {
        case 'today':
            $today_date = date('Y-m-d');
            
            // 根据语言格式化日期标签
            if ($lang == 'en') {
                $labels[] = date('M d', strtotime($today_date));
            } elseif ($lang == 'zh') {
                $labels[] = date('m月d日', strtotime($today_date));
            } else {
                $labels[] = date('d M', strtotime($today_date));
            }
            
            // 使用WooCommerce API获取今日销售数据
            $orders = wc_get_orders(array(
                'date_created' => $today_date,
                'status' => array('wc-completed', 'wc-processing'),
                'limit' => -1,
                'return' => 'ids'
            ));
            
            $sales_amount = 0;
            foreach ($orders as $order_id) {
                $order = wc_get_order($order_id);
                $sales_amount += $order->get_total();
            }
            
            $sales_amount = round($sales_amount);
            $profit_amount = round($sales_amount * 0.4);
            
            $sales_data[] = $sales_amount;
            $profit_data[] = $profit_amount;
            break;
            
        case 'diario':
            // 获取最近30天的数据
            for ($i = 29; $i >= 0; $i--) {
                $date = date('Y-m-d', strtotime("-$i days"));
                
                // 根据语言格式化日期
                if ($lang == 'en') {
                    $labels[] = date('M d', strtotime($date));
                } elseif ($lang == 'zh') {
                    $labels[] = date('m月d日', strtotime($date));
                } else {
                    $labels[] = date('d M', strtotime($date));
                }
                
                // 使用WooCommerce API获取该日销售数据
                $orders = wc_get_orders(array(
                    'date_created' => $date,
                    'status' => array('wc-completed', 'wc-processing'),
                    'limit' => -1,
                    'return' => 'ids'
                ));
                
                $sales_amount = 0;
                foreach ($orders as $order_id) {
                    $order = wc_get_order($order_id);
                    $sales_amount += $order->get_total();
                }
                
                $sales_amount = round($sales_amount);
                $profit_amount = round($sales_amount * 0.4);
                
                $sales_data[] = $sales_amount;
                $profit_data[] = $profit_amount;
            }
            break;
            
        case 'anual':
            // 获取最近2年的月度数据
            for ($i = 23; $i >= 0; $i--) {
                $month_start_date = date('Y-m-01', strtotime("-$i months"));
                $month_end_date = date('Y-m-t', strtotime("-$i months"));
                
                // 根据语言格式化日期
                if ($lang == 'en') {
                    $labels[] = date('M Y', strtotime($month_start_date));
                } elseif ($lang == 'zh') {
                    $labels[] = date('Y年m月', strtotime($month_start_date));
                } else {
                    $labels[] = date('M Y', strtotime($month_start_date));
                }
                
                // 使用WooCommerce API获取该月销售数据
                $orders = wc_get_orders(array(
                    'date_created' => $month_start_date . '...' . $month_end_date,
                    'status' => array('wc-completed', 'wc-processing'),
                    'limit' => -1,
                    'return' => 'ids'
                ));
                
                $sales_amount = 0;
                foreach ($orders as $order_id) {
                    $order = wc_get_order($order_id);
                    $sales_amount += $order->get_total();
                }
                
                $sales_amount = round($sales_amount);
                $profit_amount = round($sales_amount * 0.4);
                
                $sales_data[] = $sales_amount;
                $profit_data[] = $profit_amount;
            }
            break;
            
        default: // mensual
            // 获取最近12个月的数据
            for ($i = 11; $i >= 0; $i--) {
                $month_start_date = date('Y-m-01', strtotime("-$i months"));
                $month_end_date = date('Y-m-t', strtotime("-$i months"));
                
                // 根据语言格式化月份
                if ($lang == 'en') {
                    $labels[] = date('M', strtotime("-$i months"));
                } elseif ($lang == 'zh') {
                    $labels[] = date('m', strtotime("-$i months")) . '月';
                } else {
                    $labels[] = date('M', strtotime("-$i months"));
                }
                
                // 使用WooCommerce API获取该月销售数据
                $orders = wc_get_orders(array(
                    'date_created' => $month_start_date . '...' . $month_end_date,
                    'status' => array('wc-completed', 'wc-processing'),
                    'limit' => -1,
                    'return' => 'ids'
                ));
                
                $sales_amount = 0;
                foreach ($orders as $order_id) {
                    $order = wc_get_order($order_id);
                    $sales_amount += $order->get_total();
                }
                
                $sales_amount = round($sales_amount);
                $profit_amount = round($sales_amount * 0.4);
                
                $sales_data[] = $sales_amount;
                $profit_data[] = $profit_amount;
            }
            break;
    }
    
    // 根据语言设置标签
    $sales_label = ruiyi_translate('Ventas', 'Sales', '销售');
    $profit_label = ruiyi_translate('Ganancias', 'Profits', '利润');
    
    $chart_data = array(
        'labels' => $labels,
        'datasets' => array(
            array(
                'label' => $sales_label,
                'data' => $sales_data,
                'borderColor' => '#ff4d30',
                'backgroundColor' => 'transparent',
                'borderWidth' => 2,
                'tension' => 0.3,
                'pointRadius' => 3,
                'pointBackgroundColor' => '#ff4d30'
            ),
            array(
                'label' => $profit_label,
                'data' => $profit_data,
                'borderColor' => '#aaaaaa',
                'backgroundColor' => 'transparent',
                'borderWidth' => 2,
                'tension' => 0.3,
                'pointRadius' => 3,
                'pointBackgroundColor' => '#aaaaaa'
            )
        )
    );
    
    ruiyi_debug_log('RUIYI POS - Sending chart data with ' . count($labels) . ' data points');
    
    // 返回数据
    wp_send_json_success(array(
        'chart_data' => $chart_data,
        'period' => $period
    ));
}

// 旧版更新桌子状态的函数已删除 - 使用下方的新版本

// 更新桌子状态的AJAX处理函数 - 允许客户端和管理员使用
add_action('wp_ajax_update_table_status', 'ruiyi_update_table_status');
add_action('wp_ajax_nopriv_update_table_status', 'ruiyi_update_table_status'); // 添加nopriv钩子，允许未登录用户
function ruiyi_update_table_status() {
    check_ajax_referer('ruiyi_pos_nonce', 'nonce');
    
    // 检查是否为客户端请求、POS请求或服务员请求
    $is_guest = isset($_POST['is_guest']) && $_POST['is_guest'] === 'yes';
    $is_pos = isset($_POST['is_pos']) && $_POST['is_pos'] === 'yes';
    $is_waiter = isset($_POST['is_waiter']) && $_POST['is_waiter'] === 'yes';
    $force_refresh = isset($_POST['force_refresh']) && $_POST['force_refresh'] === 'yes';
    
    // 允许以下情况的请求：
    // 1. 客户端请求 (is_guest = yes)
    // 2. POS系统请求 (is_pos = yes)
    // 3. 服务员请求 (is_waiter = yes)
    // 4. 已登录用户有相关权限 (管理员、店铺管理员、POS用户、服务员)
    $user = wp_get_current_user();
    $allowed_roles = ['administrator', 'shop_manager', 'pos_user', 'waiter', 'editor', 'author'];
    $has_permission = is_user_logged_in() && array_intersect($allowed_roles, $user->roles);
    
    if (!$is_guest && !$is_pos && !$is_waiter && !$has_permission) {
        ruiyi_debug_log("RUIYI POS: Permission denied for table status update. User roles: " . implode(', ', $user->roles ?? []));
        wp_send_json_error(['message' => 'Permiso denegado - sin permisos suficientes']);
        return;
    }
    
    // Log para debugging de solicitudes de servicio de mesa
    if ($is_waiter) {
        ruiyi_debug_log("RUIYI POS: Waiter table status update request - table: $table_id_input, status: $status, force_refresh: " . ($force_refresh ? 'yes' : 'no'));
    }
    
    $table_id_input = isset($_POST['table_id']) ? sanitize_text_field($_POST['table_id']) : '';
    $status = isset($_POST['status']) ? sanitize_text_field($_POST['status']) : '';
    $order_id = isset($_POST['order_id']) ? absint($_POST['order_id']) : null;
    $total = isset($_POST['total']) ? floatval($_POST['total']) : null;
    
    // 🔥🔥🔥 【2026-01-19 关键修复】支持完整桌号格式（包含前缀）
    // 支持格式：COMEDOR2, DOMICILIO2, Mesa 2, 室内1, 纯数字 等
    $table_number = '';
    $table_full_name = $table_id_input; // 保留完整桌号（包含前缀）
    $table_post_id = 0;

    // Extract global table number via mapping (safe for custom names like "9.5")
    $all_mappings_for_extract = ruiyi_get_all_table_categories_mapping();
    $table_number = ruiyi_safe_extract_table_number($table_id_input, $all_mappings_for_extract);
    if (empty($table_number) && is_numeric($table_id_input)) {
        $table_number = $table_id_input;
        $table_full_name = $table_id_input;
    }

    ruiyi_debug_log("[update_table_status] 🔍 输入桌号: '$table_id_input', 完整名称: '$table_full_name', 数字部分: '$table_number'");
    
    if (empty($table_number) || empty($status)) {
        ruiyi_debug_log("RUIYI POS: Invalid table data - table_id: '$table_id_input' (parsed number: $table_number), status: '$status'");
        wp_send_json_error(['message' => 'Datos inválidos - ID de mesa o estado']);
        return;
    }
    
    // 查找对应的桌子post ID - 通过标题匹配
    $table_query = new WP_Query([
        'post_type' => 'restaurant_table',
        'title' => "Mesa $table_number",
        'posts_per_page' => 1,
        'post_status' => 'publish'
    ]);
    
    if ($table_query->have_posts()) {
        $table_post_id = $table_query->posts[0]->ID;
        wp_reset_postdata();
    } else {
        // 如果没有找到对应的post，尝试直接使用数字ID
        $table_post_id = absint($table_number);
    }
    
    if (!$table_post_id) {
        ruiyi_debug_log("RUIYI POS: Table post not found for table number: $table_number");
        wp_send_json_error(['message' => "Mesa $table_number no encontrada"]);
        return;
    }
    
    // 标准化状态值 - 允许多种状态格式并转换为标准值
    $status_mappings = [
        'available' => 'available',
        'occupied' => 'occupied',
        'libre' => 'available',
        'ocupada' => 'occupied',
        'ordering' => 'occupied',
        'ordered' => 'occupied',
        'paid' => 'available',
        'reserved' => 'occupied',
        'needs-cleaning' => 'available'
    ];
    
    $normalized_status = isset($status_mappings[$status]) ? $status_mappings[$status] : $status;
    
    // 检查标准化后的状态值是否有效
    if (!in_array($normalized_status, ['available', 'occupied'])) {
        ruiyi_debug_log("RUIYI POS: Invalid table status received: $status (normalized: $normalized_status)");
        wp_send_json_error(['message' => "Estado no válido: $status"]);
        return;
    }
    
    // 更新桌子状态 - 使用标准化后的状态值
    update_post_meta($table_post_id, '_table_status', $normalized_status);
    
    // 记录状态更新日志
    ruiyi_debug_log("RUIYI POS: Updated table $table_number (post ID: $table_post_id) status from '$status' to '$normalized_status'");

    // 🔥🔥🔥 【关键修复】直接使用 wpdb 更新数据库，绕过 WordPress 缓存
    // 问题原因：update_option 可能被对象缓存影响，导致数据不一致
    global $wpdb;

    // 🔥 使用事务 + FOR UPDATE 行级锁防止并发竞态
    $wpdb->query('START TRANSACTION');

    // 1. 首先直接从数据库读取当前值（绕过缓存，加行级锁）
    $current_value = $wpdb->get_var($wpdb->prepare(
        "SELECT option_value FROM {$wpdb->options} WHERE option_name = %s FOR UPDATE",
        'ruiyi_pos_live_table_statuses'
    ));

    $live_statuses = array();
    if ($current_value) {
        $live_statuses = maybe_unserialize($current_value);
        if (!is_array($live_statuses)) {
            $live_statuses = array();
        }
    }

    // 2. 更新数据
    // 🔥🔥🔥 【2026-01-19 关键修复】使用完整桌号作为键，避免 COMEDOR2 和 DOMICILIO2 互相覆盖
    $storage_key = $table_full_name;

    if ($normalized_status === 'occupied') {
        $new_version = time() . '_' . wp_rand(1000, 9999);
        $live_statuses[$storage_key] = array(
            'status'    => 'ocupada',
            'timestamp' => microtime(true), // 使用微秒级时间戳
            'orderId'   => $order_id,
            'total'     => $total,
            'version'   => $new_version, // 版本号确保唯一性
            'table_number' => $table_number // 保留数字部分用于兼容
        );
        ruiyi_debug_log("[update_table_status] 🔥 设置桌位 '$storage_key' 为占用: orderId=$order_id, total=$total, version=$new_version");
    } else {
        // 🔥🔥🔥 【关键修复】全面清理所有可能的键格式，避免残留条目
        // 不同代码路径创建的键格式不同（"Mesa 1"、"1"、"COMEDOR1" 等）
        // 必须遍历所有键，按数字部分匹配来清理
        $cleared_keys = array();
        $_cleanup_mappings = ruiyi_get_all_table_categories_mapping();
        foreach (array_keys($live_statuses) as $key) {
            $key_digits = ruiyi_safe_extract_table_number($key, $_cleanup_mappings);
            if ($key_digits === $table_number) {
                unset($live_statuses[$key]);
                $cleared_keys[] = $key;
            }
        }
        // 也尝试直接删除传入的键
        if (isset($live_statuses[$storage_key])) {
            unset($live_statuses[$storage_key]);
            $cleared_keys[] = $storage_key;
        }
        if (isset($live_statuses[$table_number])) {
            unset($live_statuses[$table_number]);
            $cleared_keys[] = $table_number;
        }
        ruiyi_debug_log("[update_table_status] 🔥 设置桌位 '$storage_key' 为空闲, 已清理键: " . implode(', ', array_unique($cleared_keys)));
    }

    // 3. 直接更新数据库（绕过缓存）
    $serialized = maybe_serialize($live_statuses);
    $updated = $wpdb->update(
        $wpdb->options,
        array('option_value' => $serialized),
        array('option_name' => 'ruiyi_pos_live_table_statuses')
    );

    // 4. 如果记录不存在，则插入
    if ($updated === 0 && $wpdb->get_var($wpdb->prepare(
        "SELECT COUNT(*) FROM {$wpdb->options} WHERE option_name = %s",
        'ruiyi_pos_live_table_statuses'
    )) == 0) {
        $wpdb->insert(
            $wpdb->options,
            array(
                'option_name' => 'ruiyi_pos_live_table_statuses',
                'option_value' => $serialized,
                'autoload' => 'no'
            )
        );
        ruiyi_debug_log("[update_table_status] 插入新的 live_table_statuses 记录");
    }

    $wpdb->query('COMMIT');

    // 5. 清除所有相关缓存
    wp_cache_delete('ruiyi_pos_live_table_statuses', 'options');
    wp_cache_delete('alloptions', 'options');
    wp_cache_delete('notoptions', 'options');
    delete_transient('ruiyi_tables_status_cache'); // 🚀 清除轮询缓存，确保下次轮询获取最新数据

    ruiyi_debug_log("RUIYI POS: Successfully updated table '$storage_key' (num: $table_number) status to '$normalized_status' (DB direct update)");

    wp_send_json_success([
        'message' => 'Estado actualizado correctamente',
        'table_number' => $table_number,
        'table_full_name' => $storage_key, // 🔥 返回完整桌号
        'status' => $normalized_status,
        'order_id' => $order_id,
        'total' => $total
    ]);
}

function ruiyi_normalize_table_identifier($input) {
    return strtoupper(preg_replace('/\s+/', '', trim(strval($input))));
}

/**
 * Safe table number extraction — mapping-first, not regex guessing
 * @param string $input Table identifier (custom name like "T5", "厅 9.5", "Mesa 3", pure number, etc.)
 * @param array|null $mappings Table mappings array (optional, pass to avoid repeated queries)
 * @return string Global table number string, or empty string
 */
function ruiyi_safe_extract_table_number($input, $mappings = null) {
    $input = trim(strval($input));
    if ($input === '') {
        return '';
    }

    // Internal canonical format: "Mesa X" / "餐桌 X" / "Table X"
    if (preg_match('/^(?:Mesa|餐桌|Table)\s*(\d+)$/i', $input, $match)) {
        return $match[1];
    }

    if ($mappings === null && function_exists('ruiyi_get_all_table_categories_mapping')) {
        $mappings = ruiyi_get_all_table_categories_mapping();
    }

    $input_normalized = ruiyi_normalize_table_identifier($input);

    if (!empty($mappings) && is_array($mappings)) {
        foreach ($mappings as $mapping) {
            $global_table_number = isset($mapping['global_table_number']) ? strval($mapping['global_table_number']) : '';
            if ($global_table_number === '') {
                continue;
            }

            $display_candidates = array(
                isset($mapping['category_display_name']) ? $mapping['category_display_name'] : '',
                isset($mapping['display_name']) ? $mapping['display_name'] : '',
            );
            if (!empty($mapping['category_name']) && isset($mapping['local_table_number'])) {
                $display_candidates[] = $mapping['category_name'] . $mapping['local_table_number'];
                $display_candidates[] = $mapping['category_name'] . ' ' . $mapping['local_table_number'];
            }

            foreach ($display_candidates as $display_candidate) {
                if ($display_candidate === '') {
                    continue;
                }

                if (ruiyi_normalize_table_identifier($display_candidate) === $input_normalized) {
                    return $global_table_number;
                }
            }
        }
    }

    if (ctype_digit($input)) {
        return $input;
    }

    return '';
}

// 获取所有桌子状态的AJAX处理函数
add_action('wp_ajax_get_tables_status', 'ruiyi_get_tables_status');
add_action('wp_ajax_nopriv_get_tables_status', 'ruiyi_get_tables_status'); // 允许未登录用户
function ruiyi_get_tables_status() {
    check_ajax_referer('ruiyi_pos_nonce', 'nonce');

    // 🔥 【关键修复】放宽权限检查 - 桌位状态只是读取操作，不涉及敏感数据修改
    // 允许：1. 所有已登录用户  2. 有效nonce的请求（证明来自本站页面）
    $user = wp_get_current_user();

    // 🚀 【性能优化 2026-03-30】短期缓存：同一站点多个POS用户5秒内只查一次数据库
    // 使用 transient 而非对象缓存，确保跨请求共享
    $cache_key = 'ruiyi_tables_status_cache';
    $force_refresh = isset($_POST['force_refresh']) && $_POST['force_refresh'] === '1';
    if (!$force_refresh) {
        $cached = get_transient($cache_key);
        if ($cached !== false) {
            wp_send_json_success($cached);
        }
    }

    // 🔥🔥🔥 【关键修复】更激进的缓存清除，解决手机点餐后POS不更新的问题
    // 问题原因：WordPress 对象缓存可能导致 get_option 返回旧数据
    // 解决方案：多层缓存清除 + 直接数据库查询作为备选

    // 1. 清除 WordPress 对象缓存
    wp_cache_delete('ruiyi_pos_live_table_statuses', 'options');
    wp_cache_delete('alloptions', 'options'); // 清除所有选项的缓存

    // 2. 强制 WordPress 重新加载 options
    wp_cache_delete('notoptions', 'options');

    // 3. 使用 wpdb 直接查询数据库，绕过所有缓存层
    global $wpdb;
    $option_value = $wpdb->get_var($wpdb->prepare(
        "SELECT option_value FROM {$wpdb->options} WHERE option_name = %s",
        'ruiyi_pos_live_table_statuses'
    ));

    // 4. 解析数据库返回的值
    $live_statuses = array();
    if ($option_value) {
        $live_statuses = maybe_unserialize($option_value);
        if (!is_array($live_statuses)) {
            $live_statuses = array();
        }
    }
    
    // 构建桌位更新数组，匹配前端期望的格式
    $tables_updates = [];
    $stale_keys_removed = false;
    $all_table_mappings = ruiyi_get_all_table_categories_mapping();

    // 🔥 始终获取所有活跃订单（用于验证已知桌位 + 发现未记录的桌位）
    // 这确保了即使 ruiyi_pos_live_table_statuses 不完整（如页面刷新导致条目丢失），
    // 只要 WooCommerce 订单存在，对应桌位就能正确显示为占用状态
    $all_active_orders = wc_get_orders(array(
        'status' => array('wc-pending', 'wc-processing', 'wc-on-hold'),
        'limit' => -1,
        'return' => 'objects',
        'cache' => false,
    ));

    // 定义默认前缀列表（与 ruiyi_pos_get_orders_for_table_callback 保持一致）
    $default_prefixes = array('', 'MESA', '餐桌', 'TABLE', '桌');

    // 从实时状态表获取数据，同时验证订单是否真实存在
    foreach ($live_statuses as $table_number => $data) {
        $status = $data['status'] ?? 'libre';

        // 🔥🔥🔥 【关键修复】对占用状态的桌位，验证是否有真实的待付订单
        // 防止已合并/已删除/已完成的订单导致僵尸桌位
        if ($status === 'ocupada') {
            $table_num_digits = ruiyi_safe_extract_table_number($table_number, $all_table_mappings);
            if (empty($table_num_digits)) {
                unset($live_statuses[$table_number]);
                $stale_keys_removed = true;
                continue;
            }

            // 🔥 提取桌号前缀（通过 mapping 获取，避免 "9.5" → 前缀 "9."）
            $table_prefix = '';
            if (!empty($all_table_mappings)) {
                foreach ($all_table_mappings as $_tm) {
                    if (strval($_tm['global_table_number']) === $table_num_digits) {
                        $table_prefix = trim(strtoupper($_tm['category_name'] ?? ''));
                        break;
                    }
                }
            }
            if ($table_prefix === '') {
                if (preg_match('/^(Mesa|餐桌|Table|桌)\s*/i', trim((string)$table_number), $_pMatch)) {
                    $table_prefix = strtoupper(trim($_pMatch[1]));
                }
            }
            $is_default_search = in_array($table_prefix, $default_prefixes);

            $real_order_count = 0;
            $real_total = 0;
            $real_latest_order_id = null;

            // 🔥 在PHP中过滤属于该桌位的订单（HPOS兼容，不依赖 meta_query）
            foreach ($all_active_orders as $order) {
                // 跳过回收站订单
                $post = get_post($order->get_id());
                if ($post && $post->post_status === 'trash') {
                    continue;
                }
                // 跳过已合并订单
                if ($order->get_meta('_is_merged') === 'yes') {
                    continue;
                }

                // 获取订单的桌号元数据
                $order_table_meta = $order->get_meta('_table_number', true);
                if (empty($order_table_meta)) {
                    continue;
                }

                // 提取订单桌号的前缀和数字部分
                $order_table_numeric = ruiyi_safe_extract_table_number($order_table_meta, $all_table_mappings);
                $order_table_prefix = '';
                if (!empty($all_table_mappings)) {
                    foreach ($all_table_mappings as $_om) {
                        if (strval($_om['global_table_number']) === $order_table_numeric) {
                            $order_table_prefix = trim(strtoupper($_om['category_name'] ?? ''));
                            break;
                        }
                    }
                }
                if ($order_table_prefix === '') {
                    if (preg_match('/^(Mesa|餐桌|Table|桌)\s*/i', trim((string)$order_table_meta), $_opMatch)) {
                        $order_table_prefix = strtoupper(trim($_opMatch[1]));
                    }
                }
                $is_default_order = in_array($order_table_prefix, $default_prefixes);

                // 数字部分必须匹配
                if ($order_table_numeric !== $table_num_digits) {
                    continue;
                }

                // 🔥 前缀匹配规则（与 ruiyi_pos_get_orders_for_table_callback 保持一致）：
                // 1. 前缀完全相同 → 匹配
                // 2. 两边都是默认/空前缀 → 匹配（兼容旧数据：Mesa 3 == 3 == 餐桌3）
                // 3. 不同的非默认前缀 → 不匹配（DOMICILIO3 != COMEDOR3）
                $prefix_match = ($table_prefix === $order_table_prefix) ||
                                ($is_default_search && $is_default_order);

                if (!$prefix_match) {
                    continue;
                }

                $real_order_count++;
                $real_total += $order->get_total();
                if (!$real_latest_order_id || $order->get_id() > $real_latest_order_id) {
                    $real_latest_order_id = $order->get_id();
                }
            }

            // 没有真实订单 → 僵尸条目，移除
            if ($real_order_count === 0 && !empty($data['orderId'])) {
                $direct_order = wc_get_order(absint($data['orderId']));
                if ($direct_order && in_array($direct_order->get_status(), RUIYI_POS_ACTIVE_ORDER_STATUSES, true)) {
                    $direct_post = get_post($direct_order->get_id());
                    $direct_is_trash = $direct_post && $direct_post->post_status === 'trash';
                    $direct_is_merged = $direct_order->get_meta('_is_merged') === 'yes';

                    if (!$direct_is_trash && !$direct_is_merged) {
                        $old_direct_table = $direct_order->get_meta('_table_number', true);
                        $old_direct_numeric = ruiyi_safe_extract_table_number($old_direct_table, $all_table_mappings);

                        if ($old_direct_numeric !== '' && $old_direct_numeric !== $table_num_digits) {
                            // 防串单：live status 记录错了，不要把订单改到当前桌位；移动状态到订单真实桌位。
                            $new_version = time() . '_' . wp_rand(1000, 9999);
                            unset($live_statuses[$table_number]);
                            $live_statuses[$old_direct_numeric] = array(
                                'status' => 'ocupada',
                                'orderId' => $direct_order->get_id(),
                                'total' => floatval($direct_order->get_total()),
                                'timestamp' => microtime(true),
                                'version' => $new_version,
                            );
                            $stale_keys_removed = true;
                            ruiyi_debug_log("[桌位状态轮询] ⚠️ 拒绝串单修复：status key='{$table_number}' 指向订单 #{$direct_order->get_id()}，但订单属于桌位 {$old_direct_numeric}。已移动状态。");
                            continue;
                        }

                        $real_order_count = 1;
                        $real_total = floatval($direct_order->get_total());
                        $real_latest_order_id = $direct_order->get_id();

                        $repaired_table_number = 'Mesa ' . $table_num_digits;
                        if ($old_direct_numeric === '') {
                            $direct_order->update_meta_data('_table_number', $repaired_table_number);
                            $direct_order->update_meta_data('table_number', $repaired_table_number);
                            if (!empty($all_table_mappings)) {
                                foreach ($all_table_mappings as $_repair_mapping) {
                                    if (strval($_repair_mapping['global_table_number'] ?? '') === strval($table_num_digits)) {
                                        $repair_display = trim((string)($_repair_mapping['category_display_name'] ?? ''));
                                        if ($repair_display !== '') {
                                            $direct_order->update_meta_data('_table_display_name', $repair_display);
                                        }
                                        break;
                                    }
                                }
                            }
                            $direct_order->save();
                            ruiyi_debug_log("[桌位状态轮询] ✓ 通过 live orderId 修复订单 #{$real_latest_order_id} 桌号 meta: '{$old_direct_table}' → '{$repaired_table_number}'");
                        } else {
                            ruiyi_debug_log("[桌位状态轮询] ✓ 通过 live orderId 保留桌位占用: table='{$table_number}', orderId={$real_latest_order_id}");
                        }
                    }
                }
            }

            // 没有真实订单 → 僵尸条目，移除
            if ($real_order_count === 0) {
                ruiyi_debug_log("[桌位状态轮询] 🧹 自动清理僵尸桌位: key='{$table_number}', storedOrderId=" . ($data['orderId'] ?? 'null') . ", storedTotal=" . ($data['total'] ?? 0));
                unset($live_statuses[$table_number]);
                $stale_keys_removed = true;
                continue;
            }

            // 有真实订单，使用验证后的数据
            $table_update = [
                'number' => $table_num_digits,
                'status' => $status,
                'timestamp' => $data['timestamp'] ?? microtime(true),
                'orderId' => $real_latest_order_id,
                'total' => $real_total,
                'order_count' => $real_order_count,
                'version' => $data['version'] ?? (time() . '_0000')
            ];

            // 🔥 为占用桌位返回客户信息（外送区域电话、地址等）
            if ($real_latest_order_id) {
                $ci_order = wc_get_order($real_latest_order_id);
                if ($ci_order) {
                    $ci_phone = $ci_order->get_meta('_customer_phone', true);
                    $ci_address = $ci_order->get_meta('_customer_address', true);
                    if ($ci_phone || $ci_address) {
                        $table_update['customer_info'] = array_filter([
                            'phone' => $ci_phone ?: '',
                            'address' => $ci_address ?: '',
                            'name' => $ci_order->get_meta('_customer_name', true) ?: '',
                            'business_name' => $ci_order->get_meta('_customer_business_name', true) ?: '',
                            'cif_nif' => $ci_order->get_meta('_customer_cif_nif', true) ?: '',
                            'notes' => $ci_order->get_meta('_customer_notes', true) ?: '',
                        ], function($v) { return $v !== ''; });
                    }
                }
            }

            $tables_updates[] = $table_update;
            continue;
        }

        // 非占用状态的桌位直接返回（确保 number 是 gtn）
        $tables_updates[] = [
            'number' => ruiyi_safe_extract_table_number($table_number, $all_table_mappings),
            'status' => $status,
            'timestamp' => $data['timestamp'] ?? microtime(true),
            'orderId' => $data['orderId'] ?? null,
            'total' => $data['total'] ?? 0,
            'version' => $data['version'] ?? (time() . '_0000')
        ];
    }

    // 🔥🔥🔥 【2026-02-12 关键修复】从活跃订单中发现未记录的桌位
    // 场景：客户通过 carrito-cliente.php 下单后，ruiyi_pos_live_table_statuses 可能因
    // 页面刷新等原因丢失该条目，但 WooCommerce 订单仍然存在。
    // 此逻辑确保所有有活跃订单的桌位都能被正确显示为占用状态。
    $already_reported_tables = [];
    foreach ($tables_updates as $update) {
        $already_reported_tables[] = $update['number'];
    }

    // 按桌号聚合所有活跃订单
    $discovered_tables = [];
    foreach ($all_active_orders as $order) {
        $post = get_post($order->get_id());
        if ($post && $post->post_status === 'trash') continue;
        if ($order->get_meta('_is_merged') === 'yes') continue;

        $order_table_meta = $order->get_meta('_table_number', true);
        if (empty($order_table_meta)) continue;

        $order_table_numeric = ruiyi_safe_extract_table_number($order_table_meta, $all_table_mappings);
        if (empty($order_table_numeric)) continue;

        // 跳过已经在响应中的桌位
        if (in_array($order_table_numeric, $already_reported_tables)) continue;

        if (!isset($discovered_tables[$order_table_numeric])) {
            $discovered_tables[$order_table_numeric] = [
                'total' => 0,
                'latest_order_id' => 0,
                'order_count' => 0,
            ];
        }
        $discovered_tables[$order_table_numeric]['total'] += $order->get_total();
        $discovered_tables[$order_table_numeric]['order_count']++;
        if ($order->get_id() > $discovered_tables[$order_table_numeric]['latest_order_id']) {
            $discovered_tables[$order_table_numeric]['latest_order_id'] = $order->get_id();
        }
    }

    // 将发现的桌位添加到响应中，并回写到 live_statuses 保持一致性
    foreach ($discovered_tables as $table_num => $info) {
        $new_version = time() . '_' . wp_rand(1000, 9999);
        $disc_update = [
            'number' => $table_num,
            'status' => 'ocupada',
            'timestamp' => microtime(true),
            'orderId' => $info['latest_order_id'],
            'total' => $info['total'],
            'order_count' => $info['order_count'],
            'version' => $new_version
        ];

        // 🔥 为发现的桌位也返回客户信息（外送区域电话、地址等）
        if ($info['latest_order_id']) {
            $disc_order = wc_get_order($info['latest_order_id']);
            if ($disc_order) {
                $disc_phone = $disc_order->get_meta('_customer_phone', true);
                $disc_address = $disc_order->get_meta('_customer_address', true);
                if ($disc_phone || $disc_address) {
                    $disc_update['customer_info'] = array_filter([
                        'phone' => $disc_phone ?: '',
                        'address' => $disc_address ?: '',
                        'name' => $disc_order->get_meta('_customer_name', true) ?: '',
                        'business_name' => $disc_order->get_meta('_customer_business_name', true) ?: '',
                        'cif_nif' => $disc_order->get_meta('_customer_cif_nif', true) ?: '',
                        'notes' => $disc_order->get_meta('_customer_notes', true) ?: '',
                    ], function($v) { return $v !== ''; });
                }
            }
        }

        $tables_updates[] = $disc_update;

        // 回写到 live_statuses，确保下次轮询也能看到
        $live_statuses[$table_num] = [
            'status' => 'ocupada',
            'orderId' => $info['latest_order_id'],
            'total' => $info['total'],
            'timestamp' => microtime(true),
            'version' => $new_version
        ];
        $stale_keys_removed = true; // 复用此标志触发数据库更新
    }

    // 🔥 如果清理了僵尸条目或发现了新桌位，更新数据库
    if ($stale_keys_removed) {
        $serialized = maybe_serialize($live_statuses);
        $wpdb->update(
            $wpdb->options,
            array('option_value' => $serialized),
            array('option_name' => 'ruiyi_pos_live_table_statuses')
        );
        wp_cache_delete('ruiyi_pos_live_table_statuses', 'options');
        wp_cache_delete('alloptions', 'options');
        ruiyi_debug_log("[桌位状态轮询] 🧹 僵尸条目已从数据库清理");
    }

    // ⚡ 【性能优化】移除冗余的 WP_Query 查询
    // 原因：ruiyi_pos_live_table_statuses 已包含所有桌位的实时状态
    // 该查询每2秒执行一次，造成 500-1500ms 延迟和巨大的数据库负担
    // 优化效果：减少 40-60% 的响应时间
    /*
    // 已禁用：同时从数据库获取桌位状态作为补充
    $args = [
        'post_type' => 'restaurant_table',
        'posts_per_page' => -1,
        'orderby' => 'title',
        'order' => 'ASC'
    ];
    $tables_query = new WP_Query($args);

    if ($tables_query->have_posts()) {
        while ($tables_query->have_posts()) {
            $tables_query->the_post();
            $table_id = get_the_ID();
            $table_name = get_the_title();
            $table_status = get_post_meta($table_id, '_table_status', true) ?: 'available';

            // 提取桌号 (从 "Mesa X" 中提取 X)
            if (preg_match('/Mesa\s+(\d+)/i', $table_name, $matches)) {
                $table_number = $matches[1];

                // 如果在实时状态中没有找到这个桌位，添加默认状态
                $found = false;
                foreach ($tables_updates as $update) {
                    if ($update['number'] == $table_number) {
                        $found = true;
                        break;
                    }
                }

                if (!$found) {
                    $tables_updates[] = [
                        'number' => $table_number,
                        'status' => $table_status === 'occupied' ? 'ocupada' : 'libre',
                        'timestamp' => microtime(true),
                        'orderId' => null,
                        'total' => 0,
                        'version' => time() . '_0000'
                    ];
                }
            }
        }
        wp_reset_postdata();
    }
    */

    $response_data = ['tables_updates' => $tables_updates];

    // 🚀 缓存结果5秒，同站点多POS用户共享，大幅减少重复数据库查询
    set_transient($cache_key, $response_data, 5);

    wp_send_json_success($response_data);
}

// 🔥 获取订单详情用于自动厨房打印
add_action('wp_ajax_ruiyi_pos_get_order_for_print', 'ruiyi_pos_get_order_for_print');
add_action('wp_ajax_nopriv_ruiyi_pos_get_order_for_print', 'ruiyi_pos_get_order_for_print');

function ruiyi_pos_get_order_for_print() {
    check_ajax_referer('ruiyi_pos_nonce', 'nonce');

    $order_id = isset($_POST['order_id']) ? intval($_POST['order_id']) : 0;
    $requested_version = isset($_POST['version']) ? sanitize_text_field(wp_unslash($_POST['version'])) : '';
    $only_new_items = isset($_POST['only_new_items']) && $_POST['only_new_items'] === 'true';
    // 🔥🔥🔥 【2026-03-25 全新机制】unprinted_only 模式：基于 WC 订单行项 meta 跟踪已打印状态
    // 每个 line item 标记 _kitchen_printed，只返回未打印的商品，打印后标记已打印
    // 完全不依赖前端 isAppendOrder 检测，从根本上杜绝重复打印
    $unprinted_only = isset($_POST['unprinted_only']) && $_POST['unprinted_only'] === 'true';

    if (!$order_id) {
        ruiyi_debug_log("[自动厨房打印API] ❌ 订单ID无效");
        wp_send_json_error(['message' => '订单ID无效']);
        return;
    }

    ruiyi_debug_log("[自动厨房打印API] 获取订单详情 - 订单ID: {$order_id}, version: {$requested_version}, unprinted_only: " . ($unprinted_only ? 'true' : 'false') . ", only_new_items: " . ($only_new_items ? 'true' : 'false'));

    $order = wc_get_order($order_id);

    if (!$order) {
        ruiyi_debug_log("[自动厨房打印API] ❌ 订单不存在: {$order_id}");
        wp_send_json_error(['message' => '订单不存在']);
        return;
    }

    $category_printer_enabled = get_option('clodop_category_printer_enabled', 0);
    $kitchen_filter_enabled = get_option('pos_kitchen_category_filter_enabled', '0') === '1';

    // =====================================================
    // 🔥🔥🔥 【2026-03-25 v2】unprinted_only 模式 — 基于 _kitchen_printed_qty 数量跟踪
    // 每个行项记录已打印数量，只返回 (当前数量 - 已打印数量) 的差值
    // 解决：1. 新行项（全新产品）→ 打印全部数量
    //       2. 数量增加（追加同产品）→ 只打印增加的部分
    //       3. 已完全打印的行项 → 跳过
    // =====================================================
    if ($unprinted_only) {
        $items = array();
        $items_to_mark = array(); // [ item_id => new_printed_qty ]

        foreach ($order->get_items() as $item_id => $item) {
            if (wc_get_order_item_meta($item_id, '_is_buffet_opening', true) === 'yes') {
                continue;
            }

            $total_qty = $item->get_quantity();
            $printed_qty = intval(wc_get_order_item_meta($item_id, '_kitchen_printed_qty', true));
            $unprinted_qty = $total_qty - $printed_qty;

            if ($unprinted_qty <= 0) {
                continue; // 已全部打印，跳过
            }

            $product_id = $item->get_product_id();
            $item_notes = wc_get_order_item_meta($item_id, '_item_notes', true);
            $is_supplement = wc_get_order_item_meta($item_id, '_is_supplement', true) === 'yes';
            $parent_item_name = wc_get_order_item_meta($item_id, '_parent_item_name', true);
            $item_data = array(
                'name' => $item->get_name(),
                'name_zh' => $product_id ? (get_post_meta($product_id, '_product_name_zh', true) ?: '') : '',
                'name_en' => $product_id ? (get_post_meta($product_id, '_product_name_en', true) ?: '') : '',
                'quantity' => $unprinted_qty,  // 🔥 只返回未打印的数量
                'product_id' => $product_id,
                'category_id' => 0,
                'category_name' => '',
                'category_printer' => '',
                'notes' => $item_notes ? $item_notes : '',
                'is_supplement' => $is_supplement,
                'parent_item_name' => $parent_item_name ? $parent_item_name : ''
            );

            if ($product_id) {
                $terms = get_the_terms($product_id, 'product_cat');
                if ($terms && !is_wp_error($terms)) {
                    $primary_cat = $terms[0];
                    $item_data['category_id'] = $primary_cat->term_id;
                    $item_data['category_name'] = $primary_cat->name;
                    $cat_printer = get_term_meta($primary_cat->term_id, '_ruiyi_category_printer', true);
                    if ($cat_printer) {
                        $item_data['category_printer'] = $cat_printer;
                    }
                }
            }

            // 🔥 诊断：记录分类打印机查找结果
            if ($product_id) {
                ruiyi_debug_log("[分类打印机诊断-unprinted] product_id={$product_id}, cat_id={$item_data['category_id']}, cat_name={$item_data['category_name']}, cat_printer=" . var_export($item_data['category_printer'], true));
            }

            $items[] = $item_data;
            $items_to_mark[$item_id] = $total_qty; // 标记到当前总数量
        }

        // 🔥 更新已打印数量
        foreach ($items_to_mark as $iid => $new_printed_qty) {
            wc_update_order_item_meta($iid, '_kitchen_printed_qty', $new_printed_qty);
        }

        // 清理旧 meta
        delete_post_meta($order_id, '_newly_added_items');

        ruiyi_debug_log("[自动厨房打印API] ✅ [unprinted_only_v2] 返回未打印商品 " . count($items) . " 个（更新 " . count($items_to_mark) . " 个行项的已打印数量）");

        $order_notes = get_post_meta($order->get_id(), '_order_notes', true);

        wp_send_json_success([
            'items' => $items,
            'date_created' => $order->get_date_created()->date('c'),
            'table_number' => $order->get_meta('_table_number', true),
            'notes' => $order_notes,
            'category_printer_enabled' => (bool)$category_printer_enabled,
            'is_unprinted_only' => true
        ]);
        return;
    }

    // =====================================================
    // 旧逻辑：only_new_items 模式（基于 _newly_added_items meta，保留向后兼容）
    // =====================================================
    $all_batches = get_post_meta($order_id, '_newly_added_items', false);
    $newly_added_items = array();
    $consumed_batches = array();
    $legacy_items = array();
    $legacy_batches = array();
    $has_versioned_batches = false;

    if (is_array($all_batches)) {
        foreach ($all_batches as $batch) {
            if (!is_array($batch)) {
                continue;
            }

            // New format: one meta row per kitchen batch, with version + items.
            if (isset($batch['items']) && is_array($batch['items'])) {
                $has_versioned_batches = true;
                $batch_version = isset($batch['version']) ? (string)$batch['version'] : '';

                if ($requested_version === '' || $batch_version === $requested_version) {
                    $newly_added_items = array_merge($newly_added_items, $batch['items']);
                    $consumed_batches[] = $batch;
                }

                continue;
            }

            // Legacy format: the meta row itself is the item list.
            $looks_like_item_list = true;
            foreach ($batch as $entry) {
                if (!is_array($entry) || !isset($entry['quantity']) || !isset($entry['name'])) {
                    $looks_like_item_list = false;
                    break;
                }
            }

            if ($looks_like_item_list) {
                $legacy_items = array_merge($legacy_items, $batch);
                $legacy_batches[] = $batch;
            }
        }
    }

    // Backward compatibility for orders created before versioned batches existed.
    // If a versioned request is present and versioned batches exist, do not mix in
    // legacy/stale rows; that is exactly what caused split + later append reprints.
    if ($requested_version === '' || (!$has_versioned_batches && empty($newly_added_items))) {
        $newly_added_items = array_merge($newly_added_items, $legacy_items);
        $consumed_batches = array_merge($consumed_batches, $legacy_batches);
    }
    $has_new_items = !empty($newly_added_items);

    if ($only_new_items && !$has_new_items) {
        ruiyi_debug_log("[自动厨房打印API] ℹ️ 请求新商品但无新商品记录（已被消费），返回空列表 - 订单ID: {$order_id}");
        wp_send_json_success([
            'items' => [],
            'date_created' => $order->get_date_created()->date('c'),
            'table_number' => $order->get_meta('_table_number', true),
            'notes' => '',
            'category_printer_enabled' => (bool)$category_printer_enabled,
            'is_new_items_only' => true,
            'no_new_items' => true
        ]);
        return;
    }

    if ($only_new_items && $has_new_items) {
        $items = array();
        $items_to_mark = array();
        foreach ($newly_added_items as $new_item) {
            $product_id = isset($new_item['product_id']) ? intval($new_item['product_id']) : 0;
            $source_item_id = isset($new_item['item_id']) ? intval($new_item['item_id']) : 0;
            $item_data = array(
                'name' => $new_item['name'],
                'name_zh' => $product_id ? (get_post_meta($product_id, '_product_name_zh', true) ?: '') : '',
                'name_en' => $product_id ? (get_post_meta($product_id, '_product_name_en', true) ?: '') : '',
                'quantity' => $new_item['quantity'],
                'product_id' => $product_id,
                'category_id' => 0,
                'category_name' => '',
                'category_printer' => '',
                'notes' => isset($new_item['notes']) ? $new_item['notes'] : '',
                'is_buffet' => isset($new_item['is_buffet']) ? (bool)$new_item['is_buffet'] : false,
                'is_supplement' => isset($new_item['is_supplement']) ? (bool)$new_item['is_supplement'] : false,
                'parent_item_name' => isset($new_item['parent_item_name']) ? $new_item['parent_item_name'] : ''
            );

            if ($product_id) {
                $terms = get_the_terms($product_id, 'product_cat');
                if ($terms && !is_wp_error($terms)) {
                    $primary_cat = $terms[0];
                    $item_data['category_id'] = $primary_cat->term_id;
                    $item_data['category_name'] = $primary_cat->name;
                    $cat_printer = get_term_meta($primary_cat->term_id, '_ruiyi_category_printer', true);
                    if ($cat_printer) {
                        $item_data['category_printer'] = $cat_printer;
                    }
                }
            }

            $items[] = $item_data;

            if ($source_item_id > 0) {
                $source_item = $order->get_item($source_item_id);
                if ($source_item) {
                    $items_to_mark[$source_item_id] = intval($source_item->get_quantity());
                }
            }
        }

        foreach ($items_to_mark as $iid => $new_printed_qty) {
            wc_update_order_item_meta($iid, '_kitchen_printed_qty', $new_printed_qty);
        }

        foreach ($consumed_batches as $consumed_batch) {
            delete_post_meta($order_id, '_newly_added_items', $consumed_batch);
        }

        ruiyi_debug_log("[自动厨房打印API] ✅ 返回新添加商品 " . count($items) . " 个，version={$requested_version}，已同步标记 " . count($items_to_mark) . " 个行项: " . json_encode(array_column($items, 'name')));

        $order_notes = get_post_meta($order->get_id(), '_order_notes', true);

        wp_send_json_success([
            'items' => $items,
            'date_created' => $order->get_date_created()->date('c'),
            'table_number' => $order->get_meta('_table_number', true),
            'notes' => $order_notes,
            'category_printer_enabled' => (bool)$category_printer_enabled,
            'is_new_items_only' => true
        ]);
        return;
    }

    // 获取订单全部商品
    $items = array();
    foreach ($order->get_items() as $item_id => $item) {
        if (wc_get_order_item_meta($item_id, '_is_buffet_opening', true) === 'yes') {
            continue;
        }
        $product_id = $item->get_product_id();
        $item_notes = wc_get_order_item_meta($item_id, '_item_notes', true);
        $is_supplement = wc_get_order_item_meta($item_id, '_is_supplement', true) === 'yes';
        $parent_item_name = wc_get_order_item_meta($item_id, '_parent_item_name', true);
        $item_data = array(
            'name' => $item->get_name(),
            'name_zh' => $product_id ? (get_post_meta($product_id, '_product_name_zh', true) ?: '') : '',
            'name_en' => $product_id ? (get_post_meta($product_id, '_product_name_en', true) ?: '') : '',
            'quantity' => $item->get_quantity(),
            'product_id' => $product_id,
            'category_id' => 0,
            'category_name' => '',
            'category_printer' => '',
            'notes' => $item_notes ? $item_notes : '',
            'is_supplement' => $is_supplement,
            'parent_item_name' => $parent_item_name ? $parent_item_name : ''
        );

        if ($product_id) {
            $terms = get_the_terms($product_id, 'product_cat');
            if ($terms && !is_wp_error($terms)) {
                $primary_cat = $terms[0];
                $item_data['category_id'] = $primary_cat->term_id;
                $item_data['category_name'] = $primary_cat->name;
                $cat_printer = get_term_meta($primary_cat->term_id, '_ruiyi_category_printer', true);
                if ($cat_printer) {
                    $item_data['category_printer'] = $cat_printer;
                }
            }
        }

        $items[] = $item_data;
    }

    if ($has_new_items) {
        delete_post_meta($order_id, '_newly_added_items');
    }

    ruiyi_debug_log("[自动厨房打印API] ✅ 订单详情获取成功 - 商品数量: " . count($items) . ", 分类打印机: " . ($category_printer_enabled ? '启用' : '禁用'));

    $order_notes = get_post_meta($order->get_id(), '_order_notes', true);

    wp_send_json_success([
        'items' => $items,
        'date_created' => $order->get_date_created()->date('c'),
        'table_number' => $order->get_meta('_table_number', true),
        'notes' => $order_notes,
        'category_printer_enabled' => (bool)$category_printer_enabled
    ]);
}

/* 🌐 多语言支持 */
function ruiyi_init_languages() {
    // 🔥 优先级：数据库 > Cookie > 默认中文
    $db_lang = get_option('ruiyi_pos_language', '');
    $cookie_lang = isset($_COOKIE['ruiyi_language']) ? $_COOKIE['ruiyi_language'] : '';

    if ($db_lang && in_array($db_lang, ['es', 'en', 'zh'])) {
        $current_lang = $db_lang;
    } elseif ($cookie_lang && in_array($cookie_lang, ['es', 'en', 'zh'])) {
        $current_lang = $cookie_lang;
        // 同步到数据库
        update_option('ruiyi_pos_language', $current_lang);
    } else {
        $current_lang = 'zh';
        update_option('ruiyi_pos_language', $current_lang);
    }

    // 同步cookie（保持一致）
    if ($cookie_lang !== $current_lang) {
        setcookie('ruiyi_language', $current_lang, time() + 365 * DAY_IN_SECONDS, '/');
    }

    if (!defined('RUIYI_CURRENT_LANG')) {
        define('RUIYI_CURRENT_LANG', $current_lang);
    }
}
add_action('init', 'ruiyi_init_languages');

/**
 * Get placeholder image URL with fallback
 */
function ruiyi_get_placeholder_image() {
    // Try WooCommerce placeholder first
    if (function_exists('wc_placeholder_img_src')) {
        $placeholder = wc_placeholder_img_src();
        // If it's a relative URL, make it absolute
        if (strpos($placeholder, 'http') !== 0) {
            $placeholder = home_url($placeholder);
        }
        return $placeholder;
    }
    
    // Fallback to a default placeholder
    return 'https://via.placeholder.com/300x300?text=No+Image';
}

// 多语言翻译函数
function ruiyi_translate($text_es, $text_en = '', $text_zh = '') {
    // 优先使用页面级语言覆盖（客户点餐页面设置此变量，避免使用POS语言）
    global $ruiyi_page_language;
    $current_lang = $ruiyi_page_language ?: (defined('RUIYI_CURRENT_LANG') ? RUIYI_CURRENT_LANG : 'zh');

    if ($current_lang === 'en' && !empty($text_en)) {
        return $text_en;
    } elseif ($current_lang === 'zh' && !empty($text_zh)) {
        return $text_zh;
    } else {
        return $text_es; // 默认西班牙语
    }
}

// 语言切换AJAX处理（POS收银系统）
add_action('wp_ajax_change_language', 'ruiyi_change_language');
add_action('wp_ajax_nopriv_change_language', 'ruiyi_change_language');
function ruiyi_change_language() {
    $lang = isset($_POST['lang']) ? sanitize_text_field($_POST['lang']) : 'zh';

    // 验证语言代码
    if (!in_array($lang, ['es', 'en', 'zh'])) {
        $lang = 'zh';
    }

    // 🔥 保存到数据库（持久化，不再依赖cookie）
    update_option('ruiyi_pos_language', $lang);

    // 同步Cookie（保持兼容）
    setcookie('ruiyi_language', $lang, time() + 365 * DAY_IN_SECONDS, '/');

    wp_send_json_success(['lang' => $lang, 'saved_to_db' => true]);
}

// 客户点餐页面语言切换（独立于POS，仅设置cookie，不影响收银系统）
add_action('wp_ajax_change_customer_language', 'ruiyi_change_customer_language');
add_action('wp_ajax_nopriv_change_customer_language', 'ruiyi_change_customer_language');
function ruiyi_change_customer_language() {
    $lang = isset($_POST['lang']) ? sanitize_text_field($_POST['lang']) : 'es';

    if (!in_array($lang, ['es', 'en', 'zh'])) {
        $lang = 'es';
    }

    // 仅设置客户专用cookie，不更新任何WordPress option
    setcookie('ruiyi_customer_language', $lang, time() + 365 * DAY_IN_SECONDS, '/');

    wp_send_json_success(['lang' => $lang]);
}

/* 🌐 超级管理员：查看所有子站点的语言设置 */
add_action('wp_ajax_ruiyi_get_all_sites_language', 'ruiyi_get_all_sites_language');
function ruiyi_get_all_sites_language() {
    // 仅超级管理员可访问
    if (!is_super_admin()) {
        wp_send_json_error(['message' => 'Permission denied']);
        return;
    }

    if (!is_multisite()) {
        $lang = get_option('ruiyi_pos_language', 'zh');
        wp_send_json_success([
            'is_multisite' => false,
            'sites' => [['site_id' => 1, 'name' => get_bloginfo('name'), 'url' => home_url(), 'language' => $lang]]
        ]);
        return;
    }

    $sites = get_sites(['number' => 0]);
    $result = [];

    foreach ($sites as $site) {
        switch_to_blog($site->blog_id);
        $lang = get_option('ruiyi_pos_language', '');
        $result[] = [
            'site_id'  => (int) $site->blog_id,
            'name'     => get_bloginfo('name'),
            'url'      => home_url(),
            'language' => $lang ?: 'not_set',
        ];
        restore_current_blog();
    }

    // 按 site_id 排序
    usort($result, function($a, $b) { return $a['site_id'] - $b['site_id']; });

    wp_send_json_success([
        'is_multisite' => true,
        'total_sites'  => count($result),
        'sites'        => $result
    ]);
}

/* 📊 导出订单数据为Excel */
add_action('wp_ajax_export_orders_excel', 'ruiyi_export_orders_excel');
function ruiyi_export_orders_excel() {
    // 权限检查
    if (!current_user_can('manage_options')) {
        wp_send_json_error(['message' => ruiyi_translate('Permiso denegado', 'Permission denied', '权限不足')]);
        return;
    }
    
    // 获取参数
    $period_type = isset($_POST['period_type']) ? sanitize_text_field($_POST['period_type']) : 'daily';
    $date = isset($_POST['date']) ? sanitize_text_field($_POST['date']) : date('Y-m-d');
    
    // 设置时间范围
    $start_date = '';
    $end_date = '';
    $filename = '';
    
    switch ($period_type) {
        case 'daily':
            // 日结表 - 指定日期的所有订单
            $start_date = $date . ' 00:00:00';
            $end_date = $date . ' 23:59:59';
            $filename = 'Ordenes_Diarias_' . $date;
            break;
            
        case 'monthly':
            // 月结表 - 指定月份的所有订单
            $month = date('m', strtotime($date));
            $year = date('Y', strtotime($date));
            $start_date = date('Y-m-01 00:00:00', strtotime($date));
            $end_date = date('Y-m-t 23:59:59', strtotime($date));
            $filename = 'Ordenes_Mensuales_' . $year . '-' . $month;
            break;
            
        case 'yearly':
            // 年结表 - 指定年份的所有订单
            $year = date('Y', strtotime($date));
            $start_date = $year . '-01-01 00:00:00';
            $end_date = $year . '-12-31 23:59:59';
            $filename = 'Ordenes_Anuales_' . $year;
            break;
            
        default:
            wp_send_json_error(['message' => ruiyi_translate('Tipo de período no válido', 'Invalid period type', '无效的时间段类型')]);
            return;
    }
    
    // 查询订单
    $args = array(
        'post_type' => 'shop_order',
        'post_status' => array('wc-completed', 'wc-processing'),
        'date_query' => array(
            array(
                'after'     => $start_date,
                'before'    => $end_date,
                'inclusive' => true,
            ),
        ),
        'posts_per_page' => -1,
        'orderby' => 'date',
        'order' => 'DESC',
    );
    
    $orders_query = new WP_Query($args);
    $orders_data = array();
    
    // 总计
    $total_amount = 0;
    $total_orders = 0;
    $total_items = 0;
    
    if ($orders_query->have_posts()) {
        while ($orders_query->have_posts()) {
            $orders_query->the_post();
            $order = wc_get_order(get_the_ID());
            
            // 商品信息
            $products = array();
            $order_items = $order->get_items();
            $items_count = count($order_items);
            
            foreach ($order_items as $item) {
                $products[] = array(
                    'name' => $item->get_name(),
                    'quantity' => $item->get_quantity(),
                    'price' => $order->get_item_total($item)
                );
            }
            
            // 计算汇总数据
            $total_amount += $order->get_total();
            $total_orders++;
            $total_items += $items_count;
            
            // 订单信息
            $orders_data[] = array(
                'id' => $order->get_id(),
                'date' => $order->get_date_created()->date_i18n('Y-m-d H:i:s'),
                'status' => wc_get_order_status_name($order->get_status()),
                'total' => $order->get_total(),
                'items_count' => $items_count,
                'products' => $products,
                'payment_method' => $order->get_payment_method_title(),
                'customer_name' => $order->get_billing_first_name() . ' ' . $order->get_billing_last_name()
            );
        }
        wp_reset_postdata();
    }
    
    // 导出标题翻译
    $current_lang = defined('RUIYI_CURRENT_LANG') ? RUIYI_CURRENT_LANG : 'zh';
    $headers = array();
    
    if ($current_lang === 'en') {
        $headers = array(
            'id' => 'Order ID',
            'date' => 'Date',
            'status' => 'Status',
            'total' => 'Total',
            'items_count' => 'Products Count',
            'payment_method' => 'Payment Method',
            'customer_name' => 'Customer'
        );
    } elseif ($current_lang === 'zh') {
        $headers = array(
            'id' => '订单ID',
            'date' => '日期',
            'status' => '状态',
            'total' => '总金额',
            'items_count' => '商品数量',
            'payment_method' => '支付方式',
            'customer_name' => '客户'
        );
    } else {
        $headers = array(
            'id' => 'ID de Orden',
            'date' => 'Fecha',
            'status' => 'Estado',
            'total' => 'Total',
            'items_count' => 'Cantidad de Productos',
            'payment_method' => 'Método de Pago',
            'customer_name' => 'Cliente'
        );
    }
    
    // 准备响应数据
    $response_data = array(
        'orders' => $orders_data,
        'summary' => array(
            'total_amount' => $total_amount,
            'total_orders' => $total_orders,
            'total_items' => $total_items,
            'start_date' => $start_date,
            'end_date' => $end_date
        ),
        'headers' => $headers,
        'filename' => $filename
    );
    
    wp_send_json_success($response_data);
}

/**
 * 获取产品数据AJAX处理函数
 */
add_action('wp_ajax_get_product_data', 'ruiyi_get_product_data');
function ruiyi_get_product_data() {
    // 记录请求信息，用于调试
    ruiyi_debug_log('获取产品数据请求: ' . print_r($_POST, true));
    
    // 验证安全检查
    if (!check_ajax_referer('ruiyi_pos_nonce', 'nonce', false)) {
        wp_send_json_error(['message' => ruiyi_translate('Error de seguridad', 'Security error', '安全错误')]);
        return;
    }
    
    // 检查权限，允许所有已登录用户
    if (!is_user_logged_in()) {
        wp_send_json_error(['message' => ruiyi_translate('Permiso denegado', 'Permission denied', '权限不足')]);
        return;
    }
    
    // 获取产品ID
    $product_id = isset($_POST['product_id']) ? absint($_POST['product_id']) : 0;
    if (!$product_id) {
        wp_send_json_error(['message' => ruiyi_translate('ID de producto inválido', 'Invalid product ID', '无效的产品ID')]);
        return;
    }
    
    // 获取产品
    $product = wc_get_product($product_id);
    if (!$product) {
        wp_send_json_error(['message' => ruiyi_translate('Producto no encontrado', 'Product not found', '未找到产品')]);
        return;
    }
    
    try {
        // 获取产品分类
        $category_id = 0;
        $category_name = '';
        $terms = get_the_terms($product_id, 'product_cat');
        if (!empty($terms) && !is_wp_error($terms)) {
            $category_id = $terms[0]->term_id;
            $category_name = $terms[0]->name;
        }
        $category_ids = [];
        if (!empty($terms) && !is_wp_error($terms)) {
            foreach ($terms as $term) {
                $category_ids[] = intval($term->term_id);
            }
        }
        
        // 获取图片URL
        $image_url = get_the_post_thumbnail_url($product_id, 'medium');
        if (!$image_url) {
            $image_url = ruiyi_get_placeholder_image();
        }
        
        // 获取产品颜色
        $product_color = get_post_meta($product_id, '_ruiyi_product_color', true);

        // 获取产品图片ID
        $image_id = get_post_thumbnail_id($product_id);

        // 获取分区价格
        $zone_prices = get_post_meta($product_id, '_ruiyi_zone_prices', true);
        if (!is_array($zone_prices)) {
            $zone_prices = array();
        }

        // 获取时价标记
        $market_price = get_post_meta($product_id, '_ruiyi_market_price', true);

        // 获取过敏原数据
        $allergens = get_post_meta($product_id, '_ruiyi_allergens', true);
        if (!is_array($allergens)) {
            $allergens = array();
        }

        // 获取产品多语言名称
        $name_zh = get_post_meta($product_id, '_product_name_zh', true);
        $name_en = get_post_meta($product_id, '_product_name_en', true);

        // 准备产品数据
        $product_data = [
            'id' => $product->get_id(),
            'name' => $product->get_name(),
            'name_zh' => $name_zh ? $name_zh : '',
            'name_en' => $name_en ? $name_en : '',
            'price' => $product->get_price(), // 使用产品原始价格
            'regular_price' => $product->get_regular_price(),
            'sale_price' => $product->get_sale_price(),
            'stock_quantity' => $product->get_stock_quantity(),
            'description' => $product->get_description(),
            'short_description' => $product->get_short_description(),
            'sku' => $product->get_sku(),
            'category_id' => $category_id,
            'category_ids' => $category_ids,
            'categories' => implode(' ', $category_ids),
            'category_name' => $category_name,
            'image' => $image_url,
            'image_id' => $image_id ? $image_id : '',
            'image_url' => $image_url,
            'color' => $product_color,
            'zone_prices' => $zone_prices,
            'market_price' => $market_price,
            'allergens' => $allergens
        ];
        
        // 记录返回的数据，用于调试
        ruiyi_debug_log('返回产品数据: ' . print_r($product_data, true));

        wp_send_json_success($product_data);
    } catch (Exception $e) {
        ruiyi_debug_log('获取产品数据异常: ' . $e->getMessage());
        wp_send_json_error([
            'message' => ruiyi_translate('Error al obtener datos del producto', 'Error getting product data', '获取产品数据时出错') . ': ' . $e->getMessage()
        ]);
    }
}

/**
 * 更新产品数据AJAX处理函数
 */
add_action('wp_ajax_update_product_data', 'ruiyi_update_product_data');
function ruiyi_update_product_data() {
    // 记录请求信息用于调试
    ruiyi_debug_log('更新产品请求: ' . print_r($_POST, true));
    
    // 验证安全检查
    if (!check_ajax_referer('ruiyi_pos_nonce', 'nonce', false)) {
        ruiyi_debug_log('NONCE验证失败: ' . (isset($_POST['nonce']) ? $_POST['nonce'] : '无nonce'));
        wp_send_json_error(['message' => ruiyi_translate('Error de seguridad', 'Security error', '安全错误')]);
        return;
    }
    
    // 检查权限，允许所有已登录用户
    if (!is_user_logged_in()) {
        ruiyi_debug_log('用户未登录');
        wp_send_json_error(['message' => ruiyi_translate('Permiso denegado', 'Permission denied', '权限不足')]);
        return;
    }
    
    // 获取并验证产品ID
    if (!isset($_POST['product_id']) || empty($_POST['product_id'])) {
        ruiyi_debug_log('产品ID为空: POST=' . print_r($_POST, true));
        wp_send_json_error(['message' => ruiyi_translate('ID de producto inválido', 'Invalid product ID', '无效的产品ID')]);
        return;
    }
    
    $product_id = absint($_POST['product_id']);
    if (!$product_id) {
        ruiyi_debug_log('产品ID无效: ' . $_POST['product_id']);
        wp_send_json_error(['message' => ruiyi_translate('ID de producto inválido', 'Invalid product ID', '无效的产品ID')]);
        return;
    }
    
    ruiyi_debug_log('处理产品ID: ' . $product_id);
    
    // 获取产品
    $product = wc_get_product($product_id);
    if (!$product) {
        ruiyi_debug_log('未找到产品: ' . $product_id);
        wp_send_json_error(['message' => ruiyi_translate('Producto no encontrado', 'Product not found', '未找到产品')]);
        return;
    }
    
    try {
        // 更新产品数据
        $product->set_name(sanitize_text_field($_POST['product_name']));
        $product->set_price(floatval($_POST['product_price']));
        $product->set_regular_price(floatval($_POST['product_price']));
        
        // 更新库存
        if (isset($_POST['product_stock'])) {
            $product->set_stock_quantity(absint($_POST['product_stock']));
            $product->set_manage_stock(true);
        }
        
        // 更新描述
        if (isset($_POST['product_description'])) {
            $product->set_description(wp_kses_post($_POST['product_description']));
        }
        
        // 更新分类
        if (isset($_POST['product_category']) && $_POST['product_category'] > 0) {
            $term = get_term(absint($_POST['product_category']), 'product_cat');
            if ($term && !is_wp_error($term)) {
                wp_set_object_terms($product_id, [$term->term_id], 'product_cat');
            }
        }

        // 更新产品颜色
        if (isset($_POST['product_color'])) {
            $color = sanitize_hex_color($_POST['product_color']);
            if ($color) {
                update_post_meta($product_id, '_ruiyi_product_color', $color);
            } else {
                delete_post_meta($product_id, '_ruiyi_product_color');
            }
        }

        // 更新时价标记
        if (isset($_POST['market_price'])) {
            $market_price = sanitize_text_field($_POST['market_price']);
            if ($market_price === 'yes') {
                update_post_meta($product_id, '_ruiyi_market_price', 'yes');
            } else {
                delete_post_meta($product_id, '_ruiyi_market_price');
            }
        }

        // 更新过敏原数据
        if (isset($_POST['allergens'])) {
            $allergens_raw = $_POST['allergens'];
            // 如果是JSON字符串，解码它
            if (is_string($allergens_raw)) {
                $allergens_raw = json_decode(stripslashes($allergens_raw), true);
            }

            if (is_array($allergens_raw) && !empty($allergens_raw)) {
                // 定义有效的过敏原列表
                $valid_allergens = array('gluten', 'crustaceans', 'eggs', 'fish', 'peanuts', 'soy', 'milk', 'nuts', 'celery', 'mustard', 'sesame', 'sulphites', 'lupin', 'molluscs', 'chili', 'meat');
                $allergens = array();
                foreach ($allergens_raw as $allergen) {
                    $allergen = sanitize_text_field($allergen);
                    if (in_array($allergen, $valid_allergens)) {
                        $allergens[] = $allergen;
                    }
                }
                if (!empty($allergens)) {
                    update_post_meta($product_id, '_ruiyi_allergens', $allergens);
                } else {
                    delete_post_meta($product_id, '_ruiyi_allergens');
                }
            } else {
                delete_post_meta($product_id, '_ruiyi_allergens');
            }
        }

        // 更新产品多语言名称
        if (isset($_POST['product_name_zh'])) {
            update_post_meta($product_id, '_product_name_zh', sanitize_text_field($_POST['product_name_zh']));
        }
        if (isset($_POST['product_name_en'])) {
            update_post_meta($product_id, '_product_name_en', sanitize_text_field($_POST['product_name_en']));
        }

        // 更新分区价格
        if (isset($_POST['zone_prices'])) {
            $zone_prices_raw = $_POST['zone_prices'];
            // 如果是JSON字符串，解码它
            if (is_string($zone_prices_raw)) {
                $zone_prices_raw = json_decode(stripslashes($zone_prices_raw), true);
            }

            if (is_array($zone_prices_raw)) {
                $zone_prices = array();
                foreach ($zone_prices_raw as $zone_key => $price) {
                    $zone_key = sanitize_text_field($zone_key);
                    $price = trim($price);
                    // 只保存非空价格
                    if ($price !== '' && is_numeric($price)) {
                        $zone_prices[$zone_key] = floatval($price);
                    }
                }
                update_post_meta($product_id, '_ruiyi_zone_prices', $zone_prices);
                ruiyi_debug_log("POS: 更新产品 #{$product_id} 分区价格: " . json_encode($zone_prices));
            }
        }

        // 更新产品图片（通过图片ID）
        if (isset($_POST['product_image_id'])) {
            $image_id = absint($_POST['product_image_id']);
            if ($image_id > 0) {
                $product->set_image_id($image_id);
            } else {
                // 如果图片ID为0或空，移除产品图片
                $product->set_image_id(0);
            }
        }

        // 处理图片上传（文件方式 - 保留兼容）
        if (!empty($_FILES['product_image_file']['tmp_name'])) {
            // 验证文件类型
            $file_type = wp_check_filetype(basename($_FILES['product_image_file']['name']), null);
            if (in_array($file_type['type'], ['image/jpeg', 'image/png', 'image/gif'])) {
                // 使用WordPress媒体库添加图片
                $attachment_id = media_handle_upload('product_image_file', $product_id);
                
                if (!is_wp_error($attachment_id)) {
                    // 设置产品图片
                    $product->set_image_id($attachment_id);
                } else {
                    ruiyi_debug_log('上传图片失败: ' . $attachment_id->get_error_message());
                    wp_send_json_error(['message' => $attachment_id->get_error_message()]);
                    return;
                }
            } else {
                ruiyi_debug_log('不允许的文件类型: ' . $file_type['type']);
                wp_send_json_error(['message' => ruiyi_translate('Tipo de archivo no permitido', 'File type not allowed', '不允许的文件类型')]);
                return;
            }
        }
        
        // 保存产品
        $result = $product->save();

        if (is_wp_error($result)) {
            ruiyi_debug_log('保存产品失败: ' . $result->get_error_message());
            wp_send_json_error(['message' => $result->get_error_message()]);
            return;
        }

        // 🔥 清除WooCommerce产品缓存，确保下次读取获得最新数据
        wc_delete_product_transients($product_id);
        clean_post_cache($product_id);
        wp_cache_delete('product-' . $product_id, 'products');
        wp_cache_delete($product_id, 'posts');
        wp_cache_delete($product_id, 'post_meta');

        // 响应成功，返回更新后的价格
        wp_send_json_success([
            'message' => ruiyi_translate('Producto actualizado correctamente', 'Product updated successfully', '产品更新成功'),
            'product_id' => $product_id,
            'updated_price' => $product->get_price(),
            'updated_regular_price' => $product->get_regular_price()
        ]);
        
    } catch (Exception $e) {
        ruiyi_debug_log('更新产品异常: ' . $e->getMessage());
        wp_send_json_error([
            'message' => ruiyi_translate('Error al actualizar el producto', 'Error updating product', '更新产品时出错') . ': ' . $e->getMessage()
        ]);
        return;
    }
}

/**
 * AJAX Handler: Upload Product Image
 */
add_action('wp_ajax_ruiyi_upload_product_image', 'ruiyi_upload_product_image_handler');
function ruiyi_upload_product_image_handler() {
    // Verify nonce
    if (!check_ajax_referer('ruiyi_pos_nonce', 'nonce', false)) {
        wp_send_json_error(['message' => ruiyi_translate('Error de seguridad', 'Security error', '安全错误')]);
        return;
    }

    // Check user permissions
    if (!is_user_logged_in()) {
        wp_send_json_error(['message' => ruiyi_translate('Permiso denegado', 'Permission denied', '权限不足')]);
        return;
    }

    // Check if file was uploaded
    if (empty($_FILES['image']['tmp_name'])) {
        wp_send_json_error(['message' => ruiyi_translate('No se ha seleccionado ninguna imagen', 'No image selected', '未选择图片')]);
        return;
    }

    // Include necessary files for media_handle_upload
    require_once(ABSPATH . 'wp-admin/includes/image.php');
    require_once(ABSPATH . 'wp-admin/includes/file.php');
    require_once(ABSPATH . 'wp-admin/includes/media.php');

    // Upload the file
    $attachment_id = media_handle_upload('image', 0);

    if (is_wp_error($attachment_id)) {
        wp_send_json_error(['message' => $attachment_id->get_error_message()]);
        return;
    }

    // Get the attachment URL
    $attachment_url = wp_get_attachment_url($attachment_id);

    wp_send_json_success([
        'id' => $attachment_id,
        'url' => $attachment_url,
        'message' => ruiyi_translate('Imagen subida correctamente', 'Image uploaded successfully', '图片上传成功')
    ]);
}

/**
 * AJAX Handler: Delete WooCommerce Product
 */
add_action('wp_ajax_ruiyi_delete_product', 'ruiyi_delete_product_handler');
function ruiyi_delete_product_handler() {
    // Verify nonce
    if (!check_ajax_referer('ruiyi_pos_nonce', 'nonce', false)) {
        wp_send_json_error(['message' => ruiyi_translate('Error de seguridad', 'Security error', '安全错误')]);
        return;
    }

    // Check user permissions - only admins and shop managers can delete products
    if (!is_user_logged_in() || (!current_user_can('delete_products') && !current_user_can('manage_woocommerce'))) {
        wp_send_json_error(['message' => ruiyi_translate('Permiso denegado. Solo los administradores pueden eliminar productos.', 'Permission denied. Only administrators can delete products.', '权限不足。只有管理员才能删除产品。')]);
        return;
    }

    // Get product ID
    $product_id = isset($_POST['product_id']) ? absint($_POST['product_id']) : 0;
    if (!$product_id) {
        wp_send_json_error(['message' => ruiyi_translate('ID de producto inválido', 'Invalid product ID', '无效的产品ID')]);
        return;
    }

    // Get the product
    $product = wc_get_product($product_id);
    if (!$product) {
        wp_send_json_error(['message' => ruiyi_translate('Producto no encontrado', 'Product not found', '未找到产品')]);
        return;
    }

    try {
        // Delete the product (force delete, bypass trash)
        $result = $product->delete(true);

        if ($result) {
            wp_send_json_success([
                'message' => ruiyi_translate('Producto eliminado correctamente', 'Product deleted successfully', '产品删除成功'),
                'product_id' => $product_id
            ]);
        } else {
            wp_send_json_error(['message' => ruiyi_translate('Error al eliminar el producto', 'Error deleting product', '删除产品时出错')]);
        }
    } catch (Exception $e) {
        ruiyi_debug_log('Delete product error: ' . $e->getMessage());
        wp_send_json_error([
            'message' => ruiyi_translate('Error al eliminar el producto', 'Error deleting product', '删除产品时出错') . ': ' . $e->getMessage()
        ]);
    }
}

/**
 * AJAX Handler: Create WooCommerce Product
 */
add_action('wp_ajax_ruiyi_create_product', 'ruiyi_create_product_handler');
function ruiyi_create_product_handler() {
    // Verify nonce
    if (!check_ajax_referer('ruiyi_pos_nonce', 'nonce', false)) {
        wp_send_json_error(['message' => ruiyi_translate('Error de seguridad', 'Security error', '安全错误')]);
        return;
    }

    // Check user permissions
    if (!is_user_logged_in() || !current_user_can('edit_products')) {
        wp_send_json_error(['message' => ruiyi_translate('Permiso denegado', 'Permission denied', '权限不足')]);
        return;
    }

    // Get and validate input
    $product_name = isset($_POST['product_name']) ? sanitize_text_field($_POST['product_name']) : '';
    $product_price = isset($_POST['product_price']) ? floatval($_POST['product_price']) : 0;
    $product_category = isset($_POST['product_category']) ? absint($_POST['product_category']) : 0;

    if (empty($product_name)) {
        wp_send_json_error(['message' => ruiyi_translate('El nombre del producto es requerido', 'Product name is required', '产品名称是必需的')]);
        return;
    }

    // 允许价格为0的产品（例如免费产品或赠品）
    if ($product_price < 0) {
        wp_send_json_error(['message' => ruiyi_translate('El precio no puede ser negativo', 'Price cannot be negative', '价格不能为负数')]);
        return;
    }

    if ($product_category <= 0) {
        wp_send_json_error(['message' => ruiyi_translate('Debe seleccionar una categoría', 'You must select a category', '必须选择分类')]);
        return;
    }

    try {
        // Create new product
        $product = new WC_Product_Simple();
        $product->set_name($product_name);
        $product->set_price($product_price);
        $product->set_regular_price($product_price);
        $product->set_status('publish');
        $product->set_catalog_visibility('visible');

        // Save product
        $product_id = $product->save();

        if (is_wp_error($product_id)) {
            wp_send_json_error(['message' => $product_id->get_error_message()]);
            return;
        }

        // Assign category
        $term = get_term($product_category, 'product_cat');
        if ($term && !is_wp_error($term)) {
            wp_set_object_terms($product_id, [$term->term_id], 'product_cat');
        }

        wp_send_json_success([
            'message' => ruiyi_translate('Producto creado exitosamente', 'Product created successfully', '产品创建成功'),
            'product_id' => $product_id
        ]);

    } catch (Exception $e) {
        wp_send_json_error([
            'message' => ruiyi_translate('Error al crear el producto', 'Error creating product', '创建产品时出错') . ': ' . $e->getMessage()
        ]);
    }
}

/**
 * AJAX Handler: Check if Product Name Already Exists
 * 检查产品名称是否已存在
 */
add_action('wp_ajax_ruiyi_check_product_name_exists', 'ruiyi_check_product_name_exists_handler');
function ruiyi_check_product_name_exists_handler() {
    // Verify nonce
    if (!check_ajax_referer('ruiyi_pos_nonce', 'nonce', false)) {
        wp_send_json_error(['message' => ruiyi_translate('Error de seguridad', 'Security error', '安全错误')]);
        return;
    }

    // Check user permissions
    if (!is_user_logged_in()) {
        wp_send_json_error(['message' => ruiyi_translate('Permiso denegado', 'Permission denied', '权限不足')]);
        return;
    }

    // Get product name
    $product_name = isset($_POST['product_name']) ? sanitize_text_field($_POST['product_name']) : '';

    if (empty($product_name)) {
        wp_send_json_success(['exists' => false]);
        return;
    }

    // Search for existing product with the same name (case-insensitive)
    $existing_products = wc_get_products([
        'limit' => 1,
        'status' => ['publish', 'draft', 'pending'],
        'title' => $product_name,
    ]);

    // Also check using direct query for exact match (more reliable)
    global $wpdb;
    $exact_match = $wpdb->get_var($wpdb->prepare(
        "SELECT ID FROM {$wpdb->posts}
         WHERE post_type = 'product'
         AND post_status IN ('publish', 'draft', 'pending')
         AND LOWER(post_title) = LOWER(%s)
         LIMIT 1",
        $product_name
    ));

    $exists = !empty($existing_products) || !empty($exact_match);

    wp_send_json_success([
        'exists' => $exists,
        'message' => $exists
            ? ruiyi_translate(
                'Ya existe un producto con este nombre',
                'A product with this name already exists',
                '已存在同名产品'
              )
            : ''
    ]);
}

/**
 * AJAX Handler: Create WooCommerce Product Category
 * 🔥 此函数已移至文件末尾的"Multi-Level Category System"部分
 * 新版本支持多级分类（最多3层）和多语言名称
 * @see ruiyi_create_product_category_handler() - 约在 line 18100+
 */

/**
 * AJAX Handler: Get Products by Category
 */
add_action('wp_ajax_ruiyi_get_products_by_category', 'ruiyi_get_products_by_category_handler');
add_action('wp_ajax_nopriv_ruiyi_get_products_by_category', 'ruiyi_get_products_by_category_handler');
function ruiyi_get_products_by_category_handler() {
    // Verify nonce
    if (!check_ajax_referer('ruiyi_pos_nonce', 'nonce', false)) {
        wp_send_json_error(['message' => ruiyi_translate('Error de seguridad', 'Security error', '安全错误')]);
        return;
    }

    // Check user permissions
    if (!is_user_logged_in()) {
        wp_send_json_error(['message' => ruiyi_translate('Permiso denegado', 'Permission denied', '权限不足')]);
        return;
    }

    // Get category ID
    $category_id = isset($_POST['category_id']) ? absint($_POST['category_id']) : 0;

    if ($category_id <= 0) {
        wp_send_json_error(['message' => ruiyi_translate('ID de categoría inválido', 'Invalid category ID', '无效的分类ID')]);
        return;
    }

    try {
        // Get category term
        $category = get_term($category_id, 'product_cat');
        if (!$category || is_wp_error($category)) {
            wp_send_json_error(['message' => ruiyi_translate('Categoría no encontrada', 'Category not found', '未找到分类')]);
            return;
        }

        // Get products in this category
        $args = [
            'limit' => -1,
            'status' => 'publish',
            'category' => [$category->slug],
        ];

        $products = wc_get_products($args);
        $products_data = [];

        foreach ($products as $product) {
            $pid = $product->get_id();
            // Get product category name
            $terms = get_the_terms($pid, 'product_cat');
            $category_name = $category->name;
            $cat_name_zh = get_term_meta($category->term_id, 'category_name_zh', true) ?: '';
            $cat_name_en = get_term_meta($category->term_id, 'category_name_en', true) ?: '';
            if (!empty($terms) && !is_wp_error($terms)) {
                $category_name = $terms[0]->name;
                $cat_name_zh = get_term_meta($terms[0]->term_id, 'category_name_zh', true) ?: '';
                $cat_name_en = get_term_meta($terms[0]->term_id, 'category_name_en', true) ?: '';
            }

            $products_data[] = [
                'id' => $pid,
                'name' => $product->get_name(),
                'name_zh' => get_post_meta($pid, '_product_name_zh', true) ?: '',
                'name_en' => get_post_meta($pid, '_product_name_en', true) ?: '',
                'price' => $product->get_price(),
                'category_name' => $category_name,
                'category_name_zh' => $cat_name_zh,
                'category_name_en' => $cat_name_en,
            ];
        }

        wp_send_json_success([
            'products' => $products_data,
            'category_name' => $category->name,
            'category_name_zh' => get_term_meta($category->term_id, 'category_name_zh', true) ?: '',
            'category_name_en' => get_term_meta($category->term_id, 'category_name_en', true) ?: '',
        ]);

    } catch (Exception $e) {
        wp_send_json_error([
            'message' => ruiyi_translate('Error al obtener productos', 'Error getting products', '获取产品时出错') . ': ' . $e->getMessage()
        ]);
    }
}

