// 添加获取所有订单的AJAX处理函数
add_action('wp_ajax_get_all_orders', 'ruiyi_get_all_orders');
add_action('wp_ajax_nopriv_get_all_orders', 'ruiyi_get_all_orders');
function ruiyi_get_all_orders() {
    if (!is_user_logged_in()) {
        wp_send_json_error(['message' => 'Authentication required']);
        return;
    }

    // 验证安全检查
    if (!isset($_POST['nonce']) || !wp_verify_nonce($_POST['nonce'], 'ruiyi_pos_nonce')) {
        wp_send_json_error(['message' => ruiyi_translate('Error de seguridad', 'Security error', '安全错误')]);
        return;
    }
    
    // 记录调试信息
    ruiyi_debug_log('正在执行 ruiyi_get_all_orders 函数');
    
    // 如果WooCommerce不存在，直接返回错误
    if (!function_exists('wc_get_order')) {
        ruiyi_debug_log('WooCommerce 函数不存在');
        wp_send_json_error(['message' => '系统错误: WooCommerce不可用']);
        return;
    }
    
    // 设置每页显示的订单数量（这里设置一个较大的值，如果需要分页可以修改）
    $per_page = 50;
    
    // 获取所有可能的订单状态 - 非常重要，有时订单状态可能不只是processing和completed
    $all_statuses = array('wc-pending', 'wc-processing', 'wc-on-hold', 'wc-completed', 'wc-cancelled', 'wc-refunded', 'wc-failed');
    
    // 获取订单 - 尝试获取所有状态的订单
    $args = array(
        'post_type' => 'shop_order',
        'post_status' => $all_statuses,
        'posts_per_page' => $per_page,
        'orderby' => 'date',
        'order' => 'DESC',
    );
    
    ruiyi_debug_log('查询参数: ' . print_r($args, true));
    
    // 直接使用原始方法查询订单，避免任何插件冲突
    global $wpdb;
    $query = "SELECT ID FROM {$wpdb->posts} WHERE post_type = 'shop_order' LIMIT 1";
    $test_order = $wpdb->get_var($query);
    
    if ($test_order) {
        ruiyi_debug_log('数据库中至少有一个订单: ' . $test_order);
    } else {
        ruiyi_debug_log('数据库中没有找到任何订单');
    }
    
    $orders_query = new WP_Query($args);
    $orders_data = array();
    
    ruiyi_debug_log('查询找到的订单数: ' . $orders_query->found_posts);
    
    if ($orders_query->have_posts()) {
        ruiyi_debug_log('有订单数据');
        while ($orders_query->have_posts()) {
            $orders_query->the_post();
            $order_id = get_the_ID();
            ruiyi_debug_log('处理订单 ID: ' . $order_id);
            
            try {
                $order = wc_get_order($order_id);
                if ($order) {
                    $orders_data[] = array(
                        'id' => $order->get_id(),
                        'status' => wc_get_order_status_name($order->get_status()),
                        'total' => $order->get_total(),
                        'date' => $order->get_date_created()->date_i18n('Y-m-d H:i'),
                        'items_count' => $order->get_item_count(),
                        'items' => array_map(function($item) {
                            return array(
                                'name' => $item->get_name(),
                                'quantity' => $item->get_quantity()
                            );
                        }, $order->get_items())
                    );
                } else {
                    ruiyi_debug_log('无法获取订单对象，ID: ' . $order_id);
                }
            } catch (Exception $e) {
                ruiyi_debug_log('获取订单时发生错误: ' . $e->getMessage());
            }
        }
        wp_reset_postdata();
    } else {
        ruiyi_debug_log('没有找到任何订单');
        
        // 尝试使用直接数据库查询来检查是否有订单
        $test_query = "SELECT COUNT(*) FROM {$wpdb->posts} WHERE post_type = 'shop_order'";
        $count = $wpdb->get_var($test_query);
        ruiyi_debug_log('直接数据库查询发现订单数: ' . $count);
    }
    
    // 如果没有找到订单，检查是否有测试数据，如果没有则创建一些测试订单
    if (empty($orders_data) && defined('WP_DEBUG') && WP_DEBUG) {
        ruiyi_debug_log('没有订单数据，添加一些测试数据');
        
        // 添加一个测试订单
        $test_order_data = array(
            'id' => 999999,
            'status' => '已完成',
            'total' => 123.45,
            'date' => date('Y-m-d H:i'),
            'items_count' => 2,
            'items' => array(
                array('name' => '测试商品1', 'quantity' => 1),
                array('name' => '测试商品2', 'quantity' => 2)
            )
        );
        
        $orders_data[] = $test_order_data;
    }
    
    ruiyi_debug_log('返回订单数据数量: ' . count($orders_data));
    wp_send_json_success(['orders' => $orders_data]);
}

// 添加获取热门产品的AJAX处理函数
add_action('wp_ajax_ruiyi_get_popular_products', 'ruiyi_get_popular_products');
add_action('wp_ajax_nopriv_ruiyi_get_popular_products', 'ruiyi_get_popular_products');
function ruiyi_get_popular_products() {
    // 验证安全检查
    if (!isset($_POST['nonce']) || !wp_verify_nonce($_POST['nonce'], 'ruiyi_pos_nonce')) {
        wp_send_json_error(['message' => ruiyi_translate('Error de seguridad', 'Security error', '安全错误')]);
        return;
    }
    
    // 设置要获取的产品数量
    $limit = 20;
    
    // 热门产品数组
    $popular_products = array();
    
    if (class_exists('WooCommerce')) {
        global $wpdb;
        
        // 修改SQL查询，排除积分产品
        $popular_products_query = $wpdb->prepare("
            SELECT p.ID as product_id, p.post_title as product_name, 
                   COUNT(oi.order_item_id) as order_count
            FROM {$wpdb->posts} p
            INNER JOIN {$wpdb->prefix}woocommerce_order_itemmeta oim ON oim.meta_value = p.ID
            INNER JOIN {$wpdb->prefix}woocommerce_order_items oi ON oi.order_item_id = oim.order_item_id
            LEFT JOIN {$wpdb->postmeta} pm ON p.ID = pm.post_id AND pm.meta_key = '_is_points_product'
            WHERE p.post_type = 'product'
            AND p.post_status = 'publish'
            AND oim.meta_key = '_product_id'
            AND oi.order_item_type = 'line_item'
            AND (pm.meta_value IS NULL OR pm.meta_value != 'yes')
            GROUP BY p.ID
            ORDER BY order_count DESC
            LIMIT %d
        ", $limit);
        
        $popular_products_results = $wpdb->get_results($popular_products_query);
        
        if ($popular_products_results) {
            foreach ($popular_products_results as $product) {
                $wc_product = wc_get_product($product->product_id);
                if ($wc_product) {
                    $popular_products[] = array(
                        'id' => $product->product_id,
                        'name' => $wc_product->get_name(),
                        'price' => $wc_product->get_price(), // 使用产品原始价格
                        'image' => wp_get_attachment_url($wc_product->get_image_id()) ?: ruiyi_get_placeholder_image(),
                        'order_count' => $product->order_count
                    );
                }
            }
        }
    }
    
    wp_send_json_success(['products' => $popular_products]);
}

// 添加一个函数，用于创建测试订单
function ruiyi_create_test_order() {
    if (!function_exists('wc_create_order')) {
        ruiyi_debug_log('无法创建测试订单: WooCommerce不可用');
        return false;
    }
    
    try {
        // 创建订单对象
        $order = wc_create_order();
        
        // 添加一些商品 - 假设有产品ID 1和2
        // 如果没有产品，我们创建一个简单产品
        $product_id = 0;
        
        // 检查是否有现有产品
        $products = get_posts(array(
            'post_type' => 'product',
            'posts_per_page' => 1
        ));
        
        if (!empty($products)) {
            $product_id = $products[0]->ID;
        } else {
            // 创建测试产品
            $test_product = array(
                'post_title' => '测试商品',
                'post_content' => '这是一个测试商品',
                'post_status' => 'publish',
                'post_type' => 'product'
            );
            
            $product_id = wp_insert_post($test_product);
            
            // 设置价格
            update_post_meta($product_id, '_price', '99.99');
            update_post_meta($product_id, '_regular_price', '99.99');
        }
        
        if ($product_id > 0) {
            // 添加产品到订单
            $order->add_product(wc_get_product($product_id), 2); // 添加2个
            
            // 设置订单基础信息
            $address = array(
                'first_name' => '测试',
                'last_name'  => '客户',
                'email'      => 'test@example.com',
                'phone'      => '13800138000',
                'address_1'  => '测试地址',
                'city'       => '测试城市',
                'country'    => 'CN'
            );
            
            $order->set_address($address, 'billing');
            $order->set_address($address, 'shipping');
            
            // 计算总金额并完成订单
            $order->calculate_totals();
            $order->update_status('completed', '测试订单');
            
            ruiyi_debug_log('测试订单创建成功，ID: ' . $order->get_id());
            return $order->get_id();
        } else {
            ruiyi_debug_log('无法获取或创建产品');
            return false;
        }
    } catch (Exception $e) {
        ruiyi_debug_log('创建测试订单时出错: ' . $e->getMessage());
        return false;
    }
}


