/**
 * Get discount statistics for POS system
 */
function ruiyi_get_discount_statistics() {
    if (!is_user_logged_in()) {
        wp_send_json_error(['message' => 'Authentication required']);
        return;
    }

    // Verify nonce for security
    if (!isset($_POST['nonce']) || !wp_verify_nonce($_POST['nonce'], 'ruiyi_pos_nonce')) {
        wp_send_json_error(['message' => 'Invalid security token']);
        wp_die();
    }
    
    // Get date parameters (default to last 30 days if not specified)
    $start_date = isset($_POST['start_date']) && !empty($_POST['start_date'])
        ? sanitize_text_field($_POST['start_date'])
        : date('Y-m-d', strtotime('-30 days'));
    
    $end_date = isset($_POST['end_date']) && !empty($_POST['end_date'])
        ? sanitize_text_field($_POST['end_date'])
        : date('Y-m-d');
    
    // Query orders with discounts
    $args = array(
        'limit' => -1,
        'type' => 'shop_order',
        'status' => ['completed', 'processing'],
        'date_created' => $start_date . '...' . $end_date,
    );
    
    $orders = wc_get_orders($args);
    
    // Initialize statistics
    $stats = array(
        'total_discounts' => 0,
        'total_amount' => 0,
        'average_amount' => 0,
        'max_amount' => 0
    );
    
    foreach ($orders as $order) {
        $order_id = $order->get_id();
        
        // Check for discount
        foreach ($order->get_fees() as $fee) {
            if ($fee->get_name() === 'Descuento POS' && $fee->get_total() < 0) {
                $discount_amount = abs($fee->get_total());
                
                // Update statistics
                $stats['total_discounts']++;
                $stats['total_amount'] += $discount_amount;
                
                // Track maximum discount
                if ($discount_amount > $stats['max_amount']) {
                    $stats['max_amount'] = $discount_amount;
                }
            }
        }
    }
    
    // Calculate average if there are discounts
    if ($stats['total_discounts'] > 0) {
        $stats['average_amount'] = $stats['total_amount'] / $stats['total_discounts'];
    }
    
    wp_send_json_success($stats);
    wp_die();
}
add_action('wp_ajax_get_discount_statistics', 'ruiyi_get_discount_statistics');
add_action('wp_ajax_nopriv_get_discount_statistics', 'ruiyi_get_discount_statistics');

function cargar_bootstrap() {
    // Bootstrap CSS
    wp_enqueue_style('bootstrap-css', 'https://cdn.jsdelivr.net/npm/bootstrap@5.3.2/dist/css/bootstrap.min.css');
    // Bootstrap JS
    wp_enqueue_script('bootstrap-js', 'https://cdn.jsdelivr.net/npm/bootstrap@5.3.2/dist/js/bootstrap.bundle.min.js', array('jquery'), null, true);
}
