// 获取订单列表的AJAX处理函数
add_action('wp_ajax_ruiyi_pos_get_orders', 'ruiyi_pos_get_orders_callback');
function ruiyi_pos_get_orders_callback() {
    // 验证nonce
    if (!isset($_REQUEST['nonce']) || !wp_verify_nonce($_REQUEST['nonce'], 'ruiyi_pos_nonce')) {
        wp_send_json_error(array('message' => 'Verificación de seguridad fallida'));
    }

    // 构建查询参数
    $args = array(
        'limit' => 50,
        'orderby' => 'date',
        'order' => 'DESC',
        'status' => array('any')
    );

    // 添加日期过滤
    if (isset($_REQUEST['after']) && !empty($_REQUEST['after'])) {
        $args['after'] = sanitize_text_field($_REQUEST['after']);
    }
    
    if (isset($_REQUEST['before']) && !empty($_REQUEST['before'])) {
        $args['before'] = sanitize_text_field($_REQUEST['before']);
    }

    // 获取订单
    $orders = wc_get_orders($args);
    $formatted_orders = array();

    foreach ($orders as $order) {
        $formatted_orders[] = $order->get_data();
    }

    // 获取各状态的订单数量
    $counts = array(
        'pending' => wc_orders_count('pending'),
        'processing' => wc_orders_count('processing'),
        'completed' => wc_orders_count('completed'),
        'cancelled' => wc_orders_count('cancelled')
    );

    wp_send_json_success(array(
        'orders' => $formatted_orders,
        'counts' => $counts
    ));
}

// 获取订单详情的AJAX处理函数
add_action('wp_ajax_ruiyi_pos_get_order_details', 'ruiyi_pos_get_order_details_callback');
function ruiyi_pos_get_order_details_callback() {
    // 验证nonce
    if (!isset($_REQUEST['nonce']) || !wp_verify_nonce($_REQUEST['nonce'], 'ruiyi_pos_nonce')) {
        wp_send_json_error(array('message' => 'Verificación de seguridad fallida'));
    }

    // 验证订单ID
    if (!isset($_REQUEST['order_id']) || empty($_REQUEST['order_id'])) {
        wp_send_json_error(array('message' => 'ID de pedido no válido'));
    }

    $order_id = intval($_REQUEST['order_id']);
    $order = wc_get_order($order_id);

    if (!$order) {
        wp_send_json_error(array('message' => 'Pedido no encontrado'));
    }

    // 🔥 构建格式化的订单数据（前端友好格式）
    $line_items = array();
    foreach ($order->get_items() as $item_id => $item) {
        $product = $item->get_product();
        $order_item_total = $item->get_total();
        $order_item_quantity = $item->get_quantity();
        $calculated_price = $order_item_quantity > 0 ? ($order_item_total / $order_item_quantity) : 0;

        $line_items[] = array(
            'id' => $item_id,
            'name' => $item->get_name(),
            'product_id' => $item->get_product_id(),
            'variation_id' => $item->get_variation_id(),
            'quantity' => $item->get_quantity(),
            'subtotal' => number_format($item->get_subtotal(), 2, '.', ''),
            'total' => number_format($item->get_total(), 2, '.', ''),
            'price' => $product ? $product->get_price() : $calculated_price,
            'image_url' => $product ? wp_get_attachment_url($product->get_image_id()) : ''
        );
    }

    // 🔥 获取费用项(fees) - 包括抵扣券、折扣、小费等
    $fees = array();
    foreach ($order->get_fees() as $fee_id => $fee) {
        $fees[] = array(
            'id' => $fee_id,
            'name' => $fee->get_name(),
            'amount' => floatval($fee->get_total()),
            'type' => ($fee->get_total() < 0) ? 'discount' : 'fee'
        );
    }

    // 🔥 获取抵扣券金额(如果有)
    $cheque_restaurante_amount = $order->get_meta('_cheque_restaurante_amount', true);

    // 🔥 获取手动折扣信息
    $manual_discount_percent = $order->get_meta('_manual_discount_percent', true);
    $manual_discount_amount = $order->get_meta('_manual_discount_amount', true);

    // 🔥 获取客户信息（外送订单）
    $customer_info = array(
        'name' => $order->get_meta('_customer_name', true) ?: $order->get_billing_first_name() . ' ' . $order->get_billing_last_name(),
        'phone' => $order->get_meta('_customer_phone', true) ?: $order->get_billing_phone(),
        'address' => $order->get_meta('_customer_address', true) ?: $order->get_billing_address_1(),
        'postal_code' => $order->get_meta('_customer_postal_code', true) ?: $order->get_billing_postcode(),
        'email' => $order->get_billing_email(),
        'business_name' => $order->get_meta('_customer_business_name', true),
        'cif_nif' => $order->get_meta('_customer_cif_nif', true),
        'notes' => $order->get_meta('_customer_notes', true)
    );
    // 过滤掉空值
    $customer_info = array_filter($customer_info, function($v) { return !empty(trim($v ?? '')); });

    // 🔥 添加支付明细信息（现金/刷卡）
    $payment_method = $order->get_meta('_payment_method', true) ?: $order->get_payment_method();

    // 🔥 修复：使用正确的 meta key (_cash_amount 和 _card_amount)
    $cash_amount = $order->get_meta('_cash_amount', true);
    $card_amount = $order->get_meta('_card_amount', true);
    $received_amount = $order->get_meta('_received_amount', true);
    $change_amount = $order->get_meta('_change_amount', true);

    // 🔥 构建完整的订单数据对象
    $order_response = array(
        'id' => $order->get_id(),
        'status' => $order->get_status(),
        'status_name' => wc_get_order_status_name($order->get_status()),
        'date' => $order->get_date_created()->date('Y-m-d'),
        'time' => $order->get_date_created()->date('H:i'),
        'total' => number_format($order->get_total(), 2, '.', ''),
        'subtotal' => number_format($order->get_subtotal(), 2, '.', ''),
        'tax' => number_format($order->get_total_tax(), 2, '.', ''),
        'table_number' => $order->get_meta('_table_number', true),
        'order_type' => $order->get_meta('_order_type', true),
        'customer_note' => $order->get_customer_note(),
        'payment_method' => $order->get_payment_method_title(),
        'items' => $line_items,  // 🔥 使用 items 而不是 line_items
        'fees' => $fees,  // 🔥 添加费用项
        'cheque_restaurante_amount' => $cheque_restaurante_amount ? floatval($cheque_restaurante_amount) : 0,  // 🔥 抵扣券金额
        'discount_percent' => $manual_discount_percent ? floatval($manual_discount_percent) : 0,  // 🔥 手动折扣百分比
        'discount_amount' => $manual_discount_amount ? floatval($manual_discount_amount) : 0,  // 🔥 手动折扣金额
        'customer_info' => !empty($customer_info) ? $customer_info : null,  // 🔥 客户信息（外送订单）
        'payment_details' => array(
            'method' => $payment_method,
            'cash_amount' => $cash_amount ? floatval($cash_amount) : 0,
            'card_amount' => $card_amount ? floatval($card_amount) : 0,
            'received_amount' => $received_amount ? floatval($received_amount) : 0,
            'change_amount' => $change_amount ? floatval($change_amount) : 0,
            'is_mixed' => ($payment_method === 'mixed')
        )
    );

    ruiyi_debug_log('[订单详情API] 返回数据: ' . json_encode($order_response['payment_details']));

    wp_send_json_success($order_response);
}

// 搜索订单的AJAX处理函数
add_action('wp_ajax_ruiyi_pos_search_orders', 'ruiyi_pos_search_orders_callback');
function ruiyi_pos_search_orders_callback() {
    // 验证nonce
    if (!isset($_REQUEST['nonce']) || !wp_verify_nonce($_REQUEST['nonce'], 'ruiyi_pos_nonce')) {
        wp_send_json_error(array('message' => 'Verificación de seguridad fallida'));
    }

    // 验证查询参数
    if (!isset($_REQUEST['query']) || empty($_REQUEST['query'])) {
        wp_send_json_error(array('message' => 'Consulta de búsqueda no válida'));
    }

    $query = sanitize_text_field($_REQUEST['query']);
    
    // 构建查询
    $args = array(
        'limit' => 50,
        'orderby' => 'date',
        'order' => 'DESC',
        'status' => array('any')
    );

    // 如果查询是数字，可能是订单号
    if (is_numeric($query)) {
        $args['number'] = $query;
    } else {
        // 否则搜索元数据（如桌号）
        $args['meta_query'] = array(
            array(
                'key' => '_table_number',
                'value' => $query,
                'compare' => 'LIKE'
            )
        );
    }

    // 获取订单
    $orders = wc_get_orders($args);
    $formatted_orders = array();

    foreach ($orders as $order) {
        // 过滤非收银系统订单
        $order_source = $order->get_meta('_ruiyi_order_source');
        if ($order_source && $order_source !== '收银系统') {
            continue;
        }
        $formatted_orders[] = $order->get_data();
    }

    wp_send_json_success(array('orders' => $formatted_orders));
}

// 更新订单状态的AJAX处理函数
add_action('wp_ajax_ruiyi_pos_update_order_status', 'ruiyi_pos_update_order_status_callback');
function ruiyi_pos_update_order_status_callback() {
    // 验证nonce
    if (!isset($_REQUEST['nonce']) || !wp_verify_nonce($_REQUEST['nonce'], 'ruiyi_pos_nonce')) {
        wp_send_json_error(array('message' => 'Verificación de seguridad fallida'));
    }

    // 验证订单ID和状态
    if (!isset($_REQUEST['order_id']) || empty($_REQUEST['order_id']) ||
        !isset($_REQUEST['status']) || empty($_REQUEST['status'])) {
        wp_send_json_error(array('message' => 'Parámetros inválidos'));
    }

    $order_id = intval($_REQUEST['order_id']);
    $status = sanitize_text_field($_REQUEST['status']);
    
    // 获取订单
    $order = wc_get_order($order_id);
    
    if (!$order) {
        wp_send_json_error(array('message' => 'Pedido no encontrado'));
    }
    
    // 更新状态
    $order->update_status($status, 'Estado actualizado desde POS por ' . wp_get_current_user()->display_name);

    wp_send_json_success(array('message' => 'Estado actualizado correctamente'));
}

// 🔥 更新订单产品数量（用于修改锁定产品的数量）
if (!function_exists('ruiyi_pos_sync_kitchen_printed_qty_meta')) {
    function ruiyi_pos_sync_kitchen_printed_qty_meta($item_id, $new_quantity, $item_data = array(), $is_existing_item = true) {
        $item_id = intval($item_id);
        $new_quantity = max(0, intval($new_quantity));

        if ($item_id <= 0) {
            return;
        }

        $added_qty = isset($item_data['added_quantity']) ? max(0, intval($item_data['added_quantity'])) : 0;
        $previous_qty = isset($item_data['previous_quantity'])
            ? max(0, intval($item_data['previous_quantity']))
            : max(0, $new_quantity - $added_qty);

        $printed_raw = wc_get_order_item_meta($item_id, '_kitchen_printed_qty', true);
        $has_printed_meta = ($printed_raw !== '' && $printed_raw !== null);
        $current_printed = $has_printed_meta ? max(0, intval($printed_raw)) : null;

        if ($is_existing_item) {
            if ($added_qty > 0) {
                $baseline = max($previous_qty, $new_quantity - $added_qty);
                if ($current_printed !== null) {
                    $baseline = max($baseline, $current_printed);
                }
                wc_update_order_item_meta($item_id, '_kitchen_printed_qty', min($baseline, $new_quantity));
                return;
            }

            if ($current_printed === null) {
                wc_update_order_item_meta($item_id, '_kitchen_printed_qty', $new_quantity);
                return;
            }

            if ($current_printed > $new_quantity) {
                wc_update_order_item_meta($item_id, '_kitchen_printed_qty', $new_quantity);
            }
            return;
        }

        if ($added_qty > 0 && $added_qty < $new_quantity) {
            wc_update_order_item_meta($item_id, '_kitchen_printed_qty', $new_quantity - $added_qty);
        }
    }
}

if (!function_exists('ruiyi_pos_get_kitchen_printed_qty_for_merge')) {
    function ruiyi_pos_get_kitchen_printed_qty_for_merge($item_id, $quantity) {
        $quantity = max(0, intval($quantity));
        $printed_raw = wc_get_order_item_meta($item_id, '_kitchen_printed_qty', true);

        if ($printed_raw === '' || $printed_raw === null) {
            return $quantity;
        }

        return min($quantity, max(0, intval($printed_raw)));
    }
}

add_action('wp_ajax_ruiyi_pos_update_order_items', 'ruiyi_pos_update_order_items_callback');
function ruiyi_pos_update_order_items_callback() {
    // 验证nonce
    if (!isset($_REQUEST['nonce']) || !wp_verify_nonce($_REQUEST['nonce'], 'ruiyi_pos_nonce')) {
        wp_send_json_error(array('message' => '安全验证失败'));
        return;
    }

    // 验证订单ID
    if (!isset($_REQUEST['order_id']) || empty($_REQUEST['order_id'])) {
        wp_send_json_error(array('message' => '缺少订单ID'));
        return;
    }

    // 验证产品数据
    if (!isset($_REQUEST['items']) || empty($_REQUEST['items'])) {
        wp_send_json_error(array('message' => '缺少产品数据'));
        return;
    }

    $order_id = intval($_REQUEST['order_id']);
    $items = json_decode(stripslashes($_REQUEST['items']), true);

    // 🔥 获取所有相关订单ID（用于合并多订单场景）
    $all_order_ids = array($order_id);
    if (isset($_REQUEST['all_order_ids']) && !empty($_REQUEST['all_order_ids'])) {
        $all_order_ids = json_decode(stripslashes($_REQUEST['all_order_ids']), true);
        if (!is_array($all_order_ids)) {
            $all_order_ids = array($order_id);
        }
    }

    if (!is_array($items)) {
        wp_send_json_error(array('message' => '产品数据格式错误'));
        return;
    }

    // 获取主订单
    $order = wc_get_order($order_id);
    if (!$order) {
        wp_send_json_error(array('message' => '订单不存在'));
        return;
    }

    // 只能修改处于 pending、on-hold 或 processing 状态的订单
    $status = $order->get_status();
    if (!in_array($status, ['pending', 'on-hold', 'processing'])) {
        wp_send_json_error(array('message' => '订单状态不允许修改: ' . $status));
        return;
    }

    try {
        ruiyi_debug_log('[ruiyi_pos_update_order_items] 开始更新订单 #' . $order_id . ', 产品数量: ' . count($items) . ', 所有订单: ' . implode(',', $all_order_ids));

        // 🔥🔥🔥 关键修复：先合并订单中相同 product_id + 价格 的重复订单项
        // 原因：可能存在多个相同产品的订单项（如AA分单结账后），需要先合并避免数量翻倍
        // 🔥 改进：同一产品不同价格不合并（如优惠价/原价应分开）
        $product_items_map = array(); // "product_id_price" => [first_item_id, total_quantity, unit_price, printed_quantity]
        $duplicate_item_ids = array(); // 需要删除的重复订单项ID

        foreach ($order->get_items() as $item_id => $order_item) {
            $pid = $order_item->get_product_id();
            $qty = $order_item->get_quantity();
            $printed_qty = ruiyi_pos_get_kitchen_printed_qty_for_merge($item_id, $qty);
            // 🔥 计算单价（总价/数量），保留2位小数作为key的一部分
            $unit_price = $qty > 0 ? round($order_item->get_total() / $qty, 2) : 0;
            // 使用 product_id + 单价 作为唯一键，确保不同价格的产品不被合并
            $key = $pid . '_' . number_format($unit_price, 2, '.', '');

            if (isset($product_items_map[$key])) {
                // 已存在相同产品+相同价格，标记为重复需删除
                $duplicate_item_ids[] = $item_id;
                // 累加数量到第一个订单项
                $product_items_map[$key]['total_quantity'] += $qty;
                $product_items_map[$key]['printed_quantity'] += $printed_qty;
                $product_items_map[$key]['had_duplicate'] = true;
                ruiyi_debug_log('[ruiyi_pos_update_order_items] 发现重复产品 #' . $pid . ' (价格=' . $unit_price . '), 订单项 #' . $item_id . ' 将被合并');
            } else {
                // 第一次遇到此产品+价格组合
                $product_items_map[$key] = array(
                    'first_item_id' => $item_id,
                    'total_quantity' => $qty,
                    'unit_price' => $unit_price,
                    'printed_quantity' => $printed_qty,
                    'had_duplicate' => false
                );
            }
        }

        // 删除重复的订单项（保留第一个）
        foreach ($duplicate_item_ids as $dup_item_id) {
            $order->remove_item($dup_item_id);
            ruiyi_debug_log('[ruiyi_pos_update_order_items] 🗑️ 已删除重复订单项 #' . $dup_item_id);
        }

        foreach ($product_items_map as $merge_info) {
            if (empty($merge_info['had_duplicate']) || empty($merge_info['first_item_id'])) {
                continue;
            }

            $merged_printed_qty = min(
                max(0, intval($merge_info['total_quantity'])),
                max(0, intval($merge_info['printed_quantity']))
            );
            wc_update_order_item_meta($merge_info['first_item_id'], '_kitchen_printed_qty', $merged_printed_qty);
            ruiyi_debug_log('[ruiyi_pos_update_order_items] ✅ 合并保留厨房已打印数量: item #' . $merge_info['first_item_id'] . ' = ' . $merged_printed_qty . '/' . intval($merge_info['total_quantity']));
        }

        // 如果有重复项被删除，保存订单
        if (count($duplicate_item_ids) > 0) {
            $order->save();
            // 重新加载订单以获取更新后的订单项
            $order = wc_get_order($order_id);
            ruiyi_debug_log('[ruiyi_pos_update_order_items] ✅ 已合并 ' . count($duplicate_item_ids) . ' 个重复订单项');
        }

        // 🔥🔥🔥 创建产品ID到请求数据的映射
        // 注意：对于锁定商品的更新，使用 product_id 匹配，允许价格变更
        // 如果同一 product_id 有多个条目，存储为数组
        $items_by_product_id = array();
        foreach ($items as $item_data) {
            $product_id = isset($item_data['product_id']) ? intval($item_data['product_id']) : 0;
            if ($product_id > 0) {
                if (!isset($items_by_product_id[$product_id])) {
                    $items_by_product_id[$product_id] = array();
                }
                $items_by_product_id[$product_id][] = $item_data;
            }
        }

        ruiyi_debug_log('[ruiyi_pos_update_order_items] 请求中的产品ID: ' . implode(',', array_keys($items_by_product_id)));

        // 🔥🔥🔥 遍历现有订单项，更新或删除（使用 product_id 匹配，允许价格变更）
        $updated_product_ids = array(); // 已更新的产品ID
        $used_request_indices = array(); // 已使用的请求数据索引 (product_id => [index1, index2, ...])
        $kept_items_total = 0;

        foreach ($order->get_items() as $item_id => $order_item) {
            $order_product_id = $order_item->get_product_id();
            $order_qty = $order_item->get_quantity();
            $order_unit_price = $order_qty > 0 ? round($order_item->get_total() / $order_qty, 2) : 0;

            if (isset($items_by_product_id[$order_product_id])) {
                // 🔥 找到匹配的产品ID，从请求数组中获取一个未使用的条目
                $request_items = $items_by_product_id[$order_product_id];
                $used_indices = isset($used_request_indices[$order_product_id]) ? $used_request_indices[$order_product_id] : array();

                $item_data = null;
                $used_index = -1;
                foreach ($request_items as $idx => $req_item) {
                    if (in_array($idx, $used_indices)) {
                        continue;
                    }

                    $requested_item_id = isset($req_item['item_id']) ? intval($req_item['item_id']) : 0;
                    if (!$requested_item_id && isset($req_item['order_item_id'])) {
                        $requested_item_id = intval($req_item['order_item_id']);
                    }

                    if ($requested_item_id > 0 && $requested_item_id === intval($item_id)) {
                        $item_data = $req_item;
                        $used_index = $idx;
                        break;
                    }
                }

                if ($item_data === null) {
                    foreach ($request_items as $idx => $req_item) {
                        if (!in_array($idx, $used_indices)) {
                            $item_data = $req_item;
                            $used_index = $idx;
                            break;
                        }
                    }
                }

                if ($item_data === null) {
                    // 所有请求条目都已使用，说明订单中有多余的同产品项，删除
                    $order->remove_item($item_id);
                    ruiyi_debug_log('[ruiyi_pos_update_order_items] 删除多余产品 #' . $order_product_id . ' (请求中无更多条目)');
                    continue;
                }

                // 标记此请求条目为已使用
                if (!isset($used_request_indices[$order_product_id])) {
                    $used_request_indices[$order_product_id] = array();
                }
                $used_request_indices[$order_product_id][] = $used_index;

                $new_quantity = isset($item_data['quantity']) ? floatval($item_data['quantity']) : 1;
                $new_price = isset($item_data['price']) ? floatval($item_data['price']) : $order_unit_price;

                if ($new_quantity <= 0) {
                    // 数量为0，删除此订单项
                    $order->remove_item($item_id);
                    ruiyi_debug_log('[ruiyi_pos_update_order_items] 删除产品 #' . $order_product_id . ' (数量为0)');
                } else {
                    // 更新数量和价格（允许价格从原价更新为自定义价格）
                    $order_item->set_quantity($new_quantity);
                    $order_item->set_subtotal($new_price * $new_quantity);
                    $order_item->set_total($new_price * $new_quantity);

                    // 🔥🔥🔥 更新自定义名称（如果前端传递了custom_name）
                    if (isset($item_data['custom_name']) && !empty($item_data['custom_name'])) {
                        $custom_name = sanitize_text_field($item_data['custom_name']);
                        $order_item->set_name($custom_name);
                        // 🔥 关键修复：保存元数据，以便订单ID模式下能识别自定义名称
                        $product = wc_get_product($order_product_id);
                        if ($product) {
                            wc_update_order_item_meta($item_id, '_has_custom_name', 'yes');
                            wc_update_order_item_meta($item_id, '_original_name', $product->get_name());
                        }
                        ruiyi_debug_log('[ruiyi_pos_update_order_items] 更新产品名称: ' . $custom_name);
                    }

                    // 🔥 保存配料数据到订单项元数据
                    ruiyi_debug_log('[ruiyi_pos_update_order_items] 🔍 检查配料数据: item_id=' . $item_id . ' supplements=' . var_export($item_data['supplements'] ?? 'KEY_NOT_EXISTS', true) . ' original_name=' . var_export($item_data['original_name'] ?? 'N/A', true));
                    if (isset($item_data['supplements']) && !empty($item_data['supplements'])) {
                        wc_update_order_item_meta($item_id, '_item_supplements', $item_data['supplements']);
                        ruiyi_debug_log('[ruiyi_pos_update_order_items] ✅ 保存配料数据: ' . $item_data['supplements']);
                    } else {
                        // 清除配料数据（如果配料被移除）
                        wc_delete_order_item_meta($item_id, '_item_supplements');
                    }
                    // 🔥 保存原始名称和价格（不含配料）
                    if (isset($item_data['original_name']) && !empty($item_data['original_name'])) {
                        wc_update_order_item_meta($item_id, '_supplement_original_name', sanitize_text_field($item_data['original_name']));
                    }
                    if (isset($item_data['original_price']) && $item_data['original_price'] !== null) {
                        wc_update_order_item_meta($item_id, '_supplement_original_price', floatval($item_data['original_price']));
                    }

                    ruiyi_pos_sync_kitchen_printed_qty_meta($item_id, $new_quantity, $item_data, true);
                    $order_item->save();
                    $kept_items_total += $new_price * $new_quantity;
                    ruiyi_debug_log('[ruiyi_pos_update_order_items] 更新产品 #' . $order_product_id . ': 原价=' . $order_unit_price . ' → 新价=' . $new_price . ', 数量=' . $new_quantity);
                }

                $updated_product_ids[] = $order_product_id;
            } else {
                // 🔥🔥🔥 产品ID不在请求列表中
                // 策略：保留这些项目（可能是通过 create_order 新添加的，或网络问题导致前端未发送）
                // 只有明确标记数量为0的才删除
                $explicit_delete = false;
                foreach ($items as $check_item) {
                    $check_pid = isset($check_item['product_id']) ? intval($check_item['product_id']) : 0;
                    $check_qty = isset($check_item['quantity']) ? floatval($check_item['quantity']) : 1;
                    if ($check_pid === $order_product_id && $check_qty <= 0) {
                        $explicit_delete = true;
                        break;
                    }
                }

                if ($explicit_delete) {
                    $order->remove_item($item_id);
                    ruiyi_debug_log('[ruiyi_pos_update_order_items] 删除产品 #' . $order_product_id . ' (前端明确标记数量为0)');
                } else {
                    // 保留不在请求列表中的产品
                    $kept_items_total += $order_item->get_total();
                    ruiyi_debug_log('[ruiyi_pos_update_order_items] 保留产品 #' . $order_product_id . ' 价格=' . $order_unit_price . ' (不在请求列表，保留)');
                }
            }
        }

        // 🔥🔥🔥 添加请求中未被使用的条目（订单中没有足够的同产品项来匹配）
        foreach ($items_by_product_id as $product_id => $request_items) {
            $used_indices = isset($used_request_indices[$product_id]) ? $used_request_indices[$product_id] : array();

            foreach ($request_items as $idx => $item_data) {
                // 跳过已使用的条目
                if (in_array($idx, $used_indices)) {
                    continue;
                }

                $quantity = isset($item_data['quantity']) ? floatval($item_data['quantity']) : 1;
                $price = isset($item_data['price']) ? round(floatval($item_data['price']), 2) : 0;
                $name = isset($item_data['name']) ? sanitize_text_field($item_data['name']) : '';

                if ($quantity > 0) {
                    // 创建新订单项
                    $item = new WC_Order_Item_Product();
                    $product = wc_get_product($product_id);
                    $custom_name = isset($item_data['custom_name']) ? sanitize_text_field($item_data['custom_name']) : '';

                    if ($product) {
                        $item->set_product($product);
                        // 🔥 优先使用自定义名称，否则使用请求中的name，最后使用产品原名称
                        $final_name = $custom_name ?: ($name ?: $product->get_name());
                        $item->set_name($final_name);
                    } else {
                        $item->set_name($custom_name ?: ($name ?: '产品 #' . $product_id));
                    }
                    $item->set_product_id($product_id);
                    $item->set_quantity($quantity);
                    $item->set_subtotal($price * $quantity);
                    $item->set_total($price * $quantity);
                    $new_item_id = $order->add_item($item);
                    if ($new_item_id) {
                        ruiyi_pos_sync_kitchen_printed_qty_meta($new_item_id, $quantity, $item_data, false);
                    }

                    // 🔥🔥🔥 关键修复：如果有自定义名称，保存元数据
                    if ($custom_name && $new_item_id && $product) {
                        wc_update_order_item_meta($new_item_id, '_has_custom_name', 'yes');
                        wc_update_order_item_meta($new_item_id, '_original_name', $product->get_name());
                    }

                    $kept_items_total += $price * $quantity;
                    ruiyi_debug_log('[ruiyi_pos_update_order_items] 添加新产品 #' . $product_id . ' 价格=' . $price . ': 数量=' . $quantity . ($custom_name ? ' (自定义名称: ' . $custom_name . ')' : ''));
                }
            }
        }

        // 重新计算订单总额
        $order->calculate_totals();
        $new_total = $order->get_total();

        // 🔥🔥🔥 【2026-04-10 关键修复】检查订单是否已空（所有商品数量设为0）
        // 如果订单无商品，直接删除订单并释放桌位，防止刷新后空订单导致桌位重新变为"占用"
        $remaining_items = $order->get_items();
        if (empty($remaining_items)) {
            ruiyi_debug_log('[ruiyi_pos_update_order_items] 🗑️ 订单 #' . $order_id . ' 所有商品已删除，删除空订单');

            // 清除桌位状态
            $table_number = $order->get_meta('_table_number');
            if ($table_number) {
                $order->delete_meta_data('_table_number');
                $order->save_meta_data();
                ruiyi_debug_log('[ruiyi_pos_update_order_items] 🗑️ 已清除桌位 ' . $table_number . ' 的关联');
            }

            // 删除空订单
            $order->delete(true);

            wp_send_json_success(array(
                'message' => '订单已清空并删除',
                'order_id' => $order_id,
                'order_deleted' => true,
                'table_number' => $table_number,
                'new_total' => 0
            ));
            return;
        }

        $order->add_order_note('POS: 订单产品数量已更新，新总额: €' . number_format($new_total, 2));
        $order->save();

        ruiyi_debug_log('[ruiyi_pos_update_order_items] ✅ 订单 #' . $order_id . ' 更新成功，新总额: ' . $new_total);

        // 🔥 删除其他多余的订单（合并多订单场景）
        $deleted_orders = array();
        if (count($all_order_ids) > 1) {
            foreach ($all_order_ids as $other_order_id) {
                $other_order_id = intval($other_order_id);
                if ($other_order_id > 0 && $other_order_id != $order_id) {
                    $other_order = wc_get_order($other_order_id);
                    if ($other_order) {
                        $other_status = $other_order->get_status();
                        // 只删除 pending、on-hold 或 processing 状态的订单
                        if (in_array($other_status, ['pending', 'on-hold', 'processing'])) {
                            // 永久删除订单
                            $other_order->delete(true); // WC 原生删除，兼容 HPOS
                            $deleted_orders[] = $other_order_id;
                            ruiyi_debug_log('[ruiyi_pos_update_order_items] 🗑️ 已删除多余订单 #' . $other_order_id);
                        }
                    }
                }
            }
        }

        wp_send_json_success(array(
            'message' => '订单已更新',
            'order_id' => $order_id,
            'new_total' => $new_total,
            'deleted_orders' => $deleted_orders
        ));

    } catch (Exception $e) {
        wp_send_json_error(array('message' => '更新失败: ' . $e->getMessage()));
    }
}

// 打印订单功能
add_action('wp_ajax_ruiyi_pos_print_order', 'ruiyi_pos_print_order_callback');
function ruiyi_pos_print_order_callback() {
    // 验证nonce
    if (!isset($_REQUEST['nonce']) || !wp_verify_nonce($_REQUEST['nonce'], 'ruiyi_pos_nonce')) {
        wp_die('Verificación de seguridad fallida');
    }

    // 验证订单ID
    if (!isset($_REQUEST['order_id']) || empty($_REQUEST['order_id'])) {
        wp_die('ID de pedido no válido');
    }

    $order_id = intval($_REQUEST['order_id']);
    $order = wc_get_order($order_id);

    if (!$order) {
        wp_die('Pedido no encontrado');
    }

    // 生成打印视图
    include(plugin_dir_path(__FILE__) . 'impresion.php');
    exit;
}

add_action('wp_ajax_login_social_wp', 'ruiyi_handle_social_login');
add_action('wp_ajax_nopriv_login_social_wp', 'ruiyi_handle_social_login');

function ruiyi_handle_social_login() {
  check_ajax_referer('ruiyi_pos_nonce', 'nonce');

  $email = sanitize_email($_POST['email']);
  $name = sanitize_text_field($_POST['name']);

  if (!is_email($email)) {
    wp_send_json_error(['message' => 'Correo inválido.']);
  }

  $user = get_user_by('email', $email);

  if (!$user) {
    // Crear usuario automáticamente
    $random_password = wp_generate_password(12, false);
    $user_id = wp_create_user($email, $random_password, $email);
    if (is_wp_error($user_id)) {
      wp_send_json_error(['message' => 'No se pudo crear el usuario.']);
    }
    wp_update_user([
      'ID' => $user_id,
      'display_name' => $name
    ]);
    $user = get_user_by('id', $user_id);
  }

  // Iniciar sesión
  wp_set_current_user($user->ID);
  wp_set_auth_cookie($user->ID, true); // true = sesión persistente

  wp_send_json_success([
    'redirect' => home_url('/cliente-carrito-app-home') // Cambia si tu app tiene otra URL
  ]);
}

