add_action('wp_ajax_pos_saas_get_last_ticket', 'pos_saas_get_last_ticket_callback');
add_action('wp_ajax_nopriv_pos_saas_get_last_ticket', 'pos_saas_get_last_ticket_callback');

function pos_saas_get_last_ticket_callback() {
    check_ajax_referer('pos_saas_impresora_nonce', 'security');

    // Obtener el último pedido creado (puedes modificar el estado según tus necesidades)
    $args = [
        'limit' => 1,
        'orderby' => 'date',
        'order' => 'DESC',
        'status' => ['processing', 'completed'], // Ajusta si usas otro estado
    ];

    $orders = wc_get_orders($args);

    if (empty($orders)) {
        wp_send_json_error(['message' => 'No hay pedidos recientes para imprimir.']);
    }

    $order = $orders[0];

    // Construir el texto del ticket
    $ticket = "RUIYI RESTAURANTE\n";
    $ticket .= "-------------------------\n";
    $ticket .= "PEDIDO #" . $order->get_order_number() . "\n";
    // 使用非本地化的日期格式
    $order_date = $order->get_date_created();
    $ticket .= "Fecha: " . $order_date->date('m-d-Y H:i') . "\n";
    $ticket .= "-------------------------\n";

    foreach ($order->get_items() as $item) {
        $name = $item->get_name();
        $qty = $item->get_quantity();
        $total = wc_price($item->get_total(), ['currency' => $order->get_currency()]);
        $ticket .= "$name x$qty - $total\n";
    }

    $ticket .= "-------------------------\n";
    $ticket .= "Total: " . wc_price($order->get_total(), ['currency' => $order->get_currency()]) . "\n";
    $ticket .= "Método: " . $order->get_payment_method_title() . "\n";
    $ticket .= "-------------------------\n";
    $ticket .= "¡Gracias por su compra!\n";

    wp_send_json_success(['ticket' => $ticket]);
}

add_action('wp_ajax_ruiyi_pos_complete_order', 'ruiyi_pos_complete_order_callback');
add_action('wp_ajax_nopriv_ruiyi_pos_complete_order', 'ruiyi_pos_complete_order_callback'); // 如果非登录用户也需要访问

function ruiyi_pos_complete_order_callback() {
    if (!is_user_logged_in()) {
        wp_send_json_error(['message' => 'Authentication required']);
        return;
    }

    // 添加调试日志
    ruiyi_debug_log('ruiyi_pos_complete_order_callback 开始执行');
    ruiyi_debug_log('接收到的POST数据: ' . print_r($_POST, true));

    // 1. 安全性检查：验证 Nonce
    if (!isset($_POST['nonce']) || !wp_verify_nonce(sanitize_text_field($_POST['nonce']), 'ruiyi_pos_nonce')) {
        ruiyi_debug_log('Nonce 验证失败');
        wp_send_json_error(['message' => '安全验证失败 (Nonce 无效)。'], 403);
        return;
    }

    // 2. 获取并清理参数
    $order_id = isset($_POST['order_id']) ? intval($_POST['order_id']) : 0;
    $payment_method = isset($_POST['payment_method']) ? sanitize_text_field($_POST['payment_method']) : '';
    $received_amount = isset($_POST['received_amount']) ? floatval($_POST['received_amount']) : 0;
    $change_amount = isset($_POST['change_amount']) ? floatval($_POST['change_amount']) : 0;
    $table_number = isset($_POST['table_number']) ? sanitize_text_field($_POST['table_number']) : '';
    
    // 打印接收到的参数以便调试
    ruiyi_debug_log("订单ID: $order_id, 支付方式: $payment_method, 餐桌号: $table_number");

    // 3. 检查必要参数是否存在
    if (empty($order_id)) {
        ruiyi_debug_log('缺少订单ID参数');
        wp_send_json_error(['message' => '请求参数不完整 (订单ID缺失)。'], 400);
        return;
    }
    
    if (empty($payment_method)) {
        ruiyi_debug_log('缺少支付方式参数');
        wp_send_json_error(['message' => '请求参数不完整 (支付方式缺失)。'], 400);
        return;
    }
    
    if (empty($table_number)) {
        ruiyi_debug_log('缺少餐桌号参数');
        wp_send_json_error(['message' => '请求参数不完整 (餐桌号缺失)。'], 400);
        return;
    }

    // 4. 执行订单完成的逻辑
    $order = wc_get_order($order_id);
    if (!$order) {
        ruiyi_debug_log("找不到订单，ID: $order_id");
        wp_send_json_error(['message' => "未找到指定的订单：$order_id"], 404);
        return;
    }
    
    try {
        // 更新订单状态
        $order->update_status('completed', __('订单已通过POS完成支付。', 'ruiyi-pos'));
        
        // 记录支付相关信息
        $order->add_order_note(sprintf(
            __('POS支付详情：方式 - %s, 实收 - %s, 找零 - %s, 餐桌 - %s', 'ruiyi-pos'),
            $payment_method,
            wc_price($received_amount),
            wc_price($change_amount),
            $table_number
        ));
        
        // 设置支付方式
        $payment_method_id = $payment_method;
        $payment_method_title = ucfirst($payment_method);

        if (strtolower($payment_method) === 'cash' || strtolower($payment_method) === 'efectivo') {
            $payment_method_id = 'cod'; // Cash on Delivery
            $payment_method_title = __('Efectivo', 'ruiyi-pos');
        } elseif (strtolower($payment_method) === 'card' || strtolower($payment_method) === 'tarjeta') {
            $payment_method_id = 'bacs'; // Bank Transfer
            $payment_method_title = __('Tarjeta', 'ruiyi-pos');
        }
        
        $order->set_payment_method($payment_method_id);
        $order->set_payment_method_title($payment_method_title);
        
        // 保存餐桌号 - 使用正确的元数据键
        if (!empty($table_number)) {
            $order->update_meta_data('_table_number', $table_number);
            // 为确保兼容性，也使用无下划线版本的键
            $order->update_meta_data('table_number', $table_number);
            ruiyi_debug_log("已保存餐桌号: $table_number 到订单元数据");
        }

        // 保存订单
        $order->save();
        ruiyi_debug_log("订单 $order_id 更新成功");

        // 更新桌位状态为可用 (单订单结账)
        $table_status_updated = false;
        if (!empty($table_number)) {
            // 提取桌号中的数字部分
            $table_number_numeric = preg_replace('/[^0-9]/', '', $table_number);
            
            if (!empty($table_number_numeric)) {
                // 🔥 原子更新实时桌位状态（防止并发竞态）
                ruiyi_update_single_table_status($table_number_numeric, array(
                    'status' => 'libre',
                    'orderId' => 0,
                    'total' => 0,
                    'timestamp' => time()
                ));
                ruiyi_debug_log("桌位 {$table_number_numeric} 已更新为空闲状态 (单订单结账)");
                $table_status_updated = true;
            }
        }

        wp_send_json_success([
            'message' => '订单处理成功！',
            'order_id' => $order_id,
            'table_number' => $table_number,
            'table_status_updated' => $table_status_updated
        ]);
    } catch (Exception $e) {
        ruiyi_debug_log('处理订单时发生异常: ' . $e->getMessage());
        wp_send_json_error([
            'message' => '处理订单时发生错误: ' . $e->getMessage(),
            'order_id' => $order_id
        ], 500);
    }

    wp_die();
}

// 厨房完成外送/外带订单的AJAX处理函数
add_action('wp_ajax_complete_woocommerce_order', 'ruiyi_complete_woocommerce_order_callback');
add_action('wp_ajax_nopriv_complete_woocommerce_order', 'ruiyi_complete_woocommerce_order_callback');

function ruiyi_complete_woocommerce_order_callback() {
    // 安全验证
    if (!isset($_POST['nonce']) || !wp_verify_nonce($_POST['nonce'], 'complete_order_nonce')) {
        wp_send_json_error(['message' => ruiyi_translate('Error de seguridad', 'Security error', '安全验证错误')]);
        return;
    }
    
    // 检查用户权限
    if (!is_user_logged_in()) {
        wp_send_json_error(['message' => ruiyi_translate('Debes iniciar sesión', 'Must be logged in', '必须登录')]);
        return;
    }
    
    $user = wp_get_current_user();
    $allowed_roles = ['administrator', 'chef', 'cook'];
    if (!array_intersect($allowed_roles, $user->roles)) {
        wp_send_json_error(['message' => ruiyi_translate('Permisos insuficientes', 'Insufficient permissions', '权限不足')]);
        return;
    }
    
    // 获取订单ID
    $order_id = isset($_POST['order_id']) ? intval($_POST['order_id']) : 0;
    if (empty($order_id)) {
        wp_send_json_error(['message' => ruiyi_translate('ID de pedido inválido', 'Invalid order ID', '无效的订单ID')]);
        return;
    }
    
    // 获取WooCommerce订单
    $order = wc_get_order($order_id);
    if (!$order) {
        wp_send_json_error(['message' => ruiyi_translate('Pedido no encontrado', 'Order not found', '订单未找到')]);
        return;
    }
    
    try {
        // 记录日志
        ruiyi_debug_log("厨房完成订单: $order_id, 当前状态: " . $order->get_status());

        // 获取订单类型
        $order_type = $order->get_meta('_order_type', true);
        $needs_kitchen_prep = $order->get_meta('_needs_kitchen_preparation', true);

        // 检查订单是否可以被厨房标记完成
        $can_complete = false;
        if (in_array($order->get_status(), ['processing', 'on-hold'])) {
            // 处理中的订单可以被完成
            $can_complete = true;
        } elseif ($order->get_status() === 'completed' && $needs_kitchen_prep === 'yes') {
            // 已完成但需要厨房准备的外卖订单
            $can_complete = true;
        }

        if (!$can_complete) {
            wp_send_json_error([
                'message' => ruiyi_translate(
                    'El pedido no puede ser completado en su estado actual',
                    'Order cannot be completed in its current status',
                    '订单当前状态无法完成'
                )
            ]);
            return;
        }
        
        // 获取订单的自定义元数据来确定订单类型
        $order_type = $order->get_meta('_order_type', true);
        
        // 如果没有存储订单类型，尝试从配送方式判断
        if (empty($order_type)) {
            $shipping_methods = $order->get_shipping_methods();
            foreach ($shipping_methods as $shipping_method) {
                $method_id = $shipping_method->get_method_id();
                if (strpos($method_id, 'delivery') !== false || strpos($method_id, 'shipping') !== false) {
                    $order_type = 'delivery';
                    break;
                } elseif (strpos($method_id, 'pickup') !== false || strpos($method_id, 'llevar') !== false) {
                    $order_type = 'llevar';
                    break;
                }
            }
        }
        
        // 标记为厨房已完成
        $order->update_meta_data('_kitchen_completed', 'yes');
        $order->update_meta_data('completed_by_kitchen', true);
        $order->update_meta_data('completed_time', current_time('mysql'));

        // 如果是外卖订单且有需要厨房准备的标记，移除该标记
        if ($order_type === 'llevar' && $needs_kitchen_prep === 'yes') {
            $order->delete_meta_data('_needs_kitchen_preparation');
            ruiyi_debug_log("厨房完成外卖订单: $order_id, 移除厨房准备标记");

            // 外卖订单已经是完成状态，不需要再更新状态
            $order->add_order_note(ruiyi_translate(
                'Pedido para llevar preparado en cocina',
                'Takeaway order prepared in kitchen',
                '外卖订单已在厨房准备完成'
            ));

            $order->save();

            wp_send_json_success([
                'message' => ruiyi_translate(
                    'Pedido para llevar preparado',
                    'Takeaway order prepared',
                    '外卖订单准备完成'
                ),
                'auto_completed' => false,
                'order_type' => $order_type
            ]);
            return;
        }

        // 堂食订单的正常处理流程
        if ($order_type === 'servir' || empty($order_type)) {
            // 堂食订单更新状态为已完成
            $order->update_status('completed', ruiyi_translate(
                'Completado desde cocina',
                'Completed from kitchen',
                '从厨房完成订单'
            ));
        } elseif ($order_type === 'delivery') {
            // 外送订单更新状态为已完成
            $order->update_status('completed', ruiyi_translate(
                'Pedido de entrega completado desde cocina',
                'Delivery order completed from kitchen',
                '外送订单从厨房完成'
            ));
        }

        // 添加订单备注
        $order->add_order_note(ruiyi_translate(
            'Pedido completado desde la interfaz de cocina',
            'Order completed from kitchen interface',
            '从厨房界面完成订单'
        ));
        
        // 保存订单
        $order->save();
        
        // 记录成功日志
        ruiyi_debug_log("订单 $order_id 已自动完成 - 订单类型: $order_type");
        
        wp_send_json_success([
            'message' => ruiyi_translate(
                'Pedido de entrega/para llevar completado automáticamente',
                'Delivery/takeaway order completed automatically',
                '外送/外带订单已自动完成'
            ),
            'auto_completed' => true,
            'order_type' => $order_type,
            'new_status' => 'completed'
        ]);
        
    } catch (Exception $e) {
        ruiyi_debug_log("完成订单时出错: " . $e->getMessage());
        wp_send_json_error([
            'message' => ruiyi_translate(
                'Error al completar el pedido: ',
                'Error completing order: ',
                '完成订单时出错: '
            ) . $e->getMessage()
        ]);
    }
    
    wp_die();
}

// 获取实时产品数据的AJAX函数
add_action('wp_ajax_ruiyi_get_live_products', 'ruiyi_get_live_products');
add_action('wp_ajax_nopriv_ruiyi_get_live_products', 'ruiyi_get_live_products');

function ruiyi_get_live_products() {
    // 验证nonce
    if (!isset($_REQUEST['nonce']) || !wp_verify_nonce($_REQUEST['nonce'], 'ruiyi_pos_nonce')) {
        wp_send_json_error(['message' => ruiyi_translate('Error de seguridad.', 'Security error.', '安全验证错误。')]);
        return;
    }
    
    // 获取请求的分类ID（如果有）
    $category_id = isset($_REQUEST['category_id']) ? intval($_REQUEST['category_id']) : 0;
    
    // 准备查询参数
    $args = [
        'limit' => -1,
        'status' => 'publish',
    ];
    
    // 如果指定了分类，添加分类过滤
    if ($category_id > 0) {
        $args['category'] = [$category_id];
    }
    
    // 获取产品
    $products = wc_get_products($args);
    $products = ruiyi_pos_sort_products_like_cashier($products);
    $products_data = [];
    
    foreach ($products as $product) {
        // 基本产品数据
        $product_data = [
            'id' => $product->get_id(),
            'name' => $product->get_name(), // 西班牙语名称（原始）
            'name_zh' => get_post_meta($product->get_id(), '_product_name_zh', true), // 中文名称
            'name_en' => get_post_meta($product->get_id(), '_product_name_en', true), // 英文名称
            'price' => (float)$product->get_price(), // 使用产品原始价格
            'regular_price' => (float)$product->get_regular_price(),
            'sale_price' => (float)$product->get_sale_price(),
            'stock_quantity' => $product->get_stock_quantity(),
            'stock_status' => $product->get_stock_status(),
            'image_url' => wp_get_attachment_image_url($product->get_image_id(), 'thumbnail') ?: ruiyi_get_placeholder_image(),
            'categories' => [],
            'type' => $product->get_type(),
            'sort_order' => ruiyi_pos_product_sort_value($product->get_id())
        ];
        
        // 获取分类
        $categories = get_the_terms($product->get_id(), 'product_cat');
        if ($categories && !is_wp_error($categories)) {
            foreach ($categories as $category) {
                $product_data['categories'][] = [
                    'id' => $category->term_id,
                    'name' => $category->name,
                    'slug' => $category->slug
                ];
            }
        }
        
        // 如果是变体产品，获取所有变体
        if ($product->is_type('variable')) {
            $product_data['variations'] = [];
            $variations = $product->get_available_variations();
            
            foreach ($variations as $variation) {
                $variation_obj = wc_get_product($variation['variation_id']);
                
                if ($variation_obj) {
                    $attributes = [];
                    foreach ($variation['attributes'] as $key => $value) {
                        $taxonomy = str_replace('attribute_', '', $key);
                        $term_name = $value;
                        
                        // 如果是自定义属性，尝试获取属性名称
                        if (taxonomy_exists($taxonomy)) {
                            $term = get_term_by('slug', $value, $taxonomy);
                            if ($term) {
                                $term_name = $term->name;
                            }
                        }
                        
                        $attribute_label = wc_attribute_label($taxonomy);
                        $attributes[] = [
                            'label' => $attribute_label,
                            'value' => $term_name
                        ];
                    }
                    
                    $product_data['variations'][] = [
                        'id' => $variation_obj->get_id(),
                        'name' => $variation_obj->get_name(),
                        'price' => (float)$variation_obj->get_price(),
                        'regular_price' => (float)$variation_obj->get_regular_price(),
                        'sale_price' => (float)$variation_obj->get_sale_price(),
                        'stock_quantity' => $variation_obj->get_stock_quantity(),
                        'stock_status' => $variation_obj->get_stock_status(),
                        'image_url' => isset($variation['image']['url']) ? $variation['image']['url'] : $product_data['image_url'],
                        'attributes' => $attributes
                    ];
                }
            }
        }
        
        $products_data[] = $product_data;
    }
    
    wp_send_json_success(['products' => $products_data]);
}

// 获取分类列表的AJAX函数
add_action('wp_ajax_ruiyi_get_product_categories', 'ruiyi_get_product_categories');
add_action('wp_ajax_nopriv_ruiyi_get_product_categories', 'ruiyi_get_product_categories');

function ruiyi_get_product_categories() {
    // 验证nonce
    if (!isset($_REQUEST['nonce']) || !wp_verify_nonce($_REQUEST['nonce'], 'ruiyi_pos_nonce')) {
        wp_send_json_error(['message' => ruiyi_translate('Error de seguridad.', 'Security error.', '安全验证错误。')]);
        return;
    }
    
    // 获取产品分类，顺序与收银页面保持一致
    $categories = ruiyi_pos_get_waiter_categories_like_cashier();
    
    $categories_data = [];
    
    if (!is_wp_error($categories)) {
        foreach ($categories as $category) {
            // 获取多语言字段（根据您的插件可能的字段名）
            $name_zh = get_term_meta($category->term_id, 'name_zh', true) ?:
                      get_term_meta($category->term_id, 'chinese_name', true) ?:
                      get_term_meta($category->term_id, 'category_name_zh', true);
            
            $name_en = get_term_meta($category->term_id, 'name_en', true) ?:
                      get_term_meta($category->term_id, 'english_name', true) ?:
                      get_term_meta($category->term_id, 'category_name_en', true);
            
            $name_es = get_term_meta($category->term_id, 'name_es', true) ?:
                      get_term_meta($category->term_id, 'spanish_name', true) ?:
                      get_term_meta($category->term_id, 'category_name_es', true);
            
            $categories_data[] = [
                'id' => $category->term_id,
                'name' => $category->name,
                'slug' => $category->slug,
                'count' => $category->count,
                'parent' => $category->parent,
                'term_id' => $category->term_id,
                'descendant_ids' => ruiyi_pos_get_category_descendant_ids_for_waiter($category->term_id),
                'sort_order' => isset($category->sort_order) ? intval($category->sort_order) : 999,
                // 添加多语言支持
                'name_zh' => $name_zh,
                'name_en' => $name_en,
                'name_es' => $name_es
            ];
        }
    }
    
    wp_send_json_success(['categories' => $categories_data]);
}

// 检查产品库存的AJAX函数
add_action('wp_ajax_ruiyi_check_product_stock', 'ruiyi_check_product_stock');
add_action('wp_ajax_nopriv_ruiyi_check_product_stock', 'ruiyi_check_product_stock');

function ruiyi_check_product_stock() {
    // 验证nonce
    if (!isset($_REQUEST['nonce']) || !wp_verify_nonce($_REQUEST['nonce'], 'ruiyi_pos_nonce')) {
        wp_send_json_error(['message' => ruiyi_translate('Error de seguridad.', 'Security error.', '安全验证错误。')]);
        return;
    }
    
    // 检查是否提供了cart参数
    if (!isset($_REQUEST['cart']) || empty($_REQUEST['cart'])) {
        wp_send_json_error(['message' => ruiyi_translate('Carrito vacío.', 'Empty cart.', '购物车为空。')]);
        return;
    }
    
    // 解析购物车数据
    $cart = json_decode(stripslashes($_REQUEST['cart']), true);
    if (json_last_error() !== JSON_ERROR_NONE) {
        wp_send_json_error(['message' => ruiyi_translate('Error en formato del carrito.', 'Cart format error.', '购物车格式错误。')]);
        return;
    }
    
    $out_of_stock_items = [];
    $insufficient_stock_items = [];
    
    foreach ($cart as $item) {
        // 检查必要的字段
        if (!isset($item['id']) || !isset($item['quantity'])) {
            continue;
        }
        
        $product_id = intval($item['id']);
        $quantity = intval($item['quantity']);
        
        // 获取产品对象
        $product = wc_get_product($product_id);
        if (!$product) {
            $out_of_stock_items[] = [
                'id' => $product_id,
                'name' => isset($item['name']) ? $item['name'] : ruiyi_translate('Producto desconocido', 'Unknown product', '未知产品'),
                'error' => ruiyi_translate('Producto no encontrado', 'Product not found', '产品未找到')
            ];
            continue;
        }
        
        // 检查产品是否有库存管理
        if ($product->managing_stock()) {
            $stock_quantity = $product->get_stock_quantity();
            
            // 检查库存量是否足够
            if ($quantity > $stock_quantity) {
                $insufficient_stock_items[] = [
                    'id' => $product_id,
                    'name' => $product->get_name(),
                    'requested' => $quantity,
                    'available' => $stock_quantity,
                    'error' => ruiyi_translate('Stock insuficiente', 'Insufficient stock', '库存不足')
                ];
            }
        } else if ($product->is_in_stock() === false) {
            // 产品不管理库存量但标记为缺货
            $out_of_stock_items[] = [
                'id' => $product_id,
                'name' => $product->get_name(),
                'error' => ruiyi_translate('Producto agotado', 'Product out of stock', '产品缺货')
            ];
        }
    }
    
    // 如果有缺货或库存不足的商品，返回错误
    if (!empty($out_of_stock_items) || !empty($insufficient_stock_items)) {
        wp_send_json_error([
            'message' => ruiyi_translate('Problemas de stock en algunos productos.', 'Stock issues with some products.', '部分产品库存问题。'),
            'out_of_stock' => $out_of_stock_items,
            'insufficient_stock' => $insufficient_stock_items
        ]);
    } else {
        // 所有产品库存充足
        wp_send_json_success(['message' => ruiyi_translate('Todos los productos tienen stock suficiente.', 'All products have sufficient stock.', '所有产品库存充足。')]);
    }
}

// 添加实时产品数据JavaScript文件
function ruiyi_enqueue_realtime_product_data() {
    $post = get_post();
    $has_pos_shortcode = ( $post instanceof WP_Post ) && has_shortcode( $post->post_content, 'ruiyi_pos' );

    if ( is_page('usuario-pos') || $has_pos_shortcode ) {
        // 注册并加载实时产品数据JS
        wp_register_script(
            'ruiyi-realtime-product-data',
            get_template_directory_uri() . '/js/realtime-product-data.js',
            array('jquery'),
            '1.0.0',
            true
        );
        
        // 添加需要的本地化数据
        wp_localize_script(
            'ruiyi-realtime-product-data',
            'ruiyi_data',
            array(
                'ajax_url' => admin_url('admin-ajax.php'), // <-- 添加这一行
                'nonce' => wp_create_nonce('ruiyi_pos_nonce')
            )
        );
        
        wp_enqueue_script('ruiyi-realtime-product-data');
    }
}
add_action('wp_enqueue_scripts', 'ruiyi_enqueue_realtime_product_data');

/**
 * 🔥 中西双语产品名称合并（去重编号）
 * 例如：中文"18.炸鸡" + 西文"18. Pollo frito" → "18.炸鸡Pollo frito"
 */
function ruiyi_bilingual_product_name($zh_name, $es_name) {
    if (empty($zh_name)) return $es_name;
    if ($zh_name === $es_name) return $es_name; // 避免重复（如 Varios + Varios）
    if (preg_match('/^(\d+[A-Za-z]?\.\s*)/', $es_name, $matches)) {
        $prefix = rtrim($matches[1]);
        $es_clean = substr($es_name, strlen($matches[0]));
        $zh_clean = preg_replace('/^\d+[A-Za-z]?\.\s*/', '', $zh_name);
        return $prefix . $zh_clean . $es_clean;
    }
    return $zh_name . $es_name;
}

// 添加处理POS设置保存的函数
function ruiyi_save_pos_settings() {
    // 验证nonce
    if (!isset($_POST['pos_settings_nonce']) || !wp_verify_nonce($_POST['pos_settings_nonce'], 'save_pos_settings')) {
        wp_die('安全验证失败', '错误', ['response' => 403]);
    }
    
    // 检查用户权限
    if (!current_user_can('manage_options')) {
        wp_die('您没有足够的权限执行此操作', '权限错误', ['response' => 403]);
    }
    
    // 处理并保存POS设置
    if (isset($_POST['store_name'])) {
        update_option('pos_store_name', sanitize_textarea_field(wp_unslash($_POST['store_name'])));
    }

    if (isset($_POST['store_address'])) {
        update_option('pos_store_address', sanitize_textarea_field(wp_unslash($_POST['store_address'])));
    }

    if (isset($_POST['store_phone'])) {
        update_option('pos_store_phone', sanitize_text_field(wp_unslash($_POST['store_phone'])));
    }

    if (isset($_POST['store_business_name'])) {
        update_option('pos_store_business_name', sanitize_text_field(wp_unslash($_POST['store_business_name'])));
    }

    if (isset($_POST['store_cif_nif'])) {
        update_option('pos_store_cif_nif', sanitize_text_field(wp_unslash($_POST['store_cif_nif'])));
    }

    if (isset($_POST['pos_receipt_footer_phone'])) {
        update_option('pos_receipt_footer_phone', sanitize_text_field(wp_unslash($_POST['pos_receipt_footer_phone'])));
    }

    if (isset($_POST['pos_receipt_footer_website'])) {
        update_option('pos_receipt_footer_website', sanitize_text_field(wp_unslash($_POST['pos_receipt_footer_website'])));
    }

    // 🔥 同步店铺信息到 Verifactu 插件的 Emisor 设置
    $verifactu_settings = get_option('wc_verifactu_qr_settings', array());
    $store_business_name = get_option('pos_store_business_name', '');
    $store_cif_nif = get_option('pos_store_cif_nif', '');
    $store_address = get_option('pos_store_address', '');
    $store_phone = get_option('pos_store_phone', '');

    if (!empty($store_business_name)) {
        $verifactu_settings['emitter_name'] = $store_business_name;
    }
    if (!empty($store_cif_nif)) {
        $verifactu_settings['emitter_vat'] = $store_cif_nif;
    }
    if (!empty($store_address)) {
        $verifactu_settings['emitter_address_1'] = $store_address;
    }
    if (!empty($store_phone)) {
        $verifactu_settings['emitter_phone'] = $store_phone;
    }

    update_option('wc_verifactu_qr_settings', $verifactu_settings);
    ruiyi_debug_log("[POS设置] 店铺信息已同步到Verifactu Emisor设置 - 名称: " . ($store_business_name ?: '(空)') . ", CIF: " . ($store_cif_nif ?: '(空)'));

    // 保存小票Logo
    if (isset($_POST['pos_receipt_logo'])) {
        update_option('pos_receipt_logo', esc_url_raw($_POST['pos_receipt_logo']));
    }

    // 🔥 保存小票Logo大小
    if (isset($_POST['pos_receipt_logo_size'])) {
        $logo_size = intval($_POST['pos_receipt_logo_size']);
        // 限制范围在30-70之间
        $logo_size = max(30, min(70, $logo_size));
