    // 🔥 保存快速备注模板（用于服务员点餐）
    if (isset($_POST['pos_quick_note_templates'])) {
        $qn_templates = json_decode(stripslashes($_POST['pos_quick_note_templates']), true);
        if (is_array($qn_templates)) {
            $clean_templates = array();
            foreach ($qn_templates as $template) {
                if (is_array($template)) {
                    $text = sanitize_text_field($template['text'] ?? '');
                    if ($text === '') {
                        continue;
                    }
                    $categories = isset($template['categories']) && is_array($template['categories'])
                        ? array_values(array_unique(array_filter(array_map('intval', $template['categories']))))
                        : array();
                    $clean_templates[] = array(
                        'text' => $text,
