        $clean = is_array($raw) ? array_map('intval', $raw) : [];
        update_option('pos_kitchen_excluded_categories', json_encode($clean));
    }

    // 🔥 保存跳过厨房打印的桌位分区设置
    if (isset($_POST['pos_kitchen_skip_zone_categories'])) {
        $raw = json_decode(stripslashes($_POST['pos_kitchen_skip_zone_categories']), true);
        $clean = is_array($raw) ? array_map('intval', $raw) : [];
        update_option('pos_kitchen_skip_zone_categories', json_encode($clean));
    }

    // 🔥 保存电子秤显示设置
    $scale_widget_value = isset($_POST['pos_show_scale_widget']) ? '1' : '0';
    update_option('pos_show_scale_widget', $scale_widget_value);
    ruiyi_debug_log('[设置保存] 电子秤显示设置: ' . $scale_widget_value . ' (POST值: ' . (isset($_POST['pos_show_scale_widget']) ? $_POST['pos_show_scale_widget'] : 'NOT SET') . ')');

    // 🔥 保存电子秤连接设置（与WooCommerce后台电子秤设置使用同一组选项）
    $scale_enabled_value = isset($_POST['ruiyi_scale_enabled']) ? '1' : '0';
    update_option('ruiyi_scale_enabled', $scale_enabled_value);

    if (isset($_POST['ruiyi_scale_hub_url'])) {
        $scale_hub_url = esc_url_raw(trim(wp_unslash($_POST['ruiyi_scale_hub_url'])));
        update_option('ruiyi_scale_hub_url', $scale_hub_url);
    }

    if (isset($_POST['ruiyi_scale_location'])) {
