                $item = [
                    'id'            => sanitize_text_field($entry['id'] ?? ''),
                    'name'          => sanitize_text_field($entry['name'] ?? ''),
                    'product_id'    => intval($entry['product_id'] ?? 0),
                    'default_price' => floatval($entry['default_price'] ?? 0),
                    'time_periods'  => [],
                ];
                if (!empty($entry['time_periods']) && is_array($entry['time_periods'])) {
                    foreach ($entry['time_periods'] as $tp) {
                        $days = [];
                        if (!empty($tp['days']) && is_array($tp['days'])) {
                            $days = array_map('intval', $tp['days']);
                            $days = array_filter($days, fn($d) => $d >= 0 && $d <= 6);
                            $days = array_values($days);
                        }
                        $item['time_periods'][] = [
                            'name'  => sanitize_text_field($tp['name'] ?? ''),
                            'start' => sanitize_text_field($tp['start'] ?? ''),
                            'end'   => sanitize_text_field($tp['end'] ?? ''),
                            'price' => floatval($tp['price'] ?? 0),
                            'days'  => $days,
                        ];
                    }
                }
                $clean[] = $item;
            }
        }
        update_option('pos_buffet_menu_types', json_encode($clean));
