    update_option('pos_windows7_modules', isset($_POST['pos_windows7_modules']) ? '1' : '0');

    // 🔥 保存服务员点餐页面访问权限
    $waiter_allowed = isset($_POST['pos_waiter_page_allowed_users'])
        ? array_map('intval', (array) $_POST['pos_waiter_page_allowed_users'])
        : [];
    update_option('pos_waiter_page_allowed_users', $waiter_allowed);

    // 💳 保存支付方式排序
    if (isset($_POST['pos_payment_method_order'])) {
        $order = json_decode(stripslashes($_POST['pos_payment_method_order']), true);
        $valid = ['cash','card','bizum','mixed','cheque'];
        if (is_array($order)) {
            $order = array_values(array_intersect($order, $valid));
            foreach ($valid as $m) { if (!in_array($m, $order)) $order[] = $m; }
            update_option('pos_payment_method_order', json_encode($order));
        }
    }

    // 💳 保存支付方式显示/隐藏
    if (isset($_POST['pos_payment_method_visibility'])) {
        $vis = json_decode(stripslashes($_POST['pos_payment_method_visibility']), true);
        $valid = ['cash','card','bizum','mixed','cheque'];
        if (is_array($vis)) {
            $clean = [];
            foreach ($valid as $m) {
                $clean[$m] = isset($vis[$m]) ? (bool)$vis[$m] : true;
            }
            update_option('pos_payment_method_visibility', json_encode($clean));
        }
    }

    // 保存成功后重定向（加时间戳防止缓存）
    wp_redirect(add_query_arg(['settings_saved' => 'true', '_t' => time()], wp_get_referer()));
    exit;
}
add_action('admin_post_save_pos_settings', 'ruiyi_save_pos_settings');

