// 🔥 AJAX: 延迟加载产品分区价格数据
add_action('wp_ajax_ruiyi_pos_get_zonepricing_products', 'ruiyi_pos_get_zonepricing_products_cb');
function ruiyi_pos_get_zonepricing_products_cb() {
    if (!wp_verify_nonce($_REQUEST['nonce'] ?? '', 'ruiyi_pos_nonce')) {
        wp_send_json_error(['message' => 'Nonce failed']);
    }
    if (!current_user_can('manage_options')) {
        wp_send_json_error(['message' => 'No permission']);
    }
    $current_lang = defined('RUIYI_CURRENT_LANG') ? RUIYI_CURRENT_LANG : 'zh';
    $all_products = wc_get_products(['status' => 'publish', 'limit' => -1, 'orderby' => 'title', 'order' => 'ASC']);
    $data = [];
    foreach ($all_products as $prod) {
        $display_name = $prod->get_name();
        if ($current_lang === 'zh') {
            $zh = get_post_meta($prod->get_id(), '_product_name_zh', true);
            if (!empty($zh)) $display_name = $zh;
        } elseif ($current_lang === 'en') {
            $en = get_post_meta($prod->get_id(), '_product_name_en', true);
            if (!empty($en)) $display_name = $en;
        }
        $zone_prices = get_post_meta($prod->get_id(), '_ruiyi_zone_prices', true);
        $data[] = [
            'id' => $prod->get_id(),
            'name' => $display_name,
            'image' => wp_get_attachment_image_url($prod->get_image_id(), 'thumbnail') ?: '',
            'regular_price' => $prod->get_regular_price(),
            'zone_prices' => is_array($zone_prices) ? $zone_prices : []
        ];
    }
    wp_send_json_success($data);
}

// 🔥 get_multilingual_category_name — needed by AJAX-loaded tabs (e.g. productsort)
if (!function_exists('get_multilingual_category_name')) {
    function get_multilingual_category_name($category_term, $lang = null) {
        static $use_default = null;
        if ($use_default === null) {
            $use_default = get_option('pos_category_use_default_lang', '0') === '1';
        }
        if ($use_default) {
            return $category_term->name;
        }
        if (!$lang) {
            $lang = defined('RUIYI_CURRENT_LANG') ? RUIYI_CURRENT_LANG : 'zh';
        }
        $translated_name = '';
        if ($lang === 'en') {
            $translated_name = get_term_meta($category_term->term_id, 'category_name_en', true);
        } elseif ($lang === 'es') {
            $translated_name = get_term_meta($category_term->term_id, 'category_name_es', true);
        } elseif ($lang === 'zh') {
            $translated_name = get_term_meta($category_term->term_id, 'category_name_zh', true);
        }
        return !empty($translated_name) ? $translated_name : $category_term->name;
    }
}

if (!function_exists('ruiyi_get_product_category_image_id')) {
    function ruiyi_get_product_category_image_id($term_id) {
        $term_id = absint($term_id);
        if ($term_id <= 0) {
            return 0;
        }

        $thumbnail_id = absint(get_term_meta($term_id, 'thumbnail_id', true));
        if ($thumbnail_id > 0) {
            return $thumbnail_id;
        }

        return absint(get_term_meta($term_id, '_ruiyi_category_image_id', true));
    }
}

if (!function_exists('ruiyi_get_product_category_image_url')) {
    function ruiyi_get_product_category_image_url($term_id, $size = 'medium') {
        $image_id = ruiyi_get_product_category_image_id($term_id);
        if ($image_id > 0) {
            $image_url = wp_get_attachment_image_url($image_id, $size);
            if (!empty($image_url)) {
                return $image_url;
            }
        }

        $legacy_url = get_term_meta(absint($term_id), '_ruiyi_category_image_url', true);
        return !empty($legacy_url) ? esc_url_raw($legacy_url) : '';
    }
}

