// 🔥 AJAX处理小票Logo上传
function ruiyi_upload_receipt_logo_callback() {
    // 验证nonce
    if (!isset($_POST['nonce']) || !wp_verify_nonce($_POST['nonce'], 'ruiyi_pos_nonce')) {
        wp_send_json_error(['message' => '安全验证失败']);
        return;
    }

    // 检查用户权限
    if (!current_user_can('upload_files')) {
        wp_send_json_error(['message' => '您没有上传文件的权限']);
        return;
    }

    // 检查是否有文件上传
    if (!isset($_FILES['logo_file']) || $_FILES['logo_file']['error'] !== UPLOAD_ERR_OK) {
        $error_messages = [
            UPLOAD_ERR_INI_SIZE => '文件超过服务器允许的最大大小',
            UPLOAD_ERR_FORM_SIZE => '文件超过表单允许的最大大小',
            UPLOAD_ERR_PARTIAL => '文件只上传了一部分',
            UPLOAD_ERR_NO_FILE => '没有选择文件',
            UPLOAD_ERR_NO_TMP_DIR => '找不到临时文件夹',
            UPLOAD_ERR_CANT_WRITE => '无法写入文件',
            UPLOAD_ERR_EXTENSION => '文件上传被扩展阻止'
        ];
        $error_code = isset($_FILES['logo_file']['error']) ? $_FILES['logo_file']['error'] : UPLOAD_ERR_NO_FILE;
        $error_msg = isset($error_messages[$error_code]) ? $error_messages[$error_code] : '上传失败';
        wp_send_json_error(['message' => $error_msg]);
        return;
    }

    $file = $_FILES['logo_file'];

    // 验证文件类型
    $allowed_types = ['image/png', 'image/jpeg', 'image/gif', 'image/webp'];
    $finfo = finfo_open(FILEINFO_MIME_TYPE);
    $mime_type = finfo_file($finfo, $file['tmp_name']);
    finfo_close($finfo);

    if (!in_array($mime_type, $allowed_types)) {
        wp_send_json_error(['message' => '只允许PNG、JPG、GIF或WebP格式的图片']);
        return;
    }

    // 验证文件大小 (最大5MB，保留高分辨率原图以提升热敏打印清晰度)
    if ($file['size'] > 5 * 1024 * 1024) {
        wp_send_json_error(['message' => '文件太大，最大允许5MB']);
        return;
    }

    // 使用WordPress媒体上传功能
    require_once(ABSPATH . 'wp-admin/includes/file.php');
    require_once(ABSPATH . 'wp-admin/includes/image.php');
    require_once(ABSPATH . 'wp-admin/includes/media.php');

    // 设置上传覆盖选项
    $upload_overrides = [
        'test_form' => false,
        'mimes' => [
            'jpg|jpeg|jpe' => 'image/jpeg',
            'png' => 'image/png',
            'gif' => 'image/gif',
            'webp' => 'image/webp'
        ]
    ];

    // 执行上传
    $movefile = wp_handle_upload($file, $upload_overrides);

    if ($movefile && !isset($movefile['error'])) {
        $image_width = 0;
        $image_height = 0;
        $image_size = @getimagesize($movefile['file']);
        if (is_array($image_size) && !empty($image_size[0]) && !empty($image_size[1])) {
            $image_width = (int) $image_size[0];
            $image_height = (int) $image_size[1];
            update_option('pos_receipt_logo_width', $image_width);
            update_option('pos_receipt_logo_height', $image_height);
            update_option('pos_receipt_logo_dimension_url', $movefile['url']);
        }

        // 上传成功，返回文件URL
        wp_send_json_success([
            'url' => $movefile['url'],
            'file' => $movefile['file'],
            'type' => $movefile['type'],
            'width' => $image_width,
            'height' => $image_height
        ]);
    } else {
        // 上传失败
        wp_send_json_error([
            'message' => isset($movefile['error']) ? $movefile['error'] : '上传失败'
        ]);
    }
}
add_action('wp_ajax_ruiyi_upload_receipt_logo', 'ruiyi_upload_receipt_logo_callback');

// 添加处理打印设置保存的函数
function ruiyi_save_print_settings() {
    // 验证nonce
    if (!isset($_POST['print_settings_nonce']) || !wp_verify_nonce($_POST['print_settings_nonce'], 'save_print_settings')) {
        wp_die('安全验证失败', '错误', ['response' => 403]);
    }
    
    // 检查用户权限
    if (!current_user_can('manage_options')) {
        wp_die('您没有足够的权限执行此操作', '权限错误', ['response' => 403]);
    }
    
    // 处理并保存打印设置
    if (isset($_POST['pos_printer_name'])) {
        update_option('pos_printer_name', sanitize_text_field($_POST['pos_printer_name']));
    }
    
    if (isset($_POST['pos_paper_width'])) {
        update_option('pos_paper_width', intval($_POST['pos_paper_width']));
    }
    
    update_option('pos_auto_print', isset($_POST['pos_auto_print']) ? 1 : 0);
    
    if (isset($_POST['selectedPrinter'])) {
        update_option('pos_selected_printer', sanitize_text_field($_POST['selectedPrinter']));
    }
    
    if (isset($_POST['pos_receipt_header'])) {
        update_option('pos_receipt_header', sanitize_textarea_field($_POST['pos_receipt_header']));
    }
    
    if (isset($_POST['pos_receipt_footer'])) {
        update_option('pos_receipt_footer', sanitize_textarea_field($_POST['pos_receipt_footer']));
    }

    // 🔥 保存感谢语设置
    if (isset($_POST['pos_receipt_thank_you'])) {
        update_option('pos_receipt_thank_you', sanitize_text_field($_POST['pos_receipt_thank_you']));
    }

    if (isset($_POST['pos_receipt_footer_phone'])) {
        update_option('pos_receipt_footer_phone', sanitize_text_field(wp_unslash($_POST['pos_receipt_footer_phone'])));
    }

    if (isset($_POST['pos_receipt_footer_website'])) {
        update_option('pos_receipt_footer_website', sanitize_text_field(wp_unslash($_POST['pos_receipt_footer_website'])));
    }

    update_option('pos_show_logo', isset($_POST['pos_show_logo']) ? 1 : 0);
    
    // 保存TicketBai/Verifactu设置
    update_option('pos_enable_ticketbai', isset($_POST['pos_enable_ticketbai']) ? 1 : 0);
    
    if (isset($_POST['pos_business_id'])) {
        update_option('pos_business_id', sanitize_text_field($_POST['pos_business_id']));
    }
    
    if (isset($_POST['pos_tax_id'])) {
        update_option('pos_tax_id', sanitize_text_field($_POST['pos_tax_id']));
    }
    
    if (isset($_POST['pos_fiskaly_api_key'])) {
        update_option('pos_fiskaly_api_key', sanitize_text_field($_POST['pos_fiskaly_api_key']));
    }
    
    if (isset($_POST['pos_fiskaly_api_secret'])) {
        update_option('pos_fiskaly_api_secret', sanitize_text_field($_POST['pos_fiskaly_api_secret']));
    }
    
    // 保存成功后重定向
    wp_redirect(add_query_arg('settings_saved', 'true', wp_get_referer()));
    exit;
}
