// 处理厨房标记订单为完成的AJAX请求
add_action('wp_ajax_ruiyi_kitchen_mark_order_complete', 'ruiyi_mark_order_complete_callback');
add_action('wp_ajax_nopriv_ruiyi_kitchen_mark_order_complete', 'ruiyi_mark_order_complete_callback');

function ruiyi_mark_order_complete_callback() {
    // 添加调试日志
    ruiyi_debug_log('ruiyi_mark_order_complete_callback 开始执行');
    ruiyi_debug_log('接收到的POST数据: ' . print_r($_POST, true));
    
    // 验证nonce
    if (!isset($_POST['nonce']) || !wp_verify_nonce($_POST['nonce'], 'cocina_nonce')) {
        ruiyi_debug_log('厨房nonce验证失败');
        wp_send_json_error(['message' => '安全验证失败'], 403);
        return;
    }
    
    // 获取订单ID
    $order_id = isset($_POST['order_id']) ? intval($_POST['order_id']) : 0;
    if (!$order_id) {
        ruiyi_debug_log('缺少订单ID参数');
        wp_send_json_error(['message' => '请求参数不完整 (订单ID缺失)'], 400);
        return;
    }
    
    // 获取订单对象
    $order = wc_get_order($order_id);
    if (!$order) {
        ruiyi_debug_log("找不到订单，ID: $order_id");
        wp_send_json_error(['message' => "未找到指定的订单：$order_id"], 404);
        return;
    }
    
    try {
        // 添加订单备注
        $user = wp_get_current_user();
        $order->add_order_note(
            sprintf(
                __('订单已由厨房人员 %s 标记为完成。时间: %s', 'ruiyi-pos'),
                $user->display_name,
                current_time('mysql')
            )
        );
        
        // 添加订单元数据标记厨房状态（这些元数据只影响前端显示，不改变订单状态）
        $order->update_meta_data('_kitchen_completed', 'yes');
        $order->update_meta_data('_kitchen_completed_time', current_time('mysql'));
        $order->update_meta_data('_kitchen_completed_by', $user->ID);
        
        // 保存订单（只保存元数据，不更改订单状态）
        $order->save();
        
        ruiyi_debug_log("订单 $order_id 已在厨房标记为完成");
        
        // 返回成功响应
        wp_send_json_success([
            'message' => '订单已标记为完成',
            'order_id' => $order_id
        ]);
    } catch (Exception $e) {
        ruiyi_debug_log('处理订单完成时发生异常: ' . $e->getMessage());
        wp_send_json_error([
            'message' => '处理订单时发生错误: ' . $e->getMessage()
        ], 500);
    }
    
    wp_die();
}

/**
 * AJAX Handler: 获取指定桌位的所有未结账订单
 * 接收参数: table_number (桌位号), nonce
 * 返回: 该桌位所有状态为 'processing' (或其他未结账状态) 且关联了该桌号的订单列表
 */
add_action('wp_ajax_ruiyi_pos_get_table_orders', 'ruiyi_pos_get_orders_for_table_callback');
add_action('wp_ajax_ruiyi_pos_get_table_orders_for_split', 'ruiyi_pos_get_table_orders_for_split_callback');
add_action('wp_ajax_nopriv_ruiyi_pos_get_table_orders_for_split', 'ruiyi_pos_get_table_orders_for_split_callback');
// POS系统仅允许登录用户访问

// 获取指定餐桌的订单数据用于分单结账
function ruiyi_pos_get_table_orders_for_split_callback() {
    check_ajax_referer('ruiyi_pos_nonce', 'nonce');
    
    $table_number = isset($_POST['table_number']) ? sanitize_text_field($_POST['table_number']) : '';
    
    if (empty($table_number)) {
        wp_send_json_error(['message' => '桌号参数缺失']);
        return;
    }
    
    // 处理不同的餐桌号格式：优先通过桌位映射解析为全局桌号
    $all_table_mappings = function_exists('ruiyi_get_all_table_categories_mapping') ? ruiyi_get_all_table_categories_mapping() : array();
    $table_number_numeric = function_exists('ruiyi_safe_extract_table_number')
        ? ruiyi_safe_extract_table_number($table_number, $all_table_mappings)
        : '';
    if ($table_number_numeric === '') {
        $table_number_numeric = preg_replace('/[^0-9]/', '', $table_number);
    }
    
    ruiyi_debug_log("SPLIT BILLING: 获取餐桌数据");
    ruiyi_debug_log("SPLIT BILLING: 原始餐桌号: {$table_number}");
    ruiyi_debug_log("SPLIT BILLING: 数字餐桌号: {$table_number_numeric}");
    
    try {
        // 🔥🔥🔥 关键修复：使用统一的活跃订单状态常量
        // 先获取所有活跃订单（pending, on-hold, processing），然后手动过滤
        $all_orders = wc_get_orders([
            'status' => RUIYI_POS_ACTIVE_ORDER_STATUSES_WC,
            'limit' => -1
        ]);

        ruiyi_debug_log("SPLIT BILLING: 查询到所有活跃订单数量: " . count($all_orders));
        
        // 手动过滤匹配的餐桌订单
        $orders = [];
        foreach ($all_orders as $order) {
            $order_table = $order->get_meta('_table_number', true);
            $order_table_numeric = function_exists('ruiyi_safe_extract_table_number')
                ? ruiyi_safe_extract_table_number($order_table, $all_table_mappings)
                : '';
            if ($order_table_numeric === '') {
                $order_table_numeric = preg_replace('/[^0-9]/', '', $order_table);
            }
            
            ruiyi_debug_log("SPLIT BILLING: 检查订单 #{$order->get_id()} - 存储的餐桌号: '{$order_table}', 数字: '{$order_table_numeric}'");
            
            // 精确匹配数字部分
            if ($order_table_numeric === $table_number_numeric) {
                $orders[] = $order;
                ruiyi_debug_log("SPLIT BILLING: 订单 #{$order->get_id()} 匹配餐桌 {$table_number_numeric}");
            }
        }
        
        ruiyi_debug_log("SPLIT BILLING: 查询到 " . count($orders) . " 个订单");
        
        if (empty($orders)) {
            wp_send_json_error(['message' => "餐桌 {$table_number} 没有待处理的订单"]);
            return;
        }
        
        $formatted_orders = [];
        foreach ($orders as $order) {
            // 获取并验证订单的餐桌号
            $order_table_number = $order->get_meta('_table_number', true);
            ruiyi_debug_log("SPLIT BILLING: 订单 #{$order->get_id()} 的餐桌号: '{$order_table_number}'");
            
            // 严格验证餐桌号匹配
            $order_table_numeric = function_exists('ruiyi_safe_extract_table_number')
                ? ruiyi_safe_extract_table_number($order_table_number, $all_table_mappings)
                : '';
            if ($order_table_numeric === '') {
                $order_table_numeric = preg_replace('/[^0-9]/', '', $order_table_number);
            }
            if ($order_table_numeric !== $table_number_numeric) {
                ruiyi_debug_log("SPLIT BILLING: 跳过订单 #{$order->get_id()} - 餐桌号不匹配 (期望: {$table_number_numeric}, 实际: {$order_table_numeric})");
                continue;
            }
            
            $order_items = [];
            foreach ($order->get_items() as $item) {
                $product = $item->get_product();
                $calculated_price = $item->get_subtotal() / $item->get_quantity();
                $product_price = $product ? $product->get_price() : $calculated_price;
                
                // 调试信息：比较分单价格
                ruiyi_debug_log('[分单API调试] 商品:' . $item->get_name() . ' - 产品原价:€' . $product_price . ', 订单计算价格:€' . $calculated_price);
                
                $order_items[] = [
                    'id' => $item->get_id(),        // 兼容旧代码
                    'item_id' => $item->get_id(),   // 🔥 修复：添加item_id字段，与其他API保持一致
                    'name' => $item->get_name(),
                    'product_id' => $item->get_product_id(), // 添加产品ID
                    'quantity' => $item->get_quantity(),
                    'price' => $calculated_price, // 🔥 使用订单中实际支付的价格（保留自定义价格）
                    'original_price' => $product_price, // 保留产品原价供参考
                    'total' => $item->get_subtotal()
                ];
            }
            
            $formatted_orders[] = [
                'id' => $order->get_id(),
                'table_number' => $order_table_number, // 使用订单中实际存储的餐桌号
                'items' => $order_items,
                'total' => $order->get_total(),
                'order_type' => $order->get_meta('_order_type', true) ?: 'servir',
                'date' => $order->get_date_created()->date_i18n('Y-m-d H:i:s')
            ];
            
            ruiyi_debug_log("SPLIT BILLING: 订单 #{$order->get_id()} 包含 " . count($order_items) . " 个产品");
        }
        
        ruiyi_debug_log("SPLIT BILLING: 找到 " . count($formatted_orders) . " 个订单，共 " . array_sum(array_map(function($o) { return count($o['items']); }, $formatted_orders)) . " 个产品");
        
        wp_send_json_success([
            'orders' => $formatted_orders,
            'table_number' => $table_number,
            'total_orders' => count($formatted_orders)
        ]);
        
    } catch (Exception $e) {
        ruiyi_debug_log("SPLIT BILLING ERROR: " . $e->getMessage());
        wp_send_json_error(['message' => '获取订单数据失败: ' . $e->getMessage()]);
    }
}

function ruiyi_pos_get_orders_for_table_callback() {
    // 添加调试日志，检查函数调用情况
    ruiyi_debug_log('ruiyi_pos_get_orders_for_table_callback 被调用');
    ruiyi_debug_log('收到的POST数据: ' . print_r($_POST, true));

    // 1. 安全性检查：验证 Nonce
    check_ajax_referer('ruiyi_pos_nonce', 'nonce'); // 使用与 page-pos.php 中 $ajax_nonce 相同的 'ruiyi_pos_nonce'

    // 2. 获取并清理参数
    $table_number_input = isset($_POST['table_number']) ? sanitize_text_field($_POST['table_number']) : '';
    $fallback_order_id_input = isset($_POST['order_id']) ? absint($_POST['order_id']) : 0;

    if (empty($table_number_input)) {
        wp_send_json_error(['message' => ruiyi_translate('Número de mesa no proporcionado.', 'Table number not provided.', '未提供桌位号。')], 400);
        return;
    }

    $all_mappings = function_exists('ruiyi_get_all_table_categories_mapping') ? ruiyi_get_all_table_categories_mapping() : array();

    // 🔥🔥🔥 【2026-01-19 修复】保留完整桌号名称用于精确匹配
    // 例如 "DOMICILIO3" 应该只匹配 "DOMICILIO3"，不应该匹配 "COMEDOR3"
    $table_full_name = strtoupper(trim($table_number_input));
    $table_number_numeric = function_exists('ruiyi_safe_extract_table_number')
        ? ruiyi_safe_extract_table_number($table_number_input, $all_mappings)
        : '';
    if ($table_number_numeric === '') {
        $table_number_numeric = preg_replace('/[^0-9]/', '', $table_number_input);
    }
    // 🔥 修复：添加额外的 trim() 移除前缀后的空格（"餐桌 4" -> "餐桌 " -> "餐桌"）
    $table_prefix = trim(strtoupper(preg_replace('/[0-9]+$/', '', trim($table_number_input))));

    // 🔥🔥🔥 【2026-04-04 关键修复】自定义桌位名称解析
    // 当桌位使用自定义名称（如 "T4", "W21", "厅9.5"）时，preg_replace 提取的数字
    // 不是全局编号。需要通过映射表将自定义名称解析为正确的全局编号。
    // 例如：T4 → preg_replace 提取 "4"，但全局编号是 16
    if (!empty($all_mappings)) {
        $input_normalized = strtoupper(preg_replace('/\s+/', '', trim($table_number_input)));

        foreach ($all_mappings as $mapping) {
            $display_name = isset($mapping['category_display_name']) ? $mapping['category_display_name'] : '';
            $display_normalized = strtoupper(preg_replace('/\s+/', '', trim($display_name)));

            if ($display_normalized === $input_normalized && !empty($mapping['global_table_number'])) {
                $resolved_gtn = (string)$mapping['global_table_number'];
                ruiyi_debug_log("🔥 自定义桌名解析: '{$table_number_input}' → 全局编号 {$resolved_gtn} (原始提取: {$table_number_numeric})");
                $table_number_numeric = $resolved_gtn;
                $table_full_name = 'MESA ' . $resolved_gtn;
                $table_prefix = 'MESA';
                break;
            }
        }
    }

    if (empty($table_number_numeric)) {
        // 如果处理后桌号为空（比如输入的是纯文本），也视为无效
        wp_send_json_error(['message' => ruiyi_translate('Formato de número de mesa inválido.', 'Invalid table number format.', '桌位号格式无效。')], 400);
        return;
    }

    ruiyi_debug_log("处理后的桌位号: 完整='{$table_full_name}', 前缀='{$table_prefix}', 数字='{$table_number_numeric}'");

    // 🔥 兜底：桌位状态表里保存的 orderId 是最接近前端"占用卡片"的数据源。
    // 如果订单 meta 中的桌号因旧映射损坏而不匹配，后面会用这里的 orderId 找回订单。
    $live_order_ids_for_table = array();
    if ($fallback_order_id_input > 0) {
        $live_order_ids_for_table[] = $fallback_order_id_input;
        ruiyi_debug_log("桌位 {$table_number_numeric} 的前端兜底订单ID: {$fallback_order_id_input}");
    }
    $live_statuses_for_lookup = get_option('ruiyi_pos_live_table_statuses', array());
    if (is_array($live_statuses_for_lookup)) {
        foreach ($live_statuses_for_lookup as $live_table_key => $live_status_data) {
            if (!is_array($live_status_data) || empty($live_status_data['orderId'])) {
                continue;
            }
            $live_table_numeric = function_exists('ruiyi_safe_extract_table_number')
                ? ruiyi_safe_extract_table_number($live_table_key, $all_mappings)
                : preg_replace('/[^0-9]/', '', $live_table_key);
            if ($live_table_numeric === $table_number_numeric) {
                $live_order_ids_for_table[] = absint($live_status_data['orderId']);
            }
        }
        $live_order_ids_for_table = array_values(array_unique(array_filter($live_order_ids_for_table)));
    }
    if (!empty($live_order_ids_for_table)) {
        ruiyi_debug_log("桌位 {$table_number_numeric} 的 live status 兜底订单ID: " . implode(',', $live_order_ids_for_table));
    }

    // 🔥🔥🔥 关键修复：使用统一的活跃订单状态常量
    // 包含 pending, on-hold, processing 三种状态
    $unpaid_statuses = RUIYI_POS_ACTIVE_ORDER_STATUSES;

    // 🔥🔥🔥 关键修复：清除WooCommerce订单缓存，确保获取最新数据（尤其是换台后）
    if (function_exists('wc_delete_shop_order_transients')) {
        wc_delete_shop_order_transients();
    }
    wp_cache_delete('wc_orders_cache_group', 'orders');

    // 4. 获取所有相关状态的订单 (兼容HPOS，先获取再过滤)
    $args = [
        'status' => $unpaid_statuses,
        'limit' => -1, // 获取所有匹配的订单
        'orderby' => 'date',
        'order' => 'ASC', // 按时间升序，方便查看点单顺序
        'return' => 'objects',
        'cache' => false,  // 🔥 禁用缓存，确保获取最新数据
    ];
    $all_relevant_orders = wc_get_orders($args);
    
    ruiyi_debug_log("找到的相关状态订单数量: " . count($all_relevant_orders));

    $orders_for_this_table = [];

    // 5. 在PHP中手动过滤出属于该桌位的订单
    if (!empty($all_relevant_orders)) {
        foreach ($all_relevant_orders as $order) {
            // 🔥 关键修复：跳过已经在回收站的订单（已合并的小订单）
            $post = get_post($order->get_id());
            if ($post && $post->post_status === 'trash') {
                ruiyi_debug_log("✗ 跳过回收站订单 #{$order->get_id()} - 该订单已被合并并移至回收站");
                continue;
            }

            // 🔥 关键修复：跳过已经被标记为"已合并"的订单
            if ($order->get_meta('_is_merged') === 'yes') {
                $merged_to = $order->get_meta('_merged_to_order');
                ruiyi_debug_log("✗ 跳过已合并订单 #{$order->get_id()} - 已合并到订单 #$merged_to");
                continue;
            }

            // 获取订单元数据中的桌位信息
            $order_table_meta = $order->get_meta('_table_number', true);
            // 🔥🔥🔥 【2026-01-30 新增】获取订单的显示桌号（换台后会设置此字段）
            $order_display_name = $order->get_meta('_table_display_name', true);

            // 也检查一下不带下划线的版本
            if (empty($order_table_meta)) {
                $order_table_meta = $order->get_meta('table_number', true);
            }

            ruiyi_debug_log("订单 #{$order->get_id()} 的桌位元数据: '{$order_table_meta}', 显示桌号: '{$order_display_name}', 状态: " . $order->get_status());

            // 🔥🔥🔥 【2026-01-19 修复】使用完整桌号进行精确匹配
            // 避免 COMEDOR3 和 DOMICILIO3 被错误匹配（它们是不同的桌位）
            $order_table_upper = strtoupper(trim($order_table_meta));
            $order_table_numeric_safe = function_exists('ruiyi_safe_extract_table_number')
                ? ruiyi_safe_extract_table_number($order_table_meta, $all_mappings)
                : '';
            $order_display_numeric_safe = (!empty($order_display_name) && function_exists('ruiyi_safe_extract_table_number'))
                ? ruiyi_safe_extract_table_number($order_display_name, $all_mappings)
                : '';
            $order_table_numeric = $order_table_numeric_safe !== ''
                ? $order_table_numeric_safe
                : preg_replace('/[^0-9]/', '', $order_table_meta);
            // 🔥 修复：添加额外的 trim() 移除前缀后的空格（"MESA 4" -> "MESA " -> "MESA"）
            $order_table_prefix = trim(strtoupper(preg_replace('/[0-9]+$/', '', trim($order_table_meta))));

            ruiyi_debug_log("桌位匹配检查: 订单桌号='{$order_table_upper}'(前缀:'{$order_table_prefix}',数字:'{$order_table_numeric}'), 显示名='{$order_display_name}' vs 目标桌号='{$table_full_name}'(前缀:'{$table_prefix}',数字:'{$table_number_numeric}')");

            // 🔥 匹配规则（优先级从高到低）：
            // 0. 🔥🔥🔥 【2026-01-30 新增】显示桌号精确匹配（换台后的订单）
            // 1. 完整桌号精确匹配（DOMICILIO3 == DOMICILIO3）
            // 2. 前缀+数字匹配（同前缀且数字相同）
            // 3. 默认前缀兼容匹配（用于旧数据：MESA/餐桌/空前缀互相兼容）
            // 4. 搜索使用默认前缀时，匹配任何具有相同数字的订单
            $default_prefixes = ['', 'MESA', '餐桌', 'TABLE', '桌'];
            $is_default_search = in_array($table_prefix, $default_prefixes);
            $is_default_order = in_array($order_table_prefix, $default_prefixes);

            $is_match = false;
            $match_type = "";

            // 🔥🔥🔥 【2026-01-30 新增】优先检查显示桌号匹配（换台后的订单）
            // 换台后订单的 _table_number 变为 "Mesa X"（全局编号），但 _table_display_name 保存了目标桌位名称
            // 例如：换台到 DOMICILIO1 后，_table_number="Mesa 11", _table_display_name="DOMICILIO1"
            // 当查询订单时，前端发送 table_number="DOMICILIO1"，需要通过 _table_display_name 匹配
            if (!empty($order_display_name)) {
                $display_name_upper = strtoupper(preg_replace('/\s+/', '', trim($order_display_name)));
                $search_name_normalized = strtoupper(preg_replace('/\s+/', '', trim($table_number_input)));

                if ($display_name_upper === $search_name_normalized) {
                    $is_match = true;
                    $match_type = "显示桌号精确匹配（_table_display_name='{$order_display_name}'）";
                }
            }

            if (!$is_match && $order_table_numeric_safe !== '' && $order_table_numeric_safe === $table_number_numeric) {
                // 全局桌号匹配：解决分区/自定义桌名保存为 COMEDOR1，但前端查询 Mesa 5 的情况
                $is_match = true;
                $match_type = "全局桌号匹配";
            } elseif (!$is_match && $order_display_numeric_safe !== '' && $order_display_numeric_safe === $table_number_numeric) {
                // 显示桌名能解析到同一全局桌号
                $is_match = true;
                $match_type = "显示桌名全局桌号匹配";
            } elseif (!$is_match && $order_table_upper === $table_full_name) {
                // 完整名称精确匹配
                $is_match = true;
                $match_type = "完整桌号精确匹配";
            } elseif (!$is_match && $order_table_prefix === $table_prefix && $order_table_numeric === $table_number_numeric) {
                // 同前缀+同数字
                $is_match = true;
                $match_type = "前缀+数字匹配";
            } elseif (!$is_match && $is_default_search && $is_default_order && $order_table_numeric === $table_number_numeric) {
                // 默认前缀兼容（Mesa 3 == 餐桌3 == 3）
                $is_match = true;
                $match_type = "默认前缀兼容匹配";
            } elseif (!$is_match && $is_default_search && $order_table_numeric === $table_number_numeric) {
                // 🔥 新增规则：当搜索使用默认前缀（如 Mesa 4）时，
                // 也匹配具有相同数字部分但不同前缀的订单（如 COMEDOR4）
                // 这处理了从客户点餐页面创建的订单可能存储为错误格式的情况
                $is_match = true;
                $match_type = "默认前缀搜索-数字匹配（订单桌号前缀:{$order_table_prefix}）";
            } elseif (!$is_match && !empty($live_order_ids_for_table) && in_array(absint($order->get_id()), $live_order_ids_for_table, true)) {
                // 🔥🔥🔥 【2026-05-05 修复】桌位映射损坏后的订单兜底匹配
                // 场景：桌位卡片显示占用（live status 有 orderId），WC 后台也有 processing 订单，
                // 但订单 _table_number 仍是旧映射桌号，点击桌位按当前映射查询就会显示"无订单"。
                $order_known_table_numeric = $order_table_numeric_safe !== ''
                    ? $order_table_numeric_safe
                    : ($order_display_numeric_safe !== '' ? $order_display_numeric_safe : '');

                if ($order_known_table_numeric === '') {
                    // 只有订单本身没有可识别桌号时，才允许用当前点击桌位修正。
                    $is_match = true;
                    $match_type = "live status orderId 兜底匹配（订单无桌号，已修复）";

                    $repaired_table_number = 'Mesa ' . $table_number_numeric;
                    $order->update_meta_data('_table_number', $repaired_table_number);
                    $order->update_meta_data('table_number', $repaired_table_number);
                    if (!empty($all_mappings)) {
                        foreach ($all_mappings as $_repair_mapping) {
                            if (strval($_repair_mapping['global_table_number'] ?? '') === strval($table_number_numeric)) {
                                $repair_display = trim((string)($_repair_mapping['category_display_name'] ?? ''));
                                if ($repair_display !== '') {
                                    $order->update_meta_data('_table_display_name', $repair_display);
                                }
                                break;
                            }
                        }
                    }
                    $order->save();
                    ruiyi_debug_log("✓ live status 兜底修复订单 #{$order->get_id()} 桌号 meta: '{$order_table_meta}' → '{$repaired_table_number}'");
                } elseif ($order_known_table_numeric === $table_number_numeric) {
                    $is_match = true;
                    $match_type = "live status orderId 兜底匹配（订单桌号已校验）";
                } else {
                    // 防串单：订单已经明确属于另一个桌位，不能因为当前卡片 stale orderId 而强行改订单。
                    ruiyi_debug_log("✗ live status 兜底拒绝：订单 #{$order->get_id()} 属于桌位 {$order_known_table_numeric}，当前请求桌位 {$table_number_numeric}，避免串单");
                    ruiyi_clear_table_status_all_formats($table_number_numeric);
                    ruiyi_update_single_table_status($order_known_table_numeric, array(
                        'status' => 'ocupada',
                        'orderId' => $order->get_id(),
                        'total' => floatval($order->get_total()),
                        'timestamp' => microtime(true),
                        'version' => time() . '_' . wp_rand(1000, 9999),
                    ));
                }
            }

            if (!$is_match) {
                // 无匹配，继续下一个订单
                continue;
            }

            ruiyi_debug_log("✓ {$match_type} - 订单 #{$order->get_id()} 匹配桌位 {$table_full_name}");

            // 将找到的匹配订单添加到结果中
            $order_items_data = [];
            foreach ($order->get_items() as $item_id => $item) {
                $product = $item->get_product();
                $order_item_total = $item->get_total();
                $order_item_quantity = $item->get_quantity();
                $calculated_price = $order_item_quantity > 0 ? ($order_item_total / $order_item_quantity) : 0;
                $product_price = $product ? $product->get_price() : 0;

                // 🔥 检查是否为 Varios 商品，优先使用自定义价格
                $is_varios_item = wc_get_order_item_meta($item_id, '_is_varios_item', true) === 'yes';
                $varios_custom_price = wc_get_order_item_meta($item_id, '_varios_custom_price', true);

                // 价格优先级：
                // 1. Varios 自定义价格（如果是 Varios 商品）
                // 2. 从订单总价计算的价格
                // 3. 产品原价
                if ($is_varios_item && !empty($varios_custom_price) && $varios_custom_price > 0) {
                    $item_price = floatval($varios_custom_price);
                    ruiyi_debug_log('[Varios价格修复] 商品:' . $item->get_name() . ' - 使用自定义价格:€' . $item_price);
                } else {
                    $item_price = $product ? $product->get_price() : $calculated_price;
                }

                // 🔥🔥🔥 关键修复：检查是否有自定义名称
                $has_custom_name = wc_get_order_item_meta($item_id, '_has_custom_name', true) === 'yes';
                $original_product_name = $product ? $product->get_name() : '';
                $order_item_name = $item->get_name();
                // 如果订单项名称与产品原名称不同，也视为自定义名称
                $is_name_different = $original_product_name && $order_item_name !== $original_product_name;

                // 调试信息
                ruiyi_debug_log('[桌位订单构建调试] 商品:' . $item->get_name() . ' - 产品原价:€' . $product_price . ', 订单计算价格:€' . $calculated_price . ', 最终价格:€' . $item_price);

                // 🔥 获取多语言名称和分类ID（用于购物车显示和配料筛选）
                $product_id_for_meta = $item->get_product_id();
                $item_name_zh = $product_id_for_meta ? get_post_meta($product_id_for_meta, '_product_name_zh', true) : '';
                $item_name_en = $product_id_for_meta ? get_post_meta($product_id_for_meta, '_product_name_en', true) : '';
                $item_name_es = $product ? $product->get_name() : $item->get_name();
                $item_cat_ids = $product_id_for_meta ? wp_get_post_terms($product_id_for_meta, 'product_cat', ['fields' => 'ids']) : [];
                if (is_wp_error($item_cat_ids)) $item_cat_ids = [];

                $item_data = [
                    'name' => $item->get_name(), // 使用订单项的实际名称（可能是自定义名称）
                    'name_es' => $item_name_es, // 🔥 西班牙语原名
                    'name_zh' => $item_name_zh ?: '', // 🔥 中文名称
                    'name_en' => $item_name_en ?: '', // 🔥 英文名称
                    'product_id' => $product_id_for_meta, // 添加产品ID
                    'item_id' => $item_id, // 🔥 添加订单项ID，用于精确删除
                    'quantity' => $item->get_quantity(),
                    'total' => $item->get_total(),
                    'price' => $calculated_price, // 🔥 使用订单中实际支付的价格（保留自定义价格）
                    'original_price' => $product_price, // 保留产品原价供参考
                    'categoryIds' => is_array($item_cat_ids) ? $item_cat_ids : [], // 🔥 产品分类IDs（配料筛选）
                ];

                // 🔥🔥🔥 如果有自定义名称，添加相关字段
                if ($has_custom_name || $is_name_different) {
                    $item_data['customName'] = $order_item_name; // 当前使用的名称（自定义名称）
                    $item_data['originalProductName'] = $original_product_name; // 产品原始名称
                    $item_data['hasCustomName'] = true;
                }

                // 🔥 返回配料数据（如果有）
                $saved_supplements = wc_get_order_item_meta($item_id, '_item_supplements', true);
                if (!empty($saved_supplements)) {
                    $item_data['supplements'] = $saved_supplements; // JSON string
                    $item_data['_originalName'] = wc_get_order_item_meta($item_id, '_supplement_original_name', true) ?: $original_product_name;
                    $item_data['_originalPrice'] = wc_get_order_item_meta($item_id, '_supplement_original_price', true);
                }

                $order_items_data[] = $item_data;
            }
            
            $orders_for_this_table[] = [
                'id' => $order->get_id(),
                'order_number' => $order->get_order_number(),
                'status' => $order->get_status(),
                'status_name' => wc_get_order_status_name($order->get_status()),
                'total' => $order->get_total(),
                'date_created' => $order->get_date_created() ? $order->get_date_created()->date('Y-m-d H:i:s') : null,
                'items' => $order_items_data,
                'table_number_meta' => $order_table_meta, // 返回原始meta值用于调试
                'match_type' => $match_type // 添加匹配类型用于调试
            ];
        }
    }

    ruiyi_debug_log("为桌位 $table_number_input 找到的订单数量: " . count($orders_for_this_table));

    // 6. 返回结果
    wp_send_json_success([
        'table_number_requested' => $table_number_input, // 返回请求的原始桌号
        'table_number_processed' => $table_number_numeric,     // 返回处理后的桌号数字
        'orders' => $orders_for_this_table,
        'count' => count($orders_for_this_table)
    ]);

    wp_die(); // AJAX处理函数中必须要有
}

// 添加多订单结账的AJAX处理函数
add_action('wp_ajax_ruiyi_pos_complete_multiple_orders', 'ruiyi_pos_complete_multiple_orders_callback');
add_action('wp_ajax_nopriv_ruiyi_pos_complete_multiple_orders', 'ruiyi_pos_complete_multiple_orders_callback'); // 如果非登录用户也需要访问

function ruiyi_pos_complete_multiple_orders_callback() {
    if (!is_user_logged_in()) {
        wp_send_json_error(['message' => 'Authentication required']);
        return;
    }

    // 添加调试日志
    ruiyi_debug_log('ruiyi_pos_complete_multiple_orders_callback 开始执行');
    ruiyi_debug_log('接收到的POST数据: ' . print_r($_POST, true));

    // 1. 安全性检查：验证 Nonce
    if (!isset($_POST['nonce']) || !wp_verify_nonce(sanitize_text_field($_POST['nonce']), 'ruiyi_pos_nonce')) {
        ruiyi_debug_log('Nonce 验证失败');
        wp_send_json_error(['message' => '安全验证失败 (Nonce 无效)。'], 403);
        return;
    }

    // 2. 获取并清理参数
    $table_number = isset($_POST['table_number']) ? sanitize_text_field($_POST['table_number']) : '';
    $payment_method = isset($_POST['payment_method']) ? sanitize_text_field($_POST['payment_method']) : '';
    $received_amount = isset($_POST['received_amount']) ? floatval($_POST['received_amount']) : 0;
    $change_amount = isset($_POST['change_amount']) ? floatval($_POST['change_amount']) : 0;

    // 🔥 获取混合支付参数
    $cash_amount = isset($_POST['cash_amount']) ? floatval($_POST['cash_amount']) : 0;
    $card_amount = isset($_POST['card_amount']) ? floatval($_POST['card_amount']) : 0;
    
    // 获取订单ID列表
    $order_ids = isset($_POST['order_ids']) ? $_POST['order_ids'] : [];
    
    // 如果order_ids是JSON字符串，则解析它
    if (is_string($order_ids) && !empty($order_ids)) {
        ruiyi_debug_log('解析订单ID JSON字符串: ' . $order_ids);
        $order_ids = json_decode(stripslashes($order_ids), true);
        ruiyi_debug_log('JSON解析后的订单ID: ' . print_r($order_ids, true));
        
        // 检查JSON解析是否成功
        if (json_last_error() !== JSON_ERROR_NONE) {
            ruiyi_debug_log('JSON解析错误: ' . json_last_error_msg());
        }
    } else {
        ruiyi_debug_log('订单ID不是字符串或为空: ' . print_r($order_ids, true));
    }
    
    // 确保order_ids是数组
    if (!is_array($order_ids)) {
        ruiyi_debug_log('订单ID不是数组，转换为数组: ' . print_r($order_ids, true));
        $order_ids = [$order_ids];
    }
    
    // 清理订单ID - 从格式如"#1001"中提取数字
    $cleaned_order_ids = [];
    foreach ($order_ids as $id) {
        if (is_string($id)) {
            // 从"#1001"格式中提取数字
            $clean_id = preg_replace('/[^0-9]/', '', $id);
            ruiyi_debug_log("清理订单ID: $id -> $clean_id");
            if (!empty($clean_id)) {
                $cleaned_order_ids[] = intval($clean_id);
            }
        } else if (is_numeric($id)) {
            $cleaned_order_ids[] = intval($id);
            ruiyi_debug_log("数字类型订单ID: $id");
        } else {
            ruiyi_debug_log("跳过无效订单ID类型: " . gettype($id) . " - " . print_r($id, true));
        }
    }
    
    // 打印接收到的参数以便调试
    ruiyi_debug_log("餐桌号: $table_number, 支付方式: $payment_method, 清理后的订单IDs: " . implode(', ', $cleaned_order_ids));

    // 3. 检查必要参数是否存在
    if (empty($table_number)) {
        ruiyi_debug_log('缺少餐桌号参数');
        wp_send_json_error(['message' => '请求参数不完整 (餐桌号缺失)。'], 400);
        return;
    }
    
    if (empty($payment_method)) {
        ruiyi_debug_log('缺少支付方式参数');
        wp_send_json_error(['message' => '请求参数不完整 (支付方式缺失)。'], 400);
        return;
    }
    
    if (empty($cleaned_order_ids)) {
        ruiyi_debug_log('没有有效的订单ID');
        wp_send_json_error(['message' => '没有提供有效的订单ID。'], 400);
        return;
    }

    // 4. 初始化结果数组
    $results = [
        'success' => true,
        'processed_orders' => [],
        'failed_orders' => [],
        'total_processed' => 0
    ];

    // 🔥 4.5 如果有多个订单，先标记所有订单为"即将被合并"，防止日结单重复记录
    $will_merge_orders = (count($cleaned_order_ids) > 1);
    if ($will_merge_orders) {
        ruiyi_debug_log('检测到多个订单 (' . count($cleaned_order_ids) . ' 个)，标记为即将合并，防止重复记录到日结单');
        foreach ($cleaned_order_ids as $order_id) {
            $order = wc_get_order($order_id);
            if ($order) {
                $order->update_meta_data('_will_be_merged', 'yes');
                $order->save();
                ruiyi_debug_log('订单 #' . $order_id . ' 已标记为即将被合并');
            }
        }
    }

    // 5. 处理每个订单
    foreach ($cleaned_order_ids as $order_id) {
        $order = wc_get_order($order_id);
        if (!$order) {
            ruiyi_debug_log("找不到订单，ID: $order_id");
            $results['failed_orders'][] = [
                'id' => $order_id,
                'reason' => "未找到指定的订单"
            ];
            continue;
        }
        
        ruiyi_debug_log("处理订单 ID: $order_id, 状态: " . $order->get_status());

        try {
            // 🔥 关键修复：在更新订单状态之前先保存支付详情
            // 因为 update_status('completed') 会触发 woocommerce_order_status_completed hook
            // 该hook会调用日结单记录函数，此时必须确保支付元数据已经保存

            // 标准化支付方式代码
            $normalized_method = strtolower($payment_method);
            $payment_method_id = $payment_method;
            $payment_method_title = ucfirst($payment_method);

            if ($normalized_method === 'cash' || $normalized_method === 'efectivo') {
                $normalized_method = 'cod';
                $payment_title = 'Efectivo';
            } elseif ($normalized_method === 'card' || $normalized_method === 'tarjeta' || $normalized_method === 'debit card') {
                $normalized_method = 'bacs';
                $payment_title = 'Tarjeta';
            } elseif ($normalized_method === 'bizum') {
                $normalized_method = 'bizum';
                $payment_title = 'Bizum/Transferencia';
            } else {
                $payment_title = ucfirst($payment_method);
            }

            // 🔥 步骤1：保存支付详情到订单Meta（使用与外卖相同的逻辑和键名）
            // 优先级：混合支付 > 刷卡支付 > 现金支付 > 默认推断

            // 🔥 关键修复：先解析金额为浮点数，避免空字符串被isset误判
            $post_cash_amount = isset($_POST['cash_amount']) ? floatval($_POST['cash_amount']) : 0;
            $post_card_amount = isset($_POST['card_amount']) ? floatval($_POST['card_amount']) : 0;

            // 🔥 关键修复：只有当现金和刷卡金额都大于0时才是真正的混合支付
            if ($post_cash_amount > 0 && $post_card_amount > 0) {
                // ✓ 混合支付（现金和刷卡金额都大于0）
                $order->update_meta_data('_payment_method_detail', 'mixed');
                $order->update_meta_data('_cash_amount', round($post_cash_amount, 2));
                $order->update_meta_data('_card_amount', round($post_card_amount, 2));
                $payment_method_id = 'mixed_payment';
                $payment_method_title = __('Pago Mixto', 'ruiyi-pos');
                ruiyi_debug_log("POS桌位结账: 保存混合支付详情 - 现金: €" . $post_cash_amount . ", 刷卡: €" . $post_card_amount);
            } elseif ($normalized_method === 'bizum' || strtolower($payment_method) === 'bizum') {
                // ✓ Bizum/转账支付
                $bizum_amount = isset($_POST['bizum_amount']) ? round(floatval($_POST['bizum_amount']), 2) : round($order->get_total(), 2);
                $order->update_meta_data('_payment_method_detail', 'bizum');
                $order->update_meta_data('_bizum_amount', $bizum_amount);
                $order->delete_meta_data('_cash_amount');
                $order->delete_meta_data('_card_amount');
                $order->delete_meta_data('_received_amount');
                $order->delete_meta_data('_change_amount');
                $payment_method_id = 'bizum';
                $payment_method_title = __('Bizum/Transferencia', 'ruiyi-pos');
                ruiyi_debug_log("POS桌位结账: 保存Bizum支付详情 - 金额: €" . $bizum_amount);
            } elseif ($normalized_method === 'bacs' || strtolower($payment_method) === 'card' || strtolower($payment_method) === 'tarjeta') {
                // ✓ 其次判断刷卡支付（payment_method 为 card/bacs/tarjeta）
                $order->update_meta_data('_payment_method_detail', 'card');
                // 🔥 修复：优先使用前端传递的card_amount（折扣后金额），否则使用订单总额
                // 🔥 【精度修复】使用round()确保精度
                $final_card_amount = (isset($_POST['card_amount']) && floatval($_POST['card_amount']) > 0)
                    ? round(floatval($_POST['card_amount']), 2)
                    : round($order->get_total(), 2);
                $order->update_meta_data('_card_amount', $final_card_amount);
                // 🔥 修复：清除现金支付的元数据，避免被误判为混合支付
                $order->delete_meta_data('_cash_amount');
                $order->delete_meta_data('_received_amount');
                $order->delete_meta_data('_change_amount');
                $payment_method_id = 'bacs';
                $payment_method_title = __('Tarjeta', 'ruiyi-pos');
                ruiyi_debug_log("POS桌位结账: 保存刷卡支付详情 - 金额: " . $final_card_amount . " (前端传递: " . ($_POST['card_amount'] ?? '无') . ", 订单总额: " . $order->get_total() . ")");
            } elseif (isset($_POST['received_amount']) && floatval($_POST['received_amount']) > 0) {
                // ✓ 现金支付（有 received_amount，但不是混合支付，也不是刷卡）
                $order->update_meta_data('_payment_method_detail', 'cash');
                // 🔥 关键修复：优先使用前端传递的cash_amount（折扣后金额），否则使用订单总额
                // 🔥 【精度修复】使用round()确保精度
                $final_cash_amount = (isset($_POST['cash_amount']) && floatval($_POST['cash_amount']) > 0)
                    ? round(floatval($_POST['cash_amount']), 2)
                    : round($order->get_total(), 2);
                $order->update_meta_data('_cash_amount', $final_cash_amount);
                $order->update_meta_data('_received_amount', floatval($_POST['received_amount']));
                $order->update_meta_data('_change_amount', floatval($_POST['change_amount'] ?? 0));
                $payment_method_id = 'cod';
                $payment_method_title = __('Efectivo', 'ruiyi-pos');
                ruiyi_debug_log("POS桌位结账: 保存现金支付详情 - 金额: €{$final_cash_amount} (前端传递: " . ($_POST['cash_amount'] ?? '无') . ", 订单总额: " . $order->get_total() . "), 收款: " . $_POST['received_amount'] . ", 找零: " . ($_POST['change_amount'] ?? 0));
            } elseif ($normalized_method === 'cod' || strtolower($payment_method) === 'cash' || strtolower($payment_method) === 'efectivo') {
                // ✓ 现金支付的备选判断（基于 payment_method）
                $order->update_meta_data('_payment_method_detail', 'cash');
                // 🔥 关键修复：优先使用前端传递的cash_amount（折扣后金额）
                // 🔥 【精度修复】使用round()确保精度
                $final_cash_amount_fallback = (isset($_POST['cash_amount']) && floatval($_POST['cash_amount']) > 0)
                    ? round(floatval($_POST['cash_amount']), 2)
                    : round($order->get_total(), 2);
                $order->update_meta_data('_cash_amount', $final_cash_amount_fallback);
                $payment_method_id = 'cod';
                $payment_method_title = __('Efectivo', 'ruiyi-pos');
                ruiyi_debug_log("POS桌位结账: 保存支付详情（现金-默认推断） - 金额: €{$final_cash_amount_fallback}, 方式: " . $normalized_method);
            } else {
                // 其他情况：根据normalized_method推断
                if ($normalized_method === 'cod') {
                    $order->update_meta_data('_payment_method_detail', 'cash');
                    // 🔥 修复：优先使用前端传递的cash_amount
                    // 🔥 【精度修复】使用round()确保精度
                    $other_cash_amount = (isset($_POST['cash_amount']) && floatval($_POST['cash_amount']) > 0)
                        ? round(floatval($_POST['cash_amount']), 2)
                        : round($order->get_total(), 2);
                    $order->update_meta_data('_cash_amount', $other_cash_amount);
                    $payment_method_id = 'cod';
                    $payment_method_title = __('Efectivo', 'ruiyi-pos');
                } elseif ($normalized_method === 'bacs') {
                    $order->update_meta_data('_payment_method_detail', 'card');
                    // 🔥 修复：优先使用前端传递的card_amount（折扣后金额）
                    // 🔥 【精度修复】使用round()确保精度
                    $final_card_amount_fallback = (isset($_POST['card_amount']) && floatval($_POST['card_amount']) > 0)
                        ? round(floatval($_POST['card_amount']), 2)
                        : round($order->get_total(), 2);
                    $order->update_meta_data('_card_amount', $final_card_amount_fallback);
                    // 🔥 修复：清除现金支付的元数据
                    $order->delete_meta_data('_cash_amount');
                    $order->delete_meta_data('_received_amount');
                    $order->delete_meta_data('_change_amount');
                    $payment_method_id = 'bacs';
                    $payment_method_title = __('Tarjeta', 'ruiyi-pos');
                } else {
                    // 未知支付方式，默认为现金
                    $order->update_meta_data('_payment_method_detail', 'cash');
                    // 🔥 修复：优先使用前端传递的cash_amount
                    // 🔥 【精度修复】使用round()确保精度
                    $unknown_cash_amount = (isset($_POST['cash_amount']) && floatval($_POST['cash_amount']) > 0)
                        ? round(floatval($_POST['cash_amount']), 2)
                        : round($order->get_total(), 2);
                    $order->update_meta_data('_cash_amount', $unknown_cash_amount);
                    $payment_method_id = 'cod';
                    $payment_method_title = __('Efectivo', 'ruiyi-pos');
                }
                ruiyi_debug_log("POS桌位结账: 保存支付详情（其他-默认推断） - 方式: " . $normalized_method);
            }

            $order->set_payment_method($payment_method_id);
            $order->set_payment_method_title($payment_method_title);
            ruiyi_debug_log("已设置支付方式: $payment_method_id ($payment_method_title)");

            // 保存餐桌号
            if (!empty($table_number)) {
                $order->update_meta_data('_table_number', $table_number);
                $order->update_meta_data('table_number', $table_number);
                ruiyi_debug_log("已更新餐桌号元数据: $table_number");
            }

            // 检查是否有挂起的积分交易信息
            $pending_points = get_option('ruiyi_pending_points_transaction', false);
            if ($pending_points && (time() - $pending_points['timestamp'] < 300)) { // 5分钟内的交易
                // 将积分折扣信息添加到订单
                $order->update_meta_data('_points_used', $pending_points['points_used']);
                $order->update_meta_data('_points_discount_amount', $pending_points['discount_amount']);
                $order->update_meta_data('_points_user_id', $pending_points['user_id']);

                // 添加积分折扣备注
                $order->add_order_note(sprintf(
                    __('积分折扣: 使用%d积分，折扣金额€%.2f', 'ruiyi-pos'),
                    $pending_points['points_used'],
                    $pending_points['discount_amount']
                ));

                ruiyi_debug_log("已添加积分折扣信息到订单 $order_id - 积分: {$pending_points['points_used']}, 折扣: {$pending_points['discount_amount']}€");

                // 清除挂起的交易信息（仅对第一个处理的订单使用）
                delete_option('ruiyi_pending_points_transaction');
            }

            // 🔥 注意:餐厅抵扣票 (Cheque Restaurante) 的处理已移到循环外部
            // 避免在有多个订单时重复应用抵扣券
            // 抵扣券将在合并订单后统一应用(见下方代码)

            // 🔥 步骤2：保存订单（确保所有元数据写入数据库）
            // 🔥 【关键修复】在更改状态前，检查是否有待应用的折扣
            // 如果有，标记订单以防止Hook提前记录日结单（使用错误的原价）
            $has_pending_discount_for_hook = (isset($_POST['discount_percent']) && floatval($_POST['discount_percent']) > 0);
            if ($has_pending_discount_for_hook) {
                $order->update_meta_data('_has_pending_discount', 'yes');
                ruiyi_debug_log("订单 $order_id 有待应用折扣，已标记_has_pending_discount");
            }
            $order->save();
            ruiyi_debug_log("订单 $order_id 元数据已保存");

            // 🔥 步骤3：更新订单状态（触发 Hook，此时元数据已存在）
            $old_status = $order->get_status();
            $order->update_status('completed', __('订单已通过POS多订单结账功能完成支付。', 'ruiyi-pos'));
            ruiyi_debug_log("订单状态已更新: $old_status -> completed");

            // 🔥 步骤3.5：验证日结单是否已被hook自动记录，如果没有则手动记录（双重保险）
            $fresh_order = wc_get_order($order_id);
            $recorded = $fresh_order ? $fresh_order->get_meta('_recorded_in_daily_summary', true) : '';
            $will_merge = $fresh_order ? $fresh_order->get_meta('_will_be_merged', true) : '';

            // 🔥 【关键修复】检查是否有折扣需要应用 - 如果有，延迟日结单记录
            // 单个订单的折扣是在主循环结束后才应用的，所以需要延迟记录
            $has_pending_discount = (isset($_POST['discount_percent']) && floatval($_POST['discount_percent']) > 0 && count($cleaned_order_ids) === 1);

            // 只有非合并订单且没有待应用折扣才需要手动记录
            if ($recorded !== 'yes' && $will_merge !== 'yes' && !$has_pending_discount) {
                // 手动记录到日结单（作为备份）
                ruiyi_debug_log("[日结单] 🔧 订单 #{$order_id} 未被自动记录，手动触发记录（无待折扣）");
                if (function_exists('ruiyi_record_daily_transaction')) {
                    $items_for_daily = [];
                    foreach ($fresh_order->get_items() as $item) {
                        $items_for_daily[] = [
                            'name' => $item->get_name(),
                            'quantity' => $item->get_quantity(),
                            'total' => $item->get_total()
                        ];
                    }
                    // 🔥 关键修复：使用实际支付金额而不是订单总额
                    // 订单总额可能是原价（如果订单是在折扣前创建的）
                    // 实际支付金额从元数据中获取（已经是折扣后的金额）
                    $payment_detail = $fresh_order->get_meta('_payment_method_detail', true);
                    $actual_payment_amount = $fresh_order->get_total(); // 默认值

                    if ($payment_detail === 'mixed') {
                        // 混合支付：现金+刷卡
                        $meta_cash = floatval($fresh_order->get_meta('_cash_amount', true));
                        $meta_card = floatval($fresh_order->get_meta('_card_amount', true));
                        $actual_payment_amount = $meta_cash + $meta_card;
                    } elseif ($payment_detail === 'cash' || strtolower($payment_method) === 'cash' || strtolower($payment_method) === 'cod') {
                        // 现金支付
                        $meta_cash = floatval($fresh_order->get_meta('_cash_amount', true));
                        if ($meta_cash > 0) {
                            $actual_payment_amount = $meta_cash;
                        }
                    } elseif ($payment_detail === 'card' || strtolower($payment_method) === 'card' || strtolower($payment_method) === 'bacs') {
                        // 刷卡支付
                        $meta_card = floatval($fresh_order->get_meta('_card_amount', true));
                        if ($meta_card > 0) {
                            $actual_payment_amount = $meta_card;
                        }
                    }

                    ruiyi_record_daily_transaction($order_id, $payment_method, $actual_payment_amount, $items_for_daily);
                    $fresh_order->update_meta_data('_recorded_in_daily_summary', 'yes');
                    $fresh_order->save();
                    ruiyi_debug_log("[日结单] ✅ 订单 #{$order_id} 手动记录成功 - Payment: {$payment_method}, 实际金额: €{$actual_payment_amount}, 订单总额: €" . $fresh_order->get_total());
                }
            } else if ($will_merge === 'yes') {
                ruiyi_debug_log("[日结单] 跳过订单 #{$order_id} - 即将被合并");
            } else if ($has_pending_discount) {
                ruiyi_debug_log("[日结单] ⏳ 延迟订单 #{$order_id} - 有待应用折扣，稍后记录");
            } else {
                ruiyi_debug_log("[日结单] ✅ 订单 #{$order_id} 已被自动hook记录");
            }

            // 🔥 步骤4：添加订单备注
            if (strtolower($payment_method) === 'mixed') {
                // 混合支付：记录现金和刷卡金额
                $order->add_order_note(sprintf(
                    __('POS多订单支付详情：方式 - %s, 餐桌 - %s, 现金 - %s, 刷卡 - %s', 'ruiyi-pos'),
                    $payment_method,
                    $table_number,
                    wc_price($cash_amount),
                    wc_price($card_amount)
                ));
            } else {
                // 现金或刷卡支付：记录实收和找零
                $order->add_order_note(sprintf(
                    __('POS多订单支付详情：方式 - %s, 餐桌 - %s, 总实收 - %s, 总找零 - %s', 'ruiyi-pos'),
                    $payment_method,
                    $table_number,
                    wc_price($received_amount),
                    wc_price($change_amount)
                ));
            }
            ruiyi_debug_log("已添加订单备注");
            
            // 获取订单行项目
            $line_items_data = [];
            foreach ($order->get_items() as $item_id => $item) {
                $product = $item->get_product();
                $item_price = $product ? (float)$product->get_price() : ((float)$item->get_total() / (int)$item->get_quantity());
                if (is_nan($item_price) || !is_finite($item_price)) {
                    $item_price = 0; // Fallback for invalid price
                }

                $line_items_data[] = [
                    'name' => $item->get_name(),
                    'quantity' => $item->get_quantity(),
                    'price_per_unit' => round($item_price, 2),
                    'line_total' => round((float)$item->get_total(), 2)
                ];
            }

            $results['processed_orders'][] = [
                'id' => $order_id,
                'total' => round((float)$order->get_total(), 2),
                'items' => $line_items_data // 添加商品条目信息
            ];
            $results['total_processed']++;
            
        } catch (Exception $e) {
            ruiyi_debug_log("处理订单 $order_id 时发生异常: " . $e->getMessage());
            $results['failed_orders'][] = [
                'id' => $order_id,
                'reason' => $e->getMessage()
            ];
        }
    }
    
    // 6. 返回处理结果
    if ($results['total_processed'] > 0) {
        $results['message'] = sprintf(
            __('成功处理了 %d 个订单支付。', 'ruiyi-pos'),
            $results['total_processed']
        );

        if (count($results['failed_orders']) > 0) {
            $results['message'] .= sprintf(
                __(' %d 个订单处理失败。', 'ruiyi-pos'),
                count($results['failed_orders'])
            );
        }

        ruiyi_debug_log("多订单结账成功处理 {$results['total_processed']} 个订单，失败 " . count($results['failed_orders']) . " 个");

        // 🔥 关键修复：如果有多个订单（包括追加订单），调用合并函数
        $merged_order_id = null;
        if (count($cleaned_order_ids) > 1) {
            ruiyi_debug_log("检测到多个订单 (" . count($cleaned_order_ids) . " 个)，开始合并订单...");
            ruiyi_debug_log("订单IDs: " . implode(', ', $cleaned_order_ids));

            // 🔥 关键修复：传递支付信息给合并函数，确保在设置订单完成状态前正确设置支付元数据
            // 🔥 【新增】同时传递折扣信息，以便合并函数设置 _has_pending_discount 标记
            $has_discount = isset($_POST['discount_percent']) && floatval($_POST['discount_percent']) > 0;
            $payment_info = [
                'payment_method' => $payment_method,
                'received_amount' => $received_amount,
                'change_amount' => $change_amount,
                'cash_amount' => $cash_amount,
                'card_amount' => $card_amount,
                'has_pending_discount' => $has_discount, // 🔥 新增：告知合并函数是否有待应用折扣
                'discount_percent' => $has_discount ? floatval($_POST['discount_percent']) : 0,
                'discount_amount' => $has_discount && isset($_POST['discount_amount']) ? floatval($_POST['discount_amount']) : 0,
                'expected_total' => $has_discount && isset($_POST['total_amount']) ? floatval($_POST['total_amount']) : 0
            ];

            // 调用合并函数（传递支付信息）
            $merged_order_id = ruiyi_merge_table_orders($cleaned_order_ids, $table_number, $payment_info);

            if ($merged_order_id) {
                ruiyi_debug_log("订单合并成功，合并订单ID: #$merged_order_id");

                // 获取合并订单对象以验证数据
                $merged_order = wc_get_order($merged_order_id);
                if ($merged_order) {
                    $merged_total = $merged_order->get_total();
                    $merged_items_count = count($merged_order->get_items());
                    $original_order_numbers = $merged_order->get_meta('_original_order_numbers');

                    ruiyi_debug_log("合并订单验证 - 总额: €{$merged_total}, 商品数: {$merged_items_count}, 原始订单号: {$original_order_numbers}");

                    // 🔥 修复支付元数据 - 使用实际的支付金额而不是原始订单的
                    // 清除从原始订单复制的错误支付金额
                    ruiyi_debug_log("合并订单：开始更新支付元数据 - payment_method: {$payment_method}");
                    ruiyi_debug_log("合并订单：POST数据 - cash_amount: " . (isset($_POST['cash_amount']) ? $_POST['cash_amount'] : 'not set'));
                    ruiyi_debug_log("合并订单：POST数据 - card_amount: " . (isset($_POST['card_amount']) ? $_POST['card_amount'] : 'not set'));
                    ruiyi_debug_log("合并订单：POST数据 - received_amount: " . $received_amount);
                    ruiyi_debug_log("合并订单：POST数据 - change_amount: " . $change_amount);

                    if ($payment_method === 'mixed') {
                        // 混合支付：使用传递的现金和刷卡金额
                        $cash_amount = isset($_POST['cash_amount']) ? floatval($_POST['cash_amount']) : 0;
                        $card_amount = isset($_POST['card_amount']) ? floatval($_POST['card_amount']) : 0;

                        // 🔥 先删除旧的元数据，确保不会保留错误值
                        $merged_order->delete_meta_data('_payment_cash_amount');
                        $merged_order->delete_meta_data('_payment_card_amount');
                        $merged_order->delete_meta_data('_payment_total');
                        $merged_order->delete_meta_data('_received_amount');
                        $merged_order->delete_meta_data('_change_amount');

                        // 添加正确的支付元数据
                        $merged_order->add_meta_data('_payment_cash_amount', $cash_amount, true);
                        $merged_order->add_meta_data('_payment_card_amount', $card_amount, true);
                        $merged_order->add_meta_data('_payment_total', $cash_amount + $card_amount, true);
                        $merged_order->add_meta_data('_mixed_payment_processed', current_time('mysql'), true);

                        ruiyi_debug_log("合并订单：✅ 更新混合支付元数据 - 现金: €{$cash_amount}, 刷卡: €{$card_amount}, 总计: €" . ($cash_amount + $card_amount));
                    } elseif ($payment_method === 'cash') {
                        // 现金支付
                        // 🔥 先删除旧的元数据
                        $merged_order->delete_meta_data('_received_amount');
                        $merged_order->delete_meta_data('_change_amount');

                        // 添加正确的支付元数据
                        $merged_order->add_meta_data('_received_amount', $received_amount, true);
                        $merged_order->add_meta_data('_change_amount', $change_amount, true);
                        ruiyi_debug_log("合并订单：✅ 更新现金支付元数据 - 收款: €{$received_amount}, 找零: €{$change_amount}");
                    } elseif ($payment_method === 'card') {
                        // 🔥 新增：刷卡支付也要清除错误的元数据
                        $merged_order->delete_meta_data('_received_amount');
                        $merged_order->delete_meta_data('_change_amount');
                        $merged_order->delete_meta_data('_payment_cash_amount');
                        $merged_order->delete_meta_data('_payment_card_amount');

                        ruiyi_debug_log("合并订单：✅ 刷卡支付元数据已清理");
                    }

                    // 重新保存合并订单以应用更新的支付元数据
                    $merged_order->save();
                    ruiyi_debug_log("合并订单：支付元数据已更新并保存");

                    // 🔥 应用餐厅抵扣票 (Cheque Restaurante) 到合并订单
                    if (isset($_POST['cheque_restaurante_amount']) && floatval($_POST['cheque_restaurante_amount']) > 0) {
                        $cheque_restaurante = floatval($_POST['cheque_restaurante_amount']);

                        // 获取当前订单总额
                        $current_total = $merged_order->get_total();

                        // 添加费用项显示抵扣
                        $fee = new WC_Order_Item_Fee();
                        $fee->set_name(__('Cheque Restaurante', 'ruiyi-pos'));
                        $fee->set_amount(-$cheque_restaurante);
                        $fee->set_total(-$cheque_restaurante);
                        $merged_order->add_item($fee);

                        // 重新计算订单总额
                        $merged_order->calculate_totals();
                        $new_total = $merged_order->get_total();

                        // 保存抵扣券元数据
                        $merged_order->update_meta_data('_cheque_restaurante_amount', $cheque_restaurante);

                        // 添加订单备注
                        $merged_order->add_order_note(sprintf(
                            __('Cheque Restaurante aplicado: €%.2f (Total original: €%.2f, Nuevo total: €%.2f)', 'ruiyi-pos'),
                            $cheque_restaurante,
                            $current_total,
                            $new_total
                        ));

                        // 保存更新
                        $merged_order->save();

                        ruiyi_debug_log("合并订单：✅ 已应用餐厅抵扣票 - 抵扣: €{$cheque_restaurante}, 原总额: €{$current_total}, 新总额: €{$new_total}");
                    }

                    // 🔥 智能处理手动折扣 - 检测订单项目是否已有折扣价格
                    // 场景A：折扣在创建订单前应用 -> 订单项目已有折扣价格 -> 不添加折扣费用
                    // 场景B：折扣在创建订单后应用 -> 订单项目是原价 -> 需要添加折扣费用
                    if (isset($_POST['discount_percent']) && floatval($_POST['discount_percent']) > 0) {
                        $discount_percent = floatval($_POST['discount_percent']);
                        $discount_amount = isset($_POST['discount_amount']) ? floatval($_POST['discount_amount']) : 0;
                        $expected_total = isset($_POST['total_amount']) ? floatval($_POST['total_amount']) : 0;

                        // 获取当前订单总额
                        $current_total = $merged_order->get_total();

                        // 🔥 【关键修复】智能检测是否需要添加折扣费用项
                        // 如果当前订单总额明显高于前端传递的预期折扣后金额（允许0.05误差），
                        // 说明订单项目使用的是原价，需要添加折扣费用项
                        $needs_discount_fee = ($expected_total > 0 && $current_total > $expected_total + 0.05);

                        ruiyi_debug_log("合并订单：折扣检测 - 当前总额: €{$current_total}, 预期折扣后总额: €{$expected_total}, 需要添加折扣费用: " . ($needs_discount_fee ? 'YES' : 'NO'));

                        if ($needs_discount_fee) {
                            // 🔥 订单项目是原价，需要添加折扣费用项
                            // 计算实际折扣金额 = 当前总额 - 预期折扣后总额
                            $actual_discount_amount = round($current_total - $expected_total, 2);

                            // 添加折扣费用项
                            $fee = new WC_Order_Item_Fee();
                            $fee->set_name(sprintf(__('Descuento %d%%', 'ruiyi-pos'), $discount_percent));
                            $fee->set_amount(-$actual_discount_amount);
                            $fee->set_tax_class('');
                            $fee->set_tax_status('none');
                            $fee->set_total(-$actual_discount_amount);
                            $merged_order->add_item($fee);

                            // 重新计算订单总额
                            $merged_order->calculate_totals();
                            $new_total = $merged_order->get_total();

                            // 保存折扣元数据
                            $merged_order->update_meta_data('_manual_discount_percent', $discount_percent);
                            $merged_order->update_meta_data('_manual_discount_amount', round($actual_discount_amount, 2));
                            $merged_order->update_meta_data('_discount_applied_as_fee', 'yes');
                            $merged_order->add_order_note(sprintf(
                                __('Descuento aplicado: %d%% (€%.2f) - Total original: €%.2f, Total con descuento: €%.2f', 'ruiyi-pos'),
                                $discount_percent,
                                $actual_discount_amount,
                                $current_total,
                                $new_total
                            ));
                            $merged_order->save();

                            ruiyi_debug_log("合并订单：✅ 已添加折扣费用项 - 百分比: {$discount_percent}%, 折扣金额: €{$actual_discount_amount}, 原总额: €{$current_total}, 新总额: €{$new_total}");
                        } else {
                            // 🔥 订单项目已有折扣价格，只保存元数据
                            // 如果没有传递折扣金额，根据折扣后价格反推计算
                            if ($discount_amount <= 0) {
                                $original_total = round($current_total / (1 - $discount_percent / 100), 2);
                                $discount_amount = round($original_total - $current_total, 2);
                            }

                            $merged_order->update_meta_data('_manual_discount_percent', $discount_percent);
                            $merged_order->update_meta_data('_manual_discount_amount', round($discount_amount, 2));
                            $merged_order->add_order_note(sprintf(
                                __('Descuento manual: %d%% (€%.2f) - Total con descuento: €%.2f', 'ruiyi-pos'),
                                $discount_percent,
                                $discount_amount,
                                $current_total
                            ));
                            $merged_order->save();

                            ruiyi_debug_log("合并订单：✅ 订单项目已有折扣价格，只保存元数据 - 百分比: {$discount_percent}%, 折扣金额: €{$discount_amount}, 当前总额: €{$current_total}");
                        }

                        // 🔥 【关键修复】折扣应用后，更新支付金额meta为正确的折扣后金额
                        $fresh_merged_for_payment = wc_get_order($merged_order_id);
                        if ($fresh_merged_for_payment) {
                            $final_discounted_total_merged = round($fresh_merged_for_payment->get_total(), 2);
                            $payment_detail_merged = $fresh_merged_for_payment->get_meta('_payment_method_detail', true);
                            $payment_method_lower = strtolower($payment_method);
                            // 🔥 修复：添加WooCommerce标准支付方式的检测
                            $wc_payment_method = strtolower($fresh_merged_for_payment->get_payment_method());

                            ruiyi_debug_log("合并订单折扣后支付更新 - payment_detail: {$payment_detail_merged}, payment_method: {$payment_method_lower}, wc_method: {$wc_payment_method}");

                            // 🔥 混合支付：从POST参数读取各部分金额，并按比例调整
                            if ($payment_detail_merged === 'mixed' || $payment_method_lower === 'mixed') {
                                $original_cash = isset($_POST['cash_amount']) ? floatval($_POST['cash_amount']) : 0;
                                $original_card = isset($_POST['card_amount']) ? floatval($_POST['card_amount']) : 0;
                                $original_total = $original_cash + $original_card;

                                if ($original_total > 0) {
                                    // 按比例调整为折扣后金额
                                    $cash_ratio = $original_cash / $original_total;
                                    $card_ratio = $original_card / $original_total;
                                    $discounted_cash = round($final_discounted_total_merged * $cash_ratio, 2);
                                    $discounted_card = round($final_discounted_total_merged * $card_ratio, 2);

                                    // 确保总和正确（处理四舍五入误差）
                                    $diff = $final_discounted_total_merged - ($discounted_cash + $discounted_card);
                                    if (abs($diff) > 0) {
                                        $discounted_card = round($discounted_card + $diff, 2);
                                    }

                                    $fresh_merged_for_payment->update_meta_data('_cash_amount', $discounted_cash);
                                    $fresh_merged_for_payment->update_meta_data('_payment_cash_amount', $discounted_cash);
                                    $fresh_merged_for_payment->update_meta_data('_card_amount', $discounted_card);
                                    $fresh_merged_for_payment->update_meta_data('_payment_card_amount', $discounted_card);
                                    ruiyi_debug_log("合并订单：💳💵 混合支付已更新为折扣后金额 - 现金: €{$discounted_cash}, 刷卡: €{$discounted_card}");
                                } else {
                                    // 如果没有原始金额，平分
                                    $half = round($final_discounted_total_merged / 2, 2);
                                    $fresh_merged_for_payment->update_meta_data('_cash_amount', $half);
                                    $fresh_merged_for_payment->update_meta_data('_card_amount', $final_discounted_total_merged - $half);
                                    ruiyi_debug_log("合并订单：💳💵 混合支付（无原始比例）- 平分为: €{$half}");
                                }
                            } elseif ($payment_detail_merged === 'card' || $wc_payment_method === 'bacs' || $payment_method_lower === 'card' || $payment_method_lower === 'tarjeta' || $payment_method_lower === 'bacs') {
                                // 刷卡支付
                                $fresh_merged_for_payment->update_meta_data('_card_amount', $final_discounted_total_merged);
                                $fresh_merged_for_payment->update_meta_data('_payment_card_amount', $final_discounted_total_merged);
                                ruiyi_debug_log("合并订单：💳 已更新_card_amount为折扣后金额: €{$final_discounted_total_merged}");
                            } elseif ($payment_detail_merged === 'cash' || $wc_payment_method === 'cod' || $payment_method_lower === 'cash' || $payment_method_lower === 'efectivo' || $payment_method_lower === 'cod') {
                                // 现金支付
                                $fresh_merged_for_payment->update_meta_data('_cash_amount', $final_discounted_total_merged);
                                $fresh_merged_for_payment->update_meta_data('_payment_cash_amount', $final_discounted_total_merged);
                                ruiyi_debug_log("合并订单：💵 已更新_cash_amount为折扣后金额: €{$final_discounted_total_merged}");
                            } else {
                                // 默认更新现金金额
                                $fresh_merged_for_payment->update_meta_data('_cash_amount', $final_discounted_total_merged);
                                $fresh_merged_for_payment->update_meta_data('_payment_cash_amount', $final_discounted_total_merged);
                                ruiyi_debug_log("合并订单：💵 默认已更新_cash_amount为折扣后金额: €{$final_discounted_total_merged}");
                            }
                            $fresh_merged_for_payment->save();
                        }
                    }

                    // 返回合并订单ID和详细信息给前端
                    $results['merged_order_id'] = $merged_order_id;
                    // 🔥 使用最新的订单总额（可能已应用折扣或抵扣）
                    $results['merged_order_total'] = $merged_order->get_total();
                    $results['merged_items_count'] = $merged_items_count;
                    $results['original_order_ids'] = $cleaned_order_ids;
                    $results['original_order_numbers'] = $original_order_numbers; // 添加原始订单号用于小票显示

                    // 🔥 关键修复：将合并订单的详细商品信息也返回
                    $merged_items_data = [];
                    foreach ($merged_order->get_items() as $item_id => $item) {
                        $product = $item->get_product();
                        $item_price = $product ? (float)$product->get_price() : ((float)$item->get_total() / (int)$item->get_quantity());

                        $merged_items_data[] = [
                            'name' => $item->get_name(),
                            'quantity' => $item->get_quantity(),
                            'price_per_unit' => round($item_price, 2),
                            'line_total' => round((float)$item->get_total(), 2)
                        ];
                    }
                    $results['merged_order_items'] = $merged_items_data;
                    ruiyi_debug_log("合并订单商品数据已添加到响应 - 商品数: " . count($merged_items_data));

                    // 🔥 【关键修复】在折扣应用后记录日结单，确保使用正确的折扣后金额
                    $fresh_merged_order = wc_get_order($merged_order_id);
                    $recorded = $fresh_merged_order ? $fresh_merged_order->get_meta('_recorded_in_daily_summary', true) : '';

                    if ($fresh_merged_order && $recorded !== 'yes') {
                        ruiyi_debug_log("[日结单] 🔧 合并订单 #{$merged_order_id} 开始记录（折扣应用后）");
                        if (function_exists('ruiyi_record_daily_transaction')) {
                            $items_for_daily_merged = [];
                            foreach ($fresh_merged_order->get_items() as $item) {
                                $items_for_daily_merged[] = [
                                    'name' => $item->get_name(),
                                    'quantity' => $item->get_quantity(),
                                    'total' => $item->get_total()
                                ];
                            }
                            $final_payment_method_merged = $payment_method ?: 'cash';
                            $final_total_merged = $fresh_merged_order->get_total();
                            ruiyi_record_daily_transaction($merged_order_id, $final_payment_method_merged, $final_total_merged, $items_for_daily_merged);
                            $fresh_merged_order->update_meta_data('_recorded_in_daily_summary', 'yes');
                            // 🔥 清除待折扣标记
                            $fresh_merged_order->delete_meta_data('_has_pending_discount');
                            $fresh_merged_order->save();
                            ruiyi_debug_log("[日结单] ✅ 合并订单 #{$merged_order_id} 记录成功（折扣后） - Payment: {$final_payment_method_merged}, Total: €{$final_total_merged}");
                        }
                    } else if ($recorded === 'yes') {
                        ruiyi_debug_log("[日结单] ✅ 合并订单 #{$merged_order_id} 已被自动hook记录");
                    }
                } else {
                    ruiyi_debug_log("⚠️ 警告：合并订单ID返回了但无法获取订单对象");
                }
            } else {
                ruiyi_debug_log("⚠️ 警告：订单合并失败或返回false");
            }
        } else {
            ruiyi_debug_log("只有一个订单，无需合并");

            // 🔥 对于单个订单，也需要应用餐厅抵扣票 (Cheque Restaurante)
            if (isset($_POST['cheque_restaurante_amount']) && floatval($_POST['cheque_restaurante_amount']) > 0 && count($cleaned_order_ids) === 1) {
                $single_order_id = reset($cleaned_order_ids);
                $single_order = wc_get_order($single_order_id);

                if ($single_order) {
                    $cheque_restaurante = floatval($_POST['cheque_restaurante_amount']);
                    $current_total = $single_order->get_total();

                    // 添加费用项显示抵扣
                    $fee = new WC_Order_Item_Fee();
                    $fee->set_name(__('Cheque Restaurante', 'ruiyi-pos'));
                    $fee->set_amount(-$cheque_restaurante);
                    $fee->set_total(-$cheque_restaurante);
                    $single_order->add_item($fee);

                    // 重新计算订单总额
                    $single_order->calculate_totals();
                    $new_total = $single_order->get_total();

                    // 保存抵扣券元数据
                    $single_order->update_meta_data('_cheque_restaurante_amount', $cheque_restaurante);

                    // 添加订单备注
                    $single_order->add_order_note(sprintf(
                        __('Cheque Restaurante aplicado: €%.2f (Total original: €%.2f, Nuevo total: €%.2f)', 'ruiyi-pos'),
                        $cheque_restaurante,
                        $current_total,
                        $new_total
                    ));

                    // 保存更新
                    $single_order->save();

                    ruiyi_debug_log("单个订单：✅ 已应用餐厅抵扣票 - 订单ID: #{$single_order_id}, 抵扣: €{$cheque_restaurante}, 原总额: €{$current_total}, 新总额: €{$new_total}");
                }
            }

            // 🔥 智能处理手动折扣 - 检测订单项目是否已有折扣价格（单个订单）
            // 场景A：折扣在创建订单前应用 -> 订单项目已有折扣价格 -> 不添加折扣费用
            // 场景B：折扣在创建订单后应用 -> 订单项目是原价 -> 需要添加折扣费用
            if (isset($_POST['discount_percent']) && floatval($_POST['discount_percent']) > 0 && count($cleaned_order_ids) === 1) {
                $single_order_id = reset($cleaned_order_ids);
                $single_order = wc_get_order($single_order_id);

                if ($single_order) {
                    $discount_percent = floatval($_POST['discount_percent']);
                    $discount_amount = isset($_POST['discount_amount']) ? floatval($_POST['discount_amount']) : 0;
                    $expected_total = isset($_POST['total_amount']) ? floatval($_POST['total_amount']) : 0;

                    // 获取当前订单总额
                    $current_total = $single_order->get_total();

                    // 🔥 【关键修复】智能检测是否需要添加折扣费用项
                    // 如果当前订单总额明显高于前端传递的预期折扣后金额（允许0.05误差），
                    // 说明订单项目使用的是原价，需要添加折扣费用项
                    $needs_discount_fee = ($expected_total > 0 && $current_total > $expected_total + 0.05);

                    ruiyi_debug_log("单个订单：折扣检测 - 订单ID: #{$single_order_id}, 当前总额: €{$current_total}, 预期折扣后总额: €{$expected_total}, 需要添加折扣费用: " . ($needs_discount_fee ? 'YES' : 'NO'));

                    if ($needs_discount_fee) {
                        // 🔥 订单项目是原价，需要添加折扣费用项
                        // 计算实际折扣金额 = 当前总额 - 预期折扣后总额
                        $actual_discount_amount = round($current_total - $expected_total, 2);

                        // 添加折扣费用项
                        $fee = new WC_Order_Item_Fee();
                        $fee->set_name(sprintf(__('Descuento %d%%', 'ruiyi-pos'), $discount_percent));
                        $fee->set_amount(-$actual_discount_amount);
                        $fee->set_tax_class('');
                        $fee->set_tax_status('none');
                        $fee->set_total(-$actual_discount_amount);
                        $single_order->add_item($fee);

                        // 重新计算订单总额
                        $single_order->calculate_totals();
                        $new_total = $single_order->get_total();

                        // 保存折扣元数据
                        $single_order->update_meta_data('_manual_discount_percent', $discount_percent);
                        $single_order->update_meta_data('_manual_discount_amount', round($actual_discount_amount, 2));
                        $single_order->update_meta_data('_discount_applied_as_fee', 'yes');
                        $single_order->add_order_note(sprintf(
                            __('Descuento aplicado: %d%% (€%.2f) - Total original: €%.2f, Total con descuento: €%.2f', 'ruiyi-pos'),
                            $discount_percent,
                            $actual_discount_amount,
                            $current_total,
                            $new_total
                        ));
                        $single_order->save();

                        ruiyi_debug_log("单个订单：✅ 已添加折扣费用项 - 订单ID: #{$single_order_id}, 百分比: {$discount_percent}%, 折扣金额: €{$actual_discount_amount}, 原总额: €{$current_total}, 新总额: €{$new_total}");
                    } else {
                        // 🔥 订单项目已有折扣价格，只保存元数据
                        // 如果没有传递折扣金额，根据折扣后价格反推计算
                        if ($discount_amount <= 0) {
                            $original_total = round($current_total / (1 - $discount_percent / 100), 2);
                            $discount_amount = round($original_total - $current_total, 2);
                        }

                        $single_order->update_meta_data('_manual_discount_percent', $discount_percent);
                        $single_order->update_meta_data('_manual_discount_amount', round($discount_amount, 2));
                        $single_order->add_order_note(sprintf(
                            __('Descuento manual: %d%% (€%.2f) - Total con descuento: €%.2f', 'ruiyi-pos'),
                            $discount_percent,
                            $discount_amount,
                            $current_total
                        ));
                        $single_order->save();

                        ruiyi_debug_log("单个订单：✅ 订单项目已有折扣价格，只保存元数据 - 订单ID: #{$single_order_id}, 百分比: {$discount_percent}%, 折扣金额: €{$discount_amount}, 当前总额: €{$current_total}");
                    }

                    // 🔥 【关键修复】折扣应用后，更新支付金额meta为正确的折扣后金额
                    $fresh_single_order = wc_get_order($single_order_id);
                    if ($fresh_single_order) {
                        $final_discounted_total = round($fresh_single_order->get_total(), 2);
                        $payment_detail = $fresh_single_order->get_meta('_payment_method_detail', true);
                        $payment_method_lower = strtolower($payment_method);
                        // 🔥 修复：添加WooCommerce标准支付方式的检测
                        $wc_payment_method_single = strtolower($fresh_single_order->get_payment_method());

                        ruiyi_debug_log("单个订单折扣后支付更新 - payment_detail: {$payment_detail}, payment_method: {$payment_method_lower}, wc_method: {$wc_payment_method_single}");

                        // 🔥 混合支付：从POST参数读取各部分金额，并按比例调整
                        if ($payment_detail === 'mixed' || $payment_method_lower === 'mixed') {
                            $original_cash = isset($_POST['cash_amount']) ? floatval($_POST['cash_amount']) : 0;
                            $original_card = isset($_POST['card_amount']) ? floatval($_POST['card_amount']) : 0;
                            $original_total = $original_cash + $original_card;

                            if ($original_total > 0) {
                                // 按比例调整为折扣后金额
                                $cash_ratio = $original_cash / $original_total;
                                $card_ratio = $original_card / $original_total;
                                $discounted_cash = round($final_discounted_total * $cash_ratio, 2);
                                $discounted_card = round($final_discounted_total * $card_ratio, 2);

                                // 确保总和正确（处理四舍五入误差）
                                $diff = $final_discounted_total - ($discounted_cash + $discounted_card);
                                if (abs($diff) > 0) {
                                    $discounted_card = round($discounted_card + $diff, 2);
                                }

                                $fresh_single_order->update_meta_data('_cash_amount', $discounted_cash);
                                $fresh_single_order->update_meta_data('_card_amount', $discounted_card);
                                ruiyi_debug_log("单个订单：💳💵 混合支付已更新为折扣后金额 - 现金: €{$discounted_cash}, 刷卡: €{$discounted_card}");
                            } else {
                                // 如果没有原始金额，平分
                                $half = round($final_discounted_total / 2, 2);
                                $fresh_single_order->update_meta_data('_cash_amount', $half);
                                $fresh_single_order->update_meta_data('_card_amount', $final_discounted_total - $half);
                                ruiyi_debug_log("单个订单：💳💵 混合支付（无原始比例）- 平分为: €{$half}");
                            }
                        } elseif ($payment_detail === 'card' || $wc_payment_method_single === 'bacs' || $payment_method_lower === 'card' || $payment_method_lower === 'tarjeta' || $payment_method_lower === 'bacs') {
                            // 刷卡支付
                            $fresh_single_order->update_meta_data('_card_amount', $final_discounted_total);
                            $fresh_single_order->update_meta_data('_payment_card_amount', $final_discounted_total);
                            ruiyi_debug_log("单个订单：💳 已更新_card_amount为折扣后金额: €{$final_discounted_total}");
                        } elseif ($payment_detail === 'cash' || $wc_payment_method_single === 'cod' || $payment_method_lower === 'cash' || $payment_method_lower === 'efectivo' || $payment_method_lower === 'cod') {
                            // 现金支付
                            $fresh_single_order->update_meta_data('_cash_amount', $final_discounted_total);
                            $fresh_single_order->update_meta_data('_payment_cash_amount', $final_discounted_total);
                            ruiyi_debug_log("单个订单：💵 已更新_cash_amount为折扣后金额: €{$final_discounted_total}");
                        } else {
                            // 默认更新现金金额
                            $fresh_single_order->update_meta_data('_cash_amount', $final_discounted_total);
                            ruiyi_debug_log("单个订单：💵 默认已更新_cash_amount为折扣后金额: €{$final_discounted_total}");
                        }

                        // 🔥 清除待折扣标记
                        $fresh_single_order->delete_meta_data('_has_pending_discount');
                        $fresh_single_order->save();
                        ruiyi_debug_log("单个订单：已清除_has_pending_discount标记");
                    }

                    // 🔥 【关键修复】在折扣应用后记录日结单（单个订单）
                    // 重新获取最新订单数据
                    $fresh_single_order = wc_get_order($single_order_id);
                    $single_recorded = $fresh_single_order ? $fresh_single_order->get_meta('_recorded_in_daily_summary', true) : '';

                    if ($fresh_single_order && $single_recorded !== 'yes') {
                        ruiyi_debug_log("[日结单] 🔧 单个订单 #{$single_order_id} 开始记录（折扣应用后）");
                        if (function_exists('ruiyi_record_daily_transaction')) {
                            $items_for_daily_single = [];
                            foreach ($fresh_single_order->get_items() as $item) {
                                $items_for_daily_single[] = [
                                    'name' => $item->get_name(),
                                    'quantity' => $item->get_quantity(),
                                    'total' => $item->get_total()
                                ];
                            }
                            $final_payment_method_single = $payment_method ?: 'cash';
                            $final_total_single = $fresh_single_order->get_total();
                            ruiyi_record_daily_transaction($single_order_id, $final_payment_method_single, $final_total_single, $items_for_daily_single);
                            $fresh_single_order->update_meta_data('_recorded_in_daily_summary', 'yes');
                            $fresh_single_order->save();
                            ruiyi_debug_log("[日结单] ✅ 单个订单 #{$single_order_id} 记录成功（折扣后） - Payment: {$final_payment_method_single}, Total: €{$final_total_single}");
                        }
                    } else if ($single_recorded === 'yes') {
                        ruiyi_debug_log("[日结单] ✅ 单个订单 #{$single_order_id} 已被自动hook记录");
                    }
                }
            }
        }

        // 更新桌位状态为可用 (available)
        if (!empty($table_number)) {
            // 提取桌号中的数字部分
            $table_number_numeric = preg_replace('/[^0-9]/', '', $table_number);

            if (!empty($table_number_numeric)) {
                // 🔥 原子更新实时桌位状态（防止并发竞态）
                ruiyi_update_single_table_status($table_number_numeric, array(
                    'status' => 'libre',
                    'orderId' => 0,
                    'total' => 0,
                    'timestamp' => time()
                ));
                ruiyi_debug_log("桌位 {$table_number_numeric} 已更新为空闲状态");

                // 添加桌位状态更新信息到返回数据
                $results['table_status_updated'] = true;
                $results['table_number'] = $table_number_numeric;
            }
        }

        wp_send_json_success($results);
    } else {
        ruiyi_debug_log("多订单结账完全失败，没有处理成功的订单");
        wp_send_json_error([
            'message' => __('没有成功处理任何订单。', 'ruiyi-pos'),
            'failed_orders' => $results['failed_orders']
        ], 500);
    }

    wp_die();
}

/**
 * 临时授予删除订单权限的回调函数
 * 用于确保合并订单时可以永久删除旧订单
 */
function ruiyi_grant_trash_permission_temp($allcaps) {
    $allcaps['delete_posts'] = true;
    $allcaps['delete_published_posts'] = true;
    $allcaps['delete_shop_orders'] = true;
    $allcaps['delete_others_posts'] = true;
    $allcaps['delete_others_shop_orders'] = true;
    $allcaps['delete_private_posts'] = true;
    $allcaps['delete_private_shop_orders'] = true;
    return $allcaps;
}

/**
 * 🔧 诊断和清理孤立订单的工具函数
 * 找出所有仍在"正在处理"状态但应该被删除的订单
 * @return array 返回诊断结果
 */
function ruiyi_diagnose_orphan_orders() {
    global $wpdb;

    ruiyi_debug_log("=== 开始诊断孤立订单 ===");

    // 查询所有处于"processing"状态的订单
    $orphan_orders = $wpdb->get_results(
        "SELECT p.ID, p.post_title, p.post_status, p.post_date, pm.meta_value as table_number
         FROM {$wpdb->posts} p
         LEFT JOIN {$wpdb->postmeta} pm ON p.ID = pm.post_id AND pm.meta_key = '_table_number'
         WHERE p.post_type = 'shop_order' AND p.post_status = 'processing'
         ORDER BY p.post_date DESC"
    );

    $results = [
        'total_orphan_count' => count($orphan_orders),
        'orphan_orders' => []
    ];

    foreach ($orphan_orders as $order) {
        // 检查这个订单是否已被标记为已合并
        $is_merged = $wpdb->get_var(
            $wpdb->prepare(
                "SELECT meta_value FROM {$wpdb->postmeta} WHERE post_id = %d AND meta_key = '_is_merged'",
                $order->ID
            )
        );

        if ($is_merged === 'yes') {
            $merged_to = $wpdb->get_var(
                $wpdb->prepare(
                    "SELECT meta_value FROM {$wpdb->postmeta} WHERE post_id = %d AND meta_key = '_merged_to_order'",
                    $order->ID
                )
            );

            $results['orphan_orders'][] = [
                'order_id' => $order->ID,
                'order_title' => $order->post_title,
                'status' => $order->post_status,
                'table_number' => $order->table_number,
                'post_date' => $order->post_date,
                'is_merged' => true,
                'merged_to' => $merged_to,
                'issue' => '订单已标记为已合并，但Post记录仍存在'
            ];
        }
    }

    ruiyi_debug_log("诊断结果：发现 " . $results['total_orphan_count'] . " 个孤立订单");

    return $results;
}

/**
 * 🔧 批量清理孤立订单
 * @return array 返回清理结果
 */
function ruiyi_cleanup_orphan_orders() {
    $diagnosis = ruiyi_diagnose_orphan_orders();

    $cleanup_results = [
        'total_scanned' => $diagnosis['total_orphan_count'],
        'total_cleaned' => 0,
        'cleaned_orders' => []
    ];

    foreach ($diagnosis['orphan_orders'] as $orphan) {
        if ($orphan['is_merged']) {
            $delete_result = ruiyi_force_delete_order($orphan['order_id']);

            if ($delete_result) {
                $cleanup_results['total_cleaned']++;
                $cleanup_results['cleaned_orders'][] = [
                    'order_id' => $orphan['order_id'],
                    'status' => 'success',
                    'message' => '订单已成功删除'
                ];

                ruiyi_debug_log("✅ 已清理孤立订单 #" . $orphan['order_id']);
            } else {
                $cleanup_results['cleaned_orders'][] = [
                    'order_id' => $orphan['order_id'],
                    'status' => 'failed',
                    'message' => '订单删除失败'
                ];

                ruiyi_debug_log("❌ 清理孤立订单 #" . $orphan['order_id'] . " 失败");
            }
        }
    }

    ruiyi_debug_log("=== 孤立订单清理完成 - 共清理 " . $cleanup_results['total_cleaned'] . " 个订单 ===");

    return $cleanup_results;
}

/**
 * 🔥 增强版订单永久删除函数
 * 确保订单及其所有相关数据完全从数据库删除
 * @param int $order_id 订单ID
 * @return bool 成功返回true，失败返回false
 */
function ruiyi_force_delete_order($order_id) {
    ruiyi_debug_log("[订单删除] 开始执行强制删除 - 订单ID: #$order_id");

    try {
        // 获取订单对象
        $order = wc_get_order($order_id);

        if (!$order) {
            ruiyi_debug_log("[订单删除] 订单 #$order_id 不存在");
            return true;
        }

        // 🔥 使用 WooCommerce 原生 delete 方法（兼容 HPOS）
        // 参数 true = 永久删除（跳过回收站）
        $deleted = $order->delete(true);

        if ($deleted) {
            ruiyi_debug_log("✅ [订单删除] 订单 #$order_id 已通过WC原生方法成功删除");

            // 清除所有相关缓存
            wp_cache_delete($order_id, 'posts');
            wp_cache_delete($order_id, 'post_meta');
            wp_cache_delete($order_id, 'shop_order');
            wp_cache_delete($order_id, 'orders');
            clean_post_cache($order_id);

            // 清除订单相关的瞬时数据
            delete_transient('wc_order_' . $order_id);
            delete_transient('ruiyi_pos_order_' . $order_id);

            // 清理 WooCommerce 缓存
            if (function_exists('wc_delete_shop_order_transients')) {
                wc_delete_shop_order_transients($order_id);
            }

            // 清理统计缓存
            delete_transient('wc_orders_count');
            delete_transient('wc_processing_order_count');

            // 全局缓存刷新
            wp_cache_flush();

            ruiyi_debug_log("✅ [订单删除] 已清理所有缓存");

            return true;
        } else {
            ruiyi_debug_log("❌ [订单删除] WooCommerce删除方法返回false - 订单ID: #$order_id");
            return false;
        }

    } catch (Exception $e) {
        ruiyi_debug_log("❌ [订单删除] 异常错误 - 订单ID: #$order_id, 错误: " . $e->getMessage());
        return false;
    }
}

/**
 * 合并多个桌位订单为一个总订单
 * @param array $order_ids 要合并的订单ID数组
 * @param string $table_number 桌号
 * @param array $payment_info 支付信息（用于离线订单同步时正确设置支付元数据）
 * @return int|false 合并后的新订单ID，失败返回false
 */
function ruiyi_merge_table_orders($order_ids, $table_number = '', $payment_info = []) {
    ruiyi_debug_log('=== 开始合并订单 ===');
    ruiyi_debug_log('要合并的订单IDs: ' . implode(', ', $order_ids));

    if (empty($order_ids) || !is_array($order_ids)) {
        ruiyi_debug_log('合并订单失败：无效的订单ID数组');
        return false;
    }

    // 如果只有一个订单，不需要合并
    if (count($order_ids) === 1) {
        ruiyi_debug_log('只有一个订单，无需合并');
        return reset($order_ids);
    }

    // 创建合并锁，防止重复合并相同的订单组合
    sort($order_ids); // 排序确保锁的一致性
    $merge_lock_key = 'merge_lock_' . md5(implode('_', $order_ids));

    // 检查是否已经有相同的合并在进行中
    if (get_transient($merge_lock_key)) {
        $existing_merged_id = get_transient($merge_lock_key);
        ruiyi_debug_log("合并订单已存在或正在进行中，返回现有合并订单ID: #$existing_merged_id");
        return $existing_merged_id;
    }

    // 检查这些订单是否已经被合并过
    foreach ($order_ids as $order_id) {
        $order = wc_get_order($order_id);
        if ($order && $order->get_meta('_is_merged') === 'yes') {
            $existing_merged_to = $order->get_meta('_merged_to_order');
            ruiyi_debug_log("订单 #$order_id 已经被合并到 #$existing_merged_to，跳过重复合并");
            return $existing_merged_to;
        }
    }

    // 设置合并锁，防止并发合并
    set_transient($merge_lock_key, 'processing', 60); // 60秒锁定期

    // 创建新的合并订单
    $merged_order = wc_create_order();
    if (!$merged_order) {
        ruiyi_debug_log('创建合并订单失败');
        delete_transient($merge_lock_key); // 清除锁
        return false;
    }

    $total_amount = 0;
    $all_items = [];
    $customer_id = 0;
    $original_order_numbers = [];

    // 收集所有订单的商品和信息
    foreach ($order_ids as $order_id) {
        $order = wc_get_order($order_id);
        if (!$order) {
            ruiyi_debug_log("订单 #{$order_id} 不存在，跳过");
            continue;
        }

        $original_order_numbers[] = '#' . $order->get_order_number();

        // 获取客户ID（使用第一个有客户的订单）
        if (!$customer_id && $order->get_customer_id()) {
            $customer_id = $order->get_customer_id();
        }

        // 复制订单商品到合并订单
        foreach ($order->get_items() as $item) {
            $product = $item->get_product();
            if (!$product) continue;

            // 添加商品到合并订单
            $item_id = $merged_order->add_product(
                $product,
                $item->get_quantity(),
                [
                    'subtotal' => $item->get_subtotal(),
                    'total' => $item->get_total(),
                ]
            );

            // 复制商品元数据
            if ($item_id) {
                $new_item = $merged_order->get_item($item_id);
                foreach ($item->get_meta_data() as $meta) {
                    $new_item->add_meta_data($meta->key, $meta->value, true);
                }
                $new_item->save();
            }
        }

        // 复制费用项（如折扣、小费等）
        foreach ($order->get_fees() as $fee) {
            $fee_item = new WC_Order_Item_Fee();
            $fee_item->set_name($fee->get_name());
            $fee_item->set_amount($fee->get_amount());
            $fee_item->set_tax_class($fee->get_tax_class());
            $fee_item->set_tax_status($fee->get_tax_status());
            $fee_item->set_total($fee->get_total());
            $merged_order->add_item($fee_item);
        }

        $total_amount += $order->get_total();
    }

    // 设置合并订单的信息
    if ($customer_id) {
        $merged_order->set_customer_id($customer_id);
    }

    // 添加订单备注说明这是合并订单
    $merged_order->add_order_note(sprintf(
        __('订单合并自: %s (桌号: %s)', 'ruiyi-pos'),
        implode(', ', $original_order_numbers),
        $table_number
    ));

    // 设置订单元数据
    $merged_order->update_meta_data('_merged_from_orders', $order_ids);
    $merged_order->update_meta_data('_table_number', $table_number);
    $merged_order->update_meta_data('_is_merged_order', 'yes');
    $merged_order->update_meta_data('_original_order_numbers', implode(', ', $original_order_numbers));

    // 复制积分折扣元数据（如果存在）
    $total_points_used = 0;
    $total_points_discount = 0;
    $points_user_id = null;

    foreach ($order_ids as $order_id) {
        $order = wc_get_order($order_id);
        if ($order) {
            $order_points_used = $order->get_meta('_points_discount_used');
            $order_points_discount = $order->get_meta('_points_discount_amount');
            $order_user_id = $order->get_meta('_points_discount_user_id');

            if ($order_points_used && $order_points_discount) {
                $total_points_used += intval($order_points_used);
                $total_points_discount += floatval($order_points_discount);
                if (!$points_user_id) {
                    $points_user_id = $order_user_id;
                }
                ruiyi_debug_log("合并订单：从订单 #$order_id 复制积分折扣 - 积分: $order_points_used, 折扣: €$order_points_discount");
            }
        }
    }

    // 如果有积分折扣，添加到合并订单
    if ($total_points_used > 0 && $total_points_discount > 0) {
        $merged_order->update_meta_data('_points_discount_used', $total_points_used);
        $merged_order->update_meta_data('_points_discount_amount', $total_points_discount);
        if ($points_user_id) {
            $merged_order->update_meta_data('_points_discount_user_id', $points_user_id);
        }
        ruiyi_debug_log("合并订单：添加总积分折扣元数据 - 总积分: $total_points_used, 总折扣: €$total_points_discount");
    }

    // 🔥 修复bug：设置正确的支付元数据（使用合并订单的总额而不是单个订单金额）
    // 🔥 关键修复：优先使用传递的 $payment_info（来自离线同步），否则从第一个订单获取
    $merged_total = $merged_order->get_total();

    // 确定支付方式和金额
    $payment_method = '';
    $payment_method_detail = '';
    $received_amount = 0;
    $change_amount = 0;
    $cash_amount = 0;
    $card_amount = 0;

    // 🔥 如果提供了 $payment_info（离线同步场景），优先使用它
    if (!empty($payment_info) && !empty($payment_info['payment_method'])) {
        $payment_method = $payment_info['payment_method'];
        $payment_method_detail = $payment_method; // 使用相同值
        $received_amount = isset($payment_info['received_amount']) ? floatval($payment_info['received_amount']) : 0;
        $change_amount = isset($payment_info['change_amount']) ? floatval($payment_info['change_amount']) : 0;
        $cash_amount = isset($payment_info['cash_amount']) ? floatval($payment_info['cash_amount']) : 0;
        $card_amount = isset($payment_info['card_amount']) ? floatval($payment_info['card_amount']) : 0;

        ruiyi_debug_log("合并订单：使用传递的支付信息 - method: {$payment_method}, cash: €{$cash_amount}, card: €{$card_amount}");
    } else {
        // 从第一个订单获取支付方式类型
        $first_order = wc_get_order($order_ids[0]);
        if ($first_order) {
            $payment_method = $first_order->get_payment_method();
            $payment_method_detail = $first_order->get_meta('_payment_method_detail');
            $received_amount = floatval($first_order->get_meta('_received_amount'));
            $change_amount = floatval($first_order->get_meta('_change_amount'));
            $cash_amount = floatval($first_order->get_meta('_cash_amount') ?: $first_order->get_meta('_payment_cash_amount'));
            $card_amount = floatval($first_order->get_meta('_card_amount') ?: $first_order->get_meta('_payment_card_amount'));

            ruiyi_debug_log("合并订单：从第一个订单获取支付信息 - method: {$payment_method}, detail: {$payment_method_detail}");
        }
    }

    // 设置WooCommerce标准支付方式
    if ($payment_method) {
        $merged_order->set_payment_method($payment_method);
        // 根据支付方式设置标题
        $payment_titles = [
            'cash' => __('现金支付', 'ruiyi-pos'),
            'card' => __('刷卡支付', 'ruiyi-pos'),
            'mixed' => __('混合支付', 'ruiyi-pos'),
            'cod' => __('现金支付', 'ruiyi-pos')
        ];
        $merged_order->set_payment_method_title($payment_titles[$payment_method] ?? $payment_method);
    }
    if ($payment_method_detail) {
        $merged_order->update_meta_data('_payment_method_detail', $payment_method_detail);
    }

    // 🔥 关键修复：在设置订单完成状态之前，先设置正确的支付元数据
    // 这样 woocommerce_order_status_completed 钩子触发时，日结单记录函数可以读取到正确的支付信息
    if ($payment_method_detail === 'cash' || $payment_method === 'cash' || $payment_method === 'cod') {
        // 现金支付：设置现金金额
        $final_cash_amount = $cash_amount > 0 ? $cash_amount : $merged_total;
        $merged_order->update_meta_data('_cash_amount', $final_cash_amount);
        $merged_order->update_meta_data('_payment_cash_amount', $final_cash_amount);

        if ($received_amount > 0) {
            $merged_order->update_meta_data('_received_amount', $received_amount);
        }
        if ($change_amount > 0) {
            $merged_order->update_meta_data('_change_amount', $change_amount);
        }

        // 清除刷卡相关元数据
        $merged_order->delete_meta_data('_card_amount');
        $merged_order->delete_meta_data('_payment_card_amount');

        ruiyi_debug_log("合并订单：现金支付 - 现金金额: €{$final_cash_amount}, 收款: €{$received_amount}, 找零: €{$change_amount}");

    } elseif ($payment_method_detail === 'card' || $payment_method === 'card') {
        // 刷卡支付：设置刷卡金额为合并订单总额
        $merged_order->update_meta_data('_card_amount', $merged_total);
        $merged_order->update_meta_data('_payment_card_amount', $merged_total);
        // 清除现金支付的元数据，避免被误判为混合支付
        $merged_order->delete_meta_data('_cash_amount');
        $merged_order->delete_meta_data('_payment_cash_amount');
        $merged_order->delete_meta_data('_received_amount');
        $merged_order->delete_meta_data('_change_amount');

        ruiyi_debug_log("合并订单：刷卡支付 - 金额设置为合并总额: €{$merged_total}");

    } elseif ($payment_method_detail === 'mixed' || $payment_method === 'mixed') {
        // 混合支付：使用传递的现金和刷卡金额
        if ($cash_amount > 0 && $card_amount > 0) {
            $merged_order->update_meta_data('_cash_amount', $cash_amount);
            $merged_order->update_meta_data('_payment_cash_amount', $cash_amount);
            $merged_order->update_meta_data('_card_amount', $card_amount);
            $merged_order->update_meta_data('_payment_card_amount', $card_amount);
            $merged_order->update_meta_data('_payment_total', $merged_total);
            $merged_order->update_meta_data('_mixed_payment_processed', current_time('mysql'));

            ruiyi_debug_log("合并订单：混合支付 - 现金: €{$cash_amount}, 刷卡: €{$card_amount}, 总计: €{$merged_total}");
        } else {
            // 如果缺少详细金额，按50/50分配
            $merged_cash = $merged_total * 0.5;
            $merged_card = $merged_total * 0.5;

            $merged_order->update_meta_data('_cash_amount', $merged_cash);
            $merged_order->update_meta_data('_payment_cash_amount', $merged_cash);
            $merged_order->update_meta_data('_card_amount', $merged_card);
            $merged_order->update_meta_data('_payment_card_amount', $merged_card);
            $merged_order->update_meta_data('_payment_total', $merged_total);

            ruiyi_debug_log("合并订单：混合支付（默认50/50分配） - 现金: €{$merged_cash}, 刷卡: €{$merged_card}, 总计: €{$merged_total}");
        }
    }

    ruiyi_debug_log("合并订单：支付方式已设置 - Method: {$payment_method}, Detail: {$payment_method_detail}, Total: €{$merged_total}");

    // 计算总额
    $merged_order->calculate_totals();

    // 🔥 【关键修复】在设置订单状态前检查是否有待应用折扣
    // 如果有折扣，设置 _has_pending_discount 标记，防止自动hook提前记录日结单
    $has_pending_discount = !empty($payment_info['has_pending_discount']);
    if ($has_pending_discount) {
        $merged_order->update_meta_data('_has_pending_discount', 'yes');
        $discount_percent = isset($payment_info['discount_percent']) ? $payment_info['discount_percent'] : 0;
        ruiyi_debug_log("合并订单：检测到待应用折扣 {$discount_percent}%，设置 _has_pending_discount 标记（防止自动hook提前记录）");
    }

    // 保存元数据后再设置状态
    $merged_order->save();

    // 设置订单状态为完成（这会触发 woocommerce_order_status_completed hook）
    // 但由于 _has_pending_discount 标记，自动日结单记录会被跳过
    $merged_order->update_status('completed', __('合并订单已完成支付', 'ruiyi-pos'));

    // 再次保存订单
    $merged_order->save();

    $merged_order_id = $merged_order->get_id();
    ruiyi_debug_log("成功创建合并订单 #{$merged_order_id}，总金额: " . $merged_order->get_total());

    // 🔥 【关键修复】不在此处记录日结单，延迟到折扣应用后再记录
    // 因为折扣费用是在 ruiyi_pos_complete_multiple_orders_callback 中添加的
    // 如果在这里记录，会使用折扣前的金额，导致日结单总额错误
    if ($has_pending_discount) {
        ruiyi_debug_log("[日结单] ⏳ 合并订单 #{$merged_order_id} 有待应用折扣，延迟记录（已设置 _has_pending_discount 标记）");
    } else {
        ruiyi_debug_log("[日结单] ⏳ 合并订单 #{$merged_order_id} 延迟记录，等待主函数决定记录时机");
    }

    // 处理原始订单
    foreach ($order_ids as $order_id) {
        $original_order = wc_get_order($order_id);
        if ($original_order) {
            // 添加备注说明已合并
            $original_order->add_order_note(sprintf(
                __('订单已合并到 #%s，并移至回收站', 'ruiyi-pos'),
                $merged_order_id
            ));

            // 标记为已合并（在移到回收站之前先标记）
            $original_order->update_meta_data('_merged_to_order', $merged_order_id);
            $original_order->update_meta_data('_is_merged', 'yes');
            $original_order->update_meta_data('_merged_date', current_time('mysql'));
            $original_order->update_meta_data('_original_status', $original_order->get_status()); // 保存原始状态以便恢复时使用
            $original_order->save();

            ruiyi_debug_log("RUIYI POS: 订单 #{$order_id} 已标记为已合并，准备移至回收站");

            // 🔥 检查当前用户权限
            $current_user = wp_get_current_user();
            ruiyi_debug_log("RUIYI POS: 当前用户: " . $current_user->user_login . " (ID: " . $current_user->ID . ")");
            ruiyi_debug_log("RUIYI POS: 用户角色: " . implode(', ', $current_user->roles));
            ruiyi_debug_log("RUIYI POS: 是否有delete_posts权限: " . (current_user_can('delete_posts') ? '是' : '否'));
            ruiyi_debug_log("RUIYI POS: 是否有delete_published_posts权限: " . (current_user_can('delete_published_posts') ? '是' : '否'));

            // 🔥 使用增强版强制删除函数 - 确保订单及其所有数据完全删除
            $delete_result = ruiyi_force_delete_order($order_id);

            if ($delete_result) {
                ruiyi_debug_log("✅ 订单 #{$order_id} 已成功永久删除（使用增强版删除函数）");
            } else {
                ruiyi_debug_log("❌ 订单 #{$order_id} 删除失败，但已清理所有相关数据");
            }
        }
    }

    // 更新锁为实际的合并订单ID，供后续调用返回
    set_transient($merge_lock_key, $merged_order_id, 300); // 5分钟有效期

    ruiyi_debug_log("=== 合并订单完成，ID: #$merged_order_id ===");
    return $merged_order_id;
}

/**
 * 恢复已合并的订单（仅用于撤销合并操作）
 * 注意：由于原始订单已被永久删除，此功能将重新创建订单
 * @param int $merged_order_id 合并订单的ID
 * @return bool 成功返回true，失败返回false
 */
function ruiyi_restore_merged_orders($merged_order_id) {
    ruiyi_debug_log("⚠️ 警告：尝试恢复已永久删除的合并订单 #{$merged_order_id}");
    ruiyi_debug_log("   ℹ️ 原始订单已被永久删除，无法从回收站恢复");
    ruiyi_debug_log("   💡 建议：如需撤销合并，请联系管理员手动处理");

    $merged_order = wc_get_order($merged_order_id);
    if (!$merged_order) {
        ruiyi_debug_log("合并订单 #{$merged_order_id} 不存在");
        return false;
    }

    // 获取原始订单ID列表
    $original_order_ids = $merged_order->get_meta('_merged_from_orders');
    if (empty($original_order_ids) || !is_array($original_order_ids)) {
        ruiyi_debug_log("没有找到原始订单ID");
        return false;
    }

    $restored_count = 0;
    foreach ($original_order_ids as $order_id) {
        // 检查订单是否存在（已被永久删除，不会存在）
        $post = get_post($order_id);
        if ($post && $post->post_status === 'trash') {
            // 从回收站恢复（但实际上订单已被永久删除，这段代码不会执行）
            $restored = wp_untrash_post($order_id);
            if ($restored) {
                $order = wc_get_order($order_id);
                if ($order) {
                    // 恢复到原始状态（如果有记录的话）
                    $original_status = $order->get_meta('_original_status');
                    $restore_status = $original_status ? $original_status : 'pending';

                    $order->update_status($restore_status, __('订单已从回收站恢复', 'ruiyi-pos'));
                    $order->add_order_note(__('订单已从回收站恢复到原始状态，合并已撤销', 'ruiyi-pos'));

                    // 移除合并标记
                    $order->delete_meta_data('_merged_to_order');
                    $order->delete_meta_data('_is_merged');
                    $order->delete_meta_data('_merged_date');
                    $order->delete_meta_data('_original_status');
                    $order->save();

                    $restored_count++;
                    ruiyi_debug_log("成功恢复订单 #{$order_id} 到状态：{$restore_status}");
                }
            }
        }
    }

    // 取消合并订单
    if ($restored_count > 0) {
        $merged_order->update_status('cancelled', __('合并已撤销，原订单已恢复', 'ruiyi-pos'));
        $merged_order->save();
        ruiyi_debug_log("合并订单 #{$merged_order_id} 已取消，恢复了 {$restored_count} 个原始订单");
        return true;
    }

    return false;
}

/**
 * AJAX处理函数：诊断孤立订单
 * 扫描并报告所有未被正确删除的孤立订单
 */
add_action('wp_ajax_ruiyi_diagnose_orphan_orders', 'ruiyi_diagnose_orphan_orders_callback');
add_action('wp_ajax_nopriv_ruiyi_diagnose_orphan_orders', 'ruiyi_diagnose_orphan_orders_callback');

function ruiyi_diagnose_orphan_orders_callback() {
    if (!is_user_logged_in()) {
        wp_send_json_error(['message' => 'Authentication required']);
        return;
    }

    check_ajax_referer('ruiyi_pos_nonce', 'nonce');

    $diagnosis = ruiyi_diagnose_orphan_orders();

    wp_send_json_success([
        'message' => '诊断完成',
        'total_orphan_count' => $diagnosis['total_orphan_count'],
        'orphan_orders' => $diagnosis['orphan_orders']
    ]);
}

/**
 * AJAX处理函数：清理孤立订单
 * 批量删除所有已标记为合并但未被删除的订单
 */
add_action('wp_ajax_ruiyi_cleanup_orphan_orders', 'ruiyi_cleanup_orphan_orders_callback');
add_action('wp_ajax_nopriv_ruiyi_cleanup_orphan_orders', 'ruiyi_cleanup_orphan_orders_callback');

function ruiyi_cleanup_orphan_orders_callback() {
    if (!is_user_logged_in()) {
        wp_send_json_error(['message' => 'Authentication required']);
        return;
    }

    check_ajax_referer('ruiyi_pos_nonce', 'nonce');

    $cleanup_results = ruiyi_cleanup_orphan_orders();

    wp_send_json_success([
        'message' => '清理完成',
        'total_scanned' => $cleanup_results['total_scanned'],
        'total_cleaned' => $cleanup_results['total_cleaned'],
        'cleaned_orders' => $cleanup_results['cleaned_orders']
    ]);
}

/**
 * AJAX处理函数：合并桌位订单
 * 可以从前端直接调用来合并订单
 */
add_action('wp_ajax_ruiyi_pos_merge_table_orders', 'ruiyi_pos_merge_table_orders_callback');
function ruiyi_pos_merge_table_orders_callback() {
    check_ajax_referer('ruiyi_pos_nonce', 'nonce');

    $order_ids_json = isset($_POST['order_ids']) ? stripslashes($_POST['order_ids']) : '[]';
    $order_ids = json_decode($order_ids_json, true);
    $table_number = isset($_POST['table_number']) ? sanitize_text_field($_POST['table_number']) : '';

    if (empty($order_ids) || !is_array($order_ids)) {
        wp_send_json_error(['message' => '无效的订单ID列表']);
        return;
    }

    // 执行合并
    $merged_order_id = ruiyi_merge_table_orders($order_ids, $table_number);

    if ($merged_order_id) {
        $merged_order = wc_get_order($merged_order_id);

        // 获取Verifactu二维码（如果插件已激活）
        $verifactu_qr = '';
        if ($merged_order && ruiyi_has_verifactu()) {
            $verifactu_qr = $merged_order->get_meta('_verifactu_qr_base64');
        }

        wp_send_json_success([
            'message' => '订单合并成功',
            'merged_order_id' => $merged_order_id,
            'merged_order_total' => $merged_order ? $merged_order->get_total() : 0,
            'verifactu_qr' => $verifactu_qr,
            'original_orders' => $order_ids
        ]);
    } else {
        wp_send_json_error(['message' => '订单合并失败']);
    }
}

/**
 * AJAX处理函数：恢复已合并的订单
 * 从回收站恢复原始订单并取消合并订单
 */
add_action('wp_ajax_ruiyi_pos_restore_merged_orders', 'ruiyi_pos_restore_merged_orders_callback');
function ruiyi_pos_restore_merged_orders_callback() {
    check_ajax_referer('ruiyi_pos_nonce', 'nonce');

    $merged_order_id = isset($_POST['merged_order_id']) ? intval($_POST['merged_order_id']) : 0;

    if (!$merged_order_id) {
        wp_send_json_error(['message' => '无效的合并订单ID']);
        return;
    }

    // 执行恢复
    $result = ruiyi_restore_merged_orders($merged_order_id);

    if ($result) {
        wp_send_json_success([
            'message' => '订单恢复成功',
            'merged_order_id' => $merged_order_id
        ]);
    } else {
        wp_send_json_error(['message' => '订单恢复失败']);
    }
}

add_action('wp_ajax_ruiyi_pos_get_table_receipt_html', 'ruiyi_pos_get_table_receipt_html_callback');
add_action('wp_ajax_ruiyi_get_order_products_tax_rates', 'ruiyi_get_order_products_tax_rates_callback');
add_action('wp_ajax_ruiyi_get_cart_products_tax_rates', 'ruiyi_get_cart_products_tax_rates_callback');

// 获取订单产品的分类税率
function ruiyi_get_order_products_tax_rates_callback() {
    check_ajax_referer('ruiyi_pos_nonce', 'nonce');

    $order_ids_json = isset($_POST['order_ids']) ? stripslashes($_POST['order_ids']) : '[]';
    $order_ids = json_decode($order_ids_json, true);

    if (!is_array($order_ids) || empty($order_ids)) {
        wp_send_json_error(['message' => 'No order IDs provided']);
        return;
    }

    $products_with_tax_rates = [];

    ruiyi_debug_log('RUIYI TAX: 开始获取订单产品税率，订单IDs: ' . implode(',', $order_ids));

    foreach ($order_ids as $order_id) {
        $order = wc_get_order($order_id);
        if (!$order) {
            ruiyi_debug_log('RUIYI TAX: 订单不存在 ID: ' . $order_id);
            continue;
        }

        ruiyi_debug_log('RUIYI TAX: 处理订单 #' . $order_id);

        foreach ($order->get_items() as $item_id => $item) {
            $product_id = $item->get_product_id();
            $product = wc_get_product($product_id);

            if (!$product) {
                ruiyi_debug_log('RUIYI TAX: 产品不存在 ID: ' . $product_id);
                continue;
            }

            $product_name = $item->get_name();
            $quantity = $item->get_quantity();
            $line_total = $item->get_total();

            // 获取产品的实际税率
            $tax_rate = ruiyi_get_product_tax_rate($product);

            $products_with_tax_rates[] = [
                'name' => $product_name,
                'quantity' => $quantity,
                'line_total' => $line_total,
                'tax_rate' => $tax_rate,
                'product_id' => $product_id
            ];

            ruiyi_debug_log('RUIYI TAX: 产品税率获取 - ' . $product_name . ' (ID: ' . $product_id . ') = ' . $tax_rate . '%');
        }
    }

    ruiyi_debug_log('RUIYI TAX: 完成税率获取，总共 ' . count($products_with_tax_rates) . ' 个产品');

    wp_send_json_success($products_with_tax_rates);
}

// 获取购物车产品的分类税率（外卖订单使用）
function ruiyi_get_cart_products_tax_rates_callback() {
    check_ajax_referer('ruiyi_pos_nonce', 'nonce');

    $cart_data_json = isset($_POST['cart_data']) ? stripslashes($_POST['cart_data']) : '[]';
    $cart_data = json_decode($cart_data_json, true);

    if (!is_array($cart_data) || empty($cart_data)) {
        wp_send_json_error(['message' => 'No cart data provided']);
        return;
    }

    $products_with_tax_rates = [];

    ruiyi_debug_log('RUIYI TAX: 开始获取购物车产品税率，产品数量: ' . count($cart_data));

    foreach ($cart_data as $item) {
        if (!isset($item['id']) || !isset($item['name'])) {
            continue;
        }

        $product_id = intval($item['id']);
        $product = wc_get_product($product_id);

        if (!$product) {
            ruiyi_debug_log('RUIYI TAX: 购物车产品不存在 ID: ' . $product_id);
            continue;
        }

        $product_name = $item['name'];
        $quantity = isset($item['quantity']) ? intval($item['quantity']) : 1;
        $price = isset($item['price']) ? floatval($item['price']) : 0;
        $line_total = $price * $quantity;

        // 获取产品的实际税率
        $tax_rate = ruiyi_get_product_tax_rate($product);

        $products_with_tax_rates[] = [
            'name' => $product_name,
            'quantity' => $quantity,
            'price' => $price,
            'line_total' => $line_total,
            'tax_rate' => $tax_rate,
            'product_id' => $product_id
        ];

        ruiyi_debug_log('RUIYI TAX: 购物车产品税率获取 - ' . $product_name . ' (ID: ' . $product_id . ') = ' . $tax_rate . '%');
    }

    ruiyi_debug_log('RUIYI TAX: 完成购物车税率获取，总共 ' . count($products_with_tax_rates) . ' 个产品');

    wp_send_json_success($products_with_tax_rates);
}

function ruiyi_pos_get_table_receipt_html_callback() {
    // 🔥 添加全局错误处理，防止HTTP 500错误导致结账失败
    try {
        // 🔥 强制清除OpCache缓存
        if (function_exists('opcache_invalidate')) {
            opcache_invalidate(__FILE__, true);
        }

        // 🔥 修复：使用更宽松的nonce验证，同时支持 nonce 和 security 参数
        $nonce = isset($_POST['nonce']) ? $_POST['nonce'] : (isset($_POST['security']) ? $_POST['security'] : '');

        if (empty($nonce) || !wp_verify_nonce($nonce, 'ruiyi_pos_nonce')) {
            ruiyi_debug_log('[RUIYI POS] 桌位小票nonce验证失败: ' . $nonce);
            wp_send_json_error(array('message' => 'Nonce验证失败，请刷新页面后重试'));
            return;
        }

    // ===== 新增详细调试日志 =====
    ruiyi_debug_log('=== 小票生成函数开始执行 === [版本: 2025-10-13-23:35]');
    ruiyi_debug_log('🔥 [缓存检查] PHP文件: ' . __FILE__ . ', 修改时间: ' . date('Y-m-d H:i:s', filemtime(__FILE__)));
    ruiyi_debug_log('小票生成 - 接收到的所有POST参数:');
    foreach ($_POST as $key => $value) {
        if ($key !== 'nonce') { // 不记录nonce以保护安全
            ruiyi_debug_log("  {$key}: " . (is_string($value) ? substr($value, 0, 200) : print_r($value, true)));
        }
    }
    ruiyi_debug_log('=== POST参数记录结束 ===');

    $table_number_raw = isset($_POST['table']) ? sanitize_text_field($_POST['table']) : '';
    $order_ids_to_print_json = isset($_POST['order_ids_to_print']) ? stripslashes($_POST['order_ids_to_print']) : '[]';
    $order_ids_to_print = json_decode($order_ids_to_print_json, true);

    // 🔥 获取桌位的分类显示名称（如 "Zona Principal1"、"室内1" 而不是 "Mesa 1"）
    // 优先使用前端传递的完整桌位显示名称
    if (isset($_POST['table_display_name']) && !empty($_POST['table_display_name'])) {
        $table_display_name = sanitize_text_field($_POST['table_display_name']);
        ruiyi_debug_log('[小票桌号] ✅ 使用前端传递的桌位显示名称: ' . $table_display_name);
    } else {
        // 备选方案：从后端数据库查找
        $table_display_name = 'Mesa ' . $table_number_raw; // 默认值
        if (!empty($table_number_raw) && is_numeric($table_number_raw)) {
            $all_mappings = ruiyi_get_all_table_categories_mapping();
            ruiyi_debug_log('[小票桌号] 原始桌号: ' . $table_number_raw . ', 映射总数: ' . (is_array($all_mappings) ? count($all_mappings) : '0'));

            if ($all_mappings && is_array($all_mappings)) {
                foreach ($all_mappings as $mapping) {
                    if (isset($mapping['global_table_number']) &&
                        intval($mapping['global_table_number']) === intval($table_number_raw)) {
                        $table_display_name = $mapping['category_display_name'];
                        ruiyi_debug_log('[小票桌号] ✅ 从数据库匹配: 全局编号 ' . $table_number_raw . ' → ' . $table_display_name);
                        break;
                    }
                }
            }
        }
    }
    
    // 获取前端传递的最终金额
    $final_total = isset($_POST['final_total']) ? floatval($_POST['final_total']) : 0;
    
    // 获取前端传递的积分折扣信息
    $frontend_points_discount = isset($_POST['points_discount_amount']) ? floatval($_POST['points_discount_amount']) : 0;
    $frontend_points_used = isset($_POST['points_used_total']) ? intval($_POST['points_used_total']) : 0;
    
    // 获取订单类型和客户信息（外卖订单特有）
    $order_type = isset($_POST['order_type']) ? sanitize_text_field($_POST['order_type']) : '';

    // 🔍 [调试] 客户信息接收检查
    ruiyi_debug_log('🔍 [小票客户信息调试] 开始接收小票生成请求...');
    ruiyi_debug_log('🔍 [小票客户信息调试] - order_type: ' . $order_type);
    ruiyi_debug_log('🔍 [小票客户信息调试] - isset($_POST[\'customer_info\']): ' . (isset($_POST['customer_info']) ? 'YES' : 'NO'));

    if (isset($_POST['customer_info'])) {
        ruiyi_debug_log('🔍 [小票客户信息调试] - 原始$_POST[\'customer_info\']: ' . substr($_POST['customer_info'], 0, 500));
    }

    $customer_info_json = isset($_POST['customer_info']) ? stripslashes($_POST['customer_info']) : '';
    ruiyi_debug_log('🔍 [小票客户信息调试] - stripslashes后: ' . substr($customer_info_json, 0, 500));
    ruiyi_debug_log('🔍 [小票客户信息调试] - empty($customer_info_json): ' . (empty($customer_info_json) ? 'YES' : 'NO'));

    $customer_info = !empty($customer_info_json) ? json_decode($customer_info_json, true) : null;

    ruiyi_debug_log('🔍 [小票客户信息调试] - json_decode成功: ' . (is_array($customer_info) ? 'YES' : 'NO'));
    ruiyi_debug_log('🔍 [小票客户信息调试] - json_last_error: ' . json_last_error_msg());
    if ($customer_info) {
        ruiyi_debug_log('🔍 [小票客户信息调试] - 解析后的客户信息: ' . json_encode($customer_info, JSON_UNESCAPED_UNICODE));
    } else {
        ruiyi_debug_log('🔍 [小票客户信息调试] - 客户信息为NULL');
    }

    // 详细调试日志
    ruiyi_debug_log('\n=== 小票生成开始 ===');
    ruiyi_debug_log('小票生成 - 订单IDs参数: ' . $order_ids_to_print_json);
    ruiyi_debug_log('小票生成 - 解析后的订单IDs: ' . print_r($order_ids_to_print, true));
    ruiyi_debug_log('小票生成 - 订单类型: ' . $order_type);
    ruiyi_debug_log('小票生成 - 桌位号: ' . $table_number_raw);
    if ($customer_info) {
        ruiyi_debug_log('小票生成 - 客户信息: ' . json_encode($customer_info, JSON_UNESCAPED_UNICODE));
    }
    
    // 添加调试日志
    ruiyi_debug_log('小票生成 - 接收到前端参数：最终金额=' . $final_total);
    ruiyi_debug_log('小票生成 - 前端积分折扣信息：折扣金额=' . $frontend_points_discount . ', 使用积分=' . $frontend_points_used);
    
    // 如果前端没有传递积分信息，才从订单数据中读取
    if ($frontend_points_discount == 0 && $frontend_points_used == 0) {
        ruiyi_debug_log('小票生成 - 前端未传递积分信息，将从订单数据中读取');
    } else {
        ruiyi_debug_log('小票生成 - 使用前端传递的积分折扣信息');
    }

    // Validar que los IDs sean numéricos
    if (is_array($order_ids_to_print)) {
        $order_ids_to_print = array_map('intval', $order_ids_to_print);
        $order_ids_to_print = array_filter($order_ids_to_print, function($id) { return $id > 0; });
    } else {
        $order_ids_to_print = [];
    }

    // --- Lógica portada de vendor/impresion.php ---
    $paper_width = get_option('pos_paper_width', 80);
    $receipt_header = get_option('pos_receipt_header', '');
    $receipt_footer = get_option('pos_receipt_footer', '¡Gracias por su compra!');
    $store_name = get_option('pos_store_name', get_bloginfo('name'));
    $store_business_name = get_option('pos_store_business_name', ''); // 个体户/公司名称
    $store_cif_nif = get_option('pos_store_cif_nif', ''); // CIF/NIF
    $store_address = get_option('pos_store_address', '');
    $store_phone = get_option('pos_store_phone', '');
    $receipt_logo = get_option('pos_receipt_logo', ''); // 小票Logo
    $receipt_header_alignment = get_option('pos_receipt_header_alignment', 'left'); // 抬头对齐方式
    $receipt_bilingual = get_option('pos_receipt_bilingual', '0') === '1'; // 🔥 小票产品中西双语
    $receipt_store_name_font_size = get_option('pos_receipt_store_name_font_size', '18'); // 店名字体大小
    $receipt_tax_config = ruiyi_get_receipt_tax_config();
    $receipt_tax_rate = (float) $receipt_tax_config['rate'];
    $receipt_tax_label = ruiyi_get_receipt_tax_display_label($receipt_tax_config);
    $receipt_tax_divisor = 1 + ($receipt_tax_rate / 100);
    $content_width = $paper_width == 58 ? '220px' : '300px'; // Ajustar según el ancho del papel

    // 获取手动折扣信息
    $manual_discount_percent = isset($_POST['discount_percent']) ? floatval($_POST['discount_percent']) : 0;
    $manual_discount_amount = isset($_POST['discount_amount']) ? floatval($_POST['discount_amount']) : 0;
    $original_subtotal = isset($_POST['original_subtotal']) ? floatval($_POST['original_subtotal']) : 0;

    // 🔥 调试日志：记录收到的折扣信息
    ruiyi_debug_log('========================================');
    ruiyi_debug_log('[小票生成] 折扣信息调试:');
    ruiyi_debug_log('  - discount_percent 原始值: ' . (isset($_POST['discount_percent']) ? $_POST['discount_percent'] : 'NOT SET'));
    ruiyi_debug_log('  - discount_amount 原始值: ' . (isset($_POST['discount_amount']) ? $_POST['discount_amount'] : 'NOT SET'));
    ruiyi_debug_log('  - manual_discount_percent: ' . $manual_discount_percent);
    ruiyi_debug_log('  - manual_discount_amount: ' . $manual_discount_amount);
    ruiyi_debug_log('========================================');

    $all_items = [];
    $grand_total_from_orders = 0; // Total acumulado de los pedidos originales
    $merged_items_subtotal = 0; // Subtotal basado en los items fusionados
    $order_count = 0;
    
    $table_orders = []; // Inicializar array de pedidos

    // 新方案：直接使用购物车数据生成小票，不依赖订单查询
    $cart_data_json = isset($_POST['cart_data']) ? stripslashes($_POST['cart_data']) : '';
    $cart_data = !empty($cart_data_json) ? json_decode($cart_data_json, true) : null;
    $order_total = isset($_POST['order_total']) ? floatval($_POST['order_total']) : 0;
    $payment_info_json = isset($_POST['payment_info']) ? stripslashes($_POST['payment_info']) : '';
    $payment_info = !empty($payment_info_json) ? json_decode($payment_info_json, true) : null;

    // 🔥 强化调试：购物车数据处理
    ruiyi_debug_log('========================================');
    ruiyi_debug_log('小票生成 - 数据模式检查:');
    ruiyi_debug_log('  - cart_data_json 长度: ' . strlen($cart_data_json));
    ruiyi_debug_log('  - cart_data_json 原始: ' . substr($cart_data_json, 0, 300));
    ruiyi_debug_log('  - cart_data 解析结果: ' . ($cart_data ? 'SUCCESS' : 'NULL/FALSE'));
    ruiyi_debug_log('  - cart_data 是否数组: ' . (is_array($cart_data) ? 'YES' : 'NO'));
    ruiyi_debug_log('  - cart_data 数量: ' . (is_array($cart_data) ? count($cart_data) : 'N/A'));
    ruiyi_debug_log('  - order_ids_to_print: ' . (isset($_POST['order_ids_to_print']) ? 'YES' : 'NO'));
    ruiyi_debug_log('========================================');
    
    // 调试日志
    ruiyi_debug_log('小票生成 - 使用购物车数据模式');
    ruiyi_debug_log('小票生成 - 购物车数据: ' . json_encode($cart_data));
    ruiyi_debug_log('小票生成 - 订单总额: ' . $order_total);
    if ($payment_info) {
        ruiyi_debug_log('小票生成 - 支付信息: ' . json_encode($payment_info));
    }
    
    // 双模式数据处理：购物车数据 vs 订单ID数据
    $all_items = [];
    $subtotal = 0;

    // 初始化积分折扣相关变量 - 优先使用前端传递的数据
    $points_discount_amount = $frontend_points_discount;
    $points_used_total = $frontend_points_used;

    // 🔥 调试：检查是否有购物车数据
    ruiyi_debug_log('小票生成 - cart_data 检查: ' . (!empty($cart_data) ? '有数据' : '无数据') . ', 是否数组: ' . (is_array($cart_data) ? '是' : '否') . ', 数量: ' . (is_array($cart_data) ? count($cart_data) : 'N/A'));
    if ($cart_data) {
        ruiyi_debug_log('小票生成 - cart_data 类型: ' . gettype($cart_data));
        ruiyi_debug_log('小票生成 - cart_data 内容: ' . substr(json_encode($cart_data), 0, 500));
    }

    // 🔥 强制优先使用购物车数据
    $use_cart_mode = !empty($cart_data) && is_array($cart_data) && count($cart_data) > 0;

    if ($use_cart_mode) {
        // 模式A：使用购物车数据（支持 customPrice）
        ruiyi_debug_log('小票生成 - ✅ 使用购物车数据模式（支持 customPrice），商品数: ' . count($cart_data));

        foreach ($cart_data as $item) {
            // 🔥 过滤0欧元的免费产品和自助餐产品 - 不在小票中显示
            if (!empty($item['is_free']) || !empty($item['is_buffet'])) {
                $item_effective_price = isset($item['customPrice']) && !is_null($item['customPrice'])
                    ? floatval($item['customPrice'])
                    : floatval($item['price']);
                if ($item_effective_price <= 0) {
                    ruiyi_debug_log('小票生成 - 🔥 跳过0元产品（is_free/is_buffet）: ' . ($item['name'] ?? 'unknown'));
                    continue;
                }
            }

            // 🔥🔥🔥 关键修复：优先使用自定义名称（customName），否则使用西班牙语名称或默认名称
            if (isset($item['customName']) && !empty($item['customName'])) {
                // 用户修改了名称，使用自定义名称
                $product_name = $item['customName'];
                ruiyi_debug_log('小票生成 - 使用自定义名称: ' . $product_name);
            } elseif (isset($item['name_es']) && !empty($item['name_es'])) {
                // 使用西班牙语名称
                $product_name = $item['name_es'];
            } else {
                // 使用默认名称
                $product_name = $item['name'];
            }
            $quantity = intval($item['quantity']);

            // 🔥 优先使用customPrice（用户编辑的价格），否则使用原价
            $price = isset($item['customPrice']) && !is_null($item['customPrice'])
                ? floatval($item['customPrice'])
                : floatval($item['price']);

            $line_total = $price * $quantity;

            // 获取产品税率（如果购物车中有taxRate则使用，否则从产品meta获取）
            $tax_rate = 10.0; // 默认值
            if (isset($item['taxRate'])) {
                $tax_rate = floatval($item['taxRate']);
            } elseif (isset($item['id'])) {
                // 从产品ID获取税率
                $product_id = intval($item['id']);
                $product = wc_get_product($product_id);
                if ($product) {
                    $tax_rate = ruiyi_get_product_tax_rate($product);
                    // 🔥🔥🔥 关键修复：只有在没有自定义名称时才使用产品原名称
                    // 如果有 customName，保留用户设置的自定义名称
                    if (!isset($item['customName']) || empty($item['customName'])) {
                        $product_name = ruiyi_get_multilingual_product_name($product, 'es', true);
                    }
                }
            }

            // 🔥 中西双语：在产品名称前添加中文名称
            if ($receipt_bilingual) {
                $name_zh = '';
                if (!empty($item['name_zh'])) {
                    $name_zh = $item['name_zh'];
                } elseif (!empty($item['id'])) {
                    $name_zh = get_post_meta(intval($item['id']), '_product_name_zh', true);
                }
                if (!empty($name_zh)) {
                    $product_name = ruiyi_bilingual_product_name($name_zh, $product_name);
                }
            }

            // 🔥 关键修复：检查是否为Varios商品（从购物车数据）
            $is_varios_cart = isset($item['isVarios']) && $item['isVarios'] === true;

            if ($is_varios_cart) {
                // Varios 商品：按价格分组，类似订单ID模式的处理
                $price_key = $product_name . '_' . number_format($price, 2, '.', '');
                $display_name_with_price = $product_name . ' €' . number_format($price, 2);

                if (isset($all_items[$price_key])) {
                    // 相同价格的 Varios 已存在，累加数量和总价
                    $all_items[$price_key]['quantity'] += $quantity;
                    $all_items[$price_key]['line_total'] += $line_total;
                    ruiyi_debug_log('小票生成 - 购物车Varios累加（相同价格）: ' . $display_name_with_price . ' x' . $quantity . ' (键: ' . $price_key . ')');
                } else {
                    // 新价格的 Varios，创建新条目
                    $all_items[$price_key] = [
                        'quantity' => $quantity,
                        'price_per_unit' => $price,
                        'line_total' => $line_total,
                        'tax_rate' => $tax_rate,
                        'display_name' => $display_name_with_price // 显示名称包含价格
                    ];
                    ruiyi_debug_log('小票生成 - 购物车Varios新建（新价格）: ' . $display_name_with_price . ' x' . $quantity . ' (键: ' . $price_key . ')');
                }
            } else if (!empty($item['is_supplement'])) {
                // 🔥 配料项：不合并，保留独立行（带配料标记）
                $supp_key = '_supplement_' . count($all_items) . '_' . $product_name;
                $all_items[$supp_key] = [
                    'quantity' => $quantity,
                    'price_per_unit' => $price,
                    'line_total' => $line_total,
                    'tax_rate' => $tax_rate,
                    'display_name' => $product_name,
                    'is_supplement' => true,
                    'parent_item_name' => isset($item['parent_item_name']) ? sanitize_text_field($item['parent_item_name']) : ''
                ];
            } else {
                // 🔥 普通商品：按名称+价格合并（支持相同产品不同自定义价格）
                $price_key = $product_name . '_' . number_format($price, 2, '.', '');

                if (isset($all_items[$price_key])) {
                    $all_items[$price_key]['quantity'] += $quantity;
                    $all_items[$price_key]['line_total'] += $line_total;
                } else {
                    $all_items[$price_key] = [
                        'quantity' => $quantity,
                        'price_per_unit' => $price,
                        'line_total' => $line_total,
                        'tax_rate' => $tax_rate,
                        'display_name' => $product_name // 保留原始产品名称用于显示
                    ];
                }
            }

            $subtotal += $line_total;

            ruiyi_debug_log('小票生成 - 购物车商品: ' . $product_name . ', 数量: ' . $quantity . ', 单价: ' . $price . ', 税率: ' . $tax_rate . '%, 小计: ' . $line_total);
        }

        ruiyi_debug_log('小票生成 - 购物车模式完成，总商品种类: ' . count($all_items) . ', Subtotal: €' . $subtotal);

    } elseif (!empty($order_ids_to_print) && is_array($order_ids_to_print)) {
        // 模式B：使用订单ID查询数据（仅当无购物车数据时）
        ruiyi_debug_log('=== 小票生成 - 使用订单ID查询模式（无购物车数据）===');
        ruiyi_debug_log('小票生成 - 要处理的订单IDs: ' . json_encode($order_ids_to_print));
        ruiyi_debug_log('小票生成 - 订单数量: ' . count($order_ids_to_print));

        // 🔥 强制刷新订单数据（清除对象缓存）
        foreach ($order_ids_to_print as $order_id) {
            clean_post_cache($order_id);
            wp_cache_delete($order_id, 'posts');
            wp_cache_delete($order_id, 'post_meta');
        }

        // 初始化积分折扣相关变量
        $total_points_discount = 0;
        $total_points_used = 0;

        foreach ($order_ids_to_print as $order_id) {
            // 🔥 强制重新获取订单对象（确保是最新数据）
            $order = wc_get_order($order_id);
            if (!$order) {
                ruiyi_debug_log('小票生成 - ❌ 警告: 找不到订单ID ' . $order_id);
                ruiyi_debug_log('小票生成 - 尝试直接从数据库查询订单...');

                // 尝试直接查询数据库
                global $wpdb;
                $post_exists = $wpdb->get_var($wpdb->prepare(
                    "SELECT ID FROM {$wpdb->posts} WHERE ID = %d AND post_type = 'shop_order'",
                    $order_id
                ));

                if ($post_exists) {
                    ruiyi_debug_log("小票生成 - 订单在数据库中存在但WooCommerce无法获取，post_id: {$post_exists}");
                } else {
                    ruiyi_debug_log("小票生成 - 订单在数据库中不存在");
                }
                continue;
            }

            $order_items_count = count($order->get_items());
            ruiyi_debug_log("小票生成 - ✅ 处理订单: #$order_id, 状态: " . $order->get_status() . ", 总额: €" . $order->get_total() . ", 商品数: {$order_items_count}");
            
            // 检查积分折扣信息
            $order_points_discount = $order->get_meta('_points_discount_amount');
            $order_points_used = $order->get_meta('_points_discount_used');
            
            if ($order_points_discount && $order_points_used) {
                $total_points_discount += floatval($order_points_discount);
                $total_points_used += intval($order_points_used);
                ruiyi_debug_log('小票生成 - 订单 #' . $order_id . ' 积分折扣: ' . $order_points_discount . '€, 使用积分: ' . $order_points_used);
            }
            
            // 检查订单费用中的积分折扣（备选方案）
            foreach ($order->get_fees() as $fee) {
                if (strpos($fee->get_name(), 'Descuento por Puntos') !== false && $fee->get_total() < 0) {
                    $fee_discount = abs($fee->get_total());
                    if ($fee_discount > 0) {
                        // 如果meta data中没有积分信息，从费用名称中提取
                        if (!$order_points_discount) {
                            $total_points_discount += $fee_discount;
                            // 尝试从费用名称中提取积分数量 "Descuento por Puntos (100 pts)"
                            if (preg_match('/\((\d+)\s*pts?\)/', $fee->get_name(), $matches)) {
                                $total_points_used += intval($matches[1]);
                            }
                            ruiyi_debug_log('小票生成 - 从费用中提取积分折扣: ' . $fee_discount . '€');
                        }
                    }
                }
            }
            
            // 获取订单中的商品
            foreach ($order->get_items() as $item_id => $item) {
                // 获取产品对象以便获取西班牙语原名
                $product_id = $item->get_product_id();
                $product = wc_get_product($product_id);

                // 🔥 过滤0欧元的免费产品和自助餐产品 - 不在小票中显示
                $is_varios_item_check = get_metadata('order_item', $item_id, '_is_varios_item', true) === 'yes';
                if (!$is_varios_item_check && floatval($item->get_total()) <= 0) {
                    // 检查是否为自助餐产品或免费产品（价格为0的非Varios产品）
                    $is_buffet = function_exists('ruiyi_is_buffet_product') && ruiyi_is_buffet_product($product_id);
                    $is_free = $product && floatval($product->get_price()) <= 0 && !$is_buffet;
                    if ($is_buffet || $is_free) {
                        ruiyi_debug_log('小票生成 - 🔥 跳过0元产品: ' . $item->get_name() . ' (buffet=' . ($is_buffet ? 'yes' : 'no') . ', free=' . ($is_free ? 'yes' : 'no') . ')');
                        continue;
                    }
                }

                // 🔥🔥🔥 关键修复：检查是否有自定义名称
                $has_custom_name = get_metadata('order_item', $item_id, '_has_custom_name', true) === 'yes';
                $order_item_name = $item->get_name(); // 订单项的当前名称

                if ($has_custom_name) {
                    // 有自定义名称标记，使用订单项的名称（已被设置为自定义名称）
                    $product_name = $order_item_name;
                    ruiyi_debug_log('小票生成 - 使用自定义名称: ' . $product_name);
                } elseif ($product && $product->exists()) {
                    // 检查订单项名称是否与产品原名称不同（可能是手动设置的自定义名称）
                    $original_product_name = $product->get_name();
                    if ($order_item_name !== $original_product_name) {
                        // 名称不同，使用订单项的名称（自定义名称）
                        $product_name = $order_item_name;
                        ruiyi_debug_log('小票生成 - 检测到名称不同，使用订单项名称: ' . $product_name . ' (原名: ' . $original_product_name . ')');
                    } else {
                        // 使用西班牙语名称
                        $product_name = ruiyi_get_multilingual_product_name($product, 'es', true);
                    }
                } else {
                    // 无法获取产品，使用订单项名称
                    $product_name = $order_item_name;
                }
                // 🔥 中西双语：在产品名称前添加中文名称
                if ($receipt_bilingual && $product_id) {
                    $name_zh = get_post_meta($product_id, '_product_name_zh', true);
                    if (!empty($name_zh)) {
                        $product_name = ruiyi_bilingual_product_name($name_zh, $product_name);
                    }
                }

                $quantity = $item->get_quantity();
                $line_total = $item->get_total(); // 含税总价

                // 🔥 首先检查是否为 Varios 商品
                $is_varios_item = get_metadata('order_item', $item_id, '_is_varios_item', true) === 'yes';
                $varios_custom_price = get_metadata('order_item', $item_id, '_varios_custom_price', true);

                // 获取原始产品价格
                $product_id = $item->get_product_id();
                $product = wc_get_product($product_id);
                $price_per_unit = 0;
                $tax_rate = 10.0; // 默认税率

                // 🔥 检查是否有通用自定义价格（优先级最高）
                $has_custom_price = get_metadata('order_item', $item_id, '_has_custom_price', true) === 'yes';
                $custom_price = get_metadata('order_item', $item_id, '_custom_price', true);

                if ($has_custom_price && !empty($custom_price) && $custom_price > 0) {
                    // 通用自定义价格：使用编辑后的价格
                    $price_per_unit = floatval($custom_price);
                    $calculated_line_total = $price_per_unit * $quantity;

                    // 获取产品的税率
                    if ($product && $product->exists()) {
                        $tax_rate = ruiyi_get_product_tax_rate($product);
                    }

                    ruiyi_debug_log('小票生成 - 使用自定义价格: ' . $product_name . ', 自定义价格: €' . $price_per_unit . ', 数量: ' . $quantity . ', 税率: ' . $tax_rate . '%, 总价: €' . $calculated_line_total);
                }
                // 🔥 Varios 商品价格优先级：自定义价格 > 订单计算价格
                else if ($is_varios_item && !empty($varios_custom_price) && $varios_custom_price > 0) {
                    // Varios 商品：使用保存的自定义价格
                    $price_per_unit = floatval($varios_custom_price);
                    $calculated_line_total = $price_per_unit * $quantity;

                    // 获取产品的税率
                    if ($product && $product->exists()) {
                        $tax_rate = ruiyi_get_product_tax_rate($product);
                    }

                    ruiyi_debug_log('小票生成 - Varios商品使用自定义价格: ' . $product_name . ', 自定义价格: €' . $price_per_unit . ', 数量: ' . $quantity . ', 税率: ' . $tax_rate . '%, 总价: €' . $calculated_line_total);
                }
                // 普通产品：使用产品原价
                else if ($product && $product->exists()) {
                    // 使用产品原始价格
                    $price_per_unit = floatval($product->get_price());
                    // 获取产品的真实税率
                    $tax_rate = ruiyi_get_product_tax_rate($product);
                    // 重新计算line_total使用原始价格
                    $calculated_line_total = $price_per_unit * $quantity;
                    ruiyi_debug_log('小票生成 - 使用产品原价: ' . $product_name . ', 产品ID: ' . $product_id . ', 原价: €' . $price_per_unit . ', 税率: ' . $tax_rate . '%, 重新计算总价: €' . $calculated_line_total);
                } else {
                    // 备用方案：从订单总价计算（如果无法获取产品）
                    $price_per_unit = $quantity > 0 ? ($line_total / $quantity) : 0;
                    $calculated_line_total = $line_total; // 保持原始line_total
                    ruiyi_debug_log('小票生成 - 备用价格计算: ' . $product_name . ', 计算价格: €' . $price_per_unit);
                }

                if ($is_varios_item) {
                    // Varios 商品：按价格分组合并
                    // 🔥 关键修复：使用 "Varios €X.XX" 作为显示名称，而不是键名
                    $price_key = $product_name . '_' . number_format($price_per_unit, 2, '.', '');
                    $display_name_with_price = $product_name . ' €' . number_format($price_per_unit, 2);

                    if (isset($all_items[$price_key])) {
                        // 相同价格的 Varios 已存在，累加数量和总价
                        $all_items[$price_key]['quantity'] += $quantity;
                        $all_items[$price_key]['line_total'] += $calculated_line_total;
                        ruiyi_debug_log('小票生成 - Varios商品累加（相同价格）: ' . $display_name_with_price . ' x' . $quantity . ' (键: ' . $price_key . ')');
                    } else {
                        // 新价格的 Varios，创建新条目
                        $all_items[$price_key] = [
                            'quantity' => $quantity,
                            'price_per_unit' => $price_per_unit,
                            'line_total' => $calculated_line_total,
                            'tax_rate' => $tax_rate,
                            'display_name' => $display_name_with_price // 🔥 显示名称包含价格 "Varios €1.20"
                        ];
                        ruiyi_debug_log('小票生成 - Varios商品新建（新价格）: ' . $display_name_with_price . ' x' . $quantity . ' (键: ' . $price_key . ')');
                    }
                    ruiyi_debug_log('小票生成 - Varios商品（按价格合并）: €' . $price_per_unit . ' x' . $quantity . ' (键: ' . $price_key . ', 显示: ' . $display_name_with_price . ')');
                }
                // 🔥 配料项：不合并，保留独立行（从订单meta读取配料标记）
                else if (wc_get_order_item_meta($item_id, '_is_supplement', true) === 'yes') {
                    $supp_parent = wc_get_order_item_meta($item_id, '_parent_item_name', true);
                    $supp_key = '_supplement_' . count($all_items) . '_' . $product_name;
                    $all_items[$supp_key] = [
                        'quantity' => $quantity,
                        'price_per_unit' => $price_per_unit,
                        'line_total' => $calculated_line_total,
                        'tax_rate' => $tax_rate,
                        'display_name' => $product_name,
                        'is_supplement' => true,
                        'parent_item_name' => $supp_parent ? $supp_parent : ''
                    ];
                }
                // 🔥 普通商品：按名称+价格合并（支持相同产品不同自定义价格）
                else {
                    $price_key = $product_name . '_' . number_format($price_per_unit, 2, '.', '');

                    if (isset($all_items[$price_key])) {
                        $all_items[$price_key]['quantity'] += $quantity;
                        $all_items[$price_key]['line_total'] += $calculated_line_total;
                    } else {
                        $all_items[$price_key] = [
                            'quantity' => $quantity,
                            'price_per_unit' => $price_per_unit,
                            'line_total' => $calculated_line_total,
                            'tax_rate' => $tax_rate,
                            'display_name' => $product_name // 保留原始产品名称用于显示
                        ];
                    }
                }

                $subtotal += $calculated_line_total;

                ruiyi_debug_log('小票生成 - 订单商品: ' . $product_name . ', 数量: ' . $quantity . ', 原价单价: €' . $price_per_unit . ', 税率: ' . $tax_rate . '%, 小计: €' . $calculated_line_total);
            }
        }
        
        // 如果前端没有传递积分信息，使用从订单中读取的信息
        if ($frontend_points_discount == 0 && $frontend_points_used == 0) {
            $points_discount_amount = $total_points_discount;
            $points_used_total = $total_points_used;
            ruiyi_debug_log('小票生成 - 使用从订单读取的积分折扣: ' . $points_discount_amount . '€, 使用积分: ' . $points_used_total);
        } else {
            // 否则保持使用前端传递的数据（已在前面设置）
            ruiyi_debug_log('小票生成 - 使用前端传递的积分折扣: ' . $points_discount_amount . '€, 使用积分: ' . $points_used_total);
        }
        
    } else {
        // 两种数据都没有，返回错误
        ruiyi_debug_log('小票生成 - 错误: 既没有购物车数据也没有有效的订单ID');
        wp_send_json_error(['message' => '缺少必要数据：请提供购物车数据或订单ID']);
        wp_die();
    }
    
    // 计算总金额：对于订单模式，重新计算基于原始产品价格的总额
    if (!empty($cart_data)) {
        // 购物车数据模式：预结单以 cart_data 计算值为准，避免前端旧 order_total 污染金额
        $is_preview_bill_request = isset($_POST['is_preview']) && $_POST['is_preview'] === 'true';
        if ($is_preview_bill_request) {
            if ($order_total > 0 && abs($order_total - $subtotal) <= 0.01) {
                $grand_total = $order_total;
                ruiyi_debug_log('小票生成 - 预结单使用前端总金额（与购物车一致）: €' . $grand_total);
            } else {
                $grand_total = $subtotal;
                ruiyi_debug_log('小票生成 - 预结单使用 cart_data 重算总金额: €' . $grand_total . ' (front=' . $order_total . ')');
            }
        } elseif ($order_total > 0) {
            $grand_total = $order_total;
            ruiyi_debug_log('小票生成 - 使用购物车总金额: €' . $grand_total);
        } else {
            $grand_total = $subtotal;
            ruiyi_debug_log('小票生成 - 使用购物车计算的小计: €' . $grand_total);
        }
    } else {
        // 订单ID模式：使用重新计算的基于原始价格的小计
        $grand_total = $subtotal;
        ruiyi_debug_log('小票生成 - 使用基于原始产品价格重新计算的小计: €' . $grand_total);

        // 🔥🔥🔥 关键修复：AA金额分单传递 order_total 参数，优先使用
        // 这确保了AA分单小票显示的金额与用户实际支付的金额一致
        if ($order_total > 0) {
            $grand_total = $order_total;
            ruiyi_debug_log('小票生成 - 🔥 使用前端传递的order_total（AA分单金额）: €' . $grand_total);
        }
        // 如果有前端传递的最终金额且与重算金额接近，优先使用前端金额（保持折扣等）
        elseif ($final_total > 0 && abs($final_total - $grand_total) < ($grand_total * 0.5)) {
            $grand_total = $final_total;
            ruiyi_debug_log('小票生成 - 使用前端传递的最终金额（已验证合理性）: €' . $grand_total);
        }
    }
    
    // 如果有积分折扣，确保grand_total是折扣后的金额
    if ($points_discount_amount > 0 && $grand_total > ($subtotal - $points_discount_amount)) {
        $grand_total = $subtotal - $points_discount_amount;
        ruiyi_debug_log('小票生成 - 应用积分折扣后的总金额: €' . $grand_total);
    }
    
    // 计算税额：所有产品价格均为含税价，税种/税率由小票设置控制
    $tax_amount = $grand_total - ($grand_total / $receipt_tax_divisor);
    $subtotal_without_tax = $grand_total - $tax_amount;
    
    ruiyi_debug_log('小票生成 - 金额计算: 未税小计=' . $subtotal_without_tax . ', 税额=' . $tax_amount . ', 总计=' . $grand_total);

    // El IVA es la diferencia entre el total con IVA y el subtotal sin IVA
    // 简化的总金额处理 - 使用购物车计算的金额
    $final_total_merged_inclusive_tax = $grand_total;
    ruiyi_debug_log('小票生成 - 使用购物车计算的总金额: €' . $final_total_merged_inclusive_tax);

    // 🔥 添加详细调试：打印 $all_items 数组内容
    ruiyi_debug_log('=== 小票生成 - $all_items 数组详情 ===');
