            <?php
            // 🔥 检查是否为预览账单
            $is_preview_bill = isset($_POST['is_preview']) && $_POST['is_preview'] === 'true';

            if ($is_preview_bill) {
                // 预览账单标记 - PROFORMA
                // 🔥 添加外送区域标记（供CLODOP解析使用）
