                echo '<div class="proforma-marker" data-is-delivery-zone="' . ($is_delivery_zone_flag ? 'true' : 'false') . '" style="text-align: center; font-weight: bold; font-size: 1.3em; margin: 1mm 0 1.5mm 0; padding: 0 0 1mm 0; border-top: none; border-bottom: 2px dashed #000;">';
