            ?>

              <?php
              // 🔥 订单号显示已移除（按用户要求）
              // 之前显示: Pedido: #123, Pedido Combinado: #456 等
              // 现在不再显示订单号，只保留发票号
              ?>

              <?php
              // 🔥 获取隐藏产品编号设置
              $hide_product_number = get_option('pos_hide_product_number_on_receipt', '0') === '1';
              // 🔥 获取外送区域显示产品编号设置
              $show_product_number_on_delivery_zone = get_option('pos_show_product_number_on_takeaway', '0') === '1';
              // 🔥 检查是否为外送区域桌位（前端传递的参数）- 只有外送区域的PROFORMA预结单才例外
              $is_delivery_zone = isset($_POST['is_delivery_zone']) && $_POST['is_delivery_zone'] === 'true';
              $apply_delivery_zone_exception = $is_delivery_zone && $is_preview_bill; // 只有外送区域预结单才例外

              // 🔥 产品编号移除函数（使用function_exists避免重复定义错误）
              if (!function_exists('ruiyi_remove_product_number')) {
                  function ruiyi_remove_product_number($name, $should_hide, $is_takeaway_proforma = false, $show_on_takeaway = false) {
                      if (!$should_hide || empty($name)) {
                          return $name;
                      }
                      // 🔥 外卖预结单例外：如果是外卖预结单且开启了外卖显示编号设置，则不隐藏
                      if ($is_takeaway_proforma && $show_on_takeaway) {
                          return $name;
                      }
                      // 匹配格式：数字 + 可选字母 + 点 + 可选空格（如 "170A. ", "13.", "1. "）
                      $cleaned = preg_replace('/^\d+[A-Za-z]?\.\s*/', '', $name);
                      return !empty($cleaned) ? $cleaned : $name;
                  }
              }
              ?>
              <hr>
              <?php $receipt_product_format = get_option('pos_receipt_product_format', 'default'); ?>
              <table>
                <thead>
                    <tr>
                    <?php if ($receipt_product_format === 'qty_first'): ?>
                        <th style="width: 15%; text-align:center;">Cant.</th>
                        <th style="width: 50%;">Producto</th>
                    <?php else: ?>
                        <th style="width: 50%;">Producto</th>
                        <th style="width: 15%; text-align:center;">Cant.</th>
                    <?php endif; ?>
                        <th style="width: 15%; text-align:right;">Precio</th>
                        <th style="width: 20%; text-align:right;">Total</th>
                    </tr>
                </thead>
                <tbody>
                <?php if (!empty($all_items)):
                    foreach ($all_items as $name => $info):
                        // 使用 display_name 如果存在，否则使用数组键名
                        $display_name = isset($info['display_name']) ? $info['display_name'] : $name;
                        // 🔥 应用产品编号隐藏设置（只有外送区域预结单才例外）
                        $display_name = ruiyi_remove_product_number($display_name, $hide_product_number, $apply_delivery_zone_exception, $show_product_number_on_delivery_zone);
                    ?>
                    <?php
                        $is_supp = !empty($info['is_supplement']);
                        $supp_parent = $is_supp && !empty($info['parent_item_name']) ? esc_attr($info['parent_item_name']) : '';
                        $supp_prefix = $is_supp ? '+ ' : '';
                    ?>
                    <tr<?php if ($is_supp) echo ' data-supplement="true" data-parent="' . $supp_parent . '"'; ?>>
                    <?php if ($receipt_product_format === 'qty_first'): ?>
                        <td class="col-qty"><?php echo intval($info['quantity']); ?></td>
                        <td class="item-name"><?php echo esc_html($supp_prefix . $display_name); ?></td>
                    <?php else: ?>
                        <td class="item-name"><?php echo esc_html($supp_prefix . $display_name); ?></td>
                        <td class="col-qty"><?php echo intval($info['quantity']); ?></td>
                    <?php endif; ?>
                        <td class="col-price"><?php echo number_format($info['price_per_unit'], 2); ?></td>
                        <td class="col-total"><?php echo number_format($info['line_total'], 2); ?></td>
                    </tr>
                    <?php
                    endforeach;
                else:
                    ?>
                    <tr><td colspan="4" style="text-align:center; padding: 5px 0;">No hay productos en los pedidos de esta mesa.</td></tr>
                <?php endif; ?>
                </tbody>
            </table>
            <hr>
            <table class="totals-table">
                <?php
                // 根据产品实际税率计算各税率的税额
                $tax_groups = [];
                $total_pre_tax = 0;
                $total_tax = 0;

                // 🔥 最优先：如果有购物车数据（包含 customPrice），使用购物车计算税费
                if (!empty($cart_data) && is_array($cart_data) && !empty($all_items)) {
                    ruiyi_debug_log('小票生成 - 使用购物车数据计算税费（支持 customPrice）');
                    foreach ($all_items as $product_name => $item_info) {
                        $item_total = $item_info['line_total'];
                        $item_tax_rate = isset($item_info['tax_rate']) ? $item_info['tax_rate'] : 10.0;

                        // 计算此产品的税前金额和税额
                        $item_pre_tax = $item_total / (1 + $item_tax_rate / 100);
                        $item_tax = $item_total - $item_pre_tax;

                        $total_pre_tax += $item_pre_tax;
                        $total_tax += $item_tax;

                        // 按税率分组
                        $tax_key = number_format($item_tax_rate, 0);
                        if (!isset($tax_groups[$tax_key])) {
                            $tax_groups[$tax_key] = [
                                'rate' => $item_tax_rate,
                                'base' => 0,
                                'tax' => 0
                            ];
                        }
                        $tax_groups[$tax_key]['base'] += $item_pre_tax;
                        $tax_groups[$tax_key]['tax'] += $item_tax;

                        ruiyi_debug_log('小票生成 - 购物车税率: ' . $product_name . ', 总价: €' . $item_total . ', 税率: ' . $item_tax_rate . '%, 税前: €' . number_format($item_pre_tax, 2) . ', 税额: €' . number_format($item_tax, 2));
                    }
                }
                // 次优先：使用前端重新计算的产品税率数据（订单数据）
                elseif (isset($_POST['products_with_tax_rates']) && !empty($_POST['products_with_tax_rates'])) {
                    $products_with_tax_rates = json_decode(stripslashes($_POST['products_with_tax_rates']), true);
                    if (is_array($products_with_tax_rates) && !empty($products_with_tax_rates)) {
                        ruiyi_debug_log('小票生成 - 使用重新计算的税率数据，产品数量: ' . count($products_with_tax_rates));

                        foreach ($products_with_tax_rates as $product_data) {
                            $item_total = floatval($product_data['line_total']);
                            $item_tax_rate = floatval($product_data['tax_rate']);

                            // 计算此产品的税前金额和税额
                            $item_pre_tax = $item_total / (1 + $item_tax_rate / 100);
                            $item_tax = $item_total - $item_pre_tax;

                            $total_pre_tax += $item_pre_tax;
                            $total_tax += $item_tax;

                            // 按税率分组
                            $tax_key = number_format($item_tax_rate, 0);
                            if (!isset($tax_groups[$tax_key])) {
                                $tax_groups[$tax_key] = [
                                    'rate' => $item_tax_rate,
                                    'base' => 0,
                                    'tax' => 0
                                ];
                            }
                            $tax_groups[$tax_key]['base'] += $item_pre_tax;
                            $tax_groups[$tax_key]['tax'] += $item_tax;

                            ruiyi_debug_log('小票生成 - 重计算税率: ' . $product_data['name'] . ', 税率: ' . $item_tax_rate . '%, 税前: €' . $item_pre_tax . ', 税额: €' . $item_tax);
                        }
                    }
                }
                // 次优先：使用购物车产品信息（外卖订单）
                elseif (isset($_POST['cart_items']) && !empty($_POST['cart_items'])) {
                    $cart_items = json_decode(stripslashes($_POST['cart_items']), true);
                    if (is_array($cart_items) && !empty($cart_items)) {
                        foreach ($cart_items as $item) {
                            $item_price = floatval($item['price']);
                            $item_quantity = intval($item['quantity']);
                            $item_tax_rate = isset($item['taxRate']) ? floatval($item['taxRate']) : 10.0;
                            $item_total = $item_price * $item_quantity;

                            // 计算此产品的税前金额和税额
                            $item_pre_tax = $item_total / (1 + $item_tax_rate / 100);
                            $item_tax = $item_total - $item_pre_tax;

                            $total_pre_tax += $item_pre_tax;
                            $total_tax += $item_tax;

                            // 按税率分组
                            $tax_key = number_format($item_tax_rate, 0);
                            if (!isset($tax_groups[$tax_key])) {
                                $tax_groups[$tax_key] = [
                                    'rate' => $item_tax_rate,
                                    'base' => 0,
                                    'tax' => 0
                                ];
                            }
                            $tax_groups[$tax_key]['base'] += $item_pre_tax;
                            $tax_groups[$tax_key]['tax'] += $item_tax;
                        }
                    }
                } else {
                    // 使用订单产品的实际税率（餐桌订单）
                    foreach ($all_items as $product_name => $item_info) {
                        $item_total = $item_info['line_total'];
                        $item_tax_rate = isset($item_info['tax_rate']) ? $item_info['tax_rate'] : 10.0;

                        // 计算此产品的税前金额和税额
                        $item_pre_tax = $item_total / (1 + $item_tax_rate / 100);
                        $item_tax = $item_total - $item_pre_tax;

                        $total_pre_tax += $item_pre_tax;
                        $total_tax += $item_tax;

                        // 按税率分组
                        $tax_key = number_format($item_tax_rate, 0);
                        if (!isset($tax_groups[$tax_key])) {
                            $tax_groups[$tax_key] = [
                                'rate' => $item_tax_rate,
                                'base' => 0,
                                'tax' => 0
                            ];
                        }
                        $tax_groups[$tax_key]['base'] += $item_pre_tax;
                        $tax_groups[$tax_key]['tax'] += $item_tax;

                        ruiyi_debug_log('小票生成 - 税率计算: ' . $product_name . ', 税率: ' . $item_tax_rate . '%, 税前: €' . $item_pre_tax . ', 税额: €' . $item_tax);
                    }
                }

                // 如果仍然没有计算出税费信息，使用小票设置里的税率
                if (empty($tax_groups) && $subtotal > 0) {
                    $total_pre_tax = $subtotal / $receipt_tax_divisor;
                    $total_tax = $subtotal - $total_pre_tax;
                    $tax_groups[number_format($receipt_tax_rate, 0)] = [
                        'rate' => $receipt_tax_rate,
                        'base' => $total_pre_tax,
                        'tax' => $total_tax
                    ];
                }

                // 按税率排序
                ksort($tax_groups);

                // 🔥 【关键修复】先获取所有扣款，然后计算调整后的税基
                // 1. 获取 cheque restaurante（提前获取）
                $cheque_restaurante_amount_early = 0;
                if (isset($_POST['cheque_restaurante_amount']) && floatval($_POST['cheque_restaurante_amount']) > 0) {
                    $cheque_restaurante_amount_early = floatval($_POST['cheque_restaurante_amount']);
                } elseif (isset($_POST['payment_info'])) {
                    $temp_payment_info_early = json_decode(stripslashes($_POST['payment_info']), true);
                    if (isset($temp_payment_info_early['chequeRestauranteAmount']) && floatval($temp_payment_info_early['chequeRestauranteAmount']) > 0) {
                        $cheque_restaurante_amount_early = floatval($temp_payment_info_early['chequeRestauranteAmount']);
                    }
                }

                // 2. 计算总扣款（手动折扣 + cheque）
                $total_deductions = $manual_discount_amount + $points_discount_amount + $cheque_restaurante_amount_early;

                // 3. 计算调整后的有效总额
                $effective_total = $grand_total - $cheque_restaurante_amount_early;
                if ($effective_total < 0) $effective_total = 0;

                // 4. 🔥 重新计算基于有效总额的税基和税额（使用实际支付金额和小票税率设置）
                $adjusted_pre_tax = $effective_total / $receipt_tax_divisor;
                $adjusted_tax = $effective_total - $adjusted_pre_tax;

                ruiyi_debug_log("[小票税额修复] 原始税前: €{$total_pre_tax}, 原始税额: €{$total_tax}");
                ruiyi_debug_log("[小票税额修复] grand_total: €{$grand_total}, cheque: €{$cheque_restaurante_amount_early}, effective_total: €{$effective_total}");
                ruiyi_debug_log("[小票税额修复] 调整后税前: €{$adjusted_pre_tax}, 调整后税额: €{$adjusted_tax}");

                // 处理折扣
                if ($points_discount_amount > 0) {
                    $discount_without_tax = $points_discount_amount / $receipt_tax_divisor;
                    $discounted_pre_tax = $total_pre_tax - $discount_without_tax;
                }
                ?>
                <tr>
                    <td style="text-align:left;">Base Imponible:</td>
                    <td style="text-align:right;"><?php echo number_format($adjusted_pre_tax > 0 ? $adjusted_pre_tax : ($effective_total / $receipt_tax_divisor), 2); ?>€</td>
                </tr>

                <?php if ($points_discount_amount > 0): ?>
                <tr>
                    <td style="text-align:left;">DESCUENTO (<?php echo $points_used_total; ?> PUNTOS):</td>
                    <td style="text-align:right;">-€<?php echo number_format($discount_without_tax, 2); ?></td>
                </tr>
                <?php endif; ?>

                <?php
                // 🔥 显示手动折扣信息（百分比折扣）
                if ($manual_discount_percent > 0 && $manual_discount_amount > 0):
                    $manual_discount_without_tax = $manual_discount_amount / $receipt_tax_divisor; // 折扣含税
                ?>
                <tr class="discount-row" style="color: #dc2626;">
                    <td style="text-align:left;">DESCUENTO (<span class="discount-percent"><?php echo number_format($manual_discount_percent, 0); ?></span>%):</td>
                    <td style="text-align:right;" class="discount-amount">-€<?php echo number_format($manual_discount_amount, 2); ?></td>
                </tr>
                <?php endif; ?>

                <?php
                // 🔥 【修复】显示调整后的税额（基于实际支付金额和小票税率设置）
                ?>
                <tr>
                    <td style="text-align:left;"><?php echo esc_html($receipt_tax_label); ?>:</td>
                    <td style="text-align:right;"><?php echo number_format($adjusted_tax > 0 ? $adjusted_tax : ($effective_total - $effective_total / $receipt_tax_divisor), 2); ?>€</td>
                </tr>
                <?php
                ?>

                <?php
                // 🔥 显示餐厅抵扣票 (Cheque Restaurante)
                // 🔥 添加诊断日志
                ruiyi_debug_log("[小票生成] ========== Cheque Restaurante 诊断 ==========");
                ruiyi_debug_log("[小票生成] POST cheque_restaurante_amount: " . (isset($_POST['cheque_restaurante_amount']) ? $_POST['cheque_restaurante_amount'] : '未设置'));
                ruiyi_debug_log("[小票生成] POST payment_info: " . (isset($_POST['payment_info']) ? $_POST['payment_info'] : '未设置'));

                // 🔥 HTML诊断注释（用于前端调试）
                $cheque_post_value = isset($_POST['cheque_restaurante_amount']) ? $_POST['cheque_restaurante_amount'] : '未设置';
                $payment_info_raw = isset($_POST['payment_info']) ? $_POST['payment_info'] : '未设置';
                echo "<!-- [CHEQUE诊断] POST cheque_restaurante_amount: {$cheque_post_value} -->\n";
                echo "<!-- [CHEQUE诊断] POST payment_info 存在: " . (isset($_POST['payment_info']) ? 'YES' : 'NO') . " -->\n";

                $cheque_restaurante_amount = 0;
                if (isset($_POST['cheque_restaurante_amount']) && floatval($_POST['cheque_restaurante_amount']) > 0) {
                    $cheque_restaurante_amount = floatval($_POST['cheque_restaurante_amount']);
                    ruiyi_debug_log("[小票生成] ✅ 从 POST 直接获取 cheque: €{$cheque_restaurante_amount}");
                    echo "<!-- [CHEQUE诊断] ✅ 从POST直接获取: €{$cheque_restaurante_amount} -->\n";
                } elseif (isset($_POST['payment_info'])) {
                    $temp_payment_info = json_decode(stripslashes($_POST['payment_info']), true);
                    echo "<!-- [CHEQUE诊断] payment_info解析结果: " . (is_array($temp_payment_info) ? 'OK' : 'FAILED') . " -->\n";
                    if (is_array($temp_payment_info)) {
                        echo "<!-- [CHEQUE诊断] chequeRestauranteAmount字段: " . (isset($temp_payment_info['chequeRestauranteAmount']) ? $temp_payment_info['chequeRestauranteAmount'] : '未设置') . " -->\n";
                    }
                    if (isset($temp_payment_info['chequeRestauranteAmount']) && floatval($temp_payment_info['chequeRestauranteAmount']) > 0) {
                        $cheque_restaurante_amount = floatval($temp_payment_info['chequeRestauranteAmount']);
                        ruiyi_debug_log("[小票生成] ✅ 从 payment_info 获取 cheque: €{$cheque_restaurante_amount}");
                        echo "<!-- [CHEQUE诊断] ✅ 从payment_info获取: €{$cheque_restaurante_amount} -->\n";
                    }
                }
                ruiyi_debug_log("[小票生成] 最终 cheque_restaurante_amount: €{$cheque_restaurante_amount}");
                echo "<!-- [CHEQUE诊断] 最终值: €{$cheque_restaurante_amount} -->\n";

                if ($cheque_restaurante_amount > 0):
                ?>
                <tr style="color: #e65100;">
                    <td style="text-align:left;">Cheque Restaurante:</td>
                    <td style="text-align:right;">-€<?php echo number_format($cheque_restaurante_amount, 2); ?></td>
                </tr>
                <?php endif; ?>

                <?php
                // 🔥 计算最终应付金额（减去 Cheque Restaurante）
                $final_payable = $grand_total - $cheque_restaurante_amount;
                ?>
                <tr class="total-row">
                    <td style="text-align:left;">TOTAL:</td>
                    <td style="text-align:right;"><?php echo number_format($final_payable, 2); ?>€</td>
                </tr>
            </table>

            <?php
            // 显示支付方式详情
            $payment_info_data = isset($_POST['payment_info']) ? json_decode(stripslashes($_POST['payment_info']), true) : null;

            // 🔥 调试：记录接收到的支付信息
            ruiyi_debug_log('[小票生成] 接收到的payment_info: ' . json_encode($payment_info_data));

            // AA结账：如果没有payment_info但有单独的支付参数，构建payment_info_data
            $is_aa_checkout = isset($_POST['is_aa_checkout']) && $_POST['is_aa_checkout'] === '1';
            if ($is_aa_checkout && !$payment_info_data) {
                $aa_payment_method = isset($_POST['payment_method']) ? sanitize_text_field($_POST['payment_method']) : 'cash';
                $aa_cash_amount = isset($_POST['cash_amount']) ? floatval($_POST['cash_amount']) : 0;
                $aa_card_amount = isset($_POST['card_amount']) ? floatval($_POST['card_amount']) : 0;

                ruiyi_debug_log('[小票生成] AA结账支付参数 - method: ' . $aa_payment_method . ', cash: ' . $aa_cash_amount . ', card: ' . $aa_card_amount);

                $payment_info_data = array(
                    'method' => $aa_payment_method,
                    'cashAmount' => $aa_cash_amount,
                    'cardAmount' => $aa_card_amount
                );
            }

            // 如果前端传递了支付信息，显示详细的支付方式
            if ($payment_info_data && is_array($payment_info_data)):
                $payment_method_detail = isset($payment_info_data['method']) ? $payment_info_data['method'] : '';
                ruiyi_debug_log('[小票生成] 支付方式: ' . $payment_method_detail);

                if ($payment_method_detail === 'cash'):
                    // 现金支付
                    // 🔥 修复：获取实际现金支付金额（扣除折扣/cheque后的金额）
                    $actual_cash_amount = isset($payment_info_data['cashAmount']) && floatval($payment_info_data['cashAmount']) > 0
                        ? floatval($payment_info_data['cashAmount'])
                        : $grand_total;

                    if (isset($payment_info_data['receivedAmount']) && floatval($payment_info_data['receivedAmount']) > 0):
                        // 普通结账：显示实际支付金额、收款和找零
                        $received_amount = floatval($payment_info_data['receivedAmount']);
                        $change_amount = floatval($payment_info_data['changeAmount'] ?? 0);
                        ?>
                        <table class="payment-details-table" style="margin-top: 3mm; font-size: 0.95em;">
	                            <tr>
	                                <td colspan="2" style="text-align:center; font-weight: bold;">Detalles de Pago</td>
	                            </tr>
                            <tr>
                                <td style="text-align:left; padding-left: 5mm;">Efectivo:</td>
                                <td style="text-align:right;"><?php echo number_format($actual_cash_amount, 2); ?>€</td>
                            </tr>
                            <?php if ($received_amount > $actual_cash_amount + 0.01): ?>
                            <tr>
                                <td style="text-align:left; padding-left: 5mm; font-size: 0.9em; color: #666;">Recibido:</td>
                                <td style="text-align:right; font-size: 0.9em; color: #666;"><?php echo number_format($received_amount, 2); ?>€</td>
                            </tr>
                            <tr>
                                <td style="text-align:left; padding-left: 5mm; font-size: 0.9em; color: #666;">Cambio:</td>
                                <td style="text-align:right; font-size: 0.9em; color: #666;"><?php echo number_format($change_amount, 2); ?>€</td>
                            </tr>
                            <?php endif; ?>
                        </table>
                        <?php
                    else:
                        // AA结账或无收款金额：只显示现金金额
                        ?>
                        <table class="payment-details-table" style="margin-top: 3mm; font-size: 0.95em;">
	                            <tr>
	                                <td colspan="2" style="text-align:center; font-weight: bold;">Detalles de Pago</td>
	                            </tr>
                            <tr>
                                <td style="text-align:left; padding-left: 5mm;">Efectivo:</td>
                                <td style="text-align:right;"><?php echo number_format($actual_cash_amount, 2); ?>€</td>
                            </tr>
                        </table>
                        <?php
                    endif;
                elseif ($payment_method_detail === 'card'):
                    // 刷卡支付：只显示刷卡
                    $card_amount = isset($payment_info_data['cardAmount']) && $payment_info_data['cardAmount'] > 0
                        ? floatval($payment_info_data['cardAmount'])
                        : $grand_total;
                    ?>
                    <table class="payment-details-table" style="margin-top: 3mm; font-size: 0.95em;">
	                        <tr>
	                            <td colspan="2" style="text-align:center; font-weight: bold;">Detalles de Pago</td>
	                        </tr>
                        <tr>
                            <td style="text-align:left; padding-left: 5mm;">Tarjeta:</td>
                            <td style="text-align:right;"><?php echo number_format($card_amount, 2); ?>€</td>
                        </tr>
                    </table>
                    <?php
                elseif ($payment_method_detail === 'mixed' && isset($payment_info_data['cashAmount'], $payment_info_data['cardAmount'])):
                    // 混合支付：显示现金和刷卡
                    ?>
                    <table class="payment-details-table" style="margin-top: 3mm; font-size: 0.95em;">
	                        <tr>
	                            <td colspan="2" style="text-align:center; font-weight: bold;">Detalles de Pago</td>
	                        </tr>
                        <tr>
                            <td style="text-align:left; padding-left: 5mm;">Efectivo:</td>
                            <td style="text-align:right;"><?php echo number_format(floatval($payment_info_data['cashAmount']), 2); ?>€</td>
                        </tr>
                        <tr>
                            <td style="text-align:left; padding-left: 5mm;">Tarjeta:</td>
                            <td style="text-align:right;"><?php echo number_format(floatval($payment_info_data['cardAmount']), 2); ?>€</td>
                        </tr>
                    </table>
                    <?php
                endif;
            endif;
            ?>

            <?php
            // Only show original total if it's significantly different and higher (indicating a discount was applied)
            if ($order_count > 0 && $grand_total_from_orders > $final_total_merged_inclusive_tax && abs($grand_total_from_orders - $final_total_merged_inclusive_tax) > 0.01):
            ?>
            <?php endif; ?>
            <hr>

            <?php
            // 添加 Verifactu 二维码
            $verifactu_qr_base64 = null;
            $merged_order_id = null;

            // 🔥 添加错误处理，防止Verifactu问题导致整个小票生成失败
            try {
                // 如果有订单ID，尝试获取Verifactu二维码
                if (!empty($order_ids_to_print) && ruiyi_has_verifactu()) {
                    ruiyi_debug_log('小票生成 - 尝试获取Verifactu二维码，订单IDs: ' . implode(',', $order_ids_to_print));

                // 检查是否需要使用合并订单的二维码
                if (count($order_ids_to_print) > 1) {
                    ruiyi_debug_log('小票生成 - 检测到多个订单，查找已存在的合并订单');

                    // 不执行合并，而是查找已经合并的订单
                    $first_order = wc_get_order($order_ids_to_print[0]);
                    if ($first_order && $first_order->get_meta('_is_merged') === 'yes') {
                        $merged_order_id = $first_order->get_meta('_merged_to_order');
                        if ($merged_order_id) {
                            ruiyi_debug_log('小票生成 - 找到已合并的订单ID: #' . $merged_order_id);
                            $order_for_qr = wc_get_order($merged_order_id);
                        } else {
                            // 如果找不到合并订单，使用第一个订单
                            $order_for_qr = $first_order;
                            ruiyi_debug_log('小票生成 - 未找到合并订单，使用第一个订单');
                        }
                    } else {
                        // 如果订单还没被合并，使用第一个订单
                        $order_for_qr = $first_order;
                        ruiyi_debug_log('小票生成 - 订单尚未合并，使用第一个订单');
                    }
                } else {
                    // 单个订单，直接使用
                    $first_order_id = reset($order_ids_to_print);
                    $order_for_qr = wc_get_order($first_order_id);
                    ruiyi_debug_log('小票生成 - 单个订单，直接使用订单ID: #' . $first_order_id);
                }

                if ($order_for_qr) {
                    // 检查订单是否已有二维码
                    $verifactu_qr_base64 = $order_for_qr->get_meta('_verifactu_qr_base64');

                    // 如果没有二维码且订单状态是completed，尝试生成
                    if (empty($verifactu_qr_base64) && $order_for_qr->get_status() === 'completed') {
                        $order_id_for_log = $order_for_qr->get_id();
                        ruiyi_debug_log('小票生成 - 订单 #' . $order_id_for_log . ' 没有二维码，尝试生成');

                        // 使用缓存的反射方法生成二维码
                        $verifactu_ref = ruiyi_get_verifactu_method('generate_and_store_qr');
                        if ($verifactu_ref) {
                            try {
                                $verifactu_ref->invoke(ruiyi_get_verifactu_instance(), $order_for_qr, true);

                                // 直接读 meta，不重载整个订单对象
                                $verifactu_qr_base64 = get_post_meta($order_id_for_log, '_verifactu_qr_base64', true);

                                if (!empty($verifactu_qr_base64)) {
                                    ruiyi_debug_log('小票生成 - 成功生成Verifactu二维码');
                                } else {
                                    ruiyi_debug_log('小票生成 - 生成Verifactu二维码失败');
                                }
                            } catch (Exception $e) {
                                ruiyi_debug_log('小票生成 - Verifactu二维码生成异常: ' . $e->getMessage());
                            }
                        } else {
                            ruiyi_debug_log('小票生成 - 无法访问Verifactu插件实例或generate_and_store_qr方法');
                        }
                    } elseif (!empty($verifactu_qr_base64)) {
                        ruiyi_debug_log('小票生成 - 找到现有的Verifactu二维码');
                    } else {
                        ruiyi_debug_log('小票生成 - 订单状态不是completed，跳过二维码生成');
                    }

                    // 如果是合并订单，更新显示的订单信息
                    if ($merged_order_id) {
                        // 将合并订单ID存储以便后续显示
                        $_POST['merged_order_id'] = $merged_order_id;

                        // 获取原始订单号以显示
                        $original_numbers = $order_for_qr->get_meta('_original_order_numbers');
                        if ($original_numbers) {
                            $_POST['original_order_numbers'] = $original_numbers;
                        }
                    }
                }
                } // 关闭 if (!empty($order_ids_to_print) && ruiyi_has_verifactu())
            } catch (Exception $e) {
                // 🔥 Verifactu处理失败不应该影响小票生成
                ruiyi_debug_log('⚠️ [小票生成] Verifactu二维码处理失败: ' . $e->getMessage());
                ruiyi_debug_log('⚠️ [小票生成] 继续生成小票，但不包含Verifactu二维码');
                $verifactu_qr_base64 = null; // 确保不显示损坏的二维码
            }

            // 显示Verifactu二维码（如果有）
            if (!empty($verifactu_qr_base64)): ?>
                <div style="text-align: center; margin-top: 5mm; margin-bottom: 3mm;">
                    <div style="font-weight: bold; font-size: 0.9em; margin-bottom: 2mm;">VERIFACTU QR</div>
                    <?php
                    // 检查是否是base64编码的图片数据
                    if (strpos($verifactu_qr_base64, 'data:image') === 0) {
                        // 已经是完整的data URL
                        $qr_src = $verifactu_qr_base64;
                    } else {
                        // 只是base64数据，需要添加前缀
                        $qr_src = 'data:image/png;base64,' . $verifactu_qr_base64;
                    }
                    ?>
                    <img src="<?php echo esc_attr($qr_src); ?>"
                         alt="Verifactu QR Code"
                         style="width: 120px; height: 120px; max-width: 100%;" />
                    <div style="font-size: 0.7em; margin-top: 1mm;">Escanear para verificar factura</div>
                </div>
                <hr>
            <?php endif; ?>

            <?php if (!empty($receipt_footer)) : ?>
            <div class="footer"><?php echo nl2br(esc_html($receipt_footer)); ?></div>
            <?php endif; ?>
        </div>
    </body>
    </html>
    <?php
    $html = ob_get_clean();

    wp_send_json_success(['html' => $html]);
    wp_die();

    } catch (Exception $e) {
        // 🔥 捕获所有错误，防止HTTP 500导致结账流程中断
        ruiyi_debug_log('❌ [小票生成错误] ' . $e->getMessage());
        ruiyi_debug_log('❌ [小票生成错误] 堆栈跟踪: ' . $e->getTraceAsString());

        // 即使出错也返回成功，但包含错误信息（这样不会中断结账流程）
        wp_send_json_success([
            'html' => '<html><body><h3>小票生成遇到错误，但订单已成功创建</h3><p>错误: ' . esc_html($e->getMessage()) . '</p></body></html>',
            'error' => true,
            'error_message' => $e->getMessage()
        ]);
        wp_die();
    }
}

// AJAX Handler for Daily Summary
add_action('wp_ajax_ruiyi_pos_get_daily_summary_html', 'ruiyi_pos_get_daily_summary_html_callback');
function ruiyi_pos_get_daily_summary_html_callback() {
    check_ajax_referer('ruiyi_pos_nonce', 'nonce');

    $date_str = isset($_POST['date']) ? sanitize_text_field($_POST['date']) : '';
    if (empty($date_str)) {
        wp_send_json_error(['message' => 'Por favor, proporcione una fecha.']);
        wp_die();
    }

    $start_date = $date_str . ' 00:00:00';
    $end_date = $date_str . ' 23:59:59';
    $report_title = 'Resumen Diario: ' . date_i18n(get_option('date_format', 'Y-m-d'), strtotime($date_str));

    // Reutilizar la lógica de generación de HTML
    $html = ruiyi_pos_generate_summary_html($start_date, $end_date, $report_title);

    if ($html) {
        wp_send_json_success(['html' => $html]);
    } else {
        wp_send_json_error(['message' => 'No se encontraron pedidos para la fecha seleccionada o hubo un error.']);
    }
    wp_die();
}

// AJAX Handler for Monthly Summary
add_action('wp_ajax_ruiyi_pos_get_monthly_summary_html', 'ruiyi_pos_get_monthly_summary_html_callback');
function ruiyi_pos_get_monthly_summary_html_callback() {
    check_ajax_referer('ruiyi_pos_nonce', 'nonce');

    $month_year_str = isset($_POST['month_year']) ? sanitize_text_field($_POST['month_year']) : ''; // Expected format YYYY-MM
    if (empty($month_year_str) || !preg_match('/^\d{4}-\d{2}$/', $month_year_str)) {
        wp_send_json_error(['message' => 'Por favor, proporcione un mes y año válidos (YYYY-MM).']);
        wp_die();
    }

    $year = substr($month_year_str, 0, 4);
    $month = substr($month_year_str, 5, 2);

    $start_date = date('Y-m-01 00:00:00', strtotime($month_year_str));
    $end_date = date('Y-m-t 23:59:59', strtotime($month_year_str)); // 't' gives the last day of the month
    $report_title = 'Resumen Mensual: ' . date_i18n('F Y', strtotime($month_year_str));
    
    // Reutilizar la lógica de generación de HTML
    $html = ruiyi_pos_generate_summary_html($start_date, $end_date, $report_title);

    if ($html) {
        wp_send_json_success(['html' => $html]);
    } else {
        wp_send_json_error(['message' => 'No se encontraron pedidos para el mes seleccionado o hubo un error.']);
    }
    wp_die();
}

/**
 * ==================================
 * POS 桌位状态实时更新相关后台处理
 * ==================================
 */

// 处理 POS 端获取所有桌位状态更新的 AJAX 请求
add_action('wp_ajax_ruiyi_pos_get_all_table_statuses', 'ruiyi_pos_get_live_table_statuses_from_option');
// POS 端通常是登录用户访问，所以一般不需要 _nopriv

function ruiyi_pos_get_live_table_statuses_from_option() {
    // 1. 安全性检查：验证 Nonce
    if (!isset($_POST['nonce']) || !wp_verify_nonce($_POST['nonce'], 'pos_ajax_nonce_action')) {
        wp_send_json_error(array('message' => 'Nonce 验证失败'), 403);
        wp_die();
    }

    // 2. 读取持久化的桌位状态
    $live_table_statuses = get_option('ruiyi_pos_live_table_statuses', array());

    $statuses_to_send = array();
    $stale_keys_removed = false; // 🔥 标记是否有残留条目被清理

    if (!empty($live_table_statuses)) {
        foreach ($live_table_statuses as $table_num => $data) {
            if (!isset($data['status']) || !isset($data['timestamp'])) {
                continue;
            }

            // 🔥 提取纯数字桌号
            $table_num_digits = preg_replace('/\D/', '', $table_num);
            if (empty($table_num_digits)) {
                continue;
            }

            // 🔥 搜索所有可能的桌号格式来查找真实订单
            $search_values = array_unique(array_filter(array(
                $table_num,
                $table_num_digits,
                'Mesa ' . $table_num_digits
            )));

            $table_pending_orders = wc_get_orders(array(
                'status' => array('wc-pending', 'wc-processing', 'wc-on-hold'),
                'meta_query' => array(
                    array(
                        'key' => '_table_number',
                        'value' => $search_values,
                        'compare' => 'IN'
                    )
                ),
                'limit' => -1,
                'return' => 'objects'
            ));

            $total_amount = 0;
            $order_count = 0;
            $latest_order_id = isset($data['orderId']) ? $data['orderId'] : null;

            foreach ($table_pending_orders as $order) {
                // 🔥🔥🔥 【关键修复】跳过已在回收站的订单（与点击处理器保持一致）
                $post = get_post($order->get_id());
                if ($post && $post->post_status === 'trash') {
                    continue;
                }

                // 🔥🔥🔥 【关键修复】跳过已合并的订单（与点击处理器保持一致）
                if ($order->get_meta('_is_merged') === 'yes') {
                    continue;
                }

                $total_amount += $order->get_total();
                $order_count++;
                if (!$latest_order_id || $order->get_id() > $latest_order_id) {
                    $latest_order_id = $order->get_id();
                }
            }

            // 🔥🔥🔥 【关键修复】如果没有真实的待付订单，说明这是残留条目
            // 自动清理：从 live_table_statuses 中移除，不返回给前端
            if ($order_count === 0) {
                unset($live_table_statuses[$table_num]);
                $stale_keys_removed = true;
                ruiyi_debug_log("[桌位状态轮询] 🧹 自动清理残留条目: key='{$table_num}', orderId=" . ($data['orderId'] ?? 'null') . ", storedTotal=" . ($data['total'] ?? 0));
                continue; // 不返回给前端
            }

            $statuses_to_send[] = array(
                'number' => $table_num_digits,
                'status' => $data['status'],
                'orderId' => $latest_order_id,
                'total' => $total_amount,
                'order_count' => $order_count,
                'timestamp' => $data['timestamp'],
                'version' => isset($data['version']) ? $data['version'] : null
            );
        }

        // 🔥 如果有残留条目被清理，原子更新数据库（防止并发竞态）
        if ($stale_keys_removed) {
            $keys_to_remove = array();
            // 收集需要移除的key（基于之前的验证结果）
            foreach ($live_table_statuses as $k => $v) {
                // 已从 $live_table_statuses 中 unset 的key不会出现在这里
            }
            // 获取被移除的keys：对比原始数据和当前数据
            ruiyi_atomic_update_table_statuses(function($db_statuses) use ($live_table_statuses) {
                // 只移除那些在验证后确认需要清理的key
                $changed = false;
                foreach (array_keys($db_statuses) as $key) {
                    if (!isset($live_table_statuses[$key])) {
                        unset($db_statuses[$key]);
                        $changed = true;
                    }
                }
                return $changed ? $db_statuses : false;
            });
            ruiyi_debug_log("[桌位状态轮询] 🧹 残留条目已原子清理");
        }
    }

    // 4. 返回结果
    wp_send_json_success(array('tables_updates' => $statuses_to_send));
    wp_die();
}

// AJAX endpoint for canceling table orders
add_action('wp_ajax_ruiyi_pos_cancel_table_orders', 'ruiyi_pos_cancel_table_orders');
add_action('wp_ajax_nopriv_ruiyi_pos_cancel_table_orders', 'ruiyi_pos_cancel_table_orders');

/**
 * Debug function to check all orders and their table numbers
 */
