/**
 * Cancel all pending orders for a specific table
 * Changes order status to 'cancelled' in WooCommerce
 */
function ruiyi_pos_cancel_table_orders() {
    // Security check
    check_ajax_referer('ruiyi_pos_nonce', 'nonce');
    
    // Check if guest request or authorized user
    $is_guest = isset($_POST['is_guest']) && $_POST['is_guest'] === 'yes';
    
    // Verificar permisos: permitir guest, admin, shop_manager, o pos_user
    if (!$is_guest) {
        $user = wp_get_current_user();
        $allowed_roles = ['administrator', 'shop_manager', 'pos_user'];
        $has_permission = array_intersect($allowed_roles, $user->roles);
        
        if (!$has_permission) {
            ruiyi_debug_log("[RUIYI_POS] Permission denied for user roles: " . implode(', ', $user->roles));
            wp_send_json_error(['message' => 'Permiso denegado']);
            return;
        }
    }
    
    // Get and validate table number
    $table_number = isset($_POST['table_number']) ? sanitize_text_field($_POST['table_number']) : '';
    if (empty($table_number)) {
        wp_send_json_error(['message' => 'Número de mesa requerido']);
        return;
    }

    // 🔥🔥🔥 【2026-04-06 关键修复】自定义桌位名称解析
    // 将自定义名（如 "T16", "W21", "厅9.5"）解析为正确的全局编号
    // 防止数字提取错误（T16 → "16" 但实际全局是 27）导致取消错误的桌位订单
    $_cancel_resolved_display = '';
    if (function_exists('ruiyi_get_all_table_categories_mapping')) {
        $_all_mappings_cl = ruiyi_get_all_table_categories_mapping();
        $_input_norm_cl = strtoupper(preg_replace('/\s+/', '', trim((string)$table_number)));
        foreach ($_all_mappings_cl as $_mapping_cl) {
            $_dn_cl = isset($_mapping_cl['category_display_name']) ? $_mapping_cl['category_display_name'] : '';
            $_dn_norm_cl = strtoupper(preg_replace('/\s+/', '', trim($_dn_cl)));
            if ($_dn_norm_cl === $_input_norm_cl && !empty($_mapping_cl['global_table_number'])) {
                $_cancel_resolved_display = $_dn_cl; // 保留原始 display_name 用于匹配换台订单
                $table_number = 'Mesa ' . (string)$_mapping_cl['global_table_number'];
                ruiyi_debug_log("[RUIYI_POS] 🔥 取消订单-自定义桌名解析: '{$_input_norm_cl}' → {$table_number}");
                break;
            }
        }
    }

    ruiyi_debug_log("[RUIYI_POS] Attempting to cancel orders for table: " . $table_number);

    try {
        // Due to WooCommerce HPOS compatibility issues, we need to get all orders first then filter manually
        $all_orders = wc_get_orders([
            'limit' => -1,
            'status' => ['pending', 'processing', 'on-hold']
        ]);
        
        // Debug: Log all orders and their table numbers
        ruiyi_debug_log("[RUIYI_POS] Total orders found: " . count($all_orders));
        foreach ($all_orders as $debug_order) {
            $debug_table = $debug_order->get_meta('_table_number');
            ruiyi_debug_log("[RUIYI_POS] Order #{$debug_order->get_id()} has table: '{$debug_table}'");
        }
        
        $cancel_mappings = !empty($_all_mappings_cl) ? $_all_mappings_cl : (function_exists('ruiyi_get_all_table_categories_mapping') ? ruiyi_get_all_table_categories_mapping() : array());

        // Filter orders manually to ensure correct table matching
        $orders = [];
        foreach ($all_orders as $order) {
            $order_table_number = $order->get_meta('_table_number');
            
            $normalized_order_table = ruiyi_normalize_table_identifier($order_table_number);
            $normalized_search_table = ruiyi_normalize_table_identifier($table_number);
            
            // Resolve by global table number instead of stripping arbitrary digits from custom names
            $order_numeric = ruiyi_safe_extract_table_number($order_table_number, $cancel_mappings);
            $search_numeric = ruiyi_safe_extract_table_number($table_number, $cancel_mappings);
            
            // Check multiple matching conditions
            $exact_match = $normalized_order_table === $normalized_search_table && !empty($normalized_order_table);
            $numeric_match = !empty($order_numeric) && !empty($search_numeric) && $order_numeric === $search_numeric;

            // 🔥🔥🔥 【2026-04-06 关键修复】优先匹配 _table_display_name（换台后订单）
            // 如果原始输入是自定义名，检查订单的 display_name 是否匹配
            $display_name_match = false;
            if (!empty($_cancel_resolved_display)) {
                $order_display_name = $order->get_meta('_table_display_name');
                if (!empty($order_display_name)) {
                    $order_dn_norm = strtoupper(preg_replace('/\s+/', '', trim((string)$order_display_name)));
                    $search_dn_norm = strtoupper(preg_replace('/\s+/', '', trim($_cancel_resolved_display)));
                    if ($order_dn_norm === $search_dn_norm) {
                        $display_name_match = true;
                    }
                }
            }
            
            // Debug all matching attempts
            ruiyi_debug_log("[RUIYI_POS] Matching attempt for order #{$order->get_id()}:");
            ruiyi_debug_log("[RUIYI_POS]   Order table: '{$order_table_number}' (normalized: '{$normalized_order_table}')");
            ruiyi_debug_log("[RUIYI_POS]   Search table: '{$table_number}' (normalized: '{$normalized_search_table}')");
            ruiyi_debug_log("[RUIYI_POS]   Exact match: " . ($exact_match ? 'YES' : 'NO'));
            ruiyi_debug_log("[RUIYI_POS]   Safe global-number match: " . ($numeric_match ? 'YES' : 'NO') . " (order: '{$order_numeric}', search: '{$search_numeric}')");
            
            if ($exact_match || $numeric_match || $display_name_match) {
                $orders[] = $order;
                ruiyi_debug_log("[RUIYI_POS] ✓ MATCHED order #{$order->get_id()} for table {$order_table_number}");
            } else {
                ruiyi_debug_log("[RUIYI_POS] ✗ NO MATCH for order #{$order->get_id()}");
            }
        }
        
        ruiyi_debug_log("[RUIYI_POS] Found " . count($orders) . " orders to cancel for table " . $table_number);
        
        $cancelled_orders = [];
        $total_cancelled = 0;
        
        foreach ($orders as $order) {
            // Change order status to cancelled
            $order->update_status('cancelled', 'Mesa liberada - Pedido cancelado automáticamente');
            
            $cancelled_orders[] = [
                'id' => $order->get_id(),
                'total' => $order->get_total(),
                'status' => $order->get_status()
            ];
            
            $total_cancelled += $order->get_total();
            
            ruiyi_debug_log("[RUIYI_POS] Cancelled order {$order->get_id()} for table {$table_number}");
        }
        
        // 🔥 原子清理所有键格式（防止并发竞态）
        $table_number_numeric = preg_replace('/[^0-9]/', '', $table_number);
        ruiyi_clear_table_status_all_formats($table_number_numeric);
        ruiyi_debug_log("[cancel_table_orders] 已原子清理桌位 $table_number_numeric 的所有状态键");
        
        // Prepare success message based on results
        $success_message = '';
        $orders_count = count($cancelled_orders);
        
        if ($orders_count > 0) {
            $success_message = sprintf(
                'Se cancelaron %d orden%s de la Mesa %s (Total: €%.2f)',
                $orders_count,
                $orders_count > 1 ? 'es' : '',
                $table_number,
                $total_cancelled
            );
        } else {
            $success_message = 'No se encontraron órdenes pendientes para esta mesa';
        }
        
        ruiyi_debug_log("[RUIYI_POS] Cancel table orders result: " . $success_message);
        
        wp_send_json_success([
            'message' => $success_message,
            'cancelled_orders' => $cancelled_orders,
            'total_orders' => $orders_count,
            'total_amount' => $total_cancelled,
            'table_number' => $table_number,
            'detailed_message' => $orders_count > 0 ?
                "✅ Se cancelaron {$orders_count} orden" . ($orders_count > 1 ? 'es' : '') . " de la Mesa {$table_number}" :
                "ℹ️ No había órdenes pendientes para la Mesa {$table_number}"
        ]);
        
    } catch (Exception $e) {
        ruiyi_debug_log("[RUIYI_POS] Error cancelling table orders: " . $e->getMessage());
        wp_send_json_error([
            'message' => 'Error al cancelar las órdenes: ' . $e->getMessage()
        ]);
    }
}

// ... a continuación, modificaremos ruiyi_pos_record_table_status_update y ruiyi_pos_create_order


/**
 * 获取订单详细信息的函数
 * 支持Ajax请求获取详细订单信息
 */
function ruiyi_get_order_details_callback() {
    // 检查是否存在WooCommerce
    if (!class_exists('WooCommerce')) {
        wp_send_json_error('WooCommerce is not active');
        return;
    }
    
    // 获取订单ID
    $order_id = isset($_POST['order_id']) ? intval($_POST['order_id']) : 0;
    
    if (!$order_id) {
        wp_send_json_error('No order ID provided');
        return;
    }
    
    // 获取订单对象
    $order = wc_get_order($order_id);
    
    if (!$order) {
        wp_send_json_error('Order not found');
        return;
    }
    
    // 获取订单项目
    $items = array();
    foreach ($order->get_items() as $item_id => $item) {
        $product = $item->get_product();
        $product_name = $item->get_name();
        $quantity = $item->get_quantity();
        $subtotal = $item->get_subtotal();
        
        $items[] = array(
            'id' => $item_id,
            'name' => $product_name,
            'quantity' => $quantity,
            'subtotal' => $subtotal,
            'subtotal_formatted' => wc_price($subtotal),
            'product_id' => $product ? $product->get_id() : 0,
        );
    }
    
    // 构建订单数据
    $order_data = array(
        'id' => $order->get_id(),
        'status' => wc_get_order_status_name($order->get_status()),
        'date' => $order->get_date_created()->date_i18n(get_option('date_format') . ' ' . get_option('time_format')),
        'total' => $order->get_total(),
        'total_formatted' => wc_price($order->get_total()),
        'items' => $items,
        'items_count' => count($items),
    );
    
    wp_send_json_success($order_data);
}
add_action('wp_ajax_ruiyi_get_order_details', 'ruiyi_get_order_details_callback');
add_action('wp_ajax_nopriv_ruiyi_get_order_details', 'ruiyi_get_order_details_callback');

/**
 * 获取所有订单的Ajax处理函数
 * 按照日期从新到旧排序
 */
function ruiyi_get_all_orders_callback() {
    // 检查是否存在WooCommerce
    if (!class_exists('WooCommerce')) {
        wp_send_json_error('WooCommerce is not active');
        return;
    }
    
    // 获取请求的限制数量，默认为20
    $limit = isset($_POST['limit']) ? intval($_POST['limit']) : 20;
    
    // 获取页码，默认为第1页
    $page = isset($_POST['page']) ? intval($_POST['page']) : 1;
    
    // 定义查询参数
    $args = array(
        'post_type' => 'shop_order',
        'post_status' => array('wc-processing', 'wc-completed', 'wc-on-hold'),
        'posts_per_page' => $limit,
        'paged' => $page,
        'orderby' => 'date',
        'order' => 'DESC'
    );
    
    // 执行查询
    $orders_query = new WP_Query($args);
    $all_orders = array();
    
    if ($orders_query->have_posts()) {
        while ($orders_query->have_posts()) {
            $orders_query->the_post();
            $order_id = get_the_ID();
            $order = wc_get_order($order_id);
            
            if (!$order) continue;
            
            // 构建订单数据
            $order_data = array(
                'id' => $order->get_id(),
                'status' => wc_get_order_status_name($order->get_status()),
                'date' => $order->get_date_created()->date_i18n(get_option('date_format') . ' ' . get_option('time_format')),
                'total' => $order->get_total(),
                'total_formatted' => wc_price($order->get_total()),
                'items_count' => $order->get_item_count(),
                'customer' => array(
                    'name' => $order->get_billing_first_name() . ' ' . $order->get_billing_last_name(),
                    'email' => $order->get_billing_email()
                )
            );
            
            $all_orders[] = $order_data;
        }
        wp_reset_postdata();
    }
    
    // 获取总记录数和总页数
    $found_posts = $orders_query->found_posts;
    $max_num_pages = $orders_query->max_num_pages;
    
    // 构建响应数据
    $response_data = array(
        'orders' => $all_orders,
        'pagination' => array(
            'total' => $found_posts,
            'total_pages' => $max_num_pages,
            'current_page' => $page,
            'per_page' => $limit
        )
    );
    
    wp_send_json_success($all_orders);
}
add_action('wp_ajax_ruiyi_get_all_orders', 'ruiyi_get_all_orders_callback');
add_action('wp_ajax_nopriv_ruiyi_get_all_orders', 'ruiyi_get_all_orders_callback');

/** * 处理单个订单的创建 (ruiyi_pos_create_order) */function ruiyi_pos_create_order_handler() {    check_ajax_referer('ruiyi_pos_nonce', 'nonce');

    // 验证必要参数
    if (!isset($_POST['cart']) || empty($_POST['cart'])) {
        wp_send_json_error(['message' => '购物车为空']);
        return;
    }

    try {
        // 解析购物车数据
        $cart_data = json_decode(stripslashes($_POST['cart']), true);
        if (!$cart_data || !is_array($cart_data)) {
            throw new Exception('购物车数据格式无效');
        }

        // 获取其他订单信息
        $table_number = isset($_POST['table_number']) ? sanitize_text_field($_POST['table_number']) : '';
        $payment_method = isset($_POST['payment_method']) ? sanitize_text_field($_POST['payment_method']) : 'cash';
        $discount = isset($_POST['discount']) ? (float)$_POST['discount'] : 0;
        $tip_amount = isset($_POST['tip_amount']) ? (float)$_POST['tip_amount'] : 0;
        
        // 获取订单类型
        $order_type = isset($_POST['order_type']) ? sanitize_text_field($_POST['order_type']) : 'servir';

        // 创建订单 (以下应适应您的订单创建逻辑)
        $order = wc_create_order();
        
        // 添加购物车商品到订单
        foreach ($cart_data as $item) {
            $product_id = $item['id'];
            $quantity = $item['quantity'];
            $product = wc_get_product($product_id);
            
            if ($product) {
                $order->add_product($product, $quantity);
            }
        }
        
        // 设置订单元数据
        if (!empty($table_number)) {
            $order->update_meta_data('_table_number', $table_number);
        }
        
        // 设置订单类型元数据
        $order->update_meta_data('_order_type', $order_type);
        // 标记订单来源为收银系统
        $order->update_meta_data('_ruiyi_order_source', '收银系统');

        // 应用折扣
        if ($discount > 0) {
            $order->add_coupon('manual_discount', $discount);
        }
        
        // 设置支付方式 - 映射到WooCommerce的正确支付方式代码
        if ($payment_method === 'cash' || $payment_method === 'Cash') {
            $order->set_payment_method('cod'); // Cash on Delivery
            $order->set_payment_method_title('现金支付');
            $order->update_meta_data('_payment_method_detail', 'cash');
        } elseif ($payment_method === 'card' || $payment_method === 'Card') {
            $order->set_payment_method('card'); // Card payment
            $order->set_payment_method_title('刷卡支付');
            $order->update_meta_data('_payment_method_detail', 'card');
        } elseif ($payment_method === 'mixed') {
            $order->set_payment_method('mixed');
            $order->set_payment_method_title('混合支付');
            $order->update_meta_data('_payment_method_detail', 'mixed');
        } else {
            $order->set_payment_method($payment_method);
        }
        
        // 计算总额
        $order->calculate_totals();
        
        // 保存订单
        $order->save();
        
        // 返回成功响应
        wp_send_json_success([
            'order_id' => $order->get_id(),
            'total' => $order->get_total()
        ]);
        
    } catch (Exception $e) {
        wp_send_json_error(['message' => $e->getMessage()]);
    }

    wp_die();
}
// Removed duplicate handler - using original ruiyi_pos_create_order function instead

/**
 * 处理多个订单的结账 (ruiyi_pos_process_multiple_orders)
 */
function ruiyi_pos_process_multiple_orders_handler() {
    check_ajax_referer('ruiyi_pos_nonce', 'nonce');
    
    if (!isset($_POST['order_ids']) || empty($_POST['order_ids'])) {
        wp_send_json_error(['message' => '没有提供订单ID']);
        return;
    }
    
    try {
        // 解析订单IDs
        $order_ids = json_decode(stripslashes($_POST['order_ids']), true);
        if (!$order_ids || !is_array($order_ids)) {
            throw new Exception('订单ID格式无效');
        }
        
        // 获取其他信息
        $payment_method = isset($_POST['payment_method']) ? sanitize_text_field($_POST['payment_method']) : 'cash';
        $table_number = isset($_POST['table_number']) ? sanitize_text_field($_POST['table_number']) : '';
        
        // 获取订单类型
        $order_type = isset($_POST['order_type']) ? sanitize_text_field($_POST['order_type']) : 'servir';
        
        // 获取前端传递的总额（用于小票显示）
        $total_amount = isset($_POST['total_amount']) ? floatval($_POST['total_amount']) : 0;
        $final_total = isset($_POST['final_total']) ? floatval($_POST['final_total']) : $total_amount; // 向后兼容
        
        // Check for pending points transactions and apply them to the first order
        $pending_points_transaction = get_option('ruiyi_pending_points_transaction', false);
        $points_applied = false;
        
        $processed_orders = 0;
        
        // 检查是否需要合并订单（多个订单的情况）
        $should_merge_orders = count($order_ids) > 1;

        if ($should_merge_orders) {
            ruiyi_debug_log("RUIYI POS: 检测到多订单结账，将先标记订单再合并，避免重复Verifactu处理");
        }

        // 处理每个订单
        foreach ($order_ids as $order_id) {
            $order = wc_get_order($order_id);

            if ($order) {
                // 🔥 关键修复：先设置支付方式，再更新订单状态
                // 这样可以确保订单变为completed时，支付方式已经是正确的

                // 如果有积分折扣且是第一个订单，更新订单总额以反映折扣
                $original_total = $order->get_total();
                ruiyi_debug_log("RUIYI POS: 订单 #{$order_id} 原始总额: €" . $original_total);

                // 设置支付方式 - 映射到WooCommerce的正确支付方式代码
                if ($payment_method === 'cash') {
                    $order->set_payment_method('cod'); // Cash on Delivery
                    $order->set_payment_method_title('现金支付');

                    // 保存现金支付的详细信息
                    $order->update_meta_data('_payment_method_detail', 'cash');
                    if (isset($_POST['received_amount'])) {
                        $received_amt = floatval($_POST['received_amount']);
                        $order->update_meta_data('_received_amount', $received_amt);
                        $order->update_meta_data('_cash_amount', $order->get_total());
                    }
                    if (isset($_POST['change_amount'])) {
                        $order->update_meta_data('_change_amount', floatval($_POST['change_amount']));
                    }
                } elseif ($payment_method === 'card') {
                    $order->set_payment_method('bacs'); // 🔥 修复：统一使用bacs，与普通结账保持一致
                    $order->set_payment_method_title('刷卡支付');

                    // 保存刷卡支付的详细信息
                    $order->update_meta_data('_payment_method_detail', 'card');
                    $order->update_meta_data('_card_amount', $order->get_total());
                    // 🔥 修复：清除现金支付的元数据，避免被误判为混合支付
                    $order->delete_meta_data('_cash_amount');
                    $order->delete_meta_data('_received_amount');
                    $order->delete_meta_data('_change_amount');
                } elseif ($payment_method === 'mixed') {
                    $order->set_payment_method('mixed');
                    $order->set_payment_method_title('混合支付');

                    // 保存混合支付的详细信息
                    $order->update_meta_data('_payment_method_detail', 'mixed');
                    if (isset($_POST['cash_amount'])) {
                        $order->update_meta_data('_cash_amount', floatval($_POST['cash_amount']));
                    }
                    if (isset($_POST['card_amount'])) {
                        $order->update_meta_data('_card_amount', floatval($_POST['card_amount']));
                    }
                } else {
                    $order->set_payment_method($payment_method);
                }

                // 🔥 支付方式设置完成后，再更新订单状态
                if ($should_merge_orders) {
                    // 多订单情况：先标记为待合并，不设置completed状态
                    $order->update_meta_data('_pending_merge', 'yes');
                    $order->update_meta_data('_merge_session', time()); // 合并会话标识
                    ruiyi_debug_log("RUIYI POS: 订单 #{$order_id} 标记为待合并，暂不设置completed状态");
                } else {
                    // 单订单情况：正常设置completed状态
                    $order->update_status('completed', '通过POS结账');
                    ruiyi_debug_log("RUIYI POS: 单订单 #{$order_id} 设置为completed状态");
                }
                
                // 更新订单类型 (即使是多订单结账，也更新每个订单的类型)
                $order->update_meta_data('_order_type', $order_type);
                
                // 记录积分折扣信息 (如果有)
                if (!$points_applied && $pending_points_transaction && is_array($pending_points_transaction)) {
                    $points_discount = floatval($pending_points_transaction['discount_amount']);
                    $points_used = intval($pending_points_transaction['points_used']);
                    $user_id = intval($pending_points_transaction['user_id']);
                    
                    if ($points_discount > 0) {
                        // Store points transaction info in order meta (for record keeping)
                        $order->update_meta_data('_points_discount_used', $points_used);
                        $order->update_meta_data('_points_discount_amount', $points_discount);
                        $order->update_meta_data('_points_discount_user_id', $user_id);
                        
                        // Apply points discount to order total
                        $new_total = $original_total - $points_discount;
                        $order->set_total($new_total);
                        
                        // Add fee line item to show the discount
                        $fee = new WC_Order_Item_Fee();
                        $fee->set_name('Descuento por Puntos (' . $points_used . ' pts)');
                        $fee->set_amount(-$points_discount);
                        $fee->set_total(-$points_discount);
                        $order->add_item($fee);
                        
                        // Mark points as applied
                        $points_applied = true;
                        
                        // Log the points discount application
                        ruiyi_debug_log("RUIYI POS: Applied points discount to order - Order ID: {$order_id}, User ID: {$user_id}, Points: {$points_used}, Discount: €{$points_discount}, New Total: €{$new_total}");
                    }
                }
                
                // 保存订单
                $order->save();

                // 验证订单总额是否正确设置 (调试用)
                if ($processed_orders === 0 && $final_total > 0) {
                    $saved_total = $order->get_total();
                    ruiyi_debug_log("RUIYI POS: Order #{$order_id} - Set total: €{$final_total}, Saved total: €{$saved_total}");
                }

                // 🔥 新增：堂食订单在结账时记录日结数据（之前创建时跳过了）
                try {
                    // Prepare items array for daily summary
                    $items_for_daily = [];
                    foreach ($order->get_items() as $item) {
                        $items_for_daily[] = [
                            'name' => $item->get_name(),
                            'quantity' => $item->get_quantity(),
                            'total' => $item->get_total()
                        ];
                    }

                    // 🔥 不再手动调用记录函数，改由自动hook处理（woocommerce_order_status_completed）
                    // 自动hook会在订单状态变为completed时自动记录到日结单，避免重复记录问题
                    $order_type_check = $order->get_meta('_order_type', true);
                    ruiyi_debug_log("[RUIYI POS] 堂食订单结账完成 - Order #" . $order->get_id() . ", Payment: {$payment_method}, Order Type: {$order_type_check}，等待自动hook记录到日结单");
                } catch (Exception $e) {
                    // Don't fail the order if daily summary recording fails
                    ruiyi_debug_log("[RUIYI POS] Failed to record table checkout transaction: " . $e->getMessage());
                }

                $processed_orders++;
            }
        }
        
        // Clear pending points transaction after successful processing
        if ($points_applied && $pending_points_transaction) {
            delete_option('ruiyi_pending_points_transaction');
            ruiyi_debug_log("RUIYI POS: Cleared pending points transaction after multiple orders processing");
        }

        // 如果是多订单情况，执行合并逻辑
        if ($should_merge_orders) {
            ruiyi_debug_log("RUIYI POS: 开始执行订单合并...");

            // 执行订单合并
            $merged_order_id = ruiyi_merge_table_orders($order_ids, $table_number);

            if ($merged_order_id) {
                ruiyi_debug_log("RUIYI POS: 订单合并成功，新订单ID: #$merged_order_id");

                // 如果有积分折扣，手动触发合并订单的Verifactu处理
                if ($points_applied && ruiyi_has_verifactu()) {
                    $has_discount = get_post_meta($merged_order_id, '_points_discount_amount', true);
                    if (!empty($has_discount)) {
                        $already_delayed = get_post_meta($merged_order_id, '_verifactu_delay_done', true);
                        if (empty($already_delayed)) {
                            ruiyi_debug_log("RUIYI POS: Manually triggering Verifactu processing for merged order with points discount #$merged_order_id");
                            do_action('verifactu_delayed_processing', $merged_order_id);
                            update_post_meta($merged_order_id, '_verifactu_delay_done', 'yes');
                        }
                    }
                }
            } else {
                ruiyi_debug_log("RUIYI POS: 订单合并失败");
            }
        } else {
            // 单订单情况：处理积分折扣的Verifactu触发
            if ($points_applied && $pending_points_transaction && ruiyi_has_verifactu()) {
                foreach ($order_ids as $order_id) {
                    $discount = get_post_meta($order_id, '_points_discount_amount', true);
                    if (!empty($discount)) {
                        $already_delayed = get_post_meta($order_id, '_verifactu_delay_done', true);
                        if (empty($already_delayed)) {
                            ruiyi_debug_log("RUIYI POS: Manually triggering Verifactu processing for single points discount order #$order_id");
                            do_action('verifactu_delayed_processing', $order_id);
                            update_post_meta($order_id, '_verifactu_delay_done', 'yes');
                        }
                    }
                }
            }
        }
        
        // 清理桌位状态 - 支付完成后将桌位状态设为可用
        if (!empty($table_number)) {
            // 提取纯数字桌号
            $table_num = preg_replace('/\D/', '', $table_number);

            if ($table_num) {
                // 🔥 原子清理所有键格式（防止并发竞态）
                ruiyi_clear_table_status_all_formats($table_num);
                ruiyi_debug_log("RUIYI POS: Atomically cleared all table keys for '$table_num' after payment completion");
                
                // 更新数据库中的桌位状态
                $table_query = new WP_Query([
                    'post_type' => 'restaurant_table',
                    'title' => "Mesa $table_num",
                    'posts_per_page' => 1,
                    'post_status' => 'publish'
                ]);
                
                if ($table_query->have_posts()) {
                    $table_post_id = $table_query->posts[0]->ID;
                    update_post_meta($table_post_id, '_table_status', 'available');
                    wp_reset_postdata();
                    ruiyi_debug_log("RUIYI POS: Updated table $table_num post status to available");
                }
            }
        }
        
        // 确保状态更新完成
        if (!empty($table_number)) {
            // 等待一小段时间确保数据库操作完成
            usleep(100000); // 0.1秒
        }
        
        // 返回成功响应
        wp_send_json_success([
            'total_processed' => $processed_orders,
            'message' => sprintf('成功处理了 %d 个订单', $processed_orders),
            'table_cleared' => !empty($table_number),
            'merged_order_id' => $merged_order_id ?? null,  // 🔥 添加合并订单ID
            'is_merged' => $should_merge_orders  // 标记是否执行了合并
        ]);
        
    } catch (Exception $e) {
        // Rollback points if processing failed and points were used
        if ($pending_points_transaction && is_array($pending_points_transaction)) {
            $user_id = intval($pending_points_transaction['user_id']);
            $points_used = intval($pending_points_transaction['points_used']);
            $site_id = isset($pending_points_transaction['site_id']) ? $pending_points_transaction['site_id'] : null;
            
            // Restore points to user
            $points_key = is_multisite() && $site_id ? "site_{$site_id}_user_points" : 'user_points';
            $current_points = intval(get_user_meta($user_id, $points_key, true));
            $restored_points = $current_points + $points_used;
            update_user_meta($user_id, $points_key, $restored_points);
            
            // Record rollback in points history
            $description = sprintf('多订单处理失败，回滚积分：%d积分', $points_used);
            if (function_exists('ruiyi_record_points_history')) {
                ruiyi_record_points_history($user_id, $points_used, $restored_points, $description, get_current_user_id(), $site_id);
            }
            
            // Clear pending transaction
            delete_option('ruiyi_pending_points_transaction');
            
            ruiyi_debug_log("RUIYI POS: Rolled back points due to multiple orders processing failure - User ID: {$user_id}, Points restored: {$points_used}");
        }
        
        wp_send_json_error(['message' => $e->getMessage()]);
    }
    
    wp_die();
}
add_action('wp_ajax_ruiyi_pos_process_multiple_orders', 'ruiyi_pos_process_multiple_orders_handler');
add_action('wp_ajax_nopriv_ruiyi_pos_process_multiple_orders', 'ruiyi_pos_process_multiple_orders_handler');

/**
 * 🔥 删除锁定商品（同步到服务器订单）
 */
function ruiyi_pos_delete_locked_item_handler() {
    check_ajax_referer('ruiyi_pos_nonce', 'nonce');

    $product_id = isset($_POST['product_id']) ? intval($_POST['product_id']) : 0;
    $table_number = isset($_POST['table_number']) ? sanitize_text_field($_POST['table_number']) : '';
    $quantity = isset($_POST['quantity']) ? intval($_POST['quantity']) : 1;
    $order_id = isset($_POST['order_id']) ? intval($_POST['order_id']) : 0; // 🔥 添加订单ID参数
    $item_id = isset($_POST['item_id']) ? intval($_POST['item_id']) : 0; // 🔥 添加订单项ID参数

    if (!$product_id || !$table_number) {
        wp_send_json_error(['message' => '缺少必要参数']);
        return;
    }

    // 🔥🔥🔥 【2026-04-06 关键修复】自定义桌位名称解析
    // 防止 preg_replace 从 "T16" 提取 "16" 然后误删 T4(全局16) 的订单项
    $_del_custom_display = '';
    if (function_exists('ruiyi_get_all_table_categories_mapping')) {
        $_all_mappings_dl = ruiyi_get_all_table_categories_mapping();
        $_input_norm_dl = strtoupper(preg_replace('/\s+/', '', trim((string)$table_number)));
        foreach ($_all_mappings_dl as $_mapping_dl) {
            $_dn_dl = isset($_mapping_dl['category_display_name']) ? $_mapping_dl['category_display_name'] : '';
            $_dn_norm_dl = strtoupper(preg_replace('/\s+/', '', trim($_dn_dl)));
            if ($_dn_norm_dl === $_input_norm_dl && !empty($_mapping_dl['global_table_number'])) {
                $_del_custom_display = $_dn_dl;
                $table_number = 'Mesa ' . (string)$_mapping_dl['global_table_number'];
                ruiyi_debug_log("[删除锁定商品] 🔥 自定义桌名解析: '{$_input_norm_dl}' → {$table_number}");
                break;
            }
        }
    }

    try {
        ruiyi_debug_log("[删除锁定商品] 开始删除 - 桌位: $table_number, 产品ID: $product_id, 数量: $quantity, 订单ID: $order_id, 订单项ID: $item_id");

        // 🔥 关键修复：如果提供了order_id和item_id，直接使用它们进行精确删除
        if ($order_id > 0 && $item_id > 0) {
            $order = wc_get_order($order_id);

            // 🔥 修复：如果订单不存在（可能是合并订单后被删除），回退到按桌位号查找
            if (!$order) {
                ruiyi_debug_log("[删除锁定商品] ⚠️ 订单 #$order_id 不存在（可能已被合并/删除），尝试按桌位号查找...");

                // 查找该桌位的所有未完成订单
                $table_orders = wc_get_orders([
                    'limit' => -1,
                    'status' => ['pending', 'processing', 'on-hold'],
                    'meta_query' => [
                        [
                            'key' => '_table_number',
                            'value' => $table_number
                        ]
                    ]
                ]);

                // 🔥🔥🔥 【2026-01-30 新增】如果没有找到，尝试通过 _table_display_name 匹配（换台后的订单）
                if (empty($table_orders)) {
                    $search_name_upper = strtoupper(preg_replace('/\s+/', '', trim($table_number)));
                    $all_orders = wc_get_orders([
                        'limit' => -1,
                        'status' => ['pending', 'processing', 'on-hold'],
                        'cache' => false
                    ]);

                    foreach ($all_orders as $check_order) {
                        $order_display_name = $check_order->get_meta('_table_display_name');
                        if (!empty($order_display_name)) {
                            $display_name_upper = strtoupper(preg_replace('/\s+/', '', trim($order_display_name)));
                            if ($display_name_upper === $search_name_upper) {
                                $table_orders[] = $check_order;
                                ruiyi_debug_log("[删除锁定商品] 通过显示桌号找到订单 #{$check_order->get_id()} (display_name: {$order_display_name})");
                            }
                        }
                    }
                }

                // 如果还没有找到，尝试用数字匹配
                if (empty($table_orders)) {
                    $table_number_numeric = preg_replace('/[^0-9]/', '', $table_number);
                    $all_orders = wc_get_orders([
                        'limit' => -1,
                        'status' => ['pending', 'processing', 'on-hold'],
                        'cache' => false
                    ]);

                    foreach ($all_orders as $check_order) {
                        $order_table = $check_order->get_meta('_table_number');
                        $order_table_numeric = preg_replace('/[^0-9]/', '', $order_table);
                        if ($order_table_numeric === $table_number_numeric) {
                            $table_orders[] = $check_order;
                        }
                    }
                }

                // 在找到的订单中查找包含该产品的订单
                $found_order = null;
                $found_item = null;
                $found_item_id = null;

                foreach ($table_orders as $check_order) {
                    foreach ($check_order->get_items() as $check_item_id => $check_item) {
                        if ($check_item->get_product_id() == $product_id) {
                            $found_order = $check_order;
                            $found_item = $check_item;
                            $found_item_id = $check_item_id;
                            ruiyi_debug_log("[删除锁定商品] ✅ 找到包含产品的订单 #" . $check_order->get_id() . ", item_id: $found_item_id");
                            break 2;
                        }
                    }
                }

                if (!$found_order || !$found_item) {
                    ruiyi_debug_log("[删除锁定商品] ❌ 在桌位 $table_number 的订单中未找到产品ID: $product_id");
                    wp_send_json_error(['message' => '订单不存在']);
                    return;
                }

                // 使用找到的订单和项目进行删除
                $order = $found_order;
                $order_id = $order->get_id();
                $item = $found_item;
                $actual_item_id = $found_item_id;

                // 跳过后续的验证，直接进入删除逻辑
                $order_id_deleted = $order_id;
                $deleted = true;

                ruiyi_debug_log("[删除锁定商品] 删除前（回退模式） - 订单ID: $order_id_deleted, 总额: €" . $order->get_total() . ", 商品数: " . count($order->get_items()));

                // 删除订单中的商品
                wc_delete_order_item($actual_item_id);
                ruiyi_debug_log("[删除锁定商品] 已删除商品（回退模式） - 订单ID: $order_id_deleted, 商品行ID: $actual_item_id, 产品ID: $product_id");

                // 刷新订单对象
                $order = wc_get_order($order_id_deleted);

                // 清除缓存
                wp_cache_delete($order_id_deleted, 'posts');
                wp_cache_delete($order_id_deleted, 'post_meta');
                clean_post_cache($order_id_deleted);

                // 检查订单是否为空，如果空则删除订单
                $remaining_items = $order->get_items();
                ruiyi_debug_log("[删除锁定商品] 删除后剩余商品数: " . count($remaining_items));

                if (empty($remaining_items) || count($remaining_items) === 0) {
                    $order->delete(true);
                    ruiyi_debug_log("[删除锁定商品] 订单#{$order_id_deleted}已清空，已删除订单");
                    wp_send_json_success([
                        'message' => '商品已删除，订单已清空',
                        'order_id' => $order_id_deleted,
                        'table_cleared' => true
                    ]);
                } else {
                    // 重新计算订单总额
                    foreach ($order->get_fees() as $fee_id => $fee) {
                        $order->remove_item($fee_id);
                    }
                    $order->calculate_totals();
                    $order->save();
                    $order = wc_get_order($order_id_deleted);
                    $new_total = $order->get_total();

                    wp_send_json_success([
                        'message' => '商品已删除',
                        'order_id' => $order_id_deleted,
                        'new_total' => $new_total,
                        'remaining_items' => count($remaining_items)
                    ]);
                }
                return; // 已经处理完毕，退出
            }
            
            // 🔥🔥🔥 【2026-01-30 关键修复】当提供了 order_id 和 item_id 时，信任这些精确标识
            // 不再严格验证 table_number，因为：
            // 1. order_id 本身就是唯一标识，可以精确定位订单
            // 2. item_id 可以精确定位订单项
            // 3. 前端可能发送了错误的 table_number（比如 tableViewMode 未更新），但 order_id 和 item_id 是正确的
            // 4. 只要 order_id 和 item_id 正确，就不会误删其他桌位的产品

            $order_table_number = $order->get_meta('_table_number');
            $order_display_name = $order->get_meta('_table_display_name');

            // 🔥 仅记录日志用于调试，不再阻止删除操作
            $order_table_numeric = preg_replace('/[^0-9]/', '', $order_table_number);
            $table_number_numeric = preg_replace('/[^0-9]/', '', $table_number);

            if ($order_table_numeric !== $table_number_numeric) {
                // 🔥 只是警告，不阻止操作（因为 order_id 和 item_id 是准确的）
                ruiyi_debug_log("[删除锁定商品] ⚠️ 注意: 前端桌位号 '$table_number'(数字:$table_number_numeric) 与订单桌位 '$order_table_number'(数字:$order_table_numeric) 不完全匹配，但 order_id=$order_id 和 item_id=$item_id 是精确的，继续执行删除");
            } else {
                ruiyi_debug_log("[删除锁定商品] ✅ 桌位验证通过: 订单 #$order_id 桌位 '$order_table_number' 匹配请求桌位 '$table_number'");
            }
            
            // 🔥 验证订单项是否存在且匹配
            $item = $order->get_item($item_id);
            $actual_item_id = $item_id; // 记录实际使用的item_id

            // 🔥 修复：如果item_id不存在（可能是订单合并后ID变化），尝试通过product_id查找
            if (!$item) {
                ruiyi_debug_log("[删除锁定商品] ⚠️ 订单项 #$item_id 不存在于订单 #$order_id，尝试通过产品ID查找...");

                // 遍历订单中的所有商品，查找匹配的产品ID
                $found_item = null;
                $found_item_id = null;
                foreach ($order->get_items() as $search_item_id => $search_item) {
                    if ($search_item->get_product_id() == $product_id) {
                        $found_item = $search_item;
                        $found_item_id = $search_item_id;
                        ruiyi_debug_log("[删除锁定商品] ✅ 找到匹配产品 - 新item_id: $found_item_id, 产品ID: $product_id");
                        break;
                    }
                }

                if ($found_item && $found_item_id) {
                    $item = $found_item;
                    $actual_item_id = $found_item_id;
                } else {
                    ruiyi_debug_log("[删除锁定商品] ❌ 在订单 #$order_id 中未找到产品ID为 $product_id 的商品");
                    wp_send_json_error(['message' => '订单项不存在']);
                    return;
                }
            } else {
                // 🔥 验证产品ID是否匹配
                $item_product_id = $item->get_product_id();
                if ($item_product_id != $product_id) {
                    wp_send_json_error(['message' => '订单项信息不匹配']);
                    return;
                }
            }
            
            $order_id_deleted = $order_id;
            $deleted = true;

            // 删除订单中的商品（使用actual_item_id，可能是查找到的新ID）
            wc_delete_order_item($actual_item_id);
            
            // 🔥 强制刷新订单对象，确保删除操作已持久化
            $order = wc_get_order($order_id_deleted);
            
            // 🔥 清除所有相关缓存，确保数据是最新的
            wp_cache_delete($order_id_deleted, 'posts');
            wp_cache_delete($order_id_deleted, 'post_meta');
            clean_post_cache($order_id_deleted);
            
            // 检查订单是否为空，如果空则删除订单
            $remaining_items = $order->get_items();

            if (empty($remaining_items) || count($remaining_items) === 0) {
                $order->delete(true);
            } else {
                // 🔥 关键修复：重新计算订单总额
                // 先移除所有费用项（如果有）
                foreach ($order->get_fees() as $fee_id => $fee) {
                    $order->remove_item($fee_id);
                }
                
                // 🔥 使用WooCommerce的标准方法重新计算所有金额
                $order->calculate_totals();
                
                // 🔥 强制保存并刷新
                $order->save();
                
                // 🔥 再次刷新订单对象验证总额是否正确
                $order = wc_get_order($order_id_deleted);
                $new_total = $order->get_total();

                // 🔥 额外验证：如果总额仍然不正确，手动设置
                $calculated_total = 0;
                foreach ($order->get_items() as $item) {
                    $calculated_total += $item->get_total();
                }

                if (abs($new_total - $calculated_total) > 0.01) {
                    $order->set_total($calculated_total);
                    $order->save();
                }
            }

        } else {
            // 🔥 向后兼容：如果没有提供order_id和item_id，使用原来的逻辑
            
            // 查找该桌位的所有未完成订单
            $orders = wc_get_orders([
                'limit' => -1,
                'status' => ['pending', 'processing', 'on-hold'],
                'meta_query' => [
                    [
                        'key' => '_table_number',
                        'value' => $table_number
                    ]
                ]
            ]);

            if (empty($orders)) {
                ruiyi_debug_log("[删除锁定商品] 未找到桌位 $table_number 的订单");
                wp_send_json_error(['message' => '未找到对应的订单']);
                return;
            }

            $deleted = false;
            $order_id_deleted = null;

            foreach ($orders as $order) {
                foreach ($order->get_items() as $item_id => $item) {
                    if ($item->get_product_id() == $product_id && $item->get_quantity() == $quantity) {
                        $order_id_deleted = $order->get_id();

                    // 🔥 记录删除前的订单信息用于调试
                    ruiyi_debug_log("[删除锁定商品] 删除前 - 订单ID: $order_id_deleted, 总额: €" . $order->get_total() . ", 商品数: " . count($order->get_items()));

                    // 删除订单中的商品
                    wc_delete_order_item($item_id);
                    $deleted = true;
                    ruiyi_debug_log("[删除锁定商品] 已删除商品 - 订单ID: $order_id_deleted, 商品行ID: $item_id, 产品ID: $product_id");

                    // 🔥 强制刷新订单对象，确保删除操作已持久化
                    $order = wc_get_order($order_id_deleted);

                    // 🔥 清除所有相关缓存，确保数据是最新的
                    wp_cache_delete($order_id_deleted, 'posts');
                    wp_cache_delete($order_id_deleted, 'post_meta');
                    clean_post_cache($order_id_deleted);

                    // 检查订单是否为空，如果空则删除订单
                    $remaining_items = $order->get_items();
                    ruiyi_debug_log("[删除锁定商品] 删除后剩余商品数: " . count($remaining_items));

                    if (empty($remaining_items) || count($remaining_items) === 0) {
                        $order->delete(true);
                        ruiyi_debug_log("[删除锁定商品] 订单#{$order_id_deleted}已清空，已删除订单");
                    } else {
                        // 🔥 关键修复：重新计算订单总额
                        // 先移除所有费用项（如果有）
                        foreach ($order->get_fees() as $fee_id => $fee) {
                            $order->remove_item($fee_id);
                            ruiyi_debug_log("[删除锁定商品] 移除费用项: " . $fee->get_name());
                        }

                        // 🔥 使用WooCommerce的标准方法重新计算所有金额
                        $order->calculate_totals();

                        // 🔥 强制保存并刷新
                        $order->save();

                        // 🔥 再次刷新订单对象验证总额是否正确
                        $order = wc_get_order($order_id_deleted);
                        $new_total = $order->get_total();

                        ruiyi_debug_log("[删除锁定商品] ✅ 订单#{$order_id_deleted}已更新 - 剩余商品: " . count($remaining_items) . ", 新总额: €{$new_total}");

                        // 🔥 额外验证：如果总额仍然不正确，手动设置
                        $calculated_total = 0;
                        foreach ($order->get_items() as $item) {
                            $calculated_total += $item->get_total();
                        }

                        if (abs($new_total - $calculated_total) > 0.01) {
                            ruiyi_debug_log("[删除锁定商品] ⚠️ 检测到总额不匹配 - 订单总额: €{$new_total}, 手动计算: €{$calculated_total}，强制修正");
                            $order->set_total($calculated_total);
                            $order->save();
                            ruiyi_debug_log("[删除锁定商品] ✅ 已强制修正订单总额为: €{$calculated_total}");
                        }
                    }

                        break 2; // 找到后跳出两层循环
                    }
                }
            }
        }

        if (!$deleted) {
            ruiyi_debug_log("[删除锁定商品] 未找到匹配的商品");
            wp_send_json_error(['message' => '未找到对应的商品']);
            return;
        }

        // 更新桌位状态
        // 🔥 关键修复：重新检查该桌位是否还有订单（使用手动过滤，兼容不同格式）
        // 提取数字部分用于匹配
        $table_number_numeric = preg_replace('/[^0-9]/', '', $table_number);
        
        // 获取所有相关状态的订单，然后手动过滤（兼容HPOS和不同格式）
        $all_remaining_orders = wc_get_orders([
            'limit' => -1,
            'status' => ['pending', 'processing', 'on-hold']
        ]);
        
        $remaining_orders = [];
        foreach ($all_remaining_orders as $order) {
            // 跳过已合并的订单
            if ($order->get_meta('_is_merged') === 'yes') {
                continue;
            }
            
            // 获取订单的桌位号
            $order_table_meta = $order->get_meta('_table_number', true);
            if (empty($order_table_meta)) {
                $order_table_meta = $order->get_meta('table_number', true);
            }
            
            // 使用数字部分进行匹配
            $order_table_numeric = preg_replace('/[^0-9]/', '', $order_table_meta);
            
            // 匹配数字部分
            if ($order_table_numeric === $table_number_numeric) {
                $remaining_orders[] = $order;
                ruiyi_debug_log("[删除锁定商品] 找到剩余订单 #{$order->get_id()} - 桌位: {$order_table_meta}, 商品数: " . count($order->get_items()));
            }
        }
        
        ruiyi_debug_log("[删除锁定商品] 桌位 {$table_number} (数字: {$table_number_numeric}) 剩余订单数: " . count($remaining_orders));

        // 🔥 计算桌位的新总额（所有未完成订单的总和）
        $updated_table_total = 0;
        foreach ($remaining_orders as $remaining_order) {
            $updated_table_total += $remaining_order->get_total();
        }

        // 如果没有订单了，清空桌位状态
        $table_num = preg_replace('/[^0-9]/', '', $table_number);
        if (empty($remaining_orders)) {
            // 🔥 原子清理所有键格式（防止并发竞态）
            ruiyi_clear_table_status_all_formats($table_num);
            ruiyi_debug_log("[删除锁定商品] 桌位 $table_num 无订单，已原子清空所有格式的状态键");
        } else {
            // 🔥 原子更新桌位状态中的总额（防止并发竞态）
            ruiyi_atomic_update_table_statuses(function($statuses) use ($table_num, $updated_table_total) {
                if (isset($statuses[$table_num])) {
                    $statuses[$table_num]['total'] = $updated_table_total;
                    $statuses[$table_num]['timestamp'] = time();
                    return $statuses;
                }
                return false;
            });
            ruiyi_debug_log("[删除锁定商品] 桌位 $table_num 总额已更新为: €{$updated_table_total}");
        }

        // 🔥 获取最终的订单信息返回给前端
        $final_order = empty($remaining_orders) ? null : wc_get_order($order_id_deleted);
        $final_order_total = $final_order ? $final_order->get_total() : 0;

        wp_send_json_success([
            'deleted' => true,
            'order_id' => $order_id_deleted,
            'order_new_total' => $final_order_total,
            'table_total' => $updated_table_total,
            'table_cleared' => empty($remaining_orders),
            'remaining_items_count' => $final_order ? count($final_order->get_items()) : 0,
            'message' => '商品已从服务器订单删除，订单总额已重新计算'
        ]);

    } catch (Exception $e) {
        ruiyi_debug_log("[删除锁定商品] 错误: " . $e->getMessage());
        wp_send_json_error(['message' => $e->getMessage()]);
    }

    wp_die();
}
add_action('wp_ajax_ruiyi_pos_delete_locked_item', 'ruiyi_pos_delete_locked_item_handler');
add_action('wp_ajax_nopriv_ruiyi_pos_delete_locked_item', 'ruiyi_pos_delete_locked_item_handler');

/**
 * 保留订单处理函数 (ruiyi_pos_reserve_order)
 */
function ruiyi_pos_reserve_order_handler() {
    check_ajax_referer('ruiyi_pos_nonce', 'nonce');
    
    if (!isset($_POST['order_ids']) || empty($_POST['order_ids'])) {
        wp_send_json_error(['message' => '没有提供订单ID']);
        return;
    }
    
    try {
        // 解析订单IDs
        $order_ids = json_decode(stripslashes($_POST['order_ids']), true);
        if (!$order_ids || !is_array($order_ids)) {
            throw new Exception('订单ID格式无效');
        }
        
        // 获取保留信息
        $order_type = isset($_POST['order_type']) ? sanitize_text_field($_POST['order_type']) : '';
        $total_amount = isset($_POST['total_amount']) ? floatval($_POST['total_amount']) : 0;
        $reason = isset($_POST['reason']) ? sanitize_text_field($_POST['reason']) : '';
        $pickup_time = isset($_POST['pickup_time']) ? sanitize_text_field($_POST['pickup_time']) : '';
        
        // 验证订单类型是否允许保留
        if (!in_array($order_type, ['delivery', 'takeaway'])) {
            throw new Exception('只有外送和外带订单可以保留');
        }
        
        $reserved_orders = 0;
        $current_time = current_time('mysql');
        
        // 处理每个订单
        foreach ($order_ids as $order_id) {
            $order = wc_get_order($order_id);
            
            if ($order) {
                // 检查订单状态是否可以保留
                $current_status = $order->get_status();
                if (!in_array($current_status, ['pending', 'processing'])) {
                    ruiyi_debug_log("RUIYI POS: Order #{$order_id} status '{$current_status}' cannot be reserved");
                    continue;
                }
                
                // 更新订单状态为保留
                $order->update_status('on-hold', '订单已保留，等待客户支付');
                
                // 存储保留信息
                $order->update_meta_data('_order_reserved', 'yes');
                $order->update_meta_data('_reserved_timestamp', $current_time);
                $order->update_meta_data('_reserved_reason', $reason);
                $order->update_meta_data('_reserved_pickup_time', $pickup_time);
                $order->update_meta_data('_reserved_order_type', $order_type);
                $order->update_meta_data('_reserved_total', $total_amount);
                
                // 保存订单
                $order->save();
                
                $reserved_orders++;
                
                ruiyi_debug_log("RUIYI POS: Reserved order #{$order_id} - Type: {$order_type}, Total: €{$total_amount}");
            }
        }
        
        if ($reserved_orders === 0) {
            throw new Exception('没有订单被保留');
        }
        
        // 返回成功响应
        wp_send_json_success([
            'reserved_orders' => $reserved_orders,
            'message' => sprintf('成功保留了 %d 个订单', $reserved_orders),
            'pickup_time' => $pickup_time,
            'reason' => $reason
        ]);
        
    } catch (Exception $e) {
        ruiyi_debug_log("RUIYI POS: Error reserving orders: " . $e->getMessage());
        wp_send_json_error(['message' => $e->getMessage()]);
    }
    
    wp_die();
}
add_action('wp_ajax_ruiyi_pos_reserve_order', 'ruiyi_pos_reserve_order_handler');
add_action('wp_ajax_nopriv_ruiyi_pos_reserve_order', 'ruiyi_pos_reserve_order_handler');

/**
 * 获取保留订单列表 (ruiyi_pos_get_reserved_orders)
 */
function ruiyi_pos_get_reserved_orders_handler() {
    check_ajax_referer('ruiyi_pos_nonce', 'nonce');
    
    try {
        // 查询保留订单
        $args = array(
            'post_type' => 'shop_order',
            'post_status' => 'wc-on-hold',
            'meta_query' => array(
                array(
                    'key' => '_order_reserved',
                    'value' => 'yes',
                    'compare' => '='
                )
            ),
            'posts_per_page' => -1,
            'orderby' => 'date',
            'order' => 'DESC'
        );
        
        $reserved_orders_query = new WP_Query($args);
        $reserved_orders = array();
        
        if ($reserved_orders_query->have_posts()) {
            while ($reserved_orders_query->have_posts()) {
                $reserved_orders_query->the_post();
                $order_id = get_the_ID();
                $order = wc_get_order($order_id);
                
                if ($order) {
                    // 获取保留信息
                    $reserved_timestamp = $order->get_meta('_reserved_timestamp');
                    $reserved_reason = $order->get_meta('_reserved_reason');
                    $reserved_pickup_time = $order->get_meta('_reserved_pickup_time');
                    $reserved_order_type = $order->get_meta('_reserved_order_type');
                    $reserved_total = $order->get_meta('_reserved_total');
                    
                    // 获取订单商品
                    $items = array();
                    foreach ($order->get_items() as $item) {
                        $items[] = array(
                            'name' => $item->get_name(),
                            'quantity' => $item->get_quantity(),
                            'total' => $item->get_total()
                        );
                    }
                    
                    $reserved_orders[] = array(
                        'id' => $order_id,
                        'date_created' => $order->get_date_created()->date_i18n('Y-m-d H:i:s'),
                        'total' => $order->get_total(),
                        'reserved_total' => $reserved_total ?: $order->get_total(),
                        'reserved_timestamp' => $reserved_timestamp,
                        'reserved_reason' => $reserved_reason,
                        'reserved_pickup_time' => $reserved_pickup_time,
                        'reserved_order_type' => $reserved_order_type,
                        'customer_name' => $order->get_billing_first_name() . ' ' . $order->get_billing_last_name(),
                        'items' => $items,
                        'items_count' => count($items)
                    );
                }
            }
            wp_reset_postdata();
        }
        
        wp_send_json_success([
            'reserved_orders' => $reserved_orders,
            'total_count' => count($reserved_orders)
        ]);
        
    } catch (Exception $e) {
        ruiyi_debug_log("RUIYI POS: Error getting reserved orders: " . $e->getMessage());
        wp_send_json_error(['message' => $e->getMessage()]);
    }
    
    wp_die();
}
add_action('wp_ajax_ruiyi_pos_get_reserved_orders', 'ruiyi_pos_get_reserved_orders_handler');
add_action('wp_ajax_nopriv_ruiyi_pos_get_reserved_orders', 'ruiyi_pos_get_reserved_orders_handler');

/**
 * 恢复保留订单到支付流程 (ruiyi_pos_restore_reserved_order)
 */
function ruiyi_pos_restore_reserved_order_handler() {
    check_ajax_referer('ruiyi_pos_nonce', 'nonce');
    
    if (!isset($_POST['order_id']) || empty($_POST['order_id'])) {
        wp_send_json_error(['message' => '没有提供订单ID']);
        return;
    }
    
    try {
        $order_id = absint($_POST['order_id']);
        $order = wc_get_order($order_id);
        
        if (!$order) {
            throw new Exception('订单不存在');
        }
        
        // 检查是否为保留订单
        $is_reserved = $order->get_meta('_order_reserved');
        if ($is_reserved !== 'yes') {
            throw new Exception('订单不是保留状态');
        }
        
        // 恢复订单状态
        $order->update_status('pending', '订单已从保留状态恢复，等待支付');
        
        // 清除保留标记但保留历史信息
        $order->update_meta_data('_order_reserved', 'no');
        $order->update_meta_data('_restored_timestamp', current_time('mysql'));
        
        $order->save();
        
        // 获取订单信息用于前端处理
        $order_data = array(
            'id' => $order_id,
            'total' => $order->get_total(),
            'order_type' => $order->get_meta('_reserved_order_type'),
            'items' => array()
        );
        
        foreach ($order->get_items() as $item) {
            $order_data['items'][] = array(
                'name' => $item->get_name(),
                'quantity' => $item->get_quantity(),
                'price' => $item->get_total() / $item->get_quantity()
            );
        }
        
        wp_send_json_success([
            'message' => '订单已恢复到支付流程',
            'order_data' => $order_data
        ]);
        
    } catch (Exception $e) {
        ruiyi_debug_log("RUIYI POS: Error restoring reserved order: " . $e->getMessage());
        wp_send_json_error(['message' => $e->getMessage()]);
    }
    
    wp_die();
}
add_action('wp_ajax_ruiyi_pos_restore_reserved_order', 'ruiyi_pos_restore_reserved_order_handler');
add_action('wp_ajax_nopriv_ruiyi_pos_restore_reserved_order', 'ruiyi_pos_restore_reserved_order_handler');

/**
 * 获取厨房订单 (ruiyi_get_pedidos_cocina)
 */
function ruiyi_get_pedidos_cocina_handler() {
    check_ajax_referer('cocina_nonce', 'nonce');
    
    try {
        // 调试日志
        ruiyi_debug_log('开始获取厨房订单');
        
        // 查询未完成的订单（包括处理中和需要厨房准备的已完成外卖订单）
        $args = array(
            'post_type' => 'shop_order',
            'post_status' => array('wc-processing', 'wc-completed'), // 查询处理中和已完成的订单
            'posts_per_page' => -1,
            'orderby' => 'date',
            'order' => 'DESC',
        );
        
        $orders_query = new WP_Query($args);
        $orders_data = array();
        
        ruiyi_debug_log('查询到的订单数量:', $orders_query->post_count);
        
        if ($orders_query->have_posts()) {
            while ($orders_query->have_posts()) {
                $orders_query->the_post();
                $order_id = get_the_ID();
                $order = wc_get_order($order_id);

                // 检查是否应该显示在厨房
                $order_status = $order->get_status();
                $needs_kitchen_prep = $order->get_meta('_needs_kitchen_preparation', true);
                $kitchen_completed = $order->get_meta('_kitchen_completed', true);

                // 跳过不需要在厨房显示的订单
                $should_show = false;
                if ($order_status === 'processing' && $kitchen_completed !== 'yes') {
                    // 处理中且未被厨房标记完成的订单
                    $should_show = true;
                } elseif ($order_status === 'completed' && $needs_kitchen_prep === 'yes' && $kitchen_completed !== 'yes') {
                    // 已完成但需要厨房准备的外卖订单
                    $should_show = true;
                }

                if (!$should_show) {
                    continue;
                }

                // 获取订单项目
                $items = array();
                foreach ($order->get_items() as $item_id => $item) {
                    $items[] = array(
                        'name' => $item->get_name(),
                        'quantity' => $item->get_quantity()
                    );
                }

                // 获取桌号
                $table_number = $order->get_meta('_table_number', true);

                // 获取订单类型并记录日志
                $order_type = $order->get_meta('_order_type', true);
                ruiyi_debug_log("订单 ID $order_id 的订单类型:", $order_type);

                if (empty($order_type)) {
                    $order_type = 'servir'; // 默认值
                    ruiyi_debug_log("订单 ID $order_id 使用默认订单类型 'servir'");
                }

                // 构建订单数据
                $orders_data[] = array(
                    'id' => $order_id,
                    'table_number' => $table_number,
                    'items' => $items,
                    'order_type' => $order_type, // 添加订单类型
                    'date' => $order->get_date_created()->date_i18n('Y-m-d H:i:s')
                );
            }
            
            wp_reset_postdata();
        }
        
        ruiyi_debug_log('发送给厨房的订单数据:', $orders_data);
        
        wp_send_json_success(['orders' => $orders_data]);
        
    } catch (Exception $e) {
        ruiyi_debug_log('获取厨房订单时出错:', $e->getMessage());
        wp_send_json_error(['message' => $e->getMessage()]);
    }
    
    wp_die();
}

/**
 * 调试日志函数 — 仅在 RUIYI_DEBUG=true 时写入日志
 * ⚠️ 禁止将此函数内部的 error_log 替换为 ruiyi_debug_log，会导致无限递归
 */
function ruiyi_debug_log($message, $data = null) {
    if (!RUIYI_DEBUG) return;
    if (is_array($data) || is_object($data)) {
        $message .= ' ' . print_r($data, true);
    } elseif ($data) {
        $message .= ' ' . $data;
    }
    error_log($message);
}

// 处理常规用户登录的AJAX函数
function ruiyi_user_login_handler() {
    // 记录请求详情
    ruiyi_debug_log('接收到登录请求:', $_POST);
    
    // 临时移除nonce检查以便调试
    // check_ajax_referer('ruiyi_pos_nonce', 'nonce');
    
    $email = sanitize_email($_POST['email']);
    $password = $_POST['password'];

    if (empty($email) || empty($password)) {
        wp_send_json_error(['message' => '请输入邮箱和密码']);
        return;
    }

    // 获取用户
    $user = get_user_by('email', $email);
    
    if (!$user) {
        // 也尝试通过用户名查找
        $user = get_user_by('login', $email);
    }
    
    if (!$user) {
        wp_send_json_error(['message' => '用户不存在']);
        return;
    }

    // 验证密码
    $creds = [
        'user_login' => $user->user_login,
        'user_password' => $password,
        'remember' => true
    ];

    $user_verify = wp_signon($creds, false);

    if (is_wp_error($user_verify)) {
        wp_send_json_error(['message' => '密码错误']);
        return;
    }

    // 成功登录
    wp_set_current_user($user->ID);
    wp_set_auth_cookie($user->ID);
    
    // 准备返回给前端的用户数据
    $user_data = [
        'ID' => $user->ID,
        'user_login' => $user->user_login,
        'display_name' => $user->display_name,
        'user_email' => $user->user_email,
        'roles' => $user->roles
    ];

    wp_send_json_success([
        'message' => '登录成功',
        'redirect' => home_url('/'),
        'user' => $user_data
    ]);
}
add_action('wp_ajax_login_user', 'ruiyi_user_login_handler');
add_action('wp_ajax_nopriv_login_user', 'ruiyi_user_login_handler');
add_action('wp_ajax_nopriv_ruiyi_user_login', 'ruiyi_user_login_handler');

// 处理用户注册的AJAX函数
function ruiyi_user_register_handler() {
    // 记录请求详情
    ruiyi_debug_log('接收到注册请求:', $_POST);
    
    // 恢复Nonce检查
    check_ajax_referer('ruiyi_pos_nonce', 'nonce');

    $name = sanitize_text_field($_POST['name']);
    $email = sanitize_email($_POST['email']);
    $password = $_POST['password'];

    if (empty($name) || empty($email) || empty($password)) {
        wp_send_json_error(['message' => '请填写所有必填字段']);
        return;
    }

    if (!is_email($email)) {
        wp_send_json_error(['message' => '邮箱格式不正确']);
        return;
    }

    // 检查邮箱是否已存在
    if (email_exists($email)) {
        wp_send_json_error(['message' => '该邮箱已被注册']);
        return;
    }

    // 用户名使用邮箱前缀部分
    $username = explode('@', $email)[0];
    $original_username = $username;
    $counter = 1;

    // 确保用户名唯一
    while (username_exists($username)) {
        $username = $original_username . $counter;
        $counter++;
    }

    // 创建新用户
    $user_id = wp_create_user($username, $password, $email);

    if (is_wp_error($user_id)) {
        wp_send_json_error(['message' => '创建用户失败: ' . $user_id->get_error_message()]);
        return;
    }

    // 更新用户信息
    wp_update_user([
        'ID' => $user_id,
        'display_name' => $name,
        'first_name' => $name,
    ]);

    // 设置用户角色为客户
    $user = new WP_User($user_id);
    $user->set_role('customer');

    // 发送通知邮件
    wp_new_user_notification($user_id, null, 'both');

    wp_send_json_success(['message' => '注册成功']);
}
add_action('wp_ajax_register_user', 'ruiyi_user_register_handler');
add_action('wp_ajax_nopriv_register_user', 'ruiyi_user_register_handler');
add_action('wp_ajax_nopriv_ruiyi_user_register', 'ruiyi_user_register_handler');

