//用户积分 REST API

add_action('rest_api_init', function () {
    // 获取积分接口
    register_rest_route('ruiyi/v1', '/user-points-by-email', [
        'methods' => 'GET',
        'callback' => 'ruiyi_get_user_points_by_email',
        'permission_callback' => '__return_true',
    ]);

    // 修改积分接口
    register_rest_route('ruiyi/v1', '/user-points-by-email', [
        'methods' => 'POST',
        'callback' => 'ruiyi_update_user_points_by_email',
        'permission_callback' => '__return_true',
    ]);
});

function ruiyi_get_user_points_by_email($request) {
    $email = sanitize_email($request->get_param('email'));
    if (!$email || !is_email($email)) {
        return new WP_Error('invalid_email', '邮箱无效', ['status' => 400]);
    }

    $user = get_user_by('email', $email);
    if (!$user) {
        return new WP_Error('user_not_found', '未找到该邮箱对应的用户', ['status' => 404]);
    }

    $points = get_user_meta($user->ID, 'ruiyi_user_points', true);
    return [
        'email' => $email,
        'user_id' => $user->ID,
        'points' => intval($points),
    ];
}

function ruiyi_update_user_points_by_email($request) {
    $email = sanitize_email($request->get_param('email'));
    $new_points = intval($request->get_param('points'));

    if (!$email || !is_email($email)) {
        return new WP_Error('invalid_email', '邮箱无效', ['status' => 400]);
    }

    $user = get_user_by('email', $email);
    if (!$user) {
        return new WP_Error('user_not_found', '未找到该邮箱对应的用户', ['status' => 404]);
    }

    update_user_meta($user->ID, 'ruiyi_user_points', $new_points);

    return [
        'status' => 'success',
        'email' => $email,
        'user_id' => $user->ID,
        'points' => $new_points
    ];
}

