/**
 * 修复 /wp/v2/users/me 端点响应格式
 * 确保返回单个用户对象而不是数组
 */
function fix_users_me_endpoint($response, $handler, $request) {
    // 检查是否是 users/me 端点
    if (strpos($request->get_route(), '/wp/v2/users/me') !== false) {
        ruiyi_debug_log('Processing users/me endpoint request');
        
        // 如果响应是数组且只有一个元素，返回该元素
        if (is_array($response->data) && count($response->data) === 1) {
            ruiyi_debug_log('Converting users array to single user object');
            $response->data = $response->data[0];
        }
        
        // 如果是空数组，返回错误
        if (is_array($response->data) && empty($response->data)) {
            return new WP_Error(
                'user_not_found',
                '找不到当前用户',
                array('status' => 404)
            );
        }
        
        // 记录响应类型以便调试
        ruiyi_debug_log('users/me response type: ' . gettype($response->data));
    }
    
    return $response;
}
add_filter('rest_post_dispatch', 'fix_users_me_endpoint', 10, 3);

