 */
function ensure_woocommerce_customers_me() {
    // 检查WooCommerce是否激活
    if (!class_exists('WooCommerce')) {
        return;
    }
    
    // 注册customers/me端点
    add_action('rest_api_init', function() {
        register_rest_route('wc/v3', '/customers/me', array(
            'methods' => 'GET',
