add_action('init', 'ensure_woocommerce_customers_me');

function get_current_wc_customer($request) {
    $current_user = wp_get_current_user();
    
    if (!$current_user->exists()) {
        return new WP_Error(
            'woocommerce_rest_authentication_error',
            '用户未认证',
            array('status' => 401)
        );
    }
    
    // 获取WooCommerce客户数据
    $customer = new WC_Customer($current_user->ID);
    
    $customer_data = array(
        'id' => $customer->get_id(),
        'email' => $customer->get_email(),
        'first_name' => $customer->get_first_name(),
        'last_name' => $customer->get_last_name(),
        'username' => $customer->get_username(),
        'billing' => $customer->get_billing(),
        'shipping' => $customer->get_shipping(),
        'avatar_url' => get_avatar_url($customer->get_email()),
        // 添加积分字段（如果使用积分插件）
        'points' => get_user_meta($customer->get_id(), 'points', true) ?: 0,
        'shortcode' => get_user_meta($customer->get_id(), 'shortcode', true) ?: '',
    );
    
    return rest_ensure_response($customer_data);
}

/**
 * 记录API请求以便调试
 */
function log_rest_api_requests($response, $handler, $request) {
    $route = $request->get_route();
    
    // 只记录相关的端点
    if (strpos($route, '/users/me') !== false ||
        strpos($route, '/customers/me') !== false ||
        strpos($route, '/customers') !== false) {
        
        ruiyi_debug_log('=== REST API Request ===');
        ruiyi_debug_log('Route: ' . $route);
        ruiyi_debug_log('Method: ' . $request->get_method());
        ruiyi_debug_log('Headers: ' . json_encode($request->get_headers()));
        ruiyi_debug_log('Response status: ' . $response->get_status());
        ruiyi_debug_log('Response type: ' . gettype($response->data));
        ruiyi_debug_log('Response data: ' . json_encode($response->data));
        ruiyi_debug_log('=== End Request ===');
    }
    
    return $response;
}
add_filter('rest_post_dispatch', 'log_rest_api_requests', 999, 3);

/**
 * 处理CORS跨域请求
 */
add_action('init', 'handle_preflight');
function handle_preflight() {
    $origin = get_http_origin();
    if ($origin) {
        header("Access-Control-Allow-Origin: $origin");
        header("Access-Control-Allow-Methods: POST, GET, OPTIONS, PUT, DELETE");
        header("Access-Control-Allow-Credentials: true");
        header('Access-Control-Allow-Headers: Authorization, Content-Type, X-WP-Nonce');
        if ('OPTIONS' == $_SERVER['REQUEST_METHOD']) {
            status_header(200);
            exit();
        }
    }
}

// 注册自定义用户注册端点 - 使用最高优先级
add_action('rest_api_init', function () {
    // 🔥 增强调试 - 记录端点注册开始
    $debug_message = date('Y-m-d H:i:s') . " - REST_API_INIT 开始注册端点\n";
    file_put_contents(WP_CONTENT_DIR . '/debug.log', $debug_message, FILE_APPEND);
    ruiyi_debug_log("🔴 [REST_API_INIT] 开始注册自定义端点");
    
    // 🔥 强制覆盖任何现有的 /register 端点，使用明确的args定义
    $register_result = register_rest_route('custom/v1', '/register', array(
        'methods' => 'POST',
        'callback' => 'custom_user_registration',
        'permission_callback' => '__return_true',
        'override' => true, // 强制覆盖
        'args' => array(
            'username' => array(
                'required' => false,
                'type' => 'string',
                'sanitize_callback' => 'sanitize_text_field',
            ),
            'email' => array(
                'required' => true,
                'type' => 'string',
                'validate_callback' => function($param, $request, $key) {
                    return is_email($param);
                },
                'sanitize_callback' => 'sanitize_email',
            ),
            'password' => array(
                'required' => true,
                'type' => 'string',
            ),
            'first_name' => array(
                'required' => false,
                'type' => 'string',
                'sanitize_callback' => 'sanitize_text_field',
            ),
            'last_name' => array(
                'required' => false,
                'type' => 'string',
                'sanitize_callback' => 'sanitize_text_field',
            ),
            'referral_code' => array(
                'required' => false,
                'type' => 'string',
                'sanitize_callback' => 'sanitize_text_field',
            ),
        )
    ));
    
    // 🔥 验证端点注册是否成功
    if ($register_result) {
        ruiyi_debug_log("✅ [REST_API_INIT] custom/v1/register 端点注册成功");
        file_put_contents(WP_CONTENT_DIR . '/debug.log', date('Y-m-d H:i:s') . " - custom/v1/register 端点注册成功\n", FILE_APPEND);
    } else {
        ruiyi_debug_log("❌ [REST_API_INIT] custom/v1/register 端点注册失败");
        file_put_contents(WP_CONTENT_DIR . '/debug.log', date('Y-m-d H:i:s') . " - custom/v1/register 端点注册失败\n", FILE_APPEND);
    }
    
    // 🔥 添加专门的测试注册端点
    $test_register_result = register_rest_route('custom/v1', '/test-register', array(
        'methods' => 'POST',
        'callback' => function($request) {
            ruiyi_debug_log("🔴 [TEST_REGISTER] 测试注册端点被调用");
            
            // 获取参数
            $params = $request->get_json_params();
            if (empty($params)) {
                $params = $request->get_body_params();
            }
            
            return new WP_REST_Response([
                'success' => true,
                'message' => '测试注册端点工作正常',
                'timestamp' => current_time('mysql'),
                'received_params' => $params,
                'custom_function_exists' => function_exists('custom_user_registration'),
                'endpoint' => 'custom/v1/test-register'
            ], 200);
        },
        'permission_callback' => '__return_true',
        'args' => array(
            'test_param' => array(
                'required' => false,
                'type' => 'string',
            ),
        )
    ));
    
    if ($test_register_result) {
        ruiyi_debug_log("✅ [REST_API_INIT] custom/v1/test-register 端点注册成功");
    } else {
        ruiyi_debug_log("❌ [REST_API_INIT] custom/v1/test-register 端点注册失败");
    }
    
    // 保持原有的测试端点
    register_rest_route('custom/v1', '/test', array(
        'methods' => 'GET',
        'callback' => function() {
            return new WP_REST_Response([
                'success' => true,
                'message' => '测试端点工作正常',
                'timestamp' => current_time('mysql'),
                'functions_loaded' => function_exists('custom_user_registration')
            ], 200);
        },
        'permission_callback' => '__return_true'
    ));
    
    // 🔥 添加调试端点检查所有 custom/v1 路由
    register_rest_route('custom/v1', '/debug-routes', array(
        'methods' => 'GET',
        'callback' => function() {
            $routes = [];
            $server = rest_get_server();
            $all_routes = $server->get_routes();
            
            // 查找 custom/v1 命名空间的路由
            foreach ($all_routes as $route => $handlers) {
                if (strpos($route, '/custom/v1') === 0) {
                    $routes[$route] = array_map(function($handler) {
                        return [
                            'methods' => $handler['methods'],
                            'callback' => is_string($handler['callback']) ? $handler['callback'] : (is_array($handler['callback']) ? 'Array' : 'Closure'),
                            'permission_callback' => is_string($handler['permission_callback']) ? $handler['permission_callback'] : 'Closure'
                        ];
                    }, $handlers);
                }
            }
            
            return new WP_REST_Response([
                'success' => true,
                'registered_routes' => $routes,
                'total_custom_routes' => count($routes),
                'timestamp' => current_time('mysql'),
                'current_priority' => 999
            ], 200);
        },
        'permission_callback' => '__return_true'
    ));
    
    // 🔥 最终验证 - 记录端点注册完成
    ruiyi_debug_log("🔴 [REST_API_INIT] 所有端点注册完成，priority: PHP_INT_MAX (绝对最高)");
    file_put_contents(WP_CONTENT_DIR . '/debug.log', date('Y-m-d H:i:s') . " - 所有自定义端点注册完成，priority: PHP_INT_MAX\n", FILE_APPEND);
}, PHP_INT_MAX); // 🔥 使用绝对最高优先级

/**
 * 自定义用户注册回调函数
 *
 * @param WP_REST_Request $request
 * @return WP_REST_Response|WP_Error
 */
function custom_user_registration($request) {
    // 🔥 强制写入调试文件和错误日志 - 增加时间戳和唯一标识
    $debug_message = date('Y-m-d H:i:s') . " - CUSTOM_USER_REGISTRATION 函数被调用！[" . uniqid() . "]\n";
    file_put_contents(WP_CONTENT_DIR . '/debug.log', $debug_message, FILE_APPEND);
    ruiyi_debug_log("=== 🔴 [RUIYI_DEBUG] CUSTOM_USER_REGISTRATION 函数被调用！[" . uniqid() . "] ===");
    
    // 🔥 额外的强制日志 - 无论如何都会记录
    ruiyi_debug_log("[" . date('Y-m-d H:i:s') . "] ❗ CUSTOM_USER_REGISTRATION FUNCTION CALLED ❗");
    
    try {
        // 记录请求详细信息
        ruiyi_debug_log("🔴 [RUIYI_DEBUG] 请求方法: " . $request->get_method());
        ruiyi_debug_log("🔴 [RUIYI_DEBUG] Content-Type: " . $request->get_content_type());
        ruiyi_debug_log("🔴 [RUIYI_DEBUG] 原始请求体: " . $request->get_body());
        
        // 🔥 改进的参数获取逻辑
        $params = [];
        
        // 首先尝试获取JSON参数
        $json_params = $request->get_json_params();
        if (!empty($json_params) && is_array($json_params)) {
            $params = $json_params;
            ruiyi_debug_log("🔴 [RUIYI_DEBUG] 使用JSON参数");
        } else {
            // 尝试获取POST参数
            $body_params = $request->get_body_params();
            if (!empty($body_params) && is_array($body_params)) {
                $params = $body_params;
                ruiyi_debug_log("🔴 [RUIYI_DEBUG] 使用Body参数");
            } else {
                // 最后尝试解析原始请求体
                $raw_body = $request->get_body();
                if (!empty($raw_body)) {
                    $decoded = json_decode($raw_body, true);
                    if (json_last_error() === JSON_ERROR_NONE && is_array($decoded)) {
                        $params = $decoded;
                        ruiyi_debug_log("🔴 [RUIYI_DEBUG] 使用原始请求体解析");
                    }
                }
            }
        }
        
        ruiyi_debug_log("🔴 [RUIYI_DEBUG] 最终参数: " . json_encode($params));
        
        // 检查必要参数
        $required_fields = ['username', 'email', 'password'];
        foreach ($required_fields as $field) {
            if (!isset($params[$field]) || empty($params[$field])) {
                ruiyi_debug_log("🔴 [RUIYI_DEBUG] 缺少必要参数: $field");
                return new WP_Error('missing_field', "缺少必要参数: $field", array('status' => 400));
            }
        }
        
        $username = sanitize_text_field($params['username']);
        $email = sanitize_email($params['email']);
        $password = $params['password'];
        $first_name = isset($params['first_name']) ? sanitize_text_field($params['first_name']) : '';
        $last_name = isset($params['last_name']) ? sanitize_text_field($params['last_name']) : '';
        
        // 🔥 推荐码处理逻辑
        $referral_code = null;
        if (isset($params['referral_code']) && !empty($params['referral_code'])) {
            $referral_code = sanitize_text_field($params['referral_code']);
            ruiyi_debug_log("🔵 [Registration] 使用手动输入的推荐码: {$referral_code}");
        } elseif (isset($_COOKIE['ruiyi_referral_code']) && !empty($_COOKIE['ruiyi_referral_code'])) {
            $referral_code = sanitize_text_field($_COOKIE['ruiyi_referral_code']);
            ruiyi_debug_log("🔵 [Registration] 使用Cookie中的推荐码: {$referral_code}");
        }

        ruiyi_debug_log("🔵 [Registration] 开始注册流程 - 用户名: {$username}, 邮箱: {$email}, 推荐码: " . ($referral_code ?: '无'));

        // 基础验证
        if (empty($username) || empty($email) || empty($password)) {
            return new WP_Error('missing_fields', '缺少必要字段 (用户名、邮箱、密码)', array('status' => 400));
        }
        
        if (!is_email($email)) {
            return new WP_Error('invalid_email', '无效的邮箱地址', array('status' => 400));
        }
        
        if (username_exists($username)) {
            return new WP_Error('username_exists', '用户名已存在', array('status' => 409));
        }
        
        if (email_exists($email)) {
            return new WP_Error('email_exists', '该邮箱已被注册', array('status' => 409));
        }

        // 🔥 验证推荐码（如果提供）
        $referral_data = null;
        if ($referral_code) {
            ruiyi_debug_log("🔵 [Registration] 验证推荐码: {$referral_code}");
            $referral_data = get_option('ruiyi_referral_' . $referral_code);
            ruiyi_debug_log("🔵 [Registration] 推荐码数据: " . print_r($referral_data, true));
            
            if (!$referral_data || $referral_data['status'] !== 'active') {
                ruiyi_debug_log("🔴 [Registration] 推荐码无效或非活跃状态");
                return new WP_Error('invalid_referral_code', '无效的推荐码', array('status' => 400));
            }
            ruiyi_debug_log("🟢 [Registration] 推荐码验证成功 - 推荐人ID: " . $referral_data['referrer_id'] . ", 商家ID: " . $referral_data['site_id']);
        } else {
            ruiyi_debug_log("🔵 [Registration] 没有提供推荐码");
        }

        // 创建用户
        $user_data = array(
            'user_login' => $username,
            'user_email' => $email,
            'user_pass' => $password,
            'first_name' => $first_name,
            'last_name' => $last_name,
            'display_name' => trim($first_name . ' ' . $last_name),
            'role' => 'customer'
        );
        
        $user_id = wp_insert_user($user_data);

        if (is_wp_error($user_id)) {
            ruiyi_debug_log("🔴 [Registration] 用户创建失败: " . $user_id->get_error_message());
            return new WP_Error(
                $user_id->get_error_code(),
                $user_id->get_error_message(),
                array('status' => 400)
            );
        }

        ruiyi_debug_log("🟢 [Registration] 用户创建成功 - 用户ID: {$user_id}");

        // 🔥 确保主域名用户也有正确的4位数字短代码
        $main_site_shortcode = get_user_meta($user_id, 'user_shortcode', true);
        if (empty($main_site_shortcode) || !preg_match('/^\d{4}$/', $main_site_shortcode)) {
            if (function_exists('ruiyi_generate_unique_shortcode')) {
                $new_shortcode = ruiyi_generate_unique_shortcode();
                update_user_meta($user_id, 'user_shortcode', $new_shortcode);
                ruiyi_debug_log("🟢 [Registration] 主域名用户{$user_id}强制生成4位短代码: {$new_shortcode}");
            }
        }

        // 🔥 处理推荐关系和自动添加商家
        $auto_added_merchants = 0;
        ruiyi_debug_log("🔵 [Registration] 检查推荐关系 - referral_code: {$referral_code}, has_referral_data: " . (!empty($referral_data) ? 'true' : 'false'));
        
        if ($referral_code && $referral_data) {
            ruiyi_debug_log("🔵 [Registration] 开始处理推荐关系");
            try {
                $referrer_id = $referral_data['referrer_id'];
                $site_id = $referral_data['site_id'];

                // 建立推荐关系
                add_user_meta($user_id, 'referred_by', $referrer_id);
                add_user_meta($user_id, 'referral_site', $site_id);
                add_user_meta($user_id, 'referral_code_used', $referral_code);
                add_user_meta($user_id, 'referral_date', current_time('mysql'));

                // 更新推荐人的下级列表
                $referrer_referrals = get_user_meta($referrer_id, 'ruiyi_my_referrals', true);
                if (!is_array($referrer_referrals)) {
                    $referrer_referrals = array();
                }
                $referrer_referrals[] = array(
                    'user_id' => $user_id,
                    'site_id' => $site_id,
                    'referral_code' => $referral_code,
                    'date' => current_time('mysql')
                );
                update_user_meta($referrer_id, 'ruiyi_my_referrals', $referrer_referrals);

                // 🔥 自动添加被分享的特定商家
                $shared_site_id = $referral_data['site_id'];
                
                $referrer_sites = get_user_meta($referrer_id, 'ruiyi_user_sites', true);
                ruiyi_debug_log("🔵 [Registration] 调试信息 - 推荐人ID: {$referrer_id}, 商家ID: {$shared_site_id}");
                ruiyi_debug_log("🔵 [Registration] 推荐人的商家列表: " . print_r($referrer_sites, true));
                ruiyi_debug_log("🔵 [Registration] 条件检查 - 非空: " . (!empty($referrer_sites) ? 'true' : 'false') . ", 数组: " . (is_array($referrer_sites) ? 'true' : 'false') . ", 包含商家: " . (is_array($referrer_sites) && in_array($shared_site_id, $referrer_sites) ? 'true' : 'false'));
                
                if (!empty($referrer_sites) && is_array($referrer_sites) && in_array($shared_site_id, $referrer_sites)) {
                    $new_user_sites = array($shared_site_id);
                    update_user_meta($user_id, 'ruiyi_user_sites', $new_user_sites);
                    
                    $referrer_woocommerce_sites = get_user_meta($referrer_id, 'ruiyi_user_woocommerce_sites', true);
                    if (!empty($referrer_woocommerce_sites) && is_array($referrer_woocommerce_sites) && isset($referrer_woocommerce_sites[$shared_site_id])) {
                        $new_user_woocommerce_sites = array(
                            $shared_site_id => $referrer_woocommerce_sites[$shared_site_id]
                        );
                        update_user_meta($user_id, 'ruiyi_user_woocommerce_sites', $new_user_woocommerce_sites);
                    }
                    
                    // 🔥 关键修复：在被分享的商家（子域名）自动注册用户账户
                    ruiyi_debug_log("🔵 [Registration] 检查子域名注册条件 - is_multisite: " . (is_multisite() ? 'true' : 'false') . ", shared_site_id: {$shared_site_id}");
                    
                    if (is_multisite() && $shared_site_id > 1) {
                        // 处理子域名注册
                    } else if ($shared_site_id == 1) {
                        ruiyi_debug_log("🔵 [Registration] 推荐码指向主域名(site_id=1)，跳过子域名注册，但确保短代码正确");
                    }
                    
                    // 🔥 无论是主域名还是子域名，都要确保短代码正确
                    if (is_multisite() && $shared_site_id > 1) {
                        ruiyi_debug_log("🔵 [Registration] 开始在子域名{$shared_site_id}创建用户账户");
                        try {
                            // 记录当前blog ID
                            $original_blog_id = get_current_blog_id();
                            
                            // 切换到被分享的商家站点
                            switch_to_blog($shared_site_id);
                            
                            // 检查用户是否已经在该站点存在
                            $existing_user = get_user_by('email', $email);
                            if (!$existing_user) {
                                // 在子域名创建用户账户（与主域名相同的信息）
                                $subsite_user_data = array(
                                    'user_login' => $username,
                                    'user_email' => $email,
                                    'user_pass' => $password, // 使用相同密码
                                    'first_name' => $first_name,
                                    'last_name' => $last_name,
                                    'display_name' => trim($first_name . ' ' . $last_name),
                                    'role' => 'customer'
                                );
                                
                                $subsite_user_id = wp_insert_user($subsite_user_data);
                                
                                if (!is_wp_error($subsite_user_id)) {
                                    // 🔥 在子域名为用户初始化积分和短代码（确保正确的站点上下文）
                                    $current_site_id = get_current_blog_id();
                                    
                                    // 初始化积分
                                    update_user_meta($subsite_user_id, "site_{$current_site_id}_user_points", 0);
                                    
                                    // 🔥 强制生成4位数字短代码，覆盖任何可能的8位代码
                                    if (function_exists('ruiyi_generate_unique_shortcode')) {
                                        // 生成正确的4位数字短代码
                                        $shortcode = ruiyi_generate_unique_shortcode($current_site_id);
                                        update_user_meta($subsite_user_id, "site_{$current_site_id}_user_shortcode", $shortcode);
                                        ruiyi_debug_log("🟢 [Registration] 在商家{$current_site_id}为用户{$subsite_user_id}生成短代码: {$shortcode}");
                                        
                                        // 🔥 额外验证：检查是否真的设置成功，如果不是4位数字则重新生成
                                        $verify_shortcode = get_user_meta($subsite_user_id, "site_{$current_site_id}_user_shortcode", true);
                                        if (!preg_match('/^\d{4}$/', $verify_shortcode)) {
                                            ruiyi_debug_log("🔴 [Registration] 检测到非4位数字短代码: {$verify_shortcode}，强制重新生成");
                                            
                                            // 强制重新生成并设置
                                            for ($retry = 0; $retry < 3; $retry++) {
                                                $force_shortcode = ruiyi_generate_unique_shortcode($current_site_id);
                                                update_user_meta($subsite_user_id, "site_{$current_site_id}_user_shortcode", $force_shortcode);
                                                
                                                // 再次验证
                                                $final_verify = get_user_meta($subsite_user_id, "site_{$current_site_id}_user_shortcode", true);
                                                if (preg_match('/^\d{4}$/', $final_verify)) {
                                                    ruiyi_debug_log("🟢 [Registration] 重新生成成功，最终短代码: {$final_verify}");
                                                    break;
                                                } else {
                                                    ruiyi_debug_log("🔴 [Registration] 重试#{$retry}失败，短代码仍为: {$final_verify}");
                                                }
                                            }
                                        }
                                    }
                                    
                                    ruiyi_debug_log("🟢 [Registration] 在商家{$shared_site_id}成功创建用户账户: {$subsite_user_id}");
                                } else {
                                    ruiyi_debug_log("🔴 [Registration] 在商家{$shared_site_id}创建用户失败: " . $subsite_user_id->get_error_message());
                                }
                            } else {
                                // 用户已存在，添加到该站点
                                add_user_to_blog($shared_site_id, $existing_user->ID, 'customer');
                                ruiyi_debug_log("🟢 [Registration] 用户已存在，添加到商家{$shared_site_id}: {$existing_user->ID}");
                                
                                // 🔥 关键修复：为已存在用户也强制生成正确的4位短代码
                                $current_site_id = get_current_blog_id();
                                $existing_user_id = $existing_user->ID;
                                
                                // 初始化积分（如果不存在）
                                $site_points_key = "site_{$current_site_id}_user_points";
                                if (get_user_meta($existing_user_id, $site_points_key, true) === '') {
                                    update_user_meta($existing_user_id, "site_{$current_site_id}_user_points", 0);
                                }
                                
                                // 🔥 强制生成4位数字短代码，覆盖任何可能的8位代码
                                if (function_exists('ruiyi_generate_unique_shortcode')) {
                                    // 生成正确的4位数字短代码
                                    $shortcode = ruiyi_generate_unique_shortcode($current_site_id);
                                    update_user_meta($existing_user_id, "site_{$current_site_id}_user_shortcode", $shortcode);
                                    ruiyi_debug_log("🟢 [Registration] 为已存在用户{$existing_user_id}在商家{$current_site_id}生成短代码: {$shortcode}");
                                    
                                    // 🔥 额外验证：检查是否真的设置成功，如果不是4位数字则重新生成
                                    $verify_shortcode = get_user_meta($existing_user_id, "site_{$current_site_id}_user_shortcode", true);
                                    if (!preg_match('/^\d{4}$/', $verify_shortcode)) {
                                        ruiyi_debug_log("🔴 [Registration] 检测到非4位数字短代码: {$verify_shortcode}，强制重新生成");
                                        
                                        // 强制重新生成并设置
                                        for ($retry = 0; $retry < 3; $retry++) {
                                            $force_shortcode = ruiyi_generate_unique_shortcode($current_site_id);
                                            update_user_meta($existing_user_id, "site_{$current_site_id}_user_shortcode", $force_shortcode);
                                            
                                            // 再次验证
                                            $final_verify = get_user_meta($existing_user_id, "site_{$current_site_id}_user_shortcode", true);
                                            if (preg_match('/^\d{4}$/', $final_verify)) {
                                                ruiyi_debug_log("🟢 [Registration] 重新生成成功，最终短代码: {$final_verify}");
                                                break;
                                            } else {
                                                ruiyi_debug_log("🔴 [Registration] 重试#{$retry}失败，短代码仍为: {$final_verify}");
                                            }
                                        }
                                    }
                                }
                            }
                            
                            // 恢复到原始blog
                            restore_current_blog();
                            
                        } catch (Exception $e) {
                            ruiyi_debug_log("🔴 [Registration] 在商家{$shared_site_id}注册用户时出错: " . $e->getMessage());
                            // 确保恢复blog
                            if ($original_blog_id != get_current_blog_id()) {
                                restore_current_blog();
                            }
                        }
                    }
                    
                    $auto_added_merchants = 1;
                    ruiyi_debug_log("🟢 [Registration] 自动添加商家: 用户{$user_id}获得了被分享的商家(站点ID: {$shared_site_id})，并在该商家注册了账户");
                } else {
                    ruiyi_debug_log("🔴 [Registration] 条件不满足，跳过商家添加 - 推荐人未在商家{$shared_site_id}中或数据异常");
                    ruiyi_debug_log("🔴 [Registration] 但仍然需要在子域名注册用户账户 - 开始强制子域名注册");
                }
                
                // 🔥 无论条件是否满足，都要确保用户在推荐码关联的子域名注册
                if (is_multisite() && $shared_site_id > 1) {
                    ruiyi_debug_log("🔵 [Registration] 开始在推荐码关联的子域名{$shared_site_id}创建用户账户");
                    
                    // 使用现有的扫码添加商家功能来确保用户在子域名注册
                    do_action('ruiyi_add_user_to_site', $user_id, $shared_site_id);
                    
                    // 设置用户的商家访问权限
                    $new_user_sites = array($shared_site_id);
                    update_user_meta($user_id, 'ruiyi_user_sites', $new_user_sites);
                    
                    $auto_added_merchants = 1;
                    ruiyi_debug_log("🟢 [Registration] 推荐码模式：用户{$user_id}已添加到商家{$shared_site_id}");
                }

                // 奖励双方100积分
                if (function_exists('ruiyi_update_user_points')) {
                    ruiyi_update_user_points($referrer_id, 100, '推荐新用户奖励 - 用户ID: ' . $user_id, 0, $site_id);
                    ruiyi_update_user_points($user_id, 100, '新用户注册奖励 - 推荐人ID: ' . $referrer_id, 0, $site_id);
                }

                // 标记推荐码为已使用
                $referral_data['status'] = 'used';
                $referral_data['used_by'] = $user_id;
                $referral_data['used_at'] = current_time('mysql');
                update_option('ruiyi_referral_' . $referral_code, $referral_data);

                ruiyi_debug_log("🟢 [Registration] 推荐关系建立成功 - 推荐人: {$referrer_id}, 新用户: {$user_id}");
            } catch (Exception $e) {
                ruiyi_debug_log("🔴 [Registration] 推荐关系建立失败: " . $e->getMessage());
            }
        }

        // 🔥 构建响应数据
        $response_data = array(
            'success' => true,
            'user_id' => $user_id,
            'message' => '注册成功',
            'custom_handler' => true,
            'handler_function' => 'custom_user_registration',
            'timestamp' => current_time('mysql')
        );

        // 🔥 修复：只要有推荐码被处理，就标记为已处理
        if ($referral_code && $referral_data) {
            $response_data['referral_processed'] = true;
            $response_data['referral_code'] = $referral_code;
            $response_data['referrer_id'] = $referral_data['referrer_id'];
            $response_data['shared_site_id'] = $referral_data['site_id'];
            
            if ($auto_added_merchants > 0) {
                $response_data['auto_added_merchants'] = $auto_added_merchants;
                $response_data['message'] = "用户注册成功，推荐关系已建立，自动添加了{$auto_added_merchants}个商家";
            } else {
                $response_data['message'] = "用户注册成功，推荐关系已建立";
            }
        }

        ruiyi_debug_log("🟢 [Registration] 注册完成，返回响应: " . json_encode($response_data));
        
        return new WP_REST_Response($response_data, 200);
        
    } catch (Exception $e) {
        ruiyi_debug_log("🔴 [Registration] 注册过程中发生异常: " . $e->getMessage());
        
        return new WP_Error(
            'registration_error',
            '注册过程中发生错误: ' . $e->getMessage(),
            array('status' => 500)
        );
    }
}

/**
 * 取消订单的AJAX处理函数
 */
function ruiyi_pos_cancel_order() {
    // 验证nonce
    if (!isset($_POST['nonce']) || !wp_verify_nonce($_POST['nonce'], 'ruiyi_pos_nonce')) {
        wp_send_json_error(['message' => '安全验证失败']);
        return;
    }
    
    // 获取订单ID
    if (!isset($_POST['order_id']) || empty($_POST['order_id'])) {
        wp_send_json_error(['message' => '缺少订单ID']);
        return;
    }
    
    $order_id = intval($_POST['order_id']);
    
    // 获取订单
    $order = wc_get_order($order_id);
    if (!$order) {
        wp_send_json_error(['message' => '订单不存在']);
        return;
    }
    
    try {
        // 检查订单状态，只有pending、processing、on-hold状态的订单可以取消
        $current_status = $order->get_status();
        $cancellable_statuses = ['pending', 'processing', 'on-hold'];
        
        if (!in_array($current_status, $cancellable_statuses)) {
            wp_send_json_error(['message' => "订单状态为 {$current_status}，无法取消"]);
            return;
        }
        
        // 更新订单状态为取消
        $order->update_status('cancelled', '订单因释放餐桌而被取消');
        
        // 记录日志
        ruiyi_debug_log("[ruiyi_pos_cancel_order] 订单 #{$order_id} 已取消，原因：释放餐桌");
        
        wp_send_json_success([
            'message' => "订单 #{$order_id} 已成功取消",
            'order_id' => $order_id
        ]);
        
    } catch (Exception $e) {
        ruiyi_debug_log("[ruiyi_pos_cancel_order] 取消订单时出错: " . $e->getMessage());
        wp_send_json_error(['message' => '取消订单时出错: ' . $e->getMessage()]);
    }
    
    wp_die();
}

// 注册AJAX处理函数
add_action('wp_ajax_ruiyi_pos_cancel_order', 'ruiyi_pos_cancel_order');
add_action('wp_ajax_nopriv_ruiyi_pos_cancel_order', 'ruiyi_pos_cancel_order');

// 添加餐桌状态概览数据获取AJAX处理函数
add_action('wp_ajax_ruiyi_get_table_overview_data', 'ruiyi_get_table_overview_data');

function ruiyi_get_table_overview_data() {
    check_ajax_referer('ruiyi_pos_nonce', 'nonce');
    
    // Allow administrators, shop managers, and POS users
    $user = wp_get_current_user();
    $allowed_roles = ['administrator', 'shop_manager', 'pos_user'];
    if (!is_user_logged_in() || !array_intersect($allowed_roles, $user->roles)) {
        wp_send_json_error(['message' => 'Insufficient permissions']);
        return;
    }
    
    global $wpdb;
    $pos_number_of_tables = get_option('pos_number_of_tables', 25);
    
    // 获取有未完成订单的餐桌 (使用正确的订单状态)
    $occupied_tables = $wpdb->get_results($wpdb->prepare("
        SELECT DISTINCT pm.meta_value as table_number, 
               COUNT(p.ID) as order_count,
               SUM(pm2.meta_value) as total_amount
        FROM {$wpdb->posts} p
        INNER JOIN {$wpdb->postmeta} pm ON p.ID = pm.post_id AND pm.meta_key = '_table_number'
        INNER JOIN {$wpdb->postmeta} pm2 ON p.ID = pm2.post_id AND pm2.meta_key = '_order_total'
        WHERE p.post_type = 'shop_order'
        AND p.post_status IN ('wc-processing', 'wc-on-hold')
        AND pm.meta_value != ''
        AND pm.meta_value != '0'
        GROUP BY pm.meta_value
    "));
    
    // 清理餐桌号数据 - 确保只返回数字
    foreach ($occupied_tables as $table) {
        $original_table_number = $table->table_number;
        
        // 如果餐桌号包含"Mesa"前缀，提取数字部分
        if (strpos($table->table_number, 'Mesa') !== false) {
            preg_match('/Mesa\s*(\d+)/i', $table->table_number, $matches);
            if (isset($matches[1])) {
                $table->table_number = $matches[1];
            }
        }
        
        // 提取所有数字字符
        $table->table_number = preg_replace('/\D/', '', $table->table_number);
        
        // 确保不为空且是有效数字
        if (empty($table->table_number) || !is_numeric($table->table_number)) {
            $table->table_number = '0'; // 默认值，稍后过滤掉
        }
        
    }
    
    // 过滤掉无效的餐桌号
    $occupied_tables = array_filter($occupied_tables, function($table) {
        return !empty($table->table_number) && $table->table_number !== '0' && is_numeric($table->table_number);
    });
    
    $occupied_count = count($occupied_tables);
    $available_count = $pos_number_of_tables - $occupied_count;
    $utilization_rate = $pos_number_of_tables > 0 ? ($occupied_count / $pos_number_of_tables) * 100 : 0;
    
    // 计算总收入
    $total_pending_revenue = 0;
    foreach ($occupied_tables as $table) {
        $total_pending_revenue += floatval($table->total_amount);
    }
    
    
    wp_send_json_success([
        'total_tables' => $pos_number_of_tables,
        'occupied_tables' => $occupied_count,
        'available_tables' => $available_count,
        'utilization_rate' => round($utilization_rate, 1),
        'total_pending_revenue' => $total_pending_revenue,
        'occupied_table_details' => $occupied_tables
    ]);
}

