    // 1. 生成推荐链接API
  add_action('rest_api_init', 'ruiyi_register_referral_endpoints');
  function ruiyi_register_referral_endpoints() {

      // 生成推荐码端点
      register_rest_route('ruiyi/v1', '/referral/generate', array(
          'methods' => 'POST',
          'callback' => 'ruiyi_generate_referral_link',
          'permission_callback' => 'ruiyi_referral_permission_check',
          'args' => array(
              'user_id' => array(
                  'required' => true,
                  'type' => 'integer'
              ),
              'site_id' => array(
                  'required' => true,
                  'type' => 'integer'
              )
          )
      ));

      // 验证推荐关系端点
      register_rest_route('ruiyi/v1', '/referral/verify', array(
          'methods' => 'POST',
          'callback' => 'ruiyi_verify_referral',
          'permission_callback' => 'ruiyi_referral_permission_check',
          'args' => array(
              'user_id' => array(
                  'required' => true,
                  'type' => 'integer'
              ),
              'referral_code' => array(
                  'required' => true,
                  'type' => 'string'
              )
          )
      ));

      // 获取推荐统计端点
      register_rest_route('ruiyi/v1', '/referral/stats/(?P<user_id>\d+)', array(
          'methods' => 'GET',
          'callback' => 'ruiyi_get_referral_stats',
          'permission_callback' => 'ruiyi_referral_permission_check'
      ));
  }

  // 2. 权限检查函数
  function ruiyi_referral_permission_check($request) {
      // 检查用户是否已登录或有有效的token
      if (is_user_logged_in()) {
          return true;
      }

      // 检查Authorization头部
      $auth_header = $request->get_header('authorization');
      if ($auth_header && strpos($auth_header, 'Bearer ') === 0) {
          $token = str_replace('Bearer ', '', $auth_header);
          // 这里应该验证JWT token，暂时简化处理
          return !empty($token);
      }

      return false;
  }

  // 3. 生成推荐链接函数
  function ruiyi_generate_referral_link($request) {
      $user_id = $request->get_param('user_id');
      $site_id = $request->get_param('site_id');

      try {
          // 生成6位唯一推荐码
          $referral_code = ruiyi_generate_unique_referral_code();
          ruiyi_debug_log("🔵 [Referral] 生成推荐码: " . $referral_code . " 用户ID: " . $user_id . " 站点ID: " . $site_id);

          // 保存推荐信息
          $referral_data = array(
              'referrer_id' => $user_id,
              'site_id' => $site_id,
              'created_at' => current_time('mysql'),
              'status' => 'active'
          );

          update_option('ruiyi_referral_' . $referral_code, $referral_data);

          // 记录用户的推荐码历史
          $user_referrals = get_user_meta($user_id, 'ruiyi_referral_codes', true);
          if (!is_array($user_referrals)) {
              $user_referrals = array();
          }
          $user_referrals[] = array(
              'code' => $referral_code,
              'site_id' => $site_id,
              'created_at' => current_time('mysql')
          );
          update_user_meta($user_id, 'ruiyi_referral_codes', $user_referrals);

          // 返回推荐链接
          $referral_link = home_url('r/' . $referral_code);

          ruiyi_debug_log("🟢 [Referral] 返回数据 - 推荐码: " . $referral_code . " 链接: " . $referral_link);

          return new WP_REST_Response(array(
              'success' => true,
              'data' => array(
                  'referral_code' => $referral_code,
                  'referral_link' => $referral_link,
                  'qr_data' => $referral_link // 用于生成二维码
              )
          ), 200);

      } catch (Exception $e) {
          return new WP_REST_Response(array(
              'success' => false,
              'message' => '生成推荐链接失败: ' . $e->getMessage()
          ), 500);
      }
  }

  // 4. 验证推荐关系函数
  function ruiyi_verify_referral($request) {
      $new_user_id = $request->get_param('user_id');
      $referral_code = $request->get_param('referral_code');

      try {
          // 获取推荐信息
          $referral_data = get_option('ruiyi_referral_' . $referral_code);

          if (!$referral_data || $referral_data['status'] !== 'active') {
              return new WP_REST_Response(array(
                  'success' => false,
                  'message' => '无效的推荐码'
              ), 400);
          }

          $referrer_id = $referral_data['referrer_id'];
          $site_id = $referral_data['site_id'];

          // 检查用户是否已经有推荐人
          $existing_referrer = get_user_meta($new_user_id, 'referred_by', true);
          if ($existing_referrer) {
              return new WP_REST_Response(array(
                  'success' => false,
                  'message' => '用户已经有推荐人'
              ), 400);
          }

          // 不能推荐自己
          if ($referrer_id == $new_user_id) {
              return new WP_REST_Response(array(
                  'success' => false,
                  'message' => '不能推荐自己'
              ), 400);
          }

          // 建立推荐关系
          add_user_meta($new_user_id, 'referred_by', $referrer_id);
          add_user_meta($new_user_id, 'referral_site', $site_id);
          add_user_meta($new_user_id, 'referral_code_used', $referral_code);
          add_user_meta($new_user_id, 'referral_date', current_time('mysql'));

          // 更新推荐人的下级列表
          $referrer_referrals = get_user_meta($referrer_id, 'ruiyi_my_referrals', true);
          if (!is_array($referrer_referrals)) {
              $referrer_referrals = array();
          }
          $referrer_referrals[] = array(
              'user_id' => $new_user_id,
              'site_id' => $site_id,
              'referral_code' => $referral_code,
              'date' => current_time('mysql')
          );
          update_user_meta($referrer_id, 'ruiyi_my_referrals', $referrer_referrals);

          // 🔥 修复：只添加被分享的特定商家，而不是推荐人的所有商家
          if (in_array($site_id, get_user_meta($referrer_id, 'ruiyi_user_sites', true) ?: [])) {
              // 只添加被分享的特定商家
              $new_user_sites = array($site_id);
              update_user_meta($new_user_id, 'ruiyi_user_sites', $new_user_sites);
              
              // 只复制被分享商家的WooCommerce信息
              $referrer_woocommerce_sites = get_user_meta($referrer_id, 'ruiyi_user_woocommerce_sites', true);
              if (!empty($referrer_woocommerce_sites) && isset($referrer_woocommerce_sites[$site_id])) {
                  $new_user_woocommerce_sites = array(
                      $site_id => $referrer_woocommerce_sites[$site_id]
                  );
                  update_user_meta($new_user_id, 'ruiyi_user_woocommerce_sites', $new_user_woocommerce_sites);
              }
              
              ruiyi_debug_log("🟢 [Referral] 自动添加商家: 用户{$new_user_id}获得了推荐人{$referrer_id}分享的商家(站点ID: {$site_id})");
          }

          // 奖励双方100积分
          if (function_exists('ruiyi_update_user_points')) {
              // 奖励推荐人
              ruiyi_update_user_points($referrer_id, 100, '推荐新用户奖励 - 用户ID: ' . $new_user_id, 0, $site_id);

              // 奖励新用户
              ruiyi_update_user_points($new_user_id, 100, '新用户注册奖励 - 推荐人ID: ' . $referrer_id, 0, $site_id);
          }

          // 标记推荐码为已使用
          $referral_data['status'] = 'used';
          $referral_data['used_by'] = $new_user_id;
          $referral_data['used_at'] = current_time('mysql');
          update_option('ruiyi_referral_' . $referral_code, $referral_data);

          // 计算自动添加的商家数量
          $auto_added_merchants = 0;
          if (!empty($referrer_sites) && is_array($referrer_sites)) {
              $auto_added_merchants = count($referrer_sites);
          }

          return new WP_REST_Response(array(
              'success' => true,
              'data' => array(
                  'referrer_id' => $referrer_id,
                  'site_id' => $site_id,
                  'reward_points' => 100,
                  'auto_added_merchants' => $auto_added_merchants,
                  'message' => $auto_added_merchants > 0 ?
                      "推荐关系建立成功，双方各获得100积分，自动添加了{$auto_added_merchants}个商家" :
                      '推荐关系建立成功，双方各获得100积分'
              )
          ), 200);

      } catch (Exception $e) {
          return new WP_REST_Response(array(
              'success' => false,
              'message' => '验证推荐关系失败: ' . $e->getMessage()
          ), 500);
      }
  }

  // 5. 获取推荐统计函数
  function ruiyi_get_referral_stats($request) {
      $user_id = $request->get_param('user_id');

      try {
          // 获取用户推荐的人数
          $my_referrals = get_user_meta($user_id, 'ruiyi_my_referrals', true);
          if (!is_array($my_referrals)) {
              $my_referrals = array();
          }

          // 获取用户生成的推荐码
          $referral_codes = get_user_meta($user_id, 'ruiyi_referral_codes', true);
          if (!is_array($referral_codes)) {
              $referral_codes = array();
          }

          // 统计总点击数
          $total_clicks = 0;
          foreach ($referral_codes as $code_info) {
              $clicks = get_option('ruiyi_referral_clicks_' . $code_info['code'], array());
              $total_clicks += count($clicks);
          }

          return new WP_REST_Response(array(
              'success' => true,
              'data' => array(
                  'total_referrals' => count($my_referrals),
                  'total_codes_generated' => count($referral_codes),
                  'total_clicks' => $total_clicks,
                  'recent_referrals' => array_slice($my_referrals, -5), // 最近5个推荐
                  'referrer_id' => get_user_meta($user_id, 'referred_by', true) ?: null
              )
          ), 200);

      } catch (Exception $e) {
          return new WP_REST_Response(array(
              'success' => false,
              'message' => '获取推荐统计失败: ' . $e->getMessage()
          ), 500);
      }
  }

  // 6. 生成唯一推荐码函数
  function ruiyi_generate_unique_referral_code() {
      do {
          // 生成6位随机字符串（大写字母+数字）
          $characters = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
          $code = '';
          for ($i = 0; $i < 6; $i++) {
              $code .= $characters[rand(0, strlen($characters) - 1)];
          }
      } while (get_option('ruiyi_referral_' . $code)); // 确保唯一性

      return $code;
  }

