  /**
   * RUIYI推荐系统 - 积分分成机制
   * 第三阶段：下级消费时上级自动获得积分分成
   */

  // 1. 修改现有的积分奖励函数，添加推荐分成逻辑
  function ruiyi_reward_points_with_referral_commission($user_id, $points, $description = '', $operator_id = 0, $site_id = null) {
      // 先给用户本人奖励积分
      $new_points = ruiyi_update_user_points($user_id, $points, $description, $operator_id, $site_id);

      // 检查该用户是否有推荐人
      $referrer_id = get_user_meta($user_id, 'referred_by', true);

      if ($referrer_id && $referrer_id != $user_id) {
          // 给推荐人相同的积分作为分成
          $commission_description = "下级用户消费分成 - 用户ID: {$user_id} - 原因: {$description}";
          ruiyi_update_user_points($referrer_id, $points, $commission_description, $operator_id, $site_id);

          // 记录分成日志
          ruiyi_debug_log("RUIYI Referral Commission: User {$referrer_id} got {$points} points from referral {$user_id}");

          // 可选：发送通知给推荐人（如果有通知系统）
          do_action('ruiyi_referral_commission_awarded', $referrer_id, $user_id, $points, $site_id);
      }

      return $new_points;
  }

  // 2. Hook到现有的积分奖励系统 - 已移除，使用新的 ruiyi_distribute_referral_commission 函数
  // add_action('ruiyi_points_awarded', 'ruiyi_handle_referral_commission', 10, 5);

  // 3. 记录推荐分成历史
  function ruiyi_record_referral_commission($referrer_id, $referred_id, $points, $original_description, $site_id) {
      $commission_history = get_user_meta($referrer_id, 'ruiyi_referral_commissions', true);
      if (!is_array($commission_history)) {
          $commission_history = array();
      }

      $commission_record = array(
          'referred_user_id' => $referred_id,
          'points' => $points,
          'original_description' => $original_description,
          'site_id' => $site_id,
          'date' => current_time('mysql')
      );

      $commission_history[] = $commission_record;

      // 只保留最近100条记录
      if (count($commission_history) > 100) {
          $commission_history = array_slice($commission_history, -100);
      }

      update_user_meta($referrer_id, 'ruiyi_referral_commissions', $commission_history);
  }

  // 4. 修改现有的AJAX奖励积分函数
  add_action('wp_ajax_ruiyi_reward_points_v2', 'ruiyi_reward_points_ajax_v2');
  add_action('wp_ajax_nopriv_ruiyi_reward_points_v2', 'ruiyi_reward_points_ajax_v2');
  function ruiyi_reward_points_ajax_v2() {
      // 验证nonce
      if (!wp_verify_nonce($_POST['nonce'], 'ruiyi_pos_nonce')) {
          wp_die('安全验证失败');
      }

      $user_id = intval($_POST['user_id']);
      $points = intval($_POST['points']);
      $order_total = floatval($_POST['order_total']);
      $site_id = isset($_POST['site_id']) ? intval($_POST['site_id']) : null;

      if (!$user_id || $points <= 0) {
          wp_send_json_error('无效的参数');
      }

      try {
          // 给用户奖励积分
          $description = "消费奖励积分 - 消费金额: €{$order_total}";
          $new_balance = ruiyi_update_user_points($user_id, $points, $description, get_current_user_id(), $site_id);

          // 触发分成机制
          do_action('ruiyi_points_awarded', $user_id, $points, $description, get_current_user_id(), $site_id);

          wp_send_json_success(array(
              'message' => "成功奖励 {$points} 积分",
              'new_balance' => $new_balance,
              'user_id' => $user_id
          ));

      } catch (Exception $e) {
          wp_send_json_error('奖励积分失败: ' . $e->getMessage());
      }
  }

  // 5. 添加API端点获取推荐分成历史
  add_action('rest_api_init', 'ruiyi_register_commission_endpoints');
  function ruiyi_register_commission_endpoints() {
      // 获取推荐分成历史
      register_rest_route('ruiyi/v1', '/referral/commissions/(?P<user_id>\d+)', array(
          'methods' => 'GET',
          'callback' => 'ruiyi_get_referral_commissions',
          'permission_callback' => 'ruiyi_referral_permission_check'
      ));
  }

  function ruiyi_get_referral_commissions($request) {
      $user_id = $request->get_param('user_id');

      try {
          // 获取分成历史
          $commission_history = get_user_meta($user_id, 'ruiyi_referral_commissions', true);
          if (!is_array($commission_history)) {
              $commission_history = array();
          }

          // 计算总分成积分
          $total_commission_points = 0;
          foreach ($commission_history as $record) {
              $total_commission_points += $record['points'];
          }

          // 获取下级用户列表
          $my_referrals = get_user_meta($user_id, 'ruiyi_my_referrals', true);
          if (!is_array($my_referrals)) {
              $my_referrals = array();
          }

          return new WP_REST_Response(array(
              'success' => true,
              'data' => array(
                  'total_commission_points' => $total_commission_points,
                  'total_referrals' => count($my_referrals),
                  'recent_commissions' => array_slice($commission_history, -20), // 最近20条
                  'commission_history' => $commission_history
              )
          ), 200);

      } catch (Exception $e) {
          return new WP_REST_Response(array(
              'success' => false,
              'message' => '获取分成历史失败: ' . $e->getMessage()
          ), 500);
      }
  }

  // 6. 在POS系统中集成分成机制（修改现有的POS积分奖励）
  add_filter('ruiyi_pos_reward_points', 'ruiyi_pos_reward_with_commission', 10, 4);
  function ruiyi_pos_reward_with_commission($points, $user_id, $order_total, $site_id) {
      // 这个函数会在POS系统奖励积分时自动调用
      $description = "POS消费奖励 - 订单金额: €{$order_total}";

      // 奖励用户积分
      ruiyi_update_user_points($user_id, $points, $description, 0, $site_id);

      // 自动触发分成
      do_action('ruiyi_points_awarded', $user_id, $points, $description, 0, $site_id);

      return $points;
  }

  // 7. 添加管理后台查看分成统计
  add_action('wp_ajax_ruiyi_get_commission_stats', 'ruiyi_get_commission_stats_ajax');
  function ruiyi_get_commission_stats_ajax() {
      if (!current_user_can('manage_options')) {
          wp_die('权限不足');
      }

      global $wpdb;

      // 获取所有有推荐关系的用户
      $users_with_referrals = $wpdb->get_results(
          "SELECT DISTINCT meta_value as referrer_id, COUNT(*) as referral_count
           FROM {$wpdb->usermeta}
           WHERE meta_key = 'referred_by'
           GROUP BY meta_value"
      );

      $stats = array();
      foreach ($users_with_referrals as $referrer) {
          $commissions = get_user_meta($referrer->referrer_id, 'ruiyi_referral_commissions', true);
          $total_commission = 0;

          if (is_array($commissions)) {
              foreach ($commissions as $commission) {
                  $total_commission += $commission['points'];
              }
          }

          $user = get_user_by('id', $referrer->referrer_id);
          $stats[] = array(
              'user_id' => $referrer->referrer_id,
              'username' => $user ? $user->user_login : 'Unknown',
              'referral_count' => $referrer->referral_count,
              'total_commission' => $total_commission
          );
      }

      wp_send_json_success($stats);
  }

