  /**
   * 测试完整的推荐流程
   */
  function ruiyi_test_full_referral_flow() {
      try {
          // 1. 创建测试用户A（推荐人）
          $userA_data = array(
              'user_login' => 'test_referrer_' . time(),
              'user_email' => 'referrer_' . time() . '@test.com',
              'user_pass' => 'test123456',
              'first_name' => 'Test',
              'last_name' => 'Referrer'
          );
          $userA_id = wp_insert_user($userA_data);
          if (is_wp_error($userA_id)) {
              return array('success' => false, 'message' => '创建测试用户A失败: ' . $userA_id->get_error_message());
          }

          // 2. 为用户A添加一些测试商家
          update_user_meta($userA_id, 'ruiyi_user_sites', array(1, 2));
          update_user_meta($userA_id, 'ruiyi_user_woocommerce_sites', array(
              1 => array('consumer_key' => 'test_key1', 'consumer_secret' => 'test_secret1', 'is_woocommerce_enabled' => true),
              2 => array('consumer_key' => 'test_key2', 'consumer_secret' => 'test_secret2', 'is_woocommerce_enabled' => true)
          ));

          // 3. 生成推荐码
          $referral_code = ruiyi_generate_unique_referral_code();
          $referral_data = array(
              'referrer_id' => $userA_id,
              'site_id' => 1,
              'created_at' => current_time('mysql'),
              'status' => 'active'
          );
          update_option('ruiyi_referral_' . $referral_code, $referral_data);

          // 4. 模拟用户B注册（使用推荐码）
          $userB_data = array(
              'user_login' => 'test_referred_' . time(),
              'user_email' => 'referred_' . time() . '@test.com',
              'user_pass' => 'test123456',
              'first_name' => 'Test',
              'last_name' => 'Referred'
          );
          $userB_id = wp_insert_user($userB_data);
          if (is_wp_error($userB_id)) {
              return array('success' => false, 'message' => '创建测试用户B失败: ' . $userB_id->get_error_message());
          }

          // 5. 建立推荐关系（模拟注册API的逻辑）
          add_user_meta($userB_id, 'referred_by', $userA_id);
          add_user_meta($userB_id, 'referral_site', 1);
          add_user_meta($userB_id, 'referral_code_used', $referral_code);
          add_user_meta($userB_id, 'referral_date', current_time('mysql'));

          // 6. 自动添加被分享的特定商家（模拟推荐码只分享站点1）
          $shared_site_id = 1; // 假设分享的是站点1
          $new_user_sites = array($shared_site_id);
          update_user_meta($userB_id, 'ruiyi_user_sites', $new_user_sites);
          
          // 只复制被分享商家的WooCommerce信息
          $referrer_woocommerce_sites = get_user_meta($userA_id, 'ruiyi_user_woocommerce_sites', true);
          if (!empty($referrer_woocommerce_sites) && isset($referrer_woocommerce_sites[$shared_site_id])) {
              $new_user_woocommerce_sites = array(
                  $shared_site_id => $referrer_woocommerce_sites[$shared_site_id]
              );
              update_user_meta($userB_id, 'ruiyi_user_woocommerce_sites', $new_user_woocommerce_sites);
          }

          // 7. 奖励注册积分
          ruiyi_update_user_points($userA_id, 100, '推荐新用户奖励 - 用户ID: ' . $userB_id, 0, 1);
          ruiyi_update_user_points($userB_id, 100, '新用户注册奖励 - 推荐人ID: ' . $userA_id, 0, 1);

          // 8. 测试积分分成机制
          ruiyi_update_user_points($userB_id, 50, 'POS消费奖励测试', 0, 1);

          // 9. 验证结果
          $userB_referrer = get_user_meta($userB_id, 'referred_by', true);
          $userB_sites = get_user_meta($userB_id, 'ruiyi_user_sites', true);
          $userA_points = ruiyi_get_user_points_for_site($userA_id, 1);
          $userB_points = ruiyi_get_user_points_for_site($userB_id, 1);

          if ($userB_referrer != $userA_id) {
              return array('success' => false, 'message' => '推荐关系建立失败');
          }

          if (count($userB_sites) !== 1 || !in_array($shared_site_id, $userB_sites)) {
              return array('success' => false, 'message' => '商家自动添加失败 - 期望只有1个被分享的商家');
          }

          // 用户A应该有：100（推荐奖励）+ 50（分成）= 150积分
          // 用户B应该有：100（注册奖励）+ 50（消费奖励）= 150积分
          if ($userA_points < 150 || $userB_points < 150) {
              return array('success' => false, 'message' => "积分分成测试失败 - 用户A积分: {$userA_points}, 用户B积分: {$userB_points}");
          }

          // 清理测试数据
          wp_delete_user($userA_id);
          wp_delete_user($userB_id);
          delete_option('ruiyi_referral_' . $referral_code);

          return array(
              'success' => true,
              'message' => "推荐系统测试成功！✅ 推荐关系建立 ✅ 商家自动添加 ✅ 积分分成机制正常 (用户A: {$userA_points}积分, 用户B: {$userB_points}积分)"
          );

      } catch (Exception $e) {
          return array('success' => false, 'message' => '测试过程中发生错误: ' . $e->getMessage());
      }
  }

  /**
   * 显示推荐关系统计
   */
  function ruiyi_display_referral_stats() {
      global $wpdb;
      
      // 获取所有推荐关系
      $referral_relationships = $wpdb->get_results(
          "SELECT meta_value as referrer_id, COUNT(*) as referral_count
           FROM {$wpdb->usermeta}
           WHERE meta_key = 'referred_by'
           GROUP BY meta_value
           ORDER BY referral_count DESC
           LIMIT 10"
      );

      if (empty($referral_relationships)) {
          echo '<p>暂无推荐关系数据</p>';
          return;
      }

      echo '<table class="widefat fixed striped">';
      echo '<thead><tr><th>推荐人</th><th>推荐人数</th><th>总分成积分</th></tr></thead>';
      echo '<tbody>';

      foreach ($referral_relationships as $relationship) {
          $referrer = get_user_by('id', $relationship->referrer_id);
          $commission_history = get_user_meta($relationship->referrer_id, 'ruiyi_referral_commissions', true);
          $total_commission = 0;
          
          if (is_array($commission_history)) {
              foreach ($commission_history as $commission) {
                  $total_commission += $commission['points'];
              }
          }

          echo '<tr>';
          echo '<td>' . ($referrer ? $referrer->display_name . ' (' . $referrer->user_email . ')' : 'Unknown User') . '</td>';
          echo '<td>' . $relationship->referral_count . '</td>';
          echo '<td>' . $total_commission . '</td>';
          echo '</tr>';
      }

      echo '</tbody></table>';
  }

// 🔥 推荐链接处理系统
add_action('init', 'ruiyi_add_referral_rewrite_rules');
add_filter('query_vars', 'ruiyi_add_referral_query_vars');
add_action('template_redirect', 'ruiyi_handle_referral_link');

// 推荐链接重写规则已整合到现有的 ruiyi_flush_rewrite_rules 函数中

/**
 * 添加推荐链接的URL重写规则
 */
function ruiyi_add_referral_rewrite_rules() {
    add_rewrite_rule('^r/([A-Z0-9]{6})/?$', 'index.php?referral_code=$matches[1]', 'top');
    add_rewrite_rule('^app-download/?$', 'index.php?app_download=1', 'top');
}

/**
 * 添加推荐码查询变量
 */
function ruiyi_add_referral_query_vars($vars) {
    $vars[] = 'referral_code';
    $vars[] = 'app_download';
    return $vars;
}

/**
 * 处理推荐链接访问
 */
function ruiyi_handle_referral_link() {
    // 🔥 移除应用下载页面处理，因为现在直接下载APK
    // if (get_query_var('app_download')) {
    //     ruiyi_display_app_download_page();
    //     exit;
    // }
    
    $referral_code = get_query_var('referral_code');
    
    if ($referral_code) {
        ruiyi_debug_log("🔵 [Referral Link] 用户访问推荐链接 - 推荐码: {$referral_code}");
        
        // 验证推荐码是否有效
        $referral_data = get_option('ruiyi_referral_' . $referral_code);
        if (!$referral_data || $referral_data['status'] !== 'active') {
            ruiyi_debug_log("🔴 [Referral Link] 无效的推荐码: {$referral_code}");
            wp_redirect(home_url());
            exit;
        }
        
        // 将推荐码保存到cookie中（7天有效期）
        setcookie('ruiyi_referral_code', $referral_code, time() + (7 * 24 * 60 * 60), '/');
        
        ruiyi_debug_log("🟢 [Referral Link] 推荐码已保存到cookie: {$referral_code}");
        
        // 🔥 移动设备直接下载APK，不显示任何页面
        if (wp_is_mobile()) {
            ruiyi_debug_log("🔵 [Referral Link] 移动设备检测，直接下载APK");
            
            // 直接重定向到APK下载
            $apk_download_url = 'https://ruiyipos.es/wp-content/uploads/apps/app-release.apk';
            ruiyi_debug_log("🟢 [Referral Link] 重定向到APK下载: {$apk_download_url}");
            
            wp_redirect($apk_download_url);
        } else {
            // 桌面设备显示二维码页面
            ruiyi_debug_log("🔵 [Referral Link] 桌面设备检测，显示二维码页面");
            ruiyi_display_referral_landing_page($referral_code, $referral_data);
        }
        exit;
    }
}

