// 🔥 推荐分成机制 - 监听积分奖励事件
add_action('ruiyi_points_awarded', 'ruiyi_distribute_referral_commission', 10, 5);

/**
 * 分发推荐分成
 *
 * @param int $user_id 获得积分的用户ID
 * @param int $points_awarded 获得的积分数量
 * @param string $description 积分描述
 * @param int $operator_id 操作者ID
 * @param int $site_id 站点ID
 */
function ruiyi_distribute_referral_commission($user_id, $points_awarded, $description, $operator_id, $site_id) {
    // 🔥 使用静态变量防止同一次调用中的重复分成
    static $processing_commissions = array();
    $commission_key = "{$user_id}_{$points_awarded}_{$site_id}_" . md5($description);
    
    if (isset($processing_commissions[$commission_key])) {
        ruiyi_debug_log("🟡 [Commission] 检测到重复分成调用，跳过: {$commission_key}");
        return;
    }
    
    $processing_commissions[$commission_key] = true;
    
    ruiyi_debug_log("🔵 [Commission] 积分分成触发 - 用户: {$user_id}, 积分: {$points_awarded}, 站点: {$site_id}, 描述: {$description}");
    
    // 🔥 防止分成死循环：如果描述包含"推荐分成"，说明这是分成积分，不应该再次分成
    if (strpos($description, '推荐分成') !== false) {
        ruiyi_debug_log("🟡 [Commission] 检测到分成积分，防止死循环，跳过分成");
        unset($processing_commissions[$commission_key]);
        return;
    }
    
    // 检查该用户是否有推荐人
    $referrer_id = get_user_meta($user_id, 'referred_by', true);
    if (!$referrer_id) {
        ruiyi_debug_log("🟡 [Commission] 用户{$user_id}没有推荐人，跳过分成");
        unset($processing_commissions[$commission_key]);
        return;
    }
    
    // 🔥 关键修复：验证用户消费的站点是否与推荐关系中的站点匹配
    $referral_site = get_user_meta($user_id, 'referral_site', true);
    if ($referral_site && $referral_site != $site_id) {
        ruiyi_debug_log("🟡 [Commission] 用户{$user_id}在站点{$site_id}消费，但推荐关系来自站点{$referral_site}，不匹配，跳过分成");
        unset($processing_commissions[$commission_key]);
        return;
    }
    
    if (!$referral_site) {
        ruiyi_debug_log("🟡 [Commission] 用户{$user_id}没有记录推荐来源站点，跳过分成");
        unset($processing_commissions[$commission_key]);
        return;
    }
    
    ruiyi_debug_log("🟢 [Commission] 站点验证通过 - 用户{$user_id}在被分享的站点{$site_id}消费，可以分成");
    
    // 计算分成积分（100%分成）
    $commission_points = $points_awarded;
    
    ruiyi_debug_log("🔵 [Commission] 开始分成 - 推荐人: {$referrer_id}, 分成积分: {$commission_points}");
    
    // 🔥 修复：分成积分应该发放到推荐人在被分享商家站点的账户
    // 需要切换到被分享商家的站点，确保推荐人在该站点有账户
    $original_site_id = get_current_blog_id();
    
    if (is_multisite() && $site_id != $original_site_id) {
        switch_to_blog($site_id);
        ruiyi_debug_log("🔄 [Commission] 切换到被分享商家站点: {$site_id}");
    }
    
    // 检查推荐人是否在被分享商家站点有账户
    $referrer_in_site = get_user_by('id', $referrer_id);
    if (!$referrer_in_site || !is_user_member_of_blog($referrer_id, $site_id)) {
        ruiyi_debug_log("🟡 [Commission] 推荐人{$referrer_id}在被分享商家站点{$site_id}没有账户，尝试自动添加");
        
        // 🔥 自动为推荐人在被分享商家站点创建账户
        if ($referrer_in_site) {
            // 推荐人存在，但不在该站点，添加到该站点
            $add_result = add_user_to_blog($site_id, $referrer_id, 'customer');
            if ($add_result) {
                ruiyi_debug_log("🟢 [Commission] 成功将推荐人{$referrer_id}添加到商家站点{$site_id}");
                
                // 初始化推荐人在该站点的积分和短代码
                $current_site_id = get_current_blog_id();
                
                // 初始化积分
                if (get_user_meta($referrer_id, "site_{$current_site_id}_user_points", true) === '') {
                    update_user_meta($referrer_id, "site_{$current_site_id}_user_points", 0);
                }
                
                // 生成短代码
                if (function_exists('ruiyi_generate_unique_shortcode')) {
                    $shortcode = ruiyi_generate_unique_shortcode($current_site_id);
                    update_user_meta($referrer_id, "site_{$current_site_id}_user_shortcode", $shortcode);
                    ruiyi_debug_log("🟢 [Commission] 为推荐人{$referrer_id}在商家{$current_site_id}生成短代码: {$shortcode}");
                }
            } else {
                ruiyi_debug_log("🔴 [Commission] 无法将推荐人{$referrer_id}添加到商家站点{$site_id}，跳过分成");
                if (is_multisite() && $site_id != $original_site_id) {
                    restore_current_blog();
                }
                unset($processing_commissions[$commission_key]);
                return;
            }
        } else {
            ruiyi_debug_log("🔴 [Commission] 推荐人{$referrer_id}账户不存在，无法分成");
            if (is_multisite() && $site_id != $original_site_id) {
                restore_current_blog();
            }
            unset($processing_commissions[$commission_key]);
            return;
        }
    }
    
    // 给推荐人奖励分成积分（在被分享商家站点）
    if (function_exists('ruiyi_update_user_points')) {
        $commission_description = "推荐分成 - 下级用户{$user_id}获得{$points_awarded}积分";
        ruiyi_update_user_points($referrer_id, $commission_points, $commission_description, 0, $site_id);
        
        ruiyi_debug_log("🟢 [Commission] 分成成功 - 推荐人{$referrer_id}在站点{$site_id}获得{$commission_points}积分");
        
        // 记录分成历史
        $commission_history = get_user_meta($referrer_id, 'ruiyi_referral_commissions', true);
        if (!is_array($commission_history)) {
            $commission_history = array();
        }
        
        $commission_history[] = array(
            'referred_user_id' => $user_id,
            'points' => $commission_points,
            'description' => $commission_description,
            'site_id' => $site_id,
            'created_at' => current_time('mysql')
        );
        
        update_user_meta($referrer_id, 'ruiyi_referral_commissions', $commission_history);
    } else {
        ruiyi_debug_log("🔴 [Commission] ruiyi_update_user_points 函数不存在");
    }
    
    // 恢复原始站点
    if (is_multisite() && $site_id != $original_site_id) {
        restore_current_blog();
        ruiyi_debug_log("🔄 [Commission] 恢复到原始站点: {$original_site_id}");
    }
    
    // 清理静态变量
    unset($processing_commissions[$commission_key]);
}

// 为管理员用户移除管理栏中的特定项目（排除特定用户）
function remove_admin_bar_items_for_administrators() {
    // 获取当前用户
    $current_user = wp_get_current_user();
    
    // 检查是否为管理员且不是被排除的用户
    if (current_user_can('administrator') && $current_user->user_email !== 'jchenhan54@gmail.com') {
        global $wp_admin_bar;
        
        // 移除站点名称/查看站点链接
        $wp_admin_bar->remove_node('site-name');
        
        // 移除"我的站点"菜单（多站点环境）
        $wp_admin_bar->remove_node('my-sites');
        
        // 移除"网络管理员"相关项目
        $wp_admin_bar->remove_node('network-admin');
        
        // 移除WordPress logo
        $wp_admin_bar->remove_node('wp-logo');
        
        // 移除评论
        $wp_admin_bar->remove_node('comments');
        
        // 移除新建内容
        $wp_admin_bar->remove_node('new-content');
    }
}
add_action('wp_before_admin_bar_render', 'remove_admin_bar_items_for_administrators');

// 为管理员用户移除"已上线"按钮（排除特定用户）
function remove_online_status_for_administrators() {
    // 获取当前用户
    $current_user = wp_get_current_user();
    
    // 检查是否为管理员且不是被排除的用户
