/**
 * Hide admin bar for shop managers completely
 */
function ruiyi_pos_hide_admin_bar_for_shop_managers() {
    // Hide admin bar for shop managers since they can't access wp-admin
    if (current_user_can('shop_manager') && !current_user_can('administrator') && !current_user_can('pos_manager')) {
        show_admin_bar(false);
    }
}
add_action('wp', 'ruiyi_pos_hide_admin_bar_for_shop_managers');

/**
 * Remove admin access capabilities from shop_manager role
 */
function ruiyi_pos_restrict_shop_manager_capabilities() {
    // Get the shop_manager role
    $shop_manager = get_role('shop_manager');
    
    if ($shop_manager) {
        // Remove capabilities that allow admin access
        $shop_manager->remove_cap('edit_dashboard');
        $shop_manager->remove_cap('manage_options');
        $shop_manager->remove_cap('switch_themes');
        $shop_manager->remove_cap('edit_themes');
        $shop_manager->remove_cap('activate_plugins');
        $shop_manager->remove_cap('edit_plugins');
        $shop_manager->remove_cap('edit_users');
        $shop_manager->remove_cap('list_users');
        $shop_manager->remove_cap('promote_users');
        $shop_manager->remove_cap('create_users');
        $shop_manager->remove_cap('delete_users');
        $shop_manager->remove_cap('unfiltered_html');
        $shop_manager->remove_cap('manage_categories');
        $shop_manager->remove_cap('manage_links');
        $shop_manager->remove_cap('upload_files');
        $shop_manager->remove_cap('import');
        $shop_manager->remove_cap('unfiltered_upload');
    }
}
add_action('init', 'ruiyi_pos_restrict_shop_manager_capabilities');

/**
 * Force redirect shop managers from admin - multiple hooks for safety
 */
function ruiyi_pos_force_block_shop_manager_admin() {
    if (!is_user_logged_in()) {
        return;
    }
    
    $current_user = wp_get_current_user();
    
    // Check if we're in admin area and not doing AJAX
    if (is_admin() && !(defined('DOING_AJAX') && DOING_AJAX)) {
        // Block shop_manager specifically
        if (in_array('shop_manager', $current_user->roles)) {
            wp_redirect( home_url('/pos-login/') );
            exit;
        }
        
        // Block users who only have shop_manager capabilities but aren't admin or pos_manager
        if (current_user_can('shop_manager') &&
            !current_user_can('administrator') &&
            !current_user_can('pos_manager') &&
            $current_user->user_email !== 'jchenhan54@gmail.com') {
            wp_redirect( home_url('/pos-login/') );
            exit;
        }
    }
}
add_action('wp_loaded', 'ruiyi_pos_force_block_shop_manager_admin', 1);
add_action('admin_init', 'ruiyi_pos_force_block_shop_manager_admin', 1);

/**
 * Block shop_manager from accessing admin via template_redirect (earliest possible)
 */
function ruiyi_pos_template_redirect_shop_manager() {
    if (!is_user_logged_in()) {
        return;
    }
    
    $current_user = wp_get_current_user();
    
    // Check if user is trying to access admin area
    if (is_admin() && !(defined('DOING_AJAX') && DOING_AJAX)) {
        // Block shop_manager role specifically
        if (in_array('shop_manager', $current_user->roles)) {
            wp_redirect( home_url('/pos-login/') );
            exit;
        }
    }
}
add_action('template_redirect', 'ruiyi_pos_template_redirect_shop_manager', 1);

/**
 * ========================================
 * 分单结账功能的AJAX处理函数
 * ========================================
 */



// 处理分单订单支付
add_action('wp_ajax_ruiyi_pos_process_split_order_payment', 'ruiyi_pos_process_split_order_payment_callback');

function ruiyi_pos_process_split_order_payment_callback() {
    // 验证nonce
    check_ajax_referer('ruiyi_pos_nonce', 'nonce');
    
    $split_order_data = isset($_POST['split_order_data']) ? json_decode(stripslashes($_POST['split_order_data']), true) : null;
    $payment_method = isset($_POST['payment_method']) ? sanitize_text_field($_POST['payment_method']) : 'cash';
    $received_amount = isset($_POST['received_amount']) ? floatval($_POST['received_amount']) : 0;
    $change_amount = isset($_POST['change_amount']) ? floatval($_POST['change_amount']) : 0;
    $table_number = isset($_POST['table_number']) ? sanitize_text_field($_POST['table_number']) : '';
    
    // 混合支付相关参数（支持公司钱票）
    $cash_amount = isset($_POST['cash_amount']) ? floatval($_POST['cash_amount']) : 0;
    $card_amount = isset($_POST['card_amount']) ? floatval($_POST['card_amount']) : 0;
    $company_ticket_amount = isset($_POST['company_ticket_amount']) ? floatval($_POST['company_ticket_amount']) : 0;
    $total_amount = isset($_POST['total_amount']) ? floatval($_POST['total_amount']) : 0;
    
    // 详细调试日志
    ruiyi_debug_log('=== RUIYI POS: 分单结账处理开始 ===');
    ruiyi_debug_log('RUIYI POS: 分单订单数据: ' . json_encode($split_order_data));
    ruiyi_debug_log('RUIYI POS: 支付方式: ' . $payment_method);
    ruiyi_debug_log('RUIYI POS: 餐桌号: ' . $table_number);
    
    if ($payment_method === 'mixed') {
        ruiyi_debug_log("RUIYI POS: 混合支付参数 - 现金: €{$cash_amount}, 刷卡: €{$card_amount}, 公司钱票: €{$company_ticket_amount}, 总计: €{$total_amount}");
        ruiyi_debug_log("RUIYI POS: received_amount: {$received_amount}, change_amount: {$change_amount}");
    }
    
    if (!$split_order_data || empty($table_number)) {
        ruiyi_debug_log('RUIYI POS: 错误 - 缺少必要数据');
        wp_send_json_error(array('message' => 'Missing required data'));
        return;
    }
    
    try {
        // 创建新的WooCommerce订单用于分单
        $order = wc_create_order();
        
        // 添加产品到订单
        foreach ($split_order_data['products'] as $product) {
            // 查找对应的WooCommerce产品
            $product_id = null;
            $wc_products = wc_get_products(array(
                'name' => $product['name'],
                'limit' => 1
            ));
            
            if (!empty($wc_products)) {
                $product_id = $wc_products[0]->get_id();
            }
            
            if ($product_id) {
                $wc_product = wc_get_product($product_id);
                $tax_rate = isset($product['taxRate']) ? floatval($product['taxRate']) : ruiyi_get_product_tax_rate($wc_product);

                $item_id = $order->add_product($wc_product, $product['quantity']);
            } else {
                // 如果找不到产品，创建一个自定义项目
                $order->add_product(null, $product['quantity'], array(
                    'name' => $product['name'],
                    'total' => $product['total']
                ));
            }
        }
        
        // 处理积分折扣
        $discount_amount = isset($split_order_data['discountAmount']) ? floatval($split_order_data['discountAmount']) : 0;
        $points_used = isset($split_order_data['pointsUsed']) ? intval($split_order_data['pointsUsed']) : 0;
        
        ruiyi_debug_log("RUIYI POS: 积分折扣检查 - discountAmount: {$discount_amount}, pointsUsed: {$points_used}");
        ruiyi_debug_log("RUIYI POS: split_order_data keys: " . implode(', ', array_keys($split_order_data)));
        
        if ($discount_amount > 0 && $points_used > 0) {
            ruiyi_debug_log("RUIYI POS: 开始应用积分折扣到分单订单");
            
            // 添加积分折扣费用项
            $points_fee = new WC_Order_Item_Fee();
            $points_fee->set_name(sprintf(__('Descuento por Puntos (%d pts)', 'ruiyi-pos'), $points_used));
            $points_fee->set_amount(-$discount_amount);
            $points_fee->set_tax_class('');
            $points_fee->set_tax_status('none');
            $points_fee->set_total(-$discount_amount);
            
            // 将积分折扣费用项添加到订单
            $order->add_item($points_fee);
            
            // 存储积分折扣元数据
            $order->update_meta_data('_points_discount_used', $points_used);
            $order->update_meta_data('_points_discount_amount', $discount_amount);
            
            ruiyi_debug_log("RUIYI POS: ✅ 积分折扣已应用到分单订单 - 积分: {$points_used}, 折扣: €{$discount_amount}");
        } else {
            ruiyi_debug_log("RUIYI POS: ❌ 未应用积分折扣 - discountAmount: {$discount_amount}, pointsUsed: {$points_used}");
        }
        
        // 设置订单元数据
        $order->update_meta_data('_table_number', $table_number);
        $order->update_meta_data('_split_order', true);
        $order->update_meta_data('_split_order_id', $split_order_data['id']);
        $order->update_meta_data('_payment_method', $payment_method);
        
        // 获取公司钱票信息（适用于所有支付方式）
        $company_ticket_amount = isset($_POST['company_ticket_amount']) ? floatval($_POST['company_ticket_amount']) : 0;
        
        // 根据支付方式设置不同的元数据
        if ($payment_method === 'cash') {
            $order->update_meta_data('_received_amount', $received_amount);
            $order->update_meta_data('_change_amount', $change_amount);
        } elseif ($payment_method === 'mixed') {
            // 混合支付：获取现金和刷卡金额
            $cash_amount = isset($_POST['cash_amount']) ? floatval($_POST['cash_amount']) : $received_amount;
            $card_amount = isset($_POST['card_amount']) ? floatval($_POST['card_amount']) : $change_amount;
            $total_amount = $cash_amount + $card_amount;
            
            $order->update_meta_data('_payment_cash_amount', $cash_amount);
            $order->update_meta_data('_payment_card_amount', $card_amount);
            $order->update_meta_data('_payment_total', $total_amount);
            $order->update_meta_data('_mixed_payment_processed', current_time('mysql'));
            
            // 也保留received_amount和change_amount以兼容现有逻辑
            $order->update_meta_data('_received_amount', $cash_amount);
            $order->update_meta_data('_change_amount', $card_amount);
            
            $order->add_order_note(sprintf(
                __('混合支付完成 - 现金: €%.2f, 刷卡: €%.2f, 总计: €%.2f', 'ruiyi-pos'),
                $cash_amount,
                $card_amount,
                $total_amount
            ));
            
            ruiyi_debug_log("RUIYI POS: 分单混合支付处理 - 现金: €{$cash_amount}, 刷卡: €{$card_amount}, 总计: €{$total_amount}");
        } elseif ($payment_method === 'company_ticket_only') {
            // 纯公司钱票支付
            $order->add_order_note(sprintf(
                __('公司钱票支付完成 - 钱票: €%.2f', 'ruiyi-pos'),
                $company_ticket_amount
            ));
        }
        
        // 保存公司钱票信息（如果有）
        if ($company_ticket_amount > 0) {
            $order->update_meta_data('_company_ticket_amount', $company_ticket_amount);
            $order->update_meta_data('_company_ticket_processed', current_time('mysql'));
            
            // 根据支付方式添加相应的组合支付备注
            if ($payment_method !== 'company_ticket_only') {
                $payment_method_name = '';
                if ($payment_method === 'cash') {
                    $payment_method_name = '现金';
                } elseif ($payment_method === 'card') {
                    $payment_method_name = '刷卡';
                } elseif ($payment_method === 'mixed') {
                    $payment_method_name = '混合支付';
                }
                
                $order->add_order_note(sprintf(
                    __('组合支付 - 公司钱票: €%.2f + %s: €%.2f', 'ruiyi-pos'),
                    $company_ticket_amount,
                    $payment_method_name,
                    $payment_method === 'mixed' ? ($cash_amount + $card_amount) : ($payment_method === 'cash' ? $received_amount : $split_order_data['total'])
                ));
            }
        }
        
        // 计算总额并设置订单状态为已完成
        $order->calculate_totals();
        $order->update_status('completed', 'Split order payment completed');
        $order->save();
        
        // 记录分单支付状态
        $split_payments = get_option('ruiyi_split_payments', array());
        if (!isset($split_payments[$table_number])) {
            $split_payments[$table_number] = array();
        }
        
        // 根据支付方式构建不同的支付记录
        $payment_record = array(
            'order_id' => $order->get_id(),
            'total' => $split_order_data['total'],
            'payment_method' => $payment_method,
            'paid_at' => current_time('mysql'),
            'status' => 'completed'
        );
        
        if ($payment_method === 'mixed') {
            $cash_amount = isset($_POST['cash_amount']) ? floatval($_POST['cash_amount']) : $received_amount;
            $card_amount = isset($_POST['card_amount']) ? floatval($_POST['card_amount']) : $change_amount;
            $company_ticket_amount = isset($_POST['company_ticket_amount']) ? floatval($_POST['company_ticket_amount']) : 0;
            $payment_record['cash_amount'] = $cash_amount;
            $payment_record['card_amount'] = $card_amount;
            $payment_record['company_ticket_amount'] = $company_ticket_amount;
        } elseif ($payment_method === 'cash') {
            $payment_record['received_amount'] = $received_amount;
            $payment_record['change_amount'] = $change_amount;
        }
        
        $split_payments[$table_number][$split_order_data['id']] = $payment_record;
        
        update_option('ruiyi_split_payments', $split_payments);
        
        wp_send_json_success(array(
            'message' => 'Split order payment processed successfully',
            'order_id' => $order->get_id(),
            'split_order_id' => $split_order_data['id']
        ));
        
    } catch (Exception $e) {
        ruiyi_debug_log('Error processing split order payment: ' . $e->getMessage());
        wp_send_json_error(array('message' => 'Failed to process payment'));
    }
}

// AA结账抵扣模式 - 🔥 修改：删除所有原订单，创建一个合并的新订单
add_action('wp_ajax_ruiyi_pos_complete_aa_checkout', 'ruiyi_pos_complete_aa_checkout_callback');

function ruiyi_pos_complete_aa_checkout_callback() {
    // 验证nonce
    check_ajax_referer('ruiyi_pos_nonce', 'nonce');

    $table_number = isset($_POST['table_number']) ? sanitize_text_field($_POST['table_number']) : '';
    $original_order_ids = isset($_POST['original_order_ids']) ? json_decode(stripslashes($_POST['original_order_ids']), true) : array();
    $payment_method = isset($_POST['payment_method']) ? sanitize_text_field($_POST['payment_method']) : 'cash';
    $cash_amount = isset($_POST['cash_amount']) ? floatval($_POST['cash_amount']) : 0;
    $card_amount = isset($_POST['card_amount']) ? floatval($_POST['card_amount']) : 0;
    $total_amount = isset($_POST['total_amount']) ? floatval($_POST['total_amount']) : 0;
    $discount_amount = isset($_POST['discount_amount']) ? floatval($_POST['discount_amount']) : 0;
    $points_used = isset($_POST['points_used']) ? intval($_POST['points_used']) : 0;
    $split_count = isset($_POST['split_count']) ? intval($_POST['split_count']) : 0;
    $payment_details = isset($_POST['payment_details']) ? json_decode(stripslashes($_POST['payment_details']), true) : array();

    ruiyi_debug_log('=== RUIYI POS: AA金额分单结账开始（合并订单模式） ===');
    ruiyi_debug_log('RUIYI POS: 桌号: ' . $table_number);
    ruiyi_debug_log('RUIYI POS: 原订单ID: ' . json_encode($original_order_ids));
    ruiyi_debug_log('RUIYI POS: 支付方式: ' . $payment_method);
    ruiyi_debug_log('RUIYI POS: 现金: €' . $cash_amount . ', 刷卡: €' . $card_amount . ', 总计: €' . $total_amount);
    ruiyi_debug_log('RUIYI POS: 分单数量: ' . $split_count);

    if (empty($table_number) || empty($original_order_ids)) {
        ruiyi_debug_log('RUIYI POS: 错误 - 缺少必要数据');
        wp_send_json_error(array('message' => 'Missing required data'));
        return;
    }

    // 🔥 防止重复提交：检查原订单是否已被处理
    foreach ($original_order_ids as $oid) {
        $check_order = wc_get_order($oid);
        if (!$check_order) {
            ruiyi_debug_log('RUIYI POS: AA结账 - 原订单 ' . $oid . ' 不存在（可能已被处理），跳过');
            // 桌位可能已释放，直接返回成功
            wp_send_json_success(array(
                'new_order_id' => 0,
                'deleted_orders' => $original_order_ids,
                'already_processed' => true
            ));
            return;
        }
    }

    try {
        // 🔥 第一步：收集所有原订单的产品
        $all_products = array();
        $deleted_order_ids = array();

        foreach ($original_order_ids as $order_id) {
            $order = wc_get_order($order_id);
            if (!$order) {
                ruiyi_debug_log('RUIYI POS: 订单不存在: ' . $order_id);
                continue;
            }

            // 收集订单中的所有产品
            foreach ($order->get_items() as $item) {
                $product_id = $item->get_product_id();
                $quantity = $item->get_quantity();
                $item_total = floatval($item->get_total());
                $unit_price = $quantity > 0 ? $item_total / $quantity : $item_total;

                $all_products[] = array(
                    'product_id' => $product_id,
                    'name' => $item->get_name(),
                    'quantity' => $quantity,
                    'unit_price' => $unit_price,
                    'total' => $item_total
                );
            }

            $deleted_order_ids[] = $order_id;
        }

        ruiyi_debug_log('RUIYI POS: 收集到 ' . count($all_products) . ' 个产品项');

        // 🔥 第二步：创建一个新的合并订单
        $new_order = wc_create_order();

        // 添加所有产品到新订单
        foreach ($all_products as $product) {
            $product_id = intval($product['product_id']);
            $quantity = floatval($product['quantity']);
            $product_total = floatval($product['total']);

            if ($product_id > 0) {
                $wc_product = wc_get_product($product_id);
                if ($wc_product) {
                    $new_order->add_product($wc_product, $quantity, array(
                        'subtotal' => $product_total,
                        'total' => $product_total
                    ));
                } else {
                    // 产品不存在，添加自定义行项目
                    $item = new WC_Order_Item_Product();
                    $item->set_name($product['name']);
                    $item->set_quantity($quantity);
                    $item->set_subtotal($product_total);
                    $item->set_total($product_total);
                    $new_order->add_item($item);
                }
            } else {
                // 没有产品ID，添加自定义行项目
                $item = new WC_Order_Item_Product();
                $item->set_name($product['name']);
                $item->set_quantity($quantity);
                $item->set_subtotal($product_total);
                $item->set_total($product_total);
                $new_order->add_item($item);
            }
        }

        // 设置订单元数据
        $new_order->update_meta_data('_pos_order', true);
        $new_order->update_meta_data('_pos_table_number', $table_number);
        $new_order->update_meta_data('_aa_checkout', true);
        $new_order->update_meta_data('_aa_amount_split', true);
        $new_order->update_meta_data('_aa_split_count', $split_count);
        $new_order->update_meta_data('_aa_payment_method', $payment_method);
        $new_order->update_meta_data('_aa_cash_amount', $cash_amount);
        $new_order->update_meta_data('_aa_card_amount', $card_amount);
        $new_order->update_meta_data('_aa_total_amount', $total_amount);
        $new_order->update_meta_data('_aa_completed_at', current_time('mysql'));
        $new_order->update_meta_data('_aa_merged_from_orders', json_encode($deleted_order_ids));

        // 如果有积分折扣，记录信息
        if ($discount_amount > 0 && $points_used > 0) {
            $new_order->update_meta_data('_points_discount_used', $points_used);
            $new_order->update_meta_data('_points_discount_amount', $discount_amount);

            $points_fee = new WC_Order_Item_Fee();
            $points_fee->set_name(sprintf(__('Descuento por Puntos (%d pts)', 'ruiyi-pos'), $points_used));
            $points_fee->set_amount(-$discount_amount);
            $points_fee->set_tax_class('');
            $points_fee->set_tax_status('none');
            $points_fee->set_total(-$discount_amount);
            $new_order->add_item($points_fee);
        }

        // 根据支付方式设置订单支付方法
        if ($payment_method === 'mixed') {
            $new_order->set_payment_method('mixed');
            $new_order->set_payment_method_title('Mixto (Efectivo + Tarjeta)');
            $new_order->update_meta_data('_payment_method_detail', 'mixed');
            $new_order->update_meta_data('_cash_amount', $cash_amount);
            $new_order->update_meta_data('_card_amount', $card_amount);
        } else if ($payment_method === 'cash') {
            $new_order->set_payment_method('cod');
            $new_order->set_payment_method_title('Efectivo');
            $new_order->update_meta_data('_payment_method_detail', 'cash');
            $new_order->update_meta_data('_cash_amount', $cash_amount ?: $total_amount);
            $new_order->update_meta_data('_card_amount', 0);
        } else if ($payment_method === 'card') {
            $new_order->set_payment_method('bacs');
            $new_order->set_payment_method_title('Tarjeta');
            $new_order->update_meta_data('_payment_method_detail', 'card');
            $new_order->update_meta_data('_cash_amount', 0);
            $new_order->update_meta_data('_card_amount', $card_amount ?: $total_amount);
        }

        // 保存分单支付详情
        if (!empty($payment_details)) {
            $new_order->update_meta_data('_aa_payment_details', json_encode($payment_details));
        }

        // 添加订单备注
        $new_order->add_order_note(sprintf(
            __('AA金额分单结账（%d人分摊） - 桌位 %s - 合并自订单: %s - 现金: €%.2f, 刷卡: €%.2f, 总计: €%.2f', 'ruiyi-pos'),
            $split_count,
            $table_number,
            implode(', #', $deleted_order_ids),
            $cash_amount,
            $card_amount,
            $total_amount
        ));

        // 标记已记录日结单
        $new_order->update_meta_data('_recorded_in_daily_summary', 'yes');

        // 计算并保存订单
        $new_order->calculate_totals();
        $new_order->update_status('completed', 'AA amount split checkout completed');
        $new_order->save();

        $new_order_id = $new_order->get_id();
        ruiyi_debug_log('RUIYI POS: 新合并订单创建成功 - 订单ID: ' . $new_order_id);

        // 🔥 第三步：永久删除所有原订单（使用 WC 原生删除，兼容 HPOS）
        foreach ($deleted_order_ids as $order_id) {
            $old_order = wc_get_order($order_id);
            if ($old_order) {
                $old_order->delete(true);
                ruiyi_debug_log('RUIYI POS: 永久删除原订单(WC): ' . $order_id);
            } else {
                // 回退：尝试 wp_delete_post（兼容旧数据）
                if (get_post($order_id)) {
                    wp_delete_post($order_id, true);
                    ruiyi_debug_log('RUIYI POS: 永久删除原订单(WP回退): ' . $order_id);
                } else {
                    ruiyi_debug_log('RUIYI POS: 原订单 ' . $order_id . ' 已不存在，跳过删除');
                }
            }
        }

        // 🔥 原子更新桌位状态（防止并发竞态）
        $table_number_numeric = preg_replace('/[^0-9]/', '', $table_number);

        if (!empty($table_number_numeric)) {
            ruiyi_update_single_table_status($table_number_numeric, array(
                'status' => 'available',
                'order_id' => null,
                'total' => 0,
                'order_count' => 0,
                'last_updated' => current_time('mysql'),
                'updated_by' => 'aa_amount_split_checkout'
            ));
            ruiyi_debug_log('RUIYI POS: AA结账 - 桌位 ' . $table_number . ' 状态已更新为 available');
        }

        // 手动记录日结单
        if (function_exists('ruiyi_record_daily_transaction')) {
            $items_for_summary = array();
            foreach ($all_products as $product) {
                $items_for_summary[] = array(
                    'name' => $product['name'],
                    'product_id' => $product['product_id'],
                    'quantity' => $product['quantity'],
                    'total' => $product['total']
                );
            }

            ruiyi_record_daily_transaction(
                $new_order_id,
                $payment_method,
                $total_amount,
                $items_for_summary
            );

            ruiyi_debug_log('[AA金额分单] 日结单记录完成 - 订单ID: ' . $new_order_id .
                      ', 支付方式: ' . $payment_method .
                      ', 现金: €' . $cash_amount .
                      ', 刷卡: €' . $card_amount .
                      ', 总额: €' . $total_amount);
        }

        ruiyi_debug_log('=== RUIYI POS: AA金额分单结账完成 ===');
        ruiyi_debug_log('RUIYI POS: 删除了 ' . count($deleted_order_ids) . ' 个原订单，创建了新订单 #' . $new_order_id);

        wp_send_json_success(array(
            'message' => 'AA checkout completed successfully',
            'new_order_id' => $new_order_id,
            'deleted_orders' => $deleted_order_ids,
            'total_products' => count($all_products),
            'total_amount' => $total_amount,
            'split_count' => $split_count
        ));

    } catch (Exception $e) {
        ruiyi_debug_log('RUIYI POS: AA结账错误 - ' . $e->getMessage());
        wp_send_json_error(array('message' => 'Failed to complete AA checkout: ' . $e->getMessage()));
    }
}

// 🔥 新增：创建单个分单的WooCommerce订单
add_action('wp_ajax_ruiyi_pos_create_single_split_order', 'ruiyi_pos_create_single_split_order_callback');

function ruiyi_pos_create_single_split_order_callback() {
    // 验证nonce
    check_ajax_referer('ruiyi_pos_nonce', 'nonce');

    $table_number = isset($_POST['table_number']) ? sanitize_text_field($_POST['table_number']) : '';
    $split_number = isset($_POST['split_number']) ? intval($_POST['split_number']) : 1;
    $products = isset($_POST['products']) ? json_decode(stripslashes($_POST['products']), true) : array();
    $payment_method = isset($_POST['payment_method']) ? sanitize_text_field($_POST['payment_method']) : 'cash';
    $cash_amount = isset($_POST['cash_amount']) ? floatval($_POST['cash_amount']) : 0;
    $card_amount = isset($_POST['card_amount']) ? floatval($_POST['card_amount']) : 0;
    $total_amount = isset($_POST['total_amount']) ? floatval($_POST['total_amount']) : 0;
    $discount_amount = isset($_POST['discount_amount']) ? floatval($_POST['discount_amount']) : 0;
    $points_used = isset($_POST['points_used']) ? intval($_POST['points_used']) : 0;

    ruiyi_debug_log('=== RUIYI POS: 创建单个分单订单开始 ===');
    ruiyi_debug_log('RUIYI POS: 桌号: ' . $table_number . ', 分单: ' . $split_number);
    ruiyi_debug_log('RUIYI POS: 产品数量: ' . count($products) . ', 支付方式: ' . $payment_method);
    ruiyi_debug_log('RUIYI POS: 现金: €' . $cash_amount . ', 刷卡: €' . $card_amount . ', 总计: €' . $total_amount);

    if (empty($products)) {
        ruiyi_debug_log('RUIYI POS: 错误 - 没有产品');
        wp_send_json_error(array('message' => 'No products provided'));
        return;
    }

    try {
        // 创建新订单
        $new_order = wc_create_order();

        // 添加产品到订单
        foreach ($products as $product) {
            $product_id = intval($product['product_id'] ?? 0);
            $quantity = floatval($product['quantity'] ?? 1);
            $unit_price = floatval($product['price'] ?? 0);
            $product_total = floatval($product['total'] ?? ($unit_price * $quantity));

            if ($product_id > 0) {
                $wc_product = wc_get_product($product_id);
                if ($wc_product) {
                    $new_order->add_product($wc_product, $quantity, array(
                        'subtotal' => $product_total,
                        'total' => $product_total
                    ));
                } else {
                    // 产品不存在，添加自定义行项目
                    $item = new WC_Order_Item_Product();
                    $item->set_name($product['name'] ?? 'Producto');
                    $item->set_quantity($quantity);
                    $item->set_subtotal($product_total);
                    $item->set_total($product_total);
                    $new_order->add_item($item);
                }
            } else {
                // 没有产品ID，添加自定义行项目
                $item = new WC_Order_Item_Product();
                $item->set_name($product['name'] ?? 'Producto');
                $item->set_quantity($quantity);
                $item->set_subtotal($product_total);
                $item->set_total($product_total);
                $new_order->add_item($item);
            }
        }

        // 设置订单元数据
        $new_order->update_meta_data('_pos_order', true);
        $new_order->update_meta_data('_pos_table_number', $table_number);
        $new_order->update_meta_data('_aa_split_order', true);
        $new_order->update_meta_data('_aa_split_number', $split_number);

        // 设置支付信息
        if ($payment_method === 'mixed' || ($cash_amount > 0 && $card_amount > 0)) {
            $new_order->set_payment_method('mixed');
            $new_order->set_payment_method_title('Mixto (Efectivo + Tarjeta)');
            $new_order->update_meta_data('_payment_method_detail', 'mixed');
            $new_order->update_meta_data('_cash_amount', $cash_amount);
            $new_order->update_meta_data('_card_amount', $card_amount);
        } else if ($cash_amount > 0 || $payment_method === 'cash') {
            $new_order->set_payment_method('cod');
            $new_order->set_payment_method_title('Efectivo');
            $new_order->update_meta_data('_payment_method_detail', 'cash');
            $new_order->update_meta_data('_cash_amount', $cash_amount ?: $total_amount);
            $new_order->update_meta_data('_card_amount', 0);
        } else {
            $new_order->set_payment_method('bacs');
            $new_order->set_payment_method_title('Tarjeta');
            $new_order->update_meta_data('_payment_method_detail', 'card');
            $new_order->update_meta_data('_cash_amount', 0);
            $new_order->update_meta_data('_card_amount', $card_amount ?: $total_amount);
        }

        // 如果有积分折扣
        if ($discount_amount > 0 && $points_used > 0) {
            $new_order->update_meta_data('_points_discount_used', $points_used);
            $new_order->update_meta_data('_points_discount_amount', $discount_amount);

            $points_fee = new WC_Order_Item_Fee();
            $points_fee->set_name(sprintf(__('Descuento por Puntos (%d pts)', 'ruiyi-pos'), $points_used));
            $points_fee->set_amount(-$discount_amount);
            $points_fee->set_tax_class('');
            $points_fee->set_tax_status('none');
            $points_fee->set_total(-$discount_amount);
            $new_order->add_item($points_fee);
        }

        // 添加订单备注
        $new_order->add_order_note(sprintf(
            __('AA分单结账 - 分单 #%d - 桌位 %s', 'ruiyi-pos'),
            $split_number,
            $table_number
        ));

        // 标记已记录日结单（避免重复记录）
        $new_order->update_meta_data('_recorded_in_daily_summary', 'yes');

        // 计算并保存订单
        $new_order->calculate_totals();
        $new_order->update_status('completed', 'AA split checkout completed');
        $new_order->save();

        $order_id = $new_order->get_id();
        ruiyi_debug_log('RUIYI POS: 分单订单创建成功 - 订单ID: ' . $order_id);

        // 记录日结单
        if (function_exists('ruiyi_record_daily_transaction')) {
            $items_for_summary = array();
            foreach ($products as $product) {
                $items_for_summary[] = array(
                    'name' => $product['name'] ?? 'Producto',
                    'product_id' => $product['product_id'] ?? 0,
                    'quantity' => $product['quantity'] ?? 1,
                    'total' => floatval($product['total'] ?? 0)
                );
            }

            ruiyi_record_daily_transaction(
                $order_id,
                $payment_method,
                $total_amount,
                $items_for_summary
            );
            ruiyi_debug_log('RUIYI POS: 日结单记录完成');
        }

        ruiyi_debug_log('=== RUIYI POS: 创建单个分单订单完成 ===');

        wp_send_json_success(array(
            'message' => 'Split order created successfully',
            'order_id' => $order_id,
            'order_number' => $new_order->get_order_number()
        ));

    } catch (Exception $e) {
        ruiyi_debug_log('RUIYI POS: 创建分单订单错误 - ' . $e->getMessage());
        wp_send_json_error(array('message' => 'Failed to create split order: ' . $e->getMessage()));
    }
}

// 🔥 新增：部分AA结账 - 保存剩余产品到桌位，为已支付产品创建订单
add_action('wp_ajax_ruiyi_pos_save_partial_aa_checkout', 'ruiyi_pos_save_partial_aa_checkout_callback');

function ruiyi_pos_save_partial_aa_checkout_callback() {
    // 验证nonce
    check_ajax_referer('ruiyi_pos_nonce', 'nonce');

    $table_number = isset($_POST['table_number']) ? sanitize_text_field($_POST['table_number']) : '';
    $original_order_ids = isset($_POST['original_order_ids']) ? json_decode(stripslashes($_POST['original_order_ids']), true) : array();
    $remaining_products = isset($_POST['remaining_products']) ? json_decode(stripslashes($_POST['remaining_products']), true) : array();

    ruiyi_debug_log('=== RUIYI POS: 保存桌位订单开始 ===');
    ruiyi_debug_log('RUIYI POS: 桌号: ' . $table_number);
    ruiyi_debug_log('RUIYI POS: 原订单ID: ' . json_encode($original_order_ids));
    ruiyi_debug_log('RUIYI POS: 剩余产品数量: ' . count($remaining_products));

    if (empty($table_number) || empty($original_order_ids)) {
        ruiyi_debug_log('RUIYI POS: 错误 - 缺少必要数据');
        wp_send_json_error(array('message' => 'Missing required data'));
        return;
    }

    try {
        // 🔥 修改：不再创建订单（订单已在分单结账时创建）
        // 只更新原订单，保留剩余产品

        // 🔥🔥🔥 关键修复：保存新添加的商品item_id，返回给前端
        $updated_items_with_ids = array();

        if (!empty($remaining_products) && !empty($original_order_ids)) {
            // 获取第一个原订单来更新
            $first_order_id = $original_order_ids[0];
            $order = wc_get_order($first_order_id);

            if ($order) {
                $kitchen_printed_baselines = array();
                foreach ($order->get_items() as $item_id => $item) {
                    $old_qty = max(0, intval($item->get_quantity()));
                    $old_total = floatval($item->get_total());
                    $old_unit_price = $old_qty > 0 ? round($old_total / $old_qty, 2) : round($old_total, 2);
                    $printed_raw = wc_get_order_item_meta($item_id, '_kitchen_printed_qty', true);
                    $printed_qty = ($printed_raw === '' || $printed_raw === null)
                        ? $old_qty
                        : min($old_qty, max(0, intval($printed_raw)));
                    $baseline_key = intval($item->get_product_id()) . '|' . strtolower(trim($item->get_name())) . '|' . number_format($old_unit_price, 2, '.', '');

                    if (!isset($kitchen_printed_baselines[$baseline_key])) {
                        $kitchen_printed_baselines[$baseline_key] = array();
                    }
                    $kitchen_printed_baselines[$baseline_key][] = $printed_qty;
                }

                // 移除所有现有商品
                foreach ($order->get_items() as $item_id => $item) {
                    $order->remove_item($item_id);
                }

                // 添加剩余产品，并记录新的item_id
                $product_index = 0;
                foreach ($remaining_products as $product) {
                    $product_id = intval($product['product_id'] ?? 0);
                    $quantity = floatval($product['quantity'] ?? 1);
                    $unit_price = floatval($product['price'] ?? 0);
                    $total = floatval($product['total'] ?? ($unit_price * $quantity));
                    $new_item_id = null;

                    if ($product_id > 0) {
                        $wc_product = wc_get_product($product_id);
                        if ($wc_product) {
                            $new_item_id = $order->add_product($wc_product, $quantity, array(
                                'subtotal' => $total,
                                'total' => $total
                            ));
                        } else {
                            $item = new WC_Order_Item_Product();
                            $item->set_name($product['name'] ?? 'Producto');
                            $item->set_quantity($quantity);
                            $item->set_subtotal($total);
                            $item->set_total($total);
                            $new_item_id = $order->add_item($item);
                        }
                    } else {
                        $item = new WC_Order_Item_Product();
                        $item->set_name($product['name'] ?? 'Producto');
                        $item->set_quantity($quantity);
                        $item->set_subtotal($total);
                        $item->set_total($total);
                        $new_item_id = $order->add_item($item);
                    }

                    // 🔥 重建后的剩余旧产品继承厨房打印状态，避免后续追加时整单重打
                    if ($new_item_id) {
                        $baseline_key = $product_id . '|' . strtolower(trim($product['name'] ?? '')) . '|' . number_format(round($unit_price, 2), 2, '.', '');
                        $printed_qty = null;

                        if (isset($kitchen_printed_baselines[$baseline_key]) && !empty($kitchen_printed_baselines[$baseline_key])) {
                            $printed_qty = array_shift($kitchen_printed_baselines[$baseline_key]);
                        }

                        // 保存部分AA剩余产品是账单重建，不是新增厨房商品。
                        // 旧订单没有打印数量meta时，按已打印处理，避免后续追加商品时整单重打。
                        if ($printed_qty === null) {
                            $printed_qty = $quantity;
                        }
                        wc_update_order_item_meta($new_item_id, '_kitchen_printed_qty', min(max(0, intval($quantity)), max(0, intval($printed_qty))));
                    }

                    // 🔥 记录新item_id与产品的映射
                    $updated_items_with_ids[] = array(
                        'product_id' => $product_id,
                        'name' => $product['name'] ?? '',
                        'quantity' => $quantity,
                        'price' => $unit_price,
                        'total' => $total,
                        'item_id' => $new_item_id,
                        'order_id' => $first_order_id
                    );

                    $product_index++;
                }

                // 添加备注
                $order->add_order_note(sprintf(
                    __('部分AA结账完成 - 已移除已付款产品，剩余 %d 个产品', 'ruiyi-pos'),
                    count($remaining_products)
                ));

                // 重新计算并保存
                $order->calculate_totals();
                $order->save();
                delete_post_meta($first_order_id, '_newly_added_items');

                ruiyi_debug_log('RUIYI POS: 原订单 ' . $first_order_id . ' 已更新，剩余产品数: ' . count($remaining_products));
                ruiyi_debug_log('RUIYI POS: 新item_ids: ' . json_encode(array_column($updated_items_with_ids, 'item_id')));
            }

            // 如果有多个原订单，永久删除后面的（不是取消，而是彻底删除）
            if (count($original_order_ids) > 1) {
                for ($i = 1; $i < count($original_order_ids); $i++) {
                    $extra_order_id = $original_order_ids[$i];
                    $extra_order = wc_get_order($extra_order_id);
                    if ($extra_order) {
                        // 🔥 永久删除订单（WC 原生删除，兼容 HPOS）
                        $extra_order->delete(true);
                        ruiyi_debug_log('RUIYI POS: 永久删除多余订单(WC) ' . $extra_order_id);
                    }
                }
            }
        } else if (empty($remaining_products)) {
            // 没有剩余产品，永久删除所有原订单
            foreach ($original_order_ids as $order_id) {
                $order = wc_get_order($order_id);
                if ($order) {
                    // 永久删除订单（WC 原生删除，兼容 HPOS）
                    $order->delete(true);
                    ruiyi_debug_log('RUIYI POS: 永久删除原订单(WC) ' . $order_id);
                }
            }
        }

        // 🔥 原子更新桌位状态（防止并发竞态）
        $table_number_numeric = preg_replace('/[^0-9]/', '', $table_number);

        if (!empty($table_number_numeric)) {
            if (empty($remaining_products)) {
                // 没有剩余产品，桌位变为可用
                ruiyi_update_single_table_status($table_number_numeric, array(
                    'status' => 'available',
                    'order_id' => null,
                    'total' => 0,
                    'order_count' => 0,
                    'last_updated' => current_time('mysql'),
                    'updated_by' => 'partial_aa_checkout'
                ));
            } else {
                // 有剩余产品，更新桌位金额
                $remaining_total = array_reduce($remaining_products, function($sum, $p) {
                    return $sum + floatval($p['total'] ?? 0);
                }, 0);

                ruiyi_update_single_table_status($table_number_numeric, array(
                    'status' => 'occupied',
                    'order_id' => $original_order_ids[0],
                    'total' => $remaining_total,
                    'order_count' => 1,
                    'last_updated' => current_time('mysql'),
                    'updated_by' => 'partial_aa_checkout'
                ));
            }
            ruiyi_debug_log('RUIYI POS: 桌位 ' . $table_number . ' 状态已更新');
        }

        ruiyi_debug_log('=== RUIYI POS: 保存桌位订单完成 ===');

        wp_send_json_success(array(
            'message' => 'Table order saved successfully',
            'remaining_products_count' => count($remaining_products),
            'remaining_total' => isset($remaining_total) ? $remaining_total : 0,
            'order_id' => !empty($original_order_ids) ? $original_order_ids[0] : null,
            'updated_items' => $updated_items_with_ids // 🔥 返回带有新item_id的商品列表
        ));

    } catch (Exception $e) {
        ruiyi_debug_log('RUIYI POS: 保存桌位订单错误 - ' . $e->getMessage());
        wp_send_json_error(array('message' => 'Failed to save: ' . $e->getMessage()));
    }
}

// 🔥 旧代码移除（订单创建已移到 processSplitOrderPayment 中的 ruiyi_pos_create_single_split_order）
