// 生成分单小票HTML
add_action('wp_ajax_ruiyi_pos_get_split_receipt_html', 'ruiyi_pos_get_split_receipt_html_callback');

function ruiyi_pos_get_split_receipt_html_callback() {
    // 验证nonce
    check_ajax_referer('ruiyi_pos_nonce', 'nonce');
    
    $split_order_data = isset($_POST['split_order_data']) ? json_decode(stripslashes($_POST['split_order_data']), true) : null;
    $table_number = isset($_POST['table_number']) ? sanitize_text_field($_POST['table_number']) : '';

    // 🔥 获取桌位的分类显示名称（AA结账小票也使用分类名称）
    $table_display_name = $table_number; // 默认值
    // 提取纯数字桌号
    $table_number_numeric = preg_replace('/[^0-9]/', '', $table_number);
    if (!empty($table_number_numeric) && is_numeric($table_number_numeric)) {
        $all_mappings = ruiyi_get_all_table_categories_mapping();
        if ($all_mappings && is_array($all_mappings)) {
            foreach ($all_mappings as $mapping) {
                if (intval($mapping['global_table_number']) === intval($table_number_numeric)) {
                    $table_display_name = $mapping['category_display_name'] ?:
                                        ($mapping['display_name'] ?: ('Mesa ' . $table_number_numeric));
                    ruiyi_debug_log('[分单小票桌号] 全局编号 ' . $table_number_numeric . ' → 分类显示名称: ' . $table_display_name);
                    break;
                }
            }
        }
    }
    
    // 调试：记录接收到的数据 (v2.0 - 2025-08-25)
    ruiyi_debug_log('RUIYI POS: Split receipt data received (v2.0) - ' . json_encode($split_order_data));
    ruiyi_debug_log('RUIYI POS: Function version check - ruiyi_pos_get_split_receipt_html_callback v2.0 is running');
    
    // 调试：检查折扣信息
    $discount_amount = isset($split_order_data['discountAmount']) ? floatval($split_order_data['discountAmount']) : 0;
    ruiyi_debug_log('RUIYI POS: Split receipt discount check - discountAmount: ' . $discount_amount);
    if ($discount_amount > 0) {
        ruiyi_debug_log('RUIYI POS: Split receipt has discount - original total: ' . (isset($split_order_data['originalTotal']) ? $split_order_data['originalTotal'] : 'not set') .
                  ', final total: ' . (isset($split_order_data['total']) ? $split_order_data['total'] : 'not set'));
    }
    
    if (!$split_order_data || empty($table_number)) {
        wp_send_json_error(array('message' => 'Missing required data'));
        return;
    }

    // 检查产品数据是否存在
    if (!isset($split_order_data['products']) || empty($split_order_data['products'])) {
        ruiyi_debug_log('RUIYI POS: No products found in split order data');
        wp_send_json_error(array('message' => 'No products found in split order'));
        return;
    }

    // 尝试获取分单订单对象（用于Verifactu二维码）
    $order = null;
    $order_id = null;

    // 检查多种可能的订单ID字段
    if (isset($split_order_data['orderId']) && $split_order_data['orderId']) {
        $order_id = $split_order_data['orderId'];
    } elseif (isset($split_order_data['woocommerce_order_id']) && $split_order_data['woocommerce_order_id']) {
        $order_id = $split_order_data['woocommerce_order_id'];
    } elseif (isset($split_order_data['order_id']) && $split_order_data['order_id']) {
        $order_id = $split_order_data['order_id'];
    }

    if ($order_id) {
        $order = wc_get_order($order_id);
        ruiyi_debug_log('RUIYI POS: 分单小票 - 找到WooCommerce订单ID: #' . $order_id);
        ruiyi_debug_log('RUIYI POS: 分单小票 - 订单对象' . ($order ? '获取成功' : '获取失败'));
