            <div class="store-info">
                <?php if (!empty($store_business_name)) : ?><div class="business-name"><?php echo esc_html($store_business_name); ?></div><?php endif; ?>
                <?php if (!empty($store_cif_nif)) : ?><div class="cif-nif">CIF/NIF: <?php echo esc_html($store_cif_nif); ?></div><?php endif; ?>
                <?php if (!empty($store_phone)) : ?><div class="phone">Tel: <?php echo esc_html($store_phone); ?></div><?php endif; ?>
                <?php if (!empty($store_address)) : ?><div class="address"><?php echo nl2br(esc_html($store_address)); ?></div><?php endif; ?>
            </div>

            <?php
            // 🔥 初始化 order_customer_info 变量（从订单meta获取客户信息）
            $order_customer_info = null;
            if (!empty($order_ids_to_print) && is_array($order_ids_to_print)) {
                $first_order = wc_get_order($order_ids_to_print[0]);
                if ($first_order) {
                    $order_customer_info = array(
                        'name' => $first_order->get_meta('_customer_name'),
                        'phone' => $first_order->get_meta('_customer_phone'),
                        'business_name' => $first_order->get_meta('_customer_business_name'),
                        'cif_nif' => $first_order->get_meta('_customer_cif_nif'),
                        'address' => $first_order->get_meta('_customer_address'),
                        'postal_code' => $first_order->get_meta('_customer_postal_code'),
                        'email' => $first_order->get_meta('_customer_email'),
                        'notes' => $first_order->get_meta('_customer_notes')
                    );
                    // 如果订单meta中有客户信息，记录日志
                    if (!empty($order_customer_info['phone'])) {
                        ruiyi_debug_log('小票生成 - 从订单meta获取到客户信息: ' . json_encode($order_customer_info));
                    } else {
                        $order_customer_info = null;
                    }
                }
            }

            // 🔥 修复：合并订单meta和前端传递的客户信息（分单区域）
            if ($order_customer_info && $customer_info) {
                // 两者都有，合并：优先使用订单meta的非空字段，缺失的从前端补充
                $display_customer_info = array(
                    'name' => !empty($order_customer_info['name']) ? $order_customer_info['name'] : ($customer_info['name'] ?? ''),
                    'phone' => !empty($order_customer_info['phone']) ? $order_customer_info['phone'] : ($customer_info['phone'] ?? ''),
                    'business_name' => !empty($order_customer_info['business_name']) ? $order_customer_info['business_name'] : ($customer_info['business_name'] ?? ''),
                    'cif_nif' => !empty($order_customer_info['cif_nif']) ? $order_customer_info['cif_nif'] : ($customer_info['cif_nif'] ?? ''),
                    'address' => !empty($order_customer_info['address']) ? $order_customer_info['address'] : ($customer_info['address'] ?? ''),
                    'postal_code' => !empty($order_customer_info['postal_code']) ? $order_customer_info['postal_code'] : ($customer_info['postal_code'] ?? ''),
                    'email' => !empty($order_customer_info['email']) ? $order_customer_info['email'] : ($customer_info['email'] ?? ''),
                    'notes' => !empty($order_customer_info['notes']) ? $order_customer_info['notes'] : ($customer_info['notes'] ?? '')
                );
                ruiyi_debug_log('小票生成(分单区域) - 合并订单meta和前端客户信息');
            } else {
                // 只有一个来源，使用可用的那个
                $display_customer_info = $order_customer_info ?: $customer_info;
            }
            $is_takeaway = ($order_type === 'llevar') || (!empty($display_customer_info) && !empty($display_customer_info['phone']));

            // 🔥 调试：记录客户信息状态
            ruiyi_debug_log('小票生成(分单区域) - 客户信息检查: order_customer_info=' . ($order_customer_info ? 'YES' : 'NO') . ', customer_info=' . ($customer_info ? 'YES' : 'NO') . ', display_customer_info=' . ($display_customer_info ? json_encode($display_customer_info) : 'NULL'));
            
            if ($is_takeaway && $display_customer_info): ?>
                <!-- 外卖订单客户信息 - 全部使用西班牙语 -->
                <?php // <h4>Pedido para Llevar</h4> - 注释掉，外卖订单不显示标题 ?>
                <div class="customer-info">
                    <strong>Datos Cliente:</strong> <?php echo esc_html($display_customer_info['name'] ?? 'N/A'); ?><br>
                    <strong>Teléfono:</strong> <?php echo esc_html($display_customer_info['phone'] ?? 'N/A'); ?><br>
                    <?php if (!empty($display_customer_info['business_name'])): ?>
                        <strong>Nombre del Negocio:</strong> <?php echo esc_html($display_customer_info['business_name']); ?><br>
                    <?php endif; ?>
                    <?php if (!empty($display_customer_info['cif_nif'])): ?>
                        <strong>CIF/NIF:</strong> <?php echo esc_html($display_customer_info['cif_nif']); ?><br>
                    <?php endif; ?>
                    <?php if (!empty($display_customer_info['address'])): ?>
                        <strong>Dirección:</strong> <?php echo esc_html($display_customer_info['address']); ?><br>
                    <?php endif; ?>
                    <?php if (!empty($display_customer_info['postal_code'])): ?>
                        <strong>Código Postal:</strong> <?php echo esc_html($display_customer_info['postal_code']); ?><br>
                    <?php endif; ?>
                    <?php // 🔥 修复：添加备注字段显示 ?>
                    <?php if (!empty($display_customer_info['notes'])): ?>
                        <strong><?php echo ruiyi_translate('Notas', 'Notes', '备注'); ?>:</strong> <?php echo esc_html($display_customer_info['notes']); ?><br>
                    <?php endif; ?>
                </div>
                <hr>
            <?php else: ?>
                <!-- 普通堂食订单 -->
                <h4><?php echo esc_html($table_display_name); ?></h4>
            <?php endif; ?>
            <?php
            // 使用date函数避免本地化，直接获取服务器时间
            $timezone_split = wp_timezone();
            $dt_split = new DateTime('now', $timezone_split);
            $formatted_date_split = $dt_split->format('m-d-Y H:i');
            ruiyi_debug_log('🔍 [拆分订单日期调试] 行10586 - DateTime输出: ' . $formatted_date_split);
            ?>
            <div class="date-line">Fecha: <?php echo $formatted_date_split; ?></div>
            <script>console.log('🔍 [拆分订单日期调试] 行10586 - 日期: <?php echo addslashes($formatted_date_split); ?>');</script>
            <?php
            // 🔥 添加 FACTURA SIMPLIFICADA（优先使用 Verifactu 插件生成的发票号码）
            // 使用前面已获取的 $order 和 $order_id 变量
            if ($order && $order_id) {
                $invoice_number = ruiyi_get_receipt_invoice_number($order);

                if (!empty($invoice_number)) {
                    echo '<div class="verifactu-invoice-number" data-invoice-number="' . esc_attr($invoice_number) . '" style="font-weight: bold; text-align: ' . esc_attr($receipt_header_alignment) . '; margin-bottom: 2mm;">';
                    echo 'FACTURA SIMPLIFICADA: ' . esc_html($invoice_number);
                    echo '</div>';
                }

                ruiyi_debug_log('RUIYI POS: 分单小票 - FACTURA SIMPLIFICADA: ' . $invoice_number);
            } else {
                ruiyi_debug_log('RUIYI POS: 分单小票 - 无法显示FACTURA SIMPLIFICADA，订单对象为空');
            }
            ?>

            <hr>

            <!-- 产品列表（使用table结构，与普通小票相同） -->
            <?php $receipt_product_format_split = get_option('pos_receipt_product_format', 'default'); ?>
            <table>
                <thead>
                    <tr>
                    <?php if ($receipt_product_format_split === 'qty_first'): ?>
                        <th style="width: 15%; text-align:center;">Cant.</th>
                        <th style="width: 50%;">Producto</th>
                    <?php else: ?>
                        <th style="width: 50%;">Producto</th>
                        <th style="width: 15%; text-align:center;">Cant.</th>
                    <?php endif; ?>
                        <th style="width: 15%; text-align:right;">Precio</th>
                        <th style="width: 20%; text-align:right;">Total</th>
                    </tr>
                </thead>
                <tbody>
                <?php
                $subtotal = 0;

                // 如果没有产品数据，显示错误信息
                if (empty($split_order_data['products'])) {
                    ruiyi_debug_log('RUIYI POS: Empty products array in split order data');
                    echo '<tr><td colspan="4" style="text-align:center; padding: 5px 0;">ERROR: No se encontraron productos</td></tr>';
                } else {
                    foreach ($split_order_data['products'] as $index => $product) {
                        // 验证产品数据完整性
                        $product_name = isset($product['name']) ? $product['name'] : 'Producto sin nombre';
                        // 🔥 中西双语
                        if ($receipt_bilingual && !empty($product['name_zh'])) {
                            $product_name = ruiyi_bilingual_product_name($product['name_zh'], $product_name);
                        } elseif ($receipt_bilingual && !empty($product['id'])) {
                            $name_zh = get_post_meta(intval($product['id']), '_product_name_zh', true);
                            if (!empty($name_zh)) $product_name = ruiyi_bilingual_product_name($name_zh, $product_name);
                        }
                        $product_price = isset($product['price']) ? floatval($product['price']) : 0;
                        $product_quantity = isset($product['quantity']) ? intval($product['quantity']) : 1;
                        $item_total = isset($product['total']) ? floatval($product['total']) : ($product_price * $product_quantity);
                        
                        ruiyi_debug_log("RUIYI POS: Processing product {$index}: {$product_name} - {$product_quantity}x €{$product_price} = €{$item_total}");
                        
                        $subtotal += $item_total;
                        ?>
                        <tr>
                        <?php if ($receipt_product_format_split === 'qty_first'): ?>
                            <td class="col-qty"><?php echo intval($product_quantity); ?></td>
                            <td class="item-name"><?php echo esc_html($product_name); ?></td>
                        <?php else: ?>
                            <td class="item-name"><?php echo esc_html($product_name); ?></td>
                            <td class="col-qty"><?php echo intval($product_quantity); ?></td>
                        <?php endif; ?>
                            <td class="col-price">€<?php echo number_format($product_price, 2); ?></td>
                            <td class="col-total">€<?php echo number_format($item_total, 2); ?></td>
                        </tr>
                        <?php
                    }
                }
                ?>
                </tbody>
            </table>
            
            <hr>
            
            <!-- 总计表格 -->
            <table class="totals-table">
                <?php
                // 验证分单总计与计算的小计是否一致
                $split_total = isset($split_order_data['total']) ? floatval($split_order_data['total']) : $subtotal;
                $discount_amount = isset($split_order_data['discountAmount']) ? floatval($split_order_data['discountAmount']) : 0;
                $original_total = $subtotal; // 原始总计（产品总价）
                $final_total = $split_total; // 最终总计（可能包含折扣后的价格）
                
                if (abs($split_total - $subtotal) > 0.01) {
                    ruiyi_debug_log("RUIYI POS: Split total mismatch - split_order_data[total]: €{$split_total}, calculated: €{$subtotal}");
                    // 如果有折扣信息，重新计算
                    if ($discount_amount > 0) {
                        $final_total = $subtotal - $discount_amount;
                    } else {
                        $final_total = $subtotal; // 使用计算的值
                    }
                }
                
                // 计算每个税率的税额
                $tax_groups = [];
                $total_pre_tax = 0;
                $total_tax = 0;

                // 遍历产品计算各税率的金额
                if (!empty($split_order_data['products'])) {
                    foreach ($split_order_data['products'] as $product) {
                        $product_price = isset($product['price']) ? floatval($product['price']) : 0;
                        $product_quantity = isset($product['quantity']) ? intval($product['quantity']) : 1;
                        $product_tax_rate = $receipt_tax_rate;
                        $item_total = $product_price * $product_quantity;

                        // 计算此产品的税前金额和税额
                        $item_pre_tax = $item_total / (1 + $product_tax_rate / 100);
                        $item_tax = $item_total - $item_pre_tax;

                        $total_pre_tax += $item_pre_tax;
                        $total_tax += $item_tax;

                        // 按税率分组
                        $tax_key = number_format($product_tax_rate, 0);
                        if (!isset($tax_groups[$tax_key])) {
                            $tax_groups[$tax_key] = [
                                'rate' => $product_tax_rate,
                                'base' => 0,
                                'tax' => 0
                            ];
                        }
                        $tax_groups[$tax_key]['base'] += $item_pre_tax;
                        $tax_groups[$tax_key]['tax'] += $item_tax;
                    }
                }

                // 如果没有税率信息，使用小票设置里的税率
                if (empty($tax_groups)) {
                    $total_pre_tax = $final_total / $receipt_tax_divisor;
                    $total_tax = $final_total - $total_pre_tax;
                    $tax_groups[number_format($receipt_tax_rate, 0)] = [
                        'rate' => $receipt_tax_rate,
                        'base' => $total_pre_tax,
                        'tax' => $total_tax
                    ];
                }

                // 按税率排序
                ksort($tax_groups);

                ruiyi_debug_log("RUIYI POS: Split receipt - Subtotal: €{$subtotal}, Discount: €{$discount_amount}, Final: €{$final_total}, Pre-tax: €{$total_pre_tax}, Total tax: €{$total_tax}");
                ?>
                <tr>
                    <td style="text-align:left;">SUBTOTAL:</td>
                    <td style="text-align:right;"><?php echo number_format($total_pre_tax, 2); ?>€</td>
                </tr>

                <?php if ($discount_amount > 0) : ?>
                <tr>
                    <td style="text-align:left;">DESCUENTO (PUNTOS):</td>
                    <td style="text-align:right;">-€<?php echo number_format($discount_amount / $receipt_tax_divisor, 2); ?></td>
                </tr>
                <?php endif; ?>

                <?php
                // 显示每个税率的税额
                foreach ($tax_groups as $tax_group) :
                ?>
                <tr>
                    <td style="text-align:left;"><?php echo esc_html($receipt_tax_label); ?>:</td>
                    <td style="text-align:right;"><?php echo number_format($tax_group['tax'], 2); ?>€</td>
                </tr>
                <?php endforeach; ?>
                
                <tr class="total-row">
                    <td style="text-align:left;">TOTAL:</td>
                    <td style="text-align:right;"><?php echo number_format($final_total, 2); ?>€</td>
                </tr>
            </table>
            
            <!-- 支付信息（西班牙语） -->
            <?php if (isset($split_order_data['paymentMethod']) && !empty($split_order_data['paymentMethod'])) : ?>
            <table class="totals-table">
                <tr>
                    <td style="text-align:left;">MÉTODO DE PAGO:</td>
                    <td style="text-align:right;"><?php echo ($split_order_data['paymentMethod'] === 'cash' ? 'EFECTIVO' : 'TARJETA'); ?></td>
                </tr>
                
                <?php if ($split_order_data['paymentMethod'] === 'cash' && isset($split_order_data['paymentDetails'])) :
                    $details = $split_order_data['paymentDetails'];
                    if (isset($details['receivedAmount'])) : ?>
                    <tr>
                        <td style="text-align:left;">RECIBIDO:</td>
                        <td style="text-align:right;"><?php echo number_format($details['receivedAmount'], 2); ?>€</td>
                    </tr>
                    <?php endif;
                    if (isset($details['changeAmount'])) : ?>
                    <tr>
                        <td style="text-align:left;">CAMBIO:</td>
                        <td style="text-align:right;"><?php echo number_format($details['changeAmount'], 2); ?>€</td>
                    </tr>
                    <?php endif;
                endif; ?>
            </table>
            <?php endif; ?>
            
            <hr>

            <?php
            // 添加分单订单的Verifactu二维码
            $verifactu_qr_base64 = null;

            // 如果分单订单已创建并且有订单ID，尝试获取Verifactu二维码
            if (isset($order) && $order && ruiyi_has_verifactu()) {
                $split_order_id = $order->get_id();
                ruiyi_debug_log('分单小票生成 - 尝试获取Verifactu二维码，订单ID: #' . $split_order_id);

                // 检查订单是否已有二维码
                $verifactu_qr_base64 = $order->get_meta('_verifactu_qr_base64');

                if (empty($verifactu_qr_base64)) {
                    ruiyi_debug_log('分单小票生成 - 订单尚无二维码，尝试生成');

                    // 如果订单状态是completed但没有二维码，尝试生成
                    if ($order->get_status() === 'completed') {
                        $verifactu_ref = ruiyi_get_verifactu_method('generate_and_store_qr');
                        if ($verifactu_ref) {
                            ruiyi_debug_log('分单小票生成 - 调用generate_and_store_qr方法');
                            $verifactu_ref->invoke(ruiyi_get_verifactu_instance(), $order, true);

                            // 直接读 meta，不重载整个订单对象
                            $verifactu_qr_base64 = get_post_meta($split_order_id, '_verifactu_qr_base64', true);
                            ruiyi_debug_log('分单小票生成 - 强制生成二维码' . ($verifactu_qr_base64 ? '成功' : '失败'));
                        } else {
                            ruiyi_debug_log('分单小票生成 - generate_and_store_qr方法不存在');
                        }
                    } else {
                        ruiyi_debug_log('分单小票生成 - 订单状态不是completed: ' . $order->get_status());
                    }
                } else {
                    ruiyi_debug_log('分单小票生成 - 找到现有的Verifactu二维码');
                }
            } else {
                if (!isset($order) || !$order) {
                    ruiyi_debug_log('分单小票生成 - 订单对象不存在');
                } else {
                    ruiyi_debug_log('分单小票生成 - WC_Verifactu_QR类不存在');
                }
            }

            // 显示Verifactu二维码（如果有）
            if (!empty($verifactu_qr_base64)): ?>
                <div style="text-align: center; margin-top: 5mm; margin-bottom: 3mm;">
                    <div style="font-weight: bold; font-size: 0.9em; margin-bottom: 2mm;">VERIFACTU QR</div>
                    <img src="data:image/png;base64,<?php echo esc_attr($verifactu_qr_base64); ?>"
                         alt="Verifactu QR Code"
                         style="max-width: 120px; max-height: 120px; margin: 0 auto; display: block;">
                    <div style="font-size: 0.8em; margin-top: 1mm; color: #666;">
                        Escanear para verificar factura
                    </div>
                </div>
                <hr>
            <?php else: ?>
                <?php ruiyi_debug_log('分单小票生成 - 未找到Verifactu二维码'); ?>
            <?php endif; ?>

            <!-- 页脚信息 -->
            <?php if (!empty($receipt_footer)) : ?>
            <div class="footer"><?php echo nl2br(esc_html($receipt_footer)); ?></div>
            <?php endif; ?>
        </div>
    </body>
    </html>
    <?php
    
    $html = ob_get_clean();
    
    // 调试：记录生成的HTML长度和开头部分
    ruiyi_debug_log('RUIYI POS: Generated HTML length: ' . strlen($html));
    ruiyi_debug_log('RUIYI POS: HTML starts with: ' . substr($html, 0, 200));
    
    // 确保HTML不为空
    if (empty($html) || strlen(trim($html)) < 100) {
        ruiyi_debug_log('RUIYI POS: Generated HTML is too short or empty');
        wp_send_json_error(array('message' => 'Generated HTML is empty or invalid'));
        return;
    }
    
    wp_send_json_success(array('html' => $html));
}

// 检查并更新原始订单状态
add_action('wp_ajax_ruiyi_pos_check_split_completion', 'ruiyi_pos_check_split_completion_callback');

function ruiyi_pos_check_split_completion_callback() {
    // 验证nonce
    check_ajax_referer('ruiyi_pos_nonce', 'nonce');
    
    $table_number = isset($_POST['table_number']) ? sanitize_text_field($_POST['table_number']) : '';
    $original_order_ids = isset($_POST['original_order_ids']) ? json_decode(stripslashes($_POST['original_order_ids']), true) : array();
    
    if (empty($table_number) || empty($original_order_ids)) {
        wp_send_json_error(array('message' => 'Missing required data'));
        return;
    }
    
    try {
        // 检查是否所有分单都已支付完成
        $split_payments = get_option('ruiyi_split_payments', array());
        $table_splits = isset($split_payments[$table_number]) ? $split_payments[$table_number] : array();
        
        $all_splits_completed = true;
        foreach ($table_splits as $split_id => $split_data) {
            if ($split_data['status'] !== 'completed') {
                $all_splits_completed = false;
                break;
            }
        }
        
        if ($all_splits_completed && !empty($table_splits)) {
            // 所有分单已完成，现在删除原始订单
            $deleted_orders_count = 0;
            foreach ($original_order_ids as $order_id) {
                $order = wc_get_order($order_id);
                if ($order) {
                    try {
                        // 记录删除的订单信息
                        $order_info = array(
                            'id' => $order->get_id(),
                            'total' => $order->get_total(),
                            'date' => $order->get_date_created()->format('Y-m-d H:i:s'),
                            'table_number' => $table_number,
                            'split_reason' => 'All split orders completed - deleting original order'
                        );
                        
                        ruiyi_debug_log('RUIYI POS: Deleting original order after all splits completed - ' . json_encode($order_info));
                        
                        // 🔥 永久删除订单（WC 原生删除，兼容 HPOS，不移至回收站）
                        $order->delete(true);
                        $deleted_orders_count++;
                        
                    } catch (Exception $delete_error) {
                        ruiyi_debug_log('Error deleting original order ' . $order_id . ': ' . $delete_error->getMessage());
                    }
                }
            }
            
            ruiyi_debug_log('RUIYI POS: Successfully deleted ' . $deleted_orders_count . ' original orders for table ' . $table_number);
            
            // 清理分单支付记录
            unset($split_payments[$table_number]);
            update_option('ruiyi_split_payments', $split_payments);
            
            // 🔥 原子清理实时桌位状态表（防止并发竞态）
            $table_number_numeric = preg_replace('/[^0-9]/', '', $table_number);
            ruiyi_update_single_table_status($table_number_numeric, array(
                'status' => 'libre',
                'orderId' => 0,
                'total' => 0,
                'timestamp' => time()
            ));
            ruiyi_debug_log("RUIYI POS: Table $table_number_numeric live status updated to 'libre' after split completion");
            
            // 🔥 修复：分单支付全部完成后，将桌位状态设置为空闲状态
            // 查找对应的桌子post ID - 通过标题匹配
            $table_query = new WP_Query([
                'post_type' => 'restaurant_table',
                'title' => "Mesa $table_number",
                'posts_per_page' => 1,
                'post_status' => 'publish'
            ]);
            
            $table_updated = false;
            if ($table_query->have_posts()) {
                $table_post_id = $table_query->posts[0]->ID;
                wp_reset_postdata();
                
                // 更新桌位状态为空闲
                update_post_meta($table_post_id, '_table_status', 'available');
                update_post_meta($table_post_id, '_current_order_id', '');
                update_post_meta($table_post_id, '_current_total', 0);
                
                $table_updated = true;
                ruiyi_debug_log("RUIYI POS: Table $table_number status updated to 'available' after split payment completion");
            } else {
                ruiyi_debug_log("RUIYI POS: Warning - Could not find table post for table number: $table_number");
            }
            
            wp_send_json_success(array(
                'message' => 'All split orders completed, original orders deleted, table status updated',
                'all_completed' => true,
                'deleted_original_orders' => $deleted_orders_count,
                'total_split_orders' => count($table_splits),
                'table_status_updated' => $table_updated,
                'table_number' => $table_number
            ));
        } else {
            wp_send_json_success(array(
                'message' => 'Split orders still pending',
                'all_completed' => false,
                'completed_splits' => count($table_splits)
            ));
        }
        
    } catch (Exception $e) {
        ruiyi_debug_log('Error checking split completion: ' . $e->getMessage());
        wp_send_json_error(array('message' => 'Failed to check split completion'));
    }
}

// 换台功能 - AJAX处理函数
add_action('wp_ajax_switch_table_orders', 'handle_switch_table_orders');
add_action('wp_ajax_nopriv_switch_table_orders', 'handle_switch_table_orders');

function handle_switch_table_orders() {
    // 验证nonce
    if (!check_ajax_referer('ruiyi_pos_nonce', 'nonce', false)) {
        wp_send_json_error(array('message' => 'Security check failed'));
        return;
    }
    
    $from_table = sanitize_text_field($_POST['from_table']);
    $to_table = sanitize_text_field($_POST['to_table']);

    // 🔥 获取完整桌位名称（用于精确匹配）
    $from_table_full = isset($_POST['from_table_full']) ? strtoupper(sanitize_text_field($_POST['from_table_full'])) : '';
    $to_table_full = isset($_POST['to_table_full']) ? strtoupper(sanitize_text_field($_POST['to_table_full'])) : '';

    if (empty($from_table) || empty($to_table)) {
        wp_send_json_error(array('message' => 'Missing table numbers'));
        return;
    }

    $all_mappings = function_exists('ruiyi_get_all_table_categories_mapping')
        ? ruiyi_get_all_table_categories_mapping()
        : array();

    $resolved_from = ruiyi_safe_extract_table_number($from_table, $all_mappings);
    if (empty($resolved_from) && !empty($from_table_full)) {
        $resolved_from = ruiyi_safe_extract_table_number($from_table_full, $all_mappings);
    }
    if (!empty($resolved_from)) {
        if (empty($from_table_full)) {
            $from_table_full = strtoupper($from_table);
        }
        ruiyi_debug_log("🔥 换台 from_table 安全解析: '{$from_table}' / '{$from_table_full}' → 全局编号 {$resolved_from}");
        $from_table = $resolved_from;
    }

    $resolved_to = ruiyi_safe_extract_table_number($to_table, $all_mappings);
    if (empty($resolved_to) && !empty($to_table_full)) {
        $resolved_to = ruiyi_safe_extract_table_number($to_table_full, $all_mappings);
    }
    if (!empty($resolved_to)) {
        if (empty($to_table_full)) {
            $to_table_full = strtoupper($to_table);
        }
        ruiyi_debug_log("🔥 换台 to_table 安全解析: '{$to_table}' / '{$to_table_full}' → 全局编号 {$resolved_to}");
        $to_table = $resolved_to;
    }

    try {
        global $wpdb;

        // 开始数据库事务
        $wpdb->query('START TRANSACTION');

        $table_number = ruiyi_safe_extract_table_number($from_table, $all_mappings);

        if (empty($table_number)) {
            $wpdb->query('ROLLBACK');
            wp_send_json_error(array('message' => 'Invalid table number format'));
            return;
        }

        ruiyi_debug_log("RUIYI POS: 换台 - 源桌位号: {$table_number}, 完整名称: {$from_table_full}");

        // 获取未结账的订单状态
        $unpaid_statuses = ['processing', 'on-hold', 'pending'];

        // 🔥 清除WooCommerce订单缓存，确保获取最新数据
        if (function_exists('wc_delete_shop_order_transients')) {
            wc_delete_shop_order_transients();
        }
        wp_cache_delete('wc_orders_cache_group', 'orders');

        // 使用 WooCommerce 的 wc_get_orders 函数
        $args = [
            'status' => $unpaid_statuses,
            'limit' => -1,
            'orderby' => 'date',
            'order' => 'ASC',
            'return' => 'objects',
            'cache' => false,  // 🔥 禁用缓存
        ];
        $all_relevant_orders = wc_get_orders($args);

        ruiyi_debug_log("RUIYI POS: 换台 - 找到的相关状态订单数量: " . count($all_relevant_orders));

        $orders_for_this_table = [];

        // 构建源桌位的安全匹配标识
        $from_table_full_upper = ruiyi_normalize_table_identifier($from_table_full);

        // 🔥 构建所有可能的匹配目标
        $possible_table_formats = array(
            $table_number,                              // "2" - 纯数字
            "Mesa " . $table_number,                    // "Mesa 2"
            "MESA " . $table_number,                    // "MESA 2"
            "Mesa" . $table_number,                     // "Mesa2"
            "MESA" . $table_number,                     // "MESA2"
            "餐桌 " . $table_number,                    // "餐桌 2"
            "餐桌" . $table_number,                     // "餐桌2"
            "Table " . $table_number,                   // "Table 2"
            $from_table_full,                           // "COMEDOR2"
            $from_table_full_upper,                     // "COMEDOR2" (normalized)
        );
        // 移除空值和重复值
        $possible_table_formats = array_unique(array_filter($possible_table_formats));
        $normalized_source_identifiers = array_unique(array_filter(array_map('ruiyi_normalize_table_identifier', $possible_table_formats)));

        ruiyi_debug_log("RUIYI POS: 换台 - 匹配参数: table_number={$table_number}, from_table_full={$from_table_full}, 可能格式: " . implode(', ', $possible_table_formats));

        if (!empty($all_relevant_orders)) {
            foreach ($all_relevant_orders as $order) {
                $post = get_post($order->get_id());
                if ($post && $post->post_status === 'trash') {
                    continue;
                }
                if ($order->get_meta('_is_merged') === 'yes') {
                    continue;
                }

                $order_table_meta = $order->get_meta('_table_number', true);
                $order_display_name = $order->get_meta('_table_display_name', true);

                // 也检查一下不带下划线的版本
                if (empty($order_table_meta)) {
                    $order_table_meta = $order->get_meta('table_number', true);
                }

                if (empty($order_table_meta)) {
                    continue;
                }

                // 🔥 规范化订单桌号
                $order_table_normalized = ruiyi_normalize_table_identifier($order_table_meta);
                $order_table_upper = strtoupper(trim($order_table_meta));
                $order_display_normalized = ruiyi_normalize_table_identifier($order_display_name);
                $order_table_numeric = ruiyi_safe_extract_table_number($order_table_meta, $all_mappings);
                $order_display_numeric = ruiyi_safe_extract_table_number($order_display_name, $all_mappings);

                ruiyi_debug_log("RUIYI POS: 换台 - 检查订单 #{$order->get_id()}, 桌位: '{$order_table_meta}', 显示名: '{$order_display_name}', 数字: '{$order_table_numeric}', 规范化: '{$order_table_normalized}'");

                $is_match = false;
                $match_type = '';

                // 🔥 优先级1：完整桌位名 / 显示桌名精确匹配
                if (!empty($from_table_full_upper) && ($order_table_normalized === $from_table_full_upper || $order_display_normalized === $from_table_full_upper || $order_table_upper === strtoupper($from_table_full))) {
                    $is_match = true;
                    $match_type = '完整名称或显示名精确匹配';
                }
                // 🔥 优先级2：检查是否匹配任何标准化源标识
                elseif (in_array($order_table_normalized, $normalized_source_identifiers, true) ||
                        (!empty($order_display_normalized) && in_array($order_display_normalized, $normalized_source_identifiers, true))) {
                    $is_match = true;
                    $match_type = '标准化标识匹配';
                }
                // 🔥 优先级3：安全全局桌号匹配
                elseif (!empty($order_table_numeric) && $order_table_numeric === $table_number) {
                    $is_match = true;
                    $match_type = "安全全局桌号匹配: '{$order_table_numeric}' === '{$table_number}'";
                } elseif (!empty($order_display_numeric) && $order_display_numeric === $table_number) {
                    $is_match = true;
                    $match_type = "显示名全局桌号匹配: '{$order_display_numeric}' === '{$table_number}'";
                }

                if ($is_match) {
                    $orders_for_this_table[] = $order;
                    ruiyi_debug_log("RUIYI POS: 换台 - ✅ 匹配成功 [{$match_type}]: 订单 #{$order->get_id()}, 桌位: '{$order_table_meta}'");
                }
            }
        }
        
        $order_ids = array_map(function($order) { return $order->get_id(); }, $orders_for_this_table);
        
        ruiyi_debug_log("RUIYI POS: 换台 - 最终找到的订单IDs: " . json_encode($order_ids));
        
        if (empty($order_ids)) {
            $wpdb->query('ROLLBACK');
            wp_send_json_error(array('message' => 'No orders found for source table'));
            return;
        }
        
        // 批量更新订单的桌号
        // 🔥 关键修复：使用全局桌位号格式 "Mesa X"，而不是显示名称 "DOMICILIO1"
        // 这样才能与系统内部的桌位识别逻辑保持一致（删除产品时通过数字部分匹配）
        // $to_table 包含目标桌位的全局编号（如 "11"）
        $target_table_name = "Mesa " . $to_table;

        $updated_count = 0;
        foreach ($orders_for_this_table as $order) {
            try {
                // 使用WooCommerce订单对象更新桌号
                $order->update_meta_data('_table_number', $target_table_name);
                // 🔥 同时保存显示名称用于显示目的
                if (!empty($to_table_full)) {
                    $order->update_meta_data('_table_display_name', $to_table_full);
                }
                $order->save();
                $updated_count++;

                ruiyi_debug_log("RUIYI POS: 换台 - 订单 #{$order->get_id()} 桌号已更新为: {$target_table_name}" . (!empty($to_table_full) ? " (显示名: {$to_table_full})" : ""));
            } catch (Exception $e) {
                ruiyi_debug_log("RUIYI POS: 换台 - 更新订单 #{$order->get_id()} 失败: " . $e->getMessage());
            }
        }
        
        // 检查是否所有订单都更新成功
        if ($updated_count === count($orders_for_this_table)) {
            // 更新桌位状态表
            try {
                // 清除原桌位状态（标记为空闲）
                $from_table_numeric = preg_replace('/[^0-9]/', '', $from_table);
                if (!empty($from_table_numeric)) {
                    ruiyi_debug_log("RUIYI POS: 换台 - 更新原桌位 {$from_table_numeric} 状态为空闲");
                    
                    // 使用与其他地方相同的状态更新方法
                    $pending_updates = get_option('ruiyi_pos_pending_table_updates', array());
                    $pending_updates[$from_table_numeric] = array(
                        'status' => 'available', // 使用正确的状态值
                        'orderId' => null,
                        'total' => 0,
                        'timestamp' => time()
                    );
                    update_option('ruiyi_pos_pending_table_updates', $pending_updates, 'no');
                }
                
                // 计算目标桌位总价
                $target_total = 0;
                foreach ($orders_for_this_table as $order) {
                    $target_total += $order->get_total();
                }
                
                // 更新目标桌位状态（标记为占用）
                $to_table_numeric = preg_replace('/[^0-9]/', '', $to_table);
                if (!empty($to_table_numeric)) {
                    ruiyi_debug_log("RUIYI POS: 换台 - 更新目标桌位 {$to_table_numeric} 状态为占用，总价: {$target_total}");
                    
                    $pending_updates[$to_table_numeric] = array(
                        'status' => 'occupied',
                        'orderId' => $orders_for_this_table[0]->get_id(),
                        'total' => $target_total,
                        'timestamp' => time()
                    );
                    update_option('ruiyi_pos_pending_table_updates', $pending_updates, 'no');
                }
                
            } catch (Exception $e) {
                ruiyi_debug_log("RUIYI POS: 换台 - 更新桌位状态失败: " . $e->getMessage());
            }
            
            $wpdb->query('COMMIT');
            
            wp_send_json_success(array(
                'message' => 'Table switch completed successfully',
                'from_table' => $from_table,
                'to_table' => $to_table,
                'updated_orders' => $updated_count,
                'order_ids' => $order_ids,
                'total' => $target_total, // 🔥🔥🔥 【2026-01-30 新增】返回订单总额
                'order_id' => !empty($orders_for_this_table) ? $orders_for_this_table[0]->get_id() : null
            ));
        } else {
            $wpdb->query('ROLLBACK');
            wp_send_json_error(array('message' => 'Failed to update all orders'));
        }
        
    } catch (Exception $e) {
        $wpdb->query('ROLLBACK');
        ruiyi_debug_log('Error switching table orders: ' . $e->getMessage());
        wp_send_json_error(array('message' => 'Database error: ' . $e->getMessage()));
    }
}

// 批量检测桌位状态的AJAX处理函数
add_action('wp_ajax_ruiyi_batch_check_table_status', 'ruiyi_batch_check_table_status_callback');
add_action('wp_ajax_nopriv_ruiyi_batch_check_table_status', 'ruiyi_batch_check_table_status_callback');

function ruiyi_batch_check_table_status_callback() {
    // 验证nonce
    check_ajax_referer('ruiyi_pos_nonce', 'nonce');

    // 🔧 添加权限验证
    $user = wp_get_current_user();
    $allowed_roles = [
        'administrator', 'shop_manager', 'pos_user', 'editor', 'author',
        'waiter', 'chef', 'cook', 'cashier', 'subscriber'
    ];
    if (!is_user_logged_in() || !array_intersect($allowed_roles, $user->roles)) {
        wp_send_json_error(['message' => 'Permiso denegado']);
        return;
    }

    ruiyi_debug_log('[批量检测] 开始批量检测所有桌位状态...');
    
    try {
        // 获取所有未完成的订单
        $unpaid_statuses = ['processing', 'on-hold', 'pending'];
        $all_orders = wc_get_orders([
            'status' => $unpaid_statuses,
            'limit' => -1
        ]);
        
        ruiyi_debug_log('[批量检测] 找到未完成订单数量: ' . count($all_orders));
        
        // 构建桌位订单映射
        $table_orders_map = [];
        $table_totals_map = [];
        
        foreach ($all_orders as $order) {
            $table_number = $order->get_meta('_table_number', true);
            
            if (!empty($table_number)) {
                // 标准化桌号为数字
                $table_number_numeric = preg_replace('/[^0-9]/', '', $table_number);
                
                if (!empty($table_number_numeric)) {
                    if (!isset($table_orders_map[$table_number_numeric])) {
                        $table_orders_map[$table_number_numeric] = [];
                        $table_totals_map[$table_number_numeric] = 0;
                    }
                    
                    $table_orders_map[$table_number_numeric][] = [
                        'id' => $order->get_id(),
                        'total' => $order->get_total(),
                        'status' => $order->get_status()
                    ];
                    
                    $table_totals_map[$table_number_numeric] += $order->get_total();
                }
            }
        }
        
        ruiyi_debug_log('[批量检测] 有订单的桌位: ' . json_encode(array_keys($table_orders_map)));

        // 获取当前桌位状态（从localStorage角度 - 通过前端传递或者从服务器状态表获取）
        $live_statuses = get_option('ruiyi_pos_live_table_statuses', []);
        ruiyi_debug_log('[批量检测] live_statuses内容: ' . json_encode($live_statuses));
        $abnormal_tables = [];
        
        // 检查1-120号桌位
        for ($i = 1; $i <= 120; $i++) {
            $has_orders = isset($table_orders_map[$i]) && count($table_orders_map[$i]) > 0;
            $server_status = isset($live_statuses[$i]) ? $live_statuses[$i]['status'] : 'available';

            // 如果服务器状态显示占用但实际没有订单，标记为异常
            // 注意：live_statuses中存储的是'ocupada'而不是'occupied'
            if (($server_status === 'occupied' || $server_status === 'ocupada') && !$has_orders) {
                $abnormal_tables[] = "餐桌 $i";
                ruiyi_debug_log("[批量检测] 发现异常桌位 $i: 服务器状态=$server_status, 实际订单=无");
            }
        }
        
        ruiyi_debug_log('[批量检测] 异常桌位数量: ' . count($abnormal_tables));
        
        wp_send_json_success([
            'abnormal_tables' => $abnormal_tables,
            'table_status_map' => $table_totals_map,
            'total_tables_checked' => 120,
            'tables_with_orders' => count($table_orders_map),
            'abnormal_count' => count($abnormal_tables)
        ]);
        
    } catch (Exception $e) {
        ruiyi_debug_log('[批量检测] 异常: ' . $e->getMessage());
        wp_send_json_error([
            'message' => '批量检测失败: ' . $e->getMessage()
        ]);
    }
}

// 处理包含公司钱票的订单支付
function ruiyi_pos_process_order_with_company_ticket() {
    // 验证nonce
    if (!isset($_POST['nonce']) || !wp_verify_nonce($_POST['nonce'], 'ruiyi_pos_nonce')) {
        wp_send_json_error(['message' => ruiyi_translate('安全验证失败', 'Security verification failed', '安全验证失败')]);
        return;
    }
    
    // 验证用户权限
    if (!is_user_logged_in()) {
        wp_send_json_error(['message' => ruiyi_translate('用户未登录', 'User not logged in', '用户未登录')]);
        return;
    }
    
    try {
        $order_ids_raw = isset($_POST['order_ids']) ? $_POST['order_ids'] : '';
        if (is_string($order_ids_raw)) {
            $order_ids_decoded = json_decode(stripslashes($order_ids_raw), true);
            $order_ids = is_array($order_ids_decoded) ? array_map('intval', $order_ids_decoded) : [];
        } else {
            $order_ids = is_array($order_ids_raw) ? array_map('intval', $order_ids_raw) : [];
        }
        
        $payment_method = isset($_POST['payment_method']) ? sanitize_text_field($_POST['payment_method']) : '';
        $company_ticket_amount = isset($_POST['company_ticket_amount']) ? floatval($_POST['company_ticket_amount']) : 0;
        $original_total_amount = isset($_POST['original_total_amount']) ? floatval($_POST['original_total_amount']) : 0;
        $current_total = isset($_POST['total_amount']) ? floatval($_POST['total_amount']) : 0;
        $ticket_change_amount = isset($_POST['ticket_change_amount']) ? floatval($_POST['ticket_change_amount']) : 0;
        $table_number = isset($_POST['table_number']) ? sanitize_text_field($_POST['table_number']) : '';
        
        // 处理纯公司钱票支付（无其他支付方式）
        if ($payment_method === 'company_ticket_only') {
            $current_total = 0; // 纯公司钱票支付，剩余为0
        }
        
        // 验证必要参数
        if (empty($order_ids)) {
            throw new Exception(ruiyi_translate('订单ID缺失', 'Order IDs missing', '订单ID缺失'));
        }
        
        if ($company_ticket_amount <= 0) {
            throw new Exception(ruiyi_translate('公司钱票金额无效', 'Invalid company ticket amount', '公司钱票金额无效'));
        }
        
        ruiyi_debug_log("[公司钱票支付] 处理订单 - IDs: " . json_encode($order_ids) .
                 ", 公司钱票: €{$company_ticket_amount}, 原始总额: €{$original_total_amount}, 当前应付: €{$current_total}, 支付方式: {$payment_method}, 桌号: {$table_number}");
        
        $processed_orders = [];
        
        foreach ($order_ids as $order_id) {
            $order = wc_get_order($order_id);
            if (!$order) {
                continue;
            }
            
            // 设置支付方式为公司钱票或组合支付
            if ($current_total <= 0) {
                // 完全用公司钱票支付
                $order->update_status('completed', ruiyi_translate('公司钱票支付完成', 'Company ticket payment completed', '公司钱票支付完成'));
                $order->update_meta_data('_payment_method', 'company_ticket');
                // 根据是否有找零添加不同的订单备注
                if ($ticket_change_amount > 0) {
                    $order->add_order_note(sprintf(
                        ruiyi_translate('公司钱票支付完成 - 票额: €%.2f, 原始订单: €%.2f, 找零: €%.2f', 'Company ticket payment completed - Ticket: €%.2f, Original order: €%.2f, Change: €%.2f', '公司钱票支付完成 - 票额: €%.2f, 原始订单: €%.2f, 找零: €%.2f'),
                        $company_ticket_amount,
                        $original_total_amount,
                        $ticket_change_amount
                    ));
                } else {
                    $order->add_order_note(sprintf(
                        ruiyi_translate('公司钱票支付完成 - 票额: €%.2f, 原始订单: €%.2f', 'Company ticket payment completed - Ticket: €%.2f, Original order: €%.2f', '公司钱票支付完成 - 票额: €%.2f, 原始订单: €%.2f'),
                        $company_ticket_amount,
                        $original_total_amount
                    ));
                }
            } else {
                // 公司钱票+其他支付方式的组合
                $other_payment_amount = 0;
                if ($payment_method === 'cash') {
                    $other_payment_amount = isset($_POST['received_amount']) ? floatval($_POST['received_amount']) : $current_total;
                } elseif ($payment_method === 'mixed') {
                    $cash_part = isset($_POST['cash_amount']) ? floatval($_POST['cash_amount']) : 0;
                    $card_part = isset($_POST['card_amount']) ? floatval($_POST['card_amount']) : 0;
                    $other_payment_amount = $cash_part + $card_part;
                } else {
                    $other_payment_amount = $current_total; // 刷卡支付
                }
                
                $order->update_status('completed', ruiyi_translate('组合支付完成', 'Combined payment completed', '组合支付完成'));
                $order->update_meta_data('_payment_method', 'company_ticket_combined');
                
                // 根据支付方式添加不同的订单备注
                if ($payment_method === 'mixed') {
                    $cash_part = isset($_POST['cash_amount']) ? floatval($_POST['cash_amount']) : 0;
                    $card_part = isset($_POST['card_amount']) ? floatval($_POST['card_amount']) : 0;
                    $order->add_order_note(sprintf(
                        ruiyi_translate('组合支付完成 - 公司钱票: €%.2f, 现金: €%.2f, 刷卡: €%.2f, 原始订单: €%.2f', 'Combined payment completed - Company ticket: €%.2f, Cash: €%.2f, Card: €%.2f, Original order: €%.2f', '组合支付完成 - 公司钱票: €%.2f, 现金: €%.2f, 刷卡: €%.2f, 原始订单: €%.2f'),
                        $company_ticket_amount,
                        $cash_part,
                        $card_part,
                        $original_total_amount
                    ));
                } else {
                    $payment_method_name = '';
                    if ($payment_method === 'cash') {
                        $payment_method_name = ruiyi_translate('现金', 'Cash', '现金');
                    } elseif ($payment_method === 'card') {
                        $payment_method_name = ruiyi_translate('刷卡', 'Card', '刷卡');
                    }
                    
                    $order->add_order_note(sprintf(
                        ruiyi_translate('组合支付完成 - 公司钱票: €%.2f, %s: €%.2f, 原始订单: €%.2f', 'Combined payment completed - Company ticket: €%.2f, %s: €%.2f, Original order: €%.2f', '组合支付完成 - 公司钱票: €%.2f, %s: €%.2f, 原始订单: €%.2f'),
                        $company_ticket_amount,
                        $payment_method_name,
                        $other_payment_amount,
                        $original_total_amount
                    ));
                }
                
                // 保存其他支付方式的详细信息
                if ($payment_method === 'cash') {
                    $order->update_meta_data('_payment_cash_amount', $other_payment_amount);
                    $order->update_meta_data('_received_amount', isset($_POST['received_amount']) ? floatval($_POST['received_amount']) : 0);
                    $order->update_meta_data('_change_amount', isset($_POST['change_amount']) ? floatval($_POST['change_amount']) : 0);
                } elseif ($payment_method === 'mixed') {
                    $order->update_meta_data('_payment_cash_amount', isset($_POST['cash_amount']) ? floatval($_POST['cash_amount']) : 0);
                    $order->update_meta_data('_payment_card_amount', isset($_POST['card_amount']) ? floatval($_POST['card_amount']) : 0);
                } elseif ($payment_method === 'card') {
                    $order->update_meta_data('_payment_card_amount', $other_payment_amount);
                }
            }
            
            // 保存公司钱票相关的元数据
            $order->update_meta_data('_company_ticket_amount', $company_ticket_amount);
            $order->update_meta_data('_original_total_amount', $original_total_amount);
            $order->update_meta_data('_payment_current_total', $current_total);
            $order->update_meta_data('_company_ticket_processed', current_time('mysql'));
            
            // 保存找零信息（如果有）
            if ($ticket_change_amount > 0) {
                $order->update_meta_data('_ticket_change_amount', $ticket_change_amount);
            }
            
            $order->save();
            
            $processed_orders[] = [
                'id' => $order_id,
                'total' => $order->get_total(), // 使用订单实际总额，确保小票显示正确
                'status' => $order->get_status()
            ];
            
            ruiyi_debug_log("[公司钱票支付] 订单 #{$order_id} 处理完成");
        }
        
        // 更新桌位状态
        if (!empty($table_number)) {
            $table_number_numeric = preg_replace('/[^0-9]/', '', $table_number);
            if (!empty($table_number_numeric)) {
                $pending_updates = get_option('ruiyi_pos_pending_table_updates', array());
                $pending_updates[$table_number_numeric] = array(
                    'status' => 'available',
                    'orderId' => null,
                    'total' => 0,
                    'timestamp' => time()
                );
                update_option('ruiyi_pos_pending_table_updates', $pending_updates, 'no');
                ruiyi_debug_log("[公司钱票支付] 桌位 {$table_number} 已更新为空闲状态");
            }
        }
        
        wp_send_json_success([
            'message' => ruiyi_translate('公司钱票支付完成', 'Company ticket payment completed', '公司钱票支付完成'),
            'processed_orders' => $processed_orders,
            'company_ticket_amount' => $company_ticket_amount,
            'original_total' => $original_total_amount,
            'current_total' => $current_total,
            'table_number' => $table_number
        ]);
        
    } catch (Exception $e) {
        ruiyi_debug_log("[公司钱票支付] 错误: " . $e->getMessage());
        wp_send_json_error([
            'message' => ruiyi_translate('公司钱票支付失败', 'Company ticket payment failed', '公司钱票支付失败') . ': ' . $e->getMessage()
        ]);
    }
}

