// 清理pending积分交易的AJAX处理函数
function ruiyi_clear_pending_points_transaction() {
    // 验证nonce
    if (!isset($_POST['nonce']) || !wp_verify_nonce($_POST['nonce'], 'ruiyi_pos_nonce')) {
        wp_send_json_error(['message' => '安全验证失败']);
        return;
    }
    
    // 删除pending积分交易
    $deleted = delete_option('ruiyi_pending_points_transaction');
    
    if ($deleted) {
        ruiyi_debug_log('[积分清理] 已清理pending积分交易');
        wp_send_json_success(['message' => '已清理pending积分交易']);
    } else {
        wp_send_json_success(['message' => '无pending积分交易需要清理']);
    }
}

add_action('wp_ajax_ruiyi_clear_pending_points_transaction', 'ruiyi_clear_pending_points_transaction');
add_action('wp_ajax_nopriv_ruiyi_clear_pending_points_transaction', 'ruiyi_clear_pending_points_transaction');

// ========================================
// 解除WordPress后台访问限制 - RUIYI POS Manager主题
// ========================================

// 允许所有登录用户访问后台所有页面
add_filter('user_has_cap', 'ruiyi_grant_all_admin_capabilities', 999, 4);
function ruiyi_grant_all_admin_capabilities($allcaps, $caps, $args, $user) {
    if (is_user_logged_in() && is_admin()) {
        // 为所有已登录用户在后台授予所有权限
        foreach ($caps as $cap) {
            $allcaps[$cap] = true;
        }
        
        // 添加基础管理权限
        $admin_caps = array(
            'read', 'edit_posts', 'edit_others_posts', 'edit_published_posts',
            'publish_posts', 'delete_posts', 'delete_others_posts', 'delete_published_posts',
            'edit_pages', 'edit_others_pages', 'edit_published_pages', 'publish_pages',
            'delete_pages', 'delete_others_pages', 'delete_published_pages',
            'manage_categories', 'manage_links', 'upload_files', 'manage_options',
            'moderate_comments', 'manage_themes', 'activate_plugins', 'edit_users',
            'list_users', 'manage_woocommerce', 'view_woocommerce_reports', 'edit_shop_orders',
            'edit_shop_coupons', 'edit_products', 'manage_product_terms', 'edit_product_terms',
            'delete_product_terms', 'assign_product_terms', 'manage_woo_commerce',
            'view_admin_dashboard', 'edit_theme_options', 'customize', 'switch_themes'
        );
        
        foreach ($admin_caps as $cap) {
            $allcaps[$cap] = true;
        }
    }
    return $allcaps;
}

// 在admin_init时提升用户权限
add_action('admin_init', 'ruiyi_enhance_user_admin_access', 1);
function ruiyi_enhance_user_admin_access() {
    if (is_user_logged_in()) {
        global $current_user;
        
        // 临时添加必要权限给当前用户
        $essential_caps = array(
            'read', 'manage_options', 'edit_posts', 'manage_woocommerce',
            'view_woocommerce_reports', 'edit_shop_orders', 'edit_products',
            'manage_themes', 'customize', 'edit_theme_options'
        );
        
        foreach ($essential_caps as $cap) {
            $current_user->add_cap($cap);
        }
    }
}

// 绕过权限映射
add_filter('map_meta_cap', 'ruiyi_bypass_capability_mapping', 1, 4);
function ruiyi_bypass_capability_mapping($caps, $cap, $user_id, $args) {
    if (is_user_logged_in() && is_admin()) {
        return array('read'); // 只需要基本的read权限
    }
    return $caps;
}

// 确保所有用户都能看到后台工具栏
add_filter('show_admin_bar', '__return_true', 999);

// 修复PHP 8.1弃用警告
add_action('init', 'ruiyi_suppress_php_deprecation_warnings');
function ruiyi_suppress_php_deprecation_warnings() {
    // 隐藏弃用警告（仅用于后台）
    if (is_admin()) {
        error_reporting(E_ALL & ~E_DEPRECATED & ~E_STRICT);
    }
}

// 额外的权限绕过 - 针对特定页面
add_action('current_screen', 'ruiyi_grant_screen_access');
function ruiyi_grant_screen_access($screen) {
    if (is_user_logged_in() && is_admin()) {
        global $current_user;
        
        // 根据当前页面添加特定权限
        switch ($screen->id) {
            case 'woocommerce_page_wc-settings':
            case 'woocommerce_page_wc-status':
            case 'woocommerce_page_wc-reports':
                $current_user->add_cap('manage_woocommerce');
                $current_user->add_cap('view_woocommerce_reports');
                break;
                
            case 'themes':
            case 'customize':
                $current_user->add_cap('manage_themes');
                $current_user->add_cap('edit_theme_options');
                $current_user->add_cap('customize');
                break;
                
            case 'plugins':
                $current_user->add_cap('activate_plugins');
                $current_user->add_cap('manage_options');
                break;
                
            default:
                // 为未知页面添加基本权限
                $current_user->add_cap('read');
                $current_user->add_cap('manage_options');
                break;
        }
    }
}

// 移除WordPress的核心权限检查
add_action('admin_head', 'ruiyi_remove_capability_restrictions', 1);
function ruiyi_remove_capability_restrictions() {
    if (is_user_logged_in()) {
        // 移除可能阻止访问的过滤器
        remove_all_filters('user_cannot_access_admin');
        
        // 确保当前用户有基础权限
        global $current_user;
        if (!$current_user->has_cap('read')) {
            $current_user->add_cap('read');
        }
    }
}

// 隐藏WordPress后台中的wp-first-item类元素和WooCommerce首页选项
add_action('admin_head', 'ruiyi_hide_wp_first_item');
function ruiyi_hide_wp_first_item() {
    echo '<style>
        /* 不隐藏wp-first-item，因为会影响正常菜单项 */
        
        /* 只隐藏WooCommerce首页菜单项 - 使用更精确的选择器 */
        #adminmenu li.toplevel_page_woocommerce .wp-submenu a[href*="page=wc-admin"]:not([href*="page=wc-admin&path"]) {
            display: none !important;
        }
        
        /* 隐藏WooCommerce子菜单中指向wc-admin主页的链接 */
        #adminmenu li.toplevel_page_woocommerce .wp-submenu li a[href="admin.php?page=wc-admin"] {
            display: none !important;
        }
        
        /* 隐藏包含WooCommerce首页链接的li元素 */
        #adminmenu li.toplevel_page_woocommerce .wp-submenu li:has(a[href="admin.php?page=wc-admin"]) {
            display: none !important;
        }
    </style>';
}

// 重定向WooCommerce设置向导页面到订单管理页面
add_action('admin_init', 'ruiyi_redirect_wc_setup_wizard');
function ruiyi_redirect_wc_setup_wizard() {
    // 检查是否正在访问WooCommerce设置向导或主页
    if (isset($_GET['page']) && $_GET['page'] === 'wc-admin') {
        // 检查是否是设置向导页面
        if (isset($_GET['path']) && strpos($_GET['path'], 'setup-wizard') !== false) {
            // 重定向到订单管理页面
            wp_redirect(admin_url('edit.php?post_type=shop_order'));
            exit;
        }

        // 如果只是访问wc-admin主页（没有具体路径），也重定向到订单页面
        if (!isset($_GET['path']) || $_GET['path'] === '' || $_GET['path'] === '/') {
            wp_redirect(admin_url('edit.php?post_type=shop_order'));
            exit;
        }
    }
}

