add_action('admin_init', 'clodop_admin_init');
function clodop_admin_init() {
    // 注册设置选项
    register_setting('clodop_settings', 'clodop_enabled');
    register_setting('clodop_settings', 'clodop_default_printer');
    register_setting('clodop_settings', 'clodop_drawer_printer');
    register_setting('clodop_settings', 'clodop_kitchen_printer'); // 厨房打印机
    register_setting('clodop_settings', 'clodop_kitchen_table_display_mode'); // 厨房小票桌号显示方式
    register_setting('clodop_settings', 'clodop_open_drawer_on_card'); // 刷卡支付后打开钱箱
    register_setting('clodop_settings', 'clodop_category_printer_enabled'); // 启用分类打印机
    register_setting('clodop_settings', 'clodop_separate_ticket_per_category'); // 每个分类单独打印一张小票
    register_setting('clodop_settings', 'clodop_kitchen_copy_to_default'); // 厨房小票同时从默认打印机打印一份
}

