        update_option('clodop_open_drawer_on_card', isset($_POST['clodop_open_drawer_on_card']) ? 1 : 0); // 刷卡支付后打开钱箱
        update_option('clodop_category_printer_enabled', isset($_POST['clodop_category_printer_enabled']) ? 1 : 0); // 启用分类打印机
