        update_option('clodop_kitchen_copy_to_default', isset($_POST['clodop_kitchen_copy_to_default']) ? 1 : 0); // 厨房小票同时从默认打印机打印一份

        // 🔥 厨房打印分类过滤（与POS设置页共用同一个 option）
