        </form>

        <!-- 说明信息 -->
        <div class="card" style="max-width: none; margin-top: 20px;">
            <h2>📋 使用说明</h2>
            <ul>
                <li><strong>服务要求：</strong>确保 CLODOP 服务已安装并运行在 localhost:8000 或 localhost:18000</li>
                <li><strong>打印机要求：</strong>确保目标打印机已连接并在 CLODOP 中可见</li>
                <li><strong>功能范围：</strong>启用后影响所有4个POS打印触发点（订单完成、外卖、餐桌结账、AA制分单）</li>
                <li><strong>降级处理：</strong>如果 CLODOP 不可用，系统会自动回退到浏览器打印方式</li>
            </ul>
        </div>
    </div>

    <script>
    let LODOP = null;

    jQuery(document).ready(function($) {
        // 页面加载时自动检测服务
        setTimeout(function() {
            checkClodopService();
        }, 1000);

        // 手动检测服务按钮
        $('#check-clodop-service').click(function() {
            checkClodopService();
        });

        // 测试打印按钮
        $('#test-clodop-print').click(function() {
            testClodopPrint();
        });

        // 测试钱箱按钮
        $('#test-clodop-drawer').click(function() {
            testClodopDrawer();
        });

        // 测试厨房打印按钮
        $('#test-clodop-kitchen').click(function() {
            testClodopKitchen();
        });

        // 分类打印机开关切换显示
        $('#clodop_category_printer_enabled').on('change', function() {
            if ($(this).is(':checked')) {
                $('#category-printer-preview-row').show();
                $('#separate-ticket-row').show();
                loadCategoryPrinterEditor();
            } else {
                $('#category-printer-preview-row').hide();
                $('#separate-ticket-row').hide();
            }
        });

        // 页面加载时如果已启用分类打印机则加载编辑器
        if ($('#clodop_category_printer_enabled').is(':checked')) {
            setTimeout(loadCategoryPrinterEditor, 1500);
        }

        // 刷新打印机列表按钮
        $('#refresh-category-printers').on('click', function() {
            loadCategoryPrinterEditor();
        });

        // 保存分类打印机配置按钮
        $('#save-category-printers').on('click', function() {
            saveCategoryPrinters();
        });

        // 存储可用打印机列表
        let availablePrinters = [];

        // 加载分类打印机编辑器
        function loadCategoryPrinterEditor() {
            $('#category-printer-list').html('<p><span class="spinner is-active" style="float: none; margin: 0 5px 0 0;"></span>正在加载分类和打印机列表...</p>');
            $('#category-printer-save-status').html('');

            // 首先获取打印机列表
            loadPrintersForCategoryEditor(function(printers) {
                availablePrinters = printers;

                // 然后获取分类列表
                $.post(ajaxurl, {
                    action: 'ruiyi_get_category_printers_preview',
                    nonce: '<?php echo wp_create_nonce("ruiyi_admin_nonce"); ?>'
                }, function(response) {
                    if (response.success && response.data.categories) {
                        renderCategoryPrinterEditor(response.data.categories, printers);
                    } else {
                        $('#category-printer-list').html('<p style="color:#d63638;">加载分类失败，请刷新页面重试</p>');
                    }
                }).fail(function() {
                    $('#category-printer-list').html('<p style="color:#d63638;">网络错误，请刷新页面重试</p>');
                });
            });
        }

        // 加载打印机列表（用于分类编辑器）
        function loadPrintersForCategoryEditor(callback) {
            if (typeof getLodop === 'undefined') {
                callback([]);
                return;
            }

            try {
                const lodop = getLodop();
                if (!lodop) {
                    callback([]);
                    return;
                }

                const count = lodop.GET_PRINTER_COUNT();
                const printers = [];
                for (let i = 0; i < count; i++) {
                    const name = lodop.GET_PRINTER_NAME(i);
                    if (name) {
                        printers.push(name);
                    }
                }
                callback(printers);
            } catch (e) {
                console.error('获取打印机列表失败:', e);
                callback([]);
            }
        }

        // 渲染分类打印机编辑器
        function renderCategoryPrinterEditor(categories, printers) {
            let html = '<table class="widefat" style="background: #fff;">';
            html += '<thead><tr><th style="padding:10px; width:40%;">分类名称</th><th style="padding:10px;">选择打印机</th></tr></thead>';
            html += '<tbody>';

            categories.forEach(function(cat) {
                html += '<tr>';
                html += '<td style="padding:10px; font-weight: 500;">' + escapeHtml(cat.name) + '</td>';
                html += '<td style="padding:10px;">';
                html += '<select class="category-printer-select" data-category-id="' + cat.id + '" style="min-width: 250px; padding: 5px;">';
                html += '<option value="">📌 使用默认厨房打印机</option>';
                html += '<option value="__no_print__"' + (cat.printer === '__no_print__' ? ' selected' : '') + '>🚫 不打印（跳过此分类）</option>';

                printers.forEach(function(printer) {
                    const selected = (cat.printer === printer) ? ' selected' : '';
                    html += '<option value="' + escapeHtml(printer) + '"' + selected + '>' + escapeHtml(printer) + '</option>';
                });

                html += '</select>';
                html += '</td>';
                html += '</tr>';
            });

            html += '</tbody></table>';

            if (printers.length === 0) {
                html += '<p style="color:#b32d2e; margin-top:10px;">⚠️ 未检测到打印机。请确保 CLODOP 服务正在运行，然后点击"刷新打印机列表"。</p>';
            }

            $('#category-printer-list').html(html);
        }

        // HTML 转义函数
        function escapeHtml(text) {
            if (!text) return '';
            const div = document.createElement('div');
            div.textContent = text;
            return div.innerHTML;
        }

        // 保存分类打印机配置
        function saveCategoryPrinters() {
            const $btn = $('#save-category-printers');
            const $status = $('#category-printer-save-status');

            $btn.prop('disabled', true).text('⏳ 保存中...');
            $status.html('');

            // 收集所有分类的打印机配置
            const configs = [];
            $('.category-printer-select').each(function() {
                configs.push({
                    category_id: $(this).data('category-id'),
                    printer: $(this).val()
                });
            });

            $.post(ajaxurl, {
                action: 'ruiyi_save_category_printers',
                nonce: '<?php echo wp_create_nonce("ruiyi_admin_nonce"); ?>',
                configs: JSON.stringify(configs)
            }, function(response) {
                $btn.prop('disabled', false).html('💾 保存分类打印机配置');

                if (response.success) {
                    $status.html('<span style="color:#00a32a;">✅ 保存成功！</span>');
                    setTimeout(function() {
                        $status.fadeOut(500, function() {
                            $(this).html('').show();
                        });
                    }, 3000);
                } else {
                    $status.html('<span style="color:#d63638;">❌ 保存失败: ' + (response.data?.message || '未知错误') + '</span>');
                }
            }).fail(function() {
                $btn.prop('disabled', false).html('💾 保存分类打印机配置');
                $status.html('<span style="color:#d63638;">❌ 网络错误，请重试</span>');
            });
        }

        // 兼容旧函数名
        function loadCategoryPrinterPreview() {
            loadCategoryPrinterEditor();
        }

        // CLODOP 服务检测
        function checkClodopService() {
            $('#clodop-status-area').html('<p><span class="spinner is-active" style="float: none; margin: 0 5px 0 0;"></span>正在检测 CLODOP 服务...</p>');

            // 检查 getLodop 函数是否可用
            if (typeof getLodop === 'undefined') {
                $('#clodop-status-area').html(
                    '<p style="color: #d63638;">❌ LodopFuncs.js 文件加载失败</p>' +
                    '<p>请检查以下事项:</p>' +
                    '<ul style="margin-left: 20px;">' +
                    '<li>• 确保 LodopFuncs.js 文件已上传到网站根目录</li>' +
                    '<li>• 检查文件路径是否正确: ' + '<?php echo home_url("/LodopFuncs.js"); ?>' + '</li>' +
                    '<li>• 确保文件权限设置正确 (644)</li>' +
                    '<li>• 检查浏览器控制台是否有加载错误</li>' +
                    '</ul>'
                );
                return;
            }

            try {
                LODOP = getLodop();

                if (LODOP && LODOP.VERSION) {
                    // 服务正常
                    let html = '<p style="color: #00a32a;">✅ CLODOP 服务运行正常</p>';

                    if (LODOP.CVERSION) {
                        html += '<p><strong>C-Lodop 版本:</strong> ' + LODOP.CVERSION + '</p>';
                        html += '<p><strong>内含 Lodop 版本:</strong> ' + LODOP.VERSION + '</p>';
                    } else {
                        html += '<p><strong>Lodop 版本:</strong> ' + LODOP.VERSION + '</p>';
                    }

                    // 获取打印机列表
                    try {
                        const printerCount = LODOP.GET_PRINTER_COUNT();
                        html += '<p><strong>可用打印机:</strong> ' + printerCount + ' 台</p>';

                        if (printerCount > 0) {
                            const printers = [];
                            html += '<ul style="margin-left: 20px;">';

                            for (let i = 0; i < printerCount; i++) {
                                const printerName = LODOP.GET_PRINTER_NAME(i);
                                printers.push(printerName);
                                html += '<li>🖨️ ' + printerName + '</li>';
                            }
                            html += '</ul>';

                            // 更新打印机选项
                            updatePrinterOptions(printers);
                        } else {
                            html += '<p style="color: #dba617;">⚠️ 未检测到可用打印机</p>';
                        }
                    } catch (e) {
                        html += '<p style="color: #dba617;">⚠️ 无法获取打印机信息: ' + e.message + '</p>';
                    }

                    $('#clodop-status-area').html(html);

                } else {
                    // 服务未运行
                    $('#clodop-status-area').html(
                        '<p style="color: #d63638;">❌ CLODOP 服务未运行</p>' +
                        '<p>请检查以下事项:</p>' +
                        '<ul style="margin-left: 20px;">' +
                        '<li>• CLODOP 服务是否已启动</li>' +
                        '<li>• 端口 8000 或 18000 是否可用</li>' +
                        '<li>• 防火墙是否阻止了服务</li>' +
                        '</ul>'
                    );
                }
            } catch (error) {
                $('#clodop-status-area').html(
                    '<p style="color: #d63638;">❌ 服务检测失败</p>' +
                    '<p class="description">错误信息: ' + error.message + '</p>'
                );
            }
        }

        // 更新打印机选项
        function updatePrinterOptions(printers) {
            const defaultSelect = $('#clodop_default_printer');
            const drawerSelect = $('#clodop_drawer_printer');
            const kitchenSelect = $('#clodop_kitchen_printer'); // 厨房打印机

            const currentDefault = '<?php echo esc_js($clodop_default_printer); ?>';
            const currentDrawer = '<?php echo esc_js($clodop_drawer_printer); ?>';
            const currentKitchen = '<?php echo esc_js($clodop_kitchen_printer); ?>'; // 厨房打印机当前值

            // 清空并重新填充选项
            defaultSelect.empty().append('<option value="">-- 选择打印机 --</option>');
            drawerSelect.empty().append('<option value="">-- 选择打印机 --</option>');
            kitchenSelect.empty().append('<option value="">-- 选择打印机 --</option>'); // 厨房打印机

            printers.forEach(function(printer) {
                const defaultOption = $('<option></option>').attr('value', printer).text(printer);
                const drawerOption = $('<option></option>').attr('value', printer).text(printer);
                const kitchenOption = $('<option></option>').attr('value', printer).text(printer); // 厨房打印机

                if (printer === currentDefault) defaultOption.prop('selected', true);
                if (printer === currentDrawer) drawerOption.prop('selected', true);
                if (printer === currentKitchen) kitchenOption.prop('selected', true); // 厨房打印机

                defaultSelect.append(defaultOption);
                drawerSelect.append(drawerOption);
                kitchenSelect.append(kitchenOption); // 厨房打印机
            });
        }

        // 测试打印
        function testClodopPrint() {
            const printer = $('#clodop_default_printer').val();
            if (!printer) {
                alert('请先选择默认打印机');
                return;
            }

            if (!LODOP || !LODOP.VERSION) {
                alert('CLODOP 服务未连接，请先检测服务状态');
                return;
            }

            try {
                // 设置Lodop注册号 - 域名：ruiyipos.es
                LODOP.SET_LICENSES("","D615C875005D74B88EC9E2585C79798E9CA","","");

                LODOP.PRINT_INIT("CLODOP管理测试");

                // 80mm热敏打印机设置 - 自适应高度避免截断
                LODOP.SET_PRINT_PAGESIZE(3, 800, 50, "");

                // 设置打印机
                LODOP.SET_PRINTER_INDEX(printer);

                // 添加测试内容
                LODOP.ADD_PRINT_TEXT(10, 10, 200, 20, "RUIYI POS - CLODOP 测试");
                LODOP.SET_PRINT_STYLEA(0, "FontName", "黑体");
                LODOP.SET_PRINT_STYLEA(0, "FontSize", 14);
                LODOP.SET_PRINT_STYLEA(0, "Bold", 1);
                LODOP.SET_PRINT_STYLEA(0, "Alignment", 2);

                LODOP.ADD_PRINT_TEXT(40, 10, 200, 15, "管理后台测试打印");
                LODOP.SET_PRINT_STYLEA(1, "FontSize", 10);
                LODOP.SET_PRINT_STYLEA(1, "Alignment", 2);

                LODOP.ADD_PRINT_TEXT(60, 10, 200, 15, "打印机: " + printer);
                LODOP.SET_PRINT_STYLEA(2, "FontSize", 9);

                LODOP.ADD_PRINT_TEXT(80, 10, 200, 15, "时间: " + new Date().toLocaleString());
                LODOP.SET_PRINT_STYLEA(3, "FontSize", 9);

                LODOP.PRINT();

                alert('✅ 测试打印已发送！请检查打印机输出。');

            } catch (error) {
                alert('❌ 测试打印失败: ' + error.message);
            }
        }

        // 测试钱箱
        function testClodopDrawer() {
            const printer = $('#clodop_drawer_printer').val();
            if (!printer) {
                alert('请先选择钱箱控制打印机');
                return;
            }

            if (!LODOP || !LODOP.VERSION) {
                alert('CLODOP 服务未连接，请先检测服务状态');
                return;
            }

            try {
                // 设置Lodop注册号 - 域名：ruiyipos.es
                LODOP.SET_LICENSES("","D615C875005D74B88EC9E2585C79798E9CA","","");

                LODOP.PRINT_INIT("钱箱控制测试");
                LODOP.SET_PRINTER_INDEX(printer);

                // 方法1：使用 SEND_PRINT_RAWDATA 发送 ESC/POS 原始命令
                // ESC/POS 开钱箱命令格式: ESC p m t1 t2
                // ESC = 27, p = 112, m = 钱箱号(0或1), t1 = 高电平时间, t2 = 低电平时间

                // 尝试钱箱1 (参数: 27, 112, 0, 128, 128)
                const drawerCommand1 = String.fromCharCode(27, 112, 0, 128, 128);
                LODOP.SEND_PRINT_RAWDATA(drawerCommand1);

                // 尝试钱箱2 (参数: 27, 112, 1, 128, 128)
                const drawerCommand2 = String.fromCharCode(27, 112, 1, 128, 128);
                LODOP.SEND_PRINT_RAWDATA(drawerCommand2);

                alert('✅ 钱箱开启命令已发送！\n\n说明：已发送 ESC/POS 原始命令。\n请检查钱箱是否已打开。');

            } catch (error) {
                alert('❌ 钱箱测试失败: ' + error.message);
            }
        }

