/**
 * 获取 CLODOP 配置的便捷函数
 */
function get_clodop_config() {
    return [
        'enabled' => get_option('clodop_enabled', 0),
        'default_printer' => get_option('clodop_default_printer', ''),
        'drawer_printer' => get_option('clodop_drawer_printer', ''),
        'kitchen_printer' => get_option('clodop_kitchen_printer', ''), // 厨房打印机
        'kitchen_table_display_mode' => get_option('clodop_kitchen_table_display_mode', 'number_only'), // 桌号显示方式
        'open_drawer_on_card' => get_option('clodop_open_drawer_on_card', 0), // 刷卡支付后打开钱箱
        'category_printer_enabled' => get_option('clodop_category_printer_enabled', 0), // 启用分类打印机
        'separate_ticket_per_category' => get_option('clodop_separate_ticket_per_category', 0), // 每个分类单独打印小票
    ];
}

/**
 * 检查 CLODOP 是否启用
 */
function is_clodop_enabled() {
    return get_option('clodop_enabled', 0) == 1;
}

/**
 * AJAX: 获取分类打印机预览（用于CLODOP设置页面）
 */
add_action('wp_ajax_ruiyi_get_category_printers_preview', 'ruiyi_get_category_printers_preview');
function ruiyi_get_category_printers_preview() {
    check_ajax_referer('ruiyi_admin_nonce', 'nonce');

    if (!current_user_can('manage_options')) {
        wp_send_json_error(['message' => '权限不足']);
        return;
    }

    $categories = get_terms([
        'taxonomy' => 'product_cat',
        'hide_empty' => false,
        'orderby' => 'name',
        'order' => 'ASC'
    ]);

    $result = [];
    if (!is_wp_error($categories)) {
        foreach ($categories as $cat) {
            $printer = get_term_meta($cat->term_id, '_ruiyi_category_printer', true);
            $result[] = [
                'id' => $cat->term_id,
                'name' => $cat->name,
                'printer' => $printer ?: ''
            ];
        }
    }

    wp_send_json_success(['categories' => $result]);
}

/**
 * AJAX: 诊断分类打印机配置（POS前端可调用）
 */
add_action('wp_ajax_ruiyi_pos_diagnose_category_printers', 'ruiyi_pos_diagnose_category_printers');
function ruiyi_pos_diagnose_category_printers() {
    // 使用POS nonce验证
    if (!wp_verify_nonce($_POST['nonce'] ?? '', 'ruiyi_pos_nonce')) {
        wp_send_json_error(['message' => 'Invalid nonce']);
        return;
    }

    $categories = get_terms([
        'taxonomy' => 'product_cat',
        'hide_empty' => false,
        'orderby' => 'name',
        'order' => 'ASC'
    ]);

    $result = [];
    if (!is_wp_error($categories)) {
        foreach ($categories as $cat) {
            $printer = get_term_meta($cat->term_id, '_ruiyi_category_printer', true);
            $all_meta = get_term_meta($cat->term_id);
            $result[] = [
                'term_id' => $cat->term_id,
                'name' => $cat->name,
                'printer' => $printer ?: '(empty)',
                'meta_keys' => array_keys($all_meta)
            ];
        }
    }

    wp_send_json_success([
        'categories' => $result,
        'option_enabled' => get_option('clodop_category_printer_enabled', 0),
        'blog_id' => get_current_blog_id()
    ]);
}

/**
 * AJAX: 保存分类打印机配置（用于CLODOP设置页面）
 */
add_action('wp_ajax_ruiyi_save_category_printers', 'ruiyi_save_category_printers');
function ruiyi_save_category_printers() {
    check_ajax_referer('ruiyi_admin_nonce', 'nonce');

    if (!current_user_can('manage_options')) {
        wp_send_json_error(['message' => '权限不足']);
        return;
    }

    $configs_json = isset($_POST['configs']) ? stripslashes($_POST['configs']) : '';
    $configs = json_decode($configs_json, true);

    if (!is_array($configs)) {
        wp_send_json_error(['message' => '配置数据格式错误']);
        return;
    }

    $updated_count = 0;
    $errors = [];

    foreach ($configs as $config) {
        $category_id = isset($config['category_id']) ? intval($config['category_id']) : 0;
        $printer = isset($config['printer']) ? sanitize_text_field($config['printer']) : '';

        if ($category_id <= 0) {
            continue;
        }

        // 验证分类是否存在
        $term = get_term($category_id, 'product_cat');
        if (is_wp_error($term) || !$term) {
            $errors[] = "分类 ID {$category_id} 不存在";
            continue;
        }

        // 保存或删除打印机配置
        if (!empty($printer)) {
            update_term_meta($category_id, '_ruiyi_category_printer', $printer);
        } else {
            delete_term_meta($category_id, '_ruiyi_category_printer');
        }

        $updated_count++;
    }

    if (count($errors) > 0) {
        wp_send_json_error([
            'message' => '部分保存失败: ' . implode(', ', $errors),
            'updated' => $updated_count
        ]);
    } else {
        wp_send_json_success([
            'message' => '保存成功',
            'updated' => $updated_count
        ]);
    }
}

/**
 * 🔥【2026-04-07】AJAX：返回最新的 CLODOP 运行时配置
 * 用于 POS 页面在 tab 重新激活时同步最新设置（避免依赖 PHP 渲染时烘焙的 window.clodopConfig 旧值）
 */
add_action('wp_ajax_ruiyi_get_clodop_runtime_config', 'ruiyi_get_clodop_runtime_config');
function ruiyi_get_clodop_runtime_config() {
    if (!wp_verify_nonce($_POST['nonce'] ?? '', 'ruiyi_pos_nonce')) {
        wp_send_json_error(['message' => 'Invalid nonce']);
        return;
    }
    $receipt_tax_config = ruiyi_get_receipt_tax_config();
    $receipt_logo_dimensions = ruiyi_get_receipt_logo_dimensions();

    // 重新计算 __no_print__ 分类，与 page-pos.php 渲染逻辑保持一致
    $manualExcluded = array_map('intval', json_decode(get_option('pos_kitchen_excluded_categories', '[]'), true) ?: []);
    $noPrintCatIds = [];
    $allCats = get_terms(['taxonomy' => 'product_cat', 'hide_empty' => false, 'fields' => 'ids']);
    if (!is_wp_error($allCats)) {
        foreach ($allCats as $catId) {
            if (get_term_meta($catId, '_ruiyi_category_printer', true) === '__no_print__') {
                $noPrintCatIds[] = (int)$catId;
            }
        }
    }
    $mergedExcluded = array_values(array_unique(array_merge($manualExcluded, $noPrintCatIds)));

    wp_send_json_success([
        'enabled' => (bool)get_option('clodop_enabled', 0),
        'defaultPrinter' => get_option('clodop_default_printer', ''),
        'drawerPrinter' => get_option('clodop_drawer_printer', ''),
        'kitchenPrinter' => get_option('clodop_kitchen_printer', ''),
        'categoryPrinterEnabled' => (bool)get_option('clodop_category_printer_enabled', 0),
        'separateTicketPerCategory' => (bool)get_option('clodop_separate_ticket_per_category', 0),
        'kitchenCopyToDefault' => (bool)get_option('clodop_kitchen_copy_to_default', 0),
        'kitchenCategoryFilterEnabled' => get_option('pos_kitchen_category_filter_enabled', '0') === '1',
        'kitchenExcludedCategories' => $mergedExcluded,
        'hasNoPrintCategories' => !empty($noPrintCatIds),
        'openDrawerOnCard' => (bool)get_option('clodop_open_drawer_on_card', 0),
        // 🔥【2026-04-08】新增小票样式相关字段，避免 POS 页面用 PHP 渲染时烘焙的旧值
        // 用户在设置里改完抬头对齐/字号/分隔线后，切回 POS tab 应立即生效
        'headerAlignment' => get_option('pos_receipt_header_alignment', 'left'),
        'storeNameFontSize' => intval(get_option('pos_receipt_store_name_font_size', 18)),
        'receiptProductFontSize' => intval(get_option('pos_receipt_product_font_size', 9)),
        'receiptShowFullProductName' => get_option('pos_receipt_show_full_product_name', '0') === '1',
        'paperWidth' => intval(get_option('pos_paper_width', 80)),
        'headerSeparatorLine' => get_option('pos_receipt_header_separator', '0') === '1',
        'receiptBilingual' => get_option('pos_receipt_bilingual', '0') === '1',
        'receiptTaxType' => $receipt_tax_config['type'],
        'receiptTaxLabel' => $receipt_tax_config['label'],
        'receiptTaxRate' => (float)$receipt_tax_config['rate'],
        'logoSize' => intval(get_option('pos_receipt_logo_size', 50)),
        'receiptLogoWidth' => (int) $receipt_logo_dimensions['width'],
        'receiptLogoHeight' => (int) $receipt_logo_dimensions['height'],
        'receiptFooterPhone' => get_option('pos_receipt_footer_phone', ''),
        'receiptFooterWebsite' => get_option('pos_receipt_footer_website', ''),
        'kitchenProductFontSize' => intval(get_option('pos_kitchen_product_font_size', 13)),
        'kitchenBoldProductNumber' => get_option('pos_kitchen_bold_product_number', '1') === '1',
    ]);
}

/**
 * ========================================
 * 产品拖拽排序功能
 * ========================================
 */

/**
 * AJAX处理器：保存产品排序顺序
 */
function ruiyi_save_product_sort_order() {
    // 记录接收到的请求
    ruiyi_debug_log('[RUIYI POS 排序] 收到AJAX请求');
    ruiyi_debug_log('[RUIYI POS 排序] POST数据: ' . print_r($_POST, true));

    // 验证nonce
    if (!isset($_POST['nonce']) || !wp_verify_nonce($_POST['nonce'], 'ruiyi_product_sort_nonce')) {
        ruiyi_debug_log('[RUIYI POS 排序] Nonce验证失败');
        wp_send_json_error('安全验证失败 / Security verification failed / 安全验证失败');
        return;
    }

    ruiyi_debug_log('[RUIYI POS 排序] Nonce验证成功');

    // 验证用户权限（仅管理员和店长可以保存排序）
    $user = wp_get_current_user();
    ruiyi_debug_log('[RUIYI POS 排序] 当前用户: ' . $user->user_login . ', 角色: ' . implode(', ', $user->roles));

    if (!current_user_can('manage_woocommerce')) {
        ruiyi_debug_log('[RUIYI POS 排序] 权限验证失败');
        wp_send_json_error('没有权限执行此操作 / No permission to perform this action / 没有权限执行此操作');
        return;
    }

    ruiyi_debug_log('[RUIYI POS 排序] 权限验证成功');

    // 获取排序数据
    if (!isset($_POST['sort_order'])) {
        ruiyi_debug_log('[RUIYI POS 排序] 缺少sort_order参数');
        wp_send_json_error('缺少排序数据 / Missing sort data / 缺少排序数据');
        return;
    }

    $sort_order = json_decode(stripslashes($_POST['sort_order']), true);
    ruiyi_debug_log('[RUIYI POS 排序] 解析后的排序数据: ' . print_r($sort_order, true));

    if (!is_array($sort_order)) {
        ruiyi_debug_log('[RUIYI POS 排序] 排序数据不是数组');
        wp_send_json_error('无效的排序数据格式 / Invalid sort data format / 无效的排序数据格式');
        return;
    }

    // 保存每个产品的排序顺序
    $saved_count = 0;
    foreach ($sort_order as $item) {
        if (isset($item['id']) && isset($item['order'])) {
            $product_id = intval($item['id']);
            $order = intval($item['order']);

            // 更新产品的自定义排序字段
            $result = update_post_meta($product_id, '_ruiyi_product_sort_order', $order);
            ruiyi_debug_log(sprintf('[RUIYI POS 排序] 更新产品 %d 顺序为 %d, 结果: %s', $product_id, $order, $result ? '成功' : '失败'));
            $saved_count++;
        }
    }

    // 记录日志
    ruiyi_debug_log(sprintf(
        '[RUIYI POS] 产品排序已保存 - 用户: %s, 保存数量: %d',
        $user->user_login,
        $saved_count
    ));

    wp_send_json_success([
        'message' => sprintf('成功保存了 %d 个产品的排序 / Successfully saved sort order for %d products / 成功保存了 %d 个产品的排序', $saved_count, $saved_count, $saved_count),
        'count' => $saved_count
    ]);
}

// 注册AJAX处理器（登录用户）
add_action('wp_ajax_ruiyi_save_product_sort_order', 'ruiyi_save_product_sort_order');

/**
 * 初始化产品排序顺序（为没有排序值的产品设置默认值）
 */
function ruiyi_init_product_sort_order() {
    $args = array(
        'post_type' => 'product',
        'posts_per_page' => -1,
        'post_status' => 'publish',
        'meta_query' => array(
            'relation' => 'OR',
            array(
                'key' => '_ruiyi_product_sort_order',
                'compare' => 'NOT EXISTS'
            ),
            array(
                'key' => '_ruiyi_product_sort_order',
                'value' => '',
                'compare' => '='
            )
        )
    );

    $products = new WP_Query($args);
    $index = 0;

    if ($products->have_posts()) {
        while ($products->have_posts()) {
            $products->the_post();
            $product_id = get_the_ID();

            // 使用产品ID作为默认排序值，确保唯一性
            update_post_meta($product_id, '_ruiyi_product_sort_order', $product_id);
            $index++;
        }
        wp_reset_postdata();
    }
}

// 在主题激活时初始化产品排序
add_action('after_switch_theme', 'ruiyi_init_product_sort_order');

// 旧的轮询API已移除 - 现在使用桌位状态更新触发打印
