// ========================================
// Varios 产品管理
// ========================================

/**
 * 获取或创建 Varios 虚拟产品
 * 用于 POS 系统快捷输入任意价格的杂项商品
 */
add_action('wp_ajax_ruiyi_get_or_create_varios_product', 'ruiyi_get_or_create_varios_product');
add_action('wp_ajax_nopriv_ruiyi_get_or_create_varios_product', 'ruiyi_get_or_create_varios_product');

function ruiyi_get_or_create_varios_product() {
    // 验证 nonce
    if (!isset($_POST['nonce']) || !wp_verify_nonce($_POST['nonce'], 'ruiyi_pos_nonce')) {
        wp_send_json_error(['message' => 'Invalid nonce']);
        return;
    }

    // 检查权限
    if (!current_user_can('edit_posts')) {
        wp_send_json_error(['message' => 'Insufficient permissions']);
        return;
    }

    // 尝试查找已存在的 Varios 产品（通过 meta 标识）
    $existing_varios = get_posts([
        'post_type' => 'product',
        'post_status' => 'publish',
        'posts_per_page' => 1,
        'meta_query' => [
            [
                'key' => '_is_varios_product',
                'value' => 'yes',
                'compare' => '='
            ]
        ]
    ]);

    if (!empty($existing_varios)) {
        // 产品已存在，返回 ID
        $product_id = $existing_varios[0]->ID;
        wp_send_json_success([
            'product_id' => $product_id,
            'message' => 'Varios product found',
            'created' => false
        ]);
        return;
    }

    // 产品不存在，创建新的 Varios 产品
    $product_data = [
        'post_title' => 'Varios',
        'post_content' => 'Producto virtual para artículos varios con precio personalizado',
        'post_status' => 'publish',
        'post_type' => 'product',
        'post_author' => get_current_user_id()
    ];

    $product_id = wp_insert_post($product_data);

    if (is_wp_error($product_id)) {
        wp_send_json_error([
            'message' => 'Failed to create Varios product: ' . $product_id->get_error_message()
        ]);
        return;
    }

    // 设置产品为虚拟产品，价格 0，不含税
    update_post_meta($product_id, '_virtual', 'yes');
    update_post_meta($product_id, '_price', '0');
    update_post_meta($product_id, '_regular_price', '0');
    update_post_meta($product_id, '_sale_price', '');
    update_post_meta($product_id, '_tax_status', 'none'); // 不含税
    update_post_meta($product_id, '_tax_class', '');
    update_post_meta($product_id, '_stock_status', 'instock');
    update_post_meta($product_id, '_manage_stock', 'no');
    update_post_meta($product_id, '_sold_individually', 'no');
    update_post_meta($product_id, '_is_varios_product', 'yes'); // 特殊标识

    // 多语言名称
    update_post_meta($product_id, '_product_name_es', 'Varios');
    update_post_meta($product_id, '_product_name_en', 'Miscellaneous');
    update_post_meta($product_id, '_product_name_zh', 'Varios');

    // 清除缓存
    clean_post_cache($product_id);
    if (function_exists('wc_delete_product_transients')) {
        wc_delete_product_transients($product_id);
    }

    wp_send_json_success([
        'product_id' => $product_id,
        'message' => 'Varios product created successfully',
        'created' => true
    ]);
}

/**
 * ========================================
 * 打印桌位订单（不含二维码）- 用于查看模式
 * ========================================
 */
add_action('wp_ajax_ruiyi_pos_get_table_receipt_no_qr', 'ruiyi_pos_get_table_receipt_no_qr_callback');
add_action('wp_ajax_nopriv_ruiyi_pos_get_table_receipt_no_qr', 'ruiyi_pos_get_table_receipt_no_qr_callback');

function ruiyi_pos_get_table_receipt_no_qr_callback() {
    check_ajax_referer('ruiyi_pos_nonce', 'nonce');

    $table_number = isset($_POST['table_number']) ? sanitize_text_field($_POST['table_number']) : '';
    $order_ids_json = isset($_POST['order_ids_to_print']) ? stripslashes($_POST['order_ids_to_print']) : '[]';
    $order_ids = json_decode($order_ids_json, true);

    if (empty($table_number) || empty($order_ids)) {
        wp_send_json_error(['message' => 'Missing required parameters']);
        return;
    }

    ruiyi_debug_log('[打印桌位订单-无二维码] 桌号: ' . $table_number . ', 订单IDs: ' . json_encode($order_ids));

    // 🔥 获取桌位的分类显示名称
    $table_display_name = 'Mesa ' . $table_number;
    if (is_numeric($table_number)) {
        $all_mappings = ruiyi_get_all_table_categories_mapping();
        if ($all_mappings && is_array($all_mappings)) {
            foreach ($all_mappings as $mapping) {
                if (intval($mapping['global_table_number']) === intval($table_number)) {
                    $table_display_name = $mapping['category_display_name'] ?: ($mapping['display_name'] ?: ('Mesa ' . $table_number));
                    break;
                }
            }
        }
    }

    // 获取小票配置
    $paper_width = get_option('pos_paper_width', 80);
    $receipt_footer = get_option('pos_receipt_footer', '¡Gracias por su compra!');
    $store_name = get_option('pos_store_name', get_bloginfo('name'));
    $store_business_name = get_option('pos_store_business_name', '');
    $store_cif_nif = get_option('pos_store_cif_nif', '');
    $store_address = get_option('pos_store_address', '');
    $store_phone = get_option('pos_store_phone', '');
    $receipt_header_alignment = get_option('pos_receipt_header_alignment', 'left');
    $receipt_store_name_font_size = get_option('pos_receipt_store_name_font_size', '18');
    $receipt_bilingual = get_option('pos_receipt_bilingual', '0') === '1';
    $receipt_tax_config = ruiyi_get_receipt_tax_config();
    $receipt_tax_rate = (float) $receipt_tax_config['rate'];
    $receipt_tax_label = ruiyi_get_receipt_tax_display_label($receipt_tax_config);
    $content_width = $paper_width == 58 ? '220px' : '300px';

    // 收集所有订单的商品
    $all_items = [];
    $grand_total = 0;

    foreach ($order_ids as $order_id) {
        $order = wc_get_order($order_id);
        if (!$order) continue;

        foreach ($order->get_items() as $item_id => $item) {
            $product = $item->get_product();
            $product_name = $product ? ruiyi_get_multilingual_product_name($product, 'es', true) : $item->get_name();
            // 🔥 中西双语
            if ($receipt_bilingual && $product) {
                $name_zh = get_post_meta($product->get_id(), '_product_name_zh', true);
                if (!empty($name_zh)) $product_name = ruiyi_bilingual_product_name($name_zh, $product_name);
            }
            // 🔥 应用产品编号隐藏设置
            if (get_option('pos_hide_product_number_on_receipt', '0') === '1') {
                $cleaned_pn = preg_replace('/^\d+[A-Za-z]?\.\s*/', '', $product_name);
                if (!empty($cleaned_pn)) $product_name = $cleaned_pn;
            }
            $quantity = $item->get_quantity();
            $price_per_unit = $product ? floatval($product->get_price()) : ($item->get_total() / $quantity);
            $line_total = $price_per_unit * $quantity;
            $tax_rate = $product ? ruiyi_get_product_tax_rate($product) : 10.0;

            // 🔥 配料项：不合并，保留独立行
            $is_supp_item = wc_get_order_item_meta($item_id, '_is_supplement', true) === 'yes';
            if ($is_supp_item) {
                $supp_parent = wc_get_order_item_meta($item_id, '_parent_item_name', true);
                $supp_key = '_supplement_' . count($all_items) . '_' . $product_name;
                $all_items[$supp_key] = [
                    'quantity' => $quantity,
                    'price_per_unit' => $price_per_unit,
                    'line_total' => $line_total,
                    'tax_rate' => $tax_rate,
                    'display_name' => $product_name,
                    'is_supplement' => true,
                    'parent_item_name' => $supp_parent ? $supp_parent : ''
                ];
            } else if (isset($all_items[$product_name])) {
                $all_items[$product_name]['quantity'] += $quantity;
                $all_items[$product_name]['line_total'] += $line_total;
            } else {
                $all_items[$product_name] = [
                    'quantity' => $quantity,
                    'price_per_unit' => $price_per_unit,
                    'line_total' => $line_total,
                    'tax_rate' => $tax_rate
                ];
            }

            $grand_total += $line_total;
        }
    }

    // 生成HTML
    ob_start();
    ?>
    <!DOCTYPE html>
    <html>
    <head>
        <meta charset="utf-8">
        <title>Recibo <?php echo esc_html($table_display_name); ?></title>
        <style>
            @media print {
                @page { size: auto; margin: 5mm; }
                body { margin: 0; padding: 0; }
            }
            body { font-family: Arial, sans-serif; width: <?php echo $content_width; ?>; margin: 0 auto; padding: 5mm 2mm; font-size: 10pt; }
            .receipt { width: 100%; }
            h2 { font-size: <?php echo intval($receipt_store_name_font_size); ?>pt; font-weight: bold; text-align: <?php echo esc_attr($receipt_header_alignment); ?>; margin: 0 0 1mm 0; line-height: 1.15; }
            .store-info { text-align: <?php echo esc_attr($receipt_header_alignment); ?>; font-size: 0.75em; }
            h4 { font-size: 1.1em; font-weight: bold; text-align: <?php echo esc_attr($receipt_header_alignment); ?>; margin: 2mm 0; }
            .date-line { text-align:<?php echo esc_attr($receipt_header_alignment); ?> !important; font-size:0.8em; margin-bottom: 2mm; }
            .verifactu-invoice-number, .invoice-number { text-align:<?php echo esc_attr($receipt_header_alignment); ?> !important; }
            table { width: 100%; border-collapse: collapse; table-layout: fixed; font-size: 1em; margin-top: 3px; }
            th, td { padding: 1.5mm 0.5mm; vertical-align: top; }
            th { border-bottom: 2px dashed #000; text-align: left; font-size: 1.0em; font-weight: bold; }
            td.item-name { white-space: nowrap; overflow: hidden; text-overflow: clip; text-transform: uppercase; word-break: normal; letter-spacing: 0; font-family: "Arial Narrow", Arial, sans-serif; font-size: 0.95em; font-weight: 500; }
            td.col-qty { text-align: center; font-size: 0.95em; }
            td.col-price, td.col-total { text-align: right; font-size: 0.95em; }
            .totals-table { margin-top: 3mm; }
            .total-row td { border-top: 2px solid #000; font-weight: bold; padding-top: 2mm; font-size: 1.15em; }
            .footer { text-align: center; font-size: 0.9em; margin-top: 4mm; }
            hr { display: none; border: none; margin: 0; }
            .no-fiscal { font-size: 0.8em; color: #666; margin-top: 3mm; font-style: italic; }
        </style>
    </head>
    <body>
        <div class="receipt">
            <h2><?php echo nl2br(esc_html($store_name)); ?></h2>
            <div class="store-info">
                <?php if (!empty($store_business_name)): ?><div class="business-name"><?php echo esc_html($store_business_name); ?></div><?php endif; ?>
                <?php if (!empty($store_cif_nif)): ?><div class="cif-nif">CIF/NIF: <?php echo esc_html($store_cif_nif); ?></div><?php endif; ?>
                <?php if (!empty($store_phone)): ?><div class="phone">Tel: <?php echo esc_html($store_phone); ?></div><?php endif; ?>
                <?php if (!empty($store_address)): ?><div class="address"><?php echo nl2br(esc_html($store_address)); ?></div><?php endif; ?>
            </div>
            <h4><?php echo esc_html($table_display_name); ?></h4>
            <div class="date-line">Fecha: <?php echo date('m-d-Y H:i'); ?></div>
            <?php
            // 🔥 添加 FACTURA SIMPLIFICADA（优先使用 Verifactu 插件生成的发票号码）
            if (!empty($order_ids)) {
                $first_order_id = reset($order_ids);
                $first_order = wc_get_order($first_order_id);
                $invoice_number = ruiyi_get_receipt_invoice_number($first_order ?: $first_order_id);

                if (!empty($invoice_number)) {
                    echo '<div class="verifactu-invoice-number" data-invoice-number="' . esc_attr($invoice_number) . '" style="font-weight: bold;">';
                    echo 'FACTURA SIMPLIFICADA: ' . esc_html($invoice_number);
                    echo '</div>';
                }
            }
            ?>
            <hr>
            <table>
                <?php $receipt_product_format_noqr = get_option('pos_receipt_product_format', 'default'); ?>
                <thead>
                    <tr>
                    <?php if ($receipt_product_format_noqr === 'qty_first'): ?>
                        <th style="width: 15%; text-align:center;">Cant.</th>
                        <th style="width: 50%;">Producto</th>
                    <?php else: ?>
                        <th style="width: 50%;">Producto</th>
                        <th style="width: 15%;">Cant.</th>
                    <?php endif; ?>
                        <th style="width: 15%;">Precio</th>
                        <th style="width: 20%;">Total</th>
                    </tr>
                </thead>
                <tbody>
                <?php if (!empty($all_items)): ?>
                    <?php foreach ($all_items as $name => $info):
                        // 🔥 使用 display_name 如果存在，否则使用数组键名
                        $display_name = isset($info['display_name']) ? $info['display_name'] : $name;
                        $is_supp_noqr = !empty($info['is_supplement']);
                        $supp_parent_noqr = $is_supp_noqr && !empty($info['parent_item_name']) ? esc_attr($info['parent_item_name']) : '';
                        $supp_prefix_noqr = $is_supp_noqr ? '+ ' : '';
                    ?>
                    <tr<?php if ($is_supp_noqr) echo ' data-supplement="true" data-parent="' . $supp_parent_noqr . '"'; ?>>
                    <?php if ($receipt_product_format_noqr === 'qty_first'): ?>
                        <td class="col-qty"><?php echo intval($info['quantity']); ?></td>
                        <td class="item-name"><?php echo esc_html($supp_prefix_noqr . $display_name); ?></td>
                    <?php else: ?>
                        <td class="item-name"><?php echo esc_html($supp_prefix_noqr . $display_name); ?></td>
                        <td class="col-qty"><?php echo intval($info['quantity']); ?></td>
                    <?php endif; ?>
                        <td class="col-price">€<?php echo number_format($info['price_per_unit'], 2); ?></td>
                        <td class="col-total">€<?php echo number_format($info['line_total'], 2); ?></td>
                    </tr>
                    <?php endforeach; ?>
                <?php else: ?>
                    <tr><td colspan="4" style="text-align:center;">Sin productos</td></tr>
                <?php endif; ?>
                </tbody>
            </table>
            <hr>
            <table class="totals-table">
                <?php
                // 计算税额
                $tax_groups = [];
                $total_pre_tax = 0;

                foreach ($all_items as $item_info) {
                    $item_total = $item_info['line_total'];
                    $tax_rate = $receipt_tax_rate;
                    $item_pre_tax = $item_total / (1 + $tax_rate / 100);
                    $item_tax = $item_total - $item_pre_tax;

                    $total_pre_tax += $item_pre_tax;

                    $tax_key = number_format($tax_rate, 0);
                    if (!isset($tax_groups[$tax_key])) {
                        $tax_groups[$tax_key] = ['rate' => $tax_rate, 'base' => 0, 'tax' => 0];
                    }
                    $tax_groups[$tax_key]['base'] += $item_pre_tax;
                    $tax_groups[$tax_key]['tax'] += $item_tax;
                }

                ksort($tax_groups);
                ?>
                <tr>
                    <td>Base Imponible:</td>
                    <td style="text-align:right;"><?php echo number_format($total_pre_tax, 2); ?>€</td>
                </tr>
                <?php foreach ($tax_groups as $group): ?>
                <tr>
                    <td><?php echo esc_html($receipt_tax_label); ?>:</td>
                    <td style="text-align:right;"><?php echo number_format($group['tax'], 2); ?>€</td>
                </tr>
                <?php endforeach; ?>
                <tr class="total-row">
                    <td>TOTAL:</td>
                    <td style="text-align:right;"><?php echo number_format($grand_total, 2); ?>€</td>
                </tr>
            </table>
            <hr>
            <div class="footer">
                <?php if (!empty($receipt_footer)): ?>
                    <p><?php echo esc_html($receipt_footer); ?></p>
                <?php endif; ?>
                <p class="no-fiscal">RECIBO DE MESA - SIN VALOR FISCAL</p>
            </div>
        </div>
    </body>
    </html>
    <?php
    $html = ob_get_clean();

    ruiyi_debug_log('[打印桌位订单-无二维码] HTML生成成功，长度: ' . strlen($html));
    wp_send_json_success(['html' => $html]);
}

// ========================================
// 历史订单模块 AJAX Handlers
// ========================================

// 获取历史订单列表
add_action('wp_ajax_ruiyi_pos_get_order_history', 'ruiyi_pos_get_order_history_callback');
add_action('wp_ajax_nopriv_ruiyi_pos_get_order_history', 'ruiyi_pos_get_order_history_callback');

// 电话号码自动补全搜索
add_action('wp_ajax_ruiyi_pos_search_phones', 'ruiyi_pos_search_phones_callback');
add_action('wp_ajax_nopriv_ruiyi_pos_search_phones', 'ruiyi_pos_search_phones_callback');

function ruiyi_pos_search_phones_callback() {
    check_ajax_referer('ruiyi_pos_nonce', 'nonce');

    $query = isset($_POST['query']) ? sanitize_text_field($_POST['query']) : '';

    if (strlen($query) < 3) {
        wp_send_json_success(array('phones' => array()));
        return;
    }

    global $wpdb;

    // HPOS兼容：检测订单存储方式
    if (class_exists('Automattic\\WooCommerce\\Utilities\\OrderUtil') &&
        \Automattic\WooCommerce\Utilities\OrderUtil::custom_orders_table_enabled()) {
        // HPOS模式 - 查询 wc_orders_meta 表
        $table = $wpdb->prefix . 'wc_orders_meta';
        $phones = $wpdb->get_col($wpdb->prepare(
            "SELECT DISTINCT meta_value FROM {$table} WHERE meta_key = '_customer_phone' AND meta_value LIKE %s AND meta_value != '' ORDER BY meta_value LIMIT 10",
            '%' . $wpdb->esc_like($query) . '%'
        ));
    } else {
        // 传统模式 - 查询 postmeta 表
        $phones = $wpdb->get_col($wpdb->prepare(
            "SELECT DISTINCT meta_value FROM {$wpdb->postmeta} WHERE meta_key = '_customer_phone' AND meta_value LIKE %s AND meta_value != '' ORDER BY meta_value LIMIT 10",
            '%' . $wpdb->esc_like($query) . '%'
        ));
    }

    wp_send_json_success(array('phones' => array_values($phones)));
}

function ruiyi_pos_get_order_history_callback() {
    check_ajax_referer('ruiyi_pos_nonce', 'nonce');

    $date_from = isset($_POST['date_from']) ? sanitize_text_field($_POST['date_from']) : '';
    $date_to = isset($_POST['date_to']) ? sanitize_text_field($_POST['date_to']) : '';
    $status = isset($_POST['status']) ? sanitize_text_field($_POST['status']) : 'all';
    $phone = isset($_POST['phone']) ? sanitize_text_field($_POST['phone']) : '';
    $payment_filter = isset($_POST['payment_method']) ? strtolower(sanitize_text_field($_POST['payment_method'])) : '';
    $valid_payment_filters = array('cash', 'card', 'mixed', 'bizum', 'cheque', 'company_ticket');
    if (!in_array($payment_filter, $valid_payment_filters, true)) {
        $payment_filter = '';
    }

    // 构建查询参数（前端分页，后端返回较多数据）
    $args = array(
        'limit' => 500,
        'orderby' => 'date',
        'order' => 'DESC',
        'return' => 'ids'
    );

    // 添加状态筛选
    if ($status !== 'all') {
        $args['status'] = $status;
    }

    // 添加日期筛选 - 修复日期范围查询
    if ($date_from && $date_to) {
        // 同时有开始和结束日期
        $args['date_created'] = $date_from . '...' . $date_to . ' 23:59:59';
    } elseif ($date_from) {
        // 只有开始日期
        $args['date_created'] = '>=' . $date_from;
    } elseif ($date_to) {
        // 只有结束日期
        $args['date_created'] = '<=' . $date_to . ' 23:59:59';
    }

    // 电话筛选：保留日期筛选条件，两者同时生效

    // 获取订单
    $order_ids = wc_get_orders($args);
    $orders = array();

    // 🔥 预加载桌位映射表，用于将 _table_number 解析为当前的自定义/分区显示名称
    $table_mappings = array();
    if (function_exists('ruiyi_get_all_table_categories_mapping')) {
        $all_mappings = ruiyi_get_all_table_categories_mapping();
        if (is_array($all_mappings)) {
            foreach ($all_mappings as $m) {
                // 按全局桌号索引: "Mesa X" → category_display_name
                $global_num = isset($m['global_table_number']) ? intval($m['global_table_number']) : 0;
                if ($global_num > 0) {
                    $table_mappings[$global_num] = $m['category_display_name'];
                }
                // 也按 category_display_name 本身索引（用于已存储为分区名的订单）
                $display = isset($m['category_display_name']) ? $m['category_display_name'] : '';
                if ($display) {
                    $table_mappings['display_' . strtoupper($display)] = $display;
                }
            }
        }
    }

    foreach ($order_ids as $order_id) {
        $order = wc_get_order($order_id);
        if (!$order) continue;

        // 过滤非收银系统订单
        $order_source = $order->get_meta('_ruiyi_order_source');
        ruiyi_debug_log('[历史订单] 订单 #' . $order_id . ' _ruiyi_order_source = "' . $order_source . '"');
        if ($order_source && $order_source !== '收银系统') {
            ruiyi_debug_log('[历史订单] 订单 #' . $order_id . ' 来源为"' . $order_source . '"，已过滤');
            continue;
        }

        // 按电话号码筛选（在循环内过滤，兼容HPOS）
        if (!empty($phone)) {
            $customer_phone = $order->get_meta('_customer_phone');
            if (empty($customer_phone) || strpos($customer_phone, $phone) === false) {
                continue;
            }
        }

        // 获取订单商品
        $items = array();
        foreach ($order->get_items() as $item) {
            $items[] = array(
                'name' => $item->get_name(),
                'quantity' => $item->get_quantity(),
                'total' => number_format($item->get_total(), 2)
            );
        }

        // 获取桌号并解析为当前的自定义/分区显示名称
        $table_number = $order->get_meta('_table_number');
        $table_display_name = $order->get_meta('_table_display_name');

        // 🔥 解析桌位显示名称：优先使用映射表中的当前名称
        $resolved_table_name = '';
        if (!empty($table_number) && !empty($table_mappings)) {
            $tn_upper = strtoupper(trim($table_number));
            // 1. 先检查是否已经是当前的 display_name
            if (isset($table_mappings['display_' . $tn_upper])) {
                $resolved_table_name = $table_mappings['display_' . $tn_upper];
            }
            // 2. 尝试 "Mesa X" 格式 → 提取数字查映射
            elseif (preg_match('/^MESA\s*(\d+)$/i', $tn_upper, $matches)) {
                $num = intval($matches[1]);
                if (isset($table_mappings[$num])) {
                    $resolved_table_name = $table_mappings[$num];
                }
            }
            // 3. 纯数字
            elseif (is_numeric($tn_upper)) {
                $num = intval($tn_upper);
                if (isset($table_mappings[$num])) {
                    $resolved_table_name = $table_mappings[$num];
                }
            }
        }
        // 最终显示名：resolved > table_display_name > table_number
        $final_table_display = $resolved_table_name ?: ($table_display_name ?: $table_number);

        // 🔥 获取小票显示用发票号码（统一为年份 + 7位订单序号）
        $invoice_label = ruiyi_get_receipt_invoice_number($order, false);
        $invoice_number = $invoice_label;

        // 🔥 获取支付方式（优先使用POS存储的支付方式）
        $payment_method_detail = $order->get_meta('_payment_method_detail', true);
        $pos_payment_method = $order->get_meta('_pos_payment_method');
        $payment_method_id = $order->get_payment_method();
        $payment_method_title = $order->get_payment_method_title();

        // 🔥 确定最终的支付方式值
        // 优先级：_payment_method_detail > _pos_payment_method > payment_method_id > payment_method_title
        $final_payment_method = '';
        if (!empty($payment_method_detail)) {
            $detail_lower = strtolower($payment_method_detail);
            if (in_array($detail_lower, array('cash', 'card', 'mixed', 'bizum', 'cheque', 'company_ticket'), true)) {
                $final_payment_method = $detail_lower;
            } else {
                $final_payment_method = $payment_method_detail;
            }
        } elseif (!empty($pos_payment_method)) {
            $pos_lower = strtolower($pos_payment_method);
            if (in_array($pos_lower, array('cod', 'cash', 'efectivo'), true)) {
                $final_payment_method = 'cash';
            } elseif (in_array($pos_lower, array('bacs', 'card', 'tarjeta'), true)) {
                $final_payment_method = 'card';
            } elseif (in_array($pos_lower, array('mixed', 'mixto'), true)) {
                $final_payment_method = 'mixed';
            } elseif (in_array($pos_lower, array('bizum', 'transfer', 'transferencia'), true)) {
                $final_payment_method = 'bizum';
            } elseif (in_array($pos_lower, array('cheque'), true)) {
                $final_payment_method = 'cheque';
            } elseif (in_array($pos_lower, array('company_ticket', 'company_ticket_only', 'pos_company_ticket'), true)) {
                $final_payment_method = 'company_ticket';
            } else {
                $final_payment_method = $pos_payment_method;
            }
        } elseif (!empty($payment_method_id)) {
            // 标准化支付方式ID
            $pm_lower = strtolower($payment_method_id);
            if (in_array($pm_lower, array('cod', 'cash', 'efectivo'))) {
                $final_payment_method = 'cash';
            } elseif (in_array($pm_lower, array('bacs', 'card', 'tarjeta'))) {
                $final_payment_method = 'card';
            } elseif (in_array($pm_lower, array('mixed', 'mixto'))) {
                $final_payment_method = 'mixed';
            } elseif (in_array($pm_lower, array('bizum', 'transfer', 'transferencia'))) {
                $final_payment_method = 'bizum';
            } elseif (in_array($pm_lower, array('cheque'))) {
                $final_payment_method = 'cheque';
            } elseif (in_array($pm_lower, array('company_ticket', 'company_ticket_only', 'pos_company_ticket'))) {
                $final_payment_method = 'company_ticket';
            } else {
                $final_payment_method = $payment_method_id;
            }
        } elseif (!empty($payment_method_title)) {
            // 从标题推断
            $title_lower = strtolower($payment_method_title);
            if (strpos($title_lower, 'efectivo') !== false || strpos($title_lower, 'cash') !== false) {
                $final_payment_method = 'cash';
            } elseif (strpos($title_lower, 'tarjeta') !== false || strpos($title_lower, 'card') !== false) {
                $final_payment_method = 'card';
            } elseif (strpos($title_lower, 'mixto') !== false || strpos($title_lower, 'mixed') !== false) {
                $final_payment_method = 'mixed';
            } elseif (strpos($title_lower, 'bizum') !== false || strpos($title_lower, 'transfer') !== false) {
                $final_payment_method = 'bizum';
            } elseif (strpos($title_lower, 'cheque') !== false) {
                $final_payment_method = 'cheque';
            } elseif (strpos($title_lower, 'empresa') !== false || strpos($title_lower, 'company') !== false) {
                $final_payment_method = 'company_ticket';
            } else {
                $final_payment_method = $payment_method_title;
            }
        }

        // 按支付方式筛选（在循环内过滤，兼容 HPOS 和旧订单的不同元数据）
        if ($payment_filter !== '' && strtolower($final_payment_method) !== $payment_filter) {
            continue;
        }

        // 🔥 获取支付详情
        $cash_amount = $order->get_meta('_cash_amount');
        $card_amount = $order->get_meta('_card_amount');
        $received_amount = $order->get_meta('_received_amount');
        $change_amount = $order->get_meta('_change_amount');

        // 🔥 计算税费（IVA）- 订单总额包含税费，计算出税费部分
        $order_total = $order->get_total();
        $order_subtotal = $order->get_subtotal(); // 商品小计（不含税）
        $order_tax = $order->get_total_tax(); // 税费总额

        $orders[] = array(
            'id' => $order->get_id(),
            'status' => $order->get_status(),
            'status_name' => wc_get_order_status_name($order->get_status()),
            'date' => $order->get_date_created()->format('Y-m-d'),
            'time' => $order->get_date_created()->format('H:i'),
            'total' => number_format($order->get_total(), 2),
            'subtotal' => number_format($order_subtotal, 2),
            'tax' => number_format($order_tax, 2),
            'payment_method' => $final_payment_method,
            'payment_method_title' => $payment_method_title,
            'table_number' => $table_number,
            'table_display_name' => $final_table_display ?: '',
            'items' => $items,
            'customer_note' => $order->get_customer_note(),
            'invoice_label' => $invoice_label,
            'invoice_number' => $invoice_number,
            // 🔥 支付详情
            'cash_amount' => $cash_amount ? number_format(floatval($cash_amount), 2) : '',
            'card_amount' => $card_amount ? number_format(floatval($card_amount), 2) : '',
            'received_amount' => $received_amount ? number_format(floatval($received_amount), 2) : '',
            'change_amount' => $change_amount ? number_format(floatval($change_amount), 2) : ''
        );
    }

    wp_send_json_success(array('orders' => $orders));
}

// 获取历史订单小票HTML（带二维码）
add_action('wp_ajax_ruiyi_pos_get_order_receipt_with_qr', 'ruiyi_pos_get_order_receipt_with_qr_callback');
add_action('wp_ajax_nopriv_ruiyi_pos_get_order_receipt_with_qr', 'ruiyi_pos_get_order_receipt_with_qr_callback');

function ruiyi_pos_get_order_receipt_with_qr_callback() {
    // 🔥 修复：使用更宽松的nonce验证，同时支持 nonce 和 security 参数
    $nonce = isset($_POST['nonce']) ? $_POST['nonce'] : (isset($_POST['security']) ? $_POST['security'] : '');

    if (empty($nonce) || !wp_verify_nonce($nonce, 'ruiyi_pos_nonce')) {
        ruiyi_debug_log('[RUIYI POS] 打印小票nonce验证失败: ' . $nonce);
        wp_send_json_error(array('message' => 'Nonce验证失败，请刷新页面后重试'));
        return;
    }

    $order_id = isset($_POST['order_id']) ? intval($_POST['order_id']) : 0;
    if (!$order_id) {
        wp_send_json_error(array('message' => '订单ID无效'));
    }

    $order = wc_get_order($order_id);
    if (!$order) {
        wp_send_json_error(array('message' => '订单不存在'));
    }

    // 获取订单信息
    $table_number = $order->get_meta('_table_number');
    $order_type = $order->get_meta('_order_type') ?: 'llevar';

    // 🔥 获取桌位分区显示名称 (如 "室内1" 而不是只是 "1")
    $table_display_name = 'Mesa ' . $table_number; // 默认值
    if (!empty($table_number)) {
        // 提取桌位号中的数字（"餐桌1" -> 1, "Mesa 2" -> 2, "1" -> 1）
        $table_number_numeric = intval(preg_replace('/[^0-9]/', '', $table_number));

        // 使用与正常结账小票相同的函数获取映射
        if (function_exists('ruiyi_get_all_table_categories_mapping')) {
            $all_mappings = ruiyi_get_all_table_categories_mapping();
            if ($all_mappings && is_array($all_mappings)) {
                foreach ($all_mappings as $mapping) {
                    // 使用 global_table_number 字段匹配（与正常结账小票一致）
                    if (isset($mapping['global_table_number']) &&
                        intval($mapping['global_table_number']) === $table_number_numeric) {
                        $table_display_name = $mapping['category_display_name'] ?:
                                              ($mapping['display_name'] ?: ('Mesa ' . $table_number));
                        break;
                    }
                }
            }
        }
    }

    // 获取店铺信息
    $store_name = get_option('pos_store_name', get_bloginfo('name'));
    $store_business_name = get_option('pos_store_business_name', '');
    $store_cif_nif = get_option('pos_store_cif_nif', '');
    $store_address = get_option('pos_store_address', '');
    $store_phone = get_option('pos_store_phone', '');
    $receipt_header_alignment = get_option('pos_receipt_header_alignment', 'left');
    $receipt_store_name_font_size = get_option('pos_receipt_store_name_font_size', '18');
    $receipt_bilingual = get_option('pos_receipt_bilingual', '0') === '1';
    $hide_product_number_qr = get_option('pos_hide_product_number_on_receipt', '0') === '1';
    $receipt_tax_config = ruiyi_get_receipt_tax_config();
    $receipt_tax_rate = (float) $receipt_tax_config['rate'];
    $receipt_tax_label = ruiyi_get_receipt_tax_display_label($receipt_tax_config);

    // 🔥 生成与正常结账小票相同结构的HTML（CLODOP解析器需要这些类名）
    ob_start();
    ?>
    <!DOCTYPE html>
    <html>
    <head>
        <meta charset="utf-8">
        <title>Ticket Histórico #<?php echo esc_html($order_id); ?></title>
        <style>
            body { font-family: Arial, sans-serif; width: 72mm; margin: 0 auto; padding: 5mm 4mm; box-sizing: border-box; font-size: 10pt; }
            .receipt { width: 100%; max-width: 72mm; }
            h2 { font-size: <?php echo intval($receipt_store_name_font_size); ?>pt; font-weight: bold; text-align: <?php echo esc_attr($receipt_header_alignment); ?>; margin: 0 0 1mm 0; line-height: 1.15; }
            .store-info { text-align: <?php echo esc_attr($receipt_header_alignment); ?>; }
            .store-info .business-name { font-size: 0.9em; margin-bottom: 0; }
            .store-info .cif-nif { font-size: 0.85em; margin-bottom: 0; }
            .store-info .phone { font-size: 0.85em; margin-bottom: 0; }
            .store-info .address { font-size: 0.85em; margin-bottom: 0; margin-top: 0.5mm; line-height: 1.3; }
            h4 { font-size: 1.1em; font-weight: bold; text-align: <?php echo esc_attr($receipt_header_alignment); ?>; margin: 2mm 0 1mm 0; }
            .date-line { text-align: <?php echo esc_attr($receipt_header_alignment); ?> !important; font-size: 0.8em; margin-bottom: 2mm; }
            .verifactu-invoice-number, .invoice-number { text-align: <?php echo esc_attr($receipt_header_alignment); ?> !important; }
            .order-numbers { text-align: <?php echo esc_attr($receipt_header_alignment); ?>; font-size: 0.9em; font-weight: bold; margin-bottom: 2mm; padding: 0; border: none; }
            table { width: 100%; border-collapse: collapse; table-layout: fixed; font-size: 1em; margin-top: 3px; margin-bottom: 3px; }
            th, td { padding: 0.8mm 0.5mm; vertical-align: top; }
            th { border-bottom: 2px dashed #000; text-align: left; font-weight: bold; }
            td.item-name { white-space: nowrap; overflow: hidden; text-overflow: clip; text-transform: uppercase; word-break: normal; letter-spacing: 0; font-family: "Arial Narrow", Arial, sans-serif; font-size: 0.95em; font-weight: 500; text-align: left; }
            td.col-qty { text-align: center; font-weight: 500; font-size: 0.95em; }
            td.col-price { text-align: right; font-weight: 500; font-size: 0.95em; }
            td.col-total { text-align: right; font-weight: 500; font-size: 0.95em; }
            .totals-table { margin-top: 2mm; }
            .totals-table td { padding: 0.6mm 0.5mm; }
            .total-row td { border-top: 2px solid #000; font-weight: bold; padding-top: 1.2mm; font-size: 1.15em; }
            .footer { text-align: center; font-size: 0.9em; margin-top: 4mm; line-height: 1.4em; }
            hr { display: none; border: none; margin: 0; }
            .qr-container { text-align: center; margin: 3mm 0; }
            .qr-container img { width: 35mm; height: 35mm; }
        </style>
    </head>
    <body>
        <div class="receipt">
            <?php
            // 🔥 添加小票Logo（如果已设置）
            $logo_url = get_option('pos_receipt_logo', '');
            $logo_size = get_option('pos_receipt_logo_size', '50');
            if (!empty($logo_url)):
            ?>
            <div style="text-align: <?php echo esc_attr($receipt_header_alignment); ?>; margin-bottom: 3mm;">
                <img class="receipt-logo" src="<?php echo esc_url($logo_url); ?>"
                     style="max-width: <?php echo esc_attr($logo_size); ?>mm; max-height: 25mm; object-fit: contain;">
            </div>
            <?php endif; ?>
            <h2><?php echo nl2br(esc_html($store_name)); ?></h2>
            <div class="store-info">
                <?php if (!empty($store_business_name)) : ?><div class="business-name"><?php echo esc_html($store_business_name); ?></div><?php endif; ?>
                <?php if (!empty($store_cif_nif)) : ?><div class="cif-nif">CIF/NIF: <?php echo esc_html($store_cif_nif); ?></div><?php endif; ?>
                <?php if (!empty($store_phone)) : ?><div class="phone">Tel: <?php echo esc_html($store_phone); ?></div><?php endif; ?>
                <?php if (!empty($store_address)) : ?><div class="address"><?php echo nl2br(esc_html($store_address)); ?></div><?php endif; ?>
            </div>

            <?php if ($order_type !== 'llevar' && !empty($table_number)): ?>
                <h4><?php echo esc_html($table_display_name); ?></h4>
            <?php endif; ?>

            <?php
            // 🔥 获取并显示客户信息（外送订单）
            $customer_name = $order->get_meta('_customer_name', true);
            $customer_phone = $order->get_meta('_customer_phone', true) ?: $order->get_billing_phone();
            $customer_address = $order->get_meta('_customer_address', true) ?: $order->get_billing_address_1();
            $customer_postal_code = $order->get_meta('_customer_postal_code', true) ?: $order->get_billing_postcode();

            $has_customer_info = !empty($customer_name) || !empty($customer_phone) || !empty($customer_address);
            if ($has_customer_info):
            ?>
            <div class="customer-info" style="text-align: <?php echo esc_attr($receipt_header_alignment); ?>; margin: 1mm 0; padding: 0; border: none; font-size: 0.9em; line-height: 1.25em;">
                <?php if (!empty($customer_name)): ?>
                    <div><strong>Cliente:</strong> <?php echo esc_html($customer_name); ?></div>
                <?php endif; ?>
                <?php if (!empty($customer_phone)): ?>
                    <div><strong>Teléfono:</strong> <?php echo esc_html($customer_phone); ?></div>
                <?php endif; ?>
                <?php if (!empty($customer_address)): ?>
                    <div><strong>Dirección:</strong> <?php echo esc_html($customer_address); ?></div>
                <?php endif; ?>
                <?php if (!empty($customer_postal_code)): ?>
                    <div><strong>C.P.:</strong> <?php echo esc_html($customer_postal_code); ?></div>
                <?php endif; ?>
            </div>
            <?php endif; ?>

            <?php
            // 日期格式化 - 使用订单创建日期，而非当前日期
            $timezone = wp_timezone();
            $order_date_obj = $order->get_date_created();
            if ($order_date_obj) {
                // 克隆日期对象以避免修改原始对象
                $order_date_clone = clone $order_date_obj;
                $order_date_clone->setTimezone($timezone);
                $formatted_date = $order_date_clone->format('d-m-Y H:i');
            } else {
                // 备用：如果没有创建日期，尝试使用完成日期
                $order_completed_date = $order->get_date_completed();
                if ($order_completed_date) {
                    $order_completed_clone = clone $order_completed_date;
                    $order_completed_clone->setTimezone($timezone);
                    $formatted_date = $order_completed_clone->format('d-m-Y H:i');
                } else {
                    // 最后备用：当前日期
                    $formatted_date = date('d-m-Y H:i');
                }
            }
            ?>
            <div class="date-line">Fecha: <?php echo $formatted_date; ?></div>

            <?php
            // 发票号码
            $invoice_number = ruiyi_get_receipt_invoice_number($order);
            ?>
            <?php if (!empty($invoice_number)): ?>
                <div class="verifactu-invoice-number" data-invoice-number="<?php echo esc_attr($invoice_number); ?>" style="text-align: <?php echo esc_attr($receipt_header_alignment); ?>; font-weight: bold;">
                    FACTURA SIMPLIFICADA: <?php echo esc_html($invoice_number); ?>
                </div>
            <?php endif; ?>

            <hr>
            <?php $receipt_product_format_qr = get_option('pos_receipt_product_format', 'default'); ?>
            <table>
                <thead>
                    <tr>
                    <?php if ($receipt_product_format_qr === 'qty_first'): ?>
                        <th style="width: 15%; text-align:center;">Cant.</th>
                        <th style="width: 50%;">Producto</th>
                    <?php else: ?>
                        <th style="width: 50%;">Producto</th>
                        <th style="width: 15%; text-align:center;">Cant.</th>
                    <?php endif; ?>
                        <th style="width: 15%; text-align:right;">Precio</th>
                        <th style="width: 20%; text-align:right;">Total</th>
                    </tr>
                </thead>
                <tbody>
                <?php
                // 收集税费信息并计算
                $tax_groups = array();
                $total_before_tax = 0;
                $total_tax = 0;

                foreach ($order->get_items() as $item) {
                    $product = $item->get_product();
                    $item_total = floatval($item->get_total());
                    $quantity = $item->get_quantity();
                    $price_per_unit = $quantity > 0 ? $item_total / $quantity : 0;
                    $tax_rate = $receipt_tax_rate;

                    // 计算税前价格和税额
                    $item_base = $item_total / (1 + $tax_rate / 100);
                    $item_tax = $item_total - $item_base;

                    $total_before_tax += $item_base;
                    $total_tax += $item_tax;

                    // 按税率分组
                    $tax_key = number_format($tax_rate, 0);
                    if (!isset($tax_groups[$tax_key])) {
                        $tax_groups[$tax_key] = array('rate' => $tax_rate, 'base' => 0, 'tax' => 0);
                    }
                    $tax_groups[$tax_key]['base'] += $item_base;
                    $tax_groups[$tax_key]['tax'] += $item_tax;

                    // 🔥 中西双语产品名称
                    $item_display_name = $item->get_name();
                    if ($receipt_bilingual && $product) {
                        $name_zh = get_post_meta($product->get_id(), '_product_name_zh', true);
                        if (!empty($name_zh)) $item_display_name = ruiyi_bilingual_product_name($name_zh, $item_display_name);
                    }
                    // 🔥 应用产品编号隐藏设置（历史订单小票）
                    if ($hide_product_number_qr) {
                        $cleaned_name = preg_replace('/^\d+[A-Za-z]?\.\s*/', '', $item_display_name);
                        if (!empty($cleaned_name)) $item_display_name = $cleaned_name;
                    }
                    ?>
                    <tr>
                    <?php if ($receipt_product_format_qr === 'qty_first'): ?>
                        <td class="col-qty"><?php echo intval($quantity); ?></td>
                        <td class="item-name"><?php echo esc_html($item_display_name); ?></td>
                    <?php else: ?>
                        <td class="item-name"><?php echo esc_html($item_display_name); ?></td>
                        <td class="col-qty"><?php echo intval($quantity); ?></td>
                    <?php endif; ?>
                        <td class="col-price"><?php echo number_format($price_per_unit, 2); ?></td>
                        <td class="col-total"><?php echo number_format($item_total, 2); ?></td>
                    </tr>
                    <?php
                }
                ?>
                </tbody>
            </table>
            <hr>

            <!-- 🔥 使用 totals-table 类名以便 CLODOP 解析器正确识别 -->
            <table class="totals-table">
                <tr>
                    <td>Base Imponible:</td>
                    <td style="text-align: right;"><?php echo number_format($total_before_tax, 2); ?>€</td>
                </tr>
                <?php
                // 按税率排序并显示
                ksort($tax_groups);
                foreach ($tax_groups as $tax_key => $amounts) :
                ?>
                <tr>
                    <td><?php echo esc_html($receipt_tax_label); ?>:</td>
                    <td style="text-align: right;"><?php echo number_format($amounts['tax'], 2); ?>€</td>
                </tr>
                <?php endforeach; ?>

                <?php
                // 🔥 获取并显示手动折扣信息
                $discount_percent = $order->get_meta('_manual_discount_percent', true);
                $discount_amount = $order->get_meta('_manual_discount_amount', true);

                if ($discount_percent && floatval($discount_percent) > 0 && $discount_amount && floatval($discount_amount) > 0):
                ?>
                <tr class="discount-row" style="color: #dc2626;">
                    <td>DESCUENTO (<span class="discount-percent"><?php echo number_format(floatval($discount_percent), 0); ?></span>%):</td>
                    <td style="text-align: right;" class="discount-amount">-€<?php echo number_format(floatval($discount_amount), 2); ?></td>
                </tr>
                <?php endif; ?>

                <?php
                // 🔥 获取并显示Cheque Restaurante抵扣信息
                $cheque_restaurante = $order->get_meta('_cheque_restaurante_amount', true);
                ruiyi_debug_log("[历史订单小票] 订单 #{$order_id} - Cheque Restaurante 元数据: " . ($cheque_restaurante ?: '空'));

                if ($cheque_restaurante && floatval($cheque_restaurante) > 0):
                    ruiyi_debug_log("[历史订单小票] ✅ 订单 #{$order_id} 将显示 Cheque: €" . number_format(floatval($cheque_restaurante), 2));
                ?>
                <tr style="color: #e65100;">
                    <td>Cheque Restaurante:</td>
                    <td style="text-align: right;">-€<?php echo number_format(floatval($cheque_restaurante), 2); ?></td>
                </tr>
                <?php endif; ?>

                <tr class="total-row">
                    <td>TOTAL:</td>
                    <td style="text-align: right;"><?php echo number_format($order->get_total(), 2); ?>€</td>
                </tr>
            </table>

            <hr>

            <!-- 🔥 支付明细 (现金/刷卡/找零) - 详细版 -->
            <?php
            // 🔥 修复：优先使用 _payment_method_detail 来判断实际支付方式
            // 因为 bacs 被用于刷卡支付，但之前的逻辑错误地将其归类为现金
            $payment_method_detail = $order->get_meta('_payment_method_detail', true);
            $payment_method = $order->get_meta('_payment_method', true) ?: $order->get_payment_method();

            // 🔥 修复：使用正确的 meta key (_cash_amount 和 _card_amount)
            $cash_amount = $order->get_meta('_cash_amount', true);
            $card_amount = $order->get_meta('_card_amount', true);
            $received_amount = $order->get_meta('_received_amount', true);
            $change_amount = $order->get_meta('_change_amount', true);

            // 🔥 修复：使用 _payment_method_detail 来判断混合支付
            $is_mixed = ($payment_method_detail === 'mixed') ||
                        ($cash_amount && $card_amount && floatval($cash_amount) > 0 && floatval($card_amount) > 0);

            // 🔥 修复：使用 _payment_method_detail 来准确判断支付类型
            $is_card_payment = ($payment_method_detail === 'card') ||
                               (($card_amount && floatval($card_amount) > 0) && !$is_mixed);
            $is_cash_payment = ($payment_method_detail === 'cash') ||
                               ($payment_method === 'cash') ||
                               ($payment_method === 'cod') ||
                               (($cash_amount && floatval($cash_amount) > 0) && !$is_mixed && !$is_card_payment);

            $order_total = $order->get_total();
            ?>

            <table class="payment-details-table" style="width: 100%; margin: 2mm 0; font-size: 0.95em;">
                <tr>
                    <td colspan="2" style="text-align: center; font-weight: bold; border-bottom: 2px dashed #000; padding-bottom: 1mm; margin-bottom: 1mm;">
                        Detalles de Pago
                    </td>
                </tr>
                <?php if ($is_mixed): ?>
                    <!-- 混合支付 -->
                    <tr>
                        <td><strong>Pago Mixto:</strong></td>
                        <td style="text-align: right; font-weight: bold;"><?php echo number_format($order_total, 2); ?>€</td>
                    </tr>
                    <tr>
                        <td style="padding-left: 5mm;">Efectivo:</td>
                        <td style="text-align: right;"><?php echo number_format(floatval($cash_amount), 2); ?>€</td>
                    </tr>
                    <tr>
                        <td style="padding-left: 5mm;">Tarjeta:</td>
                        <td style="text-align: right;"><?php echo number_format(floatval($card_amount), 2); ?>€</td>
                    </tr>
                <?php elseif ($is_card_payment): ?>
                    <!-- 🔥 修复：刷卡支付现在能正确识别 -->
                    <tr>
                        <td><strong>Tarjeta:</strong></td>
                        <td style="text-align: right; font-weight: bold;"><?php echo number_format($card_amount ? floatval($card_amount) : $order_total, 2); ?>€</td>
                    </tr>
                <?php elseif ($is_cash_payment): ?>
                    <!-- 现金支付 -->
                    <tr>
                        <td><strong>Pago:</strong></td>
                        <td style="text-align: right;"></td>
                    </tr>
                    <tr>
                        <td style="padding-left: 5mm;">Efectivo:</td>
                        <td style="text-align: right; font-weight: bold;"><?php echo number_format($cash_amount ? floatval($cash_amount) : $order_total, 2); ?>€</td>
                    </tr>
                    <?php if ($received_amount && floatval($received_amount) > 0): ?>
                    <tr>
                        <td style="padding-left: 5mm;">Recibido:</td>
                        <td style="text-align: right;"><?php echo number_format(floatval($received_amount), 2); ?>€</td>
                    </tr>
                    <?php endif; ?>
                    <?php if ($change_amount && floatval($change_amount) > 0): ?>
                    <tr>
                        <td style="padding-left: 5mm;">Cambio:</td>
                        <td style="text-align: right; font-weight: bold;"><?php echo number_format(floatval($change_amount), 2); ?>€</td>
                    </tr>
                    <?php endif; ?>
                <?php else: ?>
                    <!-- 其他支付方式 -->
                    <tr>
                        <td colspan="2" style="text-align: center;">
                            <strong>Método de Pago:</strong> <?php echo esc_html($order->get_payment_method_title()); ?>
                        </td>
                    </tr>
                <?php endif; ?>
            </table>

            <hr>

            <?php
            // 🔥 Verifactu QR码 - 直接从订单meta获取已保存的QR码
            $qr_base64 = $order->get_meta('_verifactu_qr_base64');
            if (!empty($qr_base64)) :
                // 将base64转换为data URI格式
                $qr_data_uri = 'data:image/png;base64,' . $qr_base64;
            ?>
            <div class="qr-container">
                <img src="<?php echo esc_attr($qr_data_uri); ?>" alt="Verifactu QR">
                <div style="font-size: 0.7em; margin-top: 1mm;">Código Verifactu</div>
            </div>
            <?php
            endif;
            ?>

            <hr>

            <div class="footer">
                ¡Gracias por su visita!<br>
                <span style="font-size: 0.8em;">Reimpresión de Ticket</span>
            </div>
        </div>
    </body>
    </html>
    <?php
    $html = ob_get_clean();

    wp_send_json_success(array('html' => $html));
}

