// AJAX Handler: Get Daily Summary Data
add_action('wp_ajax_ruiyi_get_daily_summary', 'ruiyi_get_daily_summary');
add_action('wp_ajax_nopriv_ruiyi_get_daily_summary', 'ruiyi_get_daily_summary');

function ruiyi_get_auto_settlement_time_parts() {
    $settlement_time = get_option('pos_auto_settlement_time', '00:00');
    $time_parts = explode(':', $settlement_time);

    return [
        'time' => $settlement_time,
        'hour' => isset($time_parts[0]) ? intval($time_parts[0]) : 0,
        'minute' => isset($time_parts[1]) ? intval($time_parts[1]) : 0,
    ];
}

function ruiyi_get_business_date_from_datetime($datetime = '') {
    $datetime = $datetime ?: current_time('mysql');
    $timestamp = strtotime($datetime);
    $hour = intval(date('H', $timestamp));

    if ($hour < 4) {
        return date('Y-m-d', strtotime('-1 day', $timestamp));
    }

    return date('Y-m-d', $timestamp);
}

function ruiyi_get_next_auto_settlement_schedule_info() {
    $time_info = ruiyi_get_auto_settlement_time_parts();
    $timezone = wp_timezone();
    $now = new DateTime('now', $timezone);
    $next_run = new DateTime($now->format('Y-m-d'), $timezone);
    $next_run->setTime($time_info['hour'], $time_info['minute'], 0);

    if ($next_run <= $now) {
        $next_run->modify('+1 day');
    }

    $business_date = clone $next_run;
    if ($time_info['hour'] < 4) {
        $business_date->modify('-1 day');
    }

    return [
        'business_date' => $business_date->format('Y-m-d'),
        'next_run' => $next_run->format('Y-m-d H:i:s'),
    ];
}

function ruiyi_get_auto_settlement_schedule_for_business_date($business_date) {
    $time_info = ruiyi_get_auto_settlement_time_parts();
    $timezone = wp_timezone();
    $period_end = new DateTime($business_date, $timezone);

    if ($time_info['hour'] < 4) {
        $period_end->modify('+1 day');
    }

    $period_end->setTime($time_info['hour'], $time_info['minute'], 0);

    $period_start = clone $period_end;
    $period_start->modify('-1 day');

    $last_settlement_time = get_option('ruiyi_last_settlement_time', '');
    if (!empty($last_settlement_time)) {
        try {
            $last_settlement_dt = new DateTime($last_settlement_time, $timezone);
            if ($last_settlement_dt > $period_start && $last_settlement_dt < $period_end) {
                $period_start = $last_settlement_dt;
            }
        } catch (Exception $e) {
            // Ignore malformed timestamps and keep calculated period.
        }
    }

    return [
        'business_date' => $business_date,
        'period_start' => $period_start->format('Y-m-d H:i:s'),
        'period_end' => $period_end->format('Y-m-d H:i:s'),
    ];
}

function ruiyi_get_current_auto_settlement_period() {
    $next_info = ruiyi_get_next_auto_settlement_schedule_info();
    $timezone = wp_timezone();
    $next_run = new DateTime($next_info['next_run'], $timezone);
    $period_start = clone $next_run;
    $period_start->modify('-1 day');
    $period_end = new DateTime(current_time('mysql'), $timezone);

    $last_settlement_time = get_option('ruiyi_last_settlement_time', '');
    if (!empty($last_settlement_time)) {
        try {
            $last_settlement_dt = new DateTime($last_settlement_time, $timezone);
            if ($last_settlement_dt > $period_start && $last_settlement_dt < $period_end) {
                $period_start = $last_settlement_dt;
            }
        } catch (Exception $e) {
            // Ignore malformed timestamps and keep calculated period.
        }
    }

    return [
        'business_date' => $next_info['business_date'],
        'period_start' => $period_start->format('Y-m-d H:i:s'),
        'period_end' => $period_end->format('Y-m-d H:i:s'),
    ];
}

function ruiyi_collect_settlement_order_ids($period_start, $period_end) {
    if (!function_exists('wc_get_orders')) {
        return [];
    }

    $range = $period_start . '...' . $period_end;
    $order_ids = [];
    $query_fields = ['date_completed', 'date_created'];

    foreach ($query_fields as $query_field) {
        $result = wc_get_orders([
            'status' => ['wc-completed'],
            'type' => 'shop_order',
            'limit' => -1,
            'return' => 'ids',
            $query_field => $range,
        ]);

        if (!empty($result) && is_array($result)) {
            $order_ids = array_merge($order_ids, $result);
        }
    }

    $order_ids = array_values(array_unique(array_map('intval', $order_ids)));
    sort($order_ids);

    return $order_ids;
}

function ruiyi_get_order_settlement_breakdown($order) {
    $payment_method = $order->get_payment_method();
    $payment_detail = $order->get_meta('_payment_method_detail', true);
    $cash_amount = floatval($order->get_meta('_cash_amount', true) ?: $order->get_meta('_payment_cash_amount', true));
    $card_amount = floatval($order->get_meta('_card_amount', true) ?: $order->get_meta('_payment_card_amount', true));
    $bizum_amount = floatval($order->get_meta('_bizum_amount', true));
    $company_ticket_amount = floatval($order->get_meta('_company_ticket_amount', true));
    $cheque_amount = floatval($order->get_meta('_cheque_restaurante_amount', true));
    $order_total = floatval($order->get_total());
    $discount_percent = floatval($order->get_meta('_manual_discount_percent', true));
    $discount_amount = floatval($order->get_meta('_manual_discount_amount', true));

    $actual_total = $order_total;
    if ($cash_amount > 0 || $card_amount > 0 || $bizum_amount > 0) {
        $actual_total = round($cash_amount + $card_amount + $bizum_amount, 2);
    } elseif ($cheque_amount > 0) {
        $actual_total = round(max(0, $order_total - $cheque_amount), 2);
    }

    $breakdown = [
        'payment_method' => $payment_method,
        'payment_detail' => $payment_detail,
        'total_amount' => round($actual_total, 2),
        'cash_amount' => 0.0,
        'card_amount' => 0.0,
        'bizum_amount' => 0.0,
        'company_ticket_amount' => 0.0,
        'discount_percent' => $discount_percent,
        'discount_amount' => round($discount_amount, 2),
    ];

    if ($payment_detail === 'mixed' || $payment_method === 'mixed') {
        $breakdown['cash_amount'] = round($cash_amount, 2);
        $breakdown['card_amount'] = round($card_amount, 2);
        $breakdown['company_ticket_amount'] = round($company_ticket_amount, 2);
    } elseif ($payment_detail === 'bizum' || $payment_method === 'bizum') {
        $breakdown['bizum_amount'] = round($bizum_amount > 0 ? $bizum_amount : $actual_total, 2);
    } elseif ($payment_detail === 'card' || in_array($payment_method, ['bacs', 'card', 'pos_tarjeta', 'tarjeta'], true)) {
        $breakdown['card_amount'] = round($card_amount > 0 ? $card_amount : $actual_total, 2);
    } elseif ($payment_detail === 'cash' || in_array($payment_method, ['cod', 'cash'], true)) {
        $breakdown['cash_amount'] = round($cash_amount > 0 ? $cash_amount : $actual_total, 2);
    } elseif ($payment_detail === 'company_ticket' || in_array($payment_method, ['company_ticket', 'company_ticket_only', 'pos_company_ticket'], true)) {
        $breakdown['company_ticket_amount'] = round($company_ticket_amount > 0 ? $company_ticket_amount : $actual_total, 2);
    } else {
        $breakdown['cash_amount'] = round($actual_total, 2);
    }

    return $breakdown;
}

function ruiyi_build_daily_summary_from_wc_orders($period_start, $period_end, $business_date = '') {
    $business_date = $business_date ?: ruiyi_get_business_date_from_datetime($period_end);

    $summary = [
        'start_date' => substr($period_start, 0, 10),
        'start_datetime' => $period_start,
        'business_date' => $business_date,
        'total_amount' => 0,
        'card_amount' => 0,
        'cash_amount' => 0,
        'bizum_amount' => 0,
        'company_ticket_amount' => 0,
        'mixed_payment_count' => 0,
        'total_discount_amount' => 0,
        'discount_orders_count' => 0,
        'original_total_before_discount' => 0,
        'products' => [],
        'transactions' => [],
        'last_updated' => $period_end,
    ];

    $starting_cash_enabled = get_option('pos_starting_cash_enabled', '0') === '1';
    $starting_cash_data = get_option('ruiyi_pos_starting_cash', ['amount' => 0]);
    $starting_cash = $starting_cash_enabled ? floatval($starting_cash_data['amount']) : 0;

    $start_ts = strtotime($period_start);
    $end_ts = strtotime($period_end);
    $order_ids = ruiyi_collect_settlement_order_ids($period_start, $period_end);

    foreach ($order_ids as $order_id) {
        $order = wc_get_order($order_id);
        if (!$order || $order->get_type() === 'shop_order_refund') {
            continue;
        }

        $effective_date = $order->get_date_completed();
        if (!$effective_date) {
            $effective_date = $order->get_date_created();
        }
        if (!$effective_date) {
            continue;
        }

        $effective_ts = $effective_date->getTimestamp();
        if ($effective_ts < $start_ts || $effective_ts >= $end_ts) {
            continue;
        }

        $breakdown = ruiyi_get_order_settlement_breakdown($order);
        $summary['total_amount'] = round($summary['total_amount'] + $breakdown['total_amount'], 2);
        $summary['cash_amount'] = round($summary['cash_amount'] + $breakdown['cash_amount'], 2);
        $summary['card_amount'] = round($summary['card_amount'] + $breakdown['card_amount'], 2);
        $summary['bizum_amount'] = round($summary['bizum_amount'] + $breakdown['bizum_amount'], 2);
        $summary['company_ticket_amount'] = round($summary['company_ticket_amount'] + $breakdown['company_ticket_amount'], 2);

        if (
            ($breakdown['cash_amount'] > 0 && $breakdown['card_amount'] > 0) ||
            $breakdown['payment_detail'] === 'mixed' ||
            $breakdown['payment_method'] === 'mixed'
        ) {
            $summary['mixed_payment_count']++;
        }

        if ($breakdown['discount_amount'] > 0) {
            $summary['total_discount_amount'] = round($summary['total_discount_amount'] + $breakdown['discount_amount'], 2);
            $summary['discount_orders_count']++;
            $summary['original_total_before_discount'] = round(
                $summary['original_total_before_discount'] + $breakdown['total_amount'] + $breakdown['discount_amount'],
                2
            );
        }

        foreach ($order->get_items() as $item) {
            $product_name = $item->get_name();
            $product_quantity = intval($item->get_quantity());
            $product_total = floatval($item->get_total());
            $product_category = 'Sin categoría';

            if ($item->get_product_id()) {
                $terms = get_the_terms($item->get_product_id(), 'product_cat');
                if ($terms && !is_wp_error($terms)) {
                    $product_category = $terms[0]->name;
                }
            }

            if (isset($summary['products'][$product_name])) {
                $summary['products'][$product_name]['quantity'] += $product_quantity;
                $summary['products'][$product_name]['total'] += $product_total;
                $summary['products'][$product_name]['category'] = $product_category;
            } else {
                $summary['products'][$product_name] = [
                    'name' => $product_name,
                    'category' => $product_category,
                    'quantity' => $product_quantity,
                    'total' => $product_total,
                ];
            }
        }

        $summary['transactions'][] = [
            'order_id' => $order_id,
            'time' => $effective_date->date('Y-m-d H:i:s'),
            'payment_method' => $breakdown['payment_method'],
            'payment_detail' => $breakdown['payment_detail'],
            'amount' => $breakdown['total_amount'],
            'cash_amount' => $breakdown['cash_amount'],
            'card_amount' => $breakdown['card_amount'],
            'bizum_amount' => $breakdown['bizum_amount'],
            'company_ticket_amount' => $breakdown['company_ticket_amount'],
            'discount_percent' => $breakdown['discount_percent'],
            'discount_amount' => $breakdown['discount_amount'],
            'cashier' => $order->get_meta('_pos_cashier', true),
        ];
    }

    return [
        'summary' => $summary,
        'starting_cash' => $starting_cash,
        'starting_cash_enabled' => $starting_cash_enabled,
        'orders_count' => count($summary['transactions']),
        'period_start' => $period_start,
        'period_end' => $period_end,
    ];
}

function ruiyi_get_daily_summary() {
    if (!is_user_logged_in()) {
        wp_send_json_error(['message' => 'Authentication required']);
        return;
    }

    // Verify nonce for security
    check_ajax_referer('ruiyi_pos_nonce', 'nonce');

    $settlement_mode = get_option('pos_settlement_mode', 'manual');
    $starting_cash_enabled = get_option('pos_starting_cash_enabled', '0') === '1';
    $starting_cash_data = get_option('ruiyi_pos_starting_cash', ['amount' => 0]);
    $starting_cash = $starting_cash_enabled ? floatval($starting_cash_data['amount']) : 0;

    if ($settlement_mode === 'auto') {
        $current_date = current_time('Y-m-d');
        $period_start = $current_date . ' 00:00:00';
        $period_end = current_time('mysql');
        $built = ruiyi_build_daily_summary_from_wc_orders($period_start, $period_end, $current_date);
        $daily_data = $built['summary'];
        $products_array = array_values($daily_data['products']);

        usort($products_array, function($a, $b) {
            return $b['quantity'] - $a['quantity'];
        });

        wp_send_json_success([
            'total_amount' => number_format($daily_data['total_amount'], 2, '.', ''),
            'card_amount' => number_format($daily_data['card_amount'], 2, '.', ''),
            'cash_amount' => number_format($daily_data['cash_amount'], 2, '.', ''),
            'bizum_amount' => number_format($daily_data['bizum_amount'], 2, '.', ''),
            'company_ticket_amount' => number_format($daily_data['company_ticket_amount'], 2, '.', ''),
            'products' => $products_array,
            'start_date' => $daily_data['start_date'],
            'start_datetime' => $period_start,
            'current_date' => $daily_data['business_date'],
            'end_datetime' => $period_end,
            'orders_count' => $built['orders_count'],
            'last_updated' => $daily_data['last_updated'],
            'starting_cash' => $built['starting_cash'],
            'starting_cash_enabled' => $built['starting_cash_enabled'],
            'total_cash_with_starting' => number_format($daily_data['cash_amount'] + $built['starting_cash'], 2, '.', ''),
            'last_auto_settlement_time' => '',
            'last_auto_settlement_date' => ''
        ]);
        return;
    }

    // 🔥 手动模式：读取持续累加的数据
    $daily_data_key = 'ruiyi_daily_summary_current';

    // 从临时存储获取累计数据
    $daily_data = get_option($daily_data_key, [
        'start_date' => current_time('Y-m-d'), // 累计开始日期
        'total_amount' => 0,
        'card_amount' => 0,
        'cash_amount' => 0,
        'bizum_amount' => 0,
        'company_ticket_amount' => 0,
        'mixed_payment_count' => 0,
        'products' => [],
        'transactions' => [],
        'last_updated' => current_time('mysql')
    ]);

    // 转换产品数组为数值索引数组
    $products_array = array_values($daily_data['products']);

    // 按销量排序产品
    usort($products_array, function($a, $b) {
        return $b['quantity'] - $a['quantity'];
    });

    // 记录日志
    ruiyi_debug_log(sprintf(
        '[日结单] 读取数据 - 总额: €%.2f, 刷卡: €%.2f, 现金: €%.2f, 产品种类: %d, 交易数: %d',
        $daily_data['total_amount'],
        $daily_data['card_amount'],
        $daily_data['cash_amount'],
        count($products_array),
        count($daily_data['transactions'])
    ));

    // Prepare response data
    $response_data = array(
        'total_amount' => number_format($daily_data['total_amount'], 2, '.', ''),
        'card_amount' => number_format($daily_data['card_amount'], 2, '.', ''),
        'cash_amount' => number_format($daily_data['cash_amount'], 2, '.', ''),
        'bizum_amount' => number_format(isset($daily_data['bizum_amount']) ? $daily_data['bizum_amount'] : 0, 2, '.', ''),
        'company_ticket_amount' => number_format($daily_data['company_ticket_amount'], 2, '.', ''),
        'products' => $products_array,
        'start_date' => isset($daily_data['start_date']) ? $daily_data['start_date'] : current_time('Y-m-d'), // 累计开始日期
        'start_datetime' => isset($daily_data['start_datetime']) ? $daily_data['start_datetime'] : current_time('mysql'), // 🔥 开始日期时间
        'current_date' => current_time('Y-m-d'), // 当前日期
        'end_datetime' => current_time('mysql'), // 🔥 结束日期时间（当前时间）
        'orders_count' => count($daily_data['transactions']),
        'last_updated' => $daily_data['last_updated'],
        // 🔥 启始现金相关数据
        'starting_cash' => $starting_cash,
        'starting_cash_enabled' => $starting_cash_enabled,
        'total_cash_with_starting' => number_format($daily_data['cash_amount'] + $starting_cash, 2, '.', ''),
        // 🔥 自动结算信息
        'last_auto_settlement_time' => get_option('ruiyi_last_auto_settlement_time', ''),
        'last_auto_settlement_date' => get_option('ruiyi_last_auto_settlement_date', '')
    );

    wp_send_json_success($response_data);
}

// ==================== 启始现金功能 AJAX Handlers ====================

/**
 * AJAX Handler: 获取启始现金
 */
add_action('wp_ajax_ruiyi_get_starting_cash', 'ruiyi_get_starting_cash');
add_action('wp_ajax_nopriv_ruiyi_get_starting_cash', 'ruiyi_get_starting_cash');

function ruiyi_get_starting_cash() {
    if (!is_user_logged_in()) {
        wp_send_json_error(['message' => 'Authentication required']);
        return;
    }

    check_ajax_referer('ruiyi_pos_nonce', 'nonce');

    $starting_cash_data = get_option('ruiyi_pos_starting_cash', [
        'amount' => 0,
        'updated_at' => '',
        'updated_by' => 0
    ]);

    // 检查功能是否启用
    $is_enabled = get_option('pos_starting_cash_enabled', '0') === '1';

    wp_send_json_success([
        'amount' => floatval($starting_cash_data['amount']),
        'updated_at' => $starting_cash_data['updated_at'],
        'updated_by' => $starting_cash_data['updated_by'],
        'is_enabled' => $is_enabled
    ]);
}

/**
 * AJAX Handler: 保存启始现金
 */
add_action('wp_ajax_ruiyi_save_starting_cash', 'ruiyi_save_starting_cash');

function ruiyi_save_starting_cash() {
    check_ajax_referer('ruiyi_pos_nonce', 'nonce');

    $amount = isset($_POST['amount']) ? floatval($_POST['amount']) : 0;

    // 验证金额必须 >= 0
    if ($amount < 0) {
        wp_send_json_error(['message' => '启始现金不能为负数']);
        return;
    }

    $data = [
        'amount' => $amount,
        'updated_at' => current_time('mysql'),
        'updated_by' => get_current_user_id()
    ];

    update_option('ruiyi_pos_starting_cash', $data);

    ruiyi_debug_log(sprintf('[启始现金] 已保存: €%.2f 由用户 #%d', $amount, get_current_user_id()));

    wp_send_json_success([
        'amount' => $amount,
        'message' => '启始现金已保存'
    ]);
}

/**
 * AJAX Handler: 清零启始现金
 */
add_action('wp_ajax_ruiyi_clear_starting_cash', 'ruiyi_clear_starting_cash');

function ruiyi_clear_starting_cash() {
    check_ajax_referer('ruiyi_pos_nonce', 'nonce');

    // 记录清零日志
    $old_data = get_option('ruiyi_pos_starting_cash', ['amount' => 0]);
    ruiyi_debug_log(sprintf('[启始现金] 已清零: 原金额 €%.2f 由用户 #%d', $old_data['amount'], get_current_user_id()));

    // 删除启始现金数据
    delete_option('ruiyi_pos_starting_cash');

    wp_send_json_success([
        'message' => '启始现金已清零'
    ]);
}

// ==================== 结束：启始现金功能 ====================

// ==================== 日结单自动结算功能 ====================

/**
 * 注册自动结算Cron任务
 */
function ruiyi_schedule_auto_settlement() {
    // 清除现有任务
    $timestamp = wp_next_scheduled('ruiyi_auto_daily_settlement');
    if ($timestamp) {
        wp_unschedule_event($timestamp, 'ruiyi_auto_daily_settlement');
    }

    // 获取用户设定的自动结算时间（默认00:00）
    $settlement_time = get_option('pos_auto_settlement_time', '00:00');
    $time_parts = explode(':', $settlement_time);
    $target_hour = isset($time_parts[0]) ? intval($time_parts[0]) : 0;
    $target_minute = isset($time_parts[1]) ? intval($time_parts[1]) : 0;

    // 计算下一个执行时间
    $timezone = wp_timezone();
    $now = new DateTime('now', $timezone);
    $next_run = new DateTime('today', $timezone);
    $next_run->setTime($target_hour, $target_minute, 0);

    // 如果今天的目标时间已过，则设置为明天
    if ($next_run <= $now) {
        $next_run->modify('+1 day');
    }

    // 注册每日执行的Cron任务
    wp_schedule_event($next_run->getTimestamp(), 'daily', 'ruiyi_auto_daily_settlement');

    ruiyi_debug_log(sprintf('[日结单] 已注册自动结算任务，设定时间: %s，下次执行: %s',
        $settlement_time, $next_run->format('Y-m-d H:i:s')));
}

/**
 * 获取最近一次应执行的自动结算计划信息
 */
function ruiyi_get_auto_settlement_schedule_info() {
    $settlement_time = get_option('pos_auto_settlement_time', '00:00');
    $time_parts = explode(':', $settlement_time);
    $target_hour = isset($time_parts[0]) ? intval($time_parts[0]) : 0;
    $target_minute = isset($time_parts[1]) ? intval($time_parts[1]) : 0;

    $timezone = wp_timezone();
    $now = new DateTime('now', $timezone);
    $scheduled = new DateTime($now->format('Y-m-d'), $timezone);
    $scheduled->setTime($target_hour, $target_minute, 0);

    // 取最近一次应执行的计划时间，解决 WP-Cron 延迟执行时业务日期错位问题
    if ($scheduled > $now) {
        $scheduled->modify('-1 day');
    }

    $business_date = clone $scheduled;
    if ($target_hour < 4) {
        $business_date->modify('-1 day');
    }

    return [
        'settlement_time' => $settlement_time,
        'target_hour' => $target_hour,
        'target_minute' => $target_minute,
        'scheduled_datetime' => $scheduled->format('Y-m-d H:i:s'),
        'business_date' => $business_date->format('Y-m-d'),
        'now' => $now->format('Y-m-d H:i:s'),
    ];
}

/**
 * 确保自动结算的 WP-Cron 任务存在
 */
function ruiyi_ensure_auto_settlement_scheduled() {
    if (wp_next_scheduled('ruiyi_auto_daily_settlement')) {
        ruiyi_unschedule_auto_settlement();
    }
}
add_action('init', 'ruiyi_ensure_auto_settlement_scheduled', 20);

/**
 * 获取结算锁，避免前端自动、补偿执行和 WP-Cron 并发生成重复日结单
 */
function ruiyi_acquire_settlement_lock($context = '') {
    $lock_key = 'ruiyi_daily_settlement_lock';
    $now = current_time('timestamp');
    $lock_payload = [
        'locked_at' => current_time('mysql'),
        'timestamp' => $now,
        'context' => $context,
    ];

    if (add_option($lock_key, $lock_payload, '', 'no')) {
        return true;
    }

    $existing_lock = get_option($lock_key, []);
    $existing_timestamp = isset($existing_lock['timestamp']) ? intval($existing_lock['timestamp']) : 0;

    // 超过5分钟视为死锁，允许自动恢复
    if ($existing_timestamp > 0 && ($now - $existing_timestamp) > 300) {
        delete_option($lock_key);
        if (add_option($lock_key, $lock_payload, '', 'no')) {
            ruiyi_debug_log('[日结单自动] 检测到过期结算锁，已自动清理并重新获取');
            return true;
        }
    }

    return false;
}

function ruiyi_release_settlement_lock() {
    delete_option('ruiyi_daily_settlement_lock');
}

/**
 * 取消自动结算Cron任务
 */
function ruiyi_unschedule_auto_settlement() {
    $timestamp = wp_next_scheduled('ruiyi_auto_daily_settlement');
    if ($timestamp) {
        wp_unschedule_event($timestamp, 'ruiyi_auto_daily_settlement');
        ruiyi_debug_log('[日结单] 已取消自动结算任务');
    }
}

// 注册Cron hook
add_action('ruiyi_auto_daily_settlement', 'ruiyi_execute_auto_settlement');

/**
 * 执行自动结算
 * @param bool $is_compensate 是否为补偿执行
 * @param string $target_date 目标日期 (Y-m-d格式)，用于补偿执行
 */
function ruiyi_execute_auto_settlement($is_compensate = false, $target_date = '') {
    // 检查是否启用自动模式
    if (get_option('pos_settlement_mode', 'manual') !== 'auto') {
        return;
    }

    if (!ruiyi_acquire_settlement_lock($is_compensate ? 'auto_compensate' : 'auto_cron')) {
        ruiyi_debug_log('[日结单自动] 已有其他结算任务在执行，跳过本次自动结算');
        return;
    }

    try {
        $schedule_info = ruiyi_get_auto_settlement_schedule_info();

        // 确定要结算的业务日期
        if ($is_compensate && $target_date) {
            $business_date = $target_date;
        } else {
            $business_date = $schedule_info['business_date'];
        }

        $period_info = ruiyi_get_auto_settlement_schedule_for_business_date($business_date);
        $built_data = ruiyi_build_daily_summary_from_wc_orders(
            $period_info['period_start'],
            $period_info['period_end'],
            $business_date
        );
        $daily_data = $built_data['summary'];

        // 如果没有数据，跳过（不生成记录）
        if (empty($daily_data) || !isset($daily_data['total_amount']) || floatval($daily_data['total_amount']) <= 0) {
            ruiyi_debug_log(sprintf('[日结单自动] %s 无数据，跳过结算', $business_date));
            // 更新上次自动结算检查时间
            update_option('ruiyi_last_auto_settlement_check', current_time('mysql'));
            update_option('ruiyi_last_auto_settlement_date', $business_date);
            return;
        }

        // 检查是否已经结算过（防止重复）
        $settlement_history = get_option('ruiyi_daily_settlement_history', []);
        foreach ($settlement_history as $record) {
            if (
                isset($record['business_date']) &&
                $record['business_date'] === $business_date &&
                isset($record['settlement_type']) &&
                in_array($record['settlement_type'], ['auto', 'auto_frontend'], true)
            ) {
                ruiyi_debug_log(sprintf('[日结单自动] %s 已自动结算过，跳过', $business_date));
                return;
            }
        }

        // 执行结算
        $daily_data['start_datetime'] = $period_info['period_start'];
        $daily_data['end_datetime'] = $period_info['period_end'];
        $result = ruiyi_do_auto_settlement($business_date, $daily_data);

        if ($result['success']) {
            ruiyi_debug_log(sprintf('[日结单自动] %s 自动结算成功，总额: €%.2f',
                $business_date, $daily_data['total_amount']));

            // 更新上次自动结算时间
            update_option('ruiyi_last_auto_settlement_time', current_time('mysql'));
            update_option('ruiyi_last_auto_settlement_date', $business_date);
        } else {
            ruiyi_debug_log(sprintf('[日结单自动] %s 自动结算失败: %s', $business_date, $result['message']));
        }
    } finally {
        ruiyi_release_settlement_lock();
    }
}

/**
 * 执行自动结算的核心保存逻辑
 */
function ruiyi_do_auto_settlement($business_date, $daily_data) {
    try {
        $settlement_datetime = current_time('mysql');
        $settlement_timestamp = strtotime($settlement_datetime);

        // 获取开始时间
        $period_start = isset($daily_data['start_datetime']) ? $daily_data['start_datetime'] : $business_date . ' 00:00:00';
        $period_end = isset($daily_data['end_datetime']) ? $daily_data['end_datetime'] : $settlement_datetime;

        // 准备分类数据
        $categories_data = [];
        if (isset($daily_data['products']) && !empty($daily_data['products'])) {
            foreach ($daily_data['products'] as $product) {
                $category = isset($product['category']) ? $product['category'] : 'Sin categoría';
                if (!isset($categories_data[$category])) {
                    $categories_data[$category] = ['name' => $category, 'total' => 0];
                }
                $categories_data[$category]['total'] += floatval($product['total']);
            }
        }

        // 创建月结单文章
        $settlement_time_display = date('Y-m-d H:i', $settlement_timestamp);
        $post_title = sprintf('日结单 - %s（自动结算：%s）', $business_date, $settlement_time_display);

        $post_id = wp_insert_post([
            'post_type' => 'monthly_summary',
            'post_title' => $post_title,
            'post_status' => 'publish',
            'post_author' => 1 // 系统自动执行，使用管理员ID
        ]);

        if (is_wp_error($post_id)) {
            return ['success' => false, 'message' => '创建月结单文章失败'];
        }

        // 保存meta数据
        update_post_meta($post_id, '_summary_date', $business_date);
        update_post_meta($post_id, '_business_date', $business_date);
        update_post_meta($post_id, '_settlement_datetime', $settlement_datetime);
        update_post_meta($post_id, '_settlement_type', 'auto'); // 标记为自动结算
        update_post_meta($post_id, '_period_start', $period_start);
        update_post_meta($post_id, '_period_end', $period_end);
        update_post_meta($post_id, '_total_amount', floatval($daily_data['total_amount']));
        update_post_meta($post_id, '_cash_amount', floatval($daily_data['cash_amount']));
        update_post_meta($post_id, '_card_amount', floatval($daily_data['card_amount']));
        update_post_meta($post_id, '_bizum_amount', floatval(isset($daily_data['bizum_amount']) ? $daily_data['bizum_amount'] : 0));
        update_post_meta($post_id, '_categories_data', json_encode(array_values($categories_data), JSON_UNESCAPED_UNICODE));

        // 获取并保存启始现金
        $starting_cash_data = get_option('ruiyi_pos_starting_cash', ['amount' => 0]);
        $starting_cash = floatval($starting_cash_data['amount']);
        update_post_meta($post_id, '_starting_cash', $starting_cash);

        // 保存到历史日结单
        $history_key = 'ruiyi_daily_settlement_history';
        $history_data = get_option($history_key, []);

        $settlement_id = 'settlement_' . $settlement_timestamp;
        $history_data[$settlement_id] = [
            'id' => $settlement_id,
            'business_date' => $business_date,
            'settlement_datetime' => $settlement_datetime,
            'settlement_type' => 'auto', // 标记为自动结算
            'period_start' => $period_start,
            'period_end' => $period_end,
            'total_amount' => floatval($daily_data['total_amount']),
            'cash_amount' => floatval($daily_data['cash_amount']),
            'card_amount' => floatval($daily_data['card_amount']),
            'bizum_amount' => floatval(isset($daily_data['bizum_amount']) ? $daily_data['bizum_amount'] : 0),
            'starting_cash' => $starting_cash,
            'products' => isset($daily_data['products']) ? $daily_data['products'] : [],
            'transactions' => isset($daily_data['transactions']) ? $daily_data['transactions'] : [],
            'categories_data' => array_values($categories_data),
            'saved_by' => 'system_auto',
            'monthly_post_id' => $post_id
        ];

        krsort($history_data);
        if (count($history_data) > 60) {
            $history_data = array_slice($history_data, 0, 60, true);
        }
        update_option($history_key, $history_data);

        // 删除临时数据
        delete_option('ruiyi_daily_summary_current');

        // 更新上次结算时间
        update_option('ruiyi_last_settlement_time', $settlement_datetime, 'no');

        return ['success' => true, 'post_id' => $post_id];

    } catch (Exception $e) {
        ruiyi_debug_log('[日结单自动] 保存失败: ' . $e->getMessage());
        return ['success' => false, 'message' => $e->getMessage()];
    }
}

/**
 * 页面加载时检查并补偿执行自动结算
 * 解决WordPress Cron可能因无访问而错过执行的问题
 */
function ruiyi_check_auto_settlement_compensation() {
    return;
}

// 在init时检查补偿执行
add_action('init', 'ruiyi_check_auto_settlement_compensation');

// ==================== 结束：日结单自动结算功能 ====================

// AJAX Handler: Clear Daily Summary Data After Print
add_action('wp_ajax_ruiyi_clear_daily_summary', 'ruiyi_clear_daily_summary');
add_action('wp_ajax_nopriv_ruiyi_clear_daily_summary', 'ruiyi_clear_daily_summary');

function ruiyi_clear_daily_summary() {
    if (!is_user_logged_in()) {
        wp_send_json_error(['message' => 'Authentication required']);
        return;
    }

    // Verify nonce for security
    check_ajax_referer('ruiyi_pos_nonce', 'nonce');

    // 🔥 累计模式：清空累计数据
    $daily_data_key = 'ruiyi_daily_summary_current';
    $today = current_time('Y-m-d');

    // 🔥 获取累计数据以便归档
    $daily_data = get_option($daily_data_key, []);

    // Store the clearing timestamp in options table
    // This can be used to track when the last daily settlement was performed
    $clear_record = array(
        'date' => $today,
        'timestamp' => current_time('mysql'),
        'user_id' => get_current_user_id()
    );

    // Save to transient or option
    update_option('ruiyi_last_daily_settlement', $clear_record);

    // 🔥 关键修复：归档并删除累计数据
    if (!empty($daily_data) && isset($daily_data['total_amount'])) {
        // 归档日结单数据到历史记录
        $archive_key = 'ruiyi_daily_summary_archive';
        $archive_data = get_option($archive_key, []);

        // 使用时间戳作为归档key，支持一天多次结单
        $archive_timestamp = current_time('Y-m-d_H-i-s');
        $archive_data[$archive_timestamp] = [
            'start_date' => isset($daily_data['start_date']) ? $daily_data['start_date'] : '未知',
            'end_date' => $today,
            'data' => $daily_data,
            'printed_at' => current_time('mysql'),
            'printed_by' => get_current_user_id()
        ];

        // 只保留最近30次归档数据
        if (count($archive_data) > 30) {
            $archive_data = array_slice($archive_data, -30, 30, true);
        }

        update_option($archive_key, $archive_data, 'no');

        // 🔥 删除累计数据（重要！）
        delete_option($daily_data_key);

        ruiyi_debug_log(sprintf(
            '[日结单] 累计数据已清空并归档 - 开始日期: %s, 结束日期: %s, 总额: €%.2f, 操作者: %d',
            isset($daily_data['start_date']) ? $daily_data['start_date'] : '未知',
            $today,
            $daily_data['total_amount'],
            get_current_user_id()
        ));
    } else {
        ruiyi_debug_log('[日结单] 无累计数据需要清空 - 日期: ' . $today . ', 操作者: ' . get_current_user_id());
    }

    wp_send_json_success(array(
        'message' => '日结单数据已清空，下次订单将重新累计',
        'cleared_date' => $today,
        'timestamp' => $clear_record['timestamp'],
        'total_cleared' => isset($daily_data['total_amount']) ? $daily_data['total_amount'] : 0
    ));
}

/**
 * ========================================
 * Daily Settlement Independent Data System
 * 日结单独立数据系统
 * ========================================
 */

/**
 * Record POS transaction to daily summary temporary storage
 * Called after each order is completed
 *
 * @param int $order_id WooCommerce order ID
 * @param string $payment_method Payment method (cash, card, mixed, etc.)
 * @param float $total_amount Total amount
 * @param array $items Order items
 */
function ruiyi_record_daily_transaction($order_id, $payment_method, $total_amount, $items) {
    // 🔥 累计模式：使用固定key持续累加，直到手动打印结单
    $daily_data_key = 'ruiyi_daily_summary_current';

    // Get current cumulative data (累计数据)
    $daily_data = get_option($daily_data_key, [
        'start_date' => current_time('Y-m-d'), // 记录累计开始日期
        'start_datetime' => current_time('mysql'), // 🔥 记录累计开始日期时间
        'total_amount' => 0,
        'card_amount' => 0,
        'cash_amount' => 0,
        'bizum_amount' => 0,
        'company_ticket_amount' => 0,
        'mixed_payment_count' => 0,
        // 🔥 新增折扣统计字段
        'total_discount_amount' => 0,  // 折扣总金额
        'discount_orders_count' => 0,   // 有折扣的订单数量
        'original_total_before_discount' => 0, // 折扣前原价总额
        'products' => [],
        'transactions' => [],
        'last_updated' => current_time('mysql')
    ]);

    // 🔥 确保旧数据也有折扣字段（向后兼容）
    if (!isset($daily_data['total_discount_amount'])) {
        $daily_data['total_discount_amount'] = 0;
    }
    if (!isset($daily_data['discount_orders_count'])) {
        $daily_data['discount_orders_count'] = 0;
    }
    if (!isset($daily_data['original_total_before_discount'])) {
        $daily_data['original_total_before_discount'] = 0;
    }
    if (!isset($daily_data['bizum_amount'])) {
        $daily_data['bizum_amount'] = 0;
    }

    // 🔥 关键修复：检查订单是否已经记录过（防止重复记录导致金额翻倍）
    if (!empty($daily_data['transactions']) && is_array($daily_data['transactions'])) {
        foreach ($daily_data['transactions'] as $transaction) {
            if (isset($transaction['order_id']) && $transaction['order_id'] == $order_id) {
                ruiyi_debug_log("[日结单] ⚠️ 订单 #{$order_id} 已存在于日结单中，跳过重复记录");
                return;
            }
        }
    }

    // 🔥 如果是第一笔交易（累计金额为0），记录开始时间
    if (empty($daily_data['start_datetime']) || $daily_data['total_amount'] == 0) {
        $daily_data['start_datetime'] = current_time('mysql');
    }

    // 🔥 初始化折扣变量（用于后续交易记录）
    $discount_percent = 0;
    $discount_amount = 0;

    // 🔥 修复：获取订单对象检查实际支付详情
    $order = wc_get_order($order_id);

    // 🔥 关键修复：先获取实际支付金额，再计算日结单总额
    // 日结单总额应该是实际收款金额（现金+刷卡），不包含抵扣券
    $actual_daily_total = $total_amount; // 默认使用传入值

    if ($order) {
        // 🔥 关键修复：优先从元数据读取支付详情，而不是仅依赖payment_method
        $payment_detail = $order->get_meta('_payment_method_detail', true);
        $cash_meta = floatval($order->get_meta('_cash_amount', true));
        $card_meta = floatval($order->get_meta('_card_amount', true));
        $ticket_meta = floatval($order->get_meta('_company_ticket_amount', true));
        $cheque_meta = floatval($order->get_meta('_cheque_restaurante_amount', true));
        $bizum_meta = floatval($order->get_meta('_bizum_amount', true));

        // 🔥 关键修复：如果有现金、刷卡或Bizum元数据，使用它们的总和作为日结单总额
        // 这确保日结单记录的是实际收款金额（不含抵扣券）
        if ($cash_meta > 0 || $card_meta > 0 || $bizum_meta > 0) {
            $actual_daily_total = round($cash_meta + $card_meta + $bizum_meta, 2);
            ruiyi_debug_log("[日结单记录] 🔧 订单 #{$order_id} 使用元数据计算总额: 现金€{$cash_meta} + 刷卡€{$card_meta} + Bizum€{$bizum_meta} = €{$actual_daily_total} (原传入值: €{$total_amount}, 抵扣券: €{$cheque_meta})");
        } else {
            // 如果没有元数据，检查是否有抵扣券需要扣除
            if ($cheque_meta > 0) {
                $actual_daily_total = round(max(0, $total_amount - $cheque_meta), 2);
                ruiyi_debug_log("[日结单记录] 🔧 订单 #{$order_id} 扣除抵扣券后总额: €{$total_amount} - €{$cheque_meta} = €{$actual_daily_total}");
            }
        }

        // 🔥 获取折扣信息
        $discount_percent = floatval($order->get_meta('_manual_discount_percent', true));
        $discount_amount = floatval($order->get_meta('_manual_discount_amount', true));

        // 🔥 累加折扣统计
        // 🔥 【精度修复】使用 round() 避免浮点数精度问题
        if ($discount_amount > 0) {
            $daily_data['total_discount_amount'] = round($daily_data['total_discount_amount'] + round($discount_amount, 2), 2);
            $daily_data['discount_orders_count']++;
            // 计算折扣前原价（基于实际支付金额，不是订单总额）
            $original_total = round($actual_daily_total + $discount_amount, 2);
            $daily_data['original_total_before_discount'] = round($daily_data['original_total_before_discount'] + $original_total, 2);

            ruiyi_debug_log("[日结单记录] 💰 折扣订单 #{$order_id} - 折扣: {$discount_percent}%, 金额: €{$discount_amount}, 折扣前原价: €{$original_total}");
        }

        // 🔥 关键修复：累加日结单总额（使用实际收款金额）
        $daily_data['total_amount'] = round($daily_data['total_amount'] + round($actual_daily_total, 2), 2);

        ruiyi_debug_log("[日结单记录] 订单 #{$order_id} - 传入支付方式: {$payment_method}, 元数据支付详情: {$payment_detail}, 现金meta: {$cash_meta}, 刷卡meta: {$card_meta}, 日结单总额累加: €{$actual_daily_total}");

        // 根据支付方式累加
        // 🔥 【精度修复】所有金额累加都使用 round() 避免浮点数精度问题
        if ($payment_detail === 'mixed' || $payment_method === 'mixed') {
            // 混合支付：分别记录现金和刷卡金额
            $daily_data['mixed_payment_count']++;
            if ($cash_meta > 0) {
                $daily_data['cash_amount'] = round($daily_data['cash_amount'] + round($cash_meta, 2), 2);
                ruiyi_debug_log("[日结单记录] ✅ 混合支付-现金部分: €{$cash_meta}");
            }
            if ($card_meta > 0) {
                $daily_data['card_amount'] = round($daily_data['card_amount'] + round($card_meta, 2), 2);
                ruiyi_debug_log("[日结单记录] ✅ 混合支付-刷卡部分: €{$card_meta}");
            }
            if ($ticket_meta > 0) {
                $daily_data['company_ticket_amount'] = round($daily_data['company_ticket_amount'] + round($ticket_meta, 2), 2);
                ruiyi_debug_log("[日结单记录] ✅ 混合支付-公司钱票部分: €{$ticket_meta}");
            }

            // 如果没有读取到混合支付的详细金额，记录警告
            if (!$cash_meta && !$card_meta && !$ticket_meta) {
                ruiyi_debug_log("[日结单记录] ⚠️ 警告：混合支付订单#{$order_id}未找到详细金额元数据");
            }
        } elseif ($payment_detail === 'card' || $payment_method === 'bacs' || $payment_method === 'card') {
            // 刷卡支付
            if ($card_meta > 0) {
                $daily_data['card_amount'] = round($daily_data['card_amount'] + round($card_meta, 2), 2);
            } else {
                $daily_data['card_amount'] = round($daily_data['card_amount'] + round($total_amount, 2), 2);
            }
            ruiyi_debug_log("[日结单记录] ✅ 归类为刷卡: €{$total_amount}");
        } elseif ($payment_detail === 'bizum' || $payment_method === 'bizum') {
            // Bizum/转账支付
            if ($bizum_meta > 0) {
                $daily_data['bizum_amount'] = round($daily_data['bizum_amount'] + round($bizum_meta, 2), 2);
            } else {
                $daily_data['bizum_amount'] = round($daily_data['bizum_amount'] + round($total_amount, 2), 2);
            }
            ruiyi_debug_log("[日结单记录] ✅ 归类为Bizum/转账: €{$total_amount}");
        } elseif ($payment_detail === 'cash' || $payment_method === 'cod' || $payment_method === 'cash') {
            // 现金支付
            if ($cash_meta > 0) {
                $daily_data['cash_amount'] = round($daily_data['cash_amount'] + round($cash_meta, 2), 2);
            } else {
                $daily_data['cash_amount'] = round($daily_data['cash_amount'] + round($total_amount, 2), 2);
            }
            ruiyi_debug_log("[日结单记录] ✅ 归类为现金: €{$total_amount}");
        } elseif ($payment_method === 'company_ticket' || $payment_detail === 'company_ticket') {
            // 公司钱票
            if ($ticket_meta > 0) {
                $daily_data['company_ticket_amount'] = round($daily_data['company_ticket_amount'] + round($ticket_meta, 2), 2);
            } else {
                $daily_data['company_ticket_amount'] = round($daily_data['company_ticket_amount'] + round($total_amount, 2), 2);
            }
            ruiyi_debug_log("[日结单记录] ✅ 归类为公司钱票: €{$total_amount}");
        } else {
            // 未知支付方式，默认归类为现金
            $daily_data['cash_amount'] = round($daily_data['cash_amount'] + round($total_amount, 2), 2);
            ruiyi_debug_log("[日结单记录] ⚠️ 未知支付方式，默认归类为现金: €{$total_amount}");
        }
    } else {
        // 无法获取订单对象，使用传入的支付方式参数作为备选方案
        ruiyi_debug_log("[日结单记录] ⚠️ 警告：无法获取订单对象 #{$order_id}，使用传入参数: {$payment_method}");

        // 🔥 累加日结单总额（使用传入值作为备选）
        $daily_data['total_amount'] = round($daily_data['total_amount'] + round($total_amount, 2), 2);

        if ($payment_method === 'bacs' || $payment_method === 'card') {
            $daily_data['card_amount'] = round($daily_data['card_amount'] + round($total_amount, 2), 2);
            ruiyi_debug_log("[日结单记录] ✅ 备选方案-归类为刷卡: €{$total_amount}");
        } elseif ($payment_method === 'bizum') {
            $daily_data['bizum_amount'] = round($daily_data['bizum_amount'] + round($total_amount, 2), 2);
            ruiyi_debug_log("[日结单记录] ✅ 备选方案-归类为Bizum/转账: €{$total_amount}");
        } elseif ($payment_method === 'cash' || $payment_method === 'cod') {
            $daily_data['cash_amount'] = round($daily_data['cash_amount'] + round($total_amount, 2), 2);
            ruiyi_debug_log("[日结单记录] ✅ 备选方案-归类为现金: €{$total_amount}");
        } else {
            $daily_data['cash_amount'] = round($daily_data['cash_amount'] + round($total_amount, 2), 2); // 默认
            ruiyi_debug_log("[日结单记录] ⚠️ 备选方案-未知方式，默认现金: €{$total_amount}");
        }
    }

    // Add products to summary
    foreach ($items as $item) {
        $product_name = $item['name'];
        $product_quantity = $item['quantity'];
        $product_total = $item['total'];

        // 🔥 获取产品分类
        $product_category = isset($item['category']) ? $item['category'] : '';

        // 如果没有传入分类，尝试从WooCommerce产品获取
        if (empty($product_category) && isset($item['product_id'])) {
            $product_id = $item['product_id'];

            // 🔥 调试：记录产品ID
            ruiyi_debug_log('[日结单] 尝试获取产品分类 - 产品ID: ' . $product_id . ', 产品名: ' . $product_name);

            $terms = get_the_terms($product_id, 'product_cat');

            // 🔥 调试：记录获取结果
            if ($terms && !is_wp_error($terms)) {
                $product_category = $terms[0]->name;
                ruiyi_debug_log('[日结单] ✅ 成功获取分类 - 产品: ' . $product_name . ', 分类: ' . $product_category);
            } else {
                ruiyi_debug_log('[日结单] ⚠️ 未能获取分类 - 产品ID: ' . $product_id . ', Terms结果: ' . print_r($terms, true));
            }
        }

        // 默认分类
        if (empty($product_category)) {
            $product_category = 'Sin categoría';
            ruiyi_debug_log('[日结单] ⚠️ 使用默认分类 - 产品: ' . $product_name);
        }

        // If product already exists, add to its quantity
        if (isset($daily_data['products'][$product_name])) {
            $daily_data['products'][$product_name]['quantity'] += $product_quantity;
            $daily_data['products'][$product_name]['total'] += $product_total;
            // 🔥 更新分类（以防产品分类变更）
            $daily_data['products'][$product_name]['category'] = $product_category;
        } else {
            $daily_data['products'][$product_name] = [
                'name' => $product_name,
                'category' => $product_category,
                'quantity' => $product_quantity,
                'total' => $product_total
            ];
        }
    }

    // Add transaction record
    $daily_data['transactions'][] = [
        'order_id' => $order_id,
        'time' => current_time('mysql'),
        'payment_method' => $payment_method,
        'amount' => $total_amount,
        // 🔥 新增折扣信息
        'discount_percent' => $discount_percent,
        'discount_amount' => $discount_amount,
        'cashier' => get_current_user_id()
    ];

    $daily_data['last_updated'] = current_time('mysql');

    // Save data
    update_option($daily_data_key, $daily_data, 'no');

    ruiyi_debug_log(sprintf(
        '[日结单] Record transaction - Order: #%d, Amount: €%.2f, Method: %s, Today Total: €%.2f, 现金: €%.2f, 刷卡: €%.2f',
        $order_id,
        $total_amount,
        $payment_method,
        $daily_data['total_amount'],
        $daily_data['cash_amount'],
        $daily_data['card_amount']
    ));
}

