/**
 * Display payment details in order edit page - After order details section
 */
add_action('woocommerce_admin_order_data_after_billing_address', 'ruiyi_display_payment_details_in_order', 10, 1);

function ruiyi_display_payment_details_in_order($order) {
    if (!$order) return;

    $payment_method_detail = $order->get_meta('_payment_method_detail', true);
    $cash_amount = $order->get_meta('_cash_amount', true);
    $card_amount = $order->get_meta('_card_amount', true);
    $received_amount = $order->get_meta('_received_amount', true);
    $change_amount = $order->get_meta('_change_amount', true);

    // Only display if there are payment details
    if (!$payment_method_detail && !$cash_amount && !$card_amount) {
        return;
    }

    ?>
    <div class="order_data_column" style="clear:both; float:none; width:100%; margin-top: 20px;">
        <h3><?php _e('Detalles de Pago', 'ruiyi-pos'); ?></h3>
        <div class="address">
            <?php
            if ($payment_method_detail === 'cash') {
                echo '<p><strong>' . __('Método de Pago:', 'ruiyi-pos') . '</strong> ' . __('Efectivo', 'ruiyi-pos') . '</p>';

                if ($cash_amount > 0) {
                    echo '<p><strong>' . __('Importe en Efectivo:', 'ruiyi-pos') . '</strong> €' . number_format($cash_amount, 2) . '</p>';
                }

                if ($received_amount > 0) {
                    echo '<p><strong>' . __('Efectivo Recibido:', 'ruiyi-pos') . '</strong> €' . number_format($received_amount, 2) . '</p>';
                }

                if ($change_amount > 0) {
                    echo '<p><strong>' . __('Cambio:', 'ruiyi-pos') . '</strong> €' . number_format($change_amount, 2) . '</p>';
                }
            } elseif ($payment_method_detail === 'card') {
                echo '<p><strong>' . __('Método de Pago:', 'ruiyi-pos') . '</strong> ' . __('Tarjeta', 'ruiyi-pos') . '</p>';

                if ($card_amount > 0) {
                    echo '<p><strong>' . __('Importe con Tarjeta:', 'ruiyi-pos') . '</strong> €' . number_format($card_amount, 2) . '</p>';
                } else {
                    echo '<p><strong>' . __('Importe con Tarjeta:', 'ruiyi-pos') . '</strong> €' . number_format($order->get_total(), 2) . '</p>';
                }
            } elseif ($payment_method_detail === 'bizum') {
                echo '<p><strong>' . __('Método de Pago:', 'ruiyi-pos') . '</strong> Bizum/Transferencia</p>';

                $bizum_amount = floatval($order->get_meta('_bizum_amount', true));
                if ($bizum_amount > 0) {
                    echo '<p><strong>' . __('Importe Bizum:', 'ruiyi-pos') . '</strong> €' . number_format($bizum_amount, 2) . '</p>';
                } else {
                    echo '<p><strong>' . __('Importe Bizum:', 'ruiyi-pos') . '</strong> €' . number_format($order->get_total(), 2) . '</p>';
                }
            } elseif ($payment_method_detail === 'mixed') {
                echo '<p><strong>' . __('Método de Pago:', 'ruiyi-pos') . '</strong> ' . __('Mixto (Efectivo + Tarjeta)', 'ruiyi-pos') . '</p>';

                if ($cash_amount > 0) {
                    echo '<p><strong>' . __('Efectivo:', 'ruiyi-pos') . '</strong> €' . number_format($cash_amount, 2) . '</p>';
                }

                if ($card_amount > 0) {
                    echo '<p><strong>' . __('Tarjeta:', 'ruiyi-pos') . '</strong> €' . number_format($card_amount, 2) . '</p>';
                }

                $total_paid = $cash_amount + $card_amount;
                echo '<p><strong>' . __('Total Pagado:', 'ruiyi-pos') . '</strong> €' . number_format($total_paid, 2) . '</p>';
            }
            ?>
        </div>
    </div>
    <?php
}

