function ruiyi_payment_details_meta_box_content($post_or_order_object) {
    $order = ($post_or_order_object instanceof WP_Post) ? wc_get_order($post_or_order_object->ID) : $post_or_order_object;

    if (!$order) return;

    $payment_method_detail = $order->get_meta('_payment_method_detail', true);
    $cash_amount = $order->get_meta('_cash_amount', true);
    $card_amount = $order->get_meta('_card_amount', true);
    $received_amount = $order->get_meta('_received_amount', true);
    $change_amount = $order->get_meta('_change_amount', true);

    echo '<div style="padding: 10px;">';

    if (!$payment_method_detail && !$cash_amount && !$card_amount) {
        echo '<p style="color: #999;">' . __('No hay detalles de pago disponibles.', 'ruiyi-pos') . '</p>';
        echo '</div>';
        return;
    }

    echo '<table style="width: 100%; font-size: 12px;">';

    echo '<tr><td colspan="2" style="padding-bottom: 10px; border-bottom: 1px solid #ddd;"><strong>' . __('Información de Pago', 'ruiyi-pos') . '</strong></td></tr>';

    if ($payment_method_detail) {
        $method_labels = [
            'cash' => __('Efectivo', 'ruiyi-pos'),
            'card' => __('Tarjeta', 'ruiyi-pos'),
            'bizum' => __('Bizum/Transferencia', 'ruiyi-pos'),
            'mixed' => __('Mixto', 'ruiyi-pos')
        ];
        echo '<tr><td style="padding: 5px 0;"><strong>' . __('Método:', 'ruiyi-pos') . '</strong></td><td>' . ($method_labels[$payment_method_detail] ?? $payment_method_detail) . '</td></tr>';
    }

    if ($cash_amount > 0) {
        echo '<tr><td style="padding: 5px 0;"><strong>' . __('Efectivo:', 'ruiyi-pos') . '</strong></td><td>€' . number_format($cash_amount, 2) . '</td></tr>';
    }

    if ($card_amount > 0) {
        echo '<tr><td style="padding: 5px 0;"><strong>' . __('Tarjeta:', 'ruiyi-pos') . '</strong></td><td>€' . number_format($card_amount, 2) . '</td></tr>';
    }

    if ($received_amount > 0) {
        echo '<tr><td style="padding: 5px 0;"><strong>' . __('Recibido:', 'ruiyi-pos') . '</strong></td><td>€' . number_format($received_amount, 2) . '</td></tr>';
    }

    if ($change_amount > 0) {
        echo '<tr><td style="padding: 5px 0;"><strong>' . __('Cambio:', 'ruiyi-pos') . '</strong></td><td>€' . number_format($change_amount, 2) . '</td></tr>';
    }

    if ($payment_method_detail === 'mixed' && $cash_amount > 0 && $card_amount > 0) {
        $total_paid = $cash_amount + $card_amount;
        echo '<tr><td colspan="2" style="padding-top: 10px; border-top: 1px solid #ddd;"></td></tr>';
        echo '<tr><td style="padding: 5px 0;"><strong>' . __('Total Pagado:', 'ruiyi-pos') . '</strong></td><td><strong>€' . number_format($total_paid, 2) . '</strong></td></tr>';
    }

    echo '</table>';
    echo '</div>';
}


