function ruiyi_customer_info_meta_box_content($post_or_order_object) {
    $order = ($post_or_order_object instanceof WP_Post) ? wc_get_order($post_or_order_object->ID) : $post_or_order_object;

    if (!$order) return;

    $fields = [
        '_customer_name'          => 'Cliente',
        '_customer_phone'         => 'Teléfono',
        '_customer_address'       => 'Dirección',
        '_customer_postal_code'   => 'C.P.',
        '_customer_email'         => 'Email',
        '_customer_business_name' => 'Empresa',
        '_customer_cif_nif'       => 'CIF/NIF',
        '_customer_notes'         => 'Notas',
        '_table_number'           => 'Mesa',
        '_order_type'             => 'Tipo de Pedido',
    ];

    $has_data = false;
    $rows = '';

    foreach ($fields as $meta_key => $label) {
        $value = $order->get_meta($meta_key, true);
        if ($value !== '' && $value !== null && $value !== false) {
            $has_data = true;
            $rows .= '<tr><td style="padding: 4px 0; vertical-align: top; white-space: nowrap;"><strong>' . esc_html($label) . ':</strong></td><td style="padding: 4px 0 4px 8px;">' . esc_html($value) . '</td></tr>';
        }
    }

    echo '<div style="padding: 10px;">';

    if (!$has_data) {
        echo '<p style="color: #999;">No hay información de cliente.</p>';
        echo '</div>';
        return;
    }

    echo '<table style="width: 100%; font-size: 12px;">';
    echo $rows;
    echo '</table>';
    echo '</div>';
}


/**
 * 注册自定义混合支付方式到WooCommerce
 */
add_filter('woocommerce_payment_gateways', 'ruiyi_add_mixed_payment_gateway');
function ruiyi_add_mixed_payment_gateway($gateways) {
    $gateways[] = 'WC_Gateway_Mixed_Payment';
    return $gateways;
}

/**
 * 自定义混合支付网关类
 */
add_action('plugins_loaded', 'ruiyi_init_mixed_payment_gateway');
function ruiyi_init_mixed_payment_gateway() {
    if (!class_exists('WC_Payment_Gateway')) {
        return;
    }

    class WC_Gateway_Mixed_Payment extends WC_Payment_Gateway {
        public function __construct() {
            $this->id = 'mixed_payment';
            $this->method_title = __('Pago Mixto', 'ruiyi-pos');
            $this->method_description = __('Pago combinado con efectivo y tarjeta', 'ruiyi-pos');
            $this->has_fields = false;

            $this->init_form_fields();
            $this->init_settings();

            $this->title = $this->get_option('title', __('Pago Mixto', 'ruiyi-pos'));
            $this->description = $this->get_option('description', __('Pago parcial en efectivo y parcial con tarjeta', 'ruiyi-pos'));

            add_action('woocommerce_update_options_payment_gateways_' . $this->id, array($this, 'process_admin_options'));
        }

        public function init_form_fields() {
            $this->form_fields = array(
                'enabled' => array(
                    'title' => __('Activar/Desactivar', 'ruiyi-pos'),
                    'type' => 'checkbox',
                    'label' => __('Activar Pago Mixto', 'ruiyi-pos'),
                    'default' => 'yes'
                ),
                'title' => array(
                    'title' => __('Título', 'ruiyi-pos'),
                    'type' => 'text',
                    'description' => __('Título que se muestra en el checkout', 'ruiyi-pos'),
                    'default' => __('Pago Mixto', 'ruiyi-pos'),
                    'desc_tip' => true,
                ),
                'description' => array(
                    'title' => __('Descripción', 'ruiyi-pos'),
                    'type' => 'textarea',
                    'description' => __('Descripción del método de pago', 'ruiyi-pos'),
                    'default' => __('Pago parcial en efectivo y parcial con tarjeta', 'ruiyi-pos'),
                ),
            );
        }

        public function process_payment($order_id) {
            $order = wc_get_order($order_id);
            $order->payment_complete();
            $order->reduce_order_stock();

            return array(
                'result' => 'success',
                'redirect' => $this->get_return_url($order)
            );
        }
    }
}

/**
 * AJAX处理：用户登出
 */
add_action('wp_ajax_ruiyi_logout_user', 'ruiyi_logout_user_callback');
add_action('wp_ajax_nopriv_ruiyi_logout_user', 'ruiyi_logout_user_callback');

function ruiyi_logout_user_callback() {
    // 验证 nonce
    if (!wp_verify_nonce($_POST['nonce'] ?? '', 'ruiyi_logout_nonce')) {
        wp_send_json_error(array('message' => '安全验证失败'));
        return;
    }

    // 执行登出
    wp_logout();

    // 返回成功响应
    wp_send_json_success(array('message' => '登出成功'));
}

/**
 * 按产品名称中的编号排序（从小到大）
 */
add_filter('woocommerce_get_catalog_ordering_args', 'custom_product_number_ordering');
function custom_product_number_ordering($args) {
    // 只在后台产品列表页面应用
    if (is_admin() && isset($_GET['post_type']) && $_GET['post_type'] == 'product') {
        $args['orderby'] = 'title';
        $args['order'] = 'ASC';
    }
    return $args;
}

/**
 * 修改后台产品列表的默认排序
 * 🔥 修复：使用 meta_query EXISTS/NOT EXISTS 组合产生 LEFT JOIN，
 *    避免 INNER JOIN 导致缺少 _product_number_sort 元数据的产品被隐藏
 */
add_filter('pre_get_posts', 'custom_admin_product_sort_by_number');
function custom_admin_product_sort_by_number($query) {
    if (!is_admin() || !$query->is_main_query()) {
        return;
    }

    // 只针对产品列表
    if ($query->get('post_type') == 'product') {
        // 检查是否已经设置了其他排序
        if (!isset($_GET['orderby'])) {
            $query->set('meta_query', array(
                'relation' => 'OR',
                'product_number_sort' => array(
                    'key' => '_product_number_sort',
                    'compare' => 'EXISTS'
                ),
                'product_number_sort_missing' => array(
                    'key' => '_product_number_sort',
                    'compare' => 'NOT EXISTS'
                )
            ));
            $query->set('orderby', 'product_number_sort title');
            $query->set('order', 'ASC');
        }
    }
}

/**
 * 提取产品名称中的数字并保存为自定义字段
 */
add_action('save_post_product', 'save_product_number_for_sorting', 10, 1);
function save_product_number_for_sorting($post_id) {
    $title = get_the_title($post_id);
    
    // 提取标题开头的数字（支持小数）
    if (preg_match('/^(\d+\.?\d*)/', $title, $matches)) {
        $number = floatval($matches[1]);
        update_post_meta($post_id, '_product_number_sort', $number);
    } else {
        // 如果没有数字，设置为一个很大的值，排在后面
        update_post_meta($post_id, '_product_number_sort', 999999);
    }
}

/**
 * 为缺少排序编号的产品补充生成（每次admin_init检查）
 * 🔥 修复：改为增量模式，只为缺少 _product_number_sort 的产品生成，不依赖一次性标志
 */
add_action('admin_init', 'generate_product_numbers_for_missing');
function generate_product_numbers_for_missing() {
    // 查找缺少 _product_number_sort 的产品
    $products_without_sort = get_posts(array(
        'post_type' => 'product',
        'posts_per_page' => 100, // 每次最多处理100个，避免超时
        'post_status' => 'any',
        'meta_query' => array(
            array(
                'key' => '_product_number_sort',
                'compare' => 'NOT EXISTS'
            )
        )
    ));

    if (empty($products_without_sort)) {
        return; // 所有产品都已有排序编号
    }

    foreach ($products_without_sort as $product) {
        $title = $product->post_title;

        if (preg_match('/^(\d+\.?\d*)/', $title, $matches)) {
            $number = floatval($matches[1]);
            update_post_meta($product->ID, '_product_number_sort', $number);
        } else {
            update_post_meta($product->ID, '_product_number_sort', 999999);
        }
    }
}

// ========================================
// Monthly Summary (月结单) Backend Functions
// ========================================

/**
 * AJAX处理函数 - 保存日结单到月结单表
 */
add_action('wp_ajax_ruiyi_save_daily_to_monthly', 'ruiyi_save_daily_to_monthly_callback');
add_action('wp_ajax_nopriv_ruiyi_save_daily_to_monthly', 'ruiyi_save_daily_to_monthly_callback');

function ruiyi_save_daily_to_monthly_callback() {
    if (!is_user_logged_in()) {
        wp_send_json_error(['message' => 'Authentication required']);
        return;
    }

    // 验证nonce
    if (!isset($_POST['nonce']) || !wp_verify_nonce($_POST['nonce'], 'ruiyi_pos_nonce')) {
        wp_send_json_error(['message' => '安全验证失败']);
        return;
    }

    try {
        if (!ruiyi_acquire_settlement_lock('manual_or_frontend_auto')) {
            wp_send_json_error(['message' => '已有其他结算任务正在执行，请稍后再试']);
            return;
        }

        $user = wp_get_current_user();

        // 🔥 检查是否为前端自动触发
        $is_auto_trigger = isset($_POST['auto_trigger']) && $_POST['auto_trigger'] === '1';
        if ($is_auto_trigger) {
            ruiyi_debug_log('[日结单] 前端自动结算定时器触发');
        }

        // 获取当前结算时间
        $settlement_datetime = current_time('mysql');
        $settlement_timestamp = strtotime($settlement_datetime);
        $settlement_hour = intval(date('H', $settlement_timestamp));
        $settlement_mode = get_option('pos_settlement_mode', 'manual');
        $daily_data_key = '';

        if ($settlement_mode === 'auto') {
            ruiyi_release_settlement_lock();
            wp_send_json_error(['message' => '自动模式下无需手动保存日结单']);
            return;
        }

        // 计算业务日期：如果结算时间在凌晨4点之前，算作前一天的业务
        if ($settlement_hour < 4) {
            $business_date = date('Y-m-d', strtotime('-1 day', $settlement_timestamp));
        } else {
            $business_date = date('Y-m-d', $settlement_timestamp);
        }

        if ($settlement_mode === 'auto') {
            if ($is_auto_trigger) {
                $period_info = ruiyi_get_auto_settlement_schedule_for_business_date($business_date);
            } else {
                $period_info = ruiyi_get_current_auto_settlement_period();
                $business_date = $period_info['business_date'];
            }

            $period_start = $period_info['period_start'];
            $period_end = $period_info['period_end'];
            $built_data = ruiyi_build_daily_summary_from_wc_orders($period_start, $period_end, $business_date);
            $daily_data = $built_data['summary'];
        } else {
            // 🔥 手动模式：使用固定key读取累计数据
            $daily_data_key = 'ruiyi_daily_summary_current';

            // 获取累计数据
            $daily_data = get_option($daily_data_key, []);

            // 🔥 优先使用累计数据中的开始时间，其次使用上次结算时间
            if (isset($daily_data['start_datetime']) && !empty($daily_data['start_datetime'])) {
                $period_start = $daily_data['start_datetime'];
            } else {
                // 获取上次结算时间作为备用
                $last_settlement_time = get_option('ruiyi_last_settlement_time', '');

                // 如果是首次结算，默认从当天营业开始时间（上午10点）开始计算
                if (empty($last_settlement_time)) {
                    $last_settlement_time = $business_date . ' 10:00:00';
                }
                $period_start = $last_settlement_time;
            }

            $period_end = $settlement_datetime;
        }

        if (empty($daily_data) || !isset($daily_data['total_amount']) || floatval($daily_data['total_amount']) <= 0) {
            ruiyi_release_settlement_lock();
            wp_send_json_error(['message' => '今日暂无数据需要保存']);
            return;
        }

        // 准备分类数据
        $categories_data = [];
        if (isset($daily_data['products']) && !empty($daily_data['products'])) {
            foreach ($daily_data['products'] as $product) {
                $category = isset($product['category']) ? $product['category'] : 'Sin categoría';

                if (!isset($categories_data[$category])) {
                    $categories_data[$category] = [
                        'name' => $category,
                        'total' => 0
                    ];
                }

                $categories_data[$category]['total'] += floatval($product['total']);
            }
        }

        // 🔥 修改：每次都创建新的月结单记录，而不是累加到现有记录
        // 这样用户可以看到每一次结算的详细明细

        // 生成标题：显示业务日期和结算时间
        $settlement_time_display = date('Y-m-d H:i', $settlement_timestamp);
        $post_title = sprintf('日结单 - %s（结单时间：%s）', $business_date, $settlement_time_display);

        // 🔥 始终创建新文章（不再检查是否存在同日期的记录）
        $post_id = wp_insert_post(array(
            'post_type' => 'monthly_summary',
            'post_title' => $post_title,
            'post_status' => 'publish',
            'post_author' => $user->ID
        ));

        if (is_wp_error($post_id)) {
            throw new Exception('创建月结单文章失败');
        }

        // 保存meta数据（保留_summary_date以向后兼容）
        update_post_meta($post_id, '_summary_date', $business_date);
        update_post_meta($post_id, '_business_date', $business_date);
        update_post_meta($post_id, '_settlement_datetime', $settlement_datetime);
        update_post_meta($post_id, '_period_start', $period_start);
        update_post_meta($post_id, '_period_end', $period_end);
        update_post_meta($post_id, '_total_amount', floatval($daily_data['total_amount']));
        update_post_meta($post_id, '_cash_amount', floatval($daily_data['cash_amount']));
        update_post_meta($post_id, '_card_amount', floatval($daily_data['card_amount']));
        update_post_meta($post_id, '_bizum_amount', floatval(isset($daily_data['bizum_amount']) ? $daily_data['bizum_amount'] : 0));
        update_post_meta($post_id, '_categories_data', json_encode(array_values($categories_data), JSON_UNESCAPED_UNICODE));

        // 🔥 保存启始现金快照（当时的启始现金值）
        $starting_cash_data = get_option('ruiyi_pos_starting_cash', ['amount' => 0]);
        $starting_cash = floatval($starting_cash_data['amount']);
        update_post_meta($post_id, '_starting_cash', $starting_cash);

        // 🔥 保存交易明细数据（新增）
        if (isset($daily_data['transactions']) && !empty($daily_data['transactions'])) {
            update_post_meta($post_id, '_transactions_data', json_encode($daily_data['transactions'], JSON_UNESCAPED_UNICODE));
            ruiyi_debug_log(sprintf('[月结单] 保存交易明细 - 共%d条交易记录', count($daily_data['transactions'])));
        }

        ruiyi_debug_log(sprintf('[月结单] 创建新记录 ID:%d - 业务日期:%s, 结算时间:%s, 总额:€%.2f, 现金:€%.2f, 刷卡:€%.2f',
            $post_id, $business_date, $settlement_datetime,
            $daily_data['total_amount'], $daily_data['cash_amount'], $daily_data['card_amount']));

        // 更新上次结算时间
        update_option('ruiyi_last_settlement_time', $settlement_datetime, 'no');

        // 🔥 保存到历史日结单（用于重新打印）
        $history_key = 'ruiyi_daily_settlement_history';
        $history_data = get_option($history_key, []);

        // 使用时间戳作为唯一ID
        $settlement_id = 'settlement_' . $settlement_timestamp;

        $history_data[$settlement_id] = [
            'id' => $settlement_id,
            'business_date' => $business_date,
            'settlement_datetime' => $settlement_datetime,
            'settlement_type' => $is_auto_trigger ? 'auto_frontend' : 'manual', // 🔥 标记结算类型
            'period_start' => $period_start,
            'period_end' => $period_end,
            'total_amount' => floatval($daily_data['total_amount']),
            'cash_amount' => floatval($daily_data['cash_amount']),
            'card_amount' => floatval($daily_data['card_amount']),
            'bizum_amount' => floatval(isset($daily_data['bizum_amount']) ? $daily_data['bizum_amount'] : 0),
            'starting_cash' => $starting_cash, // 🔥 保存启始现金快照
            'products' => isset($daily_data['products']) ? $daily_data['products'] : [],
            'transactions' => isset($daily_data['transactions']) ? $daily_data['transactions'] : [],
            'categories_data' => array_values($categories_data),
            'saved_by' => $user->user_login,
            'monthly_post_id' => $post_id
        ];

        // 按时间倒序排序（最新的在前面）
        krsort($history_data);

        // 只保留最近60条历史记录
        if (count($history_data) > 60) {
            $history_data = array_slice($history_data, 0, 60, true);
        }

        update_option($history_key, $history_data, 'no');
        ruiyi_debug_log(sprintf('[历史日结单] 已保存 ID:%s - 业务日期:%s, 总额:€%.2f', $settlement_id, $business_date, $daily_data['total_amount']));

        // 归档并清除日结单数据
        $archive_key = 'ruiyi_daily_summary_archive';
        $archive_data = get_option($archive_key, []);

        $archive_data[$business_date] = [
            'date' => $business_date,
            'settlement_datetime' => $settlement_datetime,
            'period_start' => $period_start,
            'period_end' => $period_end,
            'data' => $daily_data,
            'saved_to_monthly' => current_time('mysql'),
            'saved_by' => $user->user_login
        ];

        // 只保留最近30天的归档
        if (count($archive_data) > 30) {
            $archive_data = array_slice($archive_data, -30, 30, true);
        }

        update_option($archive_key, $archive_data, 'no');

        // 删除今日临时数据
        if (!empty($daily_data_key)) {
            delete_option($daily_data_key);
        }

        // 🔥 如果是前端自动触发，更新自动结算日期（防止Cron和补偿重复执行）
        if ($is_auto_trigger) {
            update_option('ruiyi_last_auto_settlement_time', $settlement_datetime);
            update_option('ruiyi_last_auto_settlement_date', $business_date);
            ruiyi_debug_log(sprintf('[日结单] 前端自动结算完成 - 业务日期: %s, 总额: €%.2f', $business_date, $daily_data['total_amount']));
        }

        ruiyi_release_settlement_lock();
        wp_send_json_success([
            'message' => '日结单已保存到月结单',
            'date' => $business_date,
            'settlement_datetime' => $settlement_datetime,
            'post_id' => $post_id,
            'settlement_id' => $settlement_id,
            'total_amount' => $daily_data['total_amount']
        ]);

    } catch (Exception $e) {
        ruiyi_release_settlement_lock();
        ruiyi_debug_log('[月结单] 保存失败: ' . $e->getMessage());
        wp_send_json_error(['message' => '保存失败: ' . $e->getMessage()]);
    }
}

function ruiyi_get_monthly_summary_auto_date_range($from_date = '', $to_date = '', $month = '') {
    if ($month) {
        $range_start = $month . '-01';
        $range_end = date('Y-m-t', strtotime($range_start));
    } else {
        $today = current_time('Y-m-d');
        $range_start = $from_date ?: ($to_date ?: date('Y-m-01', strtotime($today)));
        $range_end = $to_date ?: ($from_date ?: date('Y-m-t', strtotime($today)));
    }

    if ($range_start > $range_end) {
        $tmp = $range_start;
        $range_start = $range_end;
        $range_end = $tmp;
    }

    return [
        'start_date' => $range_start,
        'end_date' => $range_end,
    ];
}

function ruiyi_get_monthly_summary_from_wc_orders($from_date = '', $to_date = '', $month = '') {
    $range = ruiyi_get_monthly_summary_auto_date_range($from_date, $to_date, $month);
    $period_start = $range['start_date'] . ' 00:00:00';
    $period_end = date('Y-m-d H:i:s', strtotime($range['end_date'] . ' +1 day'));
    $order_ids = ruiyi_collect_settlement_order_ids($period_start, $period_end);
    $records_map = [];
    $summary = [
        'total' => 0,
        'cash' => 0,
        'card' => 0,
        'bizum' => 0,
        'count' => 0,
    ];

    foreach ($order_ids as $order_id) {
        $order = wc_get_order($order_id);
        if (!$order || $order->get_type() === 'shop_order_refund') {
            continue;
        }

        $effective_date = $order->get_date_completed();
        if (!$effective_date) {
            $effective_date = $order->get_date_created();
        }
        if (!$effective_date) {
            continue;
        }

        $local_datetime = wp_date('Y-m-d H:i:s', $effective_date->getTimestamp());
        $business_date = substr($local_datetime, 0, 10);
        if ($business_date < $range['start_date'] || $business_date > $range['end_date']) {
            continue;
        }

        $breakdown = ruiyi_get_order_settlement_breakdown($order);

        if (!isset($records_map[$business_date])) {
            $records_map[$business_date] = [
                'date' => $business_date,
                'settlement_datetime' => $local_datetime,
                'period_start' => $local_datetime,
                'period_end' => $local_datetime,
                'total_amount' => 0,
                'cash_amount' => 0,
                'card_amount' => 0,
                'bizum_amount' => 0,
                'categories_data' => [],
            ];
        }

        $records_map[$business_date]['total_amount'] = round($records_map[$business_date]['total_amount'] + $breakdown['total_amount'], 2);
        $records_map[$business_date]['cash_amount'] = round($records_map[$business_date]['cash_amount'] + $breakdown['cash_amount'], 2);
        $records_map[$business_date]['card_amount'] = round($records_map[$business_date]['card_amount'] + $breakdown['card_amount'], 2);
        $records_map[$business_date]['bizum_amount'] = round($records_map[$business_date]['bizum_amount'] + $breakdown['bizum_amount'], 2);

        if ($local_datetime < $records_map[$business_date]['period_start']) {
            $records_map[$business_date]['period_start'] = $local_datetime;
        }
        if ($local_datetime > $records_map[$business_date]['period_end']) {
            $records_map[$business_date]['period_end'] = $local_datetime;
            $records_map[$business_date]['settlement_datetime'] = $local_datetime;
        }

        foreach ($order->get_items() as $item) {
            $category = 'Sin categoría';
            if ($item->get_product_id()) {
                $terms = get_the_terms($item->get_product_id(), 'product_cat');
                if ($terms && !is_wp_error($terms)) {
                    $category = $terms[0]->name;
                }
            }

            if (!isset($records_map[$business_date]['categories_data'][$category])) {
                $records_map[$business_date]['categories_data'][$category] = [
                    'name' => $category,
                    'total' => 0,
                ];
            }

            $records_map[$business_date]['categories_data'][$category]['total'] += floatval($item->get_total());
        }

        $summary['total'] = round($summary['total'] + $breakdown['total_amount'], 2);
        $summary['cash'] = round($summary['cash'] + $breakdown['cash_amount'], 2);
        $summary['card'] = round($summary['card'] + $breakdown['card_amount'], 2);
        $summary['bizum'] = round($summary['bizum'] + $breakdown['bizum_amount'], 2);
    }

    $records = array_values(array_map(function($record) {
        $record['categories_data'] = array_values($record['categories_data']);
        return $record;
    }, $records_map));

    usort($records, function($a, $b) {
        return strcmp($b['settlement_datetime'], $a['settlement_datetime']);
    });

    $summary['count'] = count($records);

    return [
        'records' => $records,
        'summary' => $summary,
        'filters' => [
            'from_date' => $from_date,
            'to_date' => $to_date,
            'month' => $month,
        ],
    ];
}

/**
 * 🔥 AJAX处理函数 - 获取历史日结单列表
 */
add_action('wp_ajax_ruiyi_get_daily_settlement_history', 'ruiyi_get_daily_settlement_history_callback');
add_action('wp_ajax_nopriv_ruiyi_get_daily_settlement_history', 'ruiyi_get_daily_settlement_history_callback');

function ruiyi_get_daily_settlement_history_callback() {
    // 验证nonce
    if (!isset($_POST['nonce']) || !wp_verify_nonce($_POST['nonce'], 'ruiyi_pos_nonce')) {
        wp_send_json_error(['message' => '安全验证失败']);
        return;
    }

    try {
        $from_date = isset($_POST['from_date']) ? sanitize_text_field($_POST['from_date']) : '';
        $to_date = isset($_POST['to_date']) ? sanitize_text_field($_POST['to_date']) : '';

        // 获取历史日结单数据
        $history_key = 'ruiyi_daily_settlement_history';
        $history_data = get_option($history_key, []);

        // 筛选日期范围
        if ($from_date || $to_date) {
            $filtered_data = [];
            foreach ($history_data as $id => $record) {
                $record_date = $record['business_date'];

                if ($from_date && $record_date < $from_date) {
                    continue;
                }
                if ($to_date && $record_date > $to_date) {
                    continue;
                }

                $filtered_data[$id] = $record;
            }
            $history_data = $filtered_data;
        }

        // 返回列表数据（不包含完整的products和transactions以减少数据量）
        $list_data = [];
        foreach ($history_data as $id => $record) {
            $list_data[] = [
                'id' => $record['id'],
                'business_date' => $record['business_date'],
                'settlement_datetime' => $record['settlement_datetime'],
                'settlement_type' => isset($record['settlement_type']) ? $record['settlement_type'] : 'manual',
                'period_start' => isset($record['period_start']) ? $record['period_start'] : '',
                'period_end' => isset($record['period_end']) ? $record['period_end'] : '',
                'total_amount' => $record['total_amount'],
                'cash_amount' => $record['cash_amount'],
                'card_amount' => $record['card_amount'],
                'bizum_amount' => isset($record['bizum_amount']) ? $record['bizum_amount'] : 0,
                'saved_by' => isset($record['saved_by']) ? $record['saved_by'] : '',
                'categories_data' => isset($record['categories_data']) ? $record['categories_data'] : [] // 🔥 添加分类销售数据
            ];
        }

        wp_send_json_success([
            'history' => $list_data,
            'total_count' => count($list_data)
        ]);

    } catch (Exception $e) {
        ruiyi_debug_log('[历史日结单] 获取列表失败: ' . $e->getMessage());
        wp_send_json_error(['message' => '获取失败: ' . $e->getMessage()]);
    }
}

/**
 * 🔥 AJAX处理函数 - 获取单个历史日结单详情（用于重新打印）
 */
add_action('wp_ajax_ruiyi_get_daily_settlement_detail', 'ruiyi_get_daily_settlement_detail_callback');
add_action('wp_ajax_nopriv_ruiyi_get_daily_settlement_detail', 'ruiyi_get_daily_settlement_detail_callback');

function ruiyi_get_daily_settlement_detail_callback() {
    // 验证nonce
    if (!isset($_POST['nonce']) || !wp_verify_nonce($_POST['nonce'], 'ruiyi_pos_nonce')) {
        wp_send_json_error(['message' => '安全验证失败']);
        return;
    }

    try {
        $settlement_id = isset($_POST['settlement_id']) ? sanitize_text_field($_POST['settlement_id']) : '';

        if (empty($settlement_id)) {
            wp_send_json_error(['message' => '缺少日结单ID']);
            return;
        }

        // 获取历史日结单数据
        $history_key = 'ruiyi_daily_settlement_history';
        $history_data = get_option($history_key, []);

        if (!isset($history_data[$settlement_id])) {
            wp_send_json_error(['message' => '未找到该历史日结单']);
            return;
        }

        $record = $history_data[$settlement_id];

        // 返回完整数据（用于打印）
        wp_send_json_success([
            'settlement' => [
                'id' => $record['id'],
                'business_date' => $record['business_date'],
                'settlement_datetime' => $record['settlement_datetime'],
                'period_start' => isset($record['period_start']) ? $record['period_start'] : '',
                'period_end' => isset($record['period_end']) ? $record['period_end'] : '',
                'total_amount' => $record['total_amount'],
                'cash_amount' => $record['cash_amount'],
                'card_amount' => $record['card_amount'],
                'starting_cash' => isset($record['starting_cash']) ? floatval($record['starting_cash']) : 0, // 🔥 添加启始现金
                'products' => isset($record['products']) ? $record['products'] : [],
                'transactions' => isset($record['transactions']) ? $record['transactions'] : [],
                'categories_data' => isset($record['categories_data']) ? $record['categories_data'] : [],
                'saved_by' => isset($record['saved_by']) ? $record['saved_by'] : ''
            ]
        ]);

    } catch (Exception $e) {
        ruiyi_debug_log('[历史日结单] 获取详情失败: ' . $e->getMessage());
        wp_send_json_error(['message' => '获取失败: ' . $e->getMessage()]);
    }
}

/**
 * 🔥 AJAX处理函数 - 获取今日所有日结单汇总（用于打印今日总结单）
 */
add_action('wp_ajax_ruiyi_get_today_settlements_total', 'ruiyi_get_today_settlements_total_callback');
add_action('wp_ajax_nopriv_ruiyi_get_today_settlements_total', 'ruiyi_get_today_settlements_total_callback');

function ruiyi_get_today_settlements_total_callback() {
    // 验证nonce
    if (!isset($_POST['nonce']) || !wp_verify_nonce($_POST['nonce'], 'ruiyi_pos_nonce')) {
        wp_send_json_error(['message' => '安全验证失败']);
        return;
    }

    try {
        // 获取今日日期
        $today = current_time('Y-m-d');

        // 获取历史日结单数据
        $history_key = 'ruiyi_daily_settlement_history';
        $history_data = get_option($history_key, []);

        // 筛选今天的记录
        $today_settlements = [];
        $total_amount = 0;
        $total_cash = 0;
        $total_card = 0;

        foreach ($history_data as $id => $record) {
            if ($record['business_date'] === $today) {
                $today_settlements[] = [
                    'id' => $record['id'],
                    'settlement_datetime' => $record['settlement_datetime'],
                    'period_start' => isset($record['period_start']) ? $record['period_start'] : '',
                    'period_end' => isset($record['period_end']) ? $record['period_end'] : '',
                    'total_amount' => floatval($record['total_amount']),
                    'cash_amount' => floatval($record['cash_amount']),
                    'card_amount' => floatval($record['card_amount']),
                ];

                $total_amount += floatval($record['total_amount']);
                $total_cash += floatval($record['cash_amount']);
                $total_card += floatval($record['card_amount']);
            }
        }

        // 按结算时间排序（最早的在前面）
        usort($today_settlements, function($a, $b) {
            return strcmp($a['settlement_datetime'], $b['settlement_datetime']);
        });

        if (empty($today_settlements)) {
            wp_send_json_error(['message' => '今日暂无日结单记录']);
            return;
        }

        // 获取店铺信息
        $shop_name = get_bloginfo('name');

        wp_send_json_success([
            'date' => $today,
            'shop_name' => $shop_name,
            'settlements' => $today_settlements,
            'count' => count($today_settlements),
            'totals' => [
                'total_amount' => round($total_amount, 2),
                'cash_amount' => round($total_cash, 2),
                'card_amount' => round($total_card, 2)
            ],
            'print_time' => current_time('Y-m-d H:i:s')
        ]);

    } catch (Exception $e) {
        ruiyi_debug_log('[今日汇总] 获取失败: ' . $e->getMessage());
        wp_send_json_error(['message' => '获取失败: ' . $e->getMessage()]);
    }
}

/**
 * AJAX处理函数 - 获取月结单数据
 */
add_action('wp_ajax_ruiyi_get_monthly_summary', 'ruiyi_get_monthly_summary_callback');
add_action('wp_ajax_nopriv_ruiyi_get_monthly_summary', 'ruiyi_get_monthly_summary_callback');

function ruiyi_get_monthly_summary_callback() {
    // 验证nonce
    if (!isset($_POST['nonce']) || !wp_verify_nonce($_POST['nonce'], 'ruiyi_pos_nonce')) {
        wp_send_json_error(['message' => '安全验证失败']);
        return;
    }

    try {
        $from_date = isset($_POST['from_date']) ? sanitize_text_field($_POST['from_date']) : '';
        $to_date = isset($_POST['to_date']) ? sanitize_text_field($_POST['to_date']) : '';
        $month = isset($_POST['month']) ? sanitize_text_field($_POST['month']) : '';

        if (get_option('pos_settlement_mode', 'manual') === 'auto') {
            wp_send_json_success(ruiyi_get_monthly_summary_from_wc_orders($from_date, $to_date, $month));
            return;
        }

        // 构建查询参数
        $meta_query = array('relation' => 'AND');

        if ($month) {
            // 月份筛选
            $month_start = $month . '-01';
            $month_end = date('Y-m-t', strtotime($month_start));

            $meta_query[] = array(
                'key' => '_summary_date',
                'value' => array($month_start, $month_end),
                'compare' => 'BETWEEN',
                'type' => 'DATE'
            );
        } elseif ($from_date && $to_date) {
            // 日期范围筛选
            $meta_query[] = array(
                'key' => '_summary_date',
                'value' => array($from_date, $to_date),
                'compare' => 'BETWEEN',
                'type' => 'DATE'
            );
        } elseif ($from_date) {
            $meta_query[] = array(
                'key' => '_summary_date',
                'value' => $from_date,
                'compare' => '>=',
                'type' => 'DATE'
            );
        } elseif ($to_date) {
            $meta_query[] = array(
                'key' => '_summary_date',
                'value' => $to_date,
                'compare' => '<=',
                'type' => 'DATE'
            );
        }

        // 查询文章
        $args = array(
            'post_type' => 'monthly_summary',
            'posts_per_page' => -1,
            'post_status' => 'publish',
            'orderby' => 'meta_value',
            'meta_key' => '_settlement_datetime', // 🔥 改为按结算时间排序（精确到秒）
            'order' => 'DESC', // 🔥 倒序：最新的在前面
            'meta_query' => $meta_query
        );

        $posts = get_posts($args);
        $records = [];
        $total_sum = 0;
        $cash_sum = 0;
        $card_sum = 0;
        $bizum_sum = 0;

        foreach ($posts as $post) {
            // 优先读取_business_date，如不存在则使用_summary_date（向后兼容）
            $business_date = get_post_meta($post->ID, '_business_date', true);
            if (empty($business_date)) {
                $business_date = get_post_meta($post->ID, '_summary_date', true);
            }

            $settlement_datetime = get_post_meta($post->ID, '_settlement_datetime', true);
            $period_start = get_post_meta($post->ID, '_period_start', true);
            $period_end = get_post_meta($post->ID, '_period_end', true);

            $total = floatval(get_post_meta($post->ID, '_total_amount', true));
            $cash = floatval(get_post_meta($post->ID, '_cash_amount', true));
            $card = floatval(get_post_meta($post->ID, '_card_amount', true));
            $bizum = floatval(get_post_meta($post->ID, '_bizum_amount', true));
            $categories = get_post_meta($post->ID, '_categories_data', true);

            $records[] = array(
                'post_id' => $post->ID, // 🔐 超级管理员编辑需要
                'date' => $business_date,
                'settlement_datetime' => $settlement_datetime,
                'period_start' => $period_start,
                'period_end' => $period_end,
                'total_amount' => $total,
                'cash_amount' => $cash,
                'card_amount' => $card,
                'bizum_amount' => $bizum,
                'categories_data' => $categories ? json_decode($categories, true) : []
            );

            $total_sum += $total;
            $cash_sum += $cash;
            $card_sum += $card;
            $bizum_sum += $bizum;
        }

        wp_send_json_success([
            'records' => $records,
            'summary' => [
                'total' => $total_sum,
                'cash' => $cash_sum,
                'card' => $card_sum,
                'bizum' => $bizum_sum,
                'count' => count($records)
            ],
            'filters' => [
                'from_date' => $from_date,
                'to_date' => $to_date,
                'month' => $month
            ]
        ]);

    } catch (Exception $e) {
        ruiyi_debug_log('[月结单] 查询失败: ' . $e->getMessage());
        wp_send_json_error(['message' => '查询失败: ' . $e->getMessage()]);
    }
}

