/**
 * AJAX处理函数 - 超级管理员获取月结单详情（用于编辑）
 */
add_action('wp_ajax_ruiyi_admin_get_settlement_detail', 'ruiyi_admin_get_settlement_detail_callback');
function ruiyi_admin_get_settlement_detail_callback() {
    // 验证nonce
    if (!isset($_POST['nonce']) || !wp_verify_nonce($_POST['nonce'], 'ruiyi_pos_nonce')) {
        wp_send_json_error(['message' => '安全验证失败']);
        return;
    }

    // 🔐 超级管理员权限检查
    if (!ruiyi_is_super_admin_user()) {
        wp_send_json_error(['message' => '需要超级管理员权限']);
        return;
    }

    $post_id = isset($_POST['post_id']) ? intval($_POST['post_id']) : 0;
    $settlement_id = isset($_POST['settlement_id']) ? sanitize_text_field($_POST['settlement_id']) : '';

    try {
        if ($post_id > 0) {
            // 获取月结单文章数据
            $post = get_post($post_id);
            if (!$post || $post->post_type !== 'monthly_summary') {
                wp_send_json_error(['message' => '未找到该记录']);
                return;
            }

            $data = [
                'type' => 'monthly_post',
                'post_id' => $post_id,
                'title' => $post->post_title,
                'business_date' => get_post_meta($post_id, '_business_date', true) ?: get_post_meta($post_id, '_summary_date', true),
                'settlement_datetime' => get_post_meta($post_id, '_settlement_datetime', true),
                'period_start' => get_post_meta($post_id, '_period_start', true),
                'period_end' => get_post_meta($post_id, '_period_end', true),
                'total_amount' => floatval(get_post_meta($post_id, '_total_amount', true)),
                'cash_amount' => floatval(get_post_meta($post_id, '_cash_amount', true)),
                'card_amount' => floatval(get_post_meta($post_id, '_card_amount', true)),
                'bizum_amount' => floatval(get_post_meta($post_id, '_bizum_amount', true)),
                'starting_cash' => floatval(get_post_meta($post_id, '_starting_cash', true)),
                'categories_data' => json_decode(get_post_meta($post_id, '_categories_data', true), true) ?: [],
                'transactions_data' => json_decode(get_post_meta($post_id, '_transactions_data', true), true) ?: []
            ];
        } elseif (!empty($settlement_id)) {
            // 获取历史日结单数据
            $history_data = get_option('ruiyi_daily_settlement_history', []);
            if (!isset($history_data[$settlement_id])) {
                wp_send_json_error(['message' => '未找到该历史记录']);
                return;
            }
            $record = $history_data[$settlement_id];
            $data = [
                'type' => 'history',
                'settlement_id' => $settlement_id,
                'business_date' => $record['business_date'],
                'settlement_datetime' => $record['settlement_datetime'],
                'settlement_type' => $record['settlement_type'] ?? 'manual',
                'period_start' => $record['period_start'],
                'period_end' => $record['period_end'],
                'total_amount' => floatval($record['total_amount']),
                'cash_amount' => floatval($record['cash_amount']),
                'card_amount' => floatval($record['card_amount']),
                'bizum_amount' => floatval($record['bizum_amount'] ?? 0),
                'starting_cash' => floatval($record['starting_cash'] ?? 0),
                'categories_data' => $record['categories_data'] ?? [],
                'products' => $record['products'] ?? [],
                'transactions' => $record['transactions'] ?? [],
                'saved_by' => $record['saved_by'] ?? '',
                'monthly_post_id' => $record['monthly_post_id'] ?? 0
            ];
        } else {
            wp_send_json_error(['message' => '缺少必要参数']);
            return;
        }

        wp_send_json_success($data);

    } catch (Exception $e) {
        wp_send_json_error(['message' => '获取失败: ' . $e->getMessage()]);
    }
}

/**
 * AJAX处理函数 - 超级管理员更新月结单数据
 */
add_action('wp_ajax_ruiyi_admin_update_settlement', 'ruiyi_admin_update_settlement_callback');
function ruiyi_admin_update_settlement_callback() {
    // 验证nonce
    if (!isset($_POST['nonce']) || !wp_verify_nonce($_POST['nonce'], 'ruiyi_pos_nonce')) {
        wp_send_json_error(['message' => '安全验证失败']);
        return;
    }

    // 🔐 超级管理员权限检查
    if (!ruiyi_is_super_admin_user()) {
        wp_send_json_error(['message' => '需要超级管理员权限']);
        return;
    }

    // 支持两种参数传递方式: (id + type) 或 (post_id / settlement_id)
    $id = isset($_POST['id']) ? sanitize_text_field($_POST['id']) : '';
    $type = isset($_POST['type']) ? sanitize_text_field($_POST['type']) : '';
    $post_id = isset($_POST['post_id']) ? intval($_POST['post_id']) : 0;
    $settlement_id = isset($_POST['settlement_id']) ? sanitize_text_field($_POST['settlement_id']) : '';

    // 如果使用 id + type 格式，转换为 post_id / settlement_id
    if (!empty($id) && !empty($type)) {
        if ($type === 'monthly') {
            $post_id = intval($id);
        } elseif ($type === 'history') {
            $settlement_id = $id;
        }
    }

    try {
        $business_date = isset($_POST['business_date']) ? sanitize_text_field($_POST['business_date']) : '';
        $settlement_datetime = isset($_POST['settlement_datetime']) ? sanitize_text_field($_POST['settlement_datetime']) : '';
        $period_start = isset($_POST['period_start']) ? sanitize_text_field($_POST['period_start']) : '';
        $period_end = isset($_POST['period_end']) ? sanitize_text_field($_POST['period_end']) : '';
        $total_amount = isset($_POST['total_amount']) ? floatval($_POST['total_amount']) : 0;
        $cash_amount = isset($_POST['cash_amount']) ? floatval($_POST['cash_amount']) : 0;
        $card_amount = isset($_POST['card_amount']) ? floatval($_POST['card_amount']) : 0;
        $bizum_amount = isset($_POST['bizum_amount']) ? floatval($_POST['bizum_amount']) : 0;
        $starting_cash = isset($_POST['starting_cash']) ? floatval($_POST['starting_cash']) : 0;

        if ($post_id > 0) {
            // 更新月结单文章
            $post = get_post($post_id);
            if (!$post || $post->post_type !== 'monthly_summary') {
                wp_send_json_error(['message' => '未找到该记录']);
                return;
            }

            // 更新文章标题
            $settlement_time_display = date('Y-m-d H:i', strtotime($settlement_datetime));
            $post_title = sprintf('日结单 - %s（结单时间：%s）[已修改]', $business_date, $settlement_time_display);
            wp_update_post([
                'ID' => $post_id,
                'post_title' => $post_title
            ]);

            // 更新meta数据
            update_post_meta($post_id, '_summary_date', $business_date);
            update_post_meta($post_id, '_business_date', $business_date);
            update_post_meta($post_id, '_settlement_datetime', $settlement_datetime);
            update_post_meta($post_id, '_period_start', $period_start);
            update_post_meta($post_id, '_period_end', $period_end);
            update_post_meta($post_id, '_total_amount', $total_amount);
            update_post_meta($post_id, '_cash_amount', $cash_amount);
            update_post_meta($post_id, '_card_amount', $card_amount);
            update_post_meta($post_id, '_bizum_amount', $bizum_amount);
            update_post_meta($post_id, '_starting_cash', $starting_cash);
            update_post_meta($post_id, '_admin_modified', current_time('mysql'));
            update_post_meta($post_id, '_admin_modified_by', wp_get_current_user()->user_login);

            ruiyi_debug_log(sprintf('[超级管理员] 更新月结单 ID:%d - 总额:€%.2f -> €%.2f', $post_id, get_post_meta($post_id, '_total_amount', true), $total_amount));

            wp_send_json_success(['message' => '月结单已更新', 'post_id' => $post_id]);

        } elseif (!empty($settlement_id)) {
            // 更新历史日结单
            $history_data = get_option('ruiyi_daily_settlement_history', []);
            if (!isset($history_data[$settlement_id])) {
                wp_send_json_error(['message' => '未找到该历史记录']);
                return;
            }

            // 更新数据
            $history_data[$settlement_id]['business_date'] = $business_date;
            $history_data[$settlement_id]['settlement_datetime'] = $settlement_datetime;
            $history_data[$settlement_id]['period_start'] = $period_start;
            $history_data[$settlement_id]['period_end'] = $period_end;
            $history_data[$settlement_id]['total_amount'] = $total_amount;
            $history_data[$settlement_id]['cash_amount'] = $cash_amount;
            $history_data[$settlement_id]['card_amount'] = $card_amount;
            $history_data[$settlement_id]['bizum_amount'] = $bizum_amount;
            $history_data[$settlement_id]['starting_cash'] = $starting_cash;
            $history_data[$settlement_id]['admin_modified'] = current_time('mysql');
            $history_data[$settlement_id]['admin_modified_by'] = wp_get_current_user()->user_login;

            update_option('ruiyi_daily_settlement_history', $history_data, 'no');

            // 同时更新关联的月结单文章（如果存在）
            if (!empty($history_data[$settlement_id]['monthly_post_id'])) {
                $monthly_post_id = intval($history_data[$settlement_id]['monthly_post_id']);
                if (get_post($monthly_post_id)) {
                    update_post_meta($monthly_post_id, '_total_amount', $total_amount);
                    update_post_meta($monthly_post_id, '_cash_amount', $cash_amount);
                    update_post_meta($monthly_post_id, '_card_amount', $card_amount);
                    update_post_meta($monthly_post_id, '_bizum_amount', $bizum_amount);
                    update_post_meta($monthly_post_id, '_starting_cash', $starting_cash);
                    update_post_meta($monthly_post_id, '_admin_modified', current_time('mysql'));
                    update_post_meta($monthly_post_id, '_admin_modified_by', wp_get_current_user()->user_login);
                }
            }

            ruiyi_debug_log(sprintf('[超级管理员] 更新历史日结单 ID:%s - 总额:€%.2f', $settlement_id, $total_amount));

            wp_send_json_success(['message' => '历史日结单已更新', 'settlement_id' => $settlement_id]);

        } else {
            wp_send_json_error(['message' => '缺少必要参数']);
        }

    } catch (Exception $e) {
        wp_send_json_error(['message' => '更新失败: ' . $e->getMessage()]);
    }
}

/**
 * AJAX处理函数 - 超级管理员删除结算记录
 */
add_action('wp_ajax_ruiyi_admin_delete_settlement', 'ruiyi_admin_delete_settlement_callback');
function ruiyi_admin_delete_settlement_callback() {
    // 验证nonce
    if (!isset($_POST['nonce']) || !wp_verify_nonce($_POST['nonce'], 'ruiyi_pos_nonce')) {
        wp_send_json_error(['message' => '安全验证失败']);
        return;
    }

    // 🔐 超级管理员权限检查
    if (!ruiyi_is_super_admin_user()) {
        wp_send_json_error(['message' => '需要超级管理员权限']);
        return;
    }

    // 支持两种参数传递方式: (id + type) 或 (post_id / settlement_id)
    $id = isset($_POST['id']) ? sanitize_text_field($_POST['id']) : '';
    $type = isset($_POST['type']) ? sanitize_text_field($_POST['type']) : '';
    $post_id = isset($_POST['post_id']) ? intval($_POST['post_id']) : 0;
    $settlement_id = isset($_POST['settlement_id']) ? sanitize_text_field($_POST['settlement_id']) : '';

    // 如果使用 id + type 格式，转换为 post_id / settlement_id
    if (!empty($id) && !empty($type)) {
        if ($type === 'monthly') {
            $post_id = intval($id);
        } elseif ($type === 'history') {
            $settlement_id = $id;
        }
    }

    try {
        if ($post_id > 0) {
            // 删除月结单文章
            $post = get_post($post_id);
            if (!$post || $post->post_type !== 'monthly_summary') {
                wp_send_json_error(['message' => '未找到该记录']);
                return;
            }

            wp_delete_post($post_id, true);
            ruiyi_debug_log(sprintf('[超级管理员] 删除月结单 ID:%d', $post_id));

            wp_send_json_success(['message' => '月结单已删除', 'post_id' => $post_id]);

        } elseif (!empty($settlement_id)) {
            // 删除历史日结单
            $history_data = get_option('ruiyi_daily_settlement_history', []);
            if (!isset($history_data[$settlement_id])) {
                wp_send_json_error(['message' => '未找到该历史记录']);
                return;
            }

            // 同时删除关联的月结单文章（如果存在）
            if (!empty($history_data[$settlement_id]['monthly_post_id'])) {
                $monthly_post_id = intval($history_data[$settlement_id]['monthly_post_id']);
                if (get_post($monthly_post_id)) {
                    wp_delete_post($monthly_post_id, true);
                }
            }

            unset($history_data[$settlement_id]);
            update_option('ruiyi_daily_settlement_history', $history_data, 'no');

            ruiyi_debug_log(sprintf('[超级管理员] 删除历史日结单 ID:%s', $settlement_id));

            wp_send_json_success(['message' => '历史日结单已删除', 'settlement_id' => $settlement_id]);

        } else {
            wp_send_json_error(['message' => '缺少必要参数']);
        }

    } catch (Exception $e) {
        wp_send_json_error(['message' => '删除失败: ' . $e->getMessage()]);
    }
}

/**
 * AJAX处理函数 - 超级管理员清空所有历史日结单
 */
add_action('wp_ajax_ruiyi_admin_clear_all_settlements', 'ruiyi_admin_clear_all_settlements_callback');
function ruiyi_admin_clear_all_settlements_callback() {
    if (!isset($_POST['nonce']) || !wp_verify_nonce($_POST['nonce'], 'ruiyi_pos_nonce')) {
        wp_send_json_error(['message' => '安全验证失败']);
        return;
    }

    if (!ruiyi_is_super_admin_user()) {
        wp_send_json_error(['message' => '需要超级管理员权限']);
        return;
    }

    try {
        $history_data = get_option('ruiyi_daily_settlement_history', []);
        $deleted_count = count($history_data);

        // 删除所有关联的月结单文章
        foreach ($history_data as $record) {
            if (!empty($record['monthly_post_id'])) {
                $monthly_post_id = intval($record['monthly_post_id']);
                if (get_post($monthly_post_id)) {
                    wp_delete_post($monthly_post_id, true);
                }
            }
        }

        // 清空历史记录
        update_option('ruiyi_daily_settlement_history', [], 'no');

        ruiyi_debug_log(sprintf('[超级管理员] 清空所有历史日结单，共 %d 条', $deleted_count));

        wp_send_json_success([
            'message' => sprintf('已清空 %d 条历史日结单', $deleted_count),
            'deleted_count' => $deleted_count
        ]);

    } catch (Exception $e) {
        wp_send_json_error(['message' => '清空失败: ' . $e->getMessage()]);
    }
}

/**
 * AJAX处理函数 - 超级管理员手动创建日结单记录
 */
add_action('wp_ajax_ruiyi_admin_create_settlement', 'ruiyi_admin_create_settlement_callback');
function ruiyi_admin_create_settlement_callback() {
    // 验证nonce
    if (!isset($_POST['nonce']) || !wp_verify_nonce($_POST['nonce'], 'ruiyi_pos_nonce')) {
        wp_send_json_error(['message' => '安全验证失败']);
        return;
    }

    // 🔐 超级管理员权限检查
    if (!ruiyi_is_super_admin_user()) {
        wp_send_json_error(['message' => '需要超级管理员权限']);
        return;
    }

    try {
        $business_date = isset($_POST['business_date']) ? sanitize_text_field($_POST['business_date']) : '';
        $settlement_datetime = isset($_POST['settlement_datetime']) ? sanitize_text_field($_POST['settlement_datetime']) : current_time('mysql');
        $period_start = isset($_POST['period_start']) ? sanitize_text_field($_POST['period_start']) : $business_date . ' 00:00:00';
        $period_end = isset($_POST['period_end']) ? sanitize_text_field($_POST['period_end']) : $business_date . ' 23:59:59';
        $total_amount = isset($_POST['total_amount']) ? floatval($_POST['total_amount']) : 0;
        $cash_amount = isset($_POST['cash_amount']) ? floatval($_POST['cash_amount']) : 0;
        $card_amount = isset($_POST['card_amount']) ? floatval($_POST['card_amount']) : 0;
        $bizum_amount = isset($_POST['bizum_amount']) ? floatval($_POST['bizum_amount']) : 0;
        $starting_cash = isset($_POST['starting_cash']) ? floatval($_POST['starting_cash']) : 0;

        if (empty($business_date)) {
            wp_send_json_error(['message' => '请选择业务日期']);
            return;
        }

        // 创建月结单文章
        $settlement_time_display = date('Y-m-d H:i', strtotime($settlement_datetime));
        $post_title = sprintf('日结单 - %s（结单时间：%s）[手动创建]', $business_date, $settlement_time_display);

        $user = wp_get_current_user();
        $post_id = wp_insert_post([
            'post_type' => 'monthly_summary',
            'post_title' => $post_title,
            'post_status' => 'publish',
            'post_author' => $user->ID
        ]);

        if (is_wp_error($post_id)) {
            throw new Exception('创建月结单文章失败');
        }

        // 保存meta数据
        update_post_meta($post_id, '_summary_date', $business_date);
        update_post_meta($post_id, '_business_date', $business_date);
        update_post_meta($post_id, '_settlement_datetime', $settlement_datetime);
        update_post_meta($post_id, '_settlement_type', 'admin_created');
        update_post_meta($post_id, '_period_start', $period_start);
        update_post_meta($post_id, '_period_end', $period_end);
        update_post_meta($post_id, '_total_amount', $total_amount);
        update_post_meta($post_id, '_cash_amount', $cash_amount);
        update_post_meta($post_id, '_card_amount', $card_amount);
        update_post_meta($post_id, '_bizum_amount', $bizum_amount);
        update_post_meta($post_id, '_starting_cash', $starting_cash);
        update_post_meta($post_id, '_admin_created', current_time('mysql'));
        update_post_meta($post_id, '_admin_created_by', $user->user_login);
        update_post_meta($post_id, '_categories_data', json_encode([], JSON_UNESCAPED_UNICODE));
        update_post_meta($post_id, '_transactions_data', json_encode([], JSON_UNESCAPED_UNICODE));

        // 同时保存到历史日结单
        $settlement_timestamp = strtotime($settlement_datetime);
        $settlement_id = 'settlement_' . $settlement_timestamp . '_admin';
        $history_key = 'ruiyi_daily_settlement_history';
        $history_data = get_option($history_key, []);

        $history_data[$settlement_id] = [
            'id' => $settlement_id,
            'business_date' => $business_date,
            'settlement_datetime' => $settlement_datetime,
            'settlement_type' => 'admin_created',
            'period_start' => $period_start,
            'period_end' => $period_end,
            'total_amount' => $total_amount,
            'cash_amount' => $cash_amount,
            'card_amount' => $card_amount,
            'bizum_amount' => $bizum_amount,
            'starting_cash' => $starting_cash,
            'products' => [],
            'transactions' => [],
            'categories_data' => [],
            'saved_by' => $user->user_login,
            'monthly_post_id' => $post_id,
            'admin_created' => current_time('mysql'),
            'admin_created_by' => $user->user_login
        ];

        krsort($history_data);
        if (count($history_data) > 60) {
            $history_data = array_slice($history_data, 0, 60, true);
        }

        update_option($history_key, $history_data, 'no');

        ruiyi_debug_log(sprintf('[超级管理员] 手动创建日结单 ID:%d - 业务日期:%s, 总额:€%.2f', $post_id, $business_date, $total_amount));

        wp_send_json_success([
            'message' => '日结单已创建',
            'post_id' => $post_id,
            'settlement_id' => $settlement_id,
            'business_date' => $business_date,
            'total_amount' => $total_amount
        ]);

    } catch (Exception $e) {
        wp_send_json_error(['message' => '创建失败: ' . $e->getMessage()]);
    }
}

/**
 * AJAX处理函数 - 超级管理员更新当日日结单数据
 */
add_action('wp_ajax_ruiyi_admin_update_daily_summary', 'ruiyi_admin_update_daily_summary_callback');
function ruiyi_admin_update_daily_summary_callback() {
    // 验证nonce
    if (!isset($_POST['nonce']) || !wp_verify_nonce($_POST['nonce'], 'ruiyi_pos_nonce')) {
        wp_send_json_error(['message' => '安全验证失败']);
        return;
    }

    // 🔐 超级管理员权限检查
    if (!ruiyi_is_super_admin_user()) {
        wp_send_json_error(['message' => '需要超级管理员权限']);
        return;
    }

    try {
        $total_amount = isset($_POST['total_amount']) ? floatval($_POST['total_amount']) : 0;
        $cash_amount = isset($_POST['cash_amount']) ? floatval($_POST['cash_amount']) : 0;
        $card_amount = isset($_POST['card_amount']) ? floatval($_POST['card_amount']) : 0;
        $bizum_amount = isset($_POST['bizum_amount']) ? floatval($_POST['bizum_amount']) : 0;

        $daily_data_key = 'ruiyi_daily_summary_current';
        $daily_data = get_option($daily_data_key, []);

        // 保存原始值用于日志
        $old_total = isset($daily_data['total_amount']) ? $daily_data['total_amount'] : 0;

        // 更新金额
        $daily_data['total_amount'] = $total_amount;
        $daily_data['cash_amount'] = $cash_amount;
        $daily_data['card_amount'] = $card_amount;
        $daily_data['bizum_amount'] = $bizum_amount;
        $daily_data['admin_modified'] = current_time('mysql');
        $daily_data['admin_modified_by'] = wp_get_current_user()->user_login;

        update_option($daily_data_key, $daily_data, 'no');

        ruiyi_debug_log(sprintf('[超级管理员] 更新当日日结单 - 总额:€%.2f -> €%.2f', $old_total, $total_amount));

        wp_send_json_success([
            'message' => '当日日结单数据已更新',
            'total_amount' => $total_amount,
            'cash_amount' => $cash_amount,
            'card_amount' => $card_amount,
            'bizum_amount' => $bizum_amount
        ]);

    } catch (Exception $e) {
        wp_send_json_error(['message' => '更新失败: ' . $e->getMessage()]);
    }
}

/**
 * AJAX处理函数 - 超级管理员获取所有月结单记录列表（带post_id用于编辑）
 */
add_action('wp_ajax_ruiyi_admin_get_all_settlements', 'ruiyi_admin_get_all_settlements_callback');
function ruiyi_admin_get_all_settlements_callback() {
    // 验证nonce
    if (!isset($_POST['nonce']) || !wp_verify_nonce($_POST['nonce'], 'ruiyi_pos_nonce')) {
        wp_send_json_error(['message' => '安全验证失败']);
        return;
    }

    // 🔐 超级管理员权限检查
    if (!ruiyi_is_super_admin_user()) {
        wp_send_json_error(['message' => '需要超级管理员权限']);
        return;
    }

    try {
        $from_date = isset($_POST['from_date']) ? sanitize_text_field($_POST['from_date']) : '';
        $to_date = isset($_POST['to_date']) ? sanitize_text_field($_POST['to_date']) : '';
        $month = isset($_POST['month']) ? sanitize_text_field($_POST['month']) : '';

        // 构建查询参数
        $meta_query = array('relation' => 'AND');

        if ($month) {
            $month_start = $month . '-01';
            $month_end = date('Y-m-t', strtotime($month_start));
            $meta_query[] = array(
                'key' => '_summary_date',
                'value' => array($month_start, $month_end),
                'compare' => 'BETWEEN',
                'type' => 'DATE'
            );
        } elseif ($from_date && $to_date) {
            $meta_query[] = array(
                'key' => '_summary_date',
                'value' => array($from_date, $to_date),
                'compare' => 'BETWEEN',
                'type' => 'DATE'
            );
        }

        $args = array(
            'post_type' => 'monthly_summary',
            'posts_per_page' => -1,
            'post_status' => 'publish',
            'orderby' => 'meta_value',
            'meta_key' => '_settlement_datetime',
            'order' => 'DESC',
            'meta_query' => count($meta_query) > 1 ? $meta_query : []
        );

        $posts = get_posts($args);
        $records = [];
        $total_sum = 0;
        $cash_sum = 0;
        $card_sum = 0;
        $bizum_sum = 0;

        foreach ($posts as $post) {
            $business_date = get_post_meta($post->ID, '_business_date', true);
            if (empty($business_date)) {
                $business_date = get_post_meta($post->ID, '_summary_date', true);
            }

            $total = floatval(get_post_meta($post->ID, '_total_amount', true));
            $cash = floatval(get_post_meta($post->ID, '_cash_amount', true));
            $card = floatval(get_post_meta($post->ID, '_card_amount', true));
            $bizum = floatval(get_post_meta($post->ID, '_bizum_amount', true));

            $records[] = array(
                'post_id' => $post->ID,
                'title' => $post->post_title,
                'date' => $business_date,
                'settlement_datetime' => get_post_meta($post->ID, '_settlement_datetime', true),
                'period_start' => get_post_meta($post->ID, '_period_start', true),
                'period_end' => get_post_meta($post->ID, '_period_end', true),
                'total_amount' => $total,
                'cash_amount' => $cash,
                'card_amount' => $card,
                'bizum_amount' => $bizum,
                'starting_cash' => floatval(get_post_meta($post->ID, '_starting_cash', true)),
                'admin_modified' => get_post_meta($post->ID, '_admin_modified', true),
                'admin_modified_by' => get_post_meta($post->ID, '_admin_modified_by', true),
                'admin_created' => get_post_meta($post->ID, '_admin_created', true),
                'admin_created_by' => get_post_meta($post->ID, '_admin_created_by', true)
            );

            $total_sum += $total;
            $cash_sum += $cash;
            $card_sum += $card;
            $bizum_sum += $bizum;
        }

        wp_send_json_success([
            'records' => $records,
            'summary' => [
                'total' => $total_sum,
                'cash' => $cash_sum,
                'card' => $card_sum,
                'bizum' => $bizum_sum,
                'count' => count($records)
            ]
        ]);

    } catch (Exception $e) {
        wp_send_json_error(['message' => '获取失败: ' . $e->getMessage()]);
    }
}

