/**
 * 月结单管理页面内容
 */
function ruiyi_monthly_summary_admin_page() {
    // 检查用户权限
    if (!current_user_can('manage_woocommerce')) {
        wp_die('您没有权限访问此页面');
    }

    // 处理清空操作
    if (isset($_POST['clear_monthly_summary']) && check_admin_referer('clear_monthly_summary_nonce')) {
        $clear_type = isset($_POST['clear_type']) ? sanitize_text_field($_POST['clear_type']) : '';
        $month_to_clear = isset($_POST['month_to_clear']) ? sanitize_text_field($_POST['month_to_clear']) : '';

        $result = ruiyi_clear_monthly_summary_data($clear_type, $month_to_clear);

        if ($result['success']) {
            echo '<div class="notice notice-success"><p>' . esc_html($result['message']) . '</p></div>';
        } else {
            echo '<div class="notice notice-error"><p>' . esc_html($result['message']) . '</p></div>';
        }
    }

    // 获取所有月结单数据
    $monthly_summaries = get_posts(array(
        'post_type' => 'monthly_summary',
        'posts_per_page' => -1,
        'post_status' => 'publish',
        'orderby' => 'meta_value',
        'meta_key' => '_business_date',
        'order' => 'DESC'
    ));

    // 统计数据
    $total_records = count($monthly_summaries);
    $total_amount = 0;
    $total_cash = 0;
    $total_card = 0;
    $months_list = array();

    foreach ($monthly_summaries as $summary) {
        $business_date = get_post_meta($summary->ID, '_business_date', true);
        if (empty($business_date)) {
            $business_date = get_post_meta($summary->ID, '_summary_date', true);
        }

        $month_key = date('Y-m', strtotime($business_date));
        if (!in_array($month_key, $months_list)) {
            $months_list[] = $month_key;
        }

        $total_amount += floatval(get_post_meta($summary->ID, '_total_amount', true));
        $total_cash += floatval(get_post_meta($summary->ID, '_cash_amount', true));
        $total_card += floatval(get_post_meta($summary->ID, '_card_amount', true));
    }

    sort($months_list);
    $months_list = array_reverse($months_list);
    ?>

    <div class="wrap">
        <h1>📊 月结单数据管理</h1>
        <p>管理系统中的月结单数据，包括查看统计信息和清空数据。</p>

        <!-- 统计信息卡片 -->
        <div class="card" style="max-width: none; margin: 20px 0; padding: 20px; background: #fff; border: 1px solid #ccd0d4; box-shadow: 0 1px 1px rgba(0,0,0,.04);">
            <h2 style="margin-top: 0;">📈 数据统计</h2>
            <table class="widefat" style="margin-top: 15px;">
                <tr>
                    <th style="width: 200px;">总记录数</th>
                    <td><strong><?php echo number_format($total_records); ?></strong> 条</td>
                </tr>
                <tr>
                    <th>累计总额</th>
                    <td><strong>€<?php echo number_format($total_amount, 2); ?></strong></td>
                </tr>
                <tr>
                    <th>累计现金</th>
                    <td><strong>€<?php echo number_format($total_cash, 2); ?></strong></td>
                </tr>
                <tr>
                    <th>累计刷卡</th>
                    <td><strong>€<?php echo number_format($total_card, 2); ?></strong></td>
                </tr>
                <tr>
                    <th>数据月份</th>
                    <td><?php echo !empty($months_list) ? implode(', ', $months_list) : '无'; ?></td>
                </tr>
            </table>
        </div>

        <!-- 清空数据功能 -->
        <div class="card" style="max-width: none; margin: 20px 0; padding: 20px; background: #fff; border: 1px solid #ccd0d4; box-shadow: 0 1px 1px rgba(0,0,0,.04);">
            <h2 style="margin-top: 0;">🗑️ 清空月结单数据</h2>
            <p style="color: #d63638;"><strong>⚠️ 警告：</strong>此操作不可撤销！请谨慎操作。建议在清空前先导出数据备份。</p>

            <form method="post" action="" id="clear-monthly-form">
                <?php wp_nonce_field('clear_monthly_summary_nonce'); ?>

                <table class="form-table">
                    <tr>
                        <th scope="row">清空范围</th>
                        <td>
