/**
 * 清空月结单数据的核心函数
 *
 * @param string $clear_type 清空类型 ('all' 或 'month')
 * @param string $month_to_clear 要清空的月份 (格式: YYYY-MM)
 * @return array 返回操作结果
 */
function ruiyi_clear_monthly_summary_data($clear_type, $month_to_clear = '') {
    global $wpdb;

    // 验证参数
    if ($clear_type !== 'all' && $clear_type !== 'month') {
        return array(
            'success' => false,
            'message' => '无效的清空类型'
        );
    }

    if ($clear_type === 'month' && empty($month_to_clear)) {
        return array(
            'success' => false,
            'message' => '请选择要清空的月份'
        );
    }

    try {
        $deleted_count = 0;

        if ($clear_type === 'all') {
            // 清空所有月结单数据
            $all_summaries = get_posts(array(
                'post_type' => 'monthly_summary',
                'posts_per_page' => -1,
                'post_status' => 'publish'
            ));

            foreach ($all_summaries as $summary) {
                wp_delete_post($summary->ID, true); // true = 永久删除，不放入回收站
                $deleted_count++;
            }

            ruiyi_debug_log('[月结单管理] 已清空所有月结单数据，共 ' . $deleted_count . ' 条记录');

            return array(
                'success' => true,
                'message' => sprintf('成功清空了所有月结单数据，共删除 %d 条记录', $deleted_count)
            );

        } else if ($clear_type === 'month') {
            // 清空指定月份的数据
            $month_start = $month_to_clear . '-01';
            $month_end = date('Y-m-t', strtotime($month_start));

            $month_summaries = get_posts(array(
                'post_type' => 'monthly_summary',
                'posts_per_page' => -1,
                'post_status' => 'publish',
                'meta_query' => array(
                    array(
                        'key' => '_business_date',
                        'value' => array($month_start, $month_end),
                        'compare' => 'BETWEEN',
                        'type' => 'DATE'
                    )
                )
            ));

            // 如果 _business_date 查询为空，尝试用 _summary_date 查询（向后兼容）
            if (empty($month_summaries)) {
                $month_summaries = get_posts(array(
                    'post_type' => 'monthly_summary',
                    'posts_per_page' => -1,
                    'post_status' => 'publish',
                    'meta_query' => array(
                        array(
                            'key' => '_summary_date',
                            'value' => array($month_start, $month_end),
                            'compare' => 'BETWEEN',
                            'type' => 'DATE'
                        )
                    )
                ));
            }

            foreach ($month_summaries as $summary) {
                wp_delete_post($summary->ID, true);
                $deleted_count++;
            }

            ruiyi_debug_log('[月结单管理] 已清空 ' . $month_to_clear . ' 的月结单数据，共 ' . $deleted_count . ' 条记录');

            return array(
                'success' => true,
                'message' => sprintf('成功清空了 %s 的月结单数据，共删除 %d 条记录',
                    date('Y年m月', strtotime($month_start)),
                    $deleted_count)
            );
        }

    } catch (Exception $e) {
        ruiyi_debug_log('[月结单管理] 清空数据失败: ' . $e->getMessage());
        return array(
            'success' => false,
            'message' => '清空失败: ' . $e->getMessage()
        );
    }
}

/**
 * Clear all saved original orders
 * This function deletes all WooCommerce orders from the database
 *
 * @param array $statuses Optional. Array of order statuses to delete. Default: ['pending', 'processing', 'on-hold', 'completed', 'cancelled', 'refunded', 'failed']
 * @param bool $permanent_delete Optional. Whether to permanently delete (true) or move to trash (false). Default: true
 * @return array Result array with success status, deleted count, and message
 */
function ruiyi_clear_all_original_orders($statuses = null, $permanent_delete = true) {
    // Check user permissions
    if (!current_user_can('manage_woocommerce') && !current_user_can('administrator')) {
        return array(
            'success' => false,
            'message' => ruiyi_translate('No tiene permisos para realizar esta acción', 'You do not have permission to perform this action', '您没有权限执行此操作'),
            'deleted_count' => 0
        );
    }

    // Default statuses to delete if not specified
    if ($statuses === null) {
        $statuses = ['pending', 'processing', 'on-hold', 'completed', 'cancelled', 'refunded', 'failed'];
    }

    try {
        ruiyi_debug_log('[清空订单] 开始清空所有原始订单 - 状态: ' . implode(', ', $statuses) . ', 永久删除: ' . ($permanent_delete ? '是' : '否'));

        // Get all orders with specified statuses
        $orders = wc_get_orders(array(
            'limit' => -1,
            'status' => $statuses,
            'return' => 'ids' // Get only IDs for better performance
        ));

        $total_orders = count($orders);
        $deleted_count = 0;
        $failed_count = 0;
        $deleted_order_ids = array();

        ruiyi_debug_log('[清空订单] 找到 ' . $total_orders . ' 个订单需要删除');

        if ($total_orders === 0) {
            return array(
                'success' => true,
                'message' => ruiyi_translate('No se encontraron órdenes para eliminar', 'No orders found to delete', '未找到需要删除的订单'),
                'deleted_count' => 0,
                'total_orders' => 0
            );
        }

        // Delete each order
        foreach ($orders as $order_id) {
            try {
                $order = wc_get_order($order_id);
                
                if (!$order) {
                    ruiyi_debug_log('[清空订单] ⚠️ 订单 #' . $order_id . ' 不存在，跳过');
                    $failed_count++;
                    continue;
                }

                // Get order info before deletion for logging
                $order_number = $order->get_order_number();
                $order_total = $order->get_total();
                $order_status = $order->get_status();
                $order_date = $order->get_date_created() ? $order->get_date_created()->date('Y-m-d H:i:s') : 'N/A';

                // Delete the order
                if ($permanent_delete) {
                    $deleted = $order->delete(true); // true = permanent delete
                } else {
                    $deleted = $order->delete(false); // false = move to trash
                }

                if ($deleted) {
                    $deleted_count++;
                    $deleted_order_ids[] = $order_id;
                    
                    // Clear caches
                    wp_cache_delete($order_id, 'posts');
                    wp_cache_delete($order_id, 'post_meta');
                    wp_cache_delete($order_id, 'shop_order');
                    wp_cache_delete($order_id, 'orders');
                    clean_post_cache($order_id);
                    
                    // Clear transients
                    delete_transient('wc_order_' . $order_id);
                    delete_transient('ruiyi_pos_order_' . $order_id);
                    
                    ruiyi_debug_log('[清空订单] ✅ 已删除订单 #' . $order_id . ' (订单号: ' . $order_number . ', 状态: ' . $order_status . ', 总额: €' . $order_total . ', 日期: ' . $order_date . ')');
                } else {
                    $failed_count++;
                    ruiyi_debug_log('[清空订单] ❌ 删除订单 #' . $order_id . ' 失败');
                }

                // Clear cache every 50 orders to prevent memory issues
                if ($deleted_count % 50 === 0) {
                    wp_cache_flush();
                    ruiyi_debug_log('[清空订单] 已清理缓存 (已删除: ' . $deleted_count . ' 个订单)');
                }

            } catch (Exception $e) {
                $failed_count++;
                ruiyi_debug_log('[清空订单] ❌ 删除订单 #' . $order_id . ' 时发生异常: ' . $e->getMessage());
            }
        }

        // Final cache flush
        wp_cache_flush();
        
        // Clear WooCommerce order count transients
        delete_transient('wc_orders_count');
        delete_transient('wc_processing_order_count');
        delete_transient('wc_pending_order_count');
        delete_transient('wc_on_hold_order_count');

        $message = sprintf(
            ruiyi_translate(
                '已删除 %d 个订单，失败 %d 个，共 %d 个订单',
                'Deleted %d orders, failed %d, total %d orders',
                '已删除 %d 个订单，失败 %d 个，共 %d 个订单'
            ),
            $deleted_count,
            $failed_count,
            $total_orders
        );

        ruiyi_debug_log('[清空订单] ✅ 完成 - ' . $message);

        return array(
            'success' => true,
            'message' => $message,
            'deleted_count' => $deleted_count,
            'failed_count' => $failed_count,
            'total_orders' => $total_orders,
            'deleted_order_ids' => $deleted_order_ids,
            'statuses' => $statuses,
            'permanent_delete' => $permanent_delete
        );

    } catch (Exception $e) {
        ruiyi_debug_log('[清空订单] ❌ 清空订单时发生异常: ' . $e->getMessage());
        return array(
            'success' => false,
            'message' => ruiyi_translate('清空订单时发生错误', 'Error occurred while clearing orders', '清空订单时发生错误') . ': ' . $e->getMessage(),
            'deleted_count' => isset($deleted_count) ? $deleted_count : 0
        );
    }
}

/**
 * AJAX Handler: Clear all original orders
 * Allows clearing all saved orders via AJAX request
 */
add_action('wp_ajax_ruiyi_clear_all_original_orders', 'ruiyi_clear_all_original_orders_handler');
add_action('wp_ajax_nopriv_ruiyi_clear_all_original_orders', 'ruiyi_clear_all_original_orders_handler');

function ruiyi_clear_all_original_orders_handler() {
    if (!is_user_logged_in()) {
        wp_send_json_error(['message' => 'Authentication required']);
        return;
    }

    // Verify nonce for security
    check_ajax_referer('ruiyi_pos_nonce', 'nonce');

    // Check user permissions
    if (!current_user_can('manage_woocommerce') && !current_user_can('administrator')) {
        wp_send_json_error(array(
            'message' => ruiyi_translate('No tiene permisos para realizar esta acción', 'You do not have permission to perform this action', '您没有权限执行此操作')
        ));
        return;
    }

    // Get optional parameters
    $statuses = null;
    if (isset($_POST['statuses']) && !empty($_POST['statuses'])) {
        $statuses = is_array($_POST['statuses']) ? $_POST['statuses'] : explode(',', sanitize_text_field($_POST['statuses']));
        $statuses = array_map('trim', $statuses);
    }

    $permanent_delete = isset($_POST['permanent_delete']) ? (bool)$_POST['permanent_delete'] : true;

    // Execute the clear function
    $result = ruiyi_clear_all_original_orders($statuses, $permanent_delete);

    if ($result['success']) {
        wp_send_json_success($result);
    } else {
        wp_send_json_error($result);
    }

    wp_die();
}

