/**
 * Register special category field hooks after WooCommerce is loaded
 * 在WooCommerce加载后注册特殊分类字段钩子
 */
function ruiyi_register_special_category_fields() {
    if (!class_exists('WooCommerce')) {
        return;
    }
    
    // Add custom field to WooCommerce product category edit form
    // 在WooCommerce产品分类编辑表单中添加自定义字段
    add_action('product_cat_add_form_fields', 'ruiyi_add_special_category_field', 10);
    add_action('product_cat_edit_form_fields', 'ruiyi_add_special_category_field', 10, 1);
    
    // Save the special category field
    // 保存特殊分类字段
    add_action('created_product_cat', 'ruiyi_save_special_category_field', 10, 1);
    add_action('edited_product_cat', 'ruiyi_save_special_category_field', 10, 1);
}

// Register hooks when WooCommerce is loaded
add_action('woocommerce_loaded', 'ruiyi_register_special_category_fields');
// Also try to register immediately if WooCommerce is already loaded
if (did_action('woocommerce_loaded')) {
    ruiyi_register_special_category_fields();
} else {
    // Fallback: register on init if WooCommerce is already active
    add_action('init', 'ruiyi_register_special_category_fields', 20);
}

