                });
                $('#ruiyi_category_color').on('change', function() {
                    $('#ruiyi_category_color_preset').val('');
                });
            });
            </script>
        </div>
        <?php
        // 分类打印机配置（仅在启用时显示）- 添加表单
        $category_printer_enabled = get_option('clodop_category_printer_enabled', 0);
        if ($category_printer_enabled) {
            ?>
            <div class="form-field term-category-printer-wrap">
                <label for="ruiyi_category_printer"><?php echo ruiyi_translate('厨房打印机', 'Kitchen Printer', '厨房打印机'); ?></label>
                <select id="ruiyi_category_printer" name="ruiyi_category_printer" style="width:100%;">
                    <option value=""><?php echo ruiyi_translate('-- 使用默认厨房打印机 --', '-- Use Default Kitchen Printer --', '-- 使用默认厨房打印机 --'); ?></option>
                </select>
                <button type="button" id="refresh-category-printer-list" class="button" style="margin-top:5px;">🔄 <?php echo ruiyi_translate('刷新打印机列表', 'Refresh Printer List', '刷新打印机列表'); ?></button>
                <p class="description">
                    <?php echo ruiyi_translate(
                        '选择此分类产品的专属厨房打印机',
                        'Select a dedicated kitchen printer for products in this category',
                        '选择此分类产品的专属厨房打印机'
                    ); ?>
                </p>
                <script src="<?php echo home_url('/LodopFuncs.js'); ?>"></script>
                <script>
                jQuery(document).ready(function($) {
                    let LODOP_CAT_ADD = null;

                    function loadCategoryPrintersAdd() {
                        const select = $('#ruiyi_category_printer');
                        select.find('option:not(:first)').remove();

                        if (typeof getLodop === 'undefined') {
                            select.append('<option disabled>-- CLODOP服务未就绪 --</option>');
                            return;
                        }

                        try {
                            LODOP_CAT_ADD = getLodop();
                            if (LODOP_CAT_ADD && LODOP_CAT_ADD.VERSION) {
                                const count = LODOP_CAT_ADD.GET_PRINTER_COUNT();
                                for (let i = 0; i < count; i++) {
                                    const name = LODOP_CAT_ADD.GET_PRINTER_NAME(i);
                                    select.append($('<option></option>').val(name).text(name));
                                }
                                if (count === 0) {
                                    select.append('<option disabled>-- 未检测到打印机 --</option>');
                                }
                            } else {
                                select.append('<option disabled>-- 请启动CLODOP服务 --</option>');
                            }
                        } catch (e) {
                            select.append('<option disabled>-- 加载失败 --</option>');
                        }
                    }

                    setTimeout(loadCategoryPrintersAdd, 1000);

                    $('#refresh-category-printer-list').click(function() {
                        loadCategoryPrintersAdd();
                    });
                });
                </script>
            </div>
            <?php
        }
    }
}


function ruiyi_save_special_category_field($term_id) {
    // Check if WooCommerce is active
    if (!class_exists('WooCommerce')) {
        return;
    }

    // Verify nonce for security (WordPress automatically adds this)
    if (!isset($_POST['_wpnonce'])) {
        return;
    }

    // 保存分类颜色
    if (isset($_POST['ruiyi_category_color'])) {
        $category_color = sanitize_hex_color($_POST['ruiyi_category_color']);
        if ($category_color) {
            update_term_meta($term_id, '_ruiyi_category_color', $category_color);
        }
    }

    // Save the checkbox value
    if (isset($_POST['show_numberpad']) && $_POST['show_numberpad'] === '1') {
        update_term_meta($term_id, 'show_numberpad', '1');
    } else {
        // If checkbox is not checked, set to '0'
        update_term_meta($term_id, 'show_numberpad', '0');
    }

    // 保存分类打印机配置
    if (isset($_POST['ruiyi_category_printer'])) {
        $category_printer = sanitize_text_field($_POST['ruiyi_category_printer']);
        if (!empty($category_printer)) {
            update_term_meta($term_id, '_ruiyi_category_printer', $category_printer);
        } else {
            delete_term_meta($term_id, '_ruiyi_category_printer');
        }
    }
}

/**
 * Check if a category is a special category (shows numberpad)
 * 检查分类是否为特殊分类（显示数字键盘）
 */
function ruiyi_is_special_category($category_id) {
    $show_numberpad = get_term_meta($category_id, 'show_numberpad', true);
    // Debug: Log the value to help troubleshoot
    if (defined('WP_DEBUG') && WP_DEBUG) {
        ruiyi_debug_log("ruiyi_is_special_category - Category ID: $category_id, show_numberpad value: " . var_export($show_numberpad, true));
    }
    // Check for multiple possible values (string '1', boolean true, integer 1, string 'yes')
    return ($show_numberpad === '1' || $show_numberpad === true || $show_numberpad === 1 || $show_numberpad === 'yes');
}

/**
 * Get special category status for a product
 * 获取产品的特殊分类状态
 */
function ruiyi_get_product_special_category_status($product_id) {
    $terms = get_the_terms($product_id, 'product_cat');
    if ($terms && !is_wp_error($terms)) {
        foreach ($terms as $term) {
            if (ruiyi_is_special_category($term->term_id)) {
                return true;
            }
        }
    }
    return false;
}

