/**
 * Get weight unit aliases for scale products
 *
 * @return array
 */
function ruiyi_pos_get_weight_unit_aliases() {
    $defaults = array('kg', 'kilogram', 'kilograms', 'kilo', 'kilos', '公斤', '千克');
    $option_value = get_option('ruiyi_pos_weight_units', '');

    if (!empty($option_value)) {
        $custom_units = array_filter(array_map('trim', explode(',', $option_value)));
        if (!empty($custom_units)) {
            $custom_units = array_map('strtolower', $custom_units);
            $defaults = array_unique(array_merge($defaults, $custom_units));
        }
    }

    return array_values(array_map('strtolower', $defaults));
}

/**
 * Scale middleware configuration exposed to the POS front-end.
 * Scale Hub URL is hardcoded here.
 *
 * @return array
 */
function ruiyi_pos_get_scale_integration_config() {
    // 🔥 从WordPress后台读取配置（而不是硬编码）
    $enabled = get_option('ruiyi_scale_enabled', false);
    $scale_hub_url = get_option('ruiyi_scale_hub_url', 'https://srv985735.hstgr.cloud/scale');
    $location = get_option('ruiyi_scale_location', 'store-001');
    $auth_token = get_option('ruiyi_scale_auth_token', '');
    $debug = get_option('ruiyi_scale_debug', false);

    /**
     * ⚠️ CRITICAL: Location Configuration
     *
     * The 'location' value MUST match the POS_SOCKET_LOCATION in scale-middleware/.env
     * The scale hub uses rooms based on location: scale:{location}
     * If locations don't match, the POS won't receive weight events from the scale middleware!
     *
     * Example:
     * - If scale-middleware/.env has: POS_SOCKET_LOCATION=store-001
     * - Then this should be: 'location' => 'store-001'
     */
    $config = array(
        'enabled' => (bool)$enabled, // 🔥 从后台读取
        'socket_url' => $scale_hub_url, // 🔥 从后台读取
        'socket_path' => '/socket.io',
        'retry_ms' => 2000,
        'stale_after_ms' => 5000,
        'precision' => 3,
        'min_weight_kg' => 0.005,
        'weight_unit' => 'kg',
        'unit_aliases' => ruiyi_pos_get_weight_unit_aliases(),
        'debug' => (bool)$debug, // 🔥 从后台读取
        'location' => $location, // 🔥 从后台读取（⚠️ MUST match scale-middleware POS_SOCKET_LOCATION）
        'auth_token' => $auth_token, // 🔥 从后台读取
        'client_type' => 'pos',
    );

    /**
     * Allow plugins to adjust the scale integration configuration before it reaches the front-end.
     *
     * @param array $config
     */
    return apply_filters('ruiyi_pos_scale_config', $config);
}

/**
 * Add "Sold by weight" checkbox to WooCommerce product category settings.
 */
function ruiyi_pos_add_scale_category_field($term = null) {
    if (!class_exists('WooCommerce')) {
        return;
    }
    
    // Determine if this is edit form (term object provided) or add form (no term)
    $is_edit = ($term !== null && is_object($term) && isset($term->term_id));
    $term_id = $is_edit ? $term->term_id : 0;
    $is_scale_product = $is_edit ? get_term_meta($term_id, '_is_scale_product', true) : 'no';
    $checked = ($is_scale_product === 'yes' || $is_scale_product === '1' || $is_scale_product === true) ? 'checked="checked"' : '';
    
    if ($is_edit) {
        // Edit form - table row format
        ?>
        <tr class="form-field term-is-scale-product-wrap">
            <th scope="row" valign="top">
                <label for="is_scale_product"><?php echo __('Sold by weight (scale)', 'ruiyi-pos-manager'); ?></label>
            </th>
            <td>
                <label for="is_scale_product">
                    <input type="checkbox" name="is_scale_product" id="is_scale_product" value="yes" <?php echo $checked; ?>>
                    <?php echo __('Enable if products in this category should be calculated using live scale weight in POS.', 'ruiyi-pos-manager'); ?>
                </label>
                <p class="description">
                    <?php echo __('When enabled, all products in this category will use live scale weight for price calculation in POS.', 'ruiyi-pos-manager'); ?>
                </p>
            </td>
        </tr>
        <?php
    } else {
        // Add form - div format
        ?>
        <div class="form-field term-is-scale-product-wrap">
            <label for="is_scale_product">
                <input type="checkbox" name="is_scale_product" id="is_scale_product" value="yes">
                <?php echo __('Sold by weight (scale)', 'ruiyi-pos-manager'); ?>
            </label>
            <p class="description">
                <?php echo __('Enable if products in this category should be calculated using live scale weight in POS.', 'ruiyi-pos-manager'); ?>
            </p>
        </div>
        <?php
    }
}

/**
 * Register scale category field hooks
 */
function ruiyi_register_scale_category_fields() {
    if (!class_exists('WooCommerce')) {
        return;
    }
    
    // Add custom field to WooCommerce product category edit form
    add_action('product_cat_add_form_fields', 'ruiyi_pos_add_scale_category_field', 10);
    add_action('product_cat_edit_form_fields', 'ruiyi_pos_add_scale_category_field', 10, 1);
    
    // Save the scale category field
    add_action('created_product_cat', 'ruiyi_pos_save_scale_category_field', 10, 1);
    add_action('edited_product_cat', 'ruiyi_pos_save_scale_category_field', 10, 1);
}

// Register hooks when WooCommerce is loaded
add_action('woocommerce_loaded', 'ruiyi_register_scale_category_fields');
// Also try to register immediately if WooCommerce is already loaded
if (did_action('woocommerce_loaded')) {
    ruiyi_register_scale_category_fields();
} else {
    // Fallback: register on init if WooCommerce is already active
    add_action('init', 'ruiyi_register_scale_category_fields', 20);
}

