/**
 * ==================================
 * Multi-Level Category System (多级分类系统)
 * ==================================
 * 支持最多3层分类结构（一级→二级→三级）
 * 商品可分配到任意层级，点击分类时显示子分类按钮+所有层级商品
 */

/**
 * 计算分类的层级深度
 *
 * @param int $term_id 分类ID
 * @return int 层级深度（1=一级，2=二级，3=三级）
 */
function ruiyi_get_category_depth($term_id) {
    $depth = 1;
    $max_depth = 10; // 防止无限循环
    $current_id = $term_id;

    while ($depth <= $max_depth) {
        $term = get_term($current_id, 'product_cat');
        if (is_wp_error($term) || !$term) {
            break;
        }

        if ($term->parent == 0) {
            // 到达顶层
            break;
        }

        $depth++;
        $current_id = $term->parent;
    }

    return $depth;
}

/**
 * 获取分类的所有子孙分类ID（递归）
 *
 * @param int $parent_id 父分类ID
 * @param bool $include_self 是否包含自身ID
 * @return array 所有子孙分类ID数组
 */
function ruiyi_get_category_descendants($parent_id, $include_self = true) {
    $descendants = $include_self ? array($parent_id) : array();

    $children = get_term_children($parent_id, 'product_cat');

    if (!is_wp_error($children) && !empty($children)) {
        foreach ($children as $child_id) {
            $descendants[] = $child_id;
        }
    }

    return array_unique($descendants);
}

/**
 * 生成分类树结构（递归，最多3层）
 *
 * @param int $parent_id 父分类ID（0表示顶层）
 * @param int $current_depth 当前深度
 * @param int $max_depth 最大深度（默认3）
 * @return array 分类树结构
 */
function ruiyi_get_category_tree($parent_id = 0, $current_depth = 1, $max_depth = 3) {
    // 排除的分类slug
    $excluded_slugs = array('uncategorized', 'suplementos');

    $args = array(
        'taxonomy'   => 'product_cat',
        'hide_empty' => false,
        'parent'     => $parent_id,
        'orderby'    => 'name',
        'order'      => 'ASC',
    );

    $categories = get_terms($args);

    if (is_wp_error($categories) || empty($categories)) {
        return array();
    }

    $tree = array();

    foreach ($categories as $category) {
        // 跳过排除的分类
        if (in_array($category->slug, $excluded_slugs)) {
            continue;
        }

        // 获取多语言名称
        $name_zh = get_term_meta($category->term_id, 'category_name_zh', true);
        $name_en = get_term_meta($category->term_id, 'category_name_en', true);
        $name_es = get_term_meta($category->term_id, 'category_name_es', true);

        // 获取排序值（仅一级分类使用）
        $sort_order = get_term_meta($category->term_id, 'category_sort_order', true);
        $sort_order = $sort_order !== '' ? intval($sort_order) : 999;

        // 获取产品数量（包含子分类的产品）
        $product_count = ruiyi_get_category_product_count($category->term_id);

        // 检查是否有子分类
        $children = array();
        $has_children = false;

        if ($current_depth < $max_depth) {
            $child_terms = get_term_children($category->term_id, 'product_cat');
            // 过滤掉排除的子分类
            if (!is_wp_error($child_terms)) {
                foreach ($child_terms as $child_id) {
                    $child_term = get_term($child_id, 'product_cat');
                    if ($child_term && !in_array($child_term->slug, $excluded_slugs) && $child_term->parent == $category->term_id) {
                        $has_children = true;
                        break;
                    }
                }
            }

            if ($has_children) {
                $children = ruiyi_get_category_tree($category->term_id, $current_depth + 1, $max_depth);
            }
        }

        $tree[] = array(
            'term_id'       => $category->term_id,
            'name'          => $category->name,
            'slug'          => $category->slug,
            'parent'        => $category->parent,
            'depth'         => $current_depth,
            'name_zh'       => $name_zh ?: '',
            'name_en'       => $name_en ?: '',
            'name_es'       => $name_es ?: $category->name,
            'product_count' => $product_count,
            'has_children'  => $has_children,
            'can_add_child' => ($current_depth < $max_depth),
            'children'      => $children,
            'sort_order'    => $sort_order,
            'image_id'      => ruiyi_get_product_category_image_id($category->term_id),
            'image_url'     => ruiyi_get_product_category_image_url($category->term_id, 'thumbnail'),
        );
    }

    // 一级分类按 sort_order 排序
    if ($parent_id == 0 && $current_depth == 1) {
        usort($tree, function($a, $b) {
            return $a['sort_order'] - $b['sort_order'];
        });
    }

    return $tree;
}

/**
 * 获取分类的产品数量（包含所有子孙分类）
 *
 * @param int $term_id 分类ID
 * @return int 产品数量
 */
function ruiyi_get_category_product_count($term_id) {
    // 🔥 修复：简化查询，直接使用term_id查询产品
    // WooCommerce会自动包含子分类的产品
    $args = array(
        'status'   => 'publish',
        'limit'    => -1,
        'return'   => 'ids',
        'category' => array($term_id), // 🔥 使用数组格式，WooCommerce会自动包含子分类
    );

    $products = wc_get_products($args);
    $count = count($products);

    // 🔥 添加调试日志
    ruiyi_debug_log('[分类产品数] 分类ID: ' . $term_id . ', 查询到产品数量: ' . $count);

    return $count;
}

/**
 * 扁平化分类树结构（用于下拉菜单）
 *
 * @param array $tree 分类树
 * @param string $prefix 前缀（用于缩进）
 * @param int $max_depth 最大深度
 * @return array 扁平化的分类列表
 */
function ruiyi_flatten_category_tree($tree, $prefix = '', $max_depth = 3) {
    $flat = array();

    foreach ($tree as $item) {
        $indent = str_repeat('— ', max(0, $item['depth'] - 1));

        $flat[] = array(
            'term_id'       => $item['term_id'],
            'name'          => $item['name'],
            'display_name'  => $indent . $item['name'],
            'depth'         => $item['depth'],
            'name_zh'       => $item['name_zh'],
            'name_en'       => $item['name_en'],
            'name_es'       => $item['name_es'],
            'product_count' => $item['product_count'],
            'can_add_child' => $item['can_add_child'],
            'has_children'  => $item['has_children'],
            'image_id'      => isset($item['image_id']) ? $item['image_id'] : 0,
            'image_url'     => isset($item['image_url']) ? $item['image_url'] : '',
        );

        // 递归处理子分类
        if (!empty($item['children'])) {
            $child_flat = ruiyi_flatten_category_tree($item['children'], $prefix, $max_depth);
            $flat = array_merge($flat, $child_flat);
        }
    }

    return $flat;
}

// ==========================================
// AJAX Handler 1: 创建产品分类
// ==========================================
add_action('wp_ajax_ruiyi_create_product_category', 'ruiyi_create_product_category_handler');

function ruiyi_create_product_category_handler() {
    check_ajax_referer('ruiyi_pos_nonce', 'nonce');

    // 验证权限
    if (!current_user_can('manage_woocommerce')) {
        wp_send_json_error(array('message' => 'Sin permisos para crear categorías.'));
        return;
    }

    // 获取参数
    $category_name = isset($_POST['category_name']) ? sanitize_text_field($_POST['category_name']) : '';
    $parent_id = isset($_POST['parent_id']) ? intval($_POST['parent_id']) : 0;
    $name_zh = isset($_POST['name_zh']) ? sanitize_text_field($_POST['name_zh']) : '';
    $name_en = isset($_POST['name_en']) ? sanitize_text_field($_POST['name_en']) : '';
    $name_es = isset($_POST['name_es']) ? sanitize_text_field($_POST['name_es']) : '';

    // 验证分类名称
    if (empty($category_name)) {
        wp_send_json_error(array('message' => 'El nombre de la categoría es obligatorio.'));
        return;
    }

    // 验证层级深度（最多3层）
    if ($parent_id > 0) {
        $parent_depth = ruiyi_get_category_depth($parent_id);
        if ($parent_depth >= 3) {
            wp_send_json_error(array('message' => 'No se puede crear más de 3 niveles de categoría.'));
            return;
        }

        // 验证父分类存在
        $parent_term = get_term($parent_id, 'product_cat');
        if (is_wp_error($parent_term) || !$parent_term) {
            wp_send_json_error(array('message' => 'La categoría padre no existe.'));
            return;
        }
    }

    // 检查分类名称是否已存在于同级
    $existing = get_term_by('name', $category_name, 'product_cat');
    if ($existing && $existing->parent == $parent_id) {
        wp_send_json_error(array('message' => 'Ya existe una categoría con este nombre en el mismo nivel.'));
        return;
    }

    // 创建分类
    $term_data = wp_insert_term($category_name, 'product_cat', array(
        'parent' => $parent_id,
    ));

    if (is_wp_error($term_data)) {
        wp_send_json_error(array('message' => 'Error al crear categoría: ' . $term_data->get_error_message()));
        return;
    }

    $term_id = $term_data['term_id'];

    // 保存多语言名称
    if (!empty($name_zh)) {
        update_term_meta($term_id, 'category_name_zh', $name_zh);
    }
    if (!empty($name_en)) {
        update_term_meta($term_id, 'category_name_en', $name_en);
    }
    if (!empty($name_es)) {
        update_term_meta($term_id, 'category_name_es', $name_es);
    }

    // 计算新分类的深度
    $new_depth = $parent_id > 0 ? ruiyi_get_category_depth($parent_id) + 1 : 1;

    wp_send_json_success(array(
        'message'   => 'Categoría creada correctamente.',
        'term_id'   => $term_id,
        'depth'     => $new_depth,
        'name'      => $category_name,
        'parent_id' => $parent_id,
    ));
}

// ==========================================
// AJAX Handler 2: 获取分类树
// ==========================================
add_action('wp_ajax_ruiyi_get_category_tree', 'ruiyi_get_category_tree_handler');
add_action('wp_ajax_nopriv_ruiyi_get_category_tree', 'ruiyi_get_category_tree_handler');

function ruiyi_get_category_tree_handler() {
    check_ajax_referer('ruiyi_pos_nonce', 'nonce');

    // 获取完整分类树
    $tree = ruiyi_get_category_tree(0, 1, 3);

    // 获取扁平化列表（用于下拉菜单）
    $flat_list = ruiyi_flatten_category_tree($tree);

    wp_send_json_success(array(
        'tree'      => $tree,
        'flat_list' => $flat_list,
    ));
}

// ==========================================
// AJAX Handler 3: 获取子分类
// ==========================================
add_action('wp_ajax_ruiyi_get_child_categories', 'ruiyi_get_child_categories_handler');
add_action('wp_ajax_nopriv_ruiyi_get_child_categories', 'ruiyi_get_child_categories_handler');

function ruiyi_get_child_categories_handler() {
    check_ajax_referer('ruiyi_pos_nonce', 'nonce');

    $parent_id = isset($_POST['parent_id']) ? intval($_POST['parent_id']) : 0;

    // 排除的分类slug
    $excluded_slugs = array('uncategorized', 'suplementos');

    $args = array(
        'taxonomy'   => 'product_cat',
        'hide_empty' => false,
        'parent'     => $parent_id,
        'orderby'    => 'name',
        'order'      => 'ASC',
    );

    $categories = get_terms($args);

    if (is_wp_error($categories)) {
        wp_send_json_error(array('message' => 'Error al obtener subcategorías.'));
        return;
    }

    $children = array();
    $parent_depth = $parent_id > 0 ? ruiyi_get_category_depth($parent_id) : 0;

    foreach ($categories as $category) {
        // 跳过排除的分类
        if (in_array($category->slug, $excluded_slugs)) {
            continue;
        }

        // 检查是否有子分类
        $child_terms = get_term_children($category->term_id, 'product_cat');
        $has_children = false;
        if (!is_wp_error($child_terms)) {
            foreach ($child_terms as $child_id) {
                $child_term = get_term($child_id, 'product_cat');
                if ($child_term && !in_array($child_term->slug, $excluded_slugs) && $child_term->parent == $category->term_id) {
                    $has_children = true;
                    break;
                }
            }
        }

        // 获取多语言名称
        $name_zh = get_term_meta($category->term_id, 'category_name_zh', true);
        $name_en = get_term_meta($category->term_id, 'category_name_en', true);
        $name_es = get_term_meta($category->term_id, 'category_name_es', true);

        // 获取产品数量
        $product_count = ruiyi_get_category_product_count($category->term_id);

        // 🔥 获取自定义背景颜色
        $bg_color = get_term_meta($category->term_id, '_ruiyi_category_bg_color', true);

        $children[] = array(
            'term_id'       => $category->term_id,
            'name'          => $category->name,
            'slug'          => $category->slug,
            'depth'         => $parent_depth + 1,
            'name_zh'       => $name_zh ?: '',
            'name_en'       => $name_en ?: '',
            'name_es'       => $name_es ?: $category->name,
            'product_count' => $product_count,
            'has_children'  => $has_children,
            'bg_color'      => $bg_color ?: '', // 🔥 自定义背景颜色
            'image_id'      => ruiyi_get_product_category_image_id($category->term_id),
            'image_url'     => ruiyi_get_product_category_image_url($category->term_id, 'thumbnail'),
        );
    }

    wp_send_json_success(array(
        'children'    => $children,
        'parent_id'   => $parent_id,
        'parent_depth'=> $parent_depth,
    ));
}

// ==========================================
// AJAX Handler 4: 获取分类产品（递归，包含所有子孙分类）
// ==========================================
add_action('wp_ajax_ruiyi_get_products_by_category_hierarchical', 'ruiyi_get_products_by_category_hierarchical');
add_action('wp_ajax_nopriv_ruiyi_get_products_by_category_hierarchical', 'ruiyi_get_products_by_category_hierarchical');

function ruiyi_get_products_by_category_hierarchical() {
    check_ajax_referer('ruiyi_pos_nonce', 'nonce');

    $category_id = isset($_POST['category_id']) ? intval($_POST['category_id']) : 0;

    if ($category_id <= 0) {
        wp_send_json_error(array('message' => 'ID de categoría inválido.'));
        return;
    }

    // 获取所有子孙分类ID
    $all_category_ids = ruiyi_get_category_descendants($category_id, true);

    // 查询产品
    $args = array(
        'status'      => 'publish',
        'limit'       => -1,
        'category'    => $all_category_ids,
        'orderby'     => 'name',
        'order'       => 'ASC',
    );

    $products = wc_get_products($args);

    $product_list = array();
    foreach ($products as $product) {
        $product_list[] = array(
            'id'         => $product->get_id(),
            'name'       => $product->get_name(),
            'price'      => $product->get_price(),
            'image'      => wp_get_attachment_url($product->get_image_id()),
            'categories' => wp_get_post_terms($product->get_id(), 'product_cat', array('fields' => 'ids')),
        );
    }

    wp_send_json_success(array(
        'products'     => $product_list,
        'category_ids' => $all_category_ids,
        'total_count'  => count($product_list),
    ));
}

// ==========================================
// AJAX Handler 5: 更新产品分类
// ==========================================
add_action('wp_ajax_ruiyi_update_product_category', 'ruiyi_update_product_category_handler');

function ruiyi_update_product_category_handler() {
    check_ajax_referer('ruiyi_pos_nonce', 'nonce');

    // 验证权限
    if (!current_user_can('manage_woocommerce')) {
        wp_send_json_error(array('message' => 'Sin permisos para editar categorías.'));
        return;
    }

    // 获取参数
    $term_id = isset($_POST['term_id']) ? intval($_POST['term_id']) : 0;
    $category_name = isset($_POST['category_name']) ? sanitize_text_field($_POST['category_name']) : '';
    $parent_id = isset($_POST['parent_id']) ? intval($_POST['parent_id']) : -1; // -1表示不修改
    $name_zh = isset($_POST['name_zh']) ? sanitize_text_field($_POST['name_zh']) : '';
    $name_en = isset($_POST['name_en']) ? sanitize_text_field($_POST['name_en']) : '';
    $name_es = isset($_POST['name_es']) ? sanitize_text_field($_POST['name_es']) : '';
    $sort_order = isset($_POST['sort_order']) ? $_POST['sort_order'] : null; // 排序值
    $bg_color = isset($_POST['bg_color']) ? sanitize_hex_color($_POST['bg_color']) : null; // 🔥 背景颜色
    $image_id = isset($_POST['image_id']) ? absint($_POST['image_id']) : null;

    if ($term_id <= 0) {
        wp_send_json_error(array('message' => 'ID de categoría inválido.'));
        return;
    }

    // 获取现有分类
    $term = get_term($term_id, 'product_cat');
    if (is_wp_error($term) || !$term) {
        wp_send_json_error(array('message' => 'La categoría no existe.'));
        return;
    }

    $update_args = array();

    // 更新名称
    if (!empty($category_name)) {
        $update_args['name'] = $category_name;
    }

    // 更新父分类
    if ($parent_id >= 0 && $parent_id != $term->parent) {
        // 防止循环引用
        if ($parent_id > 0) {
            $ancestors = get_ancestors($parent_id, 'product_cat', 'taxonomy');
            if (in_array($term_id, $ancestors) || $parent_id == $term_id) {
                wp_send_json_error(array('message' => 'No se puede mover una categoría a su propia subcategoría.'));
                return;
            }

            // 验证新深度不超过3层
            $new_parent_depth = ruiyi_get_category_depth($parent_id);
            $current_descendants = ruiyi_get_category_descendants($term_id, false);
            $max_descendant_depth = 0;

            foreach ($current_descendants as $desc_id) {
                $desc_depth = ruiyi_get_category_depth($desc_id);
                $relative_depth = $desc_depth - ruiyi_get_category_depth($term_id);
                if ($relative_depth > $max_descendant_depth) {
                    $max_descendant_depth = $relative_depth;
                }
            }

            if ($new_parent_depth + 1 + $max_descendant_depth > 3) {
                wp_send_json_error(array('message' => 'No se puede mover: superaría el límite de 3 niveles.'));
                return;
            }
        }

        $update_args['parent'] = $parent_id;
    }

    // 执行更新
    if (!empty($update_args)) {
        $result = wp_update_term($term_id, 'product_cat', $update_args);
        if (is_wp_error($result)) {
            wp_send_json_error(array('message' => 'Error al actualizar: ' . $result->get_error_message()));
            return;
        }
    }

    // 更新多语言名称
    update_term_meta($term_id, 'category_name_zh', $name_zh);
    update_term_meta($term_id, 'category_name_en', $name_en);
    update_term_meta($term_id, 'category_name_es', $name_es);

    // 更新排序值（仅一级分类）
    if ($sort_order !== null) {
        if ($sort_order === '' || $sort_order === '0') {
            // 空值或0表示删除排序，使用默认值999
            delete_term_meta($term_id, 'category_sort_order');
        } else {
            update_term_meta($term_id, 'category_sort_order', intval($sort_order));
        }
    }

    // 🔥 更新背景颜色（仅一级分类）
    if ($bg_color !== null) {
        if (empty($bg_color)) {
            // 空值表示使用默认颜色，删除自定义颜色
            delete_term_meta($term_id, '_ruiyi_category_bg_color');
        } else {
            update_term_meta($term_id, '_ruiyi_category_bg_color', $bg_color);
        }
    }

    if ($image_id !== null) {
        if ($image_id > 0) {
            update_term_meta($term_id, 'thumbnail_id', $image_id);
            update_term_meta($term_id, '_ruiyi_category_image_id', $image_id);
        } else {
            delete_term_meta($term_id, 'thumbnail_id');
            delete_term_meta($term_id, '_ruiyi_category_image_id');
        }
    }

    wp_send_json_success(array(
        'message' => 'Categoría actualizada correctamente.',
        'term_id' => $term_id,
    ));
}

// ==========================================
// AJAX Handler 6: 删除产品分类
// ==========================================
add_action('wp_ajax_ruiyi_delete_product_category', 'ruiyi_delete_product_category_handler');

function ruiyi_delete_product_category_handler() {
    check_ajax_referer('ruiyi_pos_nonce', 'nonce');

    // 验证权限
    if (!current_user_can('manage_woocommerce')) {
        wp_send_json_error(array('message' => 'Sin permisos para eliminar categorías.'));
        return;
    }

    // 获取参数
    $term_id = isset($_POST['term_id']) ? intval($_POST['term_id']) : 0;
    $cascade = isset($_POST['cascade']) && $_POST['cascade'] === 'true';

    if ($term_id <= 0) {
        wp_send_json_error(array('message' => 'ID de categoría inválido.'));
        return;
    }

    // 获取现有分类
    $term = get_term($term_id, 'product_cat');
    if (is_wp_error($term) || !$term) {
        wp_send_json_error(array('message' => 'La categoría no existe.'));
        return;
    }

    // 获取子分类
    $children = get_term_children($term_id, 'product_cat');

    if (!is_wp_error($children) && !empty($children)) {
        if ($cascade) {
            // 级联删除：删除所有子分类
            foreach ($children as $child_id) {
                wp_delete_term($child_id, 'product_cat');
            }
        } else {
            // 提升子分类：将子分类移至父分类
            $new_parent = $term->parent;
            foreach ($children as $child_id) {
                $child_term = get_term($child_id, 'product_cat');
                if ($child_term && $child_term->parent == $term_id) {
                    wp_update_term($child_id, 'product_cat', array('parent' => $new_parent));
                }
            }
        }
    }

    // 删除分类
    $result = wp_delete_term($term_id, 'product_cat');

    if (is_wp_error($result)) {
        wp_send_json_error(array('message' => 'Error al eliminar: ' . $result->get_error_message()));
        return;
    }

    wp_send_json_success(array(
        'message' => 'Categoría eliminada correctamente.',
        'term_id' => $term_id,
        'cascade' => $cascade,
    ));
}

// ========== 发票开票功能 ==========

/**
 * 搜索发票客户
 */
add_action('wp_ajax_ruiyi_search_invoice_customer', 'ruiyi_search_invoice_customer');
function ruiyi_search_invoice_customer() {
    // 验证nonce
    if (!check_ajax_referer('ruiyi_pos_nonce', 'nonce', false)) {
        wp_send_json_error(['message' => '安全验证失败']);
        return;
    }

    $phone = isset($_POST['phone']) ? sanitize_text_field($_POST['phone']) : '';

    if (empty($phone)) {
        wp_send_json_error(['message' => '请输入电话号码']);
        return;
    }

    // 从数据库中查找客户（使用WordPress用户meta或自定义表）
    // 首先尝试在订单中查找匹配的客户信息
    global $wpdb;

    // 查找包含该电话号码的订单
    $order_id = $wpdb->get_var($wpdb->prepare(
        "SELECT post_id FROM {$wpdb->postmeta}
         WHERE meta_key = '_billing_phone' AND meta_value = %s
         ORDER BY post_id DESC LIMIT 1",
        $phone
    ));

    if ($order_id) {
        // 获取订单的客户信息
        $order = wc_get_order($order_id);
        if ($order) {
            $customer_data = [
                'name' => $order->get_billing_first_name() . ' ' . $order->get_billing_last_name(),
                'phone' => $order->get_billing_phone(),
                'company_name' => $order->get_billing_company(),
                'tax_id' => get_post_meta($order_id, '_billing_tax_id', true) ?: get_post_meta($order_id, '_billing_nif', true),
                'address' => trim($order->get_billing_address_1() . ' ' . $order->get_billing_address_2() . ', ' . $order->get_billing_city()),
            ];

            wp_send_json_success($customer_data);
            return;
        }
    }

    // 如果在订单中找不到，尝试在自定义客户表中查找
    $customer_table = $wpdb->prefix . 'ruiyi_invoice_customers';
    $table_exists = $wpdb->get_var("SHOW TABLES LIKE '$customer_table'") === $customer_table;

    if ($table_exists) {
        $customer = $wpdb->get_row($wpdb->prepare(
            "SELECT * FROM $customer_table WHERE phone = %s ORDER BY id DESC LIMIT 1",
            $phone
        ), ARRAY_A);

        if ($customer) {
            wp_send_json_success($customer);
            return;
        }
    }

    wp_send_json_error(['message' => '未找到客户']);
}

/**
 * 打印发票
 */
add_action('wp_ajax_ruiyi_print_invoice', 'ruiyi_print_invoice');
function ruiyi_print_invoice() {
    // 验证nonce
    if (!check_ajax_referer('ruiyi_pos_nonce', 'nonce', false)) {
        wp_send_json_error(['message' => '安全验证失败']);
        return;
    }

    $order_id = isset($_POST['order_id']) ? intval($_POST['order_id']) : 0;
    $customer_name = isset($_POST['customer_name']) ? sanitize_text_field($_POST['customer_name']) : '';
    $customer_phone = isset($_POST['customer_phone']) ? sanitize_text_field($_POST['customer_phone']) : '';
    $company_name = isset($_POST['company_name']) ? sanitize_text_field($_POST['company_name']) : '';
    $tax_id = isset($_POST['tax_id']) ? sanitize_text_field($_POST['tax_id']) : '';
    $address = isset($_POST['address']) ? sanitize_textarea_field($_POST['address']) : '';
    $notes = isset($_POST['notes']) ? sanitize_textarea_field($_POST['notes']) : '';

    if (!$order_id) {
        wp_send_json_error(['message' => '无效的订单ID']);
        return;
    }

    $order = wc_get_order($order_id);
    if (!$order) {
        wp_send_json_error(['message' => '未找到订单']);
        return;
    }

    // 保存客户信息到自定义表和客户管理（如果有电话号码）
    $saved_customer_id = 0;
    if (!empty($customer_phone)) {
        $saved_customer_id = intval(ruiyi_save_invoice_customer($customer_name, $customer_phone, $company_name, $tax_id, $address));
    }

    // 更新订单的发票信息
    update_post_meta($order_id, '_invoice_customer_name', $customer_name);
    update_post_meta($order_id, '_invoice_customer_phone', $customer_phone);
    update_post_meta($order_id, '_invoice_company_name', $company_name);
    update_post_meta($order_id, '_invoice_tax_id', $tax_id);
    update_post_meta($order_id, '_invoice_address', $address);
    update_post_meta($order_id, '_invoice_notes', $notes);
    update_post_meta($order_id, '_invoice_printed', 'yes');
    update_post_meta($order_id, '_invoice_printed_date', current_time('mysql'));

    // 同步一份到订单客户meta，后续重印/预结单也能读取到同一套客户信息。
    update_post_meta($order_id, '_customer_name', $customer_name);
    update_post_meta($order_id, '_customer_phone', $customer_phone);
    update_post_meta($order_id, '_customer_business_name', $company_name);
    update_post_meta($order_id, '_customer_cif_nif', $tax_id);
    update_post_meta($order_id, '_customer_address', $address);
    update_post_meta($order_id, '_customer_notes', $notes);
    if ($saved_customer_id > 0) {
        update_post_meta($order_id, '_customer_id', $saved_customer_id);
    }

    // 生成发票HTML
    $receipt_html = ruiyi_generate_invoice_html($order, [
        'customer_name' => $customer_name,
        'customer_phone' => $customer_phone,
        'company_name' => $company_name,
        'tax_id' => $tax_id,
        'address' => $address,
        'notes' => $notes
    ]);

    wp_send_json_success([
        'receipt_html' => $receipt_html,
        'order_id' => $order_id,
        'customer_id' => $saved_customer_id
    ]);
}

// 🔥 PDF发票生成 - 通过verifactu插件生成PDF并返回base64
add_action('wp_ajax_ruiyi_generate_pdf_invoice', 'ruiyi_generate_pdf_invoice');
function ruiyi_generate_pdf_invoice() {
    // 验证nonce
    if (!check_ajax_referer('ruiyi_pos_nonce', 'nonce', false)) {
        wp_send_json_error(['message' => '安全验证失败']);
        return;
    }

    $order_id = isset($_POST['order_id']) ? intval($_POST['order_id']) : 0;
    $customer_name = isset($_POST['customer_name']) ? sanitize_text_field($_POST['customer_name']) : '';
    $company_name = isset($_POST['company_name']) ? sanitize_text_field($_POST['company_name']) : '';
    $address = isset($_POST['address']) ? sanitize_text_field($_POST['address']) : '';
    $city = isset($_POST['city']) ? sanitize_text_field($_POST['city']) : '';
    $state = isset($_POST['state']) ? sanitize_text_field($_POST['state']) : '';
    $postcode = isset($_POST['postcode']) ? sanitize_text_field($_POST['postcode']) : '';
    $tax_id = isset($_POST['tax_id']) ? sanitize_text_field($_POST['tax_id']) : '';
    $notes = isset($_POST['notes']) ? sanitize_textarea_field($_POST['notes']) : '';

    if (!$order_id) {
        wp_send_json_error(['message' => '无效的订单ID']);
        return;
    }

    $order = wc_get_order($order_id);
    if (!$order) {
        wp_send_json_error(['message' => '未找到订单']);
        return;
    }

    // 检查verifactu插件是否可用
    if (!ruiyi_has_verifactu()) {
        wp_send_json_error(['message' => 'Verifactu插件未安装或未启用']);
        return;
    }

    try {
        // 设置客户信息到订单对象并保存（verifactu插件需要从数据库读取）
        $order->set_billing_first_name($customer_name);
        $order->set_billing_last_name('');
        $order->set_billing_company($company_name);
        $order->set_billing_address_1($address);
        $order->set_billing_city($city);
        $order->set_billing_state($state);
        $order->set_billing_postcode($postcode);
        $order->set_billing_country('ES');
        // 清除邮箱，避免在PDF发票中显示
        $order->set_billing_email('');
        if (!empty($tax_id)) {
            $order->update_meta_data('_billing_cif', $tax_id);
            $order->update_meta_data('_billing_nif', $tax_id);
            $order->update_meta_data('_billing_vat', $tax_id);
        }
        // 清除关联客户ID，强制使用手动输入的客户信息
        $order->update_meta_data('_verifactu_customer_id', '');
        // 保存备注到订单（verifactu插件会读取customer_note显示在PDF底部）
        if (!empty($notes)) {
            $order->set_customer_note($notes);
            $order->update_meta_data('_invoice_notes', $notes);
        }
        $order->save();

        // 重新加载订单确保数据一致
        $order = wc_get_order($order_id);
        ruiyi_debug_log("[PDF发票] 客户信息已保存. 账单名: " . $order->get_formatted_billing_full_name());

        // 删除旧PDF缓存，强制重新生成
        $old_pdf_path = $order->get_meta('_verifactu_invoice_pdf');
        if ($old_pdf_path && file_exists($old_pdf_path)) {
            @unlink($old_pdf_path);
            $order->delete_meta_data('_verifactu_invoice_pdf');
            $order->save();
        }

        // 获取QR码数据
        $qr_base64 = $order->get_meta('_verifactu_qr_base64');
        $qr_bytes = '';
        if ($qr_base64) {
            $qr_bytes = base64_decode($qr_base64, true);
            if ($qr_bytes === false) {
                $qr_bytes = '';
            }
            ruiyi_debug_log("[PDF发票] QR码已找到");
        } else {
            ruiyi_debug_log("[PDF发票] 未找到QR码, 将生成不含QR的PDF");
        }

        // 通过缓存的反射方法生成PDF
        $verifactu = ruiyi_get_verifactu_instance();
        if (!$verifactu) {
            wp_send_json_error(['message' => 'Verifactu实例获取失败']);
            return;
        }
        ruiyi_debug_log("[PDF发票] Verifactu实例获取成功, 开始生成PDF...");

        $pdf_method = ruiyi_get_verifactu_method('generate_pdf_with_qr');
        if (!$pdf_method) {
            wp_send_json_error(['message' => 'generate_pdf_with_qr方法不可用']);
            return;
        }
        $pdf = $pdf_method->invoke($verifactu, $order, $qr_bytes);

        ruiyi_debug_log("[PDF发票] PDF生成结果 - 字节长度: " . (is_string($pdf) ? strlen($pdf) : 'null/false'));

        if (!$pdf || (is_string($pdf) && strlen($pdf) < 100)) {
            wp_send_json_error(['message' => 'PDF生成失败，返回为空或内容过短']);
            return;
        }

        // 验证PDF格式
        if (substr($pdf, 0, 4) !== '%PDF') {
            ruiyi_debug_log("[PDF发票] 错误: 生成的内容不是有效的PDF!");
            wp_send_json_error(['message' => '生成的内容不是有效的PDF格式']);
            return;
        }

        // 生成文件名（使用发票标签）
        $invoice_label = $order->get_meta('_verifactu_invoice_label');
        if (!$invoice_label) {
            try {
                $label_method = $reflection->getMethod('get_invoice_label');
                $label_method->setAccessible(true);
                $invoice_label = $label_method->invoke($verifactu, $order);
            } catch (\Throwable $e) {
                $invoice_label = '';
            }
        }
        if (!$invoice_label) {
            $invoice_label = 'factura-' . $order->get_order_number();
        }
        $filename = strtolower($invoice_label) . '.pdf';

        wp_send_json_success([
            'pdf_base64' => base64_encode($pdf),
            'filename' => $filename,
            'order_id' => $order_id
        ]);

    } catch (\Throwable $e) {
        ruiyi_debug_log("[PDF发票] 生成失败: " . $e->getMessage() . " | File: " . $e->getFile() . ":" . $e->getLine());
        wp_send_json_error(['message' => 'PDF生成失败: ' . $e->getMessage()]);
    }
}

/**
 * 保存发票客户信息
 */
function ruiyi_save_invoice_customer($name, $phone, $company_name, $tax_id, $address) {
    global $wpdb;
    $table_name = $wpdb->prefix . 'ruiyi_invoice_customers';

    $name = sanitize_text_field($name);
    $phone = sanitize_text_field($phone);
    $company_name = sanitize_text_field($company_name);
    $tax_id = sanitize_text_field($tax_id);
    $address = sanitize_textarea_field($address);

    if (empty($phone)) {
        ruiyi_debug_log('[发票客户] 跳过客户管理同步：电话为空');
        return 0;
    }

    // 确保表存在
    ruiyi_create_invoice_customers_table();

    // 保存到发票客户表
    $existing = $wpdb->get_var($wpdb->prepare(
        "SELECT id FROM $table_name WHERE phone = %s",
        $phone
    ));

    if ($existing) {
        $wpdb->update(
            $table_name,
            [
                'name' => $name,
                'company_name' => $company_name,
                'tax_id' => $tax_id,
                'address' => $address,
                'updated_at' => current_time('mysql')
            ],
            ['phone' => $phone],
            ['%s', '%s', '%s', '%s', '%s'],
            ['%s']
        );
    } else {
        $wpdb->insert(
            $table_name,
            [
                'name' => $name,
                'phone' => $phone,
                'company_name' => $company_name,
                'tax_id' => $tax_id,
                'address' => $address,
                'created_at' => current_time('mysql'),
                'updated_at' => current_time('mysql')
            ],
            ['%s', '%s', '%s', '%s', '%s', '%s', '%s']
        );
    }

    // 🔥 同步到 ruiyi_customer 自定义文章类型（与设置中的客户管理挂钩）
    $existing_customer = $wpdb->get_var($wpdb->prepare(
        "SELECT pm.post_id FROM {$wpdb->postmeta} pm
         INNER JOIN {$wpdb->posts} p ON pm.post_id = p.ID
         WHERE pm.meta_key = '_customer_phone' AND pm.meta_value = %s
         AND p.post_type = 'ruiyi_customer' AND p.post_status = 'publish'
         LIMIT 1",
        $phone
    ));

    if ($existing_customer) {
        // 更新已有客户
        $customer_id = intval($existing_customer);
        wp_update_post(['ID' => $customer_id, 'post_title' => $name ?: $phone]);
        update_post_meta($customer_id, '_customer_phone', $phone);
        update_post_meta($customer_id, '_customer_business_name', $company_name);
        update_post_meta($customer_id, '_customer_cif_nif', $tax_id);
        update_post_meta($customer_id, '_customer_address', $address);
        update_post_meta($customer_id, '_customer_last_order_date', current_time('mysql'));
        ruiyi_debug_log('[发票客户] ✅ 已更新客户管理客户 ID: ' . $customer_id . ' 电话: ' . $phone);
        return $customer_id;
    } else {
        // 创建新客户
        $customer_id = wp_insert_post([
            'post_title' => $name ?: $phone,
            'post_type' => 'ruiyi_customer',
            'post_status' => 'publish',
            'post_author' => get_current_user_id()
        ]);
        if ($customer_id && !is_wp_error($customer_id)) {
            update_post_meta($customer_id, '_customer_phone', $phone);
            update_post_meta($customer_id, '_customer_business_name', $company_name);
            update_post_meta($customer_id, '_customer_cif_nif', $tax_id);
            update_post_meta($customer_id, '_customer_address', $address);
            update_post_meta($customer_id, '_customer_order_count', 0);
            update_post_meta($customer_id, '_customer_total_spent', 0);
            update_post_meta($customer_id, '_customer_first_order_date', current_time('mysql'));
            update_post_meta($customer_id, '_customer_last_order_date', current_time('mysql'));
            ruiyi_debug_log('[发票客户] ✅ 已创建客户管理客户 ID: ' . $customer_id . ' 电话: ' . $phone);
            return intval($customer_id);
        }
    }

    ruiyi_debug_log('[发票客户] ❌ 客户管理同步失败 电话: ' . $phone);
    return 0;
}

/**
 * 创建发票客户表
 */
function ruiyi_create_invoice_customers_table() {
    global $wpdb;
    $table_name = $wpdb->prefix . 'ruiyi_invoice_customers';
    $charset_collate = $wpdb->get_charset_collate();

    // 检查表是否已存在
    if ($wpdb->get_var("SHOW TABLES LIKE '$table_name'") === $table_name) {
        return;
    }

    $sql = "CREATE TABLE $table_name (
        id bigint(20) NOT NULL AUTO_INCREMENT,
        name varchar(255) NOT NULL DEFAULT '',
        phone varchar(50) NOT NULL,
        company_name varchar(255) DEFAULT '',
        tax_id varchar(50) DEFAULT '',
        address text,
        created_at datetime DEFAULT CURRENT_TIMESTAMP,
        updated_at datetime DEFAULT CURRENT_TIMESTAMP,
        PRIMARY KEY (id),
        KEY phone (phone)
    ) $charset_collate;";

    require_once(ABSPATH . 'wp-admin/includes/upgrade.php');
    dbDelta($sql);
}

/**
 * 生成发票HTML - 使用CLodop兼容格式
 * 必须使用特定的CSS类名以便CLodop解析器正确解析
 */
function ruiyi_generate_invoice_html($order, $customer_info) {
    // 获取店铺设置 - 使用与历史订单打印相同的option keys
    $store_name = get_option('pos_store_name', get_bloginfo('name'));
    $store_business_name = get_option('pos_store_business_name', '');
    $store_cif_nif = get_option('pos_store_cif_nif', '');
    $store_address = get_option('pos_store_address', '');
    $store_phone = get_option('pos_store_phone', '');
    $receipt_logo = get_option('pos_receipt_logo', ''); // 🔥 获取小票Logo
    $receipt_header_alignment = get_option('pos_receipt_header_alignment', 'left');
    $receipt_store_name_font_size = get_option('pos_receipt_store_name_font_size', '18');
    $receipt_bilingual = get_option('pos_receipt_bilingual', '0') === '1';

    // 订单信息
    $order_id = $order->get_id();
    $order_total = $order->get_total();

    // 获取桌位信息
    $table_number = $order->get_meta('_table_number');
    $order_type = $order->get_meta('_order_type') ?: 'llevar';

    // 获取桌位分区显示名称
    $table_display_name = '';
    if ($order_type !== 'llevar' && !empty($table_number)) {
        $table_display_name = 'Mesa ' . $table_number; // 默认值
        $table_number_numeric = intval(preg_replace('/[^0-9]/', '', $table_number));

        if (function_exists('ruiyi_get_all_table_categories_mapping')) {
            $all_mappings = ruiyi_get_all_table_categories_mapping();
            if ($all_mappings && is_array($all_mappings)) {
                foreach ($all_mappings as $mapping) {
                    if (isset($mapping['global_table_number']) &&
                        intval($mapping['global_table_number']) === $table_number_numeric) {
                        $table_display_name = $mapping['category_display_name'] ?:
                                              ($mapping['display_name'] ?: ('Mesa ' . $table_number));
                        break;
                    }
                }
            }
        }
    }

    // 格式化订单日期
    $timezone = wp_timezone();
    $order_date_obj = $order->get_date_created();
    if ($order_date_obj) {
        $order_date_clone = clone $order_date_obj;
        $order_date_clone->setTimezone($timezone);
        $formatted_date = $order_date_clone->format('d-m-Y H:i');
    } else {
        $formatted_date = date('d-m-Y H:i');
    }

    // 客户信息
    $customer_name = $customer_info['customer_name'] ?? '';
    $customer_phone = $customer_info['customer_phone'] ?? '';
    $company_name = $customer_info['company_name'] ?? '';
    $tax_id = $customer_info['tax_id'] ?? '';
    $address = $customer_info['address'] ?? '';
    $notes = $customer_info['notes'] ?? '';

    // 🔥 发票号 - 小票显示统一为年份 + 7位订单序号，例如 20260000381
    $invoice_number = ruiyi_get_receipt_invoice_number($order);

    // 计算税费信息
    $tax_groups = array();
    $total_before_tax = 0;
    $total_tax = 0;

    foreach ($order->get_items() as $item) {
        $product = $item->get_product();
        $item_total = floatval($item->get_total());
        $tax_rate = $receipt_tax_rate;

        // 计算税前价格和税额
        $item_base = $item_total / (1 + $tax_rate / 100);
        $item_tax = $item_total - $item_base;

        $total_before_tax += $item_base;
        $total_tax += $item_tax;

        // 按税率分组
        $tax_key = number_format($tax_rate, 0);
        if (!isset($tax_groups[$tax_key])) {
            $tax_groups[$tax_key] = array('rate' => $tax_rate, 'base' => 0, 'tax' => 0);
        }
        $tax_groups[$tax_key]['base'] += $item_base;
        $tax_groups[$tax_key]['tax'] += $item_tax;
    }

    // 🔥 获取折扣信息（多种方式尝试）
    $discount_percent = 0;
    $discount_amount = 0;
    $cheque_restaurante_amount = 0;

    ruiyi_debug_log("[开票] ========== 开始获取折扣信息 - 订单ID: {$order_id} ==========");

    // 方法1: 从元数据获取
    $meta_discount_percent = $order->get_meta('_manual_discount_percent');
    $meta_discount_amount = $order->get_meta('_manual_discount_amount');
    ruiyi_debug_log("[开票] 元数据检查 - _manual_discount_percent: " . var_export($meta_discount_percent, true));
    ruiyi_debug_log("[开票] 元数据检查 - _manual_discount_amount: " . var_export($meta_discount_amount, true));

    if (!empty($meta_discount_percent) && floatval($meta_discount_percent) > 0) {
        $discount_percent = floatval($meta_discount_percent);
        $discount_amount = !empty($meta_discount_amount) ? floatval($meta_discount_amount) : 0;
        ruiyi_debug_log("[开票] ✅ 从元数据获取折扣: {$discount_percent}%, €{$discount_amount}");
    }

    // 方法2: 从费用项获取（无论元数据是否有值都检查）
    $all_fees = $order->get_fees();
    ruiyi_debug_log("[开票] 费用项数量: " . count($all_fees));

    foreach ($all_fees as $fee_id => $fee) {
        $fee_total = floatval($fee->get_total());
        $fee_name = $fee->get_name();
        ruiyi_debug_log("[开票] 费用项详情 - ID: {$fee_id}, 名称: '{$fee_name}', 金额: {$fee_total}");

        // 检查是否为折扣费用
        if ($fee_total < 0) {
            if (stripos($fee_name, 'DESCUENTO') !== false) {
                if ($discount_amount == 0) {
                    $discount_amount = abs($fee_total);
                    if (preg_match('/\((\d+(?:\.\d+)?)\s*%?\)/', $fee_name, $matches)) {
                        $discount_percent = floatval($matches[1]);
                    }
                    ruiyi_debug_log("[开票] ✅ 从费用项获取折扣: {$discount_percent}%, €{$discount_amount}");
                }
            } elseif (stripos($fee_name, 'Cheque') !== false) {
                $cheque_restaurante_amount = abs($fee_total);
                ruiyi_debug_log("[开票] ✅ 从费用项获取Cheque: €{$cheque_restaurante_amount}");
            } elseif ($discount_amount == 0 && $cheque_restaurante_amount == 0) {
                // 其他负数费用视为折扣
                $discount_amount = abs($fee_total);
                ruiyi_debug_log("[开票] ✅ 从未知负数费用项获取折扣: €{$discount_amount}");
            }
        }
    }

    // 方法3: 检查Cheque Restaurante元数据
    if ($cheque_restaurante_amount == 0) {
        $meta_cheque = $order->get_meta('_cheque_restaurante_amount');
        ruiyi_debug_log("[开票] 检查元数据 _cheque_restaurante_amount: " . ($meta_cheque ?: '空'));
        if (!empty($meta_cheque) && floatval($meta_cheque) > 0) {
            $cheque_restaurante_amount = floatval($meta_cheque);
            ruiyi_debug_log("[开票] ✅ 从元数据获取Cheque: €{$cheque_restaurante_amount}");
        } else {
            ruiyi_debug_log("[开票] ❌ 元数据中无 Cheque Restaurante");
        }
    }

    ruiyi_debug_log("[开票] ========== 最终结果 - 折扣: {$discount_percent}% (€{$discount_amount}), Cheque: €{$cheque_restaurante_amount} ==========");

    // 🔥 生成CLodop兼容格式的HTML
    ob_start();
    ?>
    <!DOCTYPE html>
    <html>
    <head>
        <meta charset="utf-8">
        <title>Factura #<?php echo esc_html($order_id); ?></title>
        <style>
            body { font-family: Arial, sans-serif; width: 72mm; margin: 0 auto; padding: 5mm 4mm; box-sizing: border-box; font-size: 10pt; }
            .receipt { width: 100%; max-width: 72mm; }
            h2 { font-size: <?php echo intval($receipt_store_name_font_size); ?>pt; font-weight: bold; text-align: <?php echo esc_attr($receipt_header_alignment); ?>; margin: 0 0 1mm 0; line-height: 1.15; }
            .store-info { text-align: <?php echo esc_attr($receipt_header_alignment); ?>; }
            .store-info .business-name { font-size: 0.9em; margin-bottom: 0; }
            .store-info .cif-nif { font-size: 0.85em; margin-bottom: 0; }
            .store-info .phone { font-size: 0.85em; margin-bottom: 0; }
            .store-info .address { font-size: 0.85em; margin-bottom: 0; margin-top: 0.5mm; line-height: 1.3; }
