            <!-- 总计表格 - 使用.totals-table类供CLodop解析 -->
            <table class="totals-table">
                <tr>
                    <td>Base Imponible:</td>
                    <td style="text-align: right;"><?php echo number_format($total_before_tax, 2); ?>€</td>
