                    <td style="text-align:left;">DESCUENTO (<span class="discount-percent"><?php echo number_format($discount_percent, 0); ?></span>%):</td>
                    <td style="text-align: right;" class="discount-amount">-€<?php echo number_format($discount_amount, 2); ?></td>
                </tr>
