                <?php // 🔥 显示Cheque Restaurante?>
                <?php if ($cheque_restaurante_amount > 0): ?>
                <tr style="color: #e65100;">
                    <td>Cheque Restaurante:</td>
                    <td style="text-align: right;">-€<?php echo number_format($cheque_restaurante_amount, 2); ?></td>
                </tr>
                <?php endif; ?>

                <tr class="total-row">
                    <td>TOTAL:</td>
                    <td style="text-align: right;"><?php echo number_format($order_total, 2); ?>€</td>
