            <div class="notes-section">
                <strong><?php echo ruiyi_translate('Notas:', 'Notes:', '备注:'); ?></strong> <?php echo esc_html($notes); ?>
            </div>
            <?php endif; ?>

            <?php
            // 🔥 Verifactu QR码 - 直接从订单meta获取已保存的QR码（与历史订单打印一致）
            $qr_base64 = $order->get_meta('_verifactu_qr_base64');
            if (!empty($qr_base64)) :
                // 将base64转换为data URI格式
                if (strpos($qr_base64, 'data:image') === 0) {
                    $qr_data_uri = $qr_base64;
                } else {
                    $qr_data_uri = 'data:image/png;base64,' . $qr_base64;
                }
            ?>
            <hr>
            <div class="qr-container">
                <img src="<?php echo esc_attr($qr_data_uri); ?>" alt="Verifactu QR">
                <div style="font-size: 0.7em; margin-top: 1mm;">Código Verifactu</div>
            </div>
            <?php endif; ?>

            <hr>

            <!-- 页脚 -->
            <div class="footer">
                <div><?php echo ruiyi_translate('Gracias por su compra', 'Thank you for your purchase', '感谢您的惠顾'); ?></div>
                <div style="margin-top:5px;"><?php echo ruiyi_translate('Conserve este documento como comprobante', 'Keep this document as proof of purchase', '请保留此单据作为凭证'); ?></div>
            </div>
        </div>
    </body>
    </html>
    <?php
    return ob_get_clean();
}

/**
 * ==================================
 * 🔥 作废订单功能
 * ==================================
 */
add_action('wp_ajax_ruiyi_void_order', 'ruiyi_void_order_handler');
add_action('wp_ajax_nopriv_ruiyi_void_order', 'ruiyi_void_order_handler');

function ruiyi_void_order_handler() {
    if (!is_user_logged_in()) {
        wp_send_json_error(['message' => 'Authentication required']);
        return;
    }

    // 验证nonce
    if (!check_ajax_referer('ruiyi_pos_nonce', 'nonce', false)) {
        wp_send_json_error(['message' => ruiyi_translate('Error de seguridad', 'Security error', '安全验证失败')]);
        return;
    }

    $order_id = isset($_POST['order_id']) ? intval($_POST['order_id']) : 0;

    if (!$order_id) {
        wp_send_json_error(['message' => ruiyi_translate('ID de pedido inválido', 'Invalid order ID', '无效的订单ID')]);
        return;
    }

    // 获取订单
    $order = wc_get_order($order_id);
    if (!$order) {
        wp_send_json_error(['message' => ruiyi_translate('Pedido no encontrado', 'Order not found', '订单未找到')]);
        return;
    }

    // 检查订单状态是否为已完成
    $current_status = $order->get_status();
    if ($current_status !== 'completed') {
        wp_send_json_error(['message' => ruiyi_translate('Solo se pueden anular pedidos completados', 'Only completed orders can be voided', '只能作废已完成的订单')]);
        return;
    }

    // 获取订单金额和支付方式，用于更新日结单
    $order_total = floatval($order->get_total());
    $payment_method = $order->get_payment_method();

    // 🔥 更新日结单数据 - 减去作废订单的金额
    $daily_data_key = 'ruiyi_daily_summary_current';
    $daily_data = get_option($daily_data_key, [
        'start_date' => current_time('Y-m-d'),
        'total_amount' => 0,
        'card_amount' => 0,
        'cash_amount' => 0,
        'company_ticket_amount' => 0,
        'mixed_payment_count' => 0,
        'products' => [],
        'transactions' => [],
        'last_updated' => current_time('mysql')
    ]);

    // 减去总金额
    $daily_data['total_amount'] = max(0, floatval($daily_data['total_amount']) - $order_total);

    // 🔥 获取更详细的支付方式信息
    $payment_method_detail = $order->get_meta('_payment_method_detail');
    $cash_amount_meta = floatval($order->get_meta('_cash_amount'));
    $card_amount_meta = floatval($order->get_meta('_card_amount'));

    // 记录调试日志
    ruiyi_debug_log(sprintf(
        '[作废订单] 订单 #%d 支付信息 - payment_method: %s, payment_method_detail: %s, cash_meta: %.2f, card_meta: %.2f',
        $order_id, $payment_method, $payment_method_detail, $cash_amount_meta, $card_amount_meta
    ));

    // 根据支付方式减去相应金额
    // 🔥 优先使用 _payment_method_detail 元数据判断，因为订单创建时刷卡使用的是 bacs
    if ($payment_method_detail === 'mixed' && ($cash_amount_meta > 0 || $card_amount_meta > 0)) {
        // 混合支付：分别减去现金和刷卡金额
        if ($cash_amount_meta > 0) {
            $daily_data['cash_amount'] = max(0, floatval($daily_data['cash_amount']) - $cash_amount_meta);
        }
        if ($card_amount_meta > 0) {
            $daily_data['card_amount'] = max(0, floatval($daily_data['card_amount']) - $card_amount_meta);
        }
    } elseif ($payment_method_detail === 'card' || $payment_method === 'bacs' || $payment_method === 'card' || $payment_method === 'pos_tarjeta' || $payment_method === 'tarjeta') {
        // 刷卡支付
        $daily_data['card_amount'] = max(0, floatval($daily_data['card_amount']) - $order_total);
    } elseif ($payment_method === 'cash' || $payment_method === 'pos_efectivo' || $payment_method === 'efectivo' || $payment_method === 'cod') {
        // 现金支付
        $daily_data['cash_amount'] = max(0, floatval($daily_data['cash_amount']) - $order_total);
    } elseif ($payment_method === 'company_ticket' || $payment_method === 'pos_company_ticket') {
        // 公司票支付
        $daily_data['company_ticket_amount'] = max(0, floatval($daily_data['company_ticket_amount']) - $order_total);
    }

    // 🔥 从日结单交易记录中移除该订单
    if (isset($daily_data['transactions']) && is_array($daily_data['transactions'])) {
        $daily_data['transactions'] = array_filter($daily_data['transactions'], function($transaction) use ($order_id) {
            return (!isset($transaction['order_id']) || intval($transaction['order_id']) !== $order_id);
        });
        $daily_data['transactions'] = array_values($daily_data['transactions']); // 重新索引
    }

    // 🔥 从日结单产品统计中减去该订单的产品
    foreach ($order->get_items() as $item) {
        $product_id = $item->get_product_id();
        $product_name = $item->get_name();
        $quantity = $item->get_quantity();
        $item_total = floatval($item->get_total());

        // 使用产品ID作为key
        $product_key = 'pid_' . $product_id;

        if (isset($daily_data['products'][$product_key])) {
            $daily_data['products'][$product_key]['quantity'] = max(0, $daily_data['products'][$product_key]['quantity'] - $quantity);
            $daily_data['products'][$product_key]['total'] = max(0, $daily_data['products'][$product_key]['total'] - $item_total);

            // 如果数量变为0，移除该产品
            if ($daily_data['products'][$product_key]['quantity'] <= 0) {
                unset($daily_data['products'][$product_key]);
            }
        }
    }

    // 更新日结单
    $daily_data['last_updated'] = current_time('mysql');
    update_option($daily_data_key, $daily_data);

    // 🔥 将订单状态改为取消
    $order->update_status('cancelled', ruiyi_translate('Pedido anulado desde POS', 'Order voided from POS', '从POS系统作废订单'));

    // 记录日志
    ruiyi_debug_log(sprintf(
        '[作废订单] 订单 #%d 已作废 - 金额: €%.2f, 支付方式: %s, 日结单已更新',
        $order_id,
        $order_total,
        $payment_method
    ));

    wp_send_json_success([
        'message' => ruiyi_translate('Pedido anulado correctamente', 'Order voided successfully', '订单已成功作废'),
        'order_id' => $order_id,
        'voided_amount' => $order_total,
        'payment_method' => $payment_method
    ]);
}

// =============================================
// 🔥 POS产品分页加载API
// =============================================
add_action('wp_ajax_ruiyi_pos_get_products_paginated', 'ruiyi_pos_get_products_paginated');
add_action('wp_ajax_nopriv_ruiyi_pos_get_products_paginated', 'ruiyi_pos_get_products_paginated');

function ruiyi_pos_get_products_paginated() {
    // 验证nonce
    if (!isset($_GET['nonce']) || !wp_verify_nonce($_GET['nonce'], 'ruiyi_pos_nonce')) {
        wp_send_json_error(['message' => 'Invalid nonce'], 403);
    }

    // 分页参数
    $page = max(1, intval($_GET['page'] ?? 1));
    $per_page = max(10, min(100, intval($_GET['per_page'] ?? 30)));
    $category = sanitize_text_field($_GET['category'] ?? '');
    $search = sanitize_text_field($_GET['search'] ?? '');
    $offset = ($page - 1) * $per_page;

    // 使用 WP_Query 以保持与PHP渲染相同的排序
    $args = array(
        'post_type' => 'product',
        'posts_per_page' => $per_page,
        'offset' => $offset,
        'post_status' => 'publish',
        'meta_key' => '_ruiyi_product_sort_order',
        'orderby' => 'meta_value_num',
        'order' => 'ASC'
    );

    // 分类过滤
    if (!empty($category) && $category !== 'all') {
        $args['tax_query'] = array(
            array(
                'taxonomy' => 'product_cat',
                'field' => 'slug',
                'terms' => $category
            )
        );
    }

    // 搜索过滤
    if (!empty($search)) {
        $args['s'] = $search;
    }

    // 获取总数
    $count_args = $args;
    $count_args['posts_per_page'] = -1;
    $count_args['fields'] = 'ids';
    unset($count_args['offset']);
    $total = count(get_posts($count_args));
    $total_pages = ceil($total / $per_page);

    // 获取产品
    $query = new WP_Query($args);
    $current_lang = defined('RUIYI_CURRENT_LANG') ? RUIYI_CURRENT_LANG : 'zh';

    // 格式化产品数据
    $products_data = [];
    if ($query->have_posts()) {
        while ($query->have_posts()) {
            $query->the_post();
            $product_id = get_the_ID();
            $product = wc_get_product($product_id);

            if (!$product) continue;

            // 跳过价格为负数的产品
            $product_price = floatval($product->get_price());
            if ($product_price < 0) continue;

            // 获取图片
            $image_id = $product->get_image_id();
            $image_url = $image_id ? wp_get_attachment_image_url($image_id, 'medium') : '';
            $has_real_image = !empty($image_url) && strpos($image_url, 'placeholder') === false;

            // 获取税率
            $tax_rate = function_exists('ruiyi_get_product_tax_rate') ? ruiyi_get_product_tax_rate($product) : 10;

            // 获取分类ID
            $terms = get_the_terms($product_id, 'product_cat');
            $category_ids = [];
            if ($terms && !is_wp_error($terms)) {
                foreach ($terms as $term) {
                    $category_ids[] = $term->term_id;
                }
            }

            // 获取多语言名称
            $name_es = $product->get_name();
            $name_zh = get_post_meta($product_id, '_product_name_zh', true) ?: '';
            $name_en = get_post_meta($product_id, '_product_name_en', true) ?: '';

            // 根据当前语言选择显示名称
            $display_name = $name_es;
            if ($current_lang === 'zh' && !empty($name_zh)) {
                $display_name = $name_zh;
            } elseif ($current_lang === 'en' && !empty($name_en)) {
                $display_name = $name_en;
            }

            // 获取分区价格
            $zone_prices = get_post_meta($product_id, '_ruiyi_zone_prices', true);
            if (!is_array($zone_prices)) {
                $zone_prices = array();
            }

            // 获取产品颜色
            $product_color = get_post_meta($product_id, '_ruiyi_product_color', true);
            if (empty($product_color)) {
                $product_color = '#1e293b';
            }

            // 检查是否是称重产品
            $is_scale_product = function_exists('ruiyi_is_scale_product') ? ruiyi_is_scale_product($product_id) : false;

            // 检查是否是特殊分类产品
            $is_special_category = function_exists('ruiyi_get_product_special_category_status')
                ? ruiyi_get_product_special_category_status($product_id)
                : false;

            $products_data[] = [
                'id' => $product_id,
                'name' => $display_name,
                'name_es' => $name_es,
                'name_zh' => $name_zh,
                'name_en' => $name_en,
                'price' => $product_price,
                'image' => $image_url,
                'has_real_image' => $has_real_image,
                'categories' => implode(' ', $category_ids),
                'zone_prices' => $zone_prices,
                'tax_rate' => $tax_rate,
                'product_color' => $product_color,
                'is_scale_product' => $is_scale_product,
                'is_special_category' => $is_special_category,
                'sku' => $product->get_sku()
            ];
        }
        wp_reset_postdata();
    }

    wp_send_json_success([
        'products' => $products_data,
        'pagination' => [
            'page' => $page,
            'per_page' => $per_page,
            'total' => $total,
            'total_pages' => $total_pages,
            'has_more' => $page < $total_pages
        ]
    ]);
}

