        <!-- 编辑模态框 -->
        <div id="edit-modal" style="display: none; position: fixed; top: 0; left: 0; right: 0; bottom: 0; background: rgba(0,0,0,0.6); z-index: 100000;">
            <div style="background: #fff; max-width: 500px; margin: 50px auto; padding: 20px; border-radius: 5px; max-height: 80vh; overflow-y: auto;">
                <h2 id="modal-title">编辑记录</h2>
                <input type="hidden" id="edit-id">
