                <table class="form-table">
                    <tr>
                        <th>业务日期</th>
                        <td><input type="date" id="edit-business-date" class="regular-text"></td>
                    </tr>
                    <tr>
                        <th>时段</th>
                        <td>
                            <select id="edit-period" class="regular-text">
                                <option value="午餐">午餐</option>
                                <option value="晚餐">晚餐</option>
                                <option value="全天">全天</option>
                            </select>
                        </td>
                    </tr>
                    <tr>
                        <th>结算时间</th>
                        <td><input type="datetime-local" id="edit-settlement-time" class="regular-text"></td>
                    </tr>
                    <tr>
                        <th>总金额 (€)</th>
                        <td><input type="number" step="0.01" id="edit-total" class="regular-text"></td>
                    </tr>
                    <tr>
                        <th>现金 (€)</th>
                        <td><input type="number" step="0.01" id="edit-cash" class="regular-text"></td>
                    </tr>
                    <tr>
                        <th>刷卡 (€)</th>
                        <td><input type="number" step="0.01" id="edit-card" class="regular-text"></td>
                    </tr>
                    <?php if ($bizum_enabled): ?>
                    <tr>
                        <th>转账/Bizum (€)</th>
                        <td><input type="number" step="0.01" id="edit-bizum" class="regular-text"></td>
                    </tr>
                    <?php endif; ?>
                </table>

                <p class="description" style="color: #d63638; margin-top: 15px;">
                    <span class="dashicons dashicons-warning"></span> 注意：修改将直接影响财务数据，请谨慎操作。
                </p>

                <p style="margin-top: 20px; display: flex; justify-content: space-between;">
                    <button type="button" id="btn-delete-record" class="button" style="color: #d63638;">删除此记录</button>
                    <span>
                        <button type="button" id="btn-cancel-edit" class="button">取消</button>
                        <button type="button" id="btn-save-edit" class="button button-primary">保存</button>
                    </span>
                </p>
            </div>
        </div>
    </div>

    <script>
    jQuery(document).ready(function($) {
        var ajaxurl = '<?php echo admin_url("admin-ajax.php"); ?>';
        var nonce = '<?php echo wp_create_nonce("ruiyi_pos_nonce"); ?>';
        var bizumEnabled = <?php echo $bizum_enabled ? 'true' : 'false'; ?>;

        // 选项卡切换
        $('.nav-tab').on('click', function(e) {
            e.preventDefault();
            var tab = $(this).data('tab');
            $('.nav-tab').removeClass('nav-tab-active');
            $(this).addClass('nav-tab-active');
            $('.tab-content').hide();
            $('#tab-' + tab).show();

            if (tab === 'current') {
                loadCurrentSummary();
            }
        });

        // 搜索月结单
        $('#btn-search-monthly').on('click', function() {
            loadMonthlyRecords();
        });

        // 搜索历史日结单
        $('#btn-search-history').on('click', function() {
            loadHistoryRecords();
        });

        // 创建新记录
        $('#btn-create-settlement').on('click', function() {
            $('#modal-title').text('创建新日结单');
            $('#edit-id').val('');
            $('#edit-type').val('create');
            $('#edit-business-date').val(new Date().toISOString().split('T')[0]);
            $('#edit-period').val('全天');
            var now = new Date();
            var localTime = new Date(now.getTime() - now.getTimezoneOffset() * 60000).toISOString();
            $('#edit-settlement-time').val(localTime.substring(0, 16));
            $('#edit-total').val('0');
            $('#edit-cash').val('0');
            $('#edit-card').val('0');
            $('#edit-bizum').val('0');
            $('#btn-delete-record').hide();
            $('#edit-modal').show();
        });

        // 加载月结单记录
        function loadMonthlyRecords() {
            $('#monthly-loading').show();
            $('#monthly-list').html('<tr><td colspan="' + (bizumEnabled ? 8 : 7) + '" style="text-align: center;">加载中...</td></tr>');

            $.post(ajaxurl, {
                action: 'ruiyi_admin_get_all_settlements',
                nonce: nonce,
                from_date: $('#monthly-from-date').val(),
                to_date: $('#monthly-to-date').val(),
                month: $('#monthly-month').val()
            }, function(response) {
                $('#monthly-loading').hide();
                if (response.success && response.data.records) {
                    renderMonthlyTable(response.data.records);
                } else {
                    $('#monthly-list').html('<tr><td colspan="' + (bizumEnabled ? 8 : 7) + '" style="text-align: center; color: #d63638;">' + (response.data?.message || '加载失败') + '</td></tr>');
                }
            }).fail(function() {
                $('#monthly-loading').hide();
                $('#monthly-list').html('<tr><td colspan="' + (bizumEnabled ? 8 : 7) + '" style="text-align: center; color: #d63638;">网络错误</td></tr>');
            });
        }

        // 渲染月结单表格
        function renderMonthlyTable(records) {
            if (records.length === 0) {
                $('#monthly-list').html('<tr><td colspan="' + (bizumEnabled ? 8 : 7) + '" style="text-align: center;">暂无数据</td></tr>');
                return;
            }

            var html = '';
            records.forEach(function(r) {
                html += '<tr>';
                html += '<td>' + (r.post_id || '-') + '</td>';
                html += '<td>' + (r.date || '-') + '</td>';
                html += '<td>' + (r.settlement_datetime || '-') + '</td>';
                html += '<td style="text-align: right; font-weight: bold;">€' + parseFloat(r.total_amount || 0).toFixed(2) + '</td>';
                html += '<td style="text-align: right;">€' + parseFloat(r.cash_amount || 0).toFixed(2) + '</td>';
                html += '<td style="text-align: right;">€' + parseFloat(r.card_amount || 0).toFixed(2) + '</td>';
                if (bizumEnabled) {
                    html += '<td style="text-align: right;">€' + parseFloat(r.bizum_amount || 0).toFixed(2) + '</td>';
                }
                html += '<td>';
                html += '<button class="button button-small btn-edit-monthly" data-id="' + r.post_id + '">编辑</button> ';
                html += '<button class="button button-small btn-delete-monthly" data-id="' + r.post_id + '" style="color: #d63638;">删除</button>';
                html += '</td>';
                html += '</tr>';
            });
            $('#monthly-list').html(html);
        }

        // 编辑月结单
        $(document).on('click', '.btn-edit-monthly', function() {
            var postId = $(this).data('id');
            $.post(ajaxurl, {
                action: 'ruiyi_admin_get_settlement_detail',
                nonce: nonce,
                post_id: postId
            }, function(response) {
                if (response.success && response.data) {
                    openEditModal(response.data, 'monthly', postId);
                } else {
                    alert('获取数据失败: ' + (response.data?.message || ''));
                }
            });
        });

        // 删除月结单
        $(document).on('click', '.btn-delete-monthly', function() {
            var postId = $(this).data('id');
            if (confirm('确定要删除此记录吗？此操作不可撤销。')) {
                deleteRecord(postId, 'monthly');
            }
        });

        // 加载历史日结单
        function loadHistoryRecords() {
            $('#history-loading').show();
            $('#history-list').html('<tr><td colspan="' + (bizumEnabled ? 9 : 8) + '" style="text-align: center;">加载中...</td></tr>');

            $.post(ajaxurl, {
                action: 'ruiyi_get_daily_settlement_history',
                nonce: nonce,
                from_date: $('#history-from-date').val(),
                to_date: $('#history-to-date').val()
            }, function(response) {
                $('#history-loading').hide();
                if (response.success && response.data && response.data.history) {
                    renderHistoryTable(response.data.history);
                } else {
                    $('#history-list').html('<tr><td colspan="' + (bizumEnabled ? 9 : 8) + '" style="text-align: center; color: #d63638;">' + (response.data?.message || '加载失败') + '</td></tr>');
                }
            }).fail(function() {
                $('#history-loading').hide();
                $('#history-list').html('<tr><td colspan="' + (bizumEnabled ? 9 : 8) + '" style="text-align: center; color: #d63638;">网络错误</td></tr>');
            });
        }

        // 渲染历史日结单表格
        function renderHistoryTable(records) {
            if (records.length === 0) {
                $('#history-list').html('<tr><td colspan="' + (bizumEnabled ? 9 : 8) + '" style="text-align: center;">暂无数据</td></tr>');
                return;
            }

            var html = '';
            records.forEach(function(r) {
                var typeLabel = r.settlement_type === 'auto' ? '<span style="color: #2271b1;">自动</span>' : '手动';
                html += '<tr>';
                html += '<td style="font-size: 11px;">' + (r.id || '-') + '</td>';
                html += '<td>' + (r.business_date || '-') + '</td>';
                html += '<td>' + (r.settlement_datetime || '-') + '</td>';
                html += '<td>' + typeLabel + '</td>';
                html += '<td style="text-align: right; font-weight: bold;">€' + parseFloat(r.total_amount || 0).toFixed(2) + '</td>';
                html += '<td style="text-align: right;">€' + parseFloat(r.cash_amount || 0).toFixed(2) + '</td>';
                html += '<td style="text-align: right;">€' + parseFloat(r.card_amount || 0).toFixed(2) + '</td>';
                if (bizumEnabled) {
                    html += '<td style="text-align: right;">€' + parseFloat(r.bizum_amount || 0).toFixed(2) + '</td>';
                }
                html += '<td>';
                html += '<button class="button button-small btn-edit-history" data-id="' + r.id + '">编辑</button> ';
                html += '<button class="button button-small btn-delete-history" data-id="' + r.id + '" style="color: #d63638;">删除</button>';
                html += '</td>';
                html += '</tr>';
            });
            $('#history-list').html(html);
        }

        // 编辑历史日结单
        $(document).on('click', '.btn-edit-history', function() {
            var settlementId = $(this).data('id');
            $.post(ajaxurl, {
                action: 'ruiyi_admin_get_settlement_detail',
                nonce: nonce,
                settlement_id: settlementId,
                type: 'history'
            }, function(response) {
                if (response.success && response.data) {
                    openEditModal(response.data, 'history', settlementId);
                } else {
                    alert('获取数据失败: ' + (response.data?.message || ''));
                }
            });
        });

        // 删除历史日结单
        $(document).on('click', '.btn-delete-history', function() {
            var settlementId = $(this).data('id');
            if (confirm('确定要删除此记录吗？此操作不可撤销。')) {
                deleteRecord(settlementId, 'history');
            }
        });

        // 全部清除历史日结单
        $('#btn-clear-all-history').on('click', function() {
            if (!confirm('⚠️ 确定要清空所有历史日结单吗？\n\n此操作将删除所有历史日结单记录及关联的月结单文章，不可撤销！')) {
                return;
            }
            if (!confirm('再次确认：真的要清空所有历史日结单吗？')) {
                return;
            }
            $.post(ajaxurl, {
                action: 'ruiyi_admin_clear_all_settlements',
                nonce: nonce
            }, function(response) {
                if (response.success) {
                    alert('✅ ' + (response.data?.message || '已清空所有历史日结单'));
                    loadHistoryRecords();
                } else {
                    alert('❌ 清空失败: ' + (response.data?.message || ''));
                }
            }).fail(function() {
                alert('❌ 网络错误');
            });
        });

        // 打开编辑模态框
        function openEditModal(data, type, id) {
            $('#modal-title').text(type === 'monthly' ? '编辑月结单记录' : '编辑历史日结单');
            $('#edit-id').val(id);
            $('#edit-type').val(type);
            $('#edit-business-date').val(data.business_date || '');
            $('#edit-period').val(data.period || '全天');

            if (data.settlement_datetime) {
                var dt = data.settlement_datetime.replace(' ', 'T');
                $('#edit-settlement-time').val(dt.substring(0, 16));
            }

            $('#edit-total').val(parseFloat(data.total_amount || 0));
            $('#edit-cash').val(parseFloat(data.cash_amount || 0));
            $('#edit-card').val(parseFloat(data.card_amount || 0));
            $('#edit-bizum').val(parseFloat(data.bizum_amount || 0));
            $('#btn-delete-record').show();
            $('#edit-modal').show();
        }

        // 取消编辑
        $('#btn-cancel-edit').on('click', function() {
            $('#edit-modal').hide();
        });

        // 保存编辑
        $('#btn-save-edit').on('click', function() {
            var type = $('#edit-type').val();
            var id = $('#edit-id').val();
            var settlementTime = $('#edit-settlement-time').val();

            if (type === 'create') {
                // 创建新记录
                $.post(ajaxurl, {
                    action: 'ruiyi_admin_create_settlement',
                    nonce: nonce,
                    business_date: $('#edit-business-date').val(),
                    period: $('#edit-period').val(),
                    settlement_datetime: settlementTime ? settlementTime.replace('T', ' ') + ':00' : '',
                    total_amount: $('#edit-total').val(),
                    cash_amount: $('#edit-cash').val(),
                    card_amount: $('#edit-card').val(),
                    bizum_amount: $('#edit-bizum').val()
                }, function(response) {
                    if (response.success) {
                        alert('创建成功');
                        $('#edit-modal').hide();
                        loadMonthlyRecords();
                    } else {
                        alert('创建失败: ' + (response.data?.message || ''));
                    }
                });
            } else {
                // 更新记录
                $.post(ajaxurl, {
                    action: 'ruiyi_admin_update_settlement',
                    nonce: nonce,
                    id: id,
                    type: type,
                    business_date: $('#edit-business-date').val(),
                    period: $('#edit-period').val(),
                    settlement_datetime: settlementTime ? settlementTime.replace('T', ' ') + ':00' : '',
                    total_amount: $('#edit-total').val(),
                    cash_amount: $('#edit-cash').val(),
                    card_amount: $('#edit-card').val(),
                    bizum_amount: $('#edit-bizum').val()
                }, function(response) {
                    if (response.success) {
                        alert('保存成功');
                        $('#edit-modal').hide();
                        if (type === 'monthly') {
                            loadMonthlyRecords();
                        } else {
                            loadHistoryRecords();
                        }
                    } else {
                        alert('保存失败: ' + (response.data?.message || ''));
                    }
                });
            }
        });

        // 从模态框删除
        $('#btn-delete-record').on('click', function() {
            var id = $('#edit-id').val();
            var type = $('#edit-type').val();
            if (confirm('确定要删除此记录吗？此操作不可撤销。')) {
                deleteRecord(id, type);
                $('#edit-modal').hide();
            }
        });

        // 删除记录
        function deleteRecord(id, type) {
            $.post(ajaxurl, {
                action: 'ruiyi_admin_delete_settlement',
                nonce: nonce,
                id: id,
                type: type
            }, function(response) {
                if (response.success) {
                    alert('删除成功');
                    if (type === 'monthly') {
                        loadMonthlyRecords();
                    } else {
                        loadHistoryRecords();
                    }
                } else {
                    alert('删除失败: ' + (response.data?.message || ''));
                }
            });
        }

        // 加载当日汇总
        function loadCurrentSummary() {
            $.post(ajaxurl, {
                action: 'ruiyi_get_daily_summary',
                nonce: nonce
            }, function(response) {
                if (response.success && response.data) {
                    $('#current-total').val(parseFloat(response.data.total_amount || 0));
                    $('#current-cash').val(parseFloat(response.data.cash_amount || 0));
                    $('#current-card').val(parseFloat(response.data.card_amount || 0));
                    $('#current-bizum').val(parseFloat(response.data.bizum_amount || 0));
                }
            });
        }

        // 刷新当日数据
        $('#btn-load-current').on('click', function() {
            loadCurrentSummary();
        });

        // 保存当日修改
        $('#btn-save-current').on('click', function() {
            $.post(ajaxurl, {
                action: 'ruiyi_admin_update_daily_summary',
                nonce: nonce,
                total_amount: $('#current-total').val(),
                cash_amount: $('#current-cash').val(),
                card_amount: $('#current-card').val(),
                bizum_amount: $('#current-bizum').val()
            }, function(response) {
                if (response.success) {
                    alert('保存成功');
                } else {
                    alert('保存失败: ' + (response.data?.message || ''));
                }
            });
        });

        // 点击模态框背景关闭
        $('#edit-modal').on('click', function(e) {
            if (e.target === this) {
                $(this).hide();
            }
        });
    });
    </script>

    <style>
    .tab-content { background: #fff; padding: 20px; border: 1px solid #c3c4c7; border-top: none; }
    .wp-list-table th, .wp-list-table td { padding: 10px; }
    .form-table th { width: 120px; }
    #edit-modal .form-table { margin-top: 0; }
    #edit-modal .form-table th { padding: 10px 0; }
    #edit-modal .form-table td { padding: 5px 0; }
    </style>
    <?php
}

/**
 * 🍽️ 自助餐辅助函数：判断产品是否为自助餐产品
 */
function ruiyi_is_buffet_product($product_id) {
    if (get_option('pos_buffet_enabled', '0') !== '1') return false;

    $buffet_products = json_decode(get_option('pos_buffet_products', '[]'), true);
    if (is_array($buffet_products) && in_array(intval($product_id), $buffet_products)) return true;

    $buffet_categories = json_decode(get_option('pos_buffet_categories', '[]'), true);
    if (!is_array($buffet_categories) || empty($buffet_categories)) return false;

    $terms = get_the_terms($product_id, 'product_cat');
    if ($terms && !is_wp_error($terms)) {
        foreach ($terms as $term) {
            if (in_array($term->term_id, $buffet_categories)) return true;
        }
    }
    return false;
}

/* 🔥 AJAX端点：批量保存产品多语言名称 */
add_action('wp_ajax_ruiyi_save_product_names', 'ruiyi_save_product_names');
function ruiyi_save_product_names() {
    if (!isset($_POST['nonce']) || !wp_verify_nonce($_POST['nonce'], 'ruiyi_pos_nonce')) {
        wp_send_json_error(['message' => 'Error de seguridad']);
        return;
    }

    if (!current_user_can('manage_options')) {
        wp_send_json_error(['message' => 'Sin permisos']);
        return;
    }

    $products_json = isset($_POST['products']) ? stripslashes($_POST['products']) : '[]';
    $products = json_decode($products_json, true);

    if (!is_array($products) || empty($products)) {
        wp_send_json_error(['message' => 'No hay datos de productos']);
        return;
    }

    $updated = 0;
    foreach ($products as $item) {
        $id = intval($item['id'] ?? 0);
        if ($id <= 0) continue;

        $product = wc_get_product($id);
        if (!$product) continue;

        // 更新西语名（WooCommerce产品标题）
        if (isset($item['name_es'])) {
            $new_es = sanitize_text_field($item['name_es']);
            if ($new_es !== '' && $new_es !== $product->get_name()) {
                wp_update_post(['ID' => $id, 'post_title' => $new_es]);
            }
        }

        // 更新中文名
        if (isset($item['name_zh'])) {
            update_post_meta($id, '_product_name_zh', sanitize_text_field($item['name_zh']));
        }

        // 更新英文名
        if (isset($item['name_en'])) {
            update_post_meta($id, '_product_name_en', sanitize_text_field($item['name_en']));
        }

        $updated++;
    }

    wp_send_json_success(['updated' => $updated]);
}

/* ========== Excel 批量导出产品多语言名称 ========== */
add_action('wp_ajax_ruiyi_export_product_names_xlsx', 'ruiyi_export_product_names_xlsx');
function ruiyi_export_product_names_xlsx() {
    if (!isset($_GET['nonce']) || !wp_verify_nonce($_GET['nonce'], 'ruiyi_pos_nonce')) {
        wp_die('Security check failed');
    }
    if (!current_user_can('manage_options')) {
        wp_die('Permission denied');
    }

    if (!ruiyi_customer_ensure_xlsx_libraries(true)) {
        wp_die('Excel library not available');
    }

    $products = wc_get_products(['status' => 'publish', 'limit' => -1]);

    $data = [];
    $data[] = ['ID', 'Español (ES)', '中文 (ZH)', 'English (EN)'];

    foreach ($products as $p) {
        $pid = $p->get_id();
        $data[] = [
            $pid,
            $p->get_name(),
            get_post_meta($pid, '_product_name_zh', true) ?: '',
            get_post_meta($pid, '_product_name_en', true) ?: '',
        ];
    }

    SimpleXLSXGen::fromArray($data)->downloadAs('product_names_' . date('Ymd') . '.xlsx');
    exit;
}

/* ========== Excel 批量导入产品多语言名称 ========== */
add_action('wp_ajax_ruiyi_import_product_names_xlsx', 'ruiyi_import_product_names_xlsx');
function ruiyi_import_product_names_xlsx() {
    if (!isset($_POST['nonce']) || !wp_verify_nonce($_POST['nonce'], 'ruiyi_pos_nonce')) {
        wp_send_json_error(['message' => 'Security check failed']);
        return;
    }
    if (!current_user_can('manage_options')) {
        wp_send_json_error(['message' => 'Permission denied']);
        return;
    }

    if (empty($_FILES['file']) || $_FILES['file']['error'] !== UPLOAD_ERR_OK) {
        wp_send_json_error(['message' => ruiyi_translate('No se recibió el archivo', 'No file received', '未收到文件')]);
        return;
    }

    $file_path = $_FILES['file']['tmp_name'];
    $file_name = $_FILES['file']['name'];
    $ext = strtolower(pathinfo($file_name, PATHINFO_EXTENSION));

    $rows = [];

    if ($ext === 'xlsx') {
        if (!ruiyi_customer_ensure_xlsx_libraries()) {
            wp_send_json_error(['message' => 'Excel library not available']);
            return;
        }
        $xlsx = class_exists('SimpleXLSX') ? SimpleXLSX::parse($file_path) : null;
        if ($xlsx instanceof SimpleXLSX) {
            $rows = $xlsx->rows();
        } else {
            wp_send_json_error(['message' => ruiyi_translate('No se pudo leer el archivo Excel', 'Could not read Excel file', '无法读取 Excel 文件')]);
            return;
        }
    } elseif ($ext === 'csv') {
        $handle = fopen($file_path, 'r');
        if ($handle) {
            // Try to detect BOM for UTF-8
            $bom = fread($handle, 3);
            if ($bom !== "\xEF\xBB\xBF") {
                rewind($handle);
            }
            while (($line = fgetcsv($handle)) !== false) {
                $rows[] = $line;
            }
            fclose($handle);
        }
    } else {
        wp_send_json_error(['message' => ruiyi_translate('Formato no soportado', 'Unsupported format', '不支持的格式')]);
        return;
    }

    if (count($rows) < 2) {
        wp_send_json_error(['message' => ruiyi_translate('El archivo está vacío o solo tiene encabezado', 'File is empty or header only', '文件为空或仅有表头')]);
        return;
    }

    // 跳过表头
    array_shift($rows);

    $updated = 0;
    $skipped = 0;
    $updated_products = [];

    foreach ($rows as $row) {
        $product_id = isset($row[0]) ? intval($row[0]) : 0;
        if ($product_id <= 0) {
            $skipped++;
            continue;
        }

        $product = wc_get_product($product_id);
        if (!$product) {
            $skipped++;
            continue;
        }

        $name_es = isset($row[1]) ? trim($row[1]) : '';
        $name_zh = isset($row[2]) ? trim($row[2]) : '';
        $name_en = isset($row[3]) ? trim($row[3]) : '';

        // 非空才更新，空值保留原有数据
        if ($name_es !== '') {
            $sanitized_es = sanitize_text_field($name_es);
            if ($sanitized_es !== $product->get_name()) {
                wp_update_post(['ID' => $product_id, 'post_title' => $sanitized_es]);
            }
        }

        if ($name_zh !== '') {
            update_post_meta($product_id, '_product_name_zh', sanitize_text_field($name_zh));
        }

        if ($name_en !== '') {
            update_post_meta($product_id, '_product_name_en', sanitize_text_field($name_en));
        }

        // 重新获取最新数据
        $product = wc_get_product($product_id);
        $updated_products[] = [
            'id'      => $product_id,
            'name_es' => $product->get_name(),
            'name_zh' => get_post_meta($product_id, '_product_name_zh', true) ?: '',
            'name_en' => get_post_meta($product_id, '_product_name_en', true) ?: '',
        ];

        $updated++;
    }

    wp_send_json_success([
        'updated'  => $updated,
        'skipped'  => $skipped,
        'products' => $updated_products,
    ]);
}

