// ==================== Suplementos / 配料管理 AJAX Handlers ====================

/**
 * Get all supplements (products in 'suplementos' category)
 */
add_action('wp_ajax_ruiyi_pos_get_supplements', 'ruiyi_pos_get_supplements_handler');
function ruiyi_pos_get_supplements_handler() {
    if (!check_ajax_referer('ruiyi_pos_nonce', 'nonce', false)) {
        wp_send_json_error(['message' => ruiyi_translate('Error de seguridad', 'Security error', '安全错误')]);
        return;
    }

    $category = get_term_by('slug', 'suplementos', 'product_cat');
    if (!$category) {
        wp_send_json_success(['supplements' => []]);
        return;
    }

    $products = wc_get_products([
        'category' => ['suplementos'],
        'limit'    => -1,
        'status'   => 'publish',
        'orderby'  => 'title',
        'order'    => 'ASC',
    ]);

    $supplements = [];
    foreach ($products as $p) {
        if ($p->get_price() > 0) {
            $supplements[] = [
                'id'    => $p->get_id(),
                'name'  => $p->get_name(),
                'price' => floatval($p->get_price()),
            ];
        }
    }

    wp_send_json_success(['supplements' => $supplements]);
}

/**
 * Create a supplement (WC product in 'suplementos' category)
 */
add_action('wp_ajax_ruiyi_pos_create_supplement', 'ruiyi_pos_create_supplement_handler');
function ruiyi_pos_create_supplement_handler() {
    if (!check_ajax_referer('ruiyi_pos_nonce', 'nonce', false)) {
        wp_send_json_error(['message' => ruiyi_translate('Error de seguridad', 'Security error', '安全错误')]);
        return;
    }
    if (!current_user_can('edit_products')) {
        wp_send_json_error(['message' => ruiyi_translate('Permiso denegado', 'Permission denied', '权限不足')]);
        return;
    }

    $name  = isset($_POST['name']) ? sanitize_text_field($_POST['name']) : '';
    $price = isset($_POST['price']) ? floatval($_POST['price']) : 0;

    if (empty($name)) {
        wp_send_json_error(['message' => ruiyi_translate('El nombre es requerido', 'Name is required', '名称不能为空')]);
        return;
    }
    if ($price <= 0) {
        wp_send_json_error(['message' => ruiyi_translate('El precio debe ser mayor que 0', 'Price must be greater than 0', '价格必须大于0')]);
        return;
    }

    // Ensure 'suplementos' category exists
    $category = get_term_by('slug', 'suplementos', 'product_cat');
    if (!$category) {
        $result = wp_insert_term('Suplementos', 'product_cat', ['slug' => 'suplementos']);
        if (is_wp_error($result)) {
            wp_send_json_error(['message' => $result->get_error_message()]);
            return;
        }
        $cat_id = $result['term_id'];
    } else {
        $cat_id = $category->term_id;
    }

    try {
        $product = new WC_Product_Simple();
        $product->set_name($name);
        $product->set_regular_price($price);
        $product->set_price($price);
        $product->set_status('publish');
        $product->set_catalog_visibility('hidden');
        $product_id = $product->save();

        wp_set_object_terms($product_id, [$cat_id], 'product_cat');

        wp_send_json_success([
            'message'    => ruiyi_translate('Ingrediente creado', 'Supplement created', '配料已创建'),
            'supplement' => [
                'id'    => $product_id,
                'name'  => $name,
                'price' => $price,
            ],
        ]);
    } catch (Exception $e) {
        wp_send_json_error(['message' => $e->getMessage()]);
    }
}

/**
 * Update a supplement's name and/or price
 */
add_action('wp_ajax_ruiyi_pos_update_supplement', 'ruiyi_pos_update_supplement_handler');
function ruiyi_pos_update_supplement_handler() {
    if (!check_ajax_referer('ruiyi_pos_nonce', 'nonce', false)) {
        wp_send_json_error(['message' => ruiyi_translate('Error de seguridad', 'Security error', '安全错误')]);
        return;
    }
    if (!current_user_can('edit_products')) {
        wp_send_json_error(['message' => ruiyi_translate('Permiso denegado', 'Permission denied', '权限不足')]);
        return;
    }

    $product_id = isset($_POST['product_id']) ? absint($_POST['product_id']) : 0;
    $name       = isset($_POST['name']) ? sanitize_text_field($_POST['name']) : '';
    $price      = isset($_POST['price']) ? floatval($_POST['price']) : 0;

    if (!$product_id) {
        wp_send_json_error(['message' => 'Invalid product ID']);
        return;
    }

    $product = wc_get_product($product_id);
    if (!$product) {
        wp_send_json_error(['message' => ruiyi_translate('Producto no encontrado', 'Product not found', '产品不存在')]);
        return;
    }

    if (!empty($name)) {
        $product->set_name($name);
    }
    if ($price > 0) {
        $product->set_regular_price($price);
        $product->set_price($price);
    }
    $product->save();

    wp_send_json_success([
        'message'    => ruiyi_translate('Ingrediente actualizado', 'Supplement updated', '配料已更新'),
        'supplement' => [
            'id'    => $product_id,
            'name'  => $product->get_name(),
            'price' => floatval($product->get_price()),
        ],
    ]);
}

/**
 * Delete a supplement (trash the WC product)
 */
add_action('wp_ajax_ruiyi_pos_delete_supplement', 'ruiyi_pos_delete_supplement_handler');
function ruiyi_pos_delete_supplement_handler() {
    if (!check_ajax_referer('ruiyi_pos_nonce', 'nonce', false)) {
        wp_send_json_error(['message' => ruiyi_translate('Error de seguridad', 'Security error', '安全错误')]);
        return;
    }
    if (!current_user_can('delete_products')) {
        wp_send_json_error(['message' => ruiyi_translate('Permiso denegado', 'Permission denied', '权限不足')]);
        return;
    }

    $product_id = isset($_POST['product_id']) ? absint($_POST['product_id']) : 0;
    if (!$product_id) {
        wp_send_json_error(['message' => 'Invalid product ID']);
        return;
    }

    $product = wc_get_product($product_id);
    if (!$product) {
        wp_send_json_error(['message' => ruiyi_translate('Producto no encontrado', 'Product not found', '产品不存在')]);
        return;
    }

    $product->delete(true); // Force delete

    wp_send_json_success([
        'message' => ruiyi_translate('Ingrediente eliminado', 'Supplement deleted', '配料已删除'),
    ]);
}

